/// Immutable, compiler-resolved contract for one command execution. Dynamic
/// commands are never resolved by scanning the whole graph: the selected
/// source, argv, ticket scope, filesystem inputs, and dynamic result
/// requirements are captured together and compared before and after spawn.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
struct ResolvedCheckExecution {
    schema_version: String,
    profile_hash: String,
    check_id: String,
    source_kind: String,
    source_role: String,
    source_id: String,
    source_node_type: Option<String>,
    source_field: String,
    source_semantic_hash: String,
    cwd: String,
    argv: Vec<String>,
    command_hash: String,
    environment_policy_hash: String,
    environment_bindings: BTreeMap<String, String>,
    executable: ExecutableBinding,
    /// A hash-bound interpreter for an executable script. Executing the
    /// canonical script path directly would otherwise delegate interpreter
    /// selection back to a mutable shebang/PATH lookup after resolution.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    script_interpreter: Option<ScriptInterpreterBinding>,
    /// A package-manager `exec` command may otherwise delegate executable
    /// selection to Corepack (including a network download) after the command
    /// contract has been resolved. For supported repository-local tools the
    /// compiler binds the installed entrypoint and native interpreter up
    /// front, plus the exact repository snapshot and package-manager state
    /// that the read-only sandbox is allowed to observe.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    repository_tool: Option<RepositoryToolBinding>,
    sandbox_executable: Option<ExecutableBinding>,
    sandbox_profile_hash: Option<String>,
    private_temp_required: bool,
    target_bindings: BTreeMap<String, SemanticCommandBinding>,
    read_scope_bindings: BTreeMap<String, SemanticCommandBinding>,
    read_path_manifest: Vec<Value>,
    read_path_exclusions: Vec<CommandPathExclusion>,
    produced_path_roots: Vec<String>,
    argv_input_rows: Vec<Value>,
    dynamic_requirements: Value,
    result_path: Option<String>,
    gate_policy_binding: Option<GatePolicyBinding>,
    /// Present only for compiler-selected graph-set members. Keeping this
    /// optional preserves the serialized identity of every legacy command
    /// binding while making the exact parent/member/source contract part of a
    /// graph-native proof receipt.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    compiled_member_binding: Option<CompiledMemberExecutionBinding>,
    binding_hash: String,
}

