#[derive(Debug, Clone, Copy)]
enum CheckInvocation<'a> {
    Unscoped,
    Ticket(&'a Ticket),
    /// Exact graph member chosen and pinned by the compiler. This is
    /// intentionally not representable by public run-check arguments.
    CompiledMember {
        ticket: &'a Ticket,
        step: &'a Step,
        set: &'a CompiledCheckSet,
        member: &'a CompiledCheckMember,
    },
    GatePolicy {
        policy_id: &'a str,
        gate_id: &'a str,
    },
}

fn invocation_ticket(invocation: CheckInvocation<'_>) -> Option<&Ticket> {
    match invocation {
        CheckInvocation::Ticket(ticket) | CheckInvocation::CompiledMember { ticket, .. } => {
            Some(ticket)
        }
        CheckInvocation::Unscoped | CheckInvocation::GatePolicy { .. } => None,
    }
}

