#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum WorkerWaitState {
    StepCompleted,
    ExitedBeforeOutput,
    Ready,
    ReviewReady,
    FinishReady,
    Blocked,
    Paused,
    AwaitingOperator,
    OwnershipConflict,
    TimedOut,
    TicketTerminal,
    RunTerminal,
}

