/// Transport projection for a compiler-issued context pack.
///
/// The full packet remains the fail-closed default for graph authors,
/// reviewers, observers, and graph-analysis steps. Only a file-execution step
/// with no graph or gate-authoring authority may use the smaller projection.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ContextProjectionMode {
    Full,
    ProductExecution,
}

impl ContextProjectionMode {
    fn select(
        step: Option<&Step>,
        contracts: &ContextContractSelection,
        read_paths: &BTreeSet<String>,
        write_paths: &BTreeSet<String>,
        requires_graph_rework: bool,
    ) -> Self {
        let Some(step) = step else {
            return Self::Full;
        };
        let has_execution_scope = !read_paths.is_empty()
            || !write_paths.is_empty()
            || !step.compiled_check_sets.is_empty();
        if step.kind != StepKind::Review
            && step.graph_mutation == GraphMutationPolicy::Forbidden
            && contracts.gate_policy_ids.is_empty()
            && contracts.gate_policy_query_ids.is_empty()
            && !requires_graph_rework
            && has_execution_scope
        {
            Self::ProductExecution
        } else {
            Self::Full
        }
    }

    fn schema_version(self) -> &'static str {
        match self {
            Self::Full => "1.0",
            Self::ProductExecution => "1.1",
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Full => "full",
            Self::ProductExecution => "product_execution",
        }
    }

    fn compact_transport(self) -> bool {
        self == Self::ProductExecution
    }
}

