/// Non-sensitive process-local counts for the two automatic-supervisor
/// preflight paths. These counters make lock-avoidance behavior observable
/// without persisting agent identities, paths, prompts, or model content.
#[derive(Debug, Clone, Copy, Default, Serialize, Deserialize, PartialEq, Eq)]
pub struct RunSupervisionPreflightCounters {
    pub exact_live_waits: u64,
    pub full_preflights: u64,
    pub quarantine_checks: u64,
}

const MAX_SUPERVISION_PREFLIGHT_COUNTER_RUNS: usize = 2_048;
static SUPERVISION_PREFLIGHT_COUNTERS: OnceLock<
    Mutex<BTreeMap<String, RunSupervisionPreflightCounters>>,
> = OnceLock::new();

fn record_supervision_preflight_counter(
    run_id: &str,
    update: impl FnOnce(&mut RunSupervisionPreflightCounters),
) {
    let counters = SUPERVISION_PREFLIGHT_COUNTERS.get_or_init(|| Mutex::new(BTreeMap::new()));
    let mut counters = counters
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    if !counters.contains_key(run_id)
        && counters.len() >= MAX_SUPERVISION_PREFLIGHT_COUNTER_RUNS
        && let Some(oldest) = counters.keys().next().cloned()
    {
        counters.remove(&oldest);
    }
    update(counters.entry(run_id.to_owned()).or_default());
}

