type CompiledGraphSourceFieldMembers = BTreeMap<String, BTreeMap<NodeId, BTreeSet<String>>>;

fn compiled_graph_source_paths(steps: &[Step]) -> Vec<CompiledGraphSourcePath> {
    steps
        .iter()
        .flat_map(|step| {
            step.compiled_check_sets.iter().flat_map(move |set| {
                set.members.iter().flat_map(move |member| {
                    member
                        .source_paths
                        .iter()
                        .map(move |path| CompiledGraphSourcePath {
                            step_id: step.id.clone(),
                            source_node_id: member.source_node_id.clone(),
                            path: path.clone(),
                        })
                })
            })
        })
        .collect()
}

fn compiled_graph_source_field_members(
    profile: &CompiledProfile,
    steps: &[Step],
) -> Result<CompiledGraphSourceFieldMembers> {
    let mut source_fields = CompiledGraphSourceFieldMembers::new();
    for set in steps
        .iter()
        .flat_map(|step| step.compiled_check_sets.iter())
    {
        let parent = profile.checks.get(&set.parent_check_id).ok_or_else(|| {
            KoniError::Profile(format!(
                "compiled graph set references missing parent check {}",
                set.parent_check_id
            ))
        })?;
        let graph_set = parent.graph_set.as_ref().ok_or_else(|| {
            KoniError::Profile(format!(
                "compiled graph set parent {} has no graph_set",
                parent.id
            ))
        })?;
        let field = source_fields
            .entry(graph_set.source_paths_field.clone())
            .or_default();
        for member in &set.members {
            field
                .entry(member.source_node_id.clone())
                .or_default()
                .insert(set.parent_check_id.clone());
        }
    }
    Ok(source_fields)
}

fn projected_node_path_values(node: &Node, field: &str, label: &str) -> Result<Vec<String>> {
    let Some(value) = node.field_owned(field) else {
        return Ok(Vec::new());
    };
    let values = match value {
        Value::String(path) => vec![path],
        Value::Array(items) => items
            .into_iter()
            .map(|item| {
                item.as_str().map(str::to_owned).ok_or_else(|| {
                    KoniError::Graph(format!(
                        "{label} projection {}.{field} must contain only path strings",
                        node.id
                    ))
                })
            })
            .collect::<Result<Vec<_>>>()?,
        _ => {
            return Err(KoniError::Graph(format!(
                "{label} projection {}.{field} must be a path string or list of path strings",
                node.id
            )));
        }
    };
    for value in &values {
        validate_project_relative_scope_path(Path::new(value))?;
    }
    Ok(values)
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct SelectedGraphPath {
    node_id: String,
    path: String,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Serialize)]
struct GraphPathConstraintConflict {
    left_node: String,
    left_path: String,
    right_node: String,
    right_path: String,
}

fn selected_graph_path_set(
    graph: &Graph,
    resolver: &GraphResolver<'_>,
    definition: &GraphPathSetDef,
    constraint_id: &str,
    side: &str,
) -> Result<Vec<SelectedGraphPath>> {
    let selected = resolver.select(&definition.select)?;
    let mut paths = Vec::new();
    for node_id in selected {
        let node = graph.node(&node_id).ok_or_else(|| {
            KoniError::Graph(format!(
                "graph constraint {constraint_id} {side} selector returned missing node {node_id}"
            ))
        })?;
        if !definition.node_types.contains(&node.node_type) {
            return Err(KoniError::Graph(format!(
                "graph constraint {constraint_id} {side} selector returned undeclared node type {}",
                node.node_type
            )));
        }
        for path in projected_node_path_values(
            node,
            &definition.field,
            &format!("graph constraint {constraint_id} {side}"),
        )? {
            paths.push(SelectedGraphPath {
                node_id: node.id.clone(),
                path: normalized_relative_path(&path.replace('\\', "/"))?,
            });
        }
    }
    paths.sort();
    paths.dedup();
    Ok(paths)
}

fn canonical_graph_path_conflict(
    left: &SelectedGraphPath,
    right: &SelectedGraphPath,
) -> GraphPathConstraintConflict {
    let left_identity = (&left.node_id, &left.path);
    let right_identity = (&right.node_id, &right.path);
    let (left, right) = if left_identity <= right_identity {
        (left, right)
    } else {
        (right, left)
    };
    GraphPathConstraintConflict {
        left_node: left.node_id.clone(),
        left_path: left.path.clone(),
        right_node: right.node_id.clone(),
        right_path: right.path.clone(),
    }
}

fn normalized_project_authority_path(path: &str) -> Result<PathBuf> {
    if path == "." {
        return Ok(PathBuf::from("."));
    }
    let normalized = normalized_relative_path(&path.replace('\\', "/")).map_err(|error| {
        KoniError::Profile(format!(
            "graph-selected write authority path {path:?} is ambiguous: {error}"
        ))
    })?;
    Ok(PathBuf::from(normalized))
}

fn project_authority_paths_lexically_overlap(left: &str, right: &str) -> Result<bool> {
    let left = normalized_project_authority_path(left)?;
    let right = normalized_project_authority_path(right)?;
    Ok(left == Path::new(".")
        || right == Path::new(".")
        || left.starts_with(&right)
        || right.starts_with(&left))
}

fn project_authority_paths_lexically_equal(left: &str, right: &str) -> Result<bool> {
    Ok(normalized_project_authority_path(left)? == normalized_project_authority_path(right)?)
}

fn project_authority_paths_conservatively_overlap(left: &str, right: &str) -> Result<bool> {
    let components = |path: &str| -> Result<Vec<String>> {
        let normalized = normalized_project_authority_path(path)?;
        if normalized == Path::new(".") {
            return Ok(Vec::new());
        }
        normalized
            .components()
            .filter_map(|component| match component {
                std::path::Component::Normal(component) => Some(component.to_str()),
                _ => None,
            })
            .map(|component| {
                component.map(ToOwned::to_owned).ok_or_else(|| {
                    KoniError::Action(
                        "tracked Git symlink path is not valid UTF-8 after normalization"
                            .to_owned(),
                    )
                })
            })
            .collect()
    };
    let left = components(left)?;
    let right = components(right)?;
    Ok(left.is_empty() || right.is_empty() || unresolved_component_paths_overlap(&left, &right))
}

fn normalized_tracked_symlink_target(link_path: &str, target: &[u8]) -> Result<String> {
    let target = std::str::from_utf8(target).map_err(|_| {
        KoniError::Action(format!(
            "tracked Git symlink {link_path} has a non-UTF-8 target; its authority alias cannot be proven disjoint"
        ))
    })?;
    if target.is_empty() || target.contains('\0') {
        return Err(KoniError::Action(format!(
            "tracked Git symlink {link_path} has an invalid target; its authority alias cannot be proven disjoint"
        )));
    }
    let target_path = Path::new(target);
    if target_path.is_absolute() {
        return Err(KoniError::Action(format!(
            "tracked Git symlink {link_path} has an absolute target; its authority alias cannot be proven project-contained"
        )));
    }

    let link = normalized_project_authority_path(link_path)?;
    let mut resolved = link
        .parent()
        .unwrap_or_else(|| Path::new(""))
        .components()
        .filter_map(|component| match component {
            std::path::Component::Normal(component) => Some(component.to_os_string()),
            _ => None,
        })
        .collect::<Vec<_>>();
    let mut saw_target_component = false;
    for component in target_path.components() {
        match component {
            std::path::Component::CurDir => {}
            std::path::Component::Normal(component) => {
                saw_target_component = true;
                resolved.push(component.to_os_string());
            }
            std::path::Component::ParentDir => {
                // `normal/..` cannot be collapsed safely without resolving
                // whether `normal` is itself a symlink. Only leading climbs
                // from the tracked link's parent have unambiguous lexical
                // meaning (for example `.claude/skills -> ../.agents/skills`).
                if saw_target_component {
                    return Err(KoniError::Action(format!(
                        "tracked Git symlink {link_path} has an ambiguous interior parent traversal; its authority alias cannot be proven disjoint"
                    )));
                }
                if resolved.pop().is_none() {
                    return Err(KoniError::Action(format!(
                        "tracked Git symlink {link_path} escapes the project root; its authority alias cannot be proven project-contained"
                    )));
                }
            }
            std::path::Component::RootDir | std::path::Component::Prefix(_) => {
                return Err(KoniError::Action(format!(
                    "tracked Git symlink {link_path} has an absolute target; its authority alias cannot be proven project-contained"
                )));
            }
        }
    }
    let resolved = resolved.into_iter().collect::<PathBuf>();
    if resolved.as_os_str().is_empty() {
        return Ok(".".to_owned());
    }
    resolved
        .to_str()
        .map(ToOwned::to_owned)
        .ok_or_else(|| {
            KoniError::Action(format!(
                "tracked Git symlink {link_path} resolves to a non-UTF-8 project path; its authority alias cannot be proven disjoint"
            ))
        })
}

fn ensure_tracked_symlink_target_disjoint(
    root: &Path,
    new_source_path: &str,
    link_path: &str,
    target: &[u8],
) -> Result<()> {
    // A sparse or omitted checkout may not provide a filesystem object whose
    // case/Unicode identity can be queried. Conservatively protect the pinned
    // symlink pathname itself before considering its target blob.
    if project_authority_paths_conservatively_overlap(new_source_path, link_path)? {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation new path ambiguously overlaps tracked Git symlink {link_path}"
        )));
    }
    let resolved_target = normalized_tracked_symlink_target(link_path, target)?;
    if project_authority_paths_lexically_overlap(new_source_path, &resolved_target)?
        || project_authority_paths_overlap(root, new_source_path, &resolved_target)?
    {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation new path aliases tracked Git symlink {link_path} target {resolved_target}"
        )));
    }
    Ok(())
}

#[derive(Debug)]
struct ProjectAuthorityPathIdentity {
    normalized: PathBuf,
    existing_prefixes: Vec<ProjectAuthorityPathPrefixIdentity>,
    unresolved_components: Vec<String>,
}

#[derive(Debug)]
struct ProjectAuthorityPathPrefixIdentity {
    depth: usize,
    handle: same_file::Handle,
}

fn project_authority_path_identity(
    root: &Path,
    path: &str,
) -> Result<ProjectAuthorityPathIdentity> {
    let normalized = normalized_project_authority_path(path)?;
    let normalized_text = normalized.to_str().ok_or_else(|| {
        KoniError::Profile("graph-selected write authority path is not valid UTF-8".to_owned())
    })?;
    reject_project_path_symlink_components(root, normalized_text, "project authority identity")?;

    let mut current = root.to_path_buf();
    let mut existing_prefixes = vec![ProjectAuthorityPathPrefixIdentity {
        depth: 0,
        handle: same_file::Handle::from_path(root).map_err(|error| io_error(root, error))?,
    }];
    let components = normalized
        .components()
        .filter_map(|component| match component {
            std::path::Component::Normal(component) => component.to_str().map(ToOwned::to_owned),
            std::path::Component::CurDir => None,
            _ => None,
        })
        .collect::<Vec<_>>();
    for (index, component) in components.iter().enumerate() {
        current.push(component);
        match fs::symlink_metadata(&current) {
            Ok(metadata) => {
                if metadata.file_type().is_symlink() {
                    return Err(KoniError::Action(format!(
                        "project authority identity rejects symlink component: {}",
                        current.display()
                    )));
                }
                existing_prefixes.push(ProjectAuthorityPathPrefixIdentity {
                    depth: index + 1,
                    handle: same_file::Handle::from_path(&current)
                        .map_err(|error| io_error(&current, error))?,
                });
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => break,
            Err(error) => return Err(io_error(&current, error)),
        }
    }
    let resolved_depth = existing_prefixes
        .last()
        .map(|prefix| prefix.depth)
        .unwrap_or_default();
    Ok(ProjectAuthorityPathIdentity {
        normalized,
        existing_prefixes,
        unresolved_components: components.into_iter().skip(resolved_depth).collect(),
    })
}

fn conservative_authority_component(component: &str) -> String {
    component
        .nfd()
        .flat_map(char::to_lowercase)
        .collect::<String>()
}

fn unresolved_component_paths_overlap(left: &[String], right: &[String]) -> bool {
    let left = left
        .iter()
        .map(|component| conservative_authority_component(component))
        .collect::<Vec<_>>();
    let right = right
        .iter()
        .map(|component| conservative_authority_component(component))
        .collect::<Vec<_>>();
    left.starts_with(&right) || right.starts_with(&left)
}

fn project_authority_identities_equal(
    left: &ProjectAuthorityPathIdentity,
    right: &ProjectAuthorityPathIdentity,
) -> bool {
    if left.normalized == right.normalized {
        return true;
    }
    let left_endpoint = left.existing_prefixes.last();
    let right_endpoint = right.existing_prefixes.last();
    if left.unresolved_components.is_empty()
        && right.unresolved_components.is_empty()
        && left_endpoint
            .zip(right_endpoint)
            .is_some_and(|(left, right)| left.handle == right.handle)
    {
        return true;
    }
    left_endpoint
        .zip(right_endpoint)
        .is_some_and(|(left_prefix, right_prefix)| {
            left_prefix.handle == right_prefix.handle
                && left.unresolved_components == right.unresolved_components
        })
}

fn project_authority_identities_overlap(
    left: &ProjectAuthorityPathIdentity,
    right: &ProjectAuthorityPathIdentity,
) -> bool {
    if left.normalized == Path::new(".")
        || right.normalized == Path::new(".")
        || left.normalized.starts_with(&right.normalized)
        || right.normalized.starts_with(&left.normalized)
    {
        return true;
    }
    if left.unresolved_components.is_empty()
        && left.existing_prefixes.last().is_some_and(|endpoint| {
            right
                .existing_prefixes
                .iter()
                .any(|prefix| endpoint.handle == prefix.handle)
        })
    {
        return true;
    }
    if right.unresolved_components.is_empty()
        && right.existing_prefixes.last().is_some_and(|endpoint| {
            left.existing_prefixes
                .iter()
                .any(|prefix| endpoint.handle == prefix.handle)
        })
    {
        return true;
    }
    left.existing_prefixes
        .last()
        .zip(right.existing_prefixes.last())
        .is_some_and(|(left_prefix, right_prefix)| {
            left_prefix.handle == right_prefix.handle
                && unresolved_component_paths_overlap(
                    &left.unresolved_components,
                    &right.unresolved_components,
                )
        })
}

fn project_authority_paths_overlap(root: &Path, left: &str, right: &str) -> Result<bool> {
    let left = project_authority_path_identity(root, left)?;
    let right = project_authority_path_identity(root, right)?;
    Ok(project_authority_identities_overlap(&left, &right))
}

fn project_authority_paths_equal(root: &Path, left: &str, right: &str) -> Result<bool> {
    let left = project_authority_path_identity(root, left)?;
    let right = project_authority_path_identity(root, right)?;
    Ok(project_authority_identities_equal(&left, &right))
}

fn any_project_authority_path_equal<'a>(
    root: &Path,
    paths: impl IntoIterator<Item = &'a String>,
    candidate: &str,
) -> Result<bool> {
    for path in paths {
        if project_authority_paths_equal(root, path, candidate)? {
            return Ok(true);
        }
    }
    Ok(false)
}

fn ticket_write_paths_overlap(root: &Path, left: &Ticket, right: &Ticket) -> Result<bool> {
    for left_path in &left.scope.write_paths {
        for right_path in &right.scope.write_paths {
            if project_authority_paths_overlap(root, left_path, right_path)? {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

fn scopes_write_conflict(root: &Path, left: &Scope, right: &Scope) -> Result<bool> {
    if !left.write_nodes.is_disjoint(&right.write_nodes)
        || !left.write_nodes.is_disjoint(&right.read_nodes)
        || !left.read_nodes.is_disjoint(&right.write_nodes)
    {
        return Ok(true);
    }
    for left_path in &left.write_paths {
        for right_path in right.write_paths.iter().chain(&right.read_paths) {
            if project_authority_paths_overlap(root, left_path, right_path)? {
                return Ok(true);
            }
        }
    }
    for left_path in &left.read_paths {
        for right_path in &right.write_paths {
            if project_authority_paths_overlap(root, left_path, right_path)? {
                return Ok(true);
            }
        }
    }
    Ok(false)
}

fn proof_source_write_authority_binding(
    root: &Path,
    operation: &OperationDef,
    steps: &[Step],
    authority: &ResolvedTicketWriteAuthority,
) -> Result<Option<ProofSourceWriteAuthorityBinding>> {
    let Some(check_id) = operation.proof_source_preparation_check.as_deref() else {
        return Ok(None);
    };
    let mut declared_paths = BTreeMap::<NodeId, BTreeSet<String>>::new();
    for set in steps
        .iter()
        .flat_map(|step| step.compiled_check_sets.iter())
        .filter(|set| set.parent_check_id == check_id)
    {
        for member in &set.members {
            declared_paths
                .entry(member.source_node_id.clone())
                .or_default()
                .extend(member.source_paths.iter().cloned());
        }
    }

    if let Some(grant) = authority.other_grants.first() {
        return Err(KoniError::Profile(format!(
            "{} operation {} declares proof-source preparation check {} but {} write path {} is not an exact compiler-selected source projection",
            operation.public_operation(),
            operation.id,
            check_id,
            grant.owner,
            grant.path
        )));
    }

    let mut grants = BTreeSet::new();
    for grant in &authority.source_grants {
        let mut exact_grant_bindings = BTreeSet::new();
        for source in grant
            .source_bindings
            .iter()
            .filter(|source| source.parent_check_id == check_id)
        {
            let is_exact_declared_source = any_project_authority_path_equal(
                root,
                declared_paths
                    .get(&source.source_node_id)
                    .into_iter()
                    .flatten(),
                &grant.path,
            )?;
            if is_exact_declared_source {
                exact_grant_bindings.insert(ProofSourceWriteGrantBinding {
                    source_node_id: source.source_node_id.clone(),
                    path: grant.path.clone(),
                });
            }
        }
        if exact_grant_bindings.is_empty() {
            return Err(KoniError::Profile(format!(
                "{} operation {} declares proof-source preparation check {} but {} write path {} is broad, undeclared, or belongs to a different graph-set check",
                operation.public_operation(),
                operation.id,
                check_id,
                grant.owner,
                grant.path
            )));
        }
        grants.extend(exact_grant_bindings);
    }
    if grants.is_empty() {
        return Ok(None);
    }
    let mut binding = ProofSourceWriteAuthorityBinding {
        schema_version: "1.0".to_owned(),
        operation_registry_id: operation.id.clone(),
        preparation_check_id: check_id.to_owned(),
        grants: grants.into_iter().collect(),
        binding_hash: String::new(),
    };
    binding.binding_hash = proof_source_write_authority_hash(&binding);
    Ok(Some(binding))
}

fn proof_source_write_authority_hash(binding: &ProofSourceWriteAuthorityBinding) -> String {
    let mut unhashed = binding.clone();
    unhashed.binding_hash.clear();
    normalized_hash(&unhashed)
}

fn validated_ticket_proof_source_write_authority(
    root: &Path,
    profile: &CompiledProfile,
    ticket: &Ticket,
    operation: &OperationDef,
) -> Result<Option<ProofSourceWriteAuthorityBinding>> {
    let declared_check = operation.proof_source_preparation_check.as_deref();
    if declared_check.is_some()
        && (ticket.profile_hash != profile.hash || ticket.operation != operation.public_operation())
    {
        return Err(KoniError::Action(format!(
            "ticket {} conflicts with proof-source preparation operation {}",
            ticket.id, operation.id
        )));
    }
    let Some(value) = ticket
        .extensions
        .get(PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION)
    else {
        let has_persisted_write_scope = !ticket.scope.write_paths.is_empty()
            || ticket.workflow.iter().any(|step| {
                step.write_paths
                    .as_ref()
                    .is_some_and(|paths| !paths.is_empty())
            });
        if declared_check.is_some() && has_persisted_write_scope {
            return Err(KoniError::Action(format!(
                "ticket {} for proof-source preparation operation {} has write scope without compiler proof-source authority",
                ticket.id, operation.id
            )));
        }
        return Ok(None);
    };
    let binding = serde_json::from_value::<ProofSourceWriteAuthorityBinding>(value.clone())
        .map_err(|error| {
            KoniError::Action(format!(
                "ticket {} has malformed compiler proof-source write authority: {error}",
                ticket.id
            ))
        })?;
    let declared_check = declared_check.ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} carries proof-source write authority for non-preparation operation {}",
            ticket.id, operation.id
        ))
    })?;
    if ticket.profile_hash != profile.hash
        || binding.schema_version != "1.0"
        || binding.operation_registry_id != operation.id
        || binding.preparation_check_id != declared_check
        || binding.grants.is_empty()
        || binding.binding_hash != proof_source_write_authority_hash(&binding)
        || binding.grants.windows(2).any(|pair| pair[0] >= pair[1])
    {
        return Err(KoniError::Action(format!(
            "ticket {} proof-source write authority conflicts with its compiler-owned operation, check, ordering, or hash",
            ticket.id
        )));
    }

    let mut declared_paths = BTreeMap::<NodeId, BTreeSet<String>>::new();
    for set in ticket
        .workflow
        .iter()
        .flat_map(|step| step.compiled_check_sets.iter())
        .filter(|set| set.parent_check_id == declared_check)
    {
        for member in &set.members {
            declared_paths
                .entry(member.source_node_id.clone())
                .or_default()
                .extend(member.source_paths.iter().cloned());
        }
    }
    for grant in &binding.grants {
        let exact_compiled_source = any_project_authority_path_equal(
            root,
            declared_paths
                .get(&grant.source_node_id)
                .into_iter()
                .flatten(),
            &grant.path,
        )?;
        let exact_ticket_scope =
            any_project_authority_path_equal(root, &ticket.scope.write_paths, &grant.path)?;
        if !exact_compiled_source || !exact_ticket_scope {
            return Err(KoniError::Action(format!(
                "ticket {} proof-source grant {} for {} is not an exact compiled member source in ticket write scope",
                ticket.id, grant.path, grant.source_node_id
            )));
        }
    }
    for write_path in &ticket.scope.write_paths {
        let covered = any_project_authority_path_equal(
            root,
            binding.grants.iter().map(|grant| &grant.path),
            write_path,
        )?;
        if !covered {
            return Err(KoniError::Action(format!(
                "ticket {} write path {} is outside its compiler proof-source authority",
                ticket.id, write_path
            )));
        }
    }
    for (step_id, write_path) in ticket.workflow.iter().flat_map(|step| {
        step.write_paths
            .iter()
            .flatten()
            .map(move |path| (step.id.as_str(), path))
    }) {
        let covered = any_project_authority_path_equal(
            root,
            binding.grants.iter().map(|grant| &grant.path),
            write_path,
        )?;
        if !covered {
            return Err(KoniError::Action(format!(
                "ticket {} workflow step {} write path {} is outside its compiler proof-source authority",
                ticket.id, step_id, write_path
            )));
        }
    }
    Ok(Some(binding))
}

/// Revalidate the compiler capability against the persisted ticket at the
/// instant a lease is requested. This is deliberately called before the
/// existing-lease fast path: a ticket emitted before another proof became
/// prepared, or a retry of a stale lease, cannot retain superseded authority.
fn validate_persisted_ticket_prepared_source_admission(
    root: &Path,
    profile: &CompiledProfile,
    ticket: &Ticket,
    operation: &OperationDef,
    current: &[CurrentProofPreparationBinding],
) -> Result<()> {
    let allowed = validated_ticket_proof_source_write_authority(root, profile, ticket, operation)?;
    let persisted_write_grants = ticket
        .scope
        .write_paths
        .iter()
        .map(|path| ResolvedWorkflowWriteGrant {
            owner: format!("ticket {} scope", ticket.id),
            path: path.clone(),
            source_bindings: BTreeSet::new(),
        })
        .collect::<Vec<_>>();
    if let Some(conflict) =
        prepared_source_write_conflict(root, current, &persisted_write_grants, allowed.as_ref())?
    {
        return Err(KoniError::Action(format!(
            "cannot start ticket {}: {conflict}",
            ticket.id
        )));
    }
    Ok(())
}

fn prepared_source_write_conflict(
    root: &Path,
    current: &[CurrentProofPreparationBinding],
    grants: &[ResolvedWorkflowWriteGrant],
    allowed: Option<&ProofSourceWriteAuthorityBinding>,
) -> Result<Option<String>> {
    for binding in current {
        for source_path in &binding.source_paths {
            for grant in grants {
                if !project_authority_paths_overlap(root, source_path, &grant.path)? {
                    continue;
                }
                let exact_repreparation = proof_source_repreparation_allows(
                    root,
                    binding,
                    source_path,
                    &grant.path,
                    allowed,
                )?;
                if !exact_repreparation {
                    return Ok(Some(format!(
                        "{} write path {} overlaps current prepared proof source {} for node {} from preparation ticket {}; only an exact compiler-proven re-preparation projection may write it",
                        grant.owner,
                        grant.path,
                        source_path,
                        binding.source_node_id,
                        binding.ticket_id
                    )));
                }
            }
        }
    }
    Ok(None)
}

fn proof_source_repreparation_allows(
    root: &Path,
    current: &CurrentProofPreparationBinding,
    current_source_path: &str,
    write_path: &str,
    allowed: Option<&ProofSourceWriteAuthorityBinding>,
) -> Result<bool> {
    let Some(allowed) = allowed else {
        return Ok(false);
    };
    if allowed.operation_registry_id != current.preparation_operation_id
        || allowed.preparation_check_id != current.preparation_check_id
    {
        return Ok(false);
    }
    for grant in &allowed.grants {
        if grant.source_node_id == current.source_node_id
            && project_authority_paths_equal(root, &grant.path, write_path)?
            && project_authority_paths_equal(root, &grant.path, current_source_path)?
        {
            return Ok(true);
        }
    }
    Ok(false)
}

fn validate_graph_source_write_grants(
    root: &Path,
    selected_sources: &[CompiledGraphSourcePath],
    source_grants: &[ResolvedWorkflowWriteGrant],
    other_grants: &[ResolvedWorkflowWriteGrant],
) -> Result<()> {
    if selected_sources.is_empty() {
        return Ok(());
    }

    // Normalize every relevant grant before comparing roles. A malformed path
    // must not become an apparent non-overlap merely because lexical parsing
    // failed.
    for source in selected_sources {
        normalized_project_authority_path(&source.path)?;
    }
    for grant in source_grants.iter().chain(other_grants) {
        normalized_project_authority_path(&grant.path)?;
    }

    for source in selected_sources {
        let exact_source_grant = first_overlapping_write_grant(root, &source.path, source_grants)?;
        let overlapping_other = first_overlapping_write_grant(root, &source.path, other_grants)?;

        if let Some(other) = overlapping_other {
            let detail = exact_source_grant.map_or_else(
                || "without an exact selected-member source_paths projection".to_owned(),
                |grant| {
                    format!(
                        "separately granted as proof-source writes by {}",
                        grant.owner
                    )
                },
            );
            return Err(KoniError::Profile(format!(
                "{} write path {} overlaps graph-selected proof source {} from member {} in step {} {detail}; narrow the production or proof-source authority",
                other.owner, other.path, source.path, source.source_node_id, source.step_id
            )));
        }
    }
    Ok(())
}

fn first_overlapping_write_grant<'a>(
    root: &Path,
    source_path: &str,
    grants: &'a [ResolvedWorkflowWriteGrant],
) -> Result<Option<&'a ResolvedWorkflowWriteGrant>> {
    for grant in grants {
        if project_authority_paths_overlap(root, source_path, &grant.path)? {
            return Ok(Some(grant));
        }
    }
    Ok(None)
}

fn ticket_rule_anchor_node_id(ticket: &Ticket) -> Option<&str> {
    match ticket.extensions.get("rule_anchor_node_id") {
        None => ticket.target_nodes.first().map(String::as_str),
        Some(Value::String(id)) if ticket.target_nodes.iter().any(|target| target == id) => {
            Some(id)
        }
        Some(_) => None,
    }
}

fn reject_uncompiled_operational_graph_sets(
    profile: &CompiledProfile,
    workflow: &crate::config::WorkflowDef,
    owner: &str,
) -> Result<()> {
    if let Some(step) = workflow.steps.iter().find(|step| {
        step.preserve_source_paths_from.is_some()
            || step.checks.iter().any(|check_id| {
                profile
                    .checks
                    .get(check_id)
                    .is_some_and(|check| check.kind == CheckKind::Composite)
            })
    }) {
        return Err(KoniError::Profile(format!(
            "{owner} workflow {} step {} uses graph-set checks, but compiler-owned operational tickets have no target-anchored graph compilation boundary",
            workflow.id, step.id
        )));
    }
    Ok(())
}

fn compile_graph_check_sets(
    profile: &CompiledProfile,
    store: &StateStore,
    root: &Path,
    graph: &Graph,
    context: &GraphCheckSetCompileContext<'_>,
    check_ids: &[String],
) -> Result<Vec<CompiledCheckSet>> {
    if !check_ids.iter().any(|check_id| {
        profile
            .checks
            .get(check_id)
            .is_some_and(|check| check.kind == CheckKind::Composite)
    }) {
        return Ok(Vec::new());
    }
    if let Some(target) = context
        .target_nodes
        .iter()
        .find(|target| !context.read_nodes.contains(*target))
    {
        return Err(KoniError::Action(format!(
            "graph-selected checks cannot anchor target {target} outside the step read scope"
        )));
    }
    let mut selection_graph = Graph::default();
    for node_id in context.read_nodes {
        let mut node = graph.node(node_id).cloned().ok_or_else(|| {
            KoniError::Graph(format!("step read scope references missing node {node_id}"))
        })?;
        for targets in node.edges.values_mut() {
            targets.retain(|target| context.read_nodes.contains(target));
        }
        selection_graph.insert(node)?;
    }
    let mut sets = Vec::new();
    for check_id in check_ids {
        let Some(parent) = profile.checks.get(check_id) else {
            return Err(KoniError::Profile(format!(
                "workflow references unknown check {check_id}"
            )));
        };
        if parent.kind != CheckKind::Composite {
            continue;
        }
        let graph_set = parent.graph_set.as_ref().ok_or_else(|| {
            KoniError::Profile(format!("composite check {} has no graph_set", parent.id))
        })?;
        if !check_applies_to_operation(profile, parent, context.operation) {
            return Err(KoniError::Profile(format!(
                "composite check {} does not apply to ticket operation {}",
                parent.id, context.operation
            )));
        }
        let resolver = GraphResolver::new(&selection_graph, profile, store, root);
        // A graph check set is anchored independently at every ticket target.
        // Evaluating one traversal from the whole target set can suppress a
        // reachable proof node merely because that node is also another start.
        // Unioning the validated selector result per anchor preserves ordinary
        // traversal cycle semantics while making multi-target closure stable.
        let mut selected = BTreeSet::new();
        for target in context.target_nodes {
            resolver.bind("target", vec![target.clone()]);
            selected.extend(resolver.select(&graph_set.members)?);
        }
        let mut members = Vec::new();
        for node_id in selected {
            let node = graph.node(&node_id).ok_or_else(|| {
                KoniError::Graph(format!(
                    "composite check {} selected missing member {}",
                    parent.id, node_id
                ))
            })?;
            if !graph_set.member_node_types.contains(&node.node_type)
                || (!graph_set.statuses.is_empty() && !graph_set.statuses.contains(&node.status))
                || graph_set.status_excluding.contains(&node.status)
            {
                continue;
            }
            if !context.read_nodes.contains(&node.id) {
                return Err(KoniError::Action(format!(
                    "composite check {} selected member {} outside ticket read scope",
                    parent.id, node.id
                )));
            }
            let child_check_id = match (
                graph_set.member_check.as_deref(),
                graph_set.member_check_field.as_deref(),
            ) {
                (Some(check_id), None) => check_id.to_owned(),
                (None, Some(field)) => graph_member_string(node, field, &parent.id, "child check")?,
                _ => {
                    return Err(KoniError::Profile(format!(
                        "composite check {} requires exactly one child-check source",
                        parent.id
                    )));
                }
            };
            let child = profile.checks.get(&child_check_id).ok_or_else(|| {
                KoniError::Profile(format!(
                    "composite check {} member {} references unknown child check {}",
                    parent.id, node.id, child_check_id
                ))
            })?;
            if child.kind != CheckKind::Command
                || child.effect != crate::config::ProcessEffect::ReadOnly
                || !check_applies_to_operation(profile, child, context.operation)
            {
                return Err(KoniError::Profile(format!(
                    "composite check {} member {} child {} must be a read-only command applicable to {}",
                    parent.id, node.id, child.id, context.operation
                )));
            }
            let source_paths = graph_member_paths(
                node,
                &graph_set.source_paths_field,
                &parent.id,
                "source paths",
            )?;
            let covered_paths = graph_member_paths(
                node,
                &graph_set.covered_paths_field,
                &parent.id,
                "covered paths",
            )?;
            for path in source_paths.iter().chain(&covered_paths) {
                if !path_is_covered_by_ticket_scope(path, context.read_paths) {
                    return Err(KoniError::Action(format!(
                        "composite check {} member {} path {} is outside step read authority",
                        parent.id, node.id, path
                    )));
                }
            }
            let variables = compiled_graph_member_variables(context, graph, node);
            let argv = compiled_graph_member_argv(child, node, &variables)?;
            let working_directory = if let Some(field) = &graph_set.working_directory_field {
                graph_member_string(node, field, &parent.id, "working directory")?
            } else {
                child.cwd.to_string_lossy().into_owned()
            };
            let working_directory = interpolate_command(&working_directory, &variables)?;
            let working_directory = normalize_graph_member_path(
                &working_directory,
                &parent.id,
                &node.id,
                "working directory",
            )?;
            contained_process_path(root, &working_directory)?;
            let definition = profile.node_types.get(&node.node_type).ok_or_else(|| {
                KoniError::Profile(format!(
                    "composite check {} selected node {} with unknown type {}",
                    parent.id, node.id, node.node_type
                ))
            })?;
            let mut member = CompiledCheckMember {
                source_node_id: node.id.clone(),
                source_node_type: node.node_type.clone(),
                source_semantic_hash: semantic_receipt_node_hash(
                    node,
                    &definition.semantic_fields,
                    &definition.compiler_owned_fields,
                ),
                child_check_id: child.id.clone(),
                child_check_hash: normalized_hash(child),
                argv,
                working_directory,
                source_paths,
                covered_paths,
                contract_hash: String::new(),
            };
            member.contract_hash = normalized_hash(&member);
            members.push(member);
        }
        members.sort_by(|left, right| {
            (&left.source_node_id, &left.child_check_id)
                .cmp(&(&right.source_node_id, &right.child_check_id))
        });
        if members.windows(2).any(|pair| {
            pair[0].source_node_id == pair[1].source_node_id
                && pair[0].child_check_id == pair[1].child_check_id
        }) {
            return Err(KoniError::Profile(format!(
                "composite check {} compiled duplicate source/check members",
                parent.id
            )));
        }
        if members.len() < graph_set.min_members
            || graph_set
                .max_members
                .is_some_and(|maximum| members.len() > maximum)
        {
            return Err(KoniError::Action(format!(
                "composite check {} selected {} eligible members outside cardinality {}..{}",
                parent.id,
                members.len(),
                graph_set.min_members,
                graph_set
                    .max_members
                    .map_or_else(|| "unbounded".to_owned(), |value| value.to_string())
            )));
        }
        let anchor_nodes = context.target_nodes.to_vec();
        let anchor_hashes = anchor_nodes
            .iter()
            .map(|id| {
                let node = graph.node(id).ok_or_else(|| {
                    KoniError::Graph(format!(
                        "composite check {} anchor {} is missing",
                        parent.id, id
                    ))
                })?;
                let definition = profile.node_types.get(&node.node_type).ok_or_else(|| {
                    KoniError::Profile(format!(
                        "composite check {} anchor {} has unknown type {}",
                        parent.id, id, node.node_type
                    ))
                })?;
                Ok((
                    id.clone(),
                    semantic_receipt_node_hash(
                        node,
                        &definition.semantic_fields,
                        &definition.compiler_owned_fields,
                    ),
                ))
            })
            .collect::<Result<BTreeMap<_, _>>>()?;
        let mut set = CompiledCheckSet {
            schema_version: "1.0".to_owned(),
            parent_check_id: parent.id.clone(),
            receipt_type: parent.receipt_type.clone(),
            parent_check_hash: normalized_hash(parent),
            selector_hash: normalized_hash(&graph_set.members),
            anchor_nodes,
            anchor_hashes,
            selection_hash: normalized_hash(
                &members
                    .iter()
                    .map(|member| {
                        (
                            member.source_node_id.as_str(),
                            member.child_check_id.as_str(),
                            member.contract_hash.as_str(),
                        )
                    })
                    .collect::<Vec<_>>(),
            ),
            members,
            contract_hash: String::new(),
        };
        set.contract_hash = normalized_hash(&set);
        sets.push(set);
    }
    sets.sort_by(|left, right| left.parent_check_id.cmp(&right.parent_check_id));
    Ok(sets)
}

fn compile_graph_check_sets_for_step(
    profile: &CompiledProfile,
    store: &StateStore,
    root: &Path,
    graph: &Graph,
    ticket: &Ticket,
    step: &Step,
) -> Result<Vec<CompiledCheckSet>> {
    compile_graph_check_sets(
        profile,
        store,
        root,
        graph,
        &GraphCheckSetCompileContext {
            ticket_id: &ticket.id,
            operation: &ticket.operation,
            rule_anchor_node_id: ticket_rule_anchor_node_id(ticket),
            target_nodes: &ticket.target_nodes,
            read_nodes: effective_step_read_nodes(ticket, step),
            read_paths: effective_step_read_paths(ticket, step),
        },
        &step.validation_checks,
    )
}

fn validate_compiled_source_preservation(steps: &[Step], profile: &CompiledProfile) -> Result<()> {
    for step in steps {
        let Some(source_step_id) = step.preserve_source_paths_from.as_deref() else {
            continue;
        };
        let source_step = steps
            .iter()
            .find(|candidate| candidate.id == source_step_id)
            .ok_or_else(|| {
                KoniError::Profile(format!(
                    "workflow step {} preserves sources from missing step {}",
                    step.id, source_step_id
                ))
            })?;
        if step.compiled_check_sets.len() != 1 || source_step.compiled_check_sets.len() != 1 {
            return Err(KoniError::Profile(format!(
                "workflow step {} source preservation requires exactly one compiled graph set on it and source step {}",
                step.id, source_step.id
            )));
        }
        let current = &step.compiled_check_sets[0];
        let source = &source_step.compiled_check_sets[0];
        if current.members.len() != source.members.len() {
            return Err(KoniError::Profile(format!(
                "workflow step {} and source step {} selected different member counts",
                step.id, source_step.id
            )));
        }
        for member in &current.members {
            let matches = source
                .members
                .iter()
                .filter(|candidate| candidate.source_node_id == member.source_node_id)
                .collect::<Vec<_>>();
            if matches.len() != 1 {
                return Err(KoniError::Profile(format!(
                    "workflow step {} cannot uniquely match source member {} in step {}",
                    step.id, member.source_node_id, source_step.id
                )));
            }
            let baseline = matches[0];
            let compatible = member.source_node_type == baseline.source_node_type
                && member.source_semantic_hash == baseline.source_semantic_hash
                && member.argv == baseline.argv
                && member.working_directory == baseline.working_directory
                && member.source_paths == baseline.source_paths
                && member.covered_paths == baseline.covered_paths;
            if !compatible {
                return Err(KoniError::Profile(format!(
                    "workflow step {} member {} changes the baseline source/command/path basis from step {}",
                    step.id, member.source_node_id, source_step.id
                )));
            }
            let current_check = profile
                .checks
                .get(&member.child_check_id)
                .expect("compiled member child exists");
            let source_check = profile
                .checks
                .get(&baseline.child_check_id)
                .expect("compiled member child exists");
            if graph_member_execution_policy_hash(current_check)
                != graph_member_execution_policy_hash(source_check)
            {
                return Err(KoniError::Profile(format!(
                    "workflow step {} member {} differs from baseline child {} beyond receipt/exit/freshness classification",
                    step.id, member.source_node_id, source_step.id
                )));
            }
            if source_check.receipt_freshness != crate::config::ReceiptFreshness::Historical {
                return Err(KoniError::Profile(format!(
                    "source-preservation baseline check {} must declare receipt_freshness: historical",
                    source_check.id
                )));
            }
            if current_check.receipt_freshness != crate::config::ReceiptFreshness::Current {
                return Err(KoniError::Profile(format!(
                    "source-preservation promotion check {} must declare receipt_freshness: current",
                    current_check.id
                )));
            }
        }
    }
    Ok(())
}

fn ensure_preserved_graph_member_sources(
    profile: &CompiledProfile,
    store: &StateStore,
    root: &Path,
    ticket: &Ticket,
    step: &Step,
    current_set: &CompiledCheckSet,
) -> Result<()> {
    let exclusions = command_read_path_exclusions(profile, std::iter::empty::<&str>())?;
    for member in &current_set.members {
        let Some(baseline_manifest) =
            preserved_baseline_source_path_manifest(store, ticket, step, current_set, member)?
        else {
            continue;
        };
        let current_manifest =
            project_source_path_manifest(root, &member.source_paths, &exclusions)?;
        if baseline_manifest != current_manifest {
            return Err(KoniError::Action(format!(
                "ticket {} step {} source bytes changed after baseline for member {}",
                ticket.id, step.id, member.source_node_id
            )));
        }
    }
    Ok(())
}

fn preserved_baseline_source_path_manifest(
    store: &StateStore,
    ticket: &Ticket,
    step: &Step,
    current_set: &CompiledCheckSet,
    member: &CompiledCheckMember,
) -> Result<Option<Vec<Value>>> {
    let Some(source_step_id) = step.preserve_source_paths_from.as_deref() else {
        return Ok(None);
    };
    let source_step = ticket
        .workflow
        .iter()
        .find(|candidate| candidate.id == source_step_id)
        .ok_or_else(|| {
            KoniError::Action(format!(
                "ticket {} source-preservation step {} is missing",
                ticket.id, source_step_id
            ))
        })?;
    if source_step.compiled_check_sets.len() != 1 {
        return Err(KoniError::Action(format!(
            "ticket {} source-preservation step {} has no unique compiled set",
            ticket.id, source_step.id
        )));
    }
    let source_set = &source_step.compiled_check_sets[0];
    let baseline = source_set
        .members
        .iter()
        .find(|candidate| candidate.source_node_id == member.source_node_id)
        .ok_or_else(|| {
            KoniError::Action(format!(
                "ticket {} step {} has no baseline member for source {}",
                ticket.id, step.id, member.source_node_id
            ))
        })?;
    if !current_set.members.iter().any(|candidate| {
        candidate.source_node_id == member.source_node_id
            && candidate.contract_hash == member.contract_hash
    }) {
        return Err(KoniError::Action(format!(
            "ticket {} step {} source {} is not in its current compiled set",
            ticket.id, step.id, member.source_node_id
        )));
    }
    let mut receipts = load_receipt_rows_for_ticket(store.receipts_dir(), &ticket.id)?;
    receipts.sort_by_key(receipt_sort_key);
    let latest = receipts
        .iter()
        .rfind(|receipt| {
            receipt.get("check_id").and_then(Value::as_str)
                == Some(baseline.child_check_id.as_str())
                && receipt
                    .get("execution_binding")
                    .and_then(|execution| execution.get("compiled_member_binding"))
                    .is_some_and(|binding| {
                        binding.get("step_id").and_then(Value::as_str)
                            == Some(source_step.id.as_str())
                            && binding.get("parent_check_id").and_then(Value::as_str)
                                == Some(source_set.parent_check_id.as_str())
                            && binding.get("source_node_id").and_then(Value::as_str)
                                == Some(baseline.source_node_id.as_str())
                            && binding.get("member_contract_hash").and_then(Value::as_str)
                                == Some(baseline.contract_hash.as_str())
                    })
        })
        .ok_or_else(|| {
            KoniError::Action(format!(
                "ticket {} step {} has no terminal baseline receipt for source {}",
                ticket.id, step.id, member.source_node_id
            ))
        })?;
    let recorded = latest
        .get("execution_binding")
        .cloned()
        .and_then(|value| serde_json::from_value::<ResolvedCheckExecution>(value).ok());
    let recorded_post = latest
        .get("post_execution_binding")
        .cloned()
        .and_then(|value| serde_json::from_value::<ResolvedCheckExecution>(value).ok());
    let baseline_binding = recorded
        .as_ref()
        .and_then(|execution| execution.compiled_member_binding.as_ref());
    let valid = command_receipt_integrity_current(latest)
        && latest.get("status").and_then(Value::as_str) == Some("passed")
        && latest.get("receipt_freshness").and_then(Value::as_str) == Some("historical")
        && recorded
            .as_ref()
            .is_some_and(resolved_execution_binding_integrity_current)
        && recorded_post
            .as_ref()
            .is_some_and(resolved_execution_binding_integrity_current)
        && recorded
            .as_ref()
            .zip(recorded_post.as_ref())
            .is_some_and(|(pre, post)| pre.binding_hash == post.binding_hash)
        && baseline_binding.is_some_and(|binding| {
            binding.ticket_id == ticket.id
                && binding.step_id == source_step.id
                && binding.parent_check_id == source_set.parent_check_id
                && binding.set_contract_hash == source_set.contract_hash
                && binding.member_contract_hash == baseline.contract_hash
                && binding.source_node_id == baseline.source_node_id
        });
    if !valid {
        return Err(KoniError::Action(format!(
            "ticket {} step {} baseline receipt for source {} is missing, nonpassing, or invalid",
            ticket.id, step.id, member.source_node_id
        )));
    }
    Ok(baseline_binding.map(|binding| binding.source_path_manifest.clone()))
}

fn graph_member_execution_policy_hash(check: &crate::config::CheckDef) -> String {
    normalized_hash(&json!({
        "argv": check.argv,
        "argv_from": check.argv_from,
        "command_source": check.command_source,
        "cwd": check.cwd,
        "timeout_seconds": check.timeout_seconds,
        "result_protocol": check.result_protocol,
        "result_protocol_field": check.result_protocol_field,
        "required_result_fields": check.required_result_fields,
        "result_schema": check.result_schema,
        "result_line_prefix": check.result_line_prefix,
        "result_acceptance": check.result_acceptance,
        "result_identity_field": check.result_identity_field,
        "dynamic_result": check.dynamic_result,
        "allow_nonpassing_receipt": check.allow_nonpassing_receipt,
        "argv_input_bindings": check.argv_input_bindings,
        "artifact_paths": check.artifact_paths,
        "retry_policy": check.retry_policy,
        "effect": check.effect,
        "environment": check.environment,
    }))
}

fn check_applies_to_operation(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    operation: &str,
) -> bool {
    check.applies_to.is_empty()
        || check.applies_to.iter().any(|candidate| {
            candidate == operation
                || profile
                    .operations
                    .get(candidate)
                    .is_some_and(|definition| definition.public_operation() == operation)
        })
}

fn compiled_graph_member_variables(
    context: &GraphCheckSetCompileContext<'_>,
    graph: &Graph,
    node: &Node,
) -> BTreeMap<String, String> {
    let mut variables = BTreeMap::from([
        ("ticket.id".to_owned(), context.ticket_id.to_owned()),
        (format!("{}.id", node.node_type), node.id.clone()),
    ]);
    if let Some(target) = context
        .rule_anchor_node_id
        .or_else(|| context.target_nodes.first().map(String::as_str))
    {
        variables.insert("target.id".to_owned(), target.to_owned());
        if let Some(target) = graph.node(target) {
            variables.insert(format!("{}.id", target.node_type), target.id.clone());
        }
    }
    variables
}

fn compiled_graph_member_argv(
    check: &crate::config::CheckDef,
    node: &Node,
    base_variables: &BTreeMap<String, String>,
) -> Result<Vec<String>> {
    let (raw, variables) = if let Some(source) = &check.command_source {
        if source.kind != DynamicSourceKind::Node || source.gate_policy.is_some() {
            return Err(KoniError::Profile(format!(
                "graph-set child check {} must use a non-policy node command source",
                check.id
            )));
        }
        if !source.node_types.contains(&node.node_type) {
            return Err(KoniError::Profile(format!(
                "graph-set child check {} does not authorize member type {}",
                check.id, node.node_type
            )));
        }
        let mut variables = base_variables.clone();
        variables.insert(format!("{}.id", source.role), node.id.clone());
        let value = node.as_value();
        let command = lookup_dynamic_path(&value, &source.field, &variables).ok_or_else(|| {
            KoniError::Action(format!(
                "graph-set member {} lacks check {} command field {}",
                node.id, check.id, source.field
            ))
        })?;
        (command_value_argv(check, command)?, variables)
    } else {
        if check.argv_from.is_some() {
            return Err(KoniError::Profile(format!(
                "graph-set child check {} must migrate legacy argv_from to command_source",
                check.id
            )));
        }
        if check.argv.is_empty() {
            return Err(KoniError::Profile(format!(
                "graph-set child check {} has no command",
                check.id
            )));
        }
        (check.argv.clone(), base_variables.clone())
    };
    raw.iter()
        .map(|argument| interpolate_command(argument, &variables))
        .collect()
}

fn graph_member_string(node: &Node, field: &str, check_id: &str, label: &str) -> Result<String> {
    node.field_owned(field)
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| {
            KoniError::Action(format!(
                "composite check {check_id} member {} {label} field {field} is missing or empty",
                node.id
            ))
        })
}

fn graph_member_paths(
    node: &Node,
    field: &str,
    check_id: &str,
    label: &str,
) -> Result<BTreeSet<String>> {
    let values = node
        .field_owned(field)
        .and_then(|value| value.as_array().cloned())
        .ok_or_else(|| {
            KoniError::Action(format!(
                "composite check {check_id} member {} {label} field {field} is not a path list",
                node.id
            ))
        })?;
    if values.is_empty() {
        return Err(KoniError::Action(format!(
            "composite check {check_id} member {} has empty {label}",
            node.id
        )));
    }
    values
        .into_iter()
        .map(|value| {
            let raw = value.as_str().ok_or_else(|| {
                KoniError::Action(format!(
                    "composite check {check_id} member {} {label} contains a non-string",
                    node.id
                ))
            })?;
            normalize_graph_member_path(raw, check_id, &node.id, label)
        })
        .collect()
}

fn normalize_graph_member_path(
    raw: &str,
    check_id: &str,
    node_id: &str,
    label: &str,
) -> Result<String> {
    if raw == "." {
        return Ok(".".to_owned());
    }
    normalized_relative_path(raw).map_err(|error| {
        KoniError::Action(format!(
            "composite check {check_id} member {node_id} has invalid {label} {raw:?}: {error}"
        ))
    })
}

fn path_is_within_scope(path: &Path, allowed: &Path) -> bool {
    allowed == Path::new(".") || path == allowed || path.starts_with(allowed)
}

fn path_is_compiler_state(path: &Path, state_root: &Path) -> bool {
    !path.starts_with(".codex/koni")
        && (state_root == Path::new(".") || path.starts_with(state_root))
}

fn changed_paths_between(
    repository: &git2::Repository,
    base: Oid,
    head: Oid,
) -> Result<Vec<PathBuf>> {
    let base_tree = repository.find_commit(base)?.tree()?;
    let head_tree = repository.find_commit(head)?.tree()?;
    let diff = repository.diff_tree_to_tree(Some(&base_tree), Some(&head_tree), None)?;
    let mut paths = BTreeSet::new();
    for delta in diff.deltas() {
        if let Some(path) = delta.old_file().path() {
            paths.insert(path.to_path_buf());
        }
        if let Some(path) = delta.new_file().path() {
            paths.insert(path.to_path_buf());
        }
    }
    Ok(paths.into_iter().collect())
}

fn validate_ticket_transition(
    profile: &CompiledProfile,
    from: &str,
    to: &str,
    actor: &str,
) -> Result<()> {
    let Some(machine) = profile
        .state_machines
        .get("ticket")
        .or_else(|| profile.state_machines.values().next())
    else {
        return Ok(());
    };
    if machine.transitions.iter().any(|transition| {
        (transition.actors.is_empty() || transition.actors.iter().any(|allowed| allowed == actor))
            && transition
                .from
                .iter()
                .any(|candidate| candidate == from || candidate == "*")
            && transition.to == to
    }) {
        Ok(())
    } else {
        Err(KoniError::Action(format!(
            "ticket lifecycle rejects {from} -> {to}"
        )))
    }
}

fn validate_action_params(
    action: &ActionDef,
    raw: BTreeMap<String, String>,
) -> Result<BTreeMap<String, Value>> {
    let mut output = BTreeMap::new();
    for (name, definition) in &action.params {
        let value = raw
            .get(name)
            .map(|value| parse_action_value(value, definition.value_type))
            .transpose()?
            .or_else(|| definition.default.clone());
        if definition.required && value.is_none() {
            return Err(KoniError::Action(format!(
                "action {} requires parameter {name}",
                action.id
            )));
        }
        if let Some(value) = value {
            output.insert(name.clone(), value);
        }
    }
    let unknown: Vec<_> = raw
        .keys()
        .filter(|name| !action.params.contains_key(*name))
        .cloned()
        .collect();
    if !unknown.is_empty() {
        return Err(KoniError::Action(format!(
            "action {} received unknown parameters: {}",
            action.id,
            unknown.join(", ")
        )));
    }
    Ok(output)
}

fn parse_action_value(value: &str, kind: crate::config::ParameterType) -> Result<Value> {
    use crate::config::ParameterType;
    match kind {
        ParameterType::String
        | ParameterType::Path
        | ParameterType::NodeId
        | ParameterType::TicketId => Ok(Value::String(value.to_owned())),
        ParameterType::Boolean => value
            .parse::<bool>()
            .map(Value::Bool)
            .map_err(|_| KoniError::Action(format!("expected boolean, got {value}"))),
        ParameterType::Integer => value
            .parse::<i64>()
            .map(Value::from)
            .map_err(|_| KoniError::Action(format!("expected integer, got {value}"))),
        ParameterType::Number => value
            .parse::<f64>()
            .map(Value::from)
            .map_err(|_| KoniError::Action(format!("expected number, got {value}"))),
        ParameterType::Json => serde_json::from_str(value).map_err(|source| KoniError::Json {
            path: PathBuf::from("<action parameter>"),
            source,
        }),
    }
}

fn resolve_templates(
    args: &BTreeMap<String, Value>,
    context: &BTreeMap<String, Value>,
) -> Result<BTreeMap<String, Value>> {
    args.iter()
        .map(|(key, value)| Ok((key.clone(), resolve_template_value(value, context)?)))
        .collect()
}

fn resolve_template_value(value: &Value, context: &BTreeMap<String, Value>) -> Result<Value> {
    match value {
        Value::String(text) if text.starts_with("${") && text.ends_with('}') => {
            lookup_template(context, &text[2..text.len() - 1]).cloned()
        }
        Value::String(text) => {
            let mut output = text.clone();
            while let Some(start) = output.find("${") {
                let rest = &output[start + 2..];
                let Some(end) = rest.find('}') else {
                    return Err(KoniError::Action(format!("unterminated template {text}")));
                };
                let path = &rest[..end];
                let replacement = lookup_template(context, path)?;
                let replacement = replacement
                    .as_str()
                    .map(ToOwned::to_owned)
                    .unwrap_or_else(|| replacement.to_string());
                output.replace_range(start..start + 2 + end + 1, &replacement);
            }
            Ok(Value::String(output))
        }
        Value::Array(values) => values
            .iter()
            .map(|value| resolve_template_value(value, context))
            .collect(),
        Value::Object(values) => values
            .iter()
            .map(|(key, value)| Ok((key.clone(), resolve_template_value(value, context)?)))
            .collect::<Result<Map<_, _>>>()
            .map(Value::Object),
        _ => Ok(value.clone()),
    }
}

fn lookup_template<'a>(context: &'a BTreeMap<String, Value>, path: &str) -> Result<&'a Value> {
    let mut segments = path.split('.');
    let mut value = context
        .get(segments.next().unwrap_or_default())
        .ok_or_else(|| KoniError::Action(format!("unknown template {path}")))?;
    for segment in segments {
        value = value
            .get(segment)
            .ok_or_else(|| KoniError::Action(format!("unknown template {path}")))?;
    }
    Ok(value)
}

fn string_arg<'a>(args: &'a BTreeMap<String, Value>, key: &str) -> Result<&'a str> {
    args.get(key)
        .and_then(Value::as_str)
        .ok_or_else(|| KoniError::Action(format!("primitive requires string argument {key}")))
}

#[derive(Serialize)]
struct ModelFacingApprovedPlanningStage {
    order: usize,
    title: String,
    content: String,
}

#[derive(Serialize)]
struct ModelFacingApprovedPlanningDecision {
    question: String,
    context: String,
    answer: String,
    source: String,
}

#[derive(Serialize)]
struct ModelFacingApprovedPlanningContext {
    planning_stages: Vec<ModelFacingApprovedPlanningStage>,
    resolved_decisions: Vec<ModelFacingApprovedPlanningDecision>,
    #[serde(skip_serializing_if = "Option::is_none")]
    human_revision_steering: Option<String>,
}

fn planning_text_without_absolute_paths(value: &str, project_root: &Path) -> String {
    let absolute_path = Regex::new(r#"(?m)(^|[\s\"'`(\[\{=:])(/[^\s\"'`)\]\},;]+)"#)
        .expect("absolute-path planning boundary is valid regex");
    let root = project_root.to_string_lossy();
    let root = root.trim_end_matches('/');
    absolute_path
        .replace_all(value, |captures: &regex::Captures<'_>| {
            let prefix = captures.get(1).map_or("", |capture| capture.as_str());
            let captured_path = captures.get(2).map_or("", |capture| capture.as_str());
            let path = captured_path.trim_end_matches(['.', '!', '?']);
            let suffix = &captured_path[path.len()..];
            let replacement = if !root.is_empty() && path == root {
                "the pinned checkout".to_owned()
            } else if !root.is_empty()
                && path
                    .strip_prefix(root)
                    .is_some_and(|relative| relative.starts_with('/'))
            {
                path.strip_prefix(root)
                    .expect("checked project-root prefix")
                    .trim_start_matches('/')
                    .to_owned()
            } else {
                "[absolute path omitted]".to_owned()
            };
            format!("{prefix}{replacement}{suffix}")
        })
        .into_owned()
}

fn approved_planning_context_prompt(
    context: Option<&Value>,
    project_root: &Path,
) -> Result<String> {
    let Some(context) = context else {
        return Ok(String::new());
    };
    let stages = context
        .get("stages")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            KoniError::Workflow(
                "approved planning context is missing its planning stages".to_owned(),
            )
        })?
        .iter()
        .enumerate()
        .map(|(index, stage)| {
            let title = stage
                .get("title")
                .and_then(Value::as_str)
                .filter(|title| !title.trim().is_empty())
                .ok_or_else(|| {
                    KoniError::Workflow(
                        "approved planning stage is missing its semantic title".to_owned(),
                    )
                })?;
            let content = stage
                .get("output")
                .and_then(Value::as_str)
                .filter(|output| !output.trim().is_empty())
                .ok_or_else(|| {
                    KoniError::Workflow(
                        "approved planning stage is missing its semantic content".to_owned(),
                    )
                })?;
            Ok(ModelFacingApprovedPlanningStage {
                order: index + 1,
                title: planning_text_without_absolute_paths(title, project_root),
                content: planning_text_without_absolute_paths(content, project_root),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let decisions = context
        .get("decisions")
        .and_then(Value::as_array)
        .ok_or_else(|| {
            KoniError::Workflow(
                "approved planning context is missing its resolved decisions".to_owned(),
            )
        })?
        .iter()
        .map(|decision| {
            let required = |field: &str| {
                decision
                    .get(field)
                    .and_then(Value::as_str)
                    .filter(|value| field == "context" || !value.trim().is_empty())
                    .ok_or_else(|| {
                        KoniError::Workflow(format!(
                            "approved planning decision is missing its semantic {field}"
                        ))
                    })
            };
            Ok(ModelFacingApprovedPlanningDecision {
                question: planning_text_without_absolute_paths(required("prompt")?, project_root),
                context: planning_text_without_absolute_paths(required("context")?, project_root),
                answer: planning_text_without_absolute_paths(required("answer")?, project_root),
                source: planning_text_without_absolute_paths(required("source")?, project_root),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let revision_steering = context
        .get("revision_steering")
        .filter(|value| !value.is_null())
        .map(|revision| {
            let instructions = revision
                .get("instructions")
                .and_then(Value::as_str)
                .filter(|instructions| !instructions.trim().is_empty())
                .ok_or_else(|| {
                    KoniError::Workflow(
                        "approved planning revision steering is missing its instructions"
                            .to_owned(),
                    )
                })?;
            Ok::<String, KoniError>(planning_text_without_absolute_paths(
                instructions,
                project_root,
            ))
        })
        .transpose()?;
    let model_context = ModelFacingApprovedPlanningContext {
        planning_stages: stages,
        resolved_decisions: decisions,
        human_revision_steering: revision_steering,
    };
    let context = serde_json::to_string_pretty(&model_context)
        .expect("approved planning context serialization is infallible");
    Ok(format!(
        "\n\n## Approved planning context\n\nThis bounded, compiler-materialized handoff is authoritative for the approved run. Preserve its decisions and planning constraints unless later compiler-owned graph evidence explicitly supersedes them.\n\n{context}"
    ))
}

fn render_agent_assignment_prompt(
    persona_prompt: &str,
    requested_prompt: &str,
    approved_context_prompt: &str,
    lead_slice_prompt: &str,
    scope_prompt: &str,
    worker_protocol: &str,
) -> String {
    format!(
        "{persona_prompt}\n\n## Assigned Koni task\n\n{requested_prompt}{approved_context_prompt}{lead_slice_prompt}\n\n{scope_prompt}\n\n## Compiler action protocol\n\n{worker_protocol}\n\nUse only the configured Koni actions and the current ticket lease. Record structured output and stop at the configured review boundary."
    )
}

fn worker_protocol_with_context_read_discipline(
    worker_protocol: String,
    is_worker: bool,
) -> String {
    if is_worker {
        format!("{WORKER_CONTEXT_READ_DISCIPLINE} {worker_protocol}")
    } else {
        worker_protocol
    }
}

fn string_array(value: &Value, key: &str) -> Vec<String> {
    value
        .get(key)
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(ToOwned::to_owned)
        .collect()
}

fn persist_graph_atomically(graph_root: &Path, graph: &Graph) -> Result<()> {
    let parent = graph_root.parent().ok_or_else(|| {
        KoniError::Graph(format!(
            "graph directory has no parent: {}",
            graph_root.display()
        ))
    })?;
    fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    let suffix = Uuid::now_v7();
    let name = graph_root
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("graph");
    let staging = parent.join(format!(".{name}.staging-{suffix}"));
    let backup = parent.join(format!(".{name}.backup-{suffix}"));
    fs::create_dir_all(&staging).map_err(|error| io_error(&staging, error))?;
    for node in graph.nodes() {
        graph.save_node(&staging, &node.id)?;
    }
    let had_original = graph_root.exists();
    if had_original {
        fs::rename(graph_root, &backup).map_err(|error| io_error(graph_root, error))?;
    }
    if let Err(error) = fs::rename(&staging, graph_root) {
        if had_original {
            let _ = fs::rename(&backup, graph_root);
        }
        let _ = fs::remove_dir_all(&staging);
        return Err(io_error(graph_root, error));
    }
    if had_original {
        fs::remove_dir_all(&backup).map_err(|error| io_error(&backup, error))?;
    }
    Ok(())
}

fn persist_review_effects_atomically(
    store: &StateStore,
    graph: &Graph,
    ticket: &Ticket,
) -> Result<()> {
    persist_review_effects_atomically_from_status(store, graph, ticket, &ticket.status)
}

/// Publish one review-effect graph generation and its matching ticket while
/// optionally moving the ticket between lifecycle lanes. This is rollback-on-
/// error atomic within the running process. Durable host-crash recovery for
/// the staged/backup rename sequence remains a separately documented storage
/// hardening requirement; callers must not describe this helper as power-loss
/// atomic until that transaction journal exists.
fn persist_review_effects_atomically_from_status(
    store: &StateStore,
    graph: &Graph,
    ticket: &Ticket,
    source_status: &str,
) -> Result<()> {
    let graph_root = store.graph_dir();
    let graph_parent = graph_root.parent().ok_or_else(|| {
        KoniError::Action(format!(
            "review-effect graph directory has no parent: {}",
            graph_root.display()
        ))
    })?;
    let target_ticket_path = store.ticket_path(ticket);
    let target_ticket_parent = target_ticket_path.parent().ok_or_else(|| {
        KoniError::Action(format!(
            "review-effect ticket path has no parent: {}",
            target_ticket_path.display()
        ))
    })?;
    let mut source_ticket = ticket.clone();
    source_ticket.status = source_status.to_owned();
    let source_ticket_path = store.ticket_path(&source_ticket);
    let source_ticket_parent = source_ticket_path.parent().ok_or_else(|| {
        KoniError::Action(format!(
            "review-effect source ticket path has no parent: {}",
            source_ticket_path.display()
        ))
    })?;
    fs::create_dir_all(graph_parent).map_err(|error| io_error(graph_parent, error))?;
    fs::create_dir_all(target_ticket_parent)
        .map_err(|error| io_error(target_ticket_parent, error))?;
    if !graph_root.exists() || !source_ticket_path.exists() {
        return Err(KoniError::Action(
            "review effects require existing graph and ticket state".to_owned(),
        ));
    }
    if source_ticket_path != target_ticket_path && target_ticket_path.exists() {
        return Err(KoniError::Action(format!(
            "review-effect ticket transition refuses existing target {}",
            target_ticket_path.display()
        )));
    }

    let suffix = Uuid::now_v7();
    let graph_name = graph_root
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("graph");
    let staged_graph = graph_parent.join(format!(".{graph_name}.review-staging-{suffix}"));
    let backup_graph = graph_parent.join(format!(".{graph_name}.review-backup-{suffix}"));
    let ticket_name = target_ticket_path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("ticket.yaml");
    let staged_ticket =
        target_ticket_parent.join(format!(".{ticket_name}.review-staging-{suffix}"));
    let backup_ticket = source_ticket_parent.join(format!(".{ticket_name}.review-backup-{suffix}"));

    let prepare = (|| {
        fs::create_dir_all(&staged_graph).map_err(|error| io_error(&staged_graph, error))?;
        for node in graph.nodes() {
            graph.save_node(&staged_graph, &node.id)?;
        }
        atomic_write_yaml(&staged_ticket, ticket)
    })();
    if let Err(error) = prepare {
        let _ = fs::remove_dir_all(&staged_graph);
        let _ = fs::remove_file(&staged_ticket);
        return Err(error);
    }

    if let Err(error) = fs::rename(&graph_root, &backup_graph) {
        let _ = fs::remove_dir_all(&staged_graph);
        let _ = fs::remove_file(&staged_ticket);
        return Err(io_error(&graph_root, error));
    }
    if let Err(error) = fs::rename(&source_ticket_path, &backup_ticket) {
        let graph_rollback = fs::rename(&backup_graph, &graph_root);
        let _ = fs::remove_dir_all(&staged_graph);
        let _ = fs::remove_file(&staged_ticket);
        return Err(KoniError::Action(format!(
            "could not stage review-effect ticket publication ({error}); graph rollback: {}",
            graph_rollback
                .map(|()| "ok".to_owned())
                .unwrap_or_else(|rollback| rollback.to_string())
        )));
    }
    if let Err(error) = fs::rename(&staged_graph, &graph_root) {
        let graph_rollback = fs::rename(&backup_graph, &graph_root);
        let ticket_rollback = fs::rename(&backup_ticket, &source_ticket_path);
        let _ = fs::remove_dir_all(&staged_graph);
        let _ = fs::remove_file(&staged_ticket);
        return Err(KoniError::Action(format!(
            "could not publish review-effect graph ({error}); graph rollback: {}; ticket rollback: {}",
            graph_rollback
                .map(|()| "ok".to_owned())
                .unwrap_or_else(|rollback| rollback.to_string()),
            ticket_rollback
                .map(|()| "ok".to_owned())
                .unwrap_or_else(|rollback| rollback.to_string())
        )));
    }
    if let Err(error) = fs::rename(&staged_ticket, &target_ticket_path) {
        let remove_new_graph = fs::remove_dir_all(&graph_root);
        let graph_rollback = fs::rename(&backup_graph, &graph_root);
        let ticket_rollback = fs::rename(&backup_ticket, &source_ticket_path);
        let _ = fs::remove_file(&staged_ticket);
        return Err(KoniError::Action(format!(
            "could not publish review-effect ticket ({error}); new graph cleanup: {}; graph rollback: {}; ticket rollback: {}",
            remove_new_graph
                .map(|()| "ok".to_owned())
                .unwrap_or_else(|rollback| rollback.to_string()),
            graph_rollback
                .map(|()| "ok".to_owned())
                .unwrap_or_else(|rollback| rollback.to_string()),
            ticket_rollback
                .map(|()| "ok".to_owned())
                .unwrap_or_else(|rollback| rollback.to_string())
        )));
    }
    // The two authoritative paths now contain the same compiler transaction.
    // Backup cleanup is best effort: a cleanup failure cannot make the live
    // graph and ticket disagree and recovery may remove the inert siblings.
    let _ = fs::remove_dir_all(&backup_graph);
    let _ = fs::remove_file(&backup_ticket);
    Ok(())
}

fn project_report_value(expression: &Value, row: &Value) -> Value {
    let Some(path) = expression
        .as_str()
        .and_then(|value| value.strip_prefix("$row"))
    else {
        return expression.clone();
    };
    if path.is_empty() {
        return row.clone();
    }
    let pointer = format!("/{}", path.trim_start_matches('.').replace('.', "/"));
    row.pointer(&pointer).cloned().unwrap_or(Value::Null)
}

fn command_authority_store(store: &StateStore, project_root: &Path) -> Result<StateStore> {
    let run_id = store.manifest()?.id;
    let git = GitBackend::discover(project_root)?;
    let authority_root = git.sidecar_path(format!("command-authority/{run_id}"))?;
    Ok(StateStore::new(authority_root))
}

fn acquire_command_authority_lock(
    store: &StateStore,
    project_root: &Path,
    name: &str,
) -> Result<PersistentFileLock> {
    if name.is_empty()
        || !name
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.'))
    {
        return Err(KoniError::Process(format!(
            "invalid command authority lock name: {name}"
        )));
    }
    let run_id = store.manifest()?.id;
    validate_run_barrier_id(&run_id)?;
    let git = GitBackend::discover(project_root)?;
    let relative = PathBuf::from("koni/locks/command-authority")
        .join(&run_id)
        .join(format!("{name}.lock"));
    PersistentFileLock::acquire(git.common_dir(), &relative, LockMode::Try).map_err(|error| {
        if error.kind() == std::io::ErrorKind::WouldBlock {
            KoniError::Action(format!(
                "command authority lock {name} for run {run_id} is held"
            ))
        } else {
            io_error(git.common_dir().join(relative), error)
        }
    })
}

thread_local! {
    static HELD_RUN_AUTHORITY_BARRIERS: RefCell<BTreeMap<PathBuf, (PersistentFileLock, usize)>> =
        const { RefCell::new(BTreeMap::new()) };
}

struct RunAuthorityBarrier {
    path: PathBuf,
    _not_send: std::marker::PhantomData<std::rc::Rc<()>>,
}

impl Drop for RunAuthorityBarrier {
    fn drop(&mut self) {
        HELD_RUN_AUTHORITY_BARRIERS.with(|held| {
            let mut held = held.borrow_mut();
            let Some((_, depth)) = held.get_mut(&self.path) else {
                return;
            };
            *depth -= 1;
            if *depth == 0
                && let Some((lock, _)) = held.remove(&self.path)
            {
                drop(lock);
            }
        });
        // This inode is a stable rendezvous outside the deletable run
        // authority. Never unlink it: a waiter must not lock a different inode
        // after deletion or publication releases the current one.
    }
}

fn validate_run_barrier_id(run_id: &str) -> Result<()> {
    if run_id.is_empty()
        || !run_id
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_'))
    {
        return Err(KoniError::Process(
            "run authority barrier requires an exact safe run ID".to_owned(),
        ));
    }
    Ok(())
}

fn run_authority_barrier_path(sidecar_root: &Path, run_id: &str) -> Result<PathBuf> {
    validate_run_barrier_id(run_id)?;
    let common_dir = sidecar_root.parent().ok_or_else(|| {
        KoniError::Process("compiler sidecar root has no Git common directory".to_owned())
    })?;
    if sidecar_root != common_dir.join("koni") {
        return Err(KoniError::Process(format!(
            "compiler sidecar root is not the exact Git-common namespace: {}",
            sidecar_root.display()
        )));
    }
    let canonical_common = common_dir
        .canonicalize()
        .map_err(|error| io_error(common_dir, error))?;
    if canonical_common != common_dir {
        return Err(KoniError::Process(format!(
            "Git common directory is noncanonical: {}",
            common_dir.display()
        )));
    }
    Ok(common_dir
        .join("koni/locks/run-authority")
        .join(format!("{run_id}.lock")))
}

fn acquire_run_authority_barrier_at(
    sidecar_root: &Path,
    run_id: &str,
) -> Result<RunAuthorityBarrier> {
    acquire_run_authority_barrier_at_with_timeout(
        sidecar_root,
        run_id,
        RUN_AUTHORITY_CONTROL_TIMEOUT,
    )
}

fn acquire_run_authority_barrier_at_with_timeout(
    sidecar_root: &Path,
    run_id: &str,
    timeout: Duration,
) -> Result<RunAuthorityBarrier> {
    let path = run_authority_barrier_path(sidecar_root, run_id)?;
    let common_dir = sidecar_root
        .parent()
        .expect("run_authority_barrier_path validated the common directory");
    let relative = path
        .strip_prefix(common_dir)
        .expect("run authority path is rooted in the common directory");
    if HELD_RUN_AUTHORITY_BARRIERS.with(|held| {
        let mut held = held.borrow_mut();
        if let Some((_, depth)) = held.get_mut(&path) {
            *depth += 1;
            true
        } else {
            false
        }
    }) {
        return Ok(RunAuthorityBarrier {
            path,
            _not_send: std::marker::PhantomData,
        });
    }
    let deadline = Instant::now() + timeout;
    loop {
        match PersistentFileLock::acquire(common_dir, relative, LockMode::Try) {
            Ok(lock) => {
                HELD_RUN_AUTHORITY_BARRIERS.with(|held| {
                    held.borrow_mut().insert(path.clone(), (lock, 1));
                });
                return Ok(RunAuthorityBarrier {
                    path,
                    _not_send: std::marker::PhantomData,
                });
            }
            Err(error) if error.kind() == std::io::ErrorKind::WouldBlock => {
                if Instant::now() >= deadline {
                    return Err(KoniError::Action(format!(
                        "run authority barrier for {run_id} remained busy"
                    )));
                }
                thread::sleep(Duration::from_millis(10));
            }
            Err(error) => {
                return Err(KoniError::Process(format!(
                    "run authority barrier is redirected or invalid at {}: {error}",
                    path.display()
                )));
            }
        }
    }
}

fn run_authority_barrier_remained_busy(error: &KoniError) -> bool {
    matches!(error, KoniError::Action(message) if message.starts_with("run authority barrier for ") && message.ends_with(" remained busy"))
}

fn worker_wait_authority_busy_outcome() -> WorkerWaitOutcome {
    WorkerWaitOutcome {
        state: WorkerWaitState::TimedOut,
        ticket: None,
        next: WorkerNextBoundary::Wait,
        message:
            "Another compiler boundary is still publishing worker state; wait again when ready."
                .to_owned(),
    }
}

fn acquire_run_authority_barrier(
    store: &StateStore,
    project_root: &Path,
) -> Result<(RunAuthorityBarrier, PathBuf, RunManifest)> {
    acquire_run_authority_barrier_with_timeout(store, project_root, RUN_AUTHORITY_CONTROL_TIMEOUT)
}

fn acquire_run_authority_barrier_with_timeout(
    store: &StateStore,
    project_root: &Path,
    timeout: Duration,
) -> Result<(RunAuthorityBarrier, PathBuf, RunManifest)> {
    let manifest = store.manifest()?;
    let git = GitBackend::discover(project_root)?;
    let sidecar_root = git.sidecar_root();
    let barrier =
        acquire_run_authority_barrier_at_with_timeout(&sidecar_root, &manifest.id, timeout)?;
    Ok((barrier, sidecar_root, manifest))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CompileAuthority {
    Active,
    Approval,
    PlannedProofSourceRelocation,
}

fn run_registration_status_is_live(status: &RunRegistrationStatus) -> bool {
    matches!(
        status,
        RunRegistrationStatus::Planning
            | RunRegistrationStatus::Approved
            | RunRegistrationStatus::Active
            | RunRegistrationStatus::Paused
    )
}

/// Revalidate an existing run while its stable authority barrier is held.
///
/// This is deliberately weaker than semantic-publication authority: a paused
/// run still owns processes that must be allowed to publish diagnostic exit
/// state and command receipts while they drain. Deleted, unregistered, and
/// terminal runs never qualify, so those diagnostic writers cannot recreate a
/// retired run root.
fn ensure_run_identity_live_under_barrier(
    sidecar_root: &Path,
    expected: &RunManifest,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<(RunManifest, Option<RunRegistrationStatus>)> {
    let tombstone = sidecar_root
        .join("deletions")
        .join(format!("{}.yaml", expected.id));
    if tombstone.exists() {
        return Err(KoniError::Action(format!(
            "run {} was deleted while waiting for compiler authority",
            expected.id
        )));
    }
    let current = store.manifest().map_err(|_| {
        KoniError::Action(format!(
            "run {} state disappeared while waiting for compiler authority",
            expected.id
        ))
    })?;
    if current.id != expected.id
        || current.profile_hash != profile.hash
        || current.repository_root != expected.repository_root
        || current.status == "concluded"
    {
        return Err(KoniError::Action(format!(
            "run {} no longer has live compiler identity",
            expected.id
        )));
    }
    let registry_path = sidecar_root.join("project.yaml");
    let registration_status = if registry_path.exists() {
        let registry = ProjectRegistryStore::new(
            sidecar_root.to_path_buf(),
            expected.repository_root.clone(),
        )?;
        let registration = registry.run(&expected.id).map_err(|_| {
            KoniError::Action(format!(
                "run {} was unregistered while waiting for compiler authority",
                expected.id
            ))
        })?;
        if registration.profile_hash != profile.hash
            || !run_registration_status_is_live(&registration.status)
        {
            return Err(KoniError::Action(format!(
                "run {} no longer has live registry authority",
                expected.id
            )));
        }
        Some(registration.status)
    } else {
        None
    };
    Ok((current, registration_status))
}

fn ensure_run_identity_current_under_barrier(
    sidecar_root: &Path,
    expected: &RunManifest,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<RunManifest> {
    let (current, registration_status) =
        ensure_run_identity_live_under_barrier(sidecar_root, expected, profile, store)?;
    if current.status != "active"
        || registration_status.is_some_and(|status| status != RunRegistrationStatus::Active)
    {
        return Err(KoniError::Action(format!(
            "run {} is no longer the active compiler authority",
            expected.id
        )));
    }
    Ok(current)
}

fn ensure_compile_authority_under_barrier(
    sidecar_root: &Path,
    expected: &RunManifest,
    profile: &CompiledProfile,
    store: &StateStore,
    authority: CompileAuthority,
) -> Result<RunManifest> {
    match authority {
        CompileAuthority::Active | CompileAuthority::PlannedProofSourceRelocation => {
            ensure_run_identity_current_under_barrier(sidecar_root, expected, profile, store)
        }
        CompileAuthority::Approval => {
            let (current, registration_status) =
                ensure_run_identity_live_under_barrier(sidecar_root, expected, profile, store)?;
            if current.status != "active"
                || registration_status
                    .is_some_and(|status| status != RunRegistrationStatus::Approved)
            {
                return Err(KoniError::Action(format!(
                    "run {} no longer has approval-scoped compiler authority",
                    expected.id
                )));
            }
            Ok(current)
        }
    }
}

fn durable_atomic_write_yaml(path: &Path, value: &impl Serialize) -> Result<()> {
    let parent = path.parent().ok_or_else(|| {
        KoniError::Process(format!(
            "durable authority path has no parent: {}",
            path.display()
        ))
    })?;
    fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    let bytes = serde_yaml::to_string(value)
        .map_err(|source| KoniError::Yaml {
            path: path.to_path_buf(),
            source,
        })?
        .into_bytes();
    let temp = parent.join(format!(
        ".{}.{}.tmp",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("authority"),
        Uuid::now_v7()
    ));
    let mut options = fs::OpenOptions::new();
    options.create_new(true).write(true);
    #[cfg(unix)]
    options.mode(0o600);
    let mut file = options
        .open(&temp)
        .map_err(|error| io_error(&temp, error))?;
    file.write_all(&bytes)
        .map_err(|error| io_error(&temp, error))?;
    file.sync_all().map_err(|error| io_error(&temp, error))?;
    drop(file);
    fs::rename(&temp, path).map_err(|error| io_error(path, error))?;
    fs::File::open(parent)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| io_error(parent, error))?;
    Ok(())
}

fn durable_sync_existing_path(path: &Path) -> Result<()> {
    let parent = path.parent().ok_or_else(|| {
        KoniError::Process(format!(
            "durable authority path has no parent: {}",
            path.display()
        ))
    })?;
    fs::File::open(path)
        .and_then(|file| file.sync_all())
        .map_err(|error| io_error(path, error))?;
    fs::File::open(parent)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| io_error(parent, error))?;
    Ok(())
}

fn next_command_attempt_sequence(
    store: &StateStore,
    project_root: &Path,
    cache: &mut ExecutionResolutionCache,
) -> Result<u64> {
    let authority = command_authority_store(store, project_root)?;
    let _lock = acquire_command_authority_lock(store, project_root, "command-attempt-sequence")?;
    fs::create_dir_all(authority.work_dir())
        .map_err(|error| io_error(authority.work_dir(), error))?;
    let path = authority.work_dir().join("command-attempt-sequence.yaml");
    let counter = fs::read_to_string(&path)
        .ok()
        .and_then(|text| serde_yaml::from_str::<Value>(&text).ok())
        .and_then(|value| value.get("last").and_then(Value::as_u64));
    let ledger_dir = authority.work_dir().join("command-attempts");
    fs::create_dir_all(&ledger_dir).map_err(|error| io_error(&ledger_dir, error))?;
    let ledger_floor = fs::read_dir(&ledger_dir)
        .map_err(|error| io_error(&ledger_dir, error))?
        .filter_map(|entry| entry.ok())
        .filter_map(|entry| {
            entry
                .path()
                .file_stem()
                .and_then(|stem| stem.to_str())
                .and_then(|stem| stem.parse::<u64>().ok())
        })
        .max()
        .unwrap_or(0);
    let journal_dir = authority.work_dir().join("command-journals");
    let journal_floor = if journal_dir.exists() {
        load_all_receipt_rows(&journal_dir)?
            .into_iter()
            .filter(command_attempt_journal_integrity_current)
            .filter_map(|journal| journal.get("sequence").and_then(Value::as_u64))
            .max()
            .unwrap_or(0)
    } else {
        0
    };
    let retired_dir = retired_command_attempts_dir(&authority);
    let retired_floor = if retired_dir.exists() {
        load_all_receipt_rows(&retired_dir)?
            .into_iter()
            .filter(retired_command_attempt_integrity_current)
            .filter_map(|record| record.get("sequence").and_then(Value::as_u64))
            .max()
            .unwrap_or(0)
    } else {
        0
    };
    let receipt_floor = if let Some(floor) = cache.command_sequence_floor {
        floor
    } else {
        load_all_receipt_rows(store.receipts_dir())?
            .into_iter()
            .filter_map(|row| row.get("command_attempt_sequence").and_then(Value::as_u64))
            .max()
            .unwrap_or(0)
    };
    let floor = counter
        .unwrap_or(0)
        .max(ledger_floor)
        .max(journal_floor)
        .max(retired_floor)
        .max(receipt_floor);
    let next = floor
        .checked_add(1)
        .ok_or_else(|| KoniError::Process("command attempt sequence exhausted".to_owned()))?;
    durable_atomic_write_yaml(&path, &json!({"schema_version": "1.0", "last": next}))?;
    durable_atomic_write_yaml(
        &ledger_dir.join(format!("{next:020}.yaml")),
        &json!({"schema_version": "1.0", "sequence": next}),
    )?;
    cache.command_sequence_floor = Some(next);
    Ok(next)
}

fn rehash_command_attempt_journal(journal: &mut Value) {
    let object = journal
        .as_object_mut()
        .expect("command attempt journal is an object");
    object.insert("journal_hash".to_owned(), Value::String(String::new()));
    let hash = normalized_hash(journal);
    journal
        .as_object_mut()
        .expect("command attempt journal is an object")
        .insert("journal_hash".to_owned(), Value::String(hash));
}

fn command_attempt_journal_integrity_current(journal: &Value) -> bool {
    let Some(expected) = journal.get("journal_hash").and_then(Value::as_str) else {
        return false;
    };
    let mut candidate = journal.clone();
    let Some(object) = candidate.as_object_mut() else {
        return false;
    };
    object.insert("journal_hash".to_owned(), Value::String(String::new()));
    !expected.is_empty() && normalized_hash(&candidate) == expected
}

fn rehash_retired_command_attempt(record: &mut Value) {
    record
        .as_object_mut()
        .expect("retired command attempt is an object")
        .insert("archive_hash".to_owned(), Value::String(String::new()));
    let hash = normalized_hash(record);
    record
        .as_object_mut()
        .expect("retired command attempt is an object")
        .insert("archive_hash".to_owned(), Value::String(hash));
}

fn retired_command_attempt_integrity_current(record: &Value) -> bool {
    let Some(expected) = record.get("archive_hash").and_then(Value::as_str) else {
        return false;
    };
    let mut candidate = record.clone();
    let Some(object) = candidate.as_object_mut() else {
        return false;
    };
    object.insert("archive_hash".to_owned(), Value::String(String::new()));
    !expected.is_empty() && normalized_hash(&candidate) == expected
}

fn retired_command_attempts_dir(authority: &StateStore) -> PathBuf {
    authority.work_dir().join("retired-command-attempts")
}

fn ensure_command_authority_directory(authority: &StateStore, directory: &Path) -> Result<()> {
    let parent = authority
        .root()
        .parent()
        .ok_or_else(|| KoniError::Process("command authority root has no parent".to_owned()))?;
    let parent_metadata = fs::symlink_metadata(parent).map_err(|error| io_error(parent, error))?;
    if parent_metadata.file_type().is_symlink() || !parent_metadata.is_dir() {
        return Err(KoniError::Process(format!(
            "command authority parent is redirected: {}",
            parent.display()
        )));
    }
    for candidate in [authority.root(), authority.work_dir(), directory] {
        match fs::symlink_metadata(candidate) {
            Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
                return Err(KoniError::Process(format!(
                    "command authority directory is redirected: {}",
                    candidate.display()
                )));
            }
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                fs::create_dir(candidate).map_err(|error| io_error(candidate, error))?;
            }
            Err(error) => return Err(io_error(candidate, error)),
        }
    }
    let canonical_authority = authority
        .root()
        .canonicalize()
        .map_err(|error| io_error(authority.root(), error))?;
    let canonical_directory = directory
        .canonicalize()
        .map_err(|error| io_error(directory, error))?;
    if !canonical_directory.starts_with(&canonical_authority) {
        return Err(KoniError::Process(format!(
            "command authority directory escapes its run namespace: {}",
            directory.display()
        )));
    }
    Ok(())
}

fn validate_retired_command_attempt(
    record: &Value,
    project_root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<(Value, Option<Value>)> {
    if !retired_command_attempt_integrity_current(record) {
        return Err(KoniError::Process(
            "compiler authority contains a corrupt retired command attempt".to_owned(),
        ));
    }
    let manifest = store.manifest()?;
    let current_git = GitBackend::discover(project_root)?;
    let expected_common = current_git
        .common_dir()
        .canonicalize()
        .map_err(|error| io_error(current_git.common_dir(), error))?;
    if record.get("schema_version").and_then(Value::as_str) != Some("1.0")
        || record.get("kind").and_then(Value::as_str)
            != Some("compiler.retired-read-only-command-attempt")
        || record.get("producer").and_then(Value::as_str) != Some("compiler.read-only-quarantine")
        || record.get("run_id").and_then(Value::as_str) != Some(manifest.id.as_str())
        || record.get("profile_hash").and_then(Value::as_str) != Some(profile.hash.as_str())
        || record.get("repository_root").and_then(Value::as_str)
            != Some(manifest.repository_root.to_string_lossy().as_ref())
        || record.get("git_common_dir").and_then(Value::as_str)
            != Some(expected_common.to_string_lossy().as_ref())
    {
        return Err(KoniError::Process(
            "retired command attempt does not match the current run authority".to_owned(),
        ));
    }
    let journal = record.get("journal").cloned().ok_or_else(|| {
        KoniError::Process("retired command attempt has no embedded journal".to_owned())
    })?;
    if !command_attempt_journal_integrity_current(&journal)
        || !command_attempt_journal_is_configured_read_only(profile, &manifest.id, &journal)
        || record.get("sequence").and_then(Value::as_u64)
            != journal.get("sequence").and_then(Value::as_u64)
        || record.get("journal_hash").and_then(Value::as_str)
            != journal.get("journal_hash").and_then(Value::as_str)
        || record.get("workspace_root").and_then(Value::as_str)
            != journal.get("workspace_root").and_then(Value::as_str)
        || record.get("state_root").and_then(Value::as_str)
            != journal.get("state_root").and_then(Value::as_str)
        || record.get("receipts_root").and_then(Value::as_str)
            != journal.get("receipts_root").and_then(Value::as_str)
    {
        return Err(KoniError::Process(
            "retired command attempt has invalid embedded journal authority".to_owned(),
        ));
    }
    let receipt = record
        .get("receipt")
        .filter(|value| !value.is_null())
        .cloned();
    match journal.get("status").and_then(Value::as_str) {
        Some("completed") => {
            let receipt = receipt.as_ref().ok_or_else(|| {
                KoniError::Process(
                    "completed retired command attempt has no embedded receipt".to_owned(),
                )
            })?;
            if !command_attempt_journal_matches_receipt(&journal, receipt, profile)
                || record.get("receipt_id").and_then(Value::as_str)
                    != receipt.get("id").and_then(Value::as_str)
                || record.get("receipt_hash").and_then(Value::as_str)
                    != receipt.get("receipt_hash").and_then(Value::as_str)
            {
                return Err(KoniError::Process(
                    "retired command attempt receipt is not exactly journal-bound".to_owned(),
                ));
            }
        }
        Some("recovered_no_receipt") if receipt.is_none() => {
            if !record.get("receipt_id").is_none_or(Value::is_null)
                || !record.get("receipt_hash").is_none_or(Value::is_null)
            {
                return Err(KoniError::Process(
                    "receipt-free retired command attempt contains receipt authority".to_owned(),
                ));
            }
        }
        _ => {
            return Err(KoniError::Process(
                "retired command attempt is not terminal".to_owned(),
            ));
        }
    }
    Ok((journal, receipt))
}

fn retired_command_attempt_records(
    authority: &StateStore,
    project_root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<Vec<(Value, Value, Option<Value>)>> {
    let directory = retired_command_attempts_dir(authority);
    if !directory.exists() {
        return Ok(Vec::new());
    }
    ensure_command_authority_directory(authority, &directory)?;
    load_all_receipt_rows(&directory)?
        .into_iter()
        .map(|record| {
            let (journal, receipt) =
                validate_retired_command_attempt(&record, project_root, profile, store)?;
            Ok((record, journal, receipt))
        })
        .collect()
}

/// Compact live command-attempt authority before a managed worktree or its
/// lease disappears. The archive is self-contained and integrity-bound, so
/// future currentness/quarantine checks never dereference the retired roots.
fn retire_command_attempt_authority_for_workspace(
    project_root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
    workspace: &Path,
) -> Result<()> {
    let (barrier, sidecar_root, expected) = acquire_run_authority_barrier(store, project_root)?;
    ensure_run_identity_current_under_barrier(&sidecar_root, &expected, profile, store)?;
    let authority = command_authority_store(store, project_root)?;
    let journal_directory = authority.work_dir().join("command-journals");
    if !workspace.exists() {
        if !workspace.is_absolute()
            || workspace.components().any(|component| {
                matches!(
                    component,
                    std::path::Component::CurDir | std::path::Component::ParentDir
                )
            })
        {
            return Err(KoniError::Process(
                "retired workspace lease is not an exact absolute path".to_owned(),
            ));
        }
        let archived = retired_command_attempt_records(&authority, project_root, profile, store)?
            .into_iter()
            .map(|(_, journal, _)| {
                (
                    journal
                        .get("journal_hash")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_owned(),
                    journal,
                )
            })
            .collect::<BTreeMap<_, _>>();
        let mut duplicate_live_paths = Vec::new();
        if journal_directory.exists() {
            for entry in fs::read_dir(&journal_directory)
                .map_err(|error| io_error(&journal_directory, error))?
            {
                let path = entry
                    .map_err(|error| io_error(&journal_directory, error))?
                    .path();
                if path.extension().and_then(|extension| extension.to_str()) != Some("yaml") {
                    continue;
                }
                let journal = read_optional_yaml_value(&path)?.ok_or_else(|| {
                    KoniError::Process("live command journal disappeared".to_owned())
                })?;
                if journal.get("workspace_root").and_then(Value::as_str)
                    != Some(workspace.to_string_lossy().as_ref())
                {
                    continue;
                }
                if !command_attempt_journal_integrity_current(&journal)
                    || !command_attempt_journal_is_configured_read_only(
                        profile,
                        &expected.id,
                        &journal,
                    )
                {
                    return Err(KoniError::Process(
                        "absent retired workspace has invalid live command authority".to_owned(),
                    ));
                }
                let hash = journal
                    .get("journal_hash")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                if archived.get(hash) != Some(&journal) {
                    return Err(KoniError::Process(format!(
                        "absent retired workspace {} still has unarchived command authority",
                        workspace.display()
                    )));
                }
                duplicate_live_paths.push(path);
            }
        }
        for path in duplicate_live_paths {
            fs::remove_file(&path).map_err(|error| io_error(&path, error))?;
        }
        ensure_global_read_only_quarantine_clear_under_barrier(project_root, profile, store)?;
        drop(barrier);
        return Ok(());
    }
    recover_or_block_command_attempt_journals(project_root, profile, store)?;
    ensure_global_read_only_quarantine_clear_under_barrier(project_root, profile, store)?;
    let workspace = workspace
        .canonicalize()
        .map_err(|error| io_error(workspace, error))?;
    if !journal_directory.exists() {
        drop(barrier);
        return Ok(());
    }
    let archive_directory = retired_command_attempts_dir(&authority);
    ensure_command_authority_directory(&authority, &archive_directory)?;
    let project_git = GitBackend::discover(project_root)?;
    let git_common_dir = project_git
        .common_dir()
        .canonicalize()
        .map_err(|error| io_error(project_git.common_dir(), error))?;
    let manifest = store.manifest()?;
    let mut retired_paths = Vec::new();
    for entry in
        fs::read_dir(&journal_directory).map_err(|error| io_error(&journal_directory, error))?
    {
        let path = entry
            .map_err(|error| io_error(&journal_directory, error))?
            .path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("yaml") {
            continue;
        }
        let journal = read_optional_yaml_value(&path)?.ok_or_else(|| {
            KoniError::Process(format!(
                "command attempt journal disappeared during retirement: {}",
                path.display()
            ))
        })?;
        let validated =
            validate_command_attempt_journal_authority(&journal, project_root, profile, store)?;
        if validated.workspace_root != workspace {
            continue;
        }
        let sequence = journal
            .get("sequence")
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                KoniError::Process("retiring command attempt has no sequence".to_owned())
            })?;
        let receipt = match journal.get("status").and_then(Value::as_str) {
            Some("completed") => {
                let receipts = load_all_receipt_rows(&validated.receipts_root)?;
                Some(
                    receipts
                        .into_iter()
                        .find(|receipt| {
                            command_attempt_journal_matches_receipt(&journal, receipt, profile)
                        })
                        .ok_or_else(|| {
                            KoniError::Process(format!(
                                "completed command attempt {sequence} has no exact receipt"
                            ))
                        })?,
                )
            }
            Some("recovered_no_receipt") => None,
            status => {
                return Err(KoniError::Process(format!(
                    "cannot retire workspace {} with nonterminal command attempt {sequence} ({})",
                    workspace.display(),
                    status.unwrap_or("unknown")
                )));
            }
        };
        let mut record = json!({
            "schema_version": "1.0",
            "kind": "compiler.retired-read-only-command-attempt",
            "producer": "compiler.read-only-quarantine",
            "run_id": manifest.id,
            "profile_hash": profile.hash,
            "repository_root": manifest.repository_root,
            "git_common_dir": git_common_dir,
            "sequence": sequence,
            "workspace_root": journal.get("workspace_root").cloned().unwrap_or(Value::Null),
            "state_root": journal.get("state_root").cloned().unwrap_or(Value::Null),
            "receipts_root": journal.get("receipts_root").cloned().unwrap_or(Value::Null),
            "journal_hash": journal.get("journal_hash").cloned().unwrap_or(Value::Null),
            "receipt_id": receipt.as_ref().and_then(|receipt| receipt.get("id")).cloned().unwrap_or(Value::Null),
            "receipt_hash": receipt.as_ref().and_then(|receipt| receipt.get("receipt_hash")).cloned().unwrap_or(Value::Null),
            "journal": journal,
            "receipt": receipt,
            "retired_at": Utc::now(),
            "archive_hash": "",
        });
        rehash_retired_command_attempt(&mut record);
        let archive_path = archive_directory.join(format!("{sequence:020}.yaml"));
        match fs::symlink_metadata(&archive_path) {
            Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
                return Err(KoniError::Process(format!(
                    "retired command archive path is redirected: {}",
                    archive_path.display()
                )));
            }
            Ok(_) => {
                let existing = read_optional_yaml_value(&archive_path)?.ok_or_else(|| {
                    KoniError::Process("retired command archive disappeared".to_owned())
                })?;
                let (existing_journal, existing_receipt) =
                    validate_retired_command_attempt(&existing, project_root, profile, store)?;
                if existing_journal.get("journal_hash") != record["journal"].get("journal_hash")
                    || existing_receipt
                        .as_ref()
                        .and_then(|value| value.get("receipt_hash"))
                        != record["receipt"].get("receipt_hash")
                {
                    return Err(KoniError::Process(format!(
                        "retired command archive sequence {sequence} conflicts with live authority"
                    )));
                }
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                durable_atomic_write_yaml(&archive_path, &record)?;
            }
            Err(error) => return Err(io_error(&archive_path, error)),
        }
        retired_paths.push(path);
    }
    for path in retired_paths {
        fs::remove_file(&path).map_err(|error| io_error(&path, error))?;
    }
    fs::File::open(&journal_directory)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| io_error(&journal_directory, error))?;
    drop(barrier);
    Ok(())
}

fn ensure_worktree_retirement_caller_is_safe(
    caller_root: &Path,
    _profile: &CompiledProfile,
    workspace: &Path,
) -> Result<()> {
    let caller = caller_root
        .canonicalize()
        .map_err(|error| io_error(caller_root, error))?;
    let retires_caller = workspace
        .canonicalize()
        .map_or_else(|_| caller == workspace, |workspace| caller == workspace);
    if retires_caller {
        return Err(KoniError::Action(
            "worktree retirement must run from the integration or project checkout; retiring the caller would destroy its execution and publication authority"
                .to_owned(),
        ));
    }
    Ok(())
}

fn ensure_reversible_worktree_is_clean(
    primitive: &str,
    profile: &CompiledProfile,
    workspace: &Path,
) -> Result<()> {
    if !workspace.exists() {
        return Ok(());
    }
    let git = GitBackend::discover(workspace)?;
    let changes = git.status(&tracked_state_status_exclusions(profile, git.workdir())?)?;
    if changes.is_empty() {
        return Ok(());
    }
    Err(KoniError::Action(format!(
        "{primitive} is reversible and refuses to discard uncommitted work in {}: {}",
        workspace.display(),
        changes
            .iter()
            .map(|change| change.path.display().to_string())
            .collect::<Vec<_>>()
            .join(", ")
    )))
}

fn ticket_reopen_retirement_binding_hash(record: &TicketReopenRetirement) -> String {
    normalized_hash(&(
        record.schema_version.as_str(),
        record.run_id.as_str(),
        record.profile_hash.as_str(),
        record.ticket_id.as_str(),
        record.terminal_ticket_hash.as_str(),
        record.cycle,
        record.lease_id.as_str(),
        &record.worktree,
        record.worktree_name.as_str(),
        record.branch_ref.as_str(),
        record.branch_head.as_str(),
        record.integration_ref.as_str(),
        record.integration_boundary_journal.as_str(),
        record.integration_result_hash.as_str(),
    ))
}

fn validate_ticket_reopen_retirement_binding(
    record: &TicketReopenRetirement,
    manifest: &RunManifest,
    ticket: &Ticket,
    expected_spec: &TicketWorktreeSpec,
    integration_ref: &str,
    completed: &CompletedTicketIntegration,
) -> Result<()> {
    let lease = ticket.lease.as_ref().ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} reopen retirement lost its terminal lease",
            ticket.id
        ))
    })?;
    let cycle = ticket
        .extensions
        .get("reopen_count")
        .and_then(Value::as_u64)
        .unwrap_or(0)
        + 1;
    if record.schema_version != "1.0"
        || record.run_id != manifest.id
        || record.profile_hash != ticket.profile_hash
        || record.ticket_id != ticket.id
        || record.terminal_ticket_hash != normalized_hash(ticket)
        || record.cycle != cycle
        || record.lease_id != lease.id
        || record.worktree != lease.worktree
        || record.worktree_name != expected_spec.name
        || record.branch_ref != expected_spec.branch_ref
        || record.branch_head != completed.ticket_head
        || record.integration_ref != integration_ref
        || record.integration_boundary_journal != completed.journal_id
        || record.integration_result_hash != completed.result_hash
    {
        return Err(KoniError::Action(format!(
            "ticket {} reopen retirement does not match its exact terminal cycle and integration authority",
            ticket.id
        )));
    }
    Ok(())
}

fn ensure_managed_sidecar_directory_chain(
    sidecar_root: &Path,
    directory: &Path,
    label: &str,
) -> Result<()> {
    ensure_managed_sidecar_directory_chain_inner(sidecar_root, directory, label, true)
}

fn ensure_existing_managed_sidecar_directory_chain(
    sidecar_root: &Path,
    directory: &Path,
    label: &str,
) -> Result<()> {
    ensure_managed_sidecar_directory_chain_inner(sidecar_root, directory, label, false)
}

fn ensure_managed_sidecar_directory_chain_inner(
    sidecar_root: &Path,
    directory: &Path,
    label: &str,
    create_missing: bool,
) -> Result<()> {
    let relative = directory.strip_prefix(sidecar_root).map_err(|_| {
        KoniError::Action(format!(
            "{label} directory escaped the compiler sidecar: {}",
            directory.display()
        ))
    })?;
    let sidecar_parent = sidecar_root
        .parent()
        .ok_or_else(|| KoniError::Action(format!("{label} sidecar root has no parent")))?;
    let parent_metadata =
        fs::symlink_metadata(sidecar_parent).map_err(|error| io_error(sidecar_parent, error))?;
    if parent_metadata.file_type().is_symlink() || !parent_metadata.is_dir() {
        return Err(KoniError::Action(format!(
            "{label} sidecar parent is redirected: {}",
            sidecar_parent.display()
        )));
    }
    let mut current = sidecar_root.to_path_buf();
    let mut candidates = vec![current.clone()];
    for component in relative.components() {
        let std::path::Component::Normal(component) = component else {
            return Err(KoniError::Action(format!(
                "{label} directory is not a normalized sidecar path: {}",
                directory.display()
            )));
        };
        current.push(component);
        candidates.push(current.clone());
    }
    for candidate in candidates {
        match fs::symlink_metadata(&candidate) {
            Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
                return Err(KoniError::Action(format!(
                    "{label} directory is redirected: {}",
                    candidate.display()
                )));
            }
            Ok(_) => {}
            Err(error) if create_missing && error.kind() == std::io::ErrorKind::NotFound => {
                fs::create_dir(&candidate).map_err(|error| io_error(&candidate, error))?;
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
                return Err(KoniError::Action(format!(
                    "{label} directory is missing: {}",
                    candidate.display()
                )));
            }
            Err(error) => return Err(io_error(&candidate, error)),
        }
    }
    let canonical_root = sidecar_root
        .canonicalize()
        .map_err(|error| io_error(sidecar_root, error))?;
    let canonical_directory = directory
        .canonicalize()
        .map_err(|error| io_error(directory, error))?;
    if !canonical_directory.starts_with(&canonical_root) {
        return Err(KoniError::Action(format!(
            "{label} directory escaped its canonical compiler sidecar"
        )));
    }
    Ok(())
}

fn read_ticket_reopen_retirement(path: &Path) -> Result<Option<TicketReopenRetirement>> {
    match fs::symlink_metadata(path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_file() => {
            return Err(KoniError::Action(format!(
                "ticket reopen retirement path is redirected: {}",
                path.display()
            )));
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(io_error(path, error)),
    }
    let value = read_optional_yaml_value(path)?.ok_or_else(|| {
        KoniError::Action(format!(
            "ticket reopen retirement disappeared while reading {}",
            path.display()
        ))
    })?;
    serde_json::from_value(value)
        .map(Some)
        .map_err(|source| KoniError::Json {
            path: path.to_path_buf(),
            source,
        })
}

fn write_ticket_reopen_retirement(path: &Path, record: &TicketReopenRetirement) -> Result<()> {
    if let Ok(metadata) = fs::symlink_metadata(path)
        && (metadata.file_type().is_symlink() || !metadata.is_file())
    {
        return Err(KoniError::Action(format!(
            "ticket reopen retirement path is redirected: {}",
            path.display()
        )));
    }
    let parent = path.parent().ok_or_else(|| {
        KoniError::Action("ticket reopen retirement path has no parent".to_owned())
    })?;
    let parent_metadata = fs::symlink_metadata(parent).map_err(|error| io_error(parent, error))?;
    if parent_metadata.file_type().is_symlink() || !parent_metadata.is_dir() {
        return Err(KoniError::Action(format!(
            "ticket reopen retirement directory is redirected: {}",
            parent.display()
        )));
    }
    durable_atomic_write_yaml(path, record)
}

fn prepare_command_attempt_journal(
    store: &StateStore,
    project_root: &Path,
    check: &crate::config::CheckDef,
    sequence: u64,
    execution: &ResolvedCheckExecution,
    spawn_binding: &Value,
    workspace_pre: Option<&WorkspaceFingerprint>,
) -> Result<Option<PathBuf>> {
    if check.effect != crate::config::ProcessEffect::ReadOnly {
        return Ok(None);
    }
    let authority = command_authority_store(store, project_root)?;
    let directory = authority.work_dir().join("command-journals");
    fs::create_dir_all(&directory).map_err(|error| io_error(&directory, error))?;
    let path = directory.join(format!("{sequence:020}.yaml"));
    let run_id = store.manifest()?.id;
    let mut journal = json!({
        "schema_version": "1.0",
        "kind": "compiler.read-only-command-attempt",
        "producer": "compiler.read-only-quarantine",
        "run_id": run_id,
        "sequence": sequence,
        "status": "prepared",
        "check_id": check.id,
        "profile_hash": execution.profile_hash,
        "workspace_root": project_root.canonicalize().map_err(|error| io_error(project_root, error))?,
        "state_root": store.root().canonicalize().map_err(|error| io_error(store.root(), error))?,
        "receipts_root": store.receipts_dir().canonicalize().map_err(|error| io_error(store.receipts_dir(), error))?,
        "execution_binding": execution,
        "execution_binding_hash": execution.binding_hash,
        "spawn_binding": spawn_binding,
        "workspace_pre": workspace_pre,
        "prepared_at": Utc::now(),
        "journal_hash": "",
    });
    rehash_command_attempt_journal(&mut journal);
    durable_atomic_write_yaml(&path, &journal)?;
    Ok(Some(path))
}

fn complete_command_attempt_journal(
    path: Option<&Path>,
    status: &str,
    workspace_post: Option<&WorkspaceFingerprint>,
    receipt: Option<&Value>,
) -> Result<()> {
    let Some(path) = path else {
        return Ok(());
    };
    let mut journal = read_optional_yaml_value(path)?.ok_or_else(|| {
        KoniError::Process(format!(
            "command attempt journal disappeared: {}",
            path.display()
        ))
    })?;
    if !command_attempt_journal_integrity_current(&journal) {
        return Err(KoniError::Process(format!(
            "command attempt journal integrity failed: {}",
            path.display()
        )));
    }
    let object = journal
        .as_object_mut()
        .expect("validated command attempt journal is an object");
    object.insert("status".to_owned(), Value::String(status.to_owned()));
    if status == "quarantined" {
        object.insert("quarantine_observed".to_owned(), Value::Bool(true));
    }
    object.insert("finished_at".to_owned(), json!(Utc::now()));
    object.insert(
        "workspace_post".to_owned(),
        workspace_post.cloned().map_or(Value::Null, |value| {
            serde_json::to_value(value).expect("workspace fingerprint serializes")
        }),
    );
    if let Some(receipt) = receipt {
        object.insert(
            "receipt_id".to_owned(),
            receipt.get("id").cloned().unwrap_or(Value::Null),
        );
        object.insert(
            "receipt_hash".to_owned(),
            receipt.get("receipt_hash").cloned().unwrap_or(Value::Null),
        );
    }
    rehash_command_attempt_journal(&mut journal);
    durable_atomic_write_yaml(path, &journal)
}

fn sort_values_by_normalized_hash(rows: &mut Vec<Value>) {
    // `sort_by_key(normalized_hash)` recomputes canonical JSON and SHA-256 for
    // every comparison (O(n log n) hashes). Decorate each row once, sort the
    // cheap keys, then discard them.
    let mut keyed = std::mem::take(rows)
        .into_iter()
        .map(|row| (normalized_hash(&row), row))
        .collect::<Vec<_>>();
    keyed.sort_by(|left, right| left.0.cmp(&right.0));
    *rows = keyed.into_iter().map(|(_, row)| row).collect();
}

fn load_all_receipt_rows(directory: &Path) -> Result<Vec<Value>> {
    let directory = directory.to_path_buf();
    if !directory.exists() {
        return Ok(Vec::new());
    }
    let mut rows = Vec::new();
    for entry in WalkDir::new(&directory).follow_links(false) {
        let entry = entry.map_err(|error| KoniError::Action(error.to_string()))?;
        if !entry.file_type().is_file() {
            continue;
        }
        let extension = entry
            .path()
            .extension()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        if !matches!(extension, "yaml" | "yml" | "json") {
            continue;
        }
        let text =
            fs::read_to_string(entry.path()).map_err(|error| io_error(entry.path(), error))?;
        let value: Value = if extension == "json" {
            serde_json::from_str(&text).map_err(|source| KoniError::Json {
                path: entry.path().to_path_buf(),
                source,
            })?
        } else {
            serde_yaml::from_str(&text).map_err(|source| KoniError::Yaml {
                path: entry.path().to_path_buf(),
                source,
            })?
        };
        rows.push(value);
    }
    sort_values_by_normalized_hash(&mut rows);
    Ok(rows)
}

fn load_receipt_rows(directory: &Path, receipt_type: &str) -> Result<Vec<Value>> {
    Ok(load_all_receipt_rows(directory)?
        .into_iter()
        .filter(|value| {
            value
                .get("receipt_type")
                .or_else(|| value.get("type"))
                .or_else(|| value.get("check_id"))
                .and_then(Value::as_str)
                == Some(receipt_type)
        })
        .collect())
}

fn load_receipt_rows_for_ticket(directory: &Path, ticket_id: &str) -> Result<Vec<Value>> {
    let directory = directory.to_path_buf();
    if !directory.exists() {
        return Ok(Vec::new());
    }
    let mut rows = Vec::new();
    for entry in WalkDir::new(&directory).follow_links(false) {
        let entry = entry.map_err(|error| KoniError::Action(error.to_string()))?;
        if !entry.file_type().is_file() {
            continue;
        }
        let extension = entry
            .path()
            .extension()
            .and_then(|value| value.to_str())
            .unwrap_or_default();
        if !matches!(extension, "yaml" | "yml" | "json") {
            continue;
        }
        let text =
            fs::read_to_string(entry.path()).map_err(|error| io_error(entry.path(), error))?;
        let value: Value = if extension == "json" {
            serde_json::from_str(&text).map_err(|source| KoniError::Json {
                path: entry.path().to_path_buf(),
                source,
            })?
        } else {
            serde_yaml::from_str(&text).map_err(|source| KoniError::Yaml {
                path: entry.path().to_path_buf(),
                source,
            })?
        };
        if value.get("ticket_id").and_then(Value::as_str) == Some(ticket_id) {
            rows.push(value);
        }
    }
    sort_values_by_normalized_hash(&mut rows);
    Ok(rows)
}

fn merge_receipt_rows(stable: Vec<Value>, live: Vec<Value>) -> Vec<Value> {
    stable
        .into_iter()
        .chain(live)
        .map(|receipt| (normalized_hash(&receipt), receipt))
        .collect::<BTreeMap<_, _>>()
        .into_values()
        .collect()
}

fn receipt_kind(receipt: &Value) -> Option<&str> {
    receipt
        .get("receipt_type")
        .or_else(|| receipt.get("type"))
        .and_then(Value::as_str)
}

fn is_negative_report_row(row: &Value) -> bool {
    ["status", "verdict", "polarity"]
        .into_iter()
        .filter_map(|field| row.get(field).and_then(Value::as_str))
        .any(|value| {
            matches!(
                value,
                "failed" | "error" | "inconclusive" | "contradicted" | "contradicts" | "negative"
            )
        })
}

