fn report_source_row_sort_key(row: &Value) -> String {
    let node_type = row
        .get("type")
        .or_else(|| row.get("node_type"))
        .and_then(Value::as_str)
        .unwrap_or_default();
    let status = row
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let id = row
        .get("id")
        .or_else(|| row.get("ticket_id"))
        .or_else(|| row.get("receipt_id"))
        .and_then(Value::as_str)
        .unwrap_or_default();
    let fallback = serde_json::to_string(row).unwrap_or_default();
    if !node_type.is_empty() {
        return format!("node\u{0}{node_type}\u{0}{id}\u{0}{fallback}");
    }
    if row.get("operation").is_some() && row.get("steps").is_some() {
        return format!("ticket\u{0}{status}\u{0}{id}\u{0}{fallback}");
    }
    format!("row\u{0}{id}\u{0}{status}\u{0}{fallback}")
}

fn report_output_path(base: &Path, format: crate::config::ReportFormat) -> PathBuf {
    match format {
        crate::config::ReportFormat::Json => base.with_extension("json"),
        crate::config::ReportFormat::Markdown => base.with_extension("md"),
        crate::config::ReportFormat::Yaml => base.with_extension("yaml"),
        crate::config::ReportFormat::Csv => base.with_extension("csv"),
    }
}

fn render_report_output(
    report: &crate::config::ReportDef,
    format: crate::config::ReportFormat,
    data: &Value,
) -> Result<Vec<u8>> {
    match format {
        crate::config::ReportFormat::Json => {
            let mut bytes = serde_json::to_vec_pretty(data).map_err(|source| KoniError::Json {
                path: PathBuf::from("<report output>"),
                source,
            })?;
            bytes.push(b'\n');
            Ok(bytes)
        }
        crate::config::ReportFormat::Markdown => {
            Ok(render_ledger_markdown(&report.title, &report.columns, &data["rows"]).into_bytes())
        }
        crate::config::ReportFormat::Yaml => serde_yaml::to_string(data)
            .map(String::into_bytes)
            .map_err(|source| KoniError::Yaml {
                path: PathBuf::from("<report output>"),
                source,
            }),
        crate::config::ReportFormat::Csv => Ok(render_csv_report(&data["rows"]).into_bytes()),
    }
}

#[allow(clippy::too_many_arguments)]
fn prepare_report_publication_plan(
    store: &StateStore,
    manifest_state: &RunManifest,
    report_id: String,
    bundle_hash: String,
    source_hashes: Value,
    manifest: Value,
    report_files: BTreeMap<PathBuf, Vec<u8>>,
) -> Result<ReportPublicationPlan> {
    let reports_dir = store.reports_dir();
    let store_root = store.root().to_path_buf();
    let manifest_bytes = serde_yaml::to_string(&manifest)
        .map(String::into_bytes)
        .map_err(|source| KoniError::Yaml {
            path: reports_dir.join("report-manifest.yaml"),
            source,
        })?;
    let manifest_hash = raw_sha256(&manifest_bytes);
    let transaction_hash = normalized_hash(&json!({
        "schema_version": "1.0",
        "run_id": manifest_state.id,
        "profile_hash": manifest_state.profile_hash,
        "report_id": report_id,
        "bundle_hash": bundle_hash,
        "source_hashes": source_hashes,
        "manifest_hash": manifest_hash,
    }));
    let receipt_id = stable_report_id("report-manifest", &[&transaction_hash]);
    let mut receipt = json!({
        "schema_version": "1.0",
        "id": receipt_id,
        "receipt_type": "report.manifest",
        "producer": "compiler.report",
        "run_id": manifest_state.id,
        "profile_hash": manifest_state.profile_hash,
        "report_id": report_id,
        "bundle_hash": bundle_hash,
        "transaction_hash": transaction_hash,
        "source_hashes": source_hashes,
        "manifest_hash": manifest_hash,
        "outputs": manifest["outputs"],
    });
    rehash_durable_receipt(&mut receipt);
    let receipt_bytes = serde_yaml::to_string(&receipt)
        .map(String::into_bytes)
        .map_err(|source| KoniError::Yaml {
            path: store.receipts_dir().join(format!("{receipt_id}.yaml")),
            source,
        })?;
    let snapshot_id = stable_report_id("S", &["report", &transaction_hash]);
    let snapshot = json!({
        "schema_version": "1.0",
        "id": snapshot_id,
        "kind": "report",
        "run_id": manifest_state.id,
        "profile_hash": manifest_state.profile_hash,
        "report_id": report_id,
        "bundle_hash": bundle_hash,
        "transaction_hash": transaction_hash,
        "source_hashes": source_hashes,
        "manifest_hash": manifest_hash,
    });
    let snapshot_path = store_root
        .join("snapshots")
        .join(format!("{snapshot_id}.yaml"));
    let snapshot_bytes = serde_yaml::to_string(&snapshot)
        .map(String::into_bytes)
        .map_err(|source| KoniError::Yaml {
            path: snapshot_path.clone(),
            source,
        })?;
    let event_data = json!({
        "run_id": manifest_state.id,
        "report_id": report_id,
        "kind": manifest["kind"],
        "bundle_hash": bundle_hash,
        "transaction_hash": transaction_hash,
        "source_hashes": source_hashes,
        "manifest_hash": manifest_hash,
        "ledger_count": manifest["ledger_counts"].as_object().map_or(0, Map::len),
        "snapshot_id": snapshot_id,
        "receipt_id": receipt_id,
    });
    Ok(ReportPublicationPlan {
        reports_dir: reports_dir.to_path_buf(),
        store_root: store_root.clone(),
        receipt_path: store.receipts_dir().join(format!("{receipt_id}.yaml")),
        snapshot_path,
        events_path: store_root.join("events.jsonl"),
        report_id,
        bundle_hash,
        transaction_hash,
        source_hashes,
        manifest,
        manifest_bytes,
        report_files,
        receipt_bytes,
        snapshot_bytes,
        event_data,
    })
}

fn stable_report_id(prefix: &str, parts: &[&str]) -> String {
    let digest = raw_sha256(parts.join("|").as_bytes());
    let digest = digest.strip_prefix("sha256:").unwrap_or(&digest);
    format!("{prefix}-{}", &digest[..digest.len().min(12)])
}

fn report_publication_is_current(plan: &ReportPublicationPlan) -> Result<bool> {
    if fs::read(plan.reports_dir.join("report-manifest.yaml"))
        .ok()
        .as_deref()
        != Some(plan.manifest_bytes.as_slice())
        || fs::read(&plan.receipt_path).ok().as_deref() != Some(plan.receipt_bytes.as_slice())
        || fs::read(&plan.snapshot_path).ok().as_deref() != Some(plan.snapshot_bytes.as_slice())
    {
        return Ok(false);
    }
    let mut expected = plan.report_files.keys().cloned().collect::<BTreeSet<_>>();
    expected.insert(PathBuf::from("report-manifest.yaml"));
    let actual = report_directory_files(&plan.reports_dir)?;
    if actual != expected {
        return Ok(false);
    }
    for (relative, expected) in &plan.report_files {
        if fs::read(plan.reports_dir.join(relative)).ok().as_deref() != Some(expected.as_slice()) {
            return Ok(false);
        }
    }
    Ok(read_report_compiled_event(plan)?.is_some())
}

fn report_directory_files(root: &Path) -> Result<BTreeSet<PathBuf>> {
    if !root.exists() {
        return Ok(BTreeSet::new());
    }
    let mut files = BTreeSet::new();
    for entry in WalkDir::new(root).follow_links(false) {
        let entry = entry.map_err(|error| KoniError::Action(error.to_string()))?;
        if entry.file_type().is_symlink() {
            return Err(KoniError::Action(format!(
                "report bundle contains a symlink: {}",
                entry.path().display()
            )));
        }
        if entry.file_type().is_file() {
            files.insert(
                entry
                    .path()
                    .strip_prefix(root)
                    .expect("walked report file is below report root")
                    .to_path_buf(),
            );
        }
    }
    Ok(files)
}

fn read_report_compiled_event(plan: &ReportPublicationPlan) -> Result<Option<Event>> {
    if !plan.events_path.exists() {
        return Ok(None);
    }
    let file =
        fs::File::open(&plan.events_path).map_err(|error| io_error(&plan.events_path, error))?;
    let expected_event_id = stable_report_id("report-event", &[&plan.transaction_hash]);
    let mut matched = None;
    for line in BufReader::new(file).lines() {
        let line = line.map_err(|error| io_error(&plan.events_path, error))?;
        if line.trim().is_empty() {
            continue;
        }
        let event: Event = serde_json::from_str(&line).map_err(|source| KoniError::Json {
            path: plan.events_path.clone(),
            source,
        })?;
        if event.event_type == "compiler.report.compiled"
            && event.data.get("transaction_hash").and_then(Value::as_str)
                == Some(plan.transaction_hash.as_str())
        {
            if event.id != expected_event_id || event.data != plan.event_data {
                return Err(KoniError::Action(format!(
                    "report transaction {} has a conflicting compiled event",
                    plan.transaction_hash
                )));
            }
            if matched.replace(event).is_some() {
                return Err(KoniError::Action(format!(
                    "report transaction {} has duplicate compiled events",
                    plan.transaction_hash
                )));
            }
        }
    }
    Ok(matched)
}

fn publish_report_transaction(plan: &ReportPublicationPlan) -> Result<()> {
    let transaction_root = report_publication_transaction_root(&plan.store_root);
    validate_report_publication_namespace(
        &plan.store_root,
        [
            transaction_root.as_path(),
            plan.reports_dir.as_path(),
            plan.receipt_path.as_path(),
            plan.snapshot_path.as_path(),
            plan.events_path.as_path(),
        ],
    )?;
    if transaction_root.exists() {
        return Err(KoniError::Action(format!(
            "a report publication journal already exists at {}; reopen the report action so recovery can reconcile it",
            transaction_root.display()
        )));
    }
    let result = stage_and_publish_report_transaction(plan, &transaction_root);
    if result.is_err()
        && !transaction_root.join("journal.yaml").exists()
        && transaction_root.exists()
    {
        let _ = fs::remove_dir_all(&transaction_root);
        let _ = sync_report_directory(&plan.store_root);
    }
    result
}

fn stage_and_publish_report_transaction(
    plan: &ReportPublicationPlan,
    transaction_root: &Path,
) -> Result<()> {
    let staged_reports = transaction_root.join("next-reports");
    for (relative, bytes) in &plan.report_files {
        let path = staged_reports.join(relative);
        write_report_durable_file(&path, bytes)?;
    }
    report_publication_failpoint("after_stage_outputs")?;
    fs::create_dir_all(&staged_reports).map_err(|error| io_error(&staged_reports, error))?;
    let staged_manifest = staged_reports.join("report-manifest.yaml");
    write_report_durable_file(&staged_manifest, &plan.manifest_bytes)?;

    let staged_receipt = transaction_root.join("support/receipt.yaml");
    let staged_snapshot = transaction_root.join("support/snapshot.yaml");
    let staged_event_append = transaction_root.join("support/event-append.bin");
    write_report_durable_file(&staged_receipt, &plan.receipt_bytes)?;
    write_report_durable_file(&staged_snapshot, &plan.snapshot_bytes)?;
    let events_base = match fs::read(&plan.events_path) {
        Ok(events) => events,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(error) => return Err(io_error(&plan.events_path, error)),
    };
    let event_id = stable_report_id("report-event", &[&plan.transaction_hash]);
    let event = Event {
        schema_version: "1.0".to_owned(),
        id: event_id.clone(),
        event_type: "compiler.report.compiled".to_owned(),
        at: Utc::now(),
        run_id: plan.event_data["run_id"]
            .as_str()
            .unwrap_or_default()
            .to_owned(),
        ticket_id: None,
        actor: "compiler".to_owned(),
        data: plan.event_data.clone(),
    };
    let mut event_append = Vec::new();
    if !events_base.is_empty() && !events_base.ends_with(b"\n") {
        event_append.push(b'\n');
    }
    serde_json::to_writer(&mut event_append, &event).map_err(|source| KoniError::Json {
        path: staged_event_append.clone(),
        source,
    })?;
    event_append.push(b'\n');
    write_report_durable_file(&staged_event_append, &event_append)?;
    report_publication_failpoint("after_stage_manifest")?;

    validate_staged_report_transaction(plan, &staged_reports, &staged_receipt, &staged_snapshot)?;
    report_publication_failpoint("after_support_publish")?;

    let mut report_files = plan
        .report_files
        .iter()
        .map(|(path, bytes)| (normalized_project_path(path), raw_sha256(bytes)))
        .collect::<BTreeMap<_, _>>();
    report_files.insert(
        "report-manifest.yaml".to_owned(),
        raw_sha256(&plan.manifest_bytes),
    );
    let mut journal = ReportPublicationJournal {
        schema_version: "1.0".to_owned(),
        kind: "report-publication".to_owned(),
        transaction_hash: plan.transaction_hash.clone(),
        run_id: plan.event_data["run_id"]
            .as_str()
            .unwrap_or_default()
            .to_owned(),
        profile_hash: plan.manifest["profile_hash"]
            .as_str()
            .unwrap_or_default()
            .to_owned(),
        report_id: plan.report_id.clone(),
        bundle_hash: plan.bundle_hash.clone(),
        reports_path: report_publication_relative_target(&plan.store_root, &plan.reports_dir)?,
        receipt_path: report_publication_relative_target(&plan.store_root, &plan.receipt_path)?,
        snapshot_path: report_publication_relative_target(&plan.store_root, &plan.snapshot_path)?,
        events_path: report_publication_relative_target(&plan.store_root, &plan.events_path)?,
        receipt_hash: raw_sha256(&plan.receipt_bytes),
        snapshot_hash: raw_sha256(&plan.snapshot_bytes),
        event_id,
        event_append_hash: raw_sha256(&event_append),
        events_base_len: events_base.len() as u64,
        events_base_hash: raw_sha256(&events_base),
        report_tree_hash: normalized_hash(&report_files),
        report_files,
        journal_hash: String::new(),
    };
    rehash_report_publication_journal(&mut journal);
    durable_atomic_write_yaml(&transaction_root.join("journal.yaml"), &journal)?;
    sync_report_directory(&plan.store_root)?;
    report_publication_crashpoint("after_journal");
    recover_report_publication_root(&plan.store_root)
}

fn validate_staged_report_transaction(
    plan: &ReportPublicationPlan,
    staged_reports: &Path,
    staged_receipt: &Path,
    staged_snapshot: &Path,
) -> Result<()> {
    let mut expected_files = plan.report_files.keys().cloned().collect::<BTreeSet<_>>();
    expected_files.insert(PathBuf::from("report-manifest.yaml"));
    let actual_files = report_directory_files(staged_reports)?;
    if actual_files != expected_files {
        return Err(KoniError::Action(format!(
            "staged report bundle has an unexpected file set: expected {expected_files:?}, found {actual_files:?}"
        )));
    }
    if fs::read(staged_reports.join("report-manifest.yaml"))
        .map_err(|error| io_error(staged_reports.join("report-manifest.yaml"), error))?
        != plan.manifest_bytes
        || fs::read(staged_receipt).map_err(|error| io_error(staged_receipt, error))?
            != plan.receipt_bytes
        || fs::read(staged_snapshot).map_err(|error| io_error(staged_snapshot, error))?
            != plan.snapshot_bytes
    {
        return Err(KoniError::Action(
            "staged report transaction differs from its validated plan".to_owned(),
        ));
    }
    let staged_manifest: Value =
        serde_yaml::from_slice(&plan.manifest_bytes).map_err(|source| KoniError::Yaml {
            path: staged_reports.join("report-manifest.yaml"),
            source,
        })?;
    if staged_manifest != plan.manifest {
        return Err(KoniError::Action(
            "staged report manifest does not decode to its validated contract".to_owned(),
        ));
    }
    for (relative, expected) in &plan.report_files {
        let actual = fs::read(staged_reports.join(relative))
            .map_err(|error| io_error(staged_reports.join(relative), error))?;
        if actual != *expected {
            return Err(KoniError::Action(format!(
                "staged report output {} differs from its validated bytes",
                relative.display()
            )));
        }
        match relative
            .extension()
            .and_then(|extension| extension.to_str())
        {
            Some("json") => {
                serde_json::from_slice::<Value>(&actual).map_err(|source| KoniError::Json {
                    path: staged_reports.join(relative),
                    source,
                })?;
            }
            Some("yaml" | "yml") => {
                serde_yaml::from_slice::<Value>(&actual).map_err(|source| KoniError::Yaml {
                    path: staged_reports.join(relative),
                    source,
                })?;
            }
            Some("md" | "csv") | None => {
                std::str::from_utf8(&actual).map_err(|error| {
                    KoniError::Action(format!(
                        "staged report output {} is not UTF-8: {error}",
                        relative.display()
                    ))
                })?;
            }
            Some(extension) => {
                return Err(KoniError::Action(format!(
                    "staged report output {} has unsupported extension {extension}",
                    relative.display()
                )));
            }
        }
    }
    Ok(())
}

fn report_publication_transaction_root(store_root: &Path) -> PathBuf {
    store_root.join(".report-publication")
}

fn validate_report_publication_namespace<'a>(
    store_root: &Path,
    targets: impl IntoIterator<Item = &'a Path>,
) -> Result<()> {
    let root_metadata =
        fs::symlink_metadata(store_root).map_err(|error| io_error(store_root, error))?;
    if root_metadata.file_type().is_symlink() || !root_metadata.is_dir() {
        return Err(KoniError::Action(format!(
            "report publication state root is redirected: {}",
            store_root.display()
        )));
    }
    for target in targets {
        let relative = target.strip_prefix(store_root).map_err(|_| {
            KoniError::Action(format!(
                "report publication target {} is outside state root {}",
                target.display(),
                store_root.display()
            ))
        })?;
        let mut current = store_root.to_path_buf();
        let components = relative.components().collect::<Vec<_>>();
        for (index, component) in components.iter().enumerate() {
            if !matches!(component, std::path::Component::Normal(_)) {
                return Err(KoniError::Action(format!(
                    "report publication target has an unsafe component: {}",
                    target.display()
                )));
            }
            current.push(component.as_os_str());
            match fs::symlink_metadata(&current) {
                Ok(metadata) if metadata.file_type().is_symlink() => {
                    return Err(KoniError::Action(format!(
                        "report publication rejects symlink component: {}",
                        current.display()
                    )));
                }
                Ok(metadata) if index + 1 < components.len() && !metadata.is_dir() => {
                    return Err(KoniError::Action(format!(
                        "report publication path component is not a directory: {}",
                        current.display()
                    )));
                }
                Ok(_) => {}
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => break,
                Err(error) => return Err(io_error(&current, error)),
            }
        }
    }
    Ok(())
}

fn report_publication_relative_target(store_root: &Path, target: &Path) -> Result<String> {
    let relative = target.strip_prefix(store_root).map_err(|_| {
        KoniError::Action(format!(
            "report publication target {} is outside state root {}",
            target.display(),
            store_root.display()
        ))
    })?;
    validate_report_publication_relative_path(relative)?;
    Ok(normalized_project_path(relative))
}

fn validate_report_publication_relative_path(path: &Path) -> Result<()> {
    if path.as_os_str().is_empty()
        || path.is_absolute()
        || path
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err(KoniError::Action(format!(
            "report publication journal contains an unsafe relative path: {}",
            path.display()
        )));
    }
    Ok(())
}

fn report_publication_target(store_root: &Path, relative: &str) -> Result<PathBuf> {
    let relative = Path::new(relative);
    validate_report_publication_relative_path(relative)?;
    Ok(store_root.join(relative))
}

fn rehash_report_publication_journal(journal: &mut ReportPublicationJournal) {
    journal.journal_hash.clear();
    journal.journal_hash = normalized_hash(journal);
}

fn validate_report_publication_journal(journal: &ReportPublicationJournal) -> Result<()> {
    if journal.schema_version != "1.0" || journal.kind != "report-publication" {
        return Err(KoniError::Action(
            "report publication journal has an unsupported contract".to_owned(),
        ));
    }
    let mut expected = journal.clone();
    let actual_hash = expected.journal_hash.clone();
    rehash_report_publication_journal(&mut expected);
    if actual_hash.is_empty() || expected.journal_hash != actual_hash {
        return Err(KoniError::Action(
            "report publication journal integrity failed".to_owned(),
        ));
    }
    for path in [
        &journal.reports_path,
        &journal.receipt_path,
        &journal.snapshot_path,
        &journal.events_path,
    ] {
        validate_report_publication_relative_path(Path::new(path))?;
    }
    if journal.transaction_hash.trim().is_empty()
        || journal.event_id != stable_report_id("report-event", &[&journal.transaction_hash])
        || !journal.report_files.contains_key("report-manifest.yaml")
        || normalized_hash(&journal.report_files) != journal.report_tree_hash
    {
        return Err(KoniError::Action(
            "report publication journal identity binding failed".to_owned(),
        ));
    }
    for path in journal.report_files.keys() {
        validate_report_publication_relative_path(Path::new(path))?;
    }
    Ok(())
}

fn recover_report_publication(store: &StateStore) -> Result<()> {
    let transaction_root = report_publication_transaction_root(store.root());
    validate_report_publication_namespace(store.root(), [transaction_root.as_path()])?;
    if !transaction_root.exists() {
        return Ok(());
    }
    let journal_path = transaction_root.join("journal.yaml");
    if !journal_path.exists() {
        fs::remove_dir_all(&transaction_root)
            .map_err(|error| io_error(&transaction_root, error))?;
        sync_report_directory(store.root())?;
        return Ok(());
    }
    let journal: ReportPublicationJournal = serde_yaml::from_slice(
        &fs::read(&journal_path).map_err(|error| io_error(&journal_path, error))?,
    )
    .map_err(|source| KoniError::Yaml {
        path: journal_path,
        source,
    })?;
    validate_report_publication_journal(&journal)?;
    let manifest = store.manifest()?;
    if journal.run_id != manifest.id || journal.profile_hash != manifest.profile_hash {
        return Err(KoniError::Action(format!(
            "report publication journal belongs to run {} / profile {}, not {} / {}",
            journal.run_id, journal.profile_hash, manifest.id, manifest.profile_hash
        )));
    }
    recover_report_publication_root(store.root())
}

fn recover_report_publication_root(store_root: &Path) -> Result<()> {
    let transaction_root = report_publication_transaction_root(store_root);
    let journal_path = transaction_root.join("journal.yaml");
    validate_report_publication_namespace(
        store_root,
        [transaction_root.as_path(), journal_path.as_path()],
    )?;
    let journal: ReportPublicationJournal = serde_yaml::from_slice(
        &fs::read(&journal_path).map_err(|error| io_error(&journal_path, error))?,
    )
    .map_err(|source| KoniError::Yaml {
        path: journal_path.clone(),
        source,
    })?;
    validate_report_publication_journal(&journal)?;

    let staged_receipt = transaction_root.join("support/receipt.yaml");
    let staged_snapshot = transaction_root.join("support/snapshot.yaml");
    let staged_event_append = transaction_root.join("support/event-append.bin");
    validate_report_publication_file(&staged_receipt, &journal.receipt_hash)?;
    validate_report_publication_file(&staged_snapshot, &journal.snapshot_hash)?;
    validate_report_publication_file(&staged_event_append, &journal.event_append_hash)?;

    let receipt_path = report_publication_target(store_root, &journal.receipt_path)?;
    let snapshot_path = report_publication_target(store_root, &journal.snapshot_path)?;
    let events_path = report_publication_target(store_root, &journal.events_path)?;
    let reports_path = report_publication_target(store_root, &journal.reports_path)?;
    let next_reports = transaction_root.join("next-reports");
    let previous_reports = transaction_root.join("previous-reports");
    validate_report_publication_namespace(
        store_root,
        [
            staged_receipt.as_path(),
            staged_snapshot.as_path(),
            staged_event_append.as_path(),
            receipt_path.as_path(),
            snapshot_path.as_path(),
            events_path.as_path(),
            reports_path.as_path(),
            next_reports.as_path(),
            previous_reports.as_path(),
        ],
    )?;

    install_immutable_report_file(
        &staged_receipt,
        &receipt_path,
        &journal.receipt_hash,
        &journal.transaction_hash,
    )?;
    report_publication_crashpoint("after_receipt_install");
    install_immutable_report_file(
        &staged_snapshot,
        &snapshot_path,
        &journal.snapshot_hash,
        &journal.transaction_hash,
    )?;
    report_publication_crashpoint("after_snapshot_install");
    append_report_event_idempotently(&events_path, &staged_event_append, &journal)?;
    report_publication_crashpoint("after_event_append");

    let live_is_new = report_generation_matches(&reports_path, &journal.report_files)?;
    if !live_is_new && reports_path.exists() {
        if previous_reports.exists() {
            return Err(KoniError::Action(
                "report publication recovery found both a live old generation and a previous-generation backup"
                    .to_owned(),
            ));
        }
        fs::rename(&reports_path, &previous_reports)
            .map_err(|error| io_error(&reports_path, error))?;
        sync_report_directory(
            reports_path
                .parent()
                .expect("report directory has a parent"),
        )?;
        sync_report_directory(&transaction_root)?;
        report_publication_crashpoint("after_report_backup");
    }

    if !report_generation_matches(&reports_path, &journal.report_files)? {
        if !next_reports.exists() {
            if previous_reports.exists() && !reports_path.exists() {
                fs::rename(&previous_reports, &reports_path)
                    .map_err(|error| io_error(&reports_path, error))?;
                sync_report_directory(
                    reports_path
                        .parent()
                        .expect("report directory has a parent"),
                )?;
            }
            return Err(KoniError::Action(
                "staged report generation disappeared before publication; the previous generation was restored"
                    .to_owned(),
            ));
        }
        if !report_generation_matches(&next_reports, &journal.report_files)? {
            return Err(KoniError::Action(
                "staged report generation no longer matches its durable journal".to_owned(),
            ));
        }
        fs::rename(&next_reports, &reports_path).map_err(|error| io_error(&reports_path, error))?;
        sync_report_directory(
            reports_path
                .parent()
                .expect("report directory has a parent"),
        )?;
        sync_report_directory(&transaction_root)?;
    }
    if !report_generation_matches(&reports_path, &journal.report_files)? {
        return Err(KoniError::Action(
            "published report generation failed its durable journal validation".to_owned(),
        ));
    }
    report_publication_crashpoint("after_report_install");

    if previous_reports.exists() {
        fs::remove_dir_all(&previous_reports)
            .map_err(|error| io_error(&previous_reports, error))?;
        sync_report_directory(&transaction_root)?;
    }
    report_publication_crashpoint("after_previous_cleanup");
    fs::remove_dir_all(&transaction_root).map_err(|error| io_error(&transaction_root, error))?;
    sync_report_directory(store_root)
}

fn validate_report_publication_file(path: &Path, expected_hash: &str) -> Result<()> {
    let bytes = fs::read(path).map_err(|error| io_error(path, error))?;
    if raw_sha256(&bytes) != expected_hash {
        return Err(KoniError::Action(format!(
            "report publication file {} differs from its durable journal",
            path.display()
        )));
    }
    Ok(())
}

fn install_immutable_report_file(
    staged: &Path,
    target: &Path,
    expected_hash: &str,
    transaction_hash: &str,
) -> Result<()> {
    let bytes = fs::read(staged).map_err(|error| io_error(staged, error))?;
    if raw_sha256(&bytes) != expected_hash {
        return Err(KoniError::Action(format!(
            "staged immutable report support {} failed integrity validation",
            staged.display()
        )));
    }
    match fs::read(target) {
        Ok(existing) if existing == bytes => return Ok(()),
        Ok(_) => {
            return Err(KoniError::Action(format!(
                "immutable report support target {} already has conflicting content",
                target.display()
            )));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(io_error(target, error)),
    }
    let parent = target
        .parent()
        .ok_or_else(|| KoniError::Action("report support target has no parent".to_owned()))?;
    fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    let temp = parent.join(format!(
        ".{}.{}.tmp",
        target
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("report-support"),
        stable_report_id("txn", &[transaction_hash])
    ));
    if fs::symlink_metadata(&temp).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
        return Err(KoniError::Action(format!(
            "report publication rejects symlink support temp: {}",
            temp.display()
        )));
    }
    if temp.exists() {
        let existing = fs::read(&temp).map_err(|error| io_error(&temp, error))?;
        if existing != bytes {
            fs::remove_file(&temp).map_err(|error| io_error(&temp, error))?;
        }
    }
    if !temp.exists() {
        write_report_durable_file(&temp, &bytes)?;
    }
    fs::rename(&temp, target).map_err(|error| io_error(target, error))?;
    sync_report_directory(parent)
}

fn append_report_event_idempotently(
    events_path: &Path,
    staged_append: &Path,
    journal: &ReportPublicationJournal,
) -> Result<()> {
    let append = fs::read(staged_append).map_err(|error| io_error(staged_append, error))?;
    if raw_sha256(&append) != journal.event_append_hash || append.is_empty() {
        return Err(KoniError::Action(
            "staged report event append failed integrity validation".to_owned(),
        ));
    }
    let mut current = match fs::read(events_path) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(error) => return Err(io_error(events_path, error)),
    };
    let base_len = usize::try_from(journal.events_base_len).map_err(|_| {
        KoniError::Action("report event base length does not fit this platform".to_owned())
    })?;
    if current.len() < base_len || raw_sha256(&current[..base_len]) != journal.events_base_hash {
        return Err(KoniError::Action(
            "historical events changed while recovering report publication".to_owned(),
        ));
    }
    let suffix = &current[base_len..];
    if suffix == append.as_slice() {
        return Ok(());
    }
    if !append.starts_with(suffix) {
        return Err(KoniError::Action(
            "events contain data beyond the journal-bound report append; refusing to rewrite history"
                .to_owned(),
        ));
    }
    if !suffix.is_empty() {
        let file = fs::OpenOptions::new()
            .write(true)
            .open(events_path)
            .map_err(|error| io_error(events_path, error))?;
        file.set_len(journal.events_base_len)
            .map_err(|error| io_error(events_path, error))?;
        file.sync_all()
            .map_err(|error| io_error(events_path, error))?;
        current.truncate(base_len);
    }
    if let Some(parent) = events_path.parent() {
        fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    }
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(events_path)
        .map_err(|error| io_error(events_path, error))?;
    if report_publication_crashpoint_enabled("during_event_append") {
        let split = (append.len() / 2).max(1);
        file.write_all(&append[..split])
            .map_err(|error| io_error(events_path, error))?;
        file.sync_all()
            .map_err(|error| io_error(events_path, error))?;
        report_publication_crashpoint("during_event_append");
    }
    file.write_all(&append)
        .map_err(|error| io_error(events_path, error))?;
    file.sync_all()
        .map_err(|error| io_error(events_path, error))?;
    drop(file);
    if let Some(parent) = events_path.parent() {
        sync_report_directory(parent)?;
    }
    Ok(())
}

fn report_generation_matches(
    root: &Path,
    expected_hashes: &BTreeMap<String, String>,
) -> Result<bool> {
    if !root.exists() {
        return Ok(false);
    }
    let actual_files = report_directory_files(root)?;
    let expected_files = expected_hashes
        .keys()
        .map(PathBuf::from)
        .collect::<BTreeSet<_>>();
    if actual_files != expected_files {
        return Ok(false);
    }
    for (relative, expected_hash) in expected_hashes {
        let bytes =
            fs::read(root.join(relative)).map_err(|error| io_error(root.join(relative), error))?;
        if raw_sha256(&bytes) != *expected_hash {
            return Ok(false);
        }
    }
    Ok(true)
}

fn write_report_durable_file(path: &Path, bytes: &[u8]) -> Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| KoniError::Action("report file has no parent".to_owned()))?;
    fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    let mut file = fs::OpenOptions::new()
        .create(true)
        .truncate(true)
        .write(true)
        .open(path)
        .map_err(|error| io_error(path, error))?;
    file.write_all(bytes)
        .map_err(|error| io_error(path, error))?;
    file.sync_all().map_err(|error| io_error(path, error))?;
    drop(file);
    sync_report_directory(parent)
}

fn sync_report_directory(path: &Path) -> Result<()> {
    fs::File::open(path)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| io_error(path, error))
}

#[cfg(not(test))]
fn report_publication_failpoint(_phase: &str) -> Result<()> {
    Ok(())
}

#[cfg(test)]
static REPORT_PUBLICATION_FAILPOINT: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);

#[cfg(test)]
fn report_publication_failpoint(phase: &str) -> Result<()> {
    let mut configured = REPORT_PUBLICATION_FAILPOINT
        .lock()
        .expect("report failpoint mutex is not poisoned");
    if configured.as_deref() == Some(phase) {
        *configured = None;
        return Err(KoniError::Process(format!(
            "injected report publication failure at {phase}"
        )));
    }
    Ok(())
}

#[cfg(not(test))]
fn report_publication_crashpoint_enabled(_phase: &str) -> bool {
    false
}

#[cfg(test)]
fn report_publication_crashpoint_enabled(phase: &str) -> bool {
    std::env::var("KONI_REPORT_HARD_CRASH_PHASE").as_deref() == Ok(phase)
}

#[cfg(not(test))]
fn report_publication_crashpoint(_phase: &str) {}

#[cfg(test)]
fn report_publication_crashpoint(phase: &str) {
    if !report_publication_crashpoint_enabled(phase) {
        return;
    }
    let status = Command::new("/bin/kill")
        .args(["-9", &std::process::id().to_string()])
        .status();
    panic!("hard report crashpoint {phase} failed to SIGKILL the process: {status:?}");
}

fn render_ledger_markdown(
    title: &str,
    configured_columns: &[crate::config::ReportColumnDef],
    rows: &Value,
) -> String {
    let rows = rows.as_array().cloned().unwrap_or_default();
    let columns = if configured_columns.is_empty() {
        let mut columns = BTreeSet::new();
        for row in &rows {
            if let Some(object) = row.as_object() {
                columns.extend(object.keys().cloned());
            }
        }
        columns
            .into_iter()
            .map(|id| (id.clone(), id))
            .collect::<Vec<_>>()
    } else {
        configured_columns
            .iter()
            .map(|column| {
                (
                    column.id.clone(),
                    if column.title.trim().is_empty() {
                        column.id.clone()
                    } else {
                        column.title.clone()
                    },
                )
            })
            .collect::<Vec<_>>()
    };
    let mut output = format!("# {title}\n\n");
    if columns.is_empty() {
        output.push_str("No rows.\n");
    } else {
        output.push_str(&format!(
            "| {} |\n",
            columns
                .iter()
                .map(|(_, title)| title.as_str())
                .collect::<Vec<_>>()
                .join(" | ")
        ));
        output.push_str(&format!(
            "| {} |\n",
            columns
                .iter()
                .map(|_| "---")
                .collect::<Vec<_>>()
                .join(" | ")
        ));
        if rows.is_empty() {
            output.push_str(&format!(
                "| {} |\n",
                columns
                    .iter()
                    .enumerate()
                    .map(|(index, _)| if index == 0 { "no rows" } else { "-" })
                    .collect::<Vec<_>>()
                    .join(" | ")
            ));
        }
        for row in &rows {
            let values = columns
                .iter()
                .map(|(column, _)| report_markdown_cell(row.get(column).unwrap_or(&Value::Null)))
                .collect::<Vec<_>>();
            output.push_str(&format!("| {} |\n", values.join(" | ")));
        }
    }
    output
}

fn report_markdown_cell(value: &Value) -> String {
    let text = match value {
        Value::Null => "-".to_owned(),
        Value::String(value) if value.is_empty() => "-".to_owned(),
        Value::String(value) => value.clone(),
        Value::Array(values) => {
            let rendered = values
                .iter()
                .map(report_markdown_cell)
                .collect::<Vec<_>>()
                .join(", ");
            if rendered.is_empty() {
                "-".to_owned()
            } else {
                rendered
            }
        }
        other => other.to_string(),
    };
    text.replace('|', "\\|").replace('\n', " ")
}

fn markdown_cell(value: &Value) -> String {
    let text = match value {
        Value::Null => String::new(),
        Value::String(value) => value.clone(),
        other => other.to_string(),
    };
    text.replace('|', "\\|").replace('\n', " ")
}

fn render_csv_report(rows: &Value) -> String {
    let rows = rows.as_array().cloned().unwrap_or_default();
    let mut columns = BTreeSet::new();
    for row in &rows {
        if let Some(object) = row.as_object() {
            columns.extend(object.keys().cloned());
        }
    }
    let columns: Vec<_> = columns.into_iter().collect();
    let mut output = format!(
        "{}\n",
        columns
            .iter()
            .map(|value| csv_cell(value))
            .collect::<Vec<_>>()
            .join(",")
    );
    for row in rows {
        output.push_str(
            &columns
                .iter()
                .map(|column| csv_cell(&markdown_cell(row.get(column).unwrap_or(&Value::Null))))
                .collect::<Vec<_>>()
                .join(","),
        );
        output.push('\n');
    }
    output
}

fn csv_cell(value: &str) -> String {
    if value.contains([',', '"', '\n']) {
        format!("\"{}\"", value.replace('"', "\"\""))
    } else {
        value.to_owned()
    }
}

fn field_present(node: &Node, path: &str) -> bool {
    node.field_owned(path)
        .or_else(|| node.field_owned(&format!("spec.{path}")))
        .is_some_and(|value| !value_is_empty(&value))
}

fn value_is_empty(value: &Value) -> bool {
    match value {
        Value::Null => true,
        Value::String(value) => value.trim().is_empty(),
        Value::Array(value) => value.is_empty(),
        Value::Object(value) => value.is_empty(),
        _ => false,
    }
}

fn exact_argv_value_is_valid(value: &Value) -> bool {
    let Some(items) = value.as_array() else {
        return false;
    };
    let Some(argv) = items.iter().map(Value::as_str).collect::<Option<Vec<_>>>() else {
        return false;
    };
    !argv.is_empty()
        && argv
            .iter()
            .all(|argument| !argument.trim().is_empty() && !argument.contains(['\0', '\n', '\r']))
        && !argv[0].chars().any(char::is_whitespace)
}

fn field_type_matches(kind: FieldType, value: &Value) -> bool {
    match kind {
        FieldType::Json => true,
        FieldType::String | FieldType::Path | FieldType::NodeRef => value.is_string(),
        FieldType::Integer => value.is_i64() || value.is_u64(),
        FieldType::Number => value.is_number(),
        FieldType::Boolean => value.is_boolean(),
        FieldType::List => value.is_array(),
        FieldType::Object => value.is_object(),
    }
}

fn root_node_field_value(node: &Node, path: &str) -> Option<Value> {
    let normalized = path.strip_prefix("$.").unwrap_or(path);
    node.field_owned(normalized).or_else(|| {
        (!normalized.starts_with("spec."))
            .then(|| node.field_owned(&format!("spec.{normalized}")))
            .flatten()
    })
}

fn normalized_collection_scalar(kind: FieldType, value: &Value) -> Option<String> {
    let value = value.as_str()?;
    match kind {
        FieldType::String => Some(value.to_owned()),
        FieldType::Path => normalized_relative_path(&value.replace('\\', "/")).ok(),
        _ => None,
    }
}

fn validate_field_subset(
    node: &Node,
    field: &str,
    definition: &crate::config::FieldDef,
    value: &Value,
    errors: &mut Vec<String>,
) {
    let Some(reference) = definition.subset_of.as_deref() else {
        return;
    };
    let Some(item_type) = definition.items.as_deref().map(|item| item.value_type) else {
        errors.push(format!(
            "node {} type {} field {} has an invalid configured subset_of constraint",
            node.id, node.node_type, field
        ));
        return;
    };
    let Some(values) = value.as_array() else {
        return;
    };
    let Some(reference_values) =
        root_node_field_value(node, reference).and_then(|value| value.as_array().cloned())
    else {
        errors.push(format!(
            "node {} type {} field {} subset_of reference {} is missing or is not a list",
            node.id, node.node_type, field, reference
        ));
        return;
    };
    let mut allowed = BTreeSet::new();
    for (index, candidate) in reference_values.iter().enumerate() {
        let Some(candidate) = normalized_collection_scalar(item_type, candidate) else {
            errors.push(format!(
                "node {} type {} field {} subset_of reference {}[{}] cannot be normalized as {:?}",
                node.id, node.node_type, field, reference, index, item_type
            ));
            return;
        };
        allowed.insert(candidate);
    }
    let mut missing = BTreeSet::new();
    for (index, candidate) in values.iter().enumerate() {
        let Some(candidate) = normalized_collection_scalar(item_type, candidate) else {
            errors.push(format!(
                "node {} type {} field {}[{}] cannot be normalized as {:?} for subset_of {}",
                node.id, node.node_type, field, index, item_type, reference
            ));
            continue;
        };
        if !allowed.contains(&candidate) {
            missing.insert(candidate);
        }
    }
    if !missing.is_empty() {
        let diagnosis = if item_type == FieldType::Path {
            let bounded = missing.iter().take(8).cloned().collect::<Vec<_>>();
            let suffix = (missing.len() > bounded.len()).then_some(" (additional values omitted)");
            format!(
                "missing normalized paths {}{}",
                serde_json::to_string(&bounded).unwrap_or_else(|_| "[]".to_owned()),
                suffix.unwrap_or_default()
            )
        } else {
            format!("{} value(s) are not present", missing.len())
        };
        errors.push(format!(
            "node {} type {} field {} must be a subset of root field {}; {}",
            node.id, node.node_type, field, reference, diagnosis
        ));
    }
}

fn validate_field_disjoint(
    node: &Node,
    field: &str,
    definition: &crate::config::FieldDef,
    value: &Value,
    root: &Path,
    errors: &mut Vec<String>,
) {
    let Some(reference) = definition.disjoint_from.as_deref() else {
        return;
    };
    let Some(item_type) = definition.items.as_deref().map(|item| item.value_type) else {
        errors.push(format!(
            "node {} type {} field {} has an invalid configured disjoint_from constraint",
            node.id, node.node_type, field
        ));
        return;
    };
    let Some(values) = value.as_array() else {
        return;
    };
    let Some(reference_values) =
        root_node_field_value(node, reference).and_then(|value| value.as_array().cloned())
    else {
        errors.push(format!(
            "node {} type {} field {} disjoint_from reference {} is missing or is not a list",
            node.id, node.node_type, field, reference
        ));
        return;
    };
    let mut other_paths = Vec::with_capacity(reference_values.len());
    for (index, candidate) in reference_values.iter().enumerate() {
        let Some(candidate) = normalized_collection_scalar(item_type, candidate) else {
            errors.push(format!(
                "node {} type {} field {} disjoint_from reference {}[{}] cannot be normalized as {:?}",
                node.id, node.node_type, field, reference, index, item_type
            ));
            return;
        };
        other_paths.push(candidate);
    }
    let mut overlapping = BTreeSet::new();
    for (index, candidate) in values.iter().enumerate() {
        let Some(candidate) = normalized_collection_scalar(item_type, candidate) else {
            errors.push(format!(
                "node {} type {} field {}[{}] cannot be normalized as {:?} for disjoint_from {}",
                node.id, node.node_type, field, index, item_type, reference
            ));
            continue;
        };
        let mut conflicts = false;
        for other in &other_paths {
            let overlaps = match item_type {
                FieldType::String => candidate == *other,
                FieldType::Path => match project_authority_paths_overlap(root, &candidate, other) {
                    Ok(overlaps) => overlaps,
                    Err(_) => {
                        errors.push(format!(
                                "node {} type {} field {} could not safely compare its disjoint_from path authority",
                                node.id, node.node_type, field
                            ));
                        return;
                    }
                },
                _ => false,
            };
            if overlaps {
                conflicts = true;
                break;
            }
        }
        if conflicts {
            overlapping.insert(candidate);
        }
    }
    if overlapping.is_empty() {
        return;
    }
    let diagnosis = if item_type == FieldType::Path {
        let bounded = overlapping.iter().take(8).cloned().collect::<Vec<_>>();
        let suffix = (overlapping.len() > bounded.len()).then_some(" (additional values omitted)");
        format!(
            "overlapping normalized paths {}{}",
            serde_json::to_string(&bounded).unwrap_or_else(|_| "[]".to_owned()),
            suffix.unwrap_or_default()
        )
    } else {
        format!("{} value(s) overlap", overlapping.len())
    };
    errors.push(format!(
        "node {} type {} field {} must be disjoint from root field {}; {}",
        node.id, node.node_type, field, reference, diagnosis
    ));
}

fn unique_scalar_identity(kind: FieldType, value: &Value) -> Option<String> {
    match kind {
        FieldType::String | FieldType::NodeRef => value.as_str().map(ToOwned::to_owned),
        FieldType::Path => value
            .as_str()
            .and_then(|value| normalized_relative_path(&value.replace('\\', "/")).ok()),
        FieldType::Integer | FieldType::Number if value.is_number() => Some(value.to_string()),
        FieldType::Boolean if value.is_boolean() => Some(value.to_string()),
        _ => None,
    }
}

fn validate_field_unique_by(
    node: &Node,
    field: &str,
    definition: &crate::config::FieldDef,
    value: &Value,
    errors: &mut Vec<String>,
) {
    let Some(property) = definition.unique_by.as_deref() else {
        return;
    };
    let Some(values) = value.as_array() else {
        return;
    };
    let Some(property_definition) = definition
        .items
        .as_deref()
        .and_then(|items| items.properties.get(property))
    else {
        errors.push(format!(
            "node {} type {} field {} has an invalid configured unique_by property {}",
            node.id, node.node_type, field, property
        ));
        return;
    };
    let mut seen = BTreeSet::new();
    let mut duplicates = 0usize;
    for item in values {
        let Some(identity) = item
            .as_object()
            .and_then(|item| item.get(property))
            .and_then(|value| unique_scalar_identity(property_definition.value_type, value))
        else {
            continue;
        };
        if !seen.insert(identity) {
            duplicates += 1;
        }
    }
    if duplicates > 0 {
        errors.push(format!(
            "node {} type {} field {} unique_by {} has {} duplicate value(s)",
            node.id, node.node_type, field, property, duplicates
        ));
    }
}

fn validate_field_value(
    node: &Node,
    field: &str,
    definition: &crate::config::FieldDef,
    value: &Value,
    graph: &Graph,
    root: &Path,
    errors: &mut Vec<String>,
) {
    if !field_type_matches(definition.value_type, value) {
        errors.push(format!(
            "node {} type {} field {} has the wrong type",
            node.id, node.node_type, field
        ));
        return;
    }
    if !definition.enum_values.is_empty() && !definition.enum_values.contains(value) {
        let allowed = safe_schema_enum_values(&definition.enum_values)
            .and_then(|values| serde_json::to_string(&values).ok());
        errors.push(match allowed {
            Some(allowed) => format!(
                "node {} type {} field {} is not one of the configured enum values; allowed_schema_values={allowed}",
                node.id, node.node_type, field
            ),
            None => format!(
                "node {} type {} field {} is not one of the configured enum values",
                node.id, node.node_type, field
            ),
        });
    }
    if let (Some(pattern), Some(text)) = (&definition.pattern, value.as_str()) {
        // Profile compilation validates every pattern before an Engine can be
        // opened, so this branch is only defensive against impossible IR.
        match regex::Regex::new(pattern) {
            Ok(pattern) if !pattern.is_match(text) => errors.push(format!(
                "node {} type {} field {} does not match configured pattern",
                node.id, node.node_type, field
            )),
            Err(error) => errors.push(format!(
                "node {} type {} field {} has an invalid configured pattern: {}",
                node.id, node.node_type, field, error
            )),
            _ => {}
        }
    }
    validate_field_subset(node, field, definition, value, errors);
    validate_field_disjoint(node, field, definition, value, root, errors);
    validate_field_unique_by(node, field, definition, value, errors);
    match definition.value_type {
        FieldType::Path => {
            if value
                .as_str()
                .is_none_or(|path| contained_join(root, Path::new(path)).is_err())
            {
                errors.push(format!(
                    "node {} type {} field {} is not a project-relative path",
                    node.id, node.node_type, field
                ));
            }
        }
        FieldType::NodeRef => {
            if value
                .as_str()
                .is_none_or(|node_id| graph.node(node_id).is_none())
            {
                errors.push(format!(
                    "node {} type {} field {} references a missing node",
                    node.id, node.node_type, field
                ));
            }
        }
        FieldType::List => {
            if let (Some(items), Some(item_definition)) = (value.as_array(), &definition.items) {
                for (index, item) in items.iter().enumerate() {
                    validate_field_value(
                        node,
                        &format!("{field}[{index}]"),
                        item_definition,
                        item,
                        graph,
                        root,
                        errors,
                    );
                }
            }
        }
        FieldType::Object => {
            let Some(object) = value.as_object() else {
                return;
            };
            for (property, property_definition) in &definition.properties {
                let property_path = format!("{field}.{property}");
                let property_value = object.get(property);
                if property_definition.required && property_value.is_none_or(value_is_empty) {
                    errors.push(format!(
                        "node {} type {} requires field {}",
                        node.id, node.node_type, property_path
                    ));
                }
                if let Some(property_value) = property_value {
                    validate_field_value(
                        node,
                        &property_path,
                        property_definition,
                        property_value,
                        graph,
                        root,
                        errors,
                    );
                }
            }
            if definition.additional_properties == Some(false) {
                for property in object
                    .keys()
                    .filter(|property| !definition.properties.contains_key(*property))
                {
                    errors.push(format!(
                        "node {} type {} field {} contains unknown property {}",
                        node.id, node.node_type, field, property
                    ));
                }
            }
        }
        _ => {}
    }
}

fn relation_has_cycle(graph: &Graph, start: &str, relation: &str) -> bool {
    fn visit(
        graph: &Graph,
        node: &str,
        relation: &str,
        visiting: &mut HashSet<String>,
        visited: &mut HashSet<String>,
    ) -> bool {
        if visiting.contains(node) {
            return true;
        }
        if !visited.insert(node.to_owned()) {
            return false;
        }
        visiting.insert(node.to_owned());
        let cycle = graph
            .node(node)
            .and_then(|node| node.edges.get(relation))
            .into_iter()
            .flatten()
            .any(|target| visit(graph, target, relation, visiting, visited));
        visiting.remove(node);
        cycle
    }
    visit(
        graph,
        start,
        relation,
        &mut HashSet::new(),
        &mut HashSet::new(),
    )
}

fn count_matches(count: usize, leaf: &LeafPredicate) -> bool {
    leaf.exact.is_none_or(|exact| count == exact)
        && leaf.min.is_none_or(|min| count >= min)
        && leaf.max.is_none_or(|max| count <= max)
}

fn set_json_path(root: &mut Map<String, Value>, path: &str, value: Value) {
    let mut segments = path.split('.').peekable();
    let mut current = root;
    while let Some(segment) = segments.next() {
        if segments.peek().is_none() {
            current.insert(segment.to_owned(), value);
            return;
        }
        current = current
            .entry(segment.to_owned())
            .or_insert_with(|| Value::Object(Map::new()))
            .as_object_mut()
            .expect("intermediate initial spec fields are objects");
    }
}

fn remove_json_path(root: &mut Map<String, Value>, path: &str) {
    fn remove(remaining: &[&str], current: &mut Map<String, Value>) -> bool {
        let Some((segment, tail)) = remaining.split_first() else {
            return current.is_empty();
        };
        if tail.is_empty() {
            current.remove(*segment);
        } else if let Some(child) = current.get_mut(*segment).and_then(Value::as_object_mut)
            && remove(tail, child)
        {
            current.remove(*segment);
        }
        current.is_empty()
    }

    let segments = path.split('.').collect::<Vec<_>>();
    remove(&segments, root);
}

fn render_ticket_title(template: &str, target: Option<&Node>, operation: &str) -> String {
    template
        .replace("{{ operation }}", operation)
        .replace(
            "{{ target.title }}",
            target
                .map(|node| node.title.as_str())
                .unwrap_or("graph transition"),
        )
        .replace(
            "{{ target.type }}",
            target.map(|node| node.node_type.as_str()).unwrap_or("node"),
        )
        .replace(
            "{{ target.id }}",
            target.map(|node| node.id.as_str()).unwrap_or("unknown"),
        )
}

fn goal_title(goal: &str) -> String {
    let title: String = goal.trim().chars().take(96).collect();
    if title.is_empty() {
        "Untitled goal".to_owned()
    } else {
        title
    }
}

fn planning_seed_node_id(run_id: &str, local_key: &str) -> String {
    let hash = normalized_hash(&("planning-graph-seed", run_id, local_key));
    format!("ND-{}", &hash["sha256:".len()..][..24])
}

fn worktree_name(run_id: &str, ticket_id: &str) -> String {
    format!(
        "koni-{}-{}",
        &run_id[..8.min(run_id.len())],
        ticket_id.replace('/', "-")
    )
}

fn managed_worktree_branch_deletion_target(
    primitive: &str,
    branch: &str,
) -> Result<Option<String>> {
    match primitive {
        "lease.release" | "worktree.retire" => Ok(None),
        "worktree.remove" => Ok(Some(format!("refs/heads/{branch}"))),
        other => Err(KoniError::Action(format!(
            "{other} is not a worktree retirement primitive"
        ))),
    }
}

fn managed_worktree_name_for_path(
    git: &GitBackend,
    workspace: &Path,
    fallback: &str,
) -> Result<String> {
    if workspace.exists() {
        let workspace_git = GitBackend::discover(workspace)?;
        if workspace_git.common_dir() != git.common_dir()
            || workspace_git.git_dir().parent()
                != Some(git.common_dir().join("worktrees").as_path())
        {
            return Err(KoniError::Action(format!(
                "leased worktree {} is outside the managed Git namespace",
                workspace.display()
            )));
        }
        return workspace_git
            .git_dir()
            .file_name()
            .and_then(|name| name.to_str())
            .map(ToOwned::to_owned)
            .ok_or_else(|| {
                KoniError::Action(format!(
                    "leased worktree {} has no valid managed name",
                    workspace.display()
                ))
            });
    }
    for name in git.worktree_names()? {
        if git.worktree_path(&name)?.as_deref() == Some(workspace) {
            return Ok(name);
        }
    }
    Ok(fallback.to_owned())
}

const AGENT_TERM_GRACE: Duration = Duration::from_secs(2);
const AGENT_KILL_GRACE: Duration = Duration::from_secs(2);

fn canonical_ticket_agent_worktree(root: &Path, ticket: &Ticket) -> Result<PathBuf> {
    let lease = ticket.lease.as_ref().ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} cannot spawn an agent without an active worktree lease",
            ticket.id
        ))
    })?;
    if !lease.worktree.is_absolute() {
        return Err(KoniError::Action(format!(
            "ticket {} worktree lease is not canonical: {}",
            ticket.id,
            lease.worktree.display()
        )));
    }
    let canonical = lease
        .worktree
        .canonicalize()
        .map_err(|error| io_error(&lease.worktree, error))?;
    if canonical != lease.worktree {
        return Err(KoniError::Action(format!(
            "ticket {} worktree lease is not canonical: recorded {}, canonical {}",
            ticket.id,
            lease.worktree.display(),
            canonical.display()
        )));
    }
    let project_git = GitBackend::discover(root)?;
    let worktree_git = GitBackend::discover(&canonical)?;
    if worktree_git.workdir() != canonical {
        return Err(KoniError::Action(format!(
            "ticket {} lease path {} is not a Git worktree root",
            ticket.id,
            canonical.display()
        )));
    }
    if worktree_git.common_dir() != project_git.common_dir() {
        return Err(KoniError::Action(format!(
            "ticket {} lease worktree belongs to a different Git repository",
            ticket.id
        )));
    }
    let expected_branch = format!("refs/heads/{}", lease.branch);
    let actual_branch = worktree_git.branch_ref()?;
    if actual_branch != expected_branch {
        return Err(KoniError::Action(format!(
            "ticket {} lease expects branch {}, but worktree {} selects {}",
            ticket.id,
            expected_branch,
            canonical.display(),
            actual_branch
        )));
    }
    Ok(canonical)
}

fn ensure_runtime_ticket_lease_matches(canonical: &Ticket, runtime: &Ticket) -> Result<()> {
    let canonical_lease = canonical.lease.as_ref().ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} has no canonical worktree lease",
            canonical.id
        ))
    })?;
    let runtime_lease = runtime.lease.as_ref().ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} canonical worktree state has no lease",
            canonical.id
        ))
    })?;
    if runtime.id != canonical.id
        || runtime_lease.id != canonical_lease.id
        || runtime_lease.branch != canonical_lease.branch
        || runtime_lease.worktree != canonical_lease.worktree
    {
        return Err(KoniError::Action(format!(
            "ticket {} canonical worktree state does not match its active lease",
            canonical.id
        )));
    }
    Ok(())
}

const DEFAULT_PI_AGENT_MODEL: &str = "gpt-5.6-terra";
const DIRECT_PI_AGENT_TIMEOUT: Duration = Duration::from_secs(60 * 60);
// Keep each Lead-side wait comfortably below the Pi/MCP transport's own
// request deadline. Long-running workers are observed through repeatable,
// compiler-idempotent polls instead of one tool call that can be terminated
// before its `tool_completed` event reaches the transcript state machine.
const DIRECT_PI_LEAD_WAIT_POLL_TIMEOUT: Duration = Duration::from_secs(60);
const MAX_DIRECT_PI_WORKER_LOG_BYTES: u64 = 32 * 1024 * 1024;
const DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER: &[u8] =
    b"{\"runtime\":\"pi-sdk\",\"event\":{\"event\":\"log_truncated\",\"reason\":\"byte_limit\"}}\n";
const MAX_DIRECT_PI_WORKER_LOG_PAYLOAD_BYTES: u64 =
    MAX_DIRECT_PI_WORKER_LOG_BYTES - DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER.len() as u64;

fn direct_pi_worker_log_path(directory: &Path, agent_id: &str, attempt: u32) -> Result<PathBuf> {
    validate_agent_broker_id(agent_id, "agent ID")?;
    if attempt == 0 {
        return Err(KoniError::Process(
            "direct Pi worker log attempt must be positive".to_owned(),
        ));
    }
    Ok(directory.join(format!("worker.{agent_id}.attempt-{attempt}.log")))
}

fn is_direct_pi_worker_log_name(name: &str) -> bool {
    let Some(body) = name
        .strip_prefix("worker.")
        .and_then(|body| body.strip_suffix(".log"))
    else {
        return false;
    };
    let Some((agent_id, attempt)) = body.rsplit_once(".attempt-") else {
        return false;
    };
    validate_agent_broker_id(agent_id, "agent ID").is_ok()
        && attempt.parse::<u32>().is_ok_and(|attempt| attempt > 0)
}

struct DirectPiWorkerLog {
    file: fs::File,
    path: PathBuf,
    bytes: u64,
    truncated: bool,
}

impl DirectPiWorkerLog {
    fn open(path: &Path) -> Result<Self> {
        let mut file = fs::OpenOptions::new()
            .create(true)
            .read(true)
            .append(true)
            .open(path)
            .map_err(|error| io_error(path, error))?;
        let bytes = file
            .metadata()
            .map_err(|error| io_error(path, error))?
            .len();
        let marker_len =
            u64::try_from(DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER.len()).unwrap_or(u64::MAX);
        let truncated = if bytes < marker_len {
            false
        } else {
            file.seek(SeekFrom::Start(bytes - marker_len))
                .map_err(|error| io_error(path, error))?;
            let mut tail = vec![0; DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER.len()];
            file.read_exact(&mut tail)
                .map_err(|error| io_error(path, error))?;
            file.seek(SeekFrom::End(0))
                .map_err(|error| io_error(path, error))?;
            tail == DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER
        };
        let mut log = Self {
            file,
            path: path.to_path_buf(),
            bytes,
            truncated,
        };
        if log.bytes > MAX_DIRECT_PI_WORKER_LOG_BYTES
            || (!log.truncated && log.bytes > MAX_DIRECT_PI_WORKER_LOG_PAYLOAD_BYTES)
        {
            log.truncated = false;
            log.seal_truncated()?;
        }
        Ok(log)
    }

    fn append_json_line(&mut self, line: &[u8]) -> Result<()> {
        if self.truncated {
            return Ok(());
        }
        let encoded_bytes = u64::try_from(line.len())
            .unwrap_or(u64::MAX)
            .saturating_add(1);
        if self.bytes.saturating_add(encoded_bytes) > MAX_DIRECT_PI_WORKER_LOG_PAYLOAD_BYTES {
            return self.seal_truncated();
        }
        self.file
            .write_all(line)
            .and_then(|()| self.file.write_all(b"\n"))
            .and_then(|()| self.file.flush())
            .map_err(|error| io_error(&self.path, error))?;
        self.bytes = self.bytes.saturating_add(encoded_bytes);
        Ok(())
    }

    fn seal_truncated(&mut self) -> Result<()> {
        if self.truncated {
            return Ok(());
        }
        if self.bytes > MAX_DIRECT_PI_WORKER_LOG_PAYLOAD_BYTES {
            self.file
                .set_len(MAX_DIRECT_PI_WORKER_LOG_PAYLOAD_BYTES)
                .map_err(|error| io_error(&self.path, error))?;
            self.bytes = MAX_DIRECT_PI_WORKER_LOG_PAYLOAD_BYTES;
        }
        self.file
            .write_all(DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER)
            .and_then(|()| self.file.sync_data())
            .map_err(|error| io_error(&self.path, error))?;
        self.bytes = self.bytes.saturating_add(
            u64::try_from(DIRECT_PI_WORKER_LOG_TRUNCATION_MARKER.len()).unwrap_or(u64::MAX),
        );
        self.truncated = true;
        Ok(())
    }
}

fn append_direct_pi_worker_event(
    log: &mut DirectPiWorkerLog,
    event: &crate::agent_runtime::RuntimeEvent,
) -> Result<()> {
    let Some(record) = durable_pi_transcript_record(event) else {
        return Ok(());
    };
    let line = serde_json::to_vec(&record).map_err(|error| {
        KoniError::Process(format!(
            "could not serialize direct Pi transcript event: {error}"
        ))
    })?;
    log.append_json_line(&line)
}

#[derive(Clone)]
struct PiAgentSpawnSpec {
    repository_root: PathBuf,
    worktree: PathBuf,
    run_id: String,
    profile_hash: String,
    agent_id: String,
    attempt: u32,
    input_hash: String,
    broker_role: AgentBrokerRole,
    ticket_id: Option<String>,
    stage_id: Option<String>,
    persona: String,
    model: Option<String>,
    thinking_level: Option<String>,
    prompt: String,
    log_path: PathBuf,
    directory: PathBuf,
    control: RunControlStore,
    store: StateStore,
    projected_store: Option<StateStore>,
    ticket: Option<Ticket>,
    sidecar_root: PathBuf,
}

fn spawn_direct_pi_agent(spec: PiAgentSpawnSpec) -> Result<Value> {
    spawn_direct_pi_agent_with(spec, spawn_preflighted_direct_pi_agent)
}

fn spawn_direct_pi_agent_with<T>(
    mut spec: PiAgentSpawnSpec,
    launcher: impl FnOnce(PiAgentSpawnSpec, Option<AgentBrokerContextPackBinding>) -> Result<T>,
) -> Result<T> {
    // Hold live run authority continuously from exact context construction
    // through the launcher boundary. Production enters here from the
    // compiler-locked spawn-worker action; the registered-run barrier is
    // deliberately reentrant in-process because grant issuance revalidates
    // the same namespace before publication.
    let _run_barrier = acquire_registered_run_agent_barrier(&spec.repository_root, &spec.run_id)?;
    let prepared = preflight_direct_pi_worker_context(&spec)?;
    let context_pack = prepared.as_ref().map(|prepared| prepared.binding.clone());
    if let Some(prepared) = prepared {
        // Refresh the stale preflight-era ticket clone. Otherwise later PID
        // publication could overwrite the context hash that was just bound.
        spec.ticket = Some(prepared.ticket);
    }
    if let Some(binding) = context_pack.as_ref() {
        validate_prepared_worker_context_current(&spec, binding)?;
    }
    launcher(spec, context_pack)
}

struct PreparedDirectPiWorkerContext {
    binding: AgentBrokerContextPackBinding,
    ticket: Ticket,
}

fn preflight_direct_pi_worker_context(
    spec: &PiAgentSpawnSpec,
) -> Result<Option<PreparedDirectPiWorkerContext>> {
    let AgentBrokerRole::Worker {
        ticket,
        step,
        persona,
    } = &spec.broker_role
    else {
        return Ok(None);
    };
    if spec.ticket_id.as_deref() != Some(ticket)
        || spec.stage_id.as_deref() != Some(step)
        || spec.persona != *persona
    {
        return Err(KoniError::Action(
            "direct Pi Worker context preflight crossed its selected ticket/step/persona binding"
                .to_owned(),
        ));
    }
    let engine = Engine::open_run(&spec.worktree, &spec.run_id)?;
    if engine.profile.hash != spec.profile_hash {
        return Err(KoniError::Profile(
            "direct Pi Worker context preflight loaded a stale profile".to_owned(),
        ));
    }
    let result = engine.compile_context_with_document_limit(
        &BTreeMap::from([
            ("ticket".to_owned(), Value::String(ticket.clone())),
            ("step".to_owned(), Value::String(step.clone())),
            ("persona".to_owned(), Value::String(persona.clone())),
        ]),
        MAX_AGENT_BROKER_CONTEXT_DOCUMENT_BYTES,
    )?;
    let context_hash = result
        .get("context_hash")
        .and_then(Value::as_str)
        .filter(|value| valid_worker_file_hash(value))
        .ok_or_else(|| {
            KoniError::Process(
                "Worker context preflight returned no valid compiler context hash".to_owned(),
            )
        })?
        .to_owned();
    let document_path = result
        .get("document_path")
        .and_then(Value::as_str)
        .filter(|path| !path.is_empty())
        .map(PathBuf::from)
        .ok_or_else(|| {
            KoniError::Process(
                "Worker context preflight returned no compiler document path".to_owned(),
            )
        })?;
    let document = engine.read_compiled_context_document(&document_path)?;
    validate_agent_broker_context_document_size(
        document.len(),
        MAX_AGENT_BROKER_CONTEXT_DOCUMENT_BYTES,
    )?;
    let store = engine.store()?;
    let refreshed = store.ticket(ticket)?;
    if let Some(original) = spec.ticket.as_ref() {
        ensure_runtime_ticket_lease_matches(original, &refreshed)?;
    }
    let selected = refreshed
        .workflow
        .iter()
        .find(|candidate| candidate.id == *step && candidate.persona == *persona)
        .ok_or_else(|| {
            KoniError::Action(
                "selected Worker step/persona changed during context preflight".to_owned(),
            )
        })?;
    let issued_hash = refreshed
        .extensions
        .get("issued_context_hashes")
        .and_then(Value::as_object)
        .and_then(|hashes| hashes.get(step))
        .and_then(Value::as_str);
    if selected.context_hash != context_hash || issued_hash != Some(context_hash.as_str()) {
        return Err(KoniError::Action(
            "Worker context preflight did not persist its exact selected-step binding".to_owned(),
        ));
    }
    let mut receipts = load_receipt_rows_for_ticket(store.receipts_dir(), ticket)?;
    let graph = store.graph()?;
    decorate_receipt_rows_for_ticket(
        &engine.profile,
        store,
        &refreshed,
        &graph,
        refreshed
            .lease
            .as_ref()
            .map(|lease| lease.worktree.as_path())
            .unwrap_or(&spec.worktree),
        &mut receipts,
    );
    let progress = ticket_workflow_progress_with_profile(
        Some(&engine.profile),
        &refreshed,
        &receipts,
        Some(&graph),
    );
    if !progress.ready_steps.contains(step) {
        return Err(KoniError::Action(
            "selected Worker step stopped being ready during context preflight".to_owned(),
        ));
    }
    Ok(Some(PreparedDirectPiWorkerContext {
        binding: AgentBrokerContextPackBinding {
            ticket_id: ticket.clone(),
            step_id: step.clone(),
            context_hash,
            document_path,
            document_sha256: raw_sha256(document.as_bytes()),
            document_bytes: document.len() as u64,
        },
        ticket: refreshed,
    }))
}

fn validate_prepared_worker_context_current(
    spec: &PiAgentSpawnSpec,
    binding: &AgentBrokerContextPackBinding,
) -> Result<()> {
    let engine = Engine::open_run(&spec.worktree, &spec.run_id)?;
    if engine.profile.hash != spec.profile_hash {
        return Err(KoniError::Profile(
            "prepared Worker context no longer matches the pinned profile".to_owned(),
        ));
    }
    let ticket = engine.store()?.ticket(&binding.ticket_id)?;
    let step = ticket
        .workflow
        .iter()
        .find(|step| step.id == binding.step_id)
        .ok_or_else(|| {
            KoniError::Action("prepared Worker context step no longer exists".to_owned())
        })?;
    let issued = ticket
        .extensions
        .get("issued_context_hashes")
        .and_then(Value::as_object)
        .and_then(|hashes| hashes.get(&binding.step_id))
        .and_then(Value::as_str);
    if step.context_hash != binding.context_hash || issued != Some(binding.context_hash.as_str()) {
        return Err(KoniError::Action(
            "prepared Worker context changed before grant issuance".to_owned(),
        ));
    }
    let document_path = validate_worker_context_document_path(&engine, binding)?;
    let document = engine.read_compiled_context_document(&document_path)?;
    validate_agent_broker_context_document_size(
        document.len(),
        MAX_AGENT_BROKER_CONTEXT_DOCUMENT_BYTES,
    )?;
    if document.len() as u64 != binding.document_bytes
        || raw_sha256(document.as_bytes()) != binding.document_sha256
    {
        return Err(KoniError::Action(
            "prepared Worker context bytes changed before grant issuance".to_owned(),
        ));
    }
    Ok(())
}

fn publish_direct_pi_runtime_ticket_start(
    spec: &PiAgentSpawnSpec,
    runtime_ticket: &mut Option<Ticket>,
    identity: &AgentProcessIdentity,
    effective_model: &str,
    effective_thinking_name: &str,
    now: DateTime<Utc>,
) -> Result<()> {
    let Some(ticket) = runtime_ticket.as_mut() else {
        return Ok(());
    };
    let lease = ticket.lease.as_mut().ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} lost its canonical worktree lease while starting direct Pi",
            ticket.id
        ))
    })?;
    lease.worker_pid = Some(identity.pid);
    lease.heartbeat_at = now;
    let mut active_worker = json!({
        "pid": identity.pid,
        "agent_id": spec.agent_id,
        "attempt": spec.attempt,
        "input_hash": spec.input_hash,
        "persona": spec.persona,
        "model": effective_model,
        "reasoning_effort": effective_thinking_name,
        "process_identity": identity,
        "runtime": "pi-sdk",
        "spawned_at": now,
    });
    if let Some(step_id) = &spec.stage_id
        && let Some(worker) = active_worker.as_object_mut()
    {
        worker.insert("step".to_owned(), Value::String(step_id.clone()));
    }
    ticket
        .extensions
        .insert("active_worker".to_owned(), active_worker);
    if let Some(projected) = &spec.projected_store {
        projected.write_ticket(ticket)
    } else {
        spec.store.write_ticket(ticket)
    }
}

fn spawn_preflighted_direct_pi_agent(
    spec: PiAgentSpawnSpec,
    context_pack: Option<AgentBrokerContextPackBinding>,
) -> Result<Value> {
    if let Some(binding) = context_pack.as_ref() {
        validate_prepared_worker_context_current(&spec, binding)?;
    }
    let runtime_git = GitBackend::discover(&spec.repository_root)?;
    let runtime_tickets = spec.store.work_dir().join("tickets");
    let runtime_repo_path = agent_runtime_repo_path(&runtime_git, &runtime_tickets);
    ensure_agent_runtime_excludes(&runtime_git, runtime_repo_path.as_deref())?;
    fs::create_dir_all(&spec.directory).map_err(|error| io_error(&spec.directory, error))?;
    fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&spec.log_path)
        .map_err(|error| io_error(&spec.log_path, error))?;
    let artifact = PiRuntimeArtifact::discover(&[&spec.repository_root, &spec.worktree])?;
    let broker_executable = std::env::current_exe().map_err(|error| {
        KoniError::Process(format!(
            "could not resolve the Koni executable for the direct Pi broker: {error}"
        ))
    })?;
    let broker_executable = ensure_agent_executable_outside_writable_roots(
        &broker_executable,
        &[&spec.repository_root, &spec.worktree],
        "Koni direct Pi broker",
    )?;
    let runtime_image = bind_external_executable(artifact.node_executable(), "koni-pi-node")?;
    let broker_image = bind_external_executable(&broker_executable, "koni")?;
    let grant = issue_agent_broker_grant_with_context(
        &spec.repository_root,
        &spec.worktree,
        &spec.run_id,
        &spec.profile_hash,
        &spec.agent_id,
        spec.attempt,
        &spec.input_hash,
        spec.broker_role.clone(),
        context_pack,
        runtime_image,
        broker_image,
    )?;
    let grant_id = grant.id.clone();
    let session_id = format!("pi-session-{}", Uuid::now_v7());
    let credential_lease = CredentialLeaseId(format!("pi-lease-{}", Uuid::now_v7()));
    let effective_model = spec
        .model
        .clone()
        .unwrap_or_else(|| DEFAULT_PI_AGENT_MODEL.to_owned());
    let effective_thinking = parse_pi_thinking_level(spec.thinking_level.as_deref())?;
    let effective_thinking_name = pi_thinking_level_name(effective_thinking).to_owned();
    let starting_at = Utc::now();
    if let Err(error) = spec.control.write_agent(&AgentSessionRecord {
        schema_version: "1.0".to_owned(),
        id: spec.agent_id.clone(),
        run_id: spec.run_id.clone(),
        ticket_id: spec.ticket_id.clone(),
        stage_id: spec.stage_id.clone(),
        persona: spec.persona.clone(),
        model: Some(effective_model.clone()),
        reasoning_effort: Some(effective_thinking_name.clone()),
        status: "starting".to_owned(),
        attempt: spec.attempt,
        codex_session_id: Some(session_id.clone()),
        pid: None,
        process_identity: None,
        working_directory: Some(spec.worktree.clone()),
        prompt_path: None,
        stdout_path: Some(spec.log_path.clone()),
        stderr_path: Some(spec.log_path.clone()),
        output_path: None,
        output_hash: None,
        input_hash: Some(spec.input_hash.clone()),
        result: Some(json!({
            "runtime": "pi-sdk",
            "broker_grant_id": grant_id,
            "provider": PI_RUNTIME_PROVIDER_ID,
        })),
        exit_code: None,
        timed_out: false,
        started_at: None,
        finished_at: None,
        updated_at: starting_at,
    }) {
        let _ = revoke_agent_broker_grant(&spec.worktree, &grant_id);
        return Err(error);
    }

    let pid_path = spec.directory.join("worker.pid");
    let mut runtime_ticket = spec.ticket.clone();
    let mut started_identity = None;
    let prepared = (|| -> Result<(
        PiRuntimeProcess,
        DurableAgentToolBroker,
        AgentProcessIdentity,
        RuntimeModelInfo,
    )> {
        let bootstrap = PiRuntimeBootstrapRequest {
            artifact,
            transport_session_id: session_id.clone(),
            credential_lease: credential_lease.clone(),
            timeout: DIRECT_PI_AGENT_TIMEOUT,
            network_access: true,
            oauth_callback_access: false,
        };
        let mut process = PiRuntimeProcess::bootstrap(bootstrap, &mut |identity| {
            started_identity = Some(identity.clone());
            atomic_write_worker_pid(&pid_path, identity.pid)?;
            let now = Utc::now();
            spec.control.write_agent(&AgentSessionRecord {
                schema_version: "1.0".to_owned(),
                id: spec.agent_id.clone(),
                run_id: spec.run_id.clone(),
                ticket_id: spec.ticket_id.clone(),
                stage_id: spec.stage_id.clone(),
                persona: spec.persona.clone(),
                model: Some(effective_model.clone()),
                reasoning_effort: Some(effective_thinking_name.clone()),
                status: "running".to_owned(),
                attempt: spec.attempt,
                codex_session_id: Some(session_id.clone()),
                pid: Some(identity.pid),
                process_identity: Some(identity.clone()),
                working_directory: Some(spec.worktree.clone()),
                prompt_path: None,
                stdout_path: Some(spec.log_path.clone()),
                stderr_path: Some(spec.log_path.clone()),
                output_path: None,
                output_hash: None,
                input_hash: Some(spec.input_hash.clone()),
                result: Some(json!({
                    "runtime": "pi-sdk",
                    "broker_grant_id": grant_id,
                    "provider": PI_RUNTIME_PROVIDER_ID,
                    "transport_session_id": session_id,
                })),
                exit_code: None,
                timed_out: false,
                started_at: Some(now),
                finished_at: None,
                updated_at: now,
            })?;
            activate_direct_pi_lead_slice(
                &spec.control,
                &spec.broker_role,
                &spec.agent_id,
                identity,
            )?;
            publish_direct_pi_runtime_ticket_start(
                &spec,
                &mut runtime_ticket,
                identity,
                &effective_model,
                &effective_thinking_name,
                now,
            )?;
            Ok(())
        })?;
        let metadata = process.metadata()?;
        if metadata.provider != PI_RUNTIME_PROVIDER_ID {
            return Err(KoniError::Process(
                "direct Pi host reported an unexpected provider".to_owned(),
            ));
        }
        let models = process.list_models()?;
        let selected = models
            .into_iter()
            .find(|candidate| {
                candidate.provider == PI_RUNTIME_PROVIDER_ID && candidate.id == effective_model
            })
            .ok_or_else(|| {
                KoniError::Profile(format!(
                    "configured model {effective_model} is not present in the pinned Pi provider registry"
                ))
            })?;
        if !selected.thinking_levels.is_empty()
            && !selected.thinking_levels.contains(&effective_thinking)
        {
            return Err(KoniError::Profile(format!(
                "model {} does not support Pi thinking level {}",
                selected.id, effective_thinking_name
            )));
        }
        let identity = process.process_identity()?.clone();
        let host_executable = process_executable_path(identity.pid).ok_or_else(|| {
            KoniError::Process(
                "could not resolve the contained direct Pi host executable".to_owned(),
            )
        })?;
        let broker_identity = capture_process_birth_identity(std::process::id()).ok_or_else(|| {
            KoniError::Process("could not capture Koni's direct Pi broker identity".to_owned())
        })?;
        let ingress = claim_agent_runtime_grant(
            &spec.worktree,
            &grant_id,
            &spec.agent_id,
            spec.attempt,
            &broker_identity,
            &identity,
            &host_executable,
        )?;
        let context = crate::agent_tool_broker::AgentToolContext {
            session_id: session_id.clone(),
            run_id: spec.run_id.clone(),
            agent_id: spec.agent_id.clone(),
            attempt: spec.attempt,
            runtime_process: identity.clone(),
        };
        let broker = DurableAgentToolBroker::new(ingress, context)?;
        let terminal_boundary_tools = broker.tool_catalog().terminal_boundary_tools();
        process.start_session(RuntimeSessionStart {
            session_id: session_id.clone(),
            run_id: spec.run_id.clone(),
            agent_id: spec.agent_id.clone(),
            attempt: spec.attempt,
            model: RuntimeModelRef {
                provider: selected.provider.clone(),
                model: selected.id.clone(),
                thinking_level: effective_thinking,
                input_capabilities: selected.input.clone(),
                context_window: Some(selected.context_window),
            },
            instructions: spec.prompt.clone(),
            tools: broker.runtime_tools(),
            terminal_boundary_tools,
            context_completion_required: broker
                .tool_catalog()
                .context_completion_required(),
            credential_lease: credential_lease.clone(),
        })?;
        Ok((process, broker, identity, selected))
    })();

    let (mut process, broker, identity, model_info) = match prepared {
        Ok(prepared) => prepared,
        Err(error) => {
            reconcile_failed_pi_launch(
                &spec,
                started_identity.as_ref(),
                &pid_path,
                &grant_id,
                &error,
            );
            return Err(error);
        }
    };

    let thread_identity = identity.clone();
    let thread_spec = spec.clone();
    let thread_grant_id = grant_id.clone();
    let thread_pid_path = pid_path.clone();
    let reaper_guard = SpawnedAgentReaperGuard::acquire();
    let spawn = thread::Builder::new()
        .name(format!("koni-pi-agent-{}", spec.agent_id))
        .spawn(move || {
            let _reaper_guard = reaper_guard;
            let mut runtime_log = DirectPiWorkerLog::open(&thread_spec.log_path);
            let turn = process.run_turn(
                RuntimeTurnRequest {
                    turn_id: format!("turn-{}", Uuid::now_v7()),
                    input: vec![RuntimeInput::Text {
                        text: "Execute the compiler-issued assignment now.".to_owned(),
                    }],
                    output_schema: None,
                    output_token_budget: Some(model_info.max_tokens),
                },
                &broker,
                &mut |event| {
                    let log = runtime_log.as_mut().map_err(|error| {
                        KoniError::Process(format!("could not open direct Pi event log: {error}"))
                    })?;
                    append_direct_pi_worker_event(log, event)
                },
            );
            let terminal = turn.and_then(|result| {
                validate_agent_broker_terminal_boundary(&thread_spec.worktree, &thread_grant_id)?;
                Ok(result)
            });
            let _ = revoke_agent_broker_grant(&thread_spec.worktree, &thread_grant_id);
            let shutdown = process.terminate();
            let outcome = match (terminal, shutdown) {
                (Ok(result), Ok(())) => Ok(result),
                (Err(error), _) => Err(error),
                (Ok(_), Err(error)) => Err(error),
            };
            reconcile_direct_pi_agent_exit(
                &thread_spec,
                &thread_identity,
                &thread_pid_path,
                outcome,
            );
        });
    if let Err(error) = spawn {
        let error = KoniError::Process(format!(
            "could not start direct Pi agent supervisor thread: {error}"
        ));
        reconcile_failed_pi_launch(&spec, Some(&identity), &pid_path, &grant_id, &error);
        return Err(error);
    }

    Ok(json!({
        "pid": identity.pid,
        "process_identity": identity,
        "agent_id": spec.agent_id,
        "log": spec.log_path,
        "persona": spec.persona,
        "model": effective_model,
        "reasoning_effort": effective_thinking_name,
        "runtime": "pi-sdk",
        "provider": PI_RUNTIME_PROVIDER_ID,
        "worktree": spec.worktree,
    }))
}

fn parse_pi_thinking_level(value: Option<&str>) -> Result<RuntimeThinkingLevel> {
    match value.unwrap_or("high") {
        "off" => Ok(RuntimeThinkingLevel::Off),
        "minimal" => Ok(RuntimeThinkingLevel::Minimal),
        "low" => Ok(RuntimeThinkingLevel::Low),
        "medium" => Ok(RuntimeThinkingLevel::Medium),
        "high" => Ok(RuntimeThinkingLevel::High),
        "xhigh" => Ok(RuntimeThinkingLevel::Xhigh),
        // `ultra` is accepted only as a read-compatibility bridge for a
        // pre-migration pinned run; schema 2 writes the canonical `max`.
        "max" | "ultra" => Ok(RuntimeThinkingLevel::Max),
        other => Err(KoniError::Profile(format!(
            "unsupported Pi thinking level {other}"
        ))),
    }
}

fn pi_thinking_level_name(level: RuntimeThinkingLevel) -> &'static str {
    match level {
        RuntimeThinkingLevel::Off => "off",
        RuntimeThinkingLevel::Minimal => "minimal",
        RuntimeThinkingLevel::Low => "low",
        RuntimeThinkingLevel::Medium => "medium",
        RuntimeThinkingLevel::High => "high",
        RuntimeThinkingLevel::Xhigh => "xhigh",
        RuntimeThinkingLevel::Max => "max",
    }
}

fn validate_agent_broker_terminal_boundary(working_directory: &Path, grant_id: &str) -> Result<()> {
    let git = GitBackend::discover(working_directory)?;
    let _operation_lock = acquire_agent_broker_operation_lock(git.common_dir(), grant_id)?;
    let grant = read_agent_broker_grant(git.common_dir(), grant_id)?;
    if grant.state != AgentBrokerGrantState::Consumed || grant.in_flight.is_some() {
        return Err(KoniError::Action(
            "direct Pi agent stopped without one compiler-committed terminal tool boundary"
                .to_owned(),
        ));
    }
    drop(_operation_lock);
    validate_agent_broker_terminal_product(working_directory, grant_id)
}

fn persist_pi_runtime_failure(result: &mut Map<String, Value>, error: &KoniError) -> bool {
    let KoniError::PiRuntimeTurn { failure, .. } = error else {
        return false;
    };
    result.insert("runtime_failure".to_owned(), json!(failure));
    result.insert(
        "supervision_error".to_owned(),
        Value::String(failure.message.clone()),
    );
    true
}

fn pause_planning_after_process_failure(
    control: &RunControlStore,
    result: &mut Map<String, Value>,
    error: &KoniError,
) -> Result<bool> {
    if !persist_pi_runtime_failure(result, error) {
        result.insert(
            "supervision_error".to_owned(),
            Value::String(
                "Planning agent process failed; review the durable diagnostics before resuming."
                    .to_owned(),
            ),
        );
    }
    result.insert("operator_resume_required".to_owned(), Value::Bool(true));
    let _lifecycle_lock = control.lock("lifecycle")?;
    let mut lifecycle = control
        .lifecycle()?
        .unwrap_or_else(RunLifecycleState::running);
    lifecycle.set_running(false);
    control.write_lifecycle(&lifecycle)?;
    Ok(true)
}

fn reconcile_failed_pi_launch(
    spec: &PiAgentSpawnSpec,
    identity: Option<&AgentProcessIdentity>,
    pid_path: &Path,
    grant_id: &str,
    error: &KoniError,
) {
    let _ = revoke_agent_broker_grant(&spec.worktree, grant_id);
    let _ = remove_worker_pid(pid_path);
    if let Ok(Some(mut record)) = spec.control.agent(&spec.agent_id) {
        let now = Utc::now();
        record.status = "failed".to_owned();
        record.exit_code = Some(1);
        record.finished_at = Some(now);
        record.updated_at = now;
        let mut result = record
            .result
            .take()
            .and_then(|value| value.as_object().cloned())
            .unwrap_or_default();
        result.insert("runtime".to_owned(), Value::String("pi-sdk".to_owned()));
        if !persist_pi_runtime_failure(&mut result, error) {
            result.insert(
                "supervision_error".to_owned(),
                Value::String(error.to_string()),
            );
        }
        record.result = Some(Value::Object(result));
        let _ = spec.control.write_agent(&record);
    }
    if let (Some(identity), Some(ticket_id)) = (identity, spec.ticket_id.as_deref()) {
        let store = spec.projected_store.as_ref().unwrap_or(&spec.store);
        if let Ok(mut ticket) = store.ticket(ticket_id)
            && clear_reaped_ticket_worker(&mut ticket, identity).unwrap_or(false)
        {
            let _ = store.write_ticket(&ticket);
        }
    }
}

fn exit_publication_entry_exists(path: &Path) -> Result<bool> {
    match fs::symlink_metadata(path) {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(io_error(path, error)),
    }
}

/// Acquire the stable run boundary and prove that an already-owned process may
/// publish its diagnostic exit receipt. This deliberately does not require
/// active orchestration: pausing or asking a question stops new work, but an
/// existing process must still be able to finish draining. Deletion,
/// conclusion, an absent registry/control namespace, or a redirected path
/// always fails closed before the caller reads or writes an agent record.
fn acquire_agent_exit_publication_authority(
    sidecar_root: &Path,
    run_id: &str,
    control: &RunControlStore,
    expected_profile_hash: Option<&str>,
) -> Result<RunAuthorityBarrier> {
    let barrier = acquire_run_authority_barrier_at_with_timeout(
        sidecar_root,
        run_id,
        RUN_AUTHORITY_ACTION_TIMEOUT,
    )?;
    let tombstone = sidecar_root
        .join("deletions")
        .join(format!("{run_id}.yaml"));
    let deletion_journal = control.root().join("deletion.yaml");
    if exit_publication_entry_exists(&tombstone)?
        || exit_publication_entry_exists(&deletion_journal)?
    {
        return Err(KoniError::Action(format!(
            "run {run_id} entered deletion while its process exit was waiting to publish"
        )));
    }

    let registry_path = sidecar_root.join("project.yaml");
    let registry_metadata = fs::symlink_metadata(&registry_path).map_err(|error| {
        if error.kind() == std::io::ErrorKind::NotFound {
            KoniError::Action(format!(
                "run {run_id} has no project registry for process-exit publication"
            ))
        } else {
            io_error(&registry_path, error)
        }
    })?;
    if !registry_metadata.is_file() || registry_metadata.file_type().is_symlink() {
        return Err(KoniError::Action(format!(
            "run {run_id} project registry is redirected or invalid"
        )));
    }
    let registry_header: ProjectRegistry = serde_yaml::from_str(
        &fs::read_to_string(&registry_path).map_err(|error| io_error(&registry_path, error))?,
    )
    .map_err(|source| KoniError::Yaml {
        path: registry_path.clone(),
        source,
    })?;
    let registered_git = GitBackend::discover(&registry_header.repository_root)?;
    if registered_git.sidecar_root() != sidecar_root {
        return Err(KoniError::Action(format!(
            "run {run_id} project registry points at a different Git authority"
        )));
    }
    let registry =
        ProjectRegistryStore::new(sidecar_root.to_path_buf(), registry_header.repository_root)?;
    let registration = registry
        .existing_run(run_id)
        .map_err(|error| {
            KoniError::Action(format!(
                "run {run_id} lost its registry authority while its process exit was waiting to publish: {error}"
            ))
        })?
        .ok_or_else(|| {
            KoniError::Action(format!(
                "run {run_id} was unregistered while its process exit was waiting to publish"
            ))
        })?;
    if !run_registration_status_is_live(&registration.status)
        || expected_profile_hash.is_some_and(|hash| registration.profile_hash != hash)
    {
        return Err(KoniError::Action(format!(
            "run {run_id} no longer owns live process-exit publication authority"
        )));
    }

    let expected_control_root = registry.run_root(run_id)?;
    if control.root() != expected_control_root {
        return Err(KoniError::Action(format!(
            "run {run_id} process exit targets a different control namespace"
        )));
    }
    let runs_root = sidecar_root.join("runs");
    for (label, path) in [
        ("sidecar", sidecar_root),
        ("runs", runs_root.as_path()),
        ("control", control.root()),
    ] {
        let metadata = fs::symlink_metadata(path).map_err(|error| {
            if error.kind() == std::io::ErrorKind::NotFound {
                KoniError::Action(format!(
                    "run {run_id} {label} namespace disappeared before process-exit publication"
                ))
            } else {
                io_error(path, error)
            }
        })?;
        if !metadata.is_dir() || metadata.file_type().is_symlink() {
            return Err(KoniError::Action(format!(
                "run {run_id} {label} namespace is redirected or invalid"
            )));
        }
    }
    if exit_publication_entry_exists(&tombstone)?
        || exit_publication_entry_exists(&deletion_journal)?
    {
        return Err(KoniError::Action(format!(
            "run {run_id} entered deletion during process-exit publication"
        )));
    }
    Ok(barrier)
}

fn agent_result_object_preserving_prior(result: Option<Value>) -> Map<String, Value> {
    match result {
        Some(Value::Object(result)) => result,
        Some(result) => Map::from_iter([("prior_result".to_owned(), result)]),
        None => Map::new(),
    }
}

fn direct_pi_record_accepts_exact_exit(
    record: &AgentSessionRecord,
    spec: &PiAgentSpawnSpec,
    identity: &AgentProcessIdentity,
) -> bool {
    record.id == spec.agent_id
        && record.run_id == spec.run_id
        && record.ticket_id == spec.ticket_id
        && record.stage_id == spec.stage_id
        && record.persona == spec.persona
        && record.attempt == spec.attempt
        && record.input_hash.as_deref() == Some(spec.input_hash.as_str())
        && record.working_directory.as_deref() == Some(spec.worktree.as_path())
        && record.pid == Some(identity.pid)
        && record.process_identity.as_ref() == Some(identity)
        && record.started_at.is_some()
        && agent_session_accepts_exit_receipt(&record.status)
}

fn reconcile_direct_pi_agent_exit(
    spec: &PiAgentSpawnSpec,
    identity: &AgentProcessIdentity,
    pid_path: &Path,
    outcome: Result<crate::pi_runtime_process::PiTurnResult>,
) -> bool {
    let Ok(_authority) = acquire_agent_exit_publication_authority(
        &spec.sidecar_root,
        &spec.run_id,
        &spec.control,
        Some(&spec.profile_hash),
    ) else {
        return false;
    };
    let Ok(Some(mut record)) = spec.control.agent(&spec.agent_id) else {
        return false;
    };
    if !direct_pi_record_accepts_exact_exit(&record, spec, identity) {
        return false;
    }
    let now = Utc::now();
    let successful = outcome.is_ok();
    record.status = if successful { "completed" } else { "failed" }.to_owned();
    record.exit_code = Some(if successful { 0 } else { 1 });
    record.finished_at = Some(now);
    record.updated_at = now;
    let mut result = agent_result_object_preserving_prior(record.result.take());
    match outcome {
        Ok(turn) => {
            result.insert(
                "turn".to_owned(),
                json!({
                    "turn_id": turn.turn_id,
                    "stop_reason": turn.stop_reason,
                    "usage": turn.usage,
                }),
            );
        }
        Err(error) => {
            if !persist_pi_runtime_failure(&mut result, &error) {
                result.insert(
                    "supervision_error".to_owned(),
                    Value::String(error.to_string()),
                );
            }
        }
    }
    record.result = Some(Value::Object(result));
    if spec.control.write_agent(&record).is_err() {
        return false;
    }
    if successful {
        let _ = reconcile_reaped_ticket_runtime_exit(
            &record,
            identity,
            Some((&spec.sidecar_root, &spec.run_id)),
        );
    }
    if read_worker_pid(pid_path).ok().flatten() == Some(identity.pid) {
        let _ = remove_worker_pid(pid_path);
    }
    true
}

struct SpawnedAgentProcess {
    child: Option<Child>,
    identity: AgentProcessIdentity,
}

fn spawned_agent_reaper_state() -> &'static (std::sync::Mutex<usize>, std::sync::Condvar) {
    static STATE: std::sync::OnceLock<(std::sync::Mutex<usize>, std::sync::Condvar)> =
        std::sync::OnceLock::new();
    STATE.get_or_init(|| (std::sync::Mutex::new(0), std::sync::Condvar::new()))
}

struct SpawnedAgentReaperGuard;

impl SpawnedAgentReaperGuard {
    fn acquire() -> Self {
        let (active, _) = spawned_agent_reaper_state();
        let mut active = active
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        *active += 1;
        Self
    }
}

impl Drop for SpawnedAgentReaperGuard {
    fn drop(&mut self) {
        let (active, changed) = spawned_agent_reaper_state();
        let mut active = active
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        *active = active.saturating_sub(1);
        changed.notify_all();
    }
}

/// Keep a short-lived CLI process alive until every agent it spawned has a
/// durable OS-exit receipt. Long-lived TUI processes do not need to call this;
/// their detached reaper threads remain alive with the application.
pub fn wait_for_spawned_agent_reapers() {
    let (active, changed) = spawned_agent_reaper_state();
    let mut active = active
        .lock()
        .unwrap_or_else(std::sync::PoisonError::into_inner);
    while *active > 0 {
        active = changed
            .wait(active)
            .unwrap_or_else(std::sync::PoisonError::into_inner);
    }
}

impl SpawnedAgentProcess {
    fn new(mut child: Child) -> Result<Self> {
        let pid = child.id();
        let started = Instant::now();
        let identity = loop {
            if let Some(identity) = capture_owned_agent_process_identity(pid) {
                break identity;
            }
            if child
                .try_wait()
                .map_err(|error| {
                    KoniError::Process(format!("failed to inspect spawned agent {pid}: {error}"))
                })?
                .is_some()
                || started.elapsed() >= Duration::from_millis(250)
            {
                let cleanup = terminate_spawned_child(&mut child);
                return Err(KoniError::Process(format!(
                    "could not capture durable identity for spawned agent {pid}{}",
                    cleanup
                        .err()
                        .map(|error| format!("; cleanup also failed: {error}"))
                        .unwrap_or_default()
                )));
            }
            thread::sleep(Duration::from_millis(5));
        };
        Ok(Self {
            child: Some(child),
            identity,
        })
    }

    fn terminate_and_wait(&mut self) -> Result<()> {
        let Some(child) = &mut self.child else {
            return Ok(());
        };
        let result = terminate_spawned_child(child);
        self.child = None;
        result
    }

    fn release_to_reaper(
        mut self,
        on_exit: impl FnOnce(AgentProcessIdentity, std::io::Result<std::process::ExitStatus>)
        + Send
        + 'static,
    ) {
        let Some(mut child) = self.child.take() else {
            return;
        };
        let identity = self.identity.clone();
        let reaper_guard = SpawnedAgentReaperGuard::acquire();
        thread::spawn(move || {
            let _reaper_guard = reaper_guard;
            on_exit(identity, child.wait());
        });
    }
}

impl Drop for SpawnedAgentProcess {
    fn drop(&mut self) {
        let _ = self.terminate_and_wait();
    }
}

#[cfg(test)]
fn persist_spawned_agent_process(
    process: SpawnedAgentProcess,
    pid_path: &Path,
    persist_runtime: impl FnOnce(&AgentProcessIdentity) -> Result<()>,
) -> Result<AgentProcessIdentity> {
    persist_spawned_agent_process_with_reaper(process, pid_path, persist_runtime, |_, _| {})
}

fn persist_spawned_agent_process_with_reaper(
    mut process: SpawnedAgentProcess,
    pid_path: &Path,
    persist_runtime: impl FnOnce(&AgentProcessIdentity) -> Result<()>,
    on_exit: impl FnOnce(AgentProcessIdentity, std::io::Result<std::process::ExitStatus>)
    + Send
    + 'static,
) -> Result<AgentProcessIdentity> {
    let identity = process.identity.clone();
    let persisted =
        atomic_write_worker_pid(pid_path, identity.pid).and_then(|()| persist_runtime(&identity));
    if let Err(error) = persisted {
        let _ = remove_worker_pid(pid_path);
        let cleanup = process.terminate_and_wait();
        return Err(match cleanup {
            Ok(()) => error,
            Err(cleanup_error) => KoniError::Process(format!(
                "{error}; failed to terminate spawned agent {} after persistence failure: {cleanup_error}",
                identity.pid
            )),
        });
    }
    process.release_to_reaper(on_exit);
    Ok(identity)
}

/// Persist the operating-system outcome for the raw worker record created by
/// `agent.spawn`. This record describes a process session, not proof that its
/// ticket or orchestration stage reached semantic completion; those remain
/// compiler-owned decisions. A zero exit therefore means the session itself
/// completed, while ticket progress is still derived from outputs/receipts.
fn reconcile_reaped_agent_exit(
    control: &RunControlStore,
    agent_id: &str,
    expected_identity: &AgentProcessIdentity,
    exit: std::io::Result<std::process::ExitStatus>,
    authority: Option<(&Path, &str)>,
) {
    let _authority_barrier = if let Some((sidecar_root, run_id)) = authority {
        let Ok(barrier) =
            acquire_agent_exit_publication_authority(sidecar_root, run_id, control, None)
        else {
            return;
        };
        Some(barrier)
    } else {
        None
    };
    let Ok(Some(mut record)) = control.agent(agent_id) else {
        return;
    };
    // Agent IDs are normally unique, but the identity comparison makes the
    // background waiter fail closed if a record was ever replaced/retried.
    if authority.is_some_and(|(_, run_id)| record.run_id != run_id)
        || !agent_session_accepts_exit_receipt(&record.status)
        || record.process_identity.as_ref() != Some(expected_identity)
    {
        return;
    }
    match exit {
        Ok(status) => {
            record.exit_code = status.code();
            record.status = if status.success() {
                "completed".to_owned()
            } else {
                "failed".to_owned()
            };
        }
        Err(error) => {
            record.status = "supervision_failed".to_owned();
            let mut result = agent_result_object_preserving_prior(record.result.take());
            result.insert(
                "supervision_error".to_owned(),
                Value::String(error.to_string()),
            );
            record.result = Some(Value::Object(result));
        }
    }
    if record.codex_session_id.is_none()
        && let Some(path) = record.stdout_path.as_deref()
    {
        record.codex_session_id = last_codex_session_id(path);
    }
    let now = Utc::now();
    record.finished_at = Some(now);
    record.updated_at = now;
    if control.write_agent(&record).is_err() {
        return;
    }
    if record.status == "completed" {
        let _ = reconcile_reaped_ticket_runtime_exit(&record, expected_identity, authority);
    }
}

fn agent_session_accepts_exit_receipt(status: &str) -> bool {
    matches!(
        status,
        "running" | "reaping" | "exited_without_receipt" | "boundary_committed"
    )
}

/// Publish successful worker-exit cleanup on the ticket branch before the
/// short-lived spawning process returns. This keeps atomic board inspection
/// from mistaking a completed worker for an interrupted action and avoids a
/// model-mediated recovery slice for deterministic PID/heartbeat cleanup.
/// Any ownership or worktree mismatch fails closed; the ordinary configured
/// recovery path then retains authority to reconcile it.
fn reconcile_reaped_ticket_runtime_exit(
    record: &AgentSessionRecord,
    expected_identity: &AgentProcessIdentity,
    authority: Option<(&Path, &str)>,
) -> Result<()> {
    let Some(ticket_id) = record.ticket_id.as_deref() else {
        return Ok(());
    };
    let Some(worktree) = record.working_directory.as_deref() else {
        return Ok(());
    };
    let Some((_sidecar_root, run_id)) = authority else {
        return Ok(());
    };
    let engine = Engine::open_run(worktree, run_id)?;
    if engine.profile.manifest.storage.backend != StorageBackend::Tracked {
        return Ok(());
    }
    let store = engine.store()?.clone();
    let mut ticket = store.ticket(ticket_id)?;
    let ticket_git = GitBackend::discover(worktree)?;
    let tree_excluded_paths = tracked_state_tree_exclusions(&engine.profile, ticket_git.workdir())?;
    let status_exclusions = tracked_state_status_exclusions(&engine.profile, ticket_git.workdir())?;
    let before = ticket_git.status(&status_exclusions)?;
    if !before.is_empty() {
        return Err(KoniError::Action(format!(
            "ticket {ticket_id} has uncommitted paths at successful worker exit; configured recovery must reconcile them"
        )));
    }
    if !clear_reaped_ticket_worker(&mut ticket, expected_identity)? {
        return Ok(());
    }
    let expected_ticket_path = store
        .ticket_path(&ticket)
        .strip_prefix(ticket_git.workdir())
        .map(Path::to_path_buf)
        .map_err(|_| {
            KoniError::Action(format!(
                "ticket {ticket_id} runtime path is outside its canonical worktree"
            ))
        })?;
    store.write_ticket(&ticket)?;
    let changes = ticket_git.status(&status_exclusions)?;
    if changes.len() != 1 || changes[0].path != expected_ticket_path {
        return Err(KoniError::Action(format!(
            "ticket {ticket_id} worker-exit cleanup changed paths outside its runtime ticket record"
        )));
    }
    let _ = ticket_git.checkpoint(&CheckpointRequest {
        subject: format!("chore(koni): reconcile {ticket_id} worker exit"),
        body: Some(
            "Compiler-owned process reaper cleared the identity-bound worker lease after a successful durable exit."
                .to_owned(),
        ),
        trailers: Vec::new(),
        excluded_paths: pinned_codex_project_config_exclusions(ticket_git.workdir())?,
        tree_excluded_paths,
        identity: Some(CommitIdentity::default()),
    })?;
    if let Some(pid_path) = record
        .stdout_path
        .as_deref()
        .and_then(Path::parent)
        .map(|parent| parent.join("worker.pid"))
        && read_worker_pid(&pid_path)? == Some(expected_identity.pid)
    {
        remove_worker_pid(&pid_path)?;
    }
    Ok(())
}

fn clear_reaped_ticket_worker(
    ticket: &mut Ticket,
    expected_identity: &AgentProcessIdentity,
) -> Result<bool> {
    let Some(lease) = ticket.lease.as_ref() else {
        return Ok(false);
    };
    let Some(worker_pid) = lease.worker_pid else {
        return Ok(false);
    };
    if worker_pid != expected_identity.pid {
        return Err(KoniError::Process(format!(
            "ticket {} worker PID changed before exit cleanup",
            ticket.id
        )));
    }
    let recorded_identity = active_worker_process_identity(ticket)?.ok_or_else(|| {
        KoniError::Process(format!(
            "ticket {} has no identity-bound active worker for exit cleanup",
            ticket.id
        ))
    })?;
    if &recorded_identity != expected_identity {
        return Err(KoniError::Process(format!(
            "ticket {} active worker identity changed before exit cleanup",
            ticket.id
        )));
    }
    let lease = ticket
        .lease
        .as_mut()
        .expect("the verified ticket lease remains present");
    lease.worker_pid = None;
    lease.heartbeat_at = Utc::now();
    ticket.extensions.remove("active_worker");
    Ok(true)
}

fn last_codex_session_id(path: &Path) -> Option<String> {
    let file = fs::File::open(path).ok()?;
    BufReader::new(file)
        .lines()
        .map_while(std::result::Result::ok)
        .filter_map(|line| serde_json::from_str::<Value>(&line).ok())
        .filter_map(|event| {
            (event.get("type").and_then(Value::as_str) == Some("thread.started"))
                .then(|| {
                    event
                        .get("thread_id")
                        .and_then(Value::as_str)
                        .map(ToOwned::to_owned)
                })
                .flatten()
        })
        .last()
}

fn atomic_write_worker_pid(path: &Path, pid: u32) -> Result<()> {
    let parent = path.parent().ok_or_else(|| {
        KoniError::Process(format!("worker PID path has no parent: {}", path.display()))
    })?;
    fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    let temporary = path.with_extension(format!("pid.{}.tmp", Uuid::now_v7()));
    let result = (|| {
        let mut file = fs::OpenOptions::new()
            .create_new(true)
            .write(true)
            .open(&temporary)
            .map_err(|error| io_error(&temporary, error))?;
        file.write_all(format!("{pid}\n").as_bytes())
            .map_err(|error| io_error(&temporary, error))?;
        file.sync_all()
            .map_err(|error| io_error(&temporary, error))?;
        fs::rename(&temporary, path).map_err(|error| io_error(path, error))?;
        sync_directory(parent)
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

fn read_worker_pid(path: &Path) -> Result<Option<u32>> {
    let text = match fs::read_to_string(path) {
        Ok(text) => text,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(io_error(path, error)),
    };
    text.trim().parse::<u32>().map(Some).map_err(|error| {
        KoniError::Process(format!(
            "worker PID file {} is invalid: {error}",
            path.display()
        ))
    })
}

fn remove_worker_pid(path: &Path) -> Result<()> {
    match fs::remove_file(path) {
        Ok(()) => {
            if let Some(parent) = path.parent() {
                sync_directory(parent)?;
            }
            Ok(())
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(io_error(path, error)),
    }
}

#[cfg(unix)]
fn sync_directory(path: &Path) -> Result<()> {
    fs::File::open(path)
        .and_then(|directory| directory.sync_all())
        .map_err(|error| io_error(path, error))
}

#[cfg(not(unix))]
fn sync_directory(_path: &Path) -> Result<()> {
    Ok(())
}

fn terminate_spawned_child(child: &mut Child) -> Result<()> {
    let process_group_id = child.id();
    if process_group_is_alive(process_group_id) {
        signal_process_group(process_group_id, "TERM")?;
        if !wait_for_child_process_group_exit(child, AGENT_TERM_GRACE)? {
            signal_process_group(process_group_id, "KILL")?;
            if !wait_for_child_process_group_exit(child, AGENT_KILL_GRACE)? {
                return Err(KoniError::Process(format!(
                    "spawned agent process group {process_group_id} did not exit after SIGKILL"
                )));
            }
        }
    } else {
        child.wait().map_err(|error| {
            KoniError::Process(format!(
                "failed to reap spawned agent {process_group_id}: {error}"
            ))
        })?;
    }
    Ok(())
}

fn wait_for_child_process_group_exit(child: &mut Child, timeout: Duration) -> Result<bool> {
    let process_group_id = child.id();
    let started = Instant::now();
    loop {
        let leader_exited = child
            .try_wait()
            .map_err(|error| {
                KoniError::Process(format!(
                    "failed waiting for spawned agent {process_group_id}: {error}"
                ))
            })?
            .is_some();
        if !process_group_is_alive(process_group_id) {
            if !leader_exited {
                child.wait().map_err(|error| {
                    KoniError::Process(format!(
                        "failed to reap spawned agent {process_group_id}: {error}"
                    ))
                })?;
            }
            return Ok(true);
        }
        if started.elapsed() >= timeout {
            return Ok(false);
        }
        thread::sleep(Duration::from_millis(20));
    }
}

fn terminate_owned_agent_process(
    identity: &AgentProcessIdentity,
    term_grace: Duration,
    kill_grace: Duration,
) -> Result<bool> {
    if !agent_process_identity_has_strong_birth_marker(identity) {
        if process_is_alive(identity.pid) {
            return Err(KoniError::Process(format!(
                "refusing to signal PID {} because its durable process identity uses a legacy or weak birth marker",
                identity.pid
            )));
        }
        return Ok(false);
    }
    if !owned_agent_process_is_alive(identity) {
        if process_is_alive(identity.pid) {
            return Err(KoniError::Process(format!(
                "refusing to signal PID {} because its durable process identity no longer matches",
                identity.pid
            )));
        }
        return Ok(false);
    }
    signal_process_group(identity.process_group_id, "TERM")?;
    if wait_for_process_group_exit(identity.process_group_id, term_grace) {
        return Ok(true);
    }
    // TERM may have exited the recorded group leader while leaving an
    // ignoring descendant behind. Revalidate the same kernel birth identity
    // immediately before escalation so a stale or recycled PGID can never
    // acquire SIGKILL authority from the earlier TERM check.
    if !owned_agent_process_is_alive(identity) {
        if process_group_is_alive(identity.process_group_id) {
            return Err(KoniError::Process(format!(
                "refusing to send SIGKILL to process group {} because its durable leader identity no longer matches",
                identity.process_group_id
            )));
        }
        return Ok(true);
    }
    signal_process_group(identity.process_group_id, "KILL")?;
    if wait_for_process_group_exit(identity.process_group_id, kill_grace) {
        return Ok(true);
    }
    Err(KoniError::Process(format!(
        "agent process group {} did not exit after SIGKILL",
        identity.process_group_id
    )))
}

fn signal_process_group(process_group_id: u32, signal: &str) -> Result<()> {
    #[cfg(unix)]
    let target = format!("-{process_group_id}");
    #[cfg(not(unix))]
    let target = process_group_id.to_string();
    let status = Command::new("kill")
        .arg(format!("-{signal}"))
        .arg("--")
        .arg(target)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .map_err(|error| {
            KoniError::Process(format!(
                "failed to signal agent process group {process_group_id}: {error}"
            ))
        })?;
    if status.success() || !process_group_is_alive(process_group_id) {
        Ok(())
    } else {
        Err(KoniError::Process(format!(
            "agent process group {process_group_id} did not accept SIG{signal}"
        )))
    }
}

fn process_group_is_alive(process_group_id: u32) -> bool {
    #[cfg(unix)]
    let target = format!("-{process_group_id}");
    #[cfg(not(unix))]
    let target = process_group_id.to_string();
    Command::new("kill")
        .arg("-0")
        .arg("--")
        .arg(target)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .is_ok_and(|status| status.success())
}

fn wait_for_process_group_exit(process_group_id: u32, timeout: Duration) -> bool {
    let started = Instant::now();
    while process_group_is_alive(process_group_id) {
        if started.elapsed() >= timeout {
            return false;
        }
        thread::sleep(Duration::from_millis(20));
    }
    true
}

fn active_worker_process_identity(ticket: &Ticket) -> Result<Option<AgentProcessIdentity>> {
    let Some(value) = ticket
        .extensions
        .get("active_worker")
        .and_then(Value::as_object)
        .and_then(|worker| worker.get("process_identity"))
    else {
        return Ok(None);
    };
    serde_json::from_value(value.clone())
        .map(Some)
        .map_err(|error| {
            KoniError::Action(format!(
                "ticket {} has invalid active worker process identity: {error}",
                ticket.id
            ))
        })
}

fn clear_ticket_review_runtime(
    store: &StateStore,
    ticket_id: &str,
    expected_pid: Option<u32>,
) -> Result<()> {
    let mut ticket = store.ticket(ticket_id)?;
    let recorded_pid = ticket.lease.as_ref().and_then(|lease| lease.worker_pid);
    if recorded_pid.is_none() && !ticket.extensions.contains_key("active_worker") {
        return Ok(());
    }
    if let Some(expected_pid) = expected_pid
        && recorded_pid != Some(expected_pid)
    {
        return Err(KoniError::Process(format!(
            "refusing to clear ticket {ticket_id} reviewer runtime: expected process {expected_pid}, recorded {:?}",
            recorded_pid
        )));
    }
    if let Some(identity) = active_worker_process_identity(&ticket)?
        && owned_agent_process_is_alive(&identity)
    {
        return Err(KoniError::Process(format!(
            "refusing to clear live ticket reviewer {}",
            identity.pid
        )));
    }
    if let Some(lease) = &mut ticket.lease {
        lease.worker_pid = None;
        lease.heartbeat_at = Utc::now();
    }
    ticket.extensions.remove("active_worker");
    store.write_ticket(&ticket)
}

fn ticket_worker_is_alive(ticket: &Ticket) -> bool {
    let Some(pid) = ticket.lease.as_ref().and_then(|lease| lease.worker_pid) else {
        return false;
    };
    match active_worker_process_identity(ticket) {
        Ok(Some(identity)) => identity.pid == pid && owned_agent_process_is_alive(&identity),
        Ok(None) => false,
        Err(_) => false,
    }
}

fn process_is_alive(pid: u32) -> bool {
    let signalable = Command::new("kill")
        .arg("-0")
        .arg(pid.to_string())
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status()
        .is_ok_and(|status| status.success());
    if !signalable {
        return false;
    }
    Command::new("ps")
        .args(["-o", "stat=", "-p", &pid.to_string()])
        .stdin(Stdio::null())
        .stderr(Stdio::null())
        .output()
        .ok()
        .filter(|output| output.status.success())
        .and_then(|output| String::from_utf8(output.stdout).ok())
        .is_none_or(|state| !state.trim_start().starts_with('Z'))
}

fn owned_agent_pid(context: &BTreeMap<String, Value>) -> Option<u32> {
    context
        .get("effects")?
        .as_array()?
        .iter()
        .rev()
        .find(|effect| effect.get("primitive").and_then(Value::as_str) == Some("agent.spawn"))?
        .get("output")?
        .get("pid")?
        .as_u64()
        .and_then(|pid| u32::try_from(pid).ok())
}

fn owned_agent_identity(context: &BTreeMap<String, Value>) -> Option<AgentProcessIdentity> {
    serde_json::from_value(
        context
            .get("effects")?
            .as_array()?
            .iter()
            .rev()
            .find(|effect| effect.get("primitive").and_then(Value::as_str) == Some("agent.spawn"))?
            .get("output")?
            .get("process_identity")?
            .clone(),
    )
    .ok()
}

fn ticket_operation<'a>(
    profile: &'a CompiledProfile,
    ticket: &Ticket,
) -> Result<&'a crate::config::OperationDef> {
    let registry_id = ticket
        .extensions
        .get("operation_registry_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            KoniError::Profile(format!(
                "ticket {} has no operation registry binding",
                ticket.id
            ))
        })?;
    profile.operations.get(registry_id).ok_or_else(|| {
        KoniError::Profile(format!(
            "ticket {} references missing operation {registry_id}",
            ticket.id
        ))
    })
}

fn unbound_ordinary_change_control_barrier(
    profile: &CompiledProfile,
    ticket: &Ticket,
) -> Option<bool> {
    if !ticket.change_control.is_inactive_history_only() {
        return None;
    }
    let mut candidates = profile
        .operations
        .values()
        .filter(|candidate| candidate.public_operation() == ticket.operation);
    let first = candidates.next()?;
    if !matches!(
        &first.change_control,
        OperationChangeControlDef::Ordinary { .. }
    ) {
        return None;
    }
    let barrier = first.change_control_barrier;
    candidates
        .all(|candidate| {
            matches!(
                &candidate.change_control,
                OperationChangeControlDef::Ordinary { .. }
            ) && candidate.change_control_barrier == barrier
        })
        .then_some(barrier)
}

fn expand_ticket_owned_scope(profile: &CompiledProfile, ticket: &mut Ticket) -> Result<bool> {
    let operation = ticket_operation(profile, ticket)?;
    let mut changed = false;
    for node in ticket.outputs.iter().flat_map(|output| {
        output
            .typed
            .get("graph_delta")
            .into_iter()
            .flat_map(|delta| {
                [
                    "upsert",
                    "add_nodes",
                    "added_nodes",
                    "nodes",
                    "update_nodes",
                    "updated_nodes",
                ]
                .into_iter()
                .flat_map(|field| {
                    delta
                        .get(field)
                        .and_then(Value::as_array)
                        .into_iter()
                        .flatten()
                })
            })
    }) {
        let Some(node_id) = node.get("id").and_then(Value::as_str) else {
            continue;
        };
        let Some(node_type) = node.get("type").and_then(Value::as_str) else {
            continue;
        };
        if !operation
            .allowed_new_node_types
            .iter()
            .any(|allowed| allowed == node_type)
        {
            continue;
        }
        changed |= ticket.scope.read_nodes.insert(node_id.to_owned());
        changed |= ticket.scope.write_nodes.insert(node_id.to_owned());
    }
    Ok(changed)
}

/// Project a graph node into the exact semantic shape a ticket worker may
/// inspect and author. Compiler-owned projections remain durable in graph
/// storage, but including them in every worker closure duplicates large
/// readiness/obligation ledgers and invites accidental copy-back in an
/// existing-node upsert. Nested compiler-owned paths (for example the
/// approved planning handoff at `spec.planning_context`) are removed with the
/// same profile contract used by semantic receipt hashing and review packets.
fn model_facing_context_node(profile: &CompiledProfile, node: &Node) -> Value {
    let mut value = node.as_value();
    if let Some(definition) = profile.node_types.get(&node.node_type) {
        for field in &definition.compiler_owned_fields {
            if !definition
                .agent_visible_compiler_owned_fields
                .iter()
                .any(|visible| visible == field)
            {
                remove_value_path(&mut value, field);
            }
        }
    }
    if node.annotations.get("run_root").and_then(Value::as_bool) == Some(true)
        && let Some(field) = profile
            .manifest
            .initialization
            .planning_context_field
            .as_deref()
    {
        let path = format!("spec.{}", field.trim_start_matches("spec."));
        if let Some(mut planning_context) = value_at_dotted_path(&value, &path).cloned()
            && let Some(context) = planning_context.as_object_mut()
            && let Some(seed) = context.remove("graph_seed")
        {
            let node_count = seed
                .get("nodes")
                .and_then(Value::as_array)
                .map_or(0, Vec::len);
            let edge_count = seed
                .get("edges")
                .and_then(Value::as_array)
                .map_or(0, Vec::len);
            context.insert(
                "graph_seed_projection".to_owned(),
                json!({
                    "materialized_in_typed_graph": true,
                    "graph_seed_hash": context.get("graph_seed_hash"),
                    "node_count": node_count,
                    "edge_count": edge_count,
                }),
            );
            let _ = set_value_path(&mut value, &path, planning_context);
        }
    }
    value
}

/// Remove planner prose only after its approved graph seed has been
/// materialized into the typed graph. Seedless legacy planning context is
/// intentionally retained because no typed replacement can be proven.
fn product_execution_context_node(profile: &CompiledProfile, node: &Node) -> Value {
    let mut value = model_facing_context_node(profile, node);
    if node.annotations.get("run_root").and_then(Value::as_bool) != Some(true) {
        return value;
    }
    let Some(field) = profile
        .manifest
        .initialization
        .planning_context_field
        .as_deref()
    else {
        return value;
    };
    let path = format!("spec.{}", field.trim_start_matches("spec."));
    let Some(mut planning_context) = value_at_dotted_path(&value, &path).cloned() else {
        return value;
    };
    let Some(context) = planning_context.as_object_mut() else {
        return value;
    };
    let materialized = context
        .get("graph_seed_projection")
        .and_then(|projection| projection.get("materialized_in_typed_graph"))
        .and_then(Value::as_bool)
        == Some(true);
    if !materialized {
        return value;
    }
    if let Some(stages) = context.get_mut("stages").and_then(Value::as_array_mut) {
        for stage in stages {
            let Some(stage) = stage.as_object_mut() else {
                continue;
            };
            let output_is_hash_bound = stage
                .get("output_hash")
                .and_then(Value::as_str)
                .is_some_and(|hash| !hash.trim().is_empty());
            if output_is_hash_bound && stage.remove("output").is_some() {
                stage.insert(
                    "output_projection".to_owned(),
                    Value::String("materialized_in_typed_graph".to_owned()),
                );
            }
        }
    }
    let _ = set_value_path(&mut value, &path, planning_context);
    value
}

fn product_execution_spec_slice(
    profile: &CompiledProfile,
    spec_slice: &Value,
    graph_closure_node_ids: &BTreeSet<String>,
    graph_closure_emitted: bool,
) -> Value {
    let mut projected = spec_slice.clone();
    let Some(projected_object) = projected.as_object_mut() else {
        return projected;
    };
    let source_nodes = projected_object
        .remove("nodes")
        .and_then(|nodes| nodes.as_array().cloned())
        .unwrap_or_default();
    let source_node_count = source_nodes.len();
    let nodes = source_nodes
        .into_iter()
        .filter(|node| {
            node.get("id")
                .and_then(Value::as_str)
                .is_none_or(|id| !graph_closure_emitted || !graph_closure_node_ids.contains(id))
        })
        .map(|node| {
            serde_json::from_value::<Node>(node.clone())
                .map(|node| product_execution_context_node(profile, &node))
                .unwrap_or(node)
        })
        .collect::<Vec<_>>();
    let omitted_node_count = source_node_count.saturating_sub(nodes.len());
    projected_object.insert("nodes".to_owned(), Value::Array(nodes));

    let source_edges = projected_object
        .remove("edges")
        .and_then(|edges| edges.as_array().cloned())
        .unwrap_or_default();
    let source_edge_count = source_edges.len();
    let edges = source_edges
        .into_iter()
        .filter(|edge| {
            let source_in_closure = edge
                .get("source")
                .and_then(Value::as_str)
                .is_some_and(|id| graph_closure_node_ids.contains(id));
            let target_in_closure = edge
                .get("target")
                .and_then(Value::as_str)
                .is_some_and(|id| graph_closure_node_ids.contains(id));
            !(graph_closure_emitted && source_in_closure && target_in_closure)
        })
        .collect::<Vec<_>>();
    let omitted_edge_count = source_edge_count.saturating_sub(edges.len());
    projected_object.insert("edges".to_owned(), Value::Array(edges));
    projected_object.insert(
        "instruction".to_owned(),
        Value::String(if graph_closure_emitted {
            "Use graph_closure as the exact assigned typed state. Nodes and edges here are only the nonduplicate reviewed neighborhood; context_provenance.spec_slice_hash binds the complete compiler-validated slice."
                .to_owned()
        } else {
            "Use these reviewed typed nodes and edges as the assigned living-spec state; context_provenance.spec_slice_hash binds the complete compiler-validated slice."
                .to_owned()
        }),
    );
    if graph_closure_emitted {
        projected_object.insert(
            "graph_closure_ref".to_owned(),
            Value::String("#/graph_closure".to_owned()),
        );
        projected_object.insert(
            "graph_closure_node_ids".to_owned(),
            json!(graph_closure_node_ids),
        );
    }
    projected_object.insert(
        "projection".to_owned(),
        json!({
            "mode": "product_execution",
            "omitted_duplicate_nodes": omitted_node_count,
            "omitted_duplicate_edges": omitted_edge_count,
        }),
    );
    projected
}

fn product_execution_ticket(ticket: &Ticket) -> Value {
    let workflow = ticket
        .workflow
        .iter()
        .map(|step| {
            json!({
                "id": step.id,
                "persona": step.persona,
                "selected_step_ref": "#/selected_step",
            })
        })
        .collect::<Vec<_>>();
    json!({
        "schema_version": ticket.schema_version,
        "id": ticket.id,
        "operation": ticket.operation,
        "status": ticket.status,
        "title": ticket.title,
        "target_nodes": ticket.target_nodes,
        "scope": ticket.scope,
        "source_state_key": ticket.source_state_key,
        "target_state_key": ticket.target_state_key,
        "obligation_keys": ticket.obligation_keys,
        "profile_hash": ticket.profile_hash,
        "rule_id": ticket.rule_id,
        "workflow": workflow,
        "blockers": ticket.blockers,
        "change_control": ticket.change_control,
        "projection": {
            "mode": "product_execution",
            "selected_step_ref": "#/selected_step",
            "operational_state_omitted": ["lease", "extensions", "outputs", "reviews"],
        },
    })
}

fn product_execution_contracts(mut contracts: Value) -> Value {
    let Some(object) = contracts.as_object_mut() else {
        return contracts;
    };
    for key in ["node_types", "edge_types", "gate_policies", "queries"] {
        object.insert(key.to_owned(), Value::Array(Vec::new()));
    }
    object.remove("mutation_intent");
    object.remove("semantic_field_rules");
    if let Some(output_payload) = object
        .get_mut("output_payload")
        .and_then(Value::as_object_mut)
    {
        for key in [
            "pre_submit_check",
            "node_descriptions",
            "required_node_fields",
            "required_node_any",
            "allowed_outgoing_edges",
        ] {
            output_payload.remove(key);
        }
        if let Some(field_shapes) = output_payload
            .get_mut("field_shapes")
            .and_then(Value::as_object_mut)
        {
            field_shapes.insert("graph_delta".to_owned(), json!({}));
        }
        output_payload.insert(
            "rule".to_owned(),
            Value::String(
                "Submit the documented scalar, list, and structured-output fields directly. graph_delta must be absent or an empty object because this step has no graph mutation authority; typed remains compiler-owned."
                    .to_owned(),
            ),
        );
    }
    object.insert(
        "graph_delta_policy".to_owned(),
        json!({
            "step_policy": "forbidden",
            "rule": "This step cannot mutate typed graph state. Omit graph_delta or submit an empty object.",
        }),
    );
    object.insert(
        "projection".to_owned(),
        json!({
            "mode": "product_execution",
            "omitted_authoring_contracts": true,
            "full_contract_selection_hash_ref": "#/context_provenance/contract_selection_hash",
        }),
    );
    contracts
}

fn product_execution_reviews(ticket: &Ticket) -> Vec<Value> {
    ticket
        .reviews
        .last()
        .map(|review| {
            let findings = review
                .agent_binding
                .as_ref()
                .map(|binding| binding.findings.clone())
                .filter(|findings| !findings.is_empty())
                .unwrap_or_else(|| vec![review.notes.clone()]);
            let evidence_pointers = review
                .agent_binding
                .as_ref()
                .map(|binding| binding.evidence_pointers.clone())
                .unwrap_or_default();
            let failure_domain = review
                .agent_binding
                .as_ref()
                .and_then(|binding| binding.failure_domain.clone());
            json!({
                "status": review.status,
                "reviewed_at": review.reviewed_at,
                "failure_domain": failure_domain,
                "findings": findings,
                "evidence_pointers": evidence_pointers,
            })
        })
        .into_iter()
        .collect()
}

fn build_ticket_spec_slice(
    profile: &CompiledProfile,
    graph: &Graph,
    ticket: &Ticket,
    max_depth: usize,
    max_nodes: usize,
) -> Result<Value> {
    let max_nodes = max_nodes.max(1);
    let mut selected = BTreeSet::new();
    let mut queue = VecDeque::new();
    let roots = graph
        .nodes()
        .filter(|node| node.annotations.get("run_root").and_then(Value::as_bool) == Some(true))
        .map(|node| node.id.clone())
        .collect::<Vec<_>>();
    let anchors = ticket
        .target_nodes
        .iter()
        .chain(&ticket.scope.write_nodes)
        .chain(&ticket.scope.read_nodes)
        .cloned()
        .collect::<BTreeSet<_>>();
    if let Some(missing) = anchors.iter().find(|node_id| graph.node(node_id).is_none()) {
        return Err(KoniError::Action(format!(
            "ticket {} references missing mandatory graph anchor {missing}",
            ticket.id
        )));
    }
    if anchors.len() > max_nodes {
        return Err(KoniError::Action(format!(
            "ticket {} has {} graph anchors, above the profile spec-slice limit {max_nodes}",
            ticket.id,
            anchors.len()
        )));
    }
    for node_id in &anchors {
        if selected.insert(node_id.clone()) {
            queue.push_back((node_id.clone(), 0usize));
        }
    }
    // The run root keeps the objective visible, but it is not a traversal seed:
    // expanding every root sibling would spend ticket-local context on
    // unrelated work before following the assigned anchors.
    for node_id in &roots {
        if selected.len() >= max_nodes {
            break;
        }
        selected.insert(node_id.clone());
    }
    while let Some((node_id, depth)) = queue.pop_front() {
        if depth >= max_depth || selected.len() >= max_nodes {
            continue;
        }
        let mut neighbors = graph
            .outgoing(&node_id, None)
            .into_iter()
            .chain(graph.incoming(&node_id, None))
            .map(|node| node.id.clone())
            .collect::<BTreeSet<_>>();
        while let Some(neighbor) = neighbors.pop_first() {
            if selected.len() >= max_nodes {
                break;
            }
            if selected.insert(neighbor.clone()) {
                queue.push_back((neighbor, depth + 1));
            }
        }
    }
    let nodes = selected
        .iter()
        .filter_map(|node_id| graph.node(node_id))
        .map(|node| model_facing_context_node(profile, node))
        .collect::<Vec<_>>();
    let edges = graph
        .edges()
        .into_iter()
        .filter(|edge| selected.contains(&edge.source) && selected.contains(&edge.target))
        .collect::<Vec<_>>();
    Ok(json!({
        "authority": "typed_graph",
        "instruction": "Treat these reviewed typed nodes and relations as the durable living specification. Use working_memory only as advisory detail and submit semantic corrections through the configured graph mutation contract.",
        "root_node_ids": roots,
        "anchor_node_ids": anchors,
        "nodes": nodes,
        "edges": edges,
        "limits": {"max_depth": max_depth, "max_nodes": max_nodes},
        "truncated": selected.len() >= max_nodes && graph.nodes().count() > selected.len(),
    }))
}

fn scoped_graph_neighborhood(
    graph: &Graph,
    anchors: &[String],
    relations: &BTreeSet<String>,
    direction: &str,
    max_depth: usize,
    max_nodes: usize,
) -> Result<BTreeSet<String>> {
    if !matches!(direction, "outgoing" | "incoming" | "both") {
        return Err(KoniError::Action(format!(
            "unsupported graph traversal direction {direction}"
        )));
    }
    if anchors.len() > max_nodes {
        return Err(KoniError::Action(format!(
            "graph query has {} anchors, above its {max_nodes}-node result bound",
            anchors.len()
        )));
    }
    let edges = graph.edges();
    let mut selected = BTreeSet::new();
    let mut queue = VecDeque::new();
    for anchor in anchors {
        if graph.node(anchor).is_none() {
            return Err(KoniError::Action(format!(
                "graph query anchor {anchor} does not exist"
            )));
        }
        if selected.insert(anchor.clone()) {
            queue.push_back((anchor.clone(), 0usize));
        }
    }
    while let Some((current, depth)) = queue.pop_front() {
        if depth >= max_depth || selected.len() >= max_nodes {
            continue;
        }
        let mut neighbors = BTreeSet::new();
        for edge in &edges {
            if !relations.is_empty() && !relations.contains(&edge.relation) {
                continue;
            }
            if matches!(direction, "outgoing" | "both") && edge.source == current {
                neighbors.insert(edge.target.clone());
            }
            if matches!(direction, "incoming" | "both") && edge.target == current {
                neighbors.insert(edge.source.clone());
            }
        }
        for neighbor in neighbors {
            if selected.len() >= max_nodes {
                break;
            }
            if selected.insert(neighbor.clone()) {
                queue.push_back((neighbor, depth + 1));
            }
        }
    }
    Ok(selected)
}

fn bounded_graph_working_memory(
    control: &RunControlStore,
    profile: &CompiledProfile,
    graph: &Graph,
    node_ids: &BTreeSet<String>,
    max_bytes: usize,
) -> Result<Value> {
    let all_candidates = control
        .graph_notes()?
        .into_iter()
        .filter(|note| node_ids.contains(&note.node_id))
        .collect::<Vec<_>>();
    let superseded_ids = all_candidates
        .iter()
        .filter_map(|note| note.supersedes.clone())
        .collect::<BTreeSet<_>>();
    let retired_count = all_candidates
        .iter()
        .filter(|note| {
            matches!(
                note.state,
                GraphNoteState::Superseded | GraphNoteState::Invalidated
            ) || superseded_ids.contains(&note.id)
        })
        .count();
    let mut candidates = all_candidates
        .iter()
        .filter(|note| {
            matches!(
                note.state,
                GraphNoteState::Working | GraphNoteState::Confirmed
            ) && !superseded_ids.contains(&note.id)
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|left, right| {
        right
            .source
            .recorded_at
            .cmp(&left.source.recorded_at)
            .then_with(|| right.id.cmp(&left.id))
    });
    let mut notes = Vec::new();
    let mut used_bytes = 0usize;
    for note in candidates {
        let current_node_hash = graph.node(&note.node_id).map(|node| {
            profile.node_types.get(&node.node_type).map_or_else(
                || normalized_hash(node),
                |definition| {
                    semantic_receipt_node_hash(
                        node,
                        &definition.semantic_fields,
                        &definition.compiler_owned_fields,
                    )
                },
            )
        });
        let binding_status = match (
            note.source.node_hash.as_deref(),
            current_node_hash.as_deref(),
        ) {
            (Some(recorded), Some(current)) if recorded == current => "current",
            (Some(_), Some(_)) => "stale_node_revision",
            (Some(_), None) => "node_missing",
            (None, _) => "unbound_legacy",
        };
        let value = json!({
            "authority": "advisory",
            "binding": {
                "status": binding_status,
                "current_node_hash": current_node_hash,
            },
            "note": note,
        });
        let bytes = serde_json::to_vec(&value)
            .expect("validated graph knowledge notes serialize")
            .len();
        if used_bytes.saturating_add(bytes) > max_bytes {
            continue;
        }
        used_bytes += bytes;
        notes.push(value);
    }
    Ok(json!({
        "authority": "advisory_non_authoritative",
        "instruction": "These graph-bound notes preserve agent observations and decision rationale across tickets. Verify them against the typed graph and repository before acting; only reviewed graph mutations or scoped user steering change project intent.",
        "notes": notes,
        "included_count": notes.len(),
        "omitted_count": all_candidates.len().saturating_sub(notes.len()),
        "retired_count": retired_count,
        "included_bytes": used_bytes,
        "max_bytes": max_bytes,
    }))
}

fn compact_graph_delta_for_context(delta: &Value) -> Value {
    let Some(object) = delta.as_object() else {
        return delta.clone();
    };
    let mut compact = Map::new();
    for (field, value) in object {
        let node_entries = matches!(
            field.as_str(),
            "upsert" | "add_nodes" | "added_nodes" | "nodes" | "update_nodes" | "updated_nodes"
        );
        if node_entries {
            let Some(entries) = value.as_array() else {
                compact.insert(field.clone(), value.clone());
                continue;
            };
            compact.insert(
                field.clone(),
                Value::Array(
                    entries
                        .iter()
                        .map(|entry| {
                            json!({
                                "id": entry.get("id"),
                                "type": entry.get("type"),
                                "title": entry.get("title"),
                                "spec_fields": entry
                                    .get("spec")
                                    .and_then(Value::as_object)
                                    .map(|spec| spec.keys().cloned().collect::<Vec<_>>())
                                    .unwrap_or_default(),
                                "edge_relations": entry
                                    .get("edges")
                                    .and_then(Value::as_object)
                                    .map(|edges| edges.keys().cloned().collect::<Vec<_>>())
                                    .unwrap_or_default(),
                            })
                        })
                        .collect(),
                ),
            );
        } else {
            compact.insert(field.clone(), value.clone());
        }
    }
    compact.insert(
        "materialized_in_graph_closure".to_owned(),
        Value::Bool(true),
    );
    Value::Object(compact)
}

fn model_facing_step_output(output: &crate::state::StepOutput) -> Value {
    let mut value = serde_json::to_value(output).expect("step output serializes");
    if let Some(delta) = value.pointer_mut("/typed/graph_delta") {
        *delta = compact_graph_delta_for_context(delta);
    }
    value
}

/// A formal reviewer must see the semantic values and relationship targets
/// authored by the direct predecessor it is accepting or rejecting. Worker
/// dependency contexts can compact already-materialized graph deltas because
/// they also receive the graph closure; the review packet intentionally does
/// not expose arbitrary compiler-state discovery, and its graph closure may
/// still represent the pre-transition target scope. Compacting here would
/// therefore ask the reviewer to judge field names instead of evidence.
fn model_facing_review_step_output(output: &crate::state::StepOutput) -> Value {
    serde_json::to_value(output).expect("step output serializes")
}

/// Exact dependency identities are derived from the current ticket rather
/// than accepted from agent-authored prose. Structured-output receipts created
/// by newer compilers carry an explicit output binding; legacy receipts are
/// paired by the latest receipt for the exact dependency step so in-flight
/// runs can cross the upgrade boundary without losing provenance.
fn canonical_dependency_causal_receipts(
    ticket: &Ticket,
    step: &Step,
    receipts: &[Value],
) -> Result<Vec<String>> {
    let mut pointers = Vec::new();
    for dependency in &step.depends_on {
        let output = ticket
            .outputs
            .iter()
            .find(|output| output.step_id == *dependency)
            .ok_or_else(|| {
                KoniError::Workflow(format!(
                    "integration step {} has no current output for dependency {dependency}",
                    step.id
                ))
            })?;
        let output_hash = normalized_hash(output);
        pointers.push(format!("output:{}@{}", output.id, output_hash));

        let mut candidates = receipts
            .iter()
            .filter(|receipt| {
                receipt
                    .get("receipt_type")
                    .or_else(|| receipt.get("type"))
                    .and_then(Value::as_str)
                    == Some("structured-output")
                    && review_receipt_step(receipt) == Some(dependency.as_str())
                    && receipt.get("ticket_id").and_then(Value::as_str) == Some(ticket.id.as_str())
            })
            .collect::<Vec<_>>();
        let has_explicit_bindings = candidates
            .iter()
            .any(|receipt| receipt.get("output_id").is_some());
        if has_explicit_bindings {
            candidates.retain(|receipt| {
                receipt.get("output_id").and_then(Value::as_str) == Some(output.id.as_str())
                    && receipt.get("output_hash").and_then(Value::as_str)
                        == Some(output_hash.as_str())
            });
        }
        if let Some(receipt) = candidates
            .into_iter()
            .max_by_key(|receipt| review_receipt_order_key(receipt))
        {
            pointers.push(format!(
                "receipt:{}@{}",
                receipt
                    .get("id")
                    .and_then(Value::as_str)
                    .unwrap_or("unknown"),
                normalized_hash(receipt)
            ));
        }
    }
    Ok(pointers)
}

fn reconcile_compiler_owned_causal_receipts(
    ticket: &mut Ticket,
    receipts: &[Value],
) -> Result<bool> {
    let mut changed = false;
    for step in ticket
        .workflow
        .iter()
        .filter(|step| step.kind == StepKind::Integration && !step.depends_on.is_empty())
        .cloned()
        .collect::<Vec<_>>()
    {
        let Some(output_index) = ticket
            .outputs
            .iter()
            .position(|output| output.step_id == step.id)
        else {
            continue;
        };
        let canonical = json!(canonical_dependency_causal_receipts(
            ticket, &step, receipts
        )?);
        if ticket.outputs[output_index].typed.get("causal_receipts") != Some(&canonical) {
            ticket.outputs[output_index]
                .typed
                .insert("causal_receipts".to_owned(), canonical);
            changed = true;
        }
    }
    Ok(changed)
}

/// Build the exact review-time view of compiler-owned dependency provenance
/// without mutating the durable StepOutput that its scoped-compile receipt
/// authenticates. New outputs already contain these values at publication;
/// this projection is the compatibility path for outputs created by an older
/// compiler or copied from superseded review prose.
fn compiler_owned_causal_receipt_projection(ticket: &Ticket, receipts: &[Value]) -> Result<Ticket> {
    let mut projected = ticket.clone();
    reconcile_compiler_owned_causal_receipts(&mut projected, receipts)?;
    Ok(projected)
}

/// Bind the deterministic compatibility projection independently from the
/// immutable output hash. This preserves the original compile proof while
/// making a dependency change invalidate any earlier reviewer authorization.
fn compiler_owned_causal_binding_hash(source: &Ticket, projected: &Ticket) -> String {
    let bindings = projected
        .workflow
        .iter()
        .filter(|step| step.kind == StepKind::Integration && !step.depends_on.is_empty())
        .filter_map(|step| {
            let output = projected
                .outputs
                .iter()
                .find(|output| output.step_id == step.id)?;
            let source_output = source
                .outputs
                .iter()
                .find(|candidate| candidate.id == output.id)?;
            Some(json!({
                "step_id": step.id,
                "output_id": output.id,
                "source_output_hash": normalized_hash(source_output),
                "causal_receipts": output.typed.get("causal_receipts"),
            }))
        })
        .collect::<Vec<_>>();
    normalized_hash(&json!({
        "schema_version": "1.0",
        "ticket_id": source.id,
        "bindings": bindings,
    }))
}

fn model_facing_operation_acceptance(
    profile: &CompiledProfile,
    ticket: &Ticket,
    fallback_review_contract: Option<&str>,
) -> Value {
    let operation_registry_id = ticket
        .extensions
        .get("operation_registry_id")
        .and_then(Value::as_str);
    let operation = operation_registry_id.and_then(|id| profile.operations.get(id));
    let workflow = operation
        .and_then(|operation| operation.workflow.as_deref())
        .and_then(|id| profile.workflows.get(id));
    json!({
        "pointer": "packet://review/operation-acceptance",
        "registry_id": operation_registry_id,
        "operation": operation.map(|operation| operation.operation.as_str()).unwrap_or(ticket.operation.as_str()),
        "stage": operation.map(|operation| operation.stage.as_str()),
        "review_contract": operation
            .map(|operation| operation.review_contract.as_str())
            .or(fallback_review_contract),
        "output_contract": operation.map(|operation| operation.output_contract.as_str()),
        "gate_blocking_exempt": operation.is_some_and(|operation| operation.gate_blocking_exempt),
        "allowed_new_node_types": operation.map(|operation| &operation.allowed_new_node_types),
        "allowed_existing_node_types": operation.map(|operation| &operation.allowed_existing_node_types),
        "workflow": workflow.map(|workflow| json!({
            "id": workflow.id,
            "review_failure_reopen_from": workflow.review_failure_reopen_from,
            "review_failure_routes": workflow.review_failure_routes,
            "steps": workflow.steps.iter().map(|step| json!({
                "id": step.id,
                "kind": step.kind,
                "persona": step.persona,
                "depends_on": step.depends_on,
                "expected_output": step.expected_output,
                "graph_mutation": step.graph_mutation,
                "required_receipts": step.required_receipts,
                "escalation_triggers": step.escalation_triggers,
                "stop_conditions": step.stop_conditions,
            })).collect::<Vec<_>>(),
        })),
        "interpretation": if operation.is_some_and(|operation| operation.gate_blocking_exempt) {
            "Unresolved or expected-red gates do not block this operation. Review the configured output contract at this boundary; do not require downstream assets, executions, or passing gate receipts when a workflow stop condition excludes them."
        } else {
            "Apply the configured review and output contracts at this exact workflow boundary."
        },
    })
}

#[allow(clippy::too_many_arguments)]
fn model_facing_review_evidence_packet(
    profile: &CompiledProfile,
    ticket: &Ticket,
    review_ticket: &Ticket,
    graph: &Graph,
    receipts: &[Value],
    review_step: &Step,
    review_contract: &str,
    expected_output: &str,
    review_input_hash: &str,
    graph_hash: &str,
    checkout_root: Option<&Path>,
) -> Value {
    let review_subject_steps = review_step
        .depends_on
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let all_current_outputs =
        model_facing_current_ticket_outputs_with_projection(ticket, review_ticket);
    let current_outputs = if review_subject_steps.is_empty() {
        all_current_outputs
    } else {
        all_current_outputs
            .into_iter()
            .filter(|output| {
                output
                    .get("step_id")
                    .and_then(Value::as_str)
                    .is_some_and(|step_id| review_subject_steps.contains(step_id))
            })
            .collect::<Vec<_>>()
    };
    let operation_acceptance =
        model_facing_operation_acceptance(profile, ticket, Some(review_contract));
    let include_operational_state =
        operation_acceptance["gate_blocking_exempt"].as_bool() != Some(true);
    // Keep the complete non-review receipt set in the cryptographic binding,
    // but project only binding-relevant current receipts into the model-facing
    // packet. Audit history remains durable without making every retry
    // permanently increase reviewer context and its evidence-pointer enum.
    let review_input_receipts = receipts
        .iter()
        .filter(|receipt| {
            !matches!(
                receipt.get("receipt_type").and_then(Value::as_str),
                Some("review.receipt" | "review-receipt")
            )
        })
        .cloned()
        .collect::<Vec<_>>();
    let receipt_proofs = model_facing_current_review_receipts(ticket, &review_input_receipts)
        .iter()
        .map(model_facing_review_receipt)
        .collect::<Vec<_>>();

    let mut scoped_node_ids = ticket.target_nodes.iter().cloned().collect::<BTreeSet<_>>();
    scoped_node_ids.extend(ticket.scope.read_nodes.iter().cloned());
    scoped_node_ids.extend(ticket.scope.write_nodes.iter().cloned());
    let mut operational_node_ids = ticket.target_nodes.iter().cloned().collect::<BTreeSet<_>>();
    operational_node_ids.extend(ticket.scope.write_nodes.iter().cloned());
    let relevant_obligation_keys = ticket
        .obligation_keys
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    let current_nodes = scoped_node_ids
        .iter()
        .filter_map(|node_id| graph.node(node_id))
        .map(|node| {
            model_facing_review_node(
                profile,
                node,
                include_operational_state && operational_node_ids.contains(&node.id),
                Some(&relevant_obligation_keys),
            )
        })
        .collect::<Vec<_>>();

    let mut inspectable_product_paths = BTreeSet::new();
    inspectable_product_paths.extend(
        ticket
            .scope
            .read_paths
            .iter()
            .chain(&ticket.scope.write_paths)
            .filter(|path| review_product_path_allowed(path))
            .cloned(),
    );
    for output in &ticket.outputs {
        inspectable_product_paths.extend(
            output
                .files_read
                .iter()
                .chain(&output.files_written)
                .chain(&output.files_deleted)
                .filter(|path| review_product_path_allowed(path))
                .cloned(),
        );
    }
    let mut unavailable_product_paths = Vec::new();
    if let Some(checkout_root) = checkout_root {
        let canonical_root = checkout_root.canonicalize().ok();
        let candidates = std::mem::take(&mut inspectable_product_paths);
        for path in candidates {
            let candidate = checkout_root.join(&path);
            let metadata = fs::symlink_metadata(&candidate).ok();
            let current_regular_file = metadata
                .as_ref()
                .is_some_and(|metadata| metadata.file_type().is_file())
                && canonical_root.as_ref().is_some_and(|canonical_root| {
                    candidate
                        .canonicalize()
                        .is_ok_and(|candidate| candidate.starts_with(canonical_root))
                });
            if !current_regular_file {
                unavailable_product_paths.push(json!({
                    "path": path,
                    "availability": "not_current_regular_file",
                    "interpretation": "This scoped path is not a current regular file in the ticket checkout. It is not a readable capability or evidence pointer."
                }));
                continue;
            }
            let size_bytes = metadata.expect("current regular file has metadata").len();
            if size_bytes > MAX_READ_ONLY_PROJECT_FILE_BYTES {
                unavailable_product_paths.push(json!({
                    "path": path,
                    "availability": "exceeds_read_limit",
                    "size_bytes": size_bytes,
                    "limit_bytes": MAX_READ_ONLY_PROJECT_FILE_BYTES,
                    "interpretation": "This scoped file exceeds the bounded review read limit. It is not a readable capability or evidence pointer; review it through smaller compiler-provided evidence or a separately scoped artifact."
                }));
                continue;
            }
            inspectable_product_paths.insert(path);
        }
    }

    let prior_failed_review = ticket
        .reviews
        .iter()
        .rev()
        .find(|review| review.status == "failed")
        .map(|review| {
            json!({
                "pointer": format!("review:{}", review.id),
                "status": review.status,
                "notes": review.notes,
                "reviewed_at": review.reviewed_at,
                "output_hash": review.output_hash,
            })
        });
    let review_rework_corrections = ticket
        .extensions
        .get(REVIEW_REWORK_SUPERSESSIONS_EXTENSION)
        .and_then(Value::as_array)
        .filter(|history| !history.is_empty())
        .map(|history| {
            json!({
                "pointer": "packet://review/rework-correction",
                "history": history,
                "interpretation": "These compiler-bound ticket-scoped corrections superseded earlier passed reviews. Assess the replacement output against every still-applicable correction; do not reuse the historical pass as acceptance evidence."
            })
        });
    let mut evidence_pointers = vec![
        Value::String("packet://review/acceptance".to_owned()),
        Value::String("packet://review/operation-acceptance".to_owned()),
    ];
    if review_rework_corrections.is_some() {
        evidence_pointers.push(Value::String(
            "packet://review/rework-correction".to_owned(),
        ));
    }
    evidence_pointers.extend(
        current_nodes
            .iter()
            .filter_map(|node| node.get("pointer").cloned())
            .chain(
                current_outputs
                    .iter()
                    .filter_map(|output| output.get("pointer").cloned()),
            )
            .chain(
                receipt_proofs
                    .iter()
                    .filter_map(|receipt| receipt.get("pointer").cloned()),
            ),
    );
    evidence_pointers.extend(inspectable_product_paths.iter().cloned().map(Value::String));

    let mut packet = json!({
        "schema_version": "1.0",
        "kind": "compiler-bound-review-evidence",
        "binding": {
            "profile_hash": profile.hash,
            "ticket_hash": normalized_hash(ticket),
            "output_hash": normalized_hash(&ticket.outputs),
            "causal_binding_hash": compiler_owned_causal_binding_hash(ticket, review_ticket),
            "receipt_hash": normalized_hash(&review_input_receipts),
            "graph_hash": graph_hash,
            "review_input_hash": review_input_hash,
        },
        "review_contract": {
            "pointer": "packet://review/acceptance",
            "text": review_contract,
            "expected_output": expected_output,
            "step": {
                "id": review_step.id,
                "persona": review_step.persona,
                "depends_on": review_step.depends_on,
                "expected_outputs": review_step.expected_outputs,
                "required_receipts": review_step.required_receipts,
                "validation_checks": review_step.validation_checks,
                "escalation_triggers": review_step.escalation_triggers,
                "stop_conditions": review_step.stop_conditions,
                "context_hash": review_step.context_hash,
            },
        },
        "review_subject": {
            "direct_predecessor_steps": review_step.depends_on,
            "interpretation": "current_step_outputs contains the direct predecessor output(s) this review accepts or rejects. Earlier workflow outputs are causal inputs; when an integration step explicitly resolves a conflict among them, its coherent synthesis is authoritative at this boundary."
        },
        "operation_acceptance": operation_acceptance,
        "ticket": {
            "id": ticket.id,
            "title": ticket.title,
            "operation": ticket.operation,
            "status": ticket.status,
            "source_state_key": ticket.source_state_key,
            "target_state_key": ticket.target_state_key,
            "obligation_keys": ticket.obligation_keys,
            "target_nodes": ticket.target_nodes,
            "scope": ticket.scope,
            "blockers": ticket.blockers,
            "change_control": ticket.change_control,
        },
        "current_nodes": current_nodes,
        "current_step_outputs": current_outputs,
        "receipt_proofs": receipt_proofs,
        "prior_failed_review": prior_failed_review,
        "inspectable_product_paths": inspectable_product_paths,
        "unavailable_product_paths": unavailable_product_paths,
        "valid_evidence_pointers": evidence_pointers,
        "inspection_policy": {
            "compiler_state_is_embedded": true,
            "repository_discovery_allowed": false,
            "control_plane_file_reads_allowed": false,
            "product_reads_must_be_allowlisted": true,
            "operational_state_projection": if include_operational_state {
                "Only target/write nodes and obligations owned by this ticket are review-blocking; read-only neighbor lifecycle state belongs to its own compiler work."
            } else {
                "This operation is gate-blocking exempt, so node operational state is omitted."
            },
            "output_projection": "Only direct review-predecessor outputs are model-facing; all current workflow outputs remain cryptographically bound in binding.output_hash.",
        },
    });
    if let Some(review_rework_corrections) = review_rework_corrections {
        packet
            .as_object_mut()
            .expect("review evidence packet is an object")
            .insert(
                "review_rework_corrections".to_owned(),
                review_rework_corrections,
            );
    }
    let packet_hash = normalized_hash(&packet);
    packet
        .as_object_mut()
        .expect("review evidence packet is an object")
        .insert("packet_hash".to_owned(), Value::String(packet_hash));
    packet
}

fn model_facing_current_review_receipts<'a>(
    ticket: &Ticket,
    receipts: &'a [Value],
) -> Vec<&'a Value> {
    let current_contexts = ticket
        .workflow
        .iter()
        .filter(|step| step.kind != StepKind::Review)
        .map(|step| (step.id.as_str(), step.context_hash.as_str()))
        .collect::<BTreeMap<_, _>>();
    let current_output_steps = ticket
        .outputs
        .iter()
        .filter(|output| {
            current_contexts
                .get(output.step_id.as_str())
                .is_some_and(|context_hash| *context_hash == output.context_hash.as_str())
        })
        .map(|output| output.step_id.as_str())
        .collect::<BTreeSet<_>>();
    let current_output_hash = normalized_hash(&ticket.outputs);

    let mut current_context_packs = BTreeMap::<String, &'a Value>::new();
    let mut current_output_receipts = BTreeMap::<String, &'a Value>::new();
    let mut current_scoped_compile = BTreeMap::<String, &'a Value>::new();
    let mut current_scoped_checks = BTreeMap::<String, &'a Value>::new();
    let mut passthrough = Vec::new();

    for receipt in receipts {
        if review_receipt_explicitly_stale(receipt) {
            continue;
        }
        let receipt_type = receipt
            .get("receipt_type")
            .or_else(|| receipt.get("type"))
            .and_then(Value::as_str)
            .unwrap_or_default();
        match receipt_type {
            "context-pack" => {
                let Some(step_id) = review_receipt_step(receipt) else {
                    continue;
                };
                let Some(expected_context) = current_contexts.get(step_id) else {
                    continue;
                };
                if receipt.get("context_hash").and_then(Value::as_str) != Some(*expected_context) {
                    continue;
                }
                insert_latest_review_receipt(
                    &mut current_context_packs,
                    step_id.to_owned(),
                    receipt,
                );
            }
            "structured-output" => {
                let Some(step_id) = review_receipt_step(receipt) else {
                    continue;
                };
                if !current_output_steps.contains(step_id) {
                    continue;
                }
                insert_latest_review_receipt(
                    &mut current_output_receipts,
                    step_id.to_owned(),
                    receipt,
                );
            }
            "scoped-compile" => {
                if receipt.get("status").and_then(Value::as_str) != Some("passed")
                    || receipt.get("output_hash").and_then(Value::as_str)
                        != Some(current_output_hash.as_str())
                {
                    continue;
                }
                insert_latest_review_receipt(
                    &mut current_scoped_compile,
                    "scoped-compile".to_owned(),
                    receipt,
                );
            }
            "compiler.scoped-probe" | "scoped-operational-probe" => {
                let key = receipt
                    .get("check_id")
                    .and_then(Value::as_str)
                    .unwrap_or(receipt_type)
                    .to_owned();
                insert_latest_review_receipt(&mut current_scoped_checks, key, receipt);
            }
            _ => passthrough.push(receipt),
        }
    }

    let mut selected = passthrough;
    selected.extend(current_context_packs.into_values());
    selected.extend(current_output_receipts.into_values());
    selected.extend(current_scoped_compile.into_values());
    selected.extend(current_scoped_checks.into_values());
    selected.sort_by_key(|receipt| {
        (
            receipt
                .get("receipt_type")
                .or_else(|| receipt.get("type"))
                .and_then(Value::as_str)
                .unwrap_or_default()
                .to_owned(),
            review_receipt_step(receipt).unwrap_or_default().to_owned(),
            review_receipt_order_key(receipt),
        )
    });
    selected
}

fn review_receipt_step(receipt: &Value) -> Option<&str> {
    receipt
        .get("step_id")
        .or_else(|| receipt.get("step"))
        .and_then(Value::as_str)
}

fn review_receipt_explicitly_stale(receipt: &Value) -> bool {
    if receipt
        .get("_historical_evidence_valid")
        .and_then(Value::as_bool)
        == Some(true)
    {
        return false;
    }
    ["_command_current", "_input_current", "_current"]
        .into_iter()
        .any(|field| receipt.get(field).and_then(Value::as_bool) == Some(false))
}

fn review_receipt_order_key(receipt: &Value) -> (String, String) {
    (
        receipt
            .get("recorded_at")
            .or_else(|| receipt.get("finished_at"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        receipt
            .get("id")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned(),
    )
}

fn insert_latest_review_receipt<'a>(
    selected: &mut BTreeMap<String, &'a Value>,
    key: String,
    candidate: &'a Value,
) {
    let replace = selected.get(&key).is_none_or(|current| {
        review_receipt_order_key(candidate) > review_receipt_order_key(current)
    });
    if replace {
        selected.insert(key, candidate);
    }
}

fn model_facing_current_ticket_outputs_with_projection(
    ticket: &Ticket,
    projected: &Ticket,
) -> Vec<Value> {
    let mut latest_by_step = BTreeMap::<&str, &crate::state::StepOutput>::new();
    for output in &ticket.outputs {
        let current = ticket
            .workflow
            .iter()
            .find(|step| step.id == output.step_id)
            .is_some_and(|step| step.context_hash == output.context_hash);
        if current {
            latest_by_step.insert(output.step_id.as_str(), output);
        }
    }
    ticket
        .workflow
        .iter()
        .filter_map(|step| latest_by_step.get(step.id.as_str()).copied())
        .map(|source_output| {
            let output = projected
                .outputs
                .iter()
                .find(|candidate| candidate.id == source_output.id)
                .unwrap_or(source_output);
            let mut value = model_facing_review_step_output(output);
            // The evidence pointer continues to authenticate the immutable
            // durable output and therefore agrees with its structured-output
            // and scoped-compile receipts. When a compatibility projection is
            // present, expose its own hash and exact compiler-owned field so
            // the reviewer can distinguish derived provenance from authored
            // output content.
            let source_output_hash = normalized_hash(source_output);
            let output_hash = normalized_hash(output);
            if let Some(object) = value.as_object_mut() {
                object.insert(
                    "pointer".to_owned(),
                    Value::String(format!(
                        "output:{}@{}",
                        source_output.id, source_output_hash
                    )),
                );
                object.insert(
                    "output_hash".to_owned(),
                    Value::String(source_output_hash.clone()),
                );
                if output_hash != source_output_hash {
                    object.insert(
                        "compiler_projection".to_owned(),
                        json!({
                            "fields": ["typed.causal_receipts"],
                            "projection_hash": output_hash,
                        }),
                    );
                }
                object.remove("patch_proposal");
                object.remove("recommended_next_step");
            }
            value
        })
        .collect()
}

fn model_facing_review_node(
    profile: &CompiledProfile,
    node: &Node,
    include_operational_state: bool,
    relevant_obligation_keys: Option<&BTreeSet<String>>,
) -> Value {
    let source = node.as_value();
    let node_type = profile.node_types.get(&node.node_type);
    let mut semantic = if node_type.is_some_and(|definition| definition.semantic_fields.is_empty())
    {
        json!({
            "schema_version": node.schema_version,
            "id": node.id,
            "type": node.node_type,
            "title": node.title,
            "spec": node.spec,
            "edges": node.edges,
        })
    } else {
        let mut projection = json!({});
        for field in node_type
            .into_iter()
            .flat_map(|definition| &definition.semantic_fields)
        {
            if let Some(value) = value_at_dotted_path(&source, field) {
                let _ = set_value_path(&mut projection, field, value.clone());
            }
        }
        projection
    };
    if let Some(definition) = node_type {
        for field in &definition.compiler_owned_fields {
            remove_value_path(&mut semantic, field);
        }
    }
    let operational_state =
        model_facing_review_operational_state(&source, relevant_obligation_keys);
    let semantic_hash = node_type.map_or_else(
        || normalized_hash(&semantic),
        |definition| {
            semantic_receipt_node_hash(
                node,
                &definition.semantic_fields,
                &definition.compiler_owned_fields,
            )
        },
    );
    let mut projected = json!({
        "pointer": format!("node:{}@{}", node.id, semantic_hash),
        "id": node.id,
        "type": node.node_type,
        "title": node.title,
        "semantic_hash": semantic_hash,
        "semantic_state": semantic,
    });
    if include_operational_state {
        projected["operational_state"] = Value::Object(operational_state);
    }
    projected
}

/// Keep review-time gate state bound to the operation that emitted the ticket.
///
/// A ticket can read neighboring nodes for semantic context without owning their lifecycle. A
/// reviewer seeing every unmet obligation on those neighbors can otherwise reject a valid local
/// transition for work already represented by a separate compiler ticket. When a ticket-specific
/// allowlist is supplied, retain its target status and only the obligations it actually owns;
/// readiness/gate projections accompany those relevant obligations rather than leaking unrelated
/// control-plane state into the model's acceptance boundary.
fn model_facing_review_operational_state(
    source: &Value,
    relevant_obligation_keys: Option<&BTreeSet<String>>,
) -> Map<String, Value> {
    let Some(relevant_obligation_keys) = relevant_obligation_keys else {
        return ["status", "readiness", "obligations", "gates", "gate_state"]
            .into_iter()
            .filter_map(|field| {
                source
                    .get(field)
                    .cloned()
                    .map(|value| (field.to_owned(), value))
            })
            .collect();
    };

    let mut operational_state = Map::new();
    if let Some(status) = source.get("status") {
        operational_state.insert("status".to_owned(), status.clone());
    }
    let relevant_unmet = source
        .get("obligations")
        .and_then(|obligations| obligations.get("unmet"))
        .and_then(Value::as_array)
        .map(|unmet| {
            unmet
                .iter()
                .filter(|obligation| {
                    obligation
                        .get("key")
                        .and_then(Value::as_str)
                        .is_some_and(|key| relevant_obligation_keys.contains(key))
                })
                .cloned()
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    if relevant_unmet.is_empty() {
        return operational_state;
    }
    operational_state.insert("obligations".to_owned(), json!({"unmet": relevant_unmet}));
    for field in ["readiness", "gates", "gate_state"] {
        if let Some(value) = source.get(field) {
            operational_state.insert(field.to_owned(), value.clone());
        }
    }
    operational_state
}

fn model_facing_review_receipt(receipt: &&Value) -> Value {
    let receipt = *receipt;
    let mut compact = Map::new();
    for field in [
        "id",
        "receipt_type",
        "type",
        "step",
        "step_id",
        "check_id",
        "status",
        "recorded_at",
        "finished_at",
        "duration_ms",
        "context_hash",
        "context_hashes",
        "profile_hash",
        "ticket_id",
        "receipt_hash",
        "input_hash",
        "output_id",
        "output_hash",
        "graph_hash",
        "scope_hashes",
        "target_hashes",
        "ticket_binding",
        "artifact_manifest",
        "execution_binding_hash",
        "input_binding_fingerprint",
        "input_bindings_unchanged",
        "execution_bindings_unchanged",
        "expected_exit_codes",
        "receipt_freshness",
        "_historical_evidence_valid",
        "_command_current",
        "_input_current",
        "_current",
    ] {
        if let Some(value) = receipt.get(field) {
            compact.insert(field.to_owned(), value.clone());
        }
    }
    if let Some(attempts) = receipt.get("attempts").and_then(Value::as_array) {
        compact.insert(
            "attempts".to_owned(),
            Value::Array(
                attempts
                    .iter()
                    .map(|attempt| {
                        let mut value = Map::new();
                        for field in [
                            "attempt",
                            "exit_code",
                            "timed_out",
                            "interrupted",
                            "duration_ms",
                            "stdout_hash",
                            "stderr_hash",
                        ] {
                            if let Some(field_value) = attempt.get(field) {
                                value.insert(field.to_owned(), field_value.clone());
                            }
                        }
                        for field in ["stdout", "stderr"] {
                            if let Some(text) = attempt.get(field).and_then(Value::as_str)
                                && !text.trim().is_empty()
                            {
                                value.insert(
                                    field.to_owned(),
                                    Value::String(truncate_review_evidence_text(text, 2_000)),
                                );
                            }
                        }
                        Value::Object(value)
                    })
                    .collect(),
            ),
        );
    }
    let bound_hash = normalized_hash(receipt);
    let pointer_kind = if receipt.get("check_id").is_some() {
        "check"
    } else {
        "receipt"
    };
    let pointer_id = receipt
        .get("check_id")
        .or_else(|| receipt.get("id"))
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    compact.insert(
        "pointer".to_owned(),
        Value::String(format!("{pointer_kind}:{pointer_id}@{bound_hash}")),
    );
    compact.insert("bound_hash".to_owned(), Value::String(bound_hash));
    Value::Object(compact)
}

fn truncate_review_evidence_text(value: &str, limit: usize) -> String {
    let mut output = value.chars().take(limit).collect::<String>();
    if value.chars().count() > limit {
        output.push('…');
    }
    output
}

fn review_product_path_allowed(path: &str) -> bool {
    let path = path.trim().trim_start_matches("./");
    if path.is_empty() || Path::new(path).is_absolute() {
        return false;
    }
    let first = path.split('/').next().unwrap_or_default();
    !matches!(first, ".git" | ".codex" | ".agents" | "program")
        && !Path::new(path)
            .components()
            .any(|component| matches!(component, std::path::Component::ParentDir))
}

fn context_dependency_node_types(
    profile: &CompiledProfile,
    graph: &Graph,
    outputs: &[crate::state::StepOutput],
) -> BTreeSet<String> {
    fn collect_declared_nodes(
        profile: &CompiledProfile,
        value: &Value,
        declared: &mut BTreeMap<String, String>,
    ) {
        match value {
            Value::Object(object) => {
                if let (Some(id), Some(node_type)) = (
                    object.get("id").and_then(Value::as_str),
                    object.get("type").and_then(Value::as_str),
                ) && profile.node_types.contains_key(node_type)
                {
                    declared.insert(id.to_owned(), node_type.to_owned());
                }
                for child in object.values() {
                    collect_declared_nodes(profile, child, declared);
                }
            }
            Value::Array(items) => {
                for child in items {
                    collect_declared_nodes(profile, child, declared);
                }
            }
            _ => {}
        }
    }

    fn collect_referenced_types(
        graph: &Graph,
        declared: &BTreeMap<String, String>,
        value: &Value,
        types: &mut BTreeSet<String>,
    ) {
        match value {
            Value::String(candidate) => {
                if let Some(node) = graph.node(candidate) {
                    types.insert(node.node_type.clone());
                } else if let Some(node_type) = declared.get(candidate) {
                    types.insert(node_type.clone());
                }
            }
            Value::Object(object) => {
                for child in object.values() {
                    collect_referenced_types(graph, declared, child, types);
                }
            }
            Value::Array(items) => {
                for child in items {
                    collect_referenced_types(graph, declared, child, types);
                }
            }
            _ => {}
        }
    }

    let mut declared = BTreeMap::new();
    for output in outputs {
        collect_declared_nodes(
            profile,
            &serde_json::to_value(output).expect("step output serializes"),
            &mut declared,
        );
    }
    let mut types = BTreeSet::new();
    for output in outputs {
        collect_referenced_types(
            graph,
            &declared,
            &serde_json::to_value(output).expect("step output serializes"),
            &mut types,
        );
    }
    types
}

/// Select the semantic policy contracts an agent needs to interpret the graph
/// contract it received. A policy enters through one of its declared graph
/// roles or through an edge predicate, then brings along policies referenced
/// by its selectors (including references reached through named queries).
fn context_gate_contract_ids(
    profile: &CompiledProfile,
    node_type_ids: &BTreeSet<String>,
    edge_types: &[EdgeTypeDef],
) -> (BTreeSet<String>, BTreeSet<String>) {
    let mut selected = profile
        .gate_policies
        .iter()
        .filter(|(_, policy)| {
            policy
                .gate_node_types
                .iter()
                .chain(&policy.candidate_node_types)
                .chain(&policy.applicability.subject_node_types)
                .any(|node_type| node_type_ids.contains(node_type))
        })
        .map(|(id, _)| id.clone())
        .collect::<BTreeSet<_>>();
    let mut query_ids = BTreeSet::new();
    for predicate in edge_types.iter().filter_map(|edge| edge.when.as_ref()) {
        predicate.referenced_gate_policies(&mut selected);
        predicate.referenced_queries(&mut query_ids);
    }
    collect_query_gate_policy_references(profile, &mut query_ids, &mut selected);

    let mut expanded = BTreeSet::new();
    loop {
        let pending = selected.difference(&expanded).cloned().collect::<Vec<_>>();
        if pending.is_empty() {
            break;
        }
        for policy_id in pending {
            expanded.insert(policy_id.clone());
            let Some(policy) = profile.gate_policies.get(&policy_id) else {
                continue;
            };
            let mut selectors = vec![
                &policy.gate_subjects,
                &policy.candidate_pool,
                &policy.evaluation_targets.select,
                &policy.applicability.direct_gates,
                &policy.applicability.inherited_gates,
                &policy.applicability.context,
            ];
            selectors.extend(policy.applicability.context_classes.values());
            if let Some(context) = &policy.context {
                selectors.push(&context.select);
            }
            let mut policy_queries = BTreeSet::new();
            for selector in selectors {
                selector.referenced_gate_policies(&mut selected);
                selector.referenced_queries(&mut policy_queries);
            }
            collect_query_gate_policy_references(profile, &mut policy_queries, &mut selected);
            query_ids.extend(policy_queries);
        }
    }
    (selected, query_ids)
}

fn collect_query_gate_policy_references(
    profile: &CompiledProfile,
    pending: &mut BTreeSet<String>,
    policies: &mut BTreeSet<String>,
) {
    let mut expanded = BTreeSet::new();
    loop {
        let query_ids = pending.difference(&expanded).cloned().collect::<Vec<_>>();
        if query_ids.is_empty() {
            break;
        }
        for query_id in query_ids {
            expanded.insert(query_id.clone());
            let Some(query) = profile.queries.get(&query_id) else {
                continue;
            };
            if let Some(selector) = &query.select {
                selector.referenced_gate_policies(policies);
                selector.referenced_queries(pending);
            }
            if let Some(traverse) = &query.traverse {
                traverse.from.referenced_gate_policies(policies);
                traverse.from.referenced_queries(pending);
            }
            if let Some(predicate) = &query.predicate {
                predicate.referenced_gate_policies(policies);
                predicate.referenced_queries(pending);
            }
        }
    }
}

fn render_git_template(template: &str, run: &RunManifest, ticket: &Ticket) -> String {
    template
        .replace("{{ run.id }}", &run.id)
        .replace("{{ ticket.id }}", &ticket.id)
        .replace("{{ ticket.operation }}", &ticket.operation)
        .replace("{{ ticket.title }}", &ticket.title)
}

fn render_commit_value(
    template: &str,
    run: &RunManifest,
    ticket: &Ticket,
    profile_hash: &str,
) -> String {
    let review_id = ticket
        .reviews
        .last()
        .map(|review| review.id.as_str())
        .unwrap_or_default();
    render_git_template(template, run, ticket)
        .replace("{{ profile.hash }}", profile_hash)
        .replace("{{ review.id }}", review_id)
}

fn derive_filesystem_manifest(
    node: &Node,
    definition: &FilesystemManifestDef,
    project_root: &Path,
    accept_changes: bool,
) -> Value {
    let mut errors = BTreeSet::new();
    let root_value = node
        .field_owned(&definition.root_field)
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .filter(|value| !value.trim().is_empty());
    let normalized_root =
        root_value
            .as_deref()
            .and_then(|raw| match normalized_relative_filesystem_path(raw) {
                Ok(path) => Some(path),
                Err(error) => {
                    errors.insert(format!("filesystem root {error}: {raw}"));
                    None
                }
            });
    if root_value.is_none() {
        errors.insert(format!(
            "{} must be a nonempty project-relative path",
            definition.root_field
        ));
    }
    if let Some(root) = &normalized_root
        && !definition.allowed_root_prefixes.is_empty()
        && !definition.allowed_root_prefixes.iter().any(|prefix| {
            normalized_relative_filesystem_path(prefix).is_ok_and(|prefix| root.starts_with(prefix))
        })
    {
        errors.insert(format!(
            "filesystem root {} is outside configured root prefixes",
            path_text(root)
        ));
    }

    let project_canonical = match project_root.canonicalize() {
        Ok(root) if root.is_dir() => Some(root),
        _ => {
            errors.insert("project root cannot be resolved as a directory".to_owned());
            None
        }
    };
    let mut canonical_root = None;
    let mut file_rows = Vec::new();
    if let (Some(root), Some(project_canonical)) = (&normalized_root, project_canonical.as_ref()) {
        let concrete = project_root.join(root);
        if definition.scan.symlinks == FilesystemSymlinkPolicy::Reject
            && filesystem_path_contains_symlink(project_root, root)
        {
            errors.insert(format!(
                "filesystem root or one of its parents must not be a symlink: {}",
                path_text(root)
            ));
        } else {
            match fs::symlink_metadata(&concrete) {
                Err(_) => {
                    errors.insert(format!(
                        "filesystem root does not exist: {}",
                        path_text(root)
                    ));
                }
                Ok(_) => match concrete.canonicalize() {
                    Err(_) => {
                        errors.insert(format!(
                            "filesystem root cannot be resolved: {}",
                            path_text(root)
                        ));
                    }
                    Ok(resolved)
                        if !resolved.starts_with(project_canonical) || !resolved.is_dir() =>
                    {
                        errors.insert(format!(
                            "filesystem root escapes the project or is not a directory: {}",
                            path_text(root)
                        ));
                    }
                    Ok(root_resolved) => {
                        let mut allowed_boundary = definition.allowed_root_prefixes.is_empty();
                        for prefix in &definition.allowed_root_prefixes {
                            let Ok(prefix) = normalized_relative_filesystem_path(prefix) else {
                                continue;
                            };
                            match project_root.join(&prefix).canonicalize() {
                                Ok(boundary)
                                    if boundary.starts_with(project_canonical)
                                        && boundary.is_dir()
                                        && root_resolved.starts_with(&boundary) =>
                                {
                                    allowed_boundary = true;
                                }
                                Ok(_) => {}
                                Err(_) => {
                                    errors.insert(format!(
                                        "configured filesystem root prefix cannot be resolved: {}",
                                        path_text(&prefix)
                                    ));
                                }
                            }
                        }
                        if !allowed_boundary {
                            errors.insert(format!(
                                "filesystem root resolves outside configured root prefixes: {}",
                                path_text(root)
                            ));
                        } else {
                            canonical_root = Some(root_resolved.clone());
                            let walker = WalkDir::new(&concrete)
                                .follow_links(
                                    definition.scan.symlinks == FilesystemSymlinkPolicy::Contained,
                                )
                                .sort_by_file_name();
                            for entry in walker {
                                let entry = match entry {
                                    Ok(entry) => entry,
                                    Err(error) => {
                                        errors
                                            .insert(format!("filesystem inventory error: {error}"));
                                        continue;
                                    }
                                };
                                if entry.path() == concrete {
                                    continue;
                                }
                                let Ok(relative_to_root) = entry.path().strip_prefix(&concrete)
                                else {
                                    errors.insert(
                                        "filesystem inventory produced an escaped path".to_owned(),
                                    );
                                    continue;
                                };
                                if filesystem_manifest_path_is_ignored(relative_to_root, definition)
                                {
                                    continue;
                                }
                                let symlink = fs::symlink_metadata(entry.path())
                                    .is_ok_and(|metadata| metadata.file_type().is_symlink());
                                if symlink
                                    && definition.scan.symlinks == FilesystemSymlinkPolicy::Reject
                                {
                                    errors.insert(format!(
                                        "filesystem inventory rejects symlink: {}",
                                        path_text(&root.join(relative_to_root))
                                    ));
                                    continue;
                                }
                                if !entry.path().is_file() {
                                    continue;
                                }
                                match entry.path().canonicalize() {
                                    Ok(file_resolved)
                                        if file_resolved.starts_with(project_canonical)
                                            && file_resolved.starts_with(&root_resolved) => {}
                                    Ok(_) => {
                                        errors.insert(format!(
                                            "filesystem inventory path escapes configured root: {}",
                                            path_text(&root.join(relative_to_root))
                                        ));
                                        continue;
                                    }
                                    Err(_) => {
                                        errors.insert(format!(
                                            "filesystem inventory path cannot be resolved: {}",
                                            path_text(&root.join(relative_to_root))
                                        ));
                                        continue;
                                    }
                                }
                                let bytes = match fs::read(entry.path()) {
                                    Ok(bytes) => bytes,
                                    Err(_) => {
                                        errors.insert(format!(
                                            "filesystem inventory path cannot be read: {}",
                                            path_text(&root.join(relative_to_root))
                                        ));
                                        continue;
                                    }
                                };
                                let project_path = root.join(relative_to_root);
                                file_rows.push(json!({
                                    "path": path_text(&project_path),
                                    "bytes": bytes.len(),
                                    "sha256": raw_sha256(&bytes),
                                }));
                            }
                        }
                    }
                },
            }
        }
    }
    file_rows.sort_by(|left, right| {
        left["path"]
            .as_str()
            .unwrap_or_default()
            .cmp(right["path"].as_str().unwrap_or_default())
    });

    let contract = node.field_owned(&definition.implementation_contract_field);
    let contract_hash = contract
        .as_ref()
        .filter(|value| value.is_object())
        .map(normalized_hash);
    let bound_contract_fields = definition
        .contract_fields
        .iter()
        .map(|field| {
            (
                field.clone(),
                node.field_owned(field).unwrap_or(Value::Null),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let contract_fields_hash = normalized_hash(&bound_contract_fields);
    if contract.as_ref().is_none_or(|value| !value.is_object()) {
        errors.insert(format!(
            "{} must be a mapping",
            definition.implementation_contract_field
        ));
    }
    let kind = node
        .field_owned(&definition.implementation_kind_field)
        .and_then(|value| value.as_str().map(str::trim).map(ToOwned::to_owned))
        .filter(|value| !value.is_empty());
    if kind.is_none() {
        errors.insert(format!(
            "{} is required",
            definition.implementation_kind_field
        ));
    }
    let raw_entrypoints = node
        .field_owned(&definition.implementation_entrypoints_field)
        .and_then(|value| value.as_array().cloned());
    if raw_entrypoints.as_ref().is_none_or(Vec::is_empty) {
        errors.insert(format!(
            "{} must be a nonempty list",
            definition.implementation_entrypoints_field
        ));
    }
    let inventory = file_rows
        .iter()
        .filter_map(|row| {
            row["path"]
                .as_str()
                .map(|path| (path.to_owned(), row.clone()))
        })
        .collect::<BTreeMap<_, _>>();
    let mut seen = BTreeSet::new();
    let mut entrypoints = Vec::new();
    for (index, value) in raw_entrypoints.unwrap_or_default().into_iter().enumerate() {
        let Some(raw) = value
            .as_str()
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            errors.insert(format!(
                "{}[{index}] must be a nonempty path string",
                definition.implementation_entrypoints_field
            ));
            continue;
        };
        let relative = match normalized_relative_filesystem_path(raw) {
            Ok(relative) => relative,
            Err(error) => {
                errors.insert(format!("implementation entrypoint {error}: {raw}"));
                continue;
            }
        };
        let normalized = path_text(&relative);
        if !seen.insert(normalized.clone()) {
            errors.insert(format!("duplicate implementation entrypoint: {normalized}"));
            continue;
        }
        let Some(root) = normalized_root.as_ref() else {
            errors.insert(format!(
                "implementation entrypoint cannot be validated without a root: {normalized}"
            ));
            continue;
        };
        if !relative.starts_with(root) {
            errors.insert(format!(
                "implementation entrypoint escapes configured root: {normalized}"
            ));
            continue;
        }
        let concrete = project_root.join(&relative);
        if definition.scan.symlinks == FilesystemSymlinkPolicy::Reject
            && filesystem_path_contains_symlink(project_root, &relative)
        {
            errors.insert(format!(
                "implementation entrypoint is a symlink: {normalized}"
            ));
            continue;
        }
        let resolved = match concrete.canonicalize() {
            Ok(resolved) => resolved,
            Err(_) => {
                errors.insert(format!(
                    "implementation entrypoint does not exist: {normalized}"
                ));
                continue;
            }
        };
        if canonical_root
            .as_ref()
            .is_none_or(|root| !resolved.starts_with(root))
            || project_canonical
                .as_ref()
                .is_none_or(|project_root| !resolved.starts_with(project_root))
        {
            errors.insert(format!(
                "implementation entrypoint escapes configured root: {normalized}"
            ));
            continue;
        }
        if !resolved.is_file() {
            errors.insert(format!(
                "implementation entrypoint is not a file: {normalized}"
            ));
            continue;
        }
        if resolved
            .metadata()
            .map_or(true, |metadata| metadata.len() == 0)
        {
            errors.insert(format!("implementation entrypoint is empty: {normalized}"));
            continue;
        }
        let Some(row) = inventory.get(&normalized) else {
            errors.insert(format!(
                "implementation entrypoint is absent from filesystem manifest: {normalized}"
            ));
            continue;
        };
        entrypoints.push(row.clone());
    }
    entrypoints.sort_by(|left, right| {
        left["path"]
            .as_str()
            .unwrap_or_default()
            .cmp(right["path"].as_str().unwrap_or_default())
    });

    let (source, external, vendor_status) = derive_filesystem_vendor_status(
        node,
        definition,
        project_root,
        canonical_root.as_deref(),
        &file_rows,
    );
    if vendor_status != "vendored" {
        errors.insert(format!(
            "filesystem vendor status is not ready: {vendor_status}"
        ));
    }
    let content_hash = normalized_hash(&json!({
        "root": normalized_root.as_ref().map(|path| path_text(path)),
        "source": source,
        "external": external,
        "vendor_status": vendor_status,
        "implementation_kind": kind,
        "implementation_contract_hash": contract_hash,
        "contract_fields_hash": contract_fields_hash,
        "entrypoints": entrypoints,
        "files": file_rows,
    }));
    let previous_accepted_hash = node
        .field_owned(&definition.output_field)
        .and_then(|manifest| {
            manifest
                .get("accepted_content_hash")
                .and_then(Value::as_str)
                .map(ToOwned::to_owned)
        });
    let structurally_ready = errors.is_empty() && !entrypoints.is_empty();
    let accepted_content_hash = if structurally_ready && accept_changes {
        Some(content_hash.clone())
    } else {
        previous_accepted_hash
    };
    if structurally_ready && accepted_content_hash.as_deref() != Some(content_hash.as_str()) {
        errors.insert("filesystem content hash requires scoped compiler acceptance".to_owned());
    }
    let implementation_errors = errors.into_iter().map(Value::String).collect::<Vec<_>>();
    let implementation_status = if implementation_errors.is_empty() {
        "ready"
    } else {
        "incomplete"
    };
    let mut manifest = json!({
        "schema_version": "1.0",
        "root": normalized_root.as_ref().map(|path| path_text(path)),
        "source": source,
        "external": external,
        "vendor_status": vendor_status,
        "implementation_status": implementation_status,
        "implementation_kind": kind,
        "implementation_contract_hash": contract_hash,
        "contract_fields_hash": contract_fields_hash,
        "content_hash": content_hash,
        "accepted_content_hash": accepted_content_hash,
        "entrypoint_count": entrypoints.len(),
        "file_count": file_rows.len(),
        "implementation_errors": implementation_errors,
        "entrypoints": entrypoints,
        "files": file_rows,
    });
    let hash = normalized_hash(&manifest);
    manifest["hash"] = Value::String(hash);
    manifest
}

fn ticket_can_accept_filesystem_manifest(
    ticket: &Ticket,
    node: &Node,
    definition: &FilesystemManifestDef,
) -> bool {
    if !ticket.scope.write_nodes.contains(&node.id) {
        return false;
    }
    let Some(root) = node
        .field_owned(&definition.root_field)
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .and_then(|root| normalized_relative_filesystem_path(root.trim()).ok())
    else {
        return false;
    };
    ticket.scope.write_paths.iter().any(|configured| {
        normalized_relative_filesystem_path(configured)
            .is_ok_and(|configured| root == configured || root.starts_with(configured))
    })
}

fn normalized_relative_filesystem_path(raw: &str) -> std::result::Result<PathBuf, &'static str> {
    let path = Path::new(raw);
    if path.is_absolute() {
        return Err("must be project-relative");
    }
    let mut normalized = PathBuf::new();
    for component in path.components() {
        match component {
            std::path::Component::Normal(component) => normalized.push(component),
            std::path::Component::CurDir => {}
            std::path::Component::ParentDir => return Err("escapes the project"),
            std::path::Component::RootDir | std::path::Component::Prefix(_) => {
                return Err("must be project-relative");
            }
        }
    }
    if normalized.as_os_str().is_empty() {
        return Err("must be nonempty");
    }
    Ok(normalized)
}

fn path_text(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

fn filesystem_manifest_path_is_ignored(
    relative: &Path,
    definition: &FilesystemManifestDef,
) -> bool {
    let file_name = relative.file_name().and_then(|name| name.to_str());
    if file_name.is_some_and(|name| {
        definition
            .scan
            .ignored_file_names
            .iter()
            .any(|ignored| ignored == name)
    }) {
        return true;
    }
    if relative.components().any(|component| {
        component.as_os_str().to_str().is_some_and(|component| {
            definition
                .scan
                .ignored_path_components
                .iter()
                .any(|ignored| ignored == component)
        })
    }) {
        return true;
    }
    let lower = file_name.unwrap_or_default().to_ascii_lowercase();
    if definition
        .scan
        .ignored_suffixes
        .iter()
        .any(|suffix| lower.ends_with(&suffix.to_ascii_lowercase()))
    {
        return true;
    }
    definition.scan.ignored_path_prefixes.iter().any(|prefix| {
        normalized_relative_filesystem_path(prefix).is_ok_and(|prefix| relative.starts_with(prefix))
    })
}

fn filesystem_path_contains_symlink(project_root: &Path, relative: &Path) -> bool {
    let mut current = project_root.to_path_buf();
    for component in relative.components() {
        current.push(component.as_os_str());
        if fs::symlink_metadata(&current).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
            return true;
        }
    }
    false
}

fn derive_filesystem_vendor_status(
    node: &Node,
    definition: &FilesystemManifestDef,
    project_root: &Path,
    canonical_root: Option<&Path>,
    file_rows: &[Value],
) -> (String, bool, String) {
    let Some(source_policy) = &definition.source else {
        return (
            "unspecified".to_owned(),
            false,
            if file_rows.is_empty() {
                "missing"
            } else {
                "vendored"
            }
            .to_owned(),
        );
    };
    let source = node
        .field_owned(&source_policy.field)
        .and_then(|value| value.as_str().map(str::trim).map(ToOwned::to_owned))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| source_policy.unspecified_value.clone());
    let external = source_policy
        .external_values
        .iter()
        .any(|value| value.eq_ignore_ascii_case(&source));
    let Some(vendor) = &source_policy.vendor else {
        return (
            source,
            external,
            if file_rows.is_empty() {
                "missing"
            } else {
                "vendored"
            }
            .to_owned(),
        );
    };
    if vendor.blocked_reason_fields.iter().any(|field| {
        node.field_owned(field)
            .and_then(|value| value.as_str().map(str::trim).map(ToOwned::to_owned))
            .is_some_and(|value| !value.is_empty())
    }) {
        return (source, external, "blocked".to_owned());
    }
    let expected = vendor
        .path_fields
        .iter()
        .flat_map(|field| match node.field_owned(field) {
            Some(Value::String(value)) => vec![value],
            Some(Value::Array(values)) => values
                .into_iter()
                .filter_map(|value| value.as_str().map(ToOwned::to_owned))
                .collect(),
            _ => Vec::new(),
        })
        .collect::<Vec<_>>();
    if expected.is_empty() {
        return (
            source,
            external,
            if file_rows.is_empty() {
                "missing"
            } else {
                "vendored"
            }
            .to_owned(),
        );
    }
    let inventory = file_rows
        .iter()
        .filter_map(|row| row["path"].as_str().map(|path| (path, row)))
        .collect::<BTreeMap<_, _>>();
    let normalized_root = node
        .field_owned(&definition.root_field)
        .and_then(|value| value.as_str().map(ToOwned::to_owned))
        .and_then(|value| normalized_relative_filesystem_path(value.trim()).ok());
    for raw in expected {
        let Ok(relative) = normalized_relative_filesystem_path(raw.trim()) else {
            return (source, external, "invalid_path".to_owned());
        };
        let Some(relative_to_root) = normalized_root
            .as_ref()
            .and_then(|root| relative.strip_prefix(root).ok())
        else {
            return (source, external, "invalid_path".to_owned());
        };
        if filesystem_manifest_path_is_ignored(relative_to_root, definition)
            || (definition.scan.symlinks == FilesystemSymlinkPolicy::Reject
                && filesystem_path_contains_symlink(project_root, &relative))
        {
            return (source, external, "invalid_path".to_owned());
        }
        let concrete = project_root.join(&relative);
        let Ok(resolved) = concrete.canonicalize() else {
            return (source, external, "missing".to_owned());
        };
        if canonical_root.is_none_or(|root| !resolved.starts_with(root)) {
            return (source, external, "invalid_path".to_owned());
        }
        if !resolved.is_file() {
            return (source, external, "missing".to_owned());
        }
        let path = path_text(
            &normalized_root
                .as_ref()
                .expect("root checked above")
                .join(relative_to_root),
        );
        if inventory
            .get(path.as_str())
            .and_then(|row| row.get("bytes"))
            .and_then(Value::as_u64)
            .is_none_or(|bytes| bytes == 0)
        {
            return (source, external, "missing".to_owned());
        }
    }
    (source, external, "vendored".to_owned())
}

fn read_compiler_issued_context_document(
    project_root: &Path,
    work_tickets: &Path,
    issued_path: &Path,
) -> Result<String> {
    let allowed = work_tickets
        .canonicalize()
        .map_err(|error| io_error(work_tickets, error))?;
    let candidate = if issued_path.is_absolute() {
        issued_path.to_path_buf()
    } else {
        contained_join(project_root, issued_path)?
    };
    let metadata = fs::symlink_metadata(&candidate).map_err(|error| io_error(&candidate, error))?;
    if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
        return Err(KoniError::Action(
            "compiler-issued context document is not a regular file".to_owned(),
        ));
    }
    let resolved = candidate
        .canonicalize()
        .map_err(|error| io_error(&candidate, error))?;
    if !resolved.starts_with(&allowed) {
        return Err(KoniError::Action(
            "compiler-issued context document is outside current run work storage".to_owned(),
        ));
    }
    fs::read_to_string(&resolved).map_err(|error| io_error(&resolved, error))
}

fn contained_join(root: &Path, relative: &Path) -> Result<PathBuf> {
    if relative.is_absolute()
        || relative
            .components()
            .any(|component| matches!(component, std::path::Component::ParentDir))
    {
        return Err(KoniError::Action(format!(
            "path escapes project root: {}",
            relative.display()
        )));
    }
    Ok(root.join(relative))
}

fn lookup_dynamic_path<'a>(
    root: &'a Value,
    path: &str,
    variables: &BTreeMap<String, String>,
) -> Option<&'a Value> {
    let mut value = root;
    for segment in split_dynamic_path(path)? {
        let field_end = segment.find('[').unwrap_or(segment.len());
        let field = &segment[..field_end];
        if !field.is_empty() {
            value = value.as_object()?.get(field)?;
        }

        let mut remainder = &segment[field_end..];
        while !remainder.is_empty() {
            let close = remainder.find(']')?;
            if !remainder.starts_with('[') {
                return None;
            }
            let raw_key = remainder[1..close].trim();
            let key = if let Some(variable) = raw_key.strip_prefix('$') {
                variables.get(variable)?.as_str()
            } else {
                raw_key.trim_matches(['\'', '"'])
            };
            value = match value {
                Value::Object(object) => object.get(key)?,
                Value::Array(items) => items.get(key.parse::<usize>().ok()?)?,
                _ => return None,
            };
            remainder = &remainder[close + 1..];
        }
    }
    Some(value)
}

fn split_dynamic_path(path: &str) -> Option<Vec<String>> {
    let mut segments = Vec::new();
    let mut current = String::new();
    let mut bracket_depth = 0_u32;
    for character in path.chars() {
        match character {
            '[' => {
                bracket_depth = bracket_depth.checked_add(1)?;
                current.push(character);
            }
            ']' => {
                bracket_depth = bracket_depth.checked_sub(1)?;
                current.push(character);
            }
            '.' if bracket_depth == 0 => {
                if current.is_empty() {
                    return None;
                }
                segments.push(std::mem::take(&mut current));
            }
            _ => current.push(character),
        }
    }
    if bracket_depth != 0 || current.is_empty() {
        return None;
    }
    segments.push(current);
    Some(segments)
}

/// Keep a long-lived agent out of the short-lived command runner's process
/// group. Codex command execution reaps processes left in its group when the
/// command returns; without this boundary, a successfully spawned ticket
/// worker can be killed before it emits `thread.started`.
#[cfg(unix)]
fn isolate_agent_process_group(command: &mut Command) {
    command.process_group(0);
}

#[cfg(not(unix))]
fn isolate_agent_process_group(_command: &mut Command) {}

const AGENT_RUNTIME_EXCLUDE_MARKER: &str = "# koni agent runtime (operational, never semantic)";

fn agent_runtime_repo_path(git: &GitBackend, runtime_tickets: &Path) -> Option<PathBuf> {
    let runtime_tickets = runtime_tickets.canonicalize().ok()?;
    let relative = runtime_tickets.strip_prefix(git.workdir()).ok()?;
    (!relative.as_os_str().is_empty()
        && relative.components().all(|component| {
            matches!(
                component,
                std::path::Component::Normal(_) | std::path::Component::CurDir
            )
        }))
    .then(|| relative.to_path_buf())
}

fn git_pattern_path(path: &Path) -> Result<String> {
    path.components()
        .filter_map(|component| match component {
            std::path::Component::Normal(value) => Some(value),
            std::path::Component::CurDir => None,
            _ => None,
        })
        .map(|component| {
            component.to_str().map(ToOwned::to_owned).ok_or_else(|| {
                KoniError::Profile(format!(
                    "agent runtime path is not valid UTF-8: {}",
                    path.display()
                ))
            })
        })
        .collect::<Result<Vec<_>>>()
        .map(|components| components.join("/"))
}

fn ensure_agent_runtime_excludes(git: &GitBackend, runtime_repo_path: Option<&Path>) -> Result<()> {
    let Some(runtime_repo_path) = runtime_repo_path else {
        return Ok(());
    };
    let runtime_pattern = git_pattern_path(runtime_repo_path)?;
    let path = git.common_dir().join("info/exclude");
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
    }
    let existing = fs::read_to_string(&path).unwrap_or_default();

    // Remove only the legacy Koni-owned global block. Those patterns were
    // broad enough to hide product files named worker.log or worker.pid.
    let lines = existing.lines().collect::<Vec<_>>();
    let mut retained = Vec::new();
    let mut index = 0;
    while index < lines.len() {
        if lines[index] == AGENT_RUNTIME_EXCLUDE_MARKER {
            index += 1;
            while index < lines.len() && matches!(lines[index], "**/worker.log" | "**/worker.pid") {
                index += 1;
            }
            continue;
        }
        retained.push(lines[index].to_owned());
        index += 1;
    }

    let marker = format!("{AGENT_RUNTIME_EXCLUDE_MARKER}: /{runtime_pattern}");
    let log_pattern = format!("/{runtime_pattern}/**/worker.log");
    let direct_pi_log_pattern = format!("/{runtime_pattern}/**/worker.*.attempt-*.log");
    let pid_pattern = format!("/{runtime_pattern}/**/worker.pid");
    for line in [&marker, &log_pattern, &direct_pi_log_pattern, &pid_pattern] {
        if !retained.iter().any(|existing| existing == line) {
            retained.push(line.clone());
        }
    }
    let mut updated = retained.join("\n");
    if !updated.is_empty() {
        updated.push('\n');
    }
    if updated == existing {
        return Ok(());
    }
    fs::write(&path, updated).map_err(|error| io_error(&path, error))
}

fn is_agent_runtime_path(path: &Path, runtime_repo_path: &Path) -> bool {
    let Ok(relative) = path.strip_prefix(runtime_repo_path) else {
        return false;
    };
    relative
        .file_name()
        .and_then(|name| name.to_str())
        .is_some_and(|name| {
            matches!(name, "worker.log" | "worker.pid") || is_direct_pi_worker_log_name(name)
        })
        && relative
            .parent()
            .is_some_and(|parent| !parent.as_os_str().is_empty())
}

fn cleanup_agent_runtime_artifacts(
    repository: &git2::Repository,
    runtime_repo_path: Option<&Path>,
) -> Result<(Vec<PathBuf>, Option<String>, git2::Index)> {
    let parent = repository.head()?.peel_to_commit()?;
    let parent_tree = parent.tree()?;
    let mut cleanup_index = git2::Index::new()?;
    cleanup_index.read_tree(&parent_tree)?;

    let mut runtime_paths = BTreeSet::new();
    if let Some(runtime_repo_path) = runtime_repo_path {
        runtime_paths.extend(
            cleanup_index
                .iter()
                .filter_map(|entry| String::from_utf8(entry.path.to_vec()).ok())
                .map(PathBuf::from)
                .filter(|path| is_agent_runtime_path(path, runtime_repo_path)),
        );
        let live_index = repository.index()?;
        runtime_paths.extend(
            live_index
                .iter()
                .filter_map(|entry| String::from_utf8(entry.path.to_vec()).ok())
                .map(PathBuf::from)
                .filter(|path| is_agent_runtime_path(path, runtime_repo_path)),
        );
    }
    for path in &runtime_paths {
        if cleanup_index.get_path(path, 0).is_some() {
            cleanup_index.remove_path(path)?;
        }
    }

    let runtime_free_tree = cleanup_index.write_tree_to(repository)?;
    let runtime_cleanup_commit = if runtime_free_tree != parent_tree.id() {
        let tree = repository.find_tree(runtime_free_tree)?;
        let signature = git2::Signature::now("Koni State", "koni-state@example.local")?;
        Some(
            repository
                .commit(
                    Some("HEAD"),
                    &signature,
                    &signature,
                    "chore(koni): detach agent runtime files",
                    &tree,
                    &[&parent],
                )?
                .to_string(),
        )
    } else {
        None
    };

    // The cleanup tree is built in-memory. Remove only Koni runtime entries
    // from the live index so unrelated staged changes retain their exact state.
    if !runtime_paths.is_empty() {
        let mut live_index = repository.index()?;
        let mut changed = false;
        for path in &runtime_paths {
            if live_index.get_path(path, 0).is_some() {
                live_index.remove_path(path)?;
                changed = true;
            }
        }
        if changed {
            live_index.write()?;
        }
    }

    Ok((
        runtime_paths.into_iter().collect(),
        runtime_cleanup_commit,
        cleanup_index,
    ))
}

fn resolved_agent_runtime_blocker(
    message: &str,
    runtime_repo_path: &Path,
    index: &git2::Index,
) -> bool {
    let Some(paths) = message.strip_prefix("action error: integration checkout is dirty: ") else {
        return false;
    };
    let paths = paths
        .split(',')
        .map(str::trim)
        .filter(|path| !path.is_empty())
        .map(PathBuf::from)
        .collect::<Vec<_>>();
    !paths.is_empty()
        && paths.iter().all(|path| {
            is_agent_runtime_path(path, runtime_repo_path) && index.get_path(path, 0).is_none()
        })
}

fn configured_node_path_field<'a>(
    profile: &CompiledProfile,
    node: &'a Node,
    field: &str,
    role: &str,
) -> Result<(&'a Value, BTreeSet<String>)> {
    let node_type = profile.node_types.get(&node.node_type).ok_or_else(|| {
        KoniError::Action(format!(
            "read-scope-repair {role} node has no configured node type"
        ))
    })?;
    let definition = node_type.fields.get(field).ok_or_else(|| {
        KoniError::Action(format!(
            "read-scope-repair {role} field is not configured on its node type"
        ))
    })?;
    let value = node
        .spec
        .as_object()
        .and_then(|spec| spec.get(field))
        .ok_or_else(|| {
            KoniError::Action(format!(
                "read-scope-repair {role} field is absent from the exact graph node"
            ))
        })?;
    let raw_paths = match definition.value_type {
        FieldType::Path => vec![value.as_str().ok_or_else(|| {
            KoniError::Action(format!(
                "read-scope-repair {role} field does not contain one path string"
            ))
        })?],
        FieldType::List
            if definition
                .items
                .as_deref()
                .is_some_and(|items| items.value_type == FieldType::Path) =>
        {
            value
                .as_array()
                .ok_or_else(|| {
                    KoniError::Action(format!(
                        "read-scope-repair {role} field does not contain a path list"
                    ))
                })?
                .iter()
                .map(|value| {
                    value.as_str().ok_or_else(|| {
                        KoniError::Action(format!(
                            "read-scope-repair {role} path list contains a non-string value"
                        ))
                    })
                })
                .collect::<Result<Vec<_>>>()?
        }
        _ => {
            return Err(KoniError::Action(format!(
                "read-scope-repair {role} field is not configured as Path or list<Path>"
            )));
        }
    };
    let mut paths = BTreeSet::new();
    for raw in raw_paths {
        let normalized = normalized_worker_file_path(raw)?;
        if normalized == "." || normalized != raw || !paths.insert(normalized) {
            return Err(KoniError::Action(format!(
                "read-scope-repair {role} field contains a broad, noncanonical, or duplicate path"
            )));
        }
    }
    Ok((value, paths))
}

fn validate_read_scope_replan_binding(binding: &ReadScopeReplanBinding) -> Result<()> {
    let mut expected = binding.clone();
    let actual_hash = std::mem::take(&mut expected.binding_hash);
    if binding.schema_version != "1.0"
        || binding.status != "replan_required"
        || binding.request_hash.is_empty()
        || binding.request_event_id.is_empty()
        || binding.ticket_id.is_empty()
        || binding.step_id.is_empty()
        || binding.prior_ticket_status.is_empty()
        || binding.base_ticket_hash.is_empty()
        || binding.base_graph_hash.is_empty()
        || binding.base_step_hash.is_empty()
        || binding.base_compiled_check_sets_hash.is_empty()
        || binding.lease_hash.is_empty()
        || binding.lease_branch_ref.is_empty()
        || binding.lease_head.is_empty()
        || binding.path.is_empty()
        || binding.source_node_id.is_empty()
        || binding.source_field.is_empty()
        || binding.amend_node_id.is_empty()
        || binding.amend_field.is_empty()
        || binding.amend_read_only_proof_hash.is_empty()
        || actual_hash != normalized_hash(&expected)
    {
        return Err(KoniError::Action(
            "ticket has an invalid compiler-owned read-scope replan binding".to_owned(),
        ));
    }
    Ok(())
}

fn read_scope_replan_binding(
    ticket: &Ticket,
    request_hash: &str,
) -> Result<Option<ReadScopeReplanBinding>> {
    let Some(history) = ticket.extensions.get(READ_SCOPE_REPLAN_EXTENSION) else {
        return Ok(None);
    };
    let history = history.as_array().ok_or_else(|| {
        KoniError::Action(format!(
            "ticket {} has invalid {} history",
            ticket.id, READ_SCOPE_REPLAN_EXTENSION
        ))
    })?;
    let matches = history
        .iter()
        .filter(|entry| entry.get("request_hash").and_then(Value::as_str) == Some(request_hash))
        .collect::<Vec<_>>();
    if matches.len() > 1 {
        return Err(KoniError::Action(format!(
            "ticket {} repeats one read-scope replan binding",
            ticket.id
        )));
    }
    let Some(value) = matches.first() else {
        return Ok(None);
    };
    let binding =
        serde_json::from_value::<ReadScopeReplanBinding>((*value).clone()).map_err(|error| {
            KoniError::Action(format!(
                "ticket {} has an unreadable read-scope replan binding: {error}",
                ticket.id
            ))
        })?;
    validate_read_scope_replan_binding(&binding)?;
    if binding.ticket_id != ticket.id || binding.request_hash != request_hash {
        return Err(KoniError::Action(
            "read-scope replan binding is attached to a different ticket or request".to_owned(),
        ));
    }
    Ok(Some(binding))
}

fn read_scope_replan_instruction(binding: &ReadScopeReplanBinding) -> String {
    format!(
        "Step {} cannot receive legacy read authority for {} because the path changes the semantic proof boundary. Amend node {} field {}, then recompile and reissue the same deterministic ticket, compiled checks, context, and worker grant while preserving its lease and history. No read or write authority was widened.",
        binding.step_id, binding.path, binding.amend_node_id, binding.amend_field
    )
}

fn append_read_scope_replan_event_once(
    store: &StateStore,
    run: &RunManifest,
    binding: &ReadScopeReplanBinding,
    instruction: &str,
) -> Result<()> {
    let expected_data = read_scope_replan_event_data(binding, instruction);
    let matches = store
        .events()?
        .into_iter()
        .filter(|event| {
            event.event_type == READ_SCOPE_REPLAN_EVENT_TYPE
                && event.ticket_id.as_deref() == Some(binding.ticket_id.as_str())
                && event.data.get("request_hash").and_then(Value::as_str)
                    == Some(binding.request_hash.as_str())
        })
        .collect::<Vec<_>>();
    if !matches.is_empty() {
        if matches.len() == 1
            && matches[0].schema_version == "1.0"
            && matches[0].run_id == run.id
            && matches[0].actor == "compiler"
            && matches[0].data == expected_data
        {
            return Ok(());
        }
        return Err(KoniError::Action(
            "read-scope-repair derived event conflicts with its compiler-owned binding".to_owned(),
        ));
    }
    store.append_event(&Event::new(
        &run.id,
        READ_SCOPE_REPLAN_EVENT_TYPE,
        Some(binding.ticket_id.clone()),
        expected_data,
    ))
}

fn read_scope_replan_event_data(binding: &ReadScopeReplanBinding, instruction: &str) -> Value {
    json!({
        "request_hash": binding.request_hash,
        "binding_hash": binding.binding_hash,
        "step_id": binding.step_id,
        "prior_ticket_status": binding.prior_ticket_status,
        "base_ticket_hash": binding.base_ticket_hash,
        "base_graph_hash": binding.base_graph_hash,
        "base_step_hash": binding.base_step_hash,
        "base_compiled_check_sets_hash": binding.base_compiled_check_sets_hash,
        "lease_hash": binding.lease_hash,
        "lease_branch_ref": binding.lease_branch_ref,
        "lease_head": binding.lease_head,
        "path": binding.path,
        "source_node_id": binding.source_node_id,
        "source_field": binding.source_field,
        "source_field_hash": binding.source_field_hash,
        "amend_node_id": binding.amend_node_id,
        "amend_field": binding.amend_field,
        "amend_field_hash": binding.amend_field_hash,
        "amend_read_only_proof_hash": binding.amend_read_only_proof_hash,
        "review_id": binding.review_id,
        "correction_event_id": binding.correction_event_id,
        "correction_event_hash": binding.correction_event_hash,
        "instruction": instruction,
        "authority_changed": false,
    })
}

fn ensure_read_scope_replan_quiescent(
    engine: &Engine,
    run: &RunManifest,
    ticket: &Ticket,
) -> Result<()> {
    if ticket.extensions.contains_key("active_worker")
        || ticket
            .lease
            .as_ref()
            .and_then(|lease| lease.worker_pid)
            .is_some()
    {
        return Err(KoniError::Action(
            "read-scope-repair requires a recovered ticket with no active-worker lease".to_owned(),
        ));
    }
    let git = GitBackend::discover(&engine.root)?;
    let control = RunControlStore::new(git.sidecar_path(format!("runs/{}", run.id))?);
    if control
        .orchestration()?
        .is_none_or(|orchestration| orchestration.running)
    {
        return Err(KoniError::Action(
            "read-scope-repair requires the run scheduler to be durably paused".to_owned(),
        ));
    }
    if control
        .agents()?
        .iter()
        .any(|agent| agent.run_id == run.id && planning_agent_is_live_status(&agent.status))
    {
        return Err(KoniError::Action(
            "read-scope-repair requires every worker, reviewer, and Lead session to be quiescent"
                .to_owned(),
        ));
    }
    if control
        .lead_slice()?
        .is_some_and(|slice| slice.status == LeadSliceStatus::Active)
    {
        return Err(KoniError::Action(
            "read-scope-repair cannot run while a Lead slice retains active authority".to_owned(),
        ));
    }

    let grants_dir = git.common_dir().join("koni").join("broker-grants");
    if !grants_dir.exists() {
        return Ok(());
    }
    for entry in fs::read_dir(&grants_dir).map_err(|error| io_error(&grants_dir, error))? {
        let entry = entry.map_err(|error| io_error(&grants_dir, error))?;
        if entry
            .path()
            .extension()
            .and_then(|extension| extension.to_str())
            != Some("yaml")
        {
            continue;
        }
        let grant_path = entry.path();
        let grant_id = grant_path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .ok_or_else(|| {
                KoniError::Process(
                    "read-scope-repair found a non-UTF-8 broker grant identity".to_owned(),
                )
            })?;
        let grant = read_agent_broker_grant(git.common_dir(), grant_id)?;
        let matches_ticket = matches!(
            &grant.role,
            AgentBrokerRole::Worker { ticket: owner, .. } if owner == &ticket.id
        );
        if grant.run_id == run.id
            && matches_ticket
            && (!matches!(
                grant.state,
                AgentBrokerGrantState::Revoked | AgentBrokerGrantState::Consumed
            ) || grant.revoke_pending
                || grant.in_flight.is_some())
        {
            return Err(KoniError::Action(
                "read-scope-repair cannot run while the ticket has a live or in-flight broker grant"
                    .to_owned(),
            ));
        }
    }
    Ok(())
}

fn ensure_planned_proof_source_relocation_quiescent(
    engine: &Engine,
    run: &RunManifest,
    store: &StateStore,
) -> Result<()> {
    let git = GitBackend::discover(&engine.root)?;
    let control = RunControlStore::new(git.sidecar_path(format!("runs/{}", run.id))?);
    if control
        .orchestration()?
        .is_none_or(|orchestration| orchestration.running)
    {
        return Err(KoniError::Action(
            "planned-proof source relocation requires the run scheduler to be durably paused"
                .to_owned(),
        ));
    }
    if control
        .agents()?
        .iter()
        .any(|agent| agent.run_id == run.id && planning_agent_is_live_status(&agent.status))
    {
        return Err(KoniError::Action(
            "planned-proof source relocation requires every worker, reviewer, and Lead session to be quiescent"
                .to_owned(),
        ));
    }
    if control
        .lead_slice()?
        .is_some_and(|slice| slice.status == LeadSliceStatus::Active)
    {
        return Err(KoniError::Action(
            "planned-proof source relocation cannot run while a Lead slice retains active authority"
                .to_owned(),
        ));
    }
    let owned = store
        .tickets()?
        .into_iter()
        .filter(|ticket| {
            ticket.extensions.contains_key("active_worker")
                || ticket
                    .lease
                    .as_ref()
                    .and_then(|lease| lease.worker_pid)
                    .is_some()
        })
        .map(|ticket| ticket.id)
        .collect::<Vec<_>>();
    if !owned.is_empty() {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation requires recovered tickets with no active-worker authority: {}",
            owned.join(", ")
        )));
    }

    reconcile_superseded_terminal_lead_wait_grants(&engine.root, &run.id, &control)?;

    let grants_dir = git.common_dir().join("koni").join("broker-grants");
    if !grants_dir.exists() {
        return Ok(());
    }
    for entry in fs::read_dir(&grants_dir).map_err(|error| io_error(&grants_dir, error))? {
        let entry = entry.map_err(|error| io_error(&grants_dir, error))?;
        if entry
            .path()
            .extension()
            .and_then(|extension| extension.to_str())
            != Some("yaml")
        {
            continue;
        }
        let grant_path = entry.path();
        let grant_id = grant_path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .ok_or_else(|| {
                KoniError::Process(
                    "planned-proof source relocation found a non-UTF-8 broker grant identity"
                        .to_owned(),
                )
            })?;
        let grant = read_agent_broker_grant(git.common_dir(), grant_id)?;
        if grant.run_id == run.id
            && (!matches!(
                grant.state,
                AgentBrokerGrantState::Revoked | AgentBrokerGrantState::Consumed
            ) || grant.revoke_pending
                || grant.in_flight.is_some())
        {
            return Err(KoniError::Action(
                "planned-proof source relocation cannot run while the run has a live or in-flight broker grant"
                    .to_owned(),
            ));
        }
    }
    Ok(())
}

fn ensure_planned_proof_source_relocation_workspace_current(
    engine: &Engine,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<()> {
    let git = GitBackend::discover(&engine.root)?;
    if git.branch_ref()? != transaction.integration_ref
        || git.head_oid()?.to_string() != transaction.integration_head
        || git.reference_oid(&transaction.integration_ref)?.to_string()
            != transaction.integration_head
    {
        return Err(KoniError::Action(
            "planned-proof source relocation integration branch or HEAD changed after preparation"
                .to_owned(),
        ));
    }
    let mut status_exclusions = tracked_state_status_exclusions(&engine.profile, git.workdir())?;
    if engine.profile.manifest.storage.backend == StorageBackend::Tracked {
        let store = engine.store()?;
        let graph_path = store
            .graph_dir()
            .join(&transaction.amended_node.node_type)
            .join(format!(
                "{}--{}.yaml",
                slugify(&transaction.amended_node.title),
                transaction.amended_node.id
            ));
        for path in [
            planned_proof_source_relocation_transaction_path(store, &transaction.request_hash)?,
            store.root().join("events.jsonl"),
            store
                .root()
                .join("journals")
                .join(format!("{}.yaml", transaction.request_action_journal_id)),
            store
                .root()
                .join("journals")
                .join(format!("{}.yaml", transaction.failed_compile_journal_id)),
            store.ticket_path(&transaction.expected_ticket),
            graph_path,
        ] {
            status_exclusions.push(
                path.strip_prefix(git.workdir())
                    .map(Path::to_path_buf)
                    .map_err(|_| {
                        KoniError::Action(format!(
                            "planned-proof source relocation compiler-state path {} is outside checkout {}",
                            path.display(),
                            git.workdir().display()
                        ))
                    })?,
            );
        }
        status_exclusions.sort();
        status_exclusions.dedup();
    }
    let changes = git.status(&status_exclusions)?;
    if !changes.is_empty() {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation requires its integration checkout to remain clean; found {} changed path(s)",
            changes.len()
        )));
    }
    if worker_file_path_aliases_protected(
        &engine.root,
        &engine.profile,
        &transaction.new_source_path,
    )? {
        return Err(KoniError::Action(
            "planned-proof source relocation new path aliases protected compiler state".to_owned(),
        ));
    }
    ensure_planned_proof_source_relocation_path_untracked(
        &engine.root,
        &transaction.new_source_path,
    )?;
    reject_project_path_symlink_components(
        &engine.root,
        &transaction.new_source_path,
        "planned-proof source relocation",
    )?;
    let new_file = engine.root.join(&transaction.new_source_path);
    match fs::symlink_metadata(&new_file) {
        Ok(_) => Err(KoniError::Action(
            "planned-proof source relocation new source file appeared after preparation".to_owned(),
        )),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(io_error(&new_file, error)),
    }
}

fn ensure_planned_proof_source_relocation_path_untracked(
    root: &Path,
    new_source_path: &str,
) -> Result<()> {
    let repository = git2::Repository::discover(root)?;
    let index = repository.index()?;
    for entry in index.iter() {
        let tracked = std::str::from_utf8(&entry.path).map_err(|_| {
            KoniError::Git(git2::Error::from_str(
                "planned-proof source relocation found a non-UTF-8 Git index path",
            ))
        })?;
        if project_authority_paths_lexically_overlap(new_source_path, tracked)? {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation new path overlaps tracked Git index entry {tracked}"
            )));
        }
        if entry.mode == 0o120000 {
            // Git tracks both the link pathname and its target blob. Compare
            // the pinned target rather than traversing the checkout link: an
            // unrelated compatibility alias may be allowed, but a link to
            // the proposed path (or one of its ancestors) remains a tracked
            // authority alias and must fail closed.
            let target = repository.find_blob(entry.id)?;
            ensure_tracked_symlink_target_disjoint(
                root,
                new_source_path,
                tracked,
                target.content(),
            )?;
            continue;
        }
        if project_authority_paths_overlap(root, new_source_path, tracked)? {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation new path overlaps tracked Git index entry {tracked}"
            )));
        }
    }
    let tree = repository.head()?.peel_to_tree()?;
    let mut head_paths = Vec::new();
    tree.walk(git2::TreeWalkMode::PreOrder, |prefix, entry| {
        if matches!(
            entry.kind(),
            Some(git2::ObjectType::Blob | git2::ObjectType::Commit)
        ) {
            if let Ok(name) = entry.name() {
                head_paths.push((format!("{prefix}{name}"), entry.filemode(), entry.id()));
            } else {
                head_paths.push((String::new(), 0, Oid::ZERO_SHA1));
            }
        }
        git2::TreeWalkResult::Ok
    })?;
    if head_paths.iter().any(|(path, _, _)| path.is_empty()) {
        return Err(KoniError::Action(
            "planned-proof source relocation found a non-UTF-8 path in the pinned HEAD tree"
                .to_owned(),
        ));
    }
    for (tracked, mode, oid) in head_paths {
        if project_authority_paths_lexically_equal(new_source_path, &tracked)? {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation new path already belongs to pinned HEAD at {tracked}"
            )));
        }
        if mode == 0o120000 {
            let target = repository.find_blob(oid)?;
            ensure_tracked_symlink_target_disjoint(
                root,
                new_source_path,
                &tracked,
                target.content(),
            )?;
            continue;
        }
        if project_authority_paths_equal(root, new_source_path, &tracked)? {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation new path already belongs to pinned HEAD at {tracked}"
            )));
        }
    }
    Ok(())
}

fn committed_planned_proof_source_relocation_pending(
    profile: &CompiledProfile,
    store: &StateStore,
    run: &RunManifest,
) -> Result<bool> {
    for transaction in planned_proof_source_relocation_transactions(store)? {
        if !planned_proof_source_relocation_is_fully_sealed(profile, store, run, &transaction)? {
            return Ok(true);
        }
    }
    for event in store.events()?.into_iter().filter(|event| {
        event.run_id == run.id
            && event.event_type == "compiler.steering.recorded"
            && event.data.get("kind").and_then(Value::as_str)
                == Some(PLANNED_PROOF_SOURCE_RELOCATION_KIND)
    }) {
        let journal = planned_proof_source_relocation_action_journal(profile, store, &event)?;
        if journal.status != JournalStatus::Complete {
            continue;
        }
        let steer = profile.action("steer").ok_or_else(|| {
            KoniError::Profile(
                "planned-proof source relocation requires a configured steer action".to_owned(),
            )
        })?;
        if journal.completed_steps != (0..steer.recipe.len()).collect::<Vec<_>>() {
            return Err(KoniError::Action(
                "planned-proof source relocation owning action Journal has an invalid completed-step boundary"
                    .to_owned(),
            ));
        }
        let request_hash = normalized_hash(&planned_proof_source_relocation_request(&event)?);
        let Some(transaction) = planned_proof_source_relocation_transaction(store, &request_hash)?
        else {
            return Ok(true);
        };
        if !planned_proof_source_relocation_is_fully_sealed(profile, store, run, &transaction)? {
            return Ok(true);
        }
    }
    Ok(false)
}

fn read_scope_rebind_request(event: &Event) -> Result<ReadScopeRebindRequest> {
    let encoded = event
        .data
        .get("message")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            KoniError::Action(
                "read-scope-rebind requires one versioned JSON object in message".to_owned(),
            )
        })?;
    serde_json::from_str::<ReadScopeRebindRequest>(encoded).map_err(|error| {
        KoniError::Action(format!(
            "read-scope-rebind message is not the exact versioned JSON contract: {error}"
        ))
    })
}

fn planned_proof_source_relocation_request(
    event: &Event,
) -> Result<PlannedProofSourceRelocationRequest> {
    let encoded = event
        .data
        .get("message")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation requires one versioned JSON object in message"
                    .to_owned(),
            )
        })?;
    serde_json::from_str::<PlannedProofSourceRelocationRequest>(encoded).map_err(|error| {
        KoniError::Action(format!(
            "planned-proof source relocation message is not the exact versioned JSON contract: {error}"
        ))
    })
}

fn planned_proof_source_relocation_action_params(event: &Event) -> Result<BTreeMap<String, Value>> {
    let kind = event.data.get("kind").cloned().ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation owning event lost its kind parameter".to_owned(),
        )
    })?;
    let message = event.data.get("message").cloned().ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation owning event lost its message parameter".to_owned(),
        )
    })?;
    let target_nodes = event.data.get("target_nodes").cloned().ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation owning event lost its target_nodes parameter"
                .to_owned(),
        )
    })?;
    let priority = event.data.get("priority").cloned().ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation owning event lost its priority parameter".to_owned(),
        )
    })?;
    let ticket = event.ticket_id.clone().ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation owning event lost its ticket parameter".to_owned(),
        )
    })?;
    Ok(BTreeMap::from([
        ("kind".to_owned(), kind),
        ("message".to_owned(), message),
        ("ticket".to_owned(), Value::String(ticket)),
        ("target_nodes".to_owned(), target_nodes),
        ("priority".to_owned(), priority),
    ]))
}

fn planned_proof_source_relocation_action_journal(
    profile: &CompiledProfile,
    store: &StateStore,
    event: &Event,
) -> Result<Journal> {
    let action_id = event
        .data
        .get("compiler_transaction_action")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation owning event lost its action binding".to_owned(),
            )
        })?;
    let journal_id = event
        .data
        .get("compiler_transaction_journal")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation owning event lost its action Journal binding"
                    .to_owned(),
            )
        })?;
    let action = profile.action("steer").ok_or_else(|| {
        KoniError::Profile(
            "planned-proof source relocation requires a configured steer action".to_owned(),
        )
    })?;
    if action.id != action_id || action.actor != "lead" || event.actor != "lead" {
        return Err(KoniError::Action(
            "planned-proof source relocation requires its exact configured Lead steer action"
                .to_owned(),
        ));
    }
    let journal = store
        .journals()?
        .into_iter()
        .find(|journal| journal.id == journal_id)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation owning action Journal is missing".to_owned(),
            )
        })?;
    let expected_input = action_retry_input_hash(
        action,
        &planned_proof_source_relocation_action_params(event)?,
    );
    if journal.action != action.id
        || journal.profile_hash != profile.hash
        || journal.input_hash.as_deref() != Some(expected_input.as_str())
    {
        return Err(KoniError::Action(
            "planned-proof source relocation owning action Journal is not bound to the exact request"
                .to_owned(),
        ));
    }
    Ok(journal)
}

fn planned_proof_source_relocation_transaction_hash(
    transaction: &PlannedProofSourceRelocationTransaction,
) -> String {
    let mut candidate =
        serde_json::to_value(transaction).expect("proof-source relocation transaction serializes");
    candidate["transaction_hash"] = Value::String(String::new());
    normalized_hash(&candidate)
}

fn planned_proof_source_relocation_transaction_path(
    store: &StateStore,
    request_hash: &str,
) -> Result<PathBuf> {
    let suffix = request_hash.strip_prefix("sha256:").ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation request hash has an unknown format".to_owned(),
        )
    })?;
    if suffix.len() != 64 || !suffix.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(KoniError::Action(
            "planned-proof source relocation request hash is not a canonical SHA-256 identity"
                .to_owned(),
        ));
    }
    Ok(store
        .root()
        .join("recovery/planned-proof-source-relocation")
        .join(format!("{suffix}.yaml")))
}

fn planned_proof_source_relocation_sync_marker_relative_path(
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<PathBuf> {
    let suffix = transaction
        .request_hash
        .strip_prefix("sha256:")
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation sync marker has an unknown request hash format"
                    .to_owned(),
            )
        })?;
    if suffix.len() != 64 || !suffix.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(KoniError::Action(
            "planned-proof source relocation sync marker request hash is not canonical".to_owned(),
        ));
    }
    Ok(PathBuf::from("koni/runs")
        .join(&transaction.run_id)
        .join("recovery/planned-proof-source-relocation-sync")
        .join(format!("{suffix}.yaml")))
}

fn planned_proof_source_relocation_sync_marker(
    transaction: &PlannedProofSourceRelocationTransaction,
    seal_commit: &str,
) -> PlannedProofSourceRelocationSyncMarker {
    PlannedProofSourceRelocationSyncMarker {
        schema_version: "1.0".to_owned(),
        transaction_id: transaction.id.clone(),
        transaction_hash: transaction.transaction_hash.clone(),
        run_id: transaction.run_id.clone(),
        integration_ref: transaction.integration_ref.clone(),
        seal_commit: seal_commit.to_owned(),
    }
}

fn planned_proof_source_relocation_sync_marker_current(
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
    seal_commit: &str,
) -> Result<bool> {
    let git = GitBackend::discover(store.root())?;
    let relative = planned_proof_source_relocation_sync_marker_relative_path(transaction)?;
    let path = git.common_dir().join(&relative);
    match fs::symlink_metadata(&path) {
        Ok(metadata) if metadata.file_type().is_file() => {}
        Ok(_) => {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation sync marker is not a regular file: {}",
                path.display()
            )));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(error) => return Err(io_error(&path, error)),
    }
    let bytes = match read_persistent_file(
        git.common_dir(),
        &relative,
        MAX_PLANNED_PROOF_SOURCE_RELOCATION_SYNC_MARKER_BYTES,
    ) {
        Ok(bytes) => bytes,
        Err(error) if error.kind() == std::io::ErrorKind::InvalidData => return Ok(false),
        Err(error) => return Err(io_error(&path, error)),
    };
    let marker: PlannedProofSourceRelocationSyncMarker = match serde_yaml::from_slice(&bytes) {
        Ok(marker) => marker,
        Err(_) => return Ok(false),
    };
    Ok(marker == planned_proof_source_relocation_sync_marker(transaction, seal_commit))
}

fn write_planned_proof_source_relocation_sync_marker(
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
    seal_commit: &str,
) -> Result<()> {
    let git = GitBackend::discover(store.root())?;
    let relative = planned_proof_source_relocation_sync_marker_relative_path(transaction)?;
    let path = git.common_dir().join(&relative);
    let marker = planned_proof_source_relocation_sync_marker(transaction, seal_commit);
    let bytes = serde_yaml::to_string(&marker)
        .map_err(|source| KoniError::Yaml {
            path: path.clone(),
            source,
        })?
        .into_bytes();
    write_persistent_file(
        git.common_dir(),
        &relative,
        &bytes,
        MAX_PLANNED_PROOF_SOURCE_RELOCATION_SYNC_MARKER_BYTES,
    )
    .map_err(|error| io_error(&path, error))
}

fn planned_proof_source_relocation_transaction(
    store: &StateStore,
    request_hash: &str,
) -> Result<Option<PlannedProofSourceRelocationTransaction>> {
    let path = planned_proof_source_relocation_transaction_path(store, request_hash)?;
    read_optional_yaml_value(&path)?
        .map(|value| {
            serde_json::from_value::<PlannedProofSourceRelocationTransaction>(value).map_err(
                |error| {
                    KoniError::Action(format!(
                        "planned-proof source relocation transaction {} is unreadable: {error}",
                        path.display()
                    ))
                },
            )
        })
        .transpose()
}

fn planned_proof_source_relocation_transactions(
    store: &StateStore,
) -> Result<Vec<PlannedProofSourceRelocationTransaction>> {
    let root = store
        .root()
        .join("recovery/planned-proof-source-relocation");
    if !root.exists() {
        return Ok(Vec::new());
    }
    let mut transactions = Vec::new();
    for entry in fs::read_dir(&root).map_err(|error| io_error(&root, error))? {
        let entry = entry.map_err(|error| io_error(&root, error))?;
        let path = entry.path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("yaml") {
            continue;
        }
        let value = read_optional_yaml_value(&path)?.ok_or_else(|| {
            KoniError::Action(format!(
                "planned-proof source relocation transaction disappeared: {}",
                path.display()
            ))
        })?;
        transactions.push(
            serde_json::from_value::<PlannedProofSourceRelocationTransaction>(value).map_err(
                |error| {
                    KoniError::Action(format!(
                        "planned-proof source relocation transaction {} is unreadable: {error}",
                        path.display()
                    ))
                },
            )?,
        );
    }
    transactions.sort_by(|left, right| left.id.cmp(&right.id));
    Ok(transactions)
}

fn value_contains_exact_string(value: &Value, expected: &str) -> bool {
    match value {
        Value::String(value) => value == expected,
        Value::Array(values) => values
            .iter()
            .any(|value| value_contains_exact_string(value, expected)),
        Value::Object(values) => values
            .values()
            .any(|value| value_contains_exact_string(value, expected)),
        Value::Null | Value::Bool(_) | Value::Number(_) => false,
    }
}

fn relocated_planned_proof_node(
    base: &Node,
    old_source_path: &str,
    new_source_path: &str,
    old_command_argument: &str,
    new_command_argument: &str,
) -> Result<Node> {
    let mut amended = base.clone();
    let source_paths = amended
        .spec
        .get_mut("source_paths")
        .and_then(Value::as_array_mut)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation requires a list<Path> source_paths field"
                    .to_owned(),
            )
        })?;
    let source_matches = source_paths
        .iter()
        .filter(|value| value.as_str() == Some(old_source_path))
        .count();
    if source_matches != 1 {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation expected one exact source_paths occurrence, found {source_matches}"
        )));
    }
    for value in source_paths {
        if value.as_str() == Some(old_source_path) {
            *value = Value::String(new_source_path.to_owned());
        }
    }

    let command = amended
        .spec
        .get_mut("command")
        .and_then(Value::as_array_mut)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation requires a list<String> command field".to_owned(),
            )
        })?;
    let command_matches = command
        .iter()
        .filter(|value| value.as_str() == Some(old_command_argument))
        .count();
    if command_matches != 1 {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation expected one exact command argument occurrence, found {command_matches}"
        )));
    }
    for value in command {
        if value.as_str() == Some(old_command_argument) {
            *value = Value::String(new_command_argument.to_owned());
        }
    }
    Ok(amended)
}

fn planned_proof_source_relocation_ticket_fixed_identity(ticket: &Ticket) -> Value {
    let workflow = ticket
        .workflow
        .iter()
        .map(|step| {
            json!({
                "id": step.id,
                "persona": step.persona,
                "depends_on": step.depends_on,
                "required": step.required,
                "kind": step.kind,
                "read_nodes": step.read_nodes,
                "write_nodes": step.write_nodes,
                "preserve_source_paths_from": step.preserve_source_paths_from,
                "expected_outputs": step.expected_outputs,
                "graph_mutation": step.graph_mutation,
                "required_receipts": step.required_receipts,
                "validation_checks": step.validation_checks,
                "escalation_triggers": step.escalation_triggers,
                "stop_conditions": step.stop_conditions,
                "validation_action": step.validation_action,
            })
        })
        .collect::<Vec<_>>();
    let mut extensions = ticket.extensions.clone();
    extensions.remove(PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION);
    json!({
        "schema_version": ticket.schema_version,
        "id": ticket.id,
        "operation": ticket.operation,
        "status": ticket.status,
        "title": ticket.title,
        "target_nodes": ticket.target_nodes,
        "read_nodes": ticket.scope.read_nodes,
        "write_nodes": ticket.scope.write_nodes,
        "source_state_key": ticket.source_state_key,
        "target_state_key": ticket.target_state_key,
        "obligation_keys": ticket.obligation_keys,
        "profile_hash": ticket.profile_hash,
        "rule_id": ticket.rule_id,
        "workflow": workflow,
        "extensions": extensions,
    })
}

fn relocated_planned_proof_path_set(
    root: &Path,
    paths: &BTreeSet<String>,
    old_source_path: &str,
    new_source_path: &str,
) -> Result<(BTreeSet<String>, usize)> {
    let mut relocated = BTreeSet::new();
    let mut replacements = 0;
    for path in paths {
        if project_authority_paths_equal(root, path, old_source_path)? {
            relocated.insert(new_source_path.to_owned());
            replacements += 1;
        } else {
            if project_authority_paths_equal(root, path, new_source_path)? {
                return Err(KoniError::Action(
                    "planned-proof source relocation blocked candidate already contains the new source path"
                        .to_owned(),
                ));
            }
            relocated.insert(path.clone());
        }
    }
    Ok((relocated, replacements))
}

fn relocated_planned_proof_command(
    argv: &[String],
    old_argument: &str,
    new_argument: &str,
) -> Result<(Vec<String>, usize)> {
    if argv.iter().any(|argument| argument == new_argument) {
        return Err(KoniError::Action(
            "planned-proof source relocation blocked compiled command already contains the new argument"
                .to_owned(),
        ));
    }
    let mut replacements = 0;
    let relocated = argv
        .iter()
        .map(|argument| {
            if argument == old_argument {
                replacements += 1;
                new_argument.to_owned()
            } else {
                argument.clone()
            }
        })
        .collect();
    Ok((relocated, replacements))
}

struct PlannedProofSourceRelocationTransform<'a> {
    root: &'a Path,
    proof_node_id: &'a str,
    old_source_path: &'a str,
    new_source_path: &'a str,
    old_command_argument: &'a str,
    new_command_argument: &'a str,
    base_semantic_hash: &'a str,
    amended_semantic_hash: &'a str,
}

fn planned_proof_source_relocation_compiled_checks_match(
    blocked_step: &Step,
    expected_step: &Step,
    transform: &PlannedProofSourceRelocationTransform<'_>,
) -> Result<bool> {
    if blocked_step.compiled_check_sets.len() != expected_step.compiled_check_sets.len() {
        return Ok(false);
    }
    for (blocked_set, expected_set) in blocked_step
        .compiled_check_sets
        .iter()
        .zip(&expected_step.compiled_check_sets)
    {
        let mut relocated_set = blocked_set.clone();
        let mut set_touched = false;
        if let Some(anchor_hash) = relocated_set.anchor_hashes.get_mut(transform.proof_node_id) {
            if anchor_hash != transform.base_semantic_hash {
                return Ok(false);
            }
            *anchor_hash = transform.amended_semantic_hash.to_owned();
            set_touched = true;
        }
        for relocated_member in &mut relocated_set.members {
            if relocated_member.source_node_id != transform.proof_node_id {
                continue;
            }
            if relocated_member.source_semantic_hash != transform.base_semantic_hash {
                return Ok(false);
            }
            let (argv, argument_replacements) = relocated_planned_proof_command(
                &relocated_member.argv,
                transform.old_command_argument,
                transform.new_command_argument,
            )?;
            let (source_paths, source_replacements) = relocated_planned_proof_path_set(
                transform.root,
                &relocated_member.source_paths,
                transform.old_source_path,
                transform.new_source_path,
            )?;
            let (covered_paths, _) = relocated_planned_proof_path_set(
                transform.root,
                &relocated_member.covered_paths,
                transform.old_source_path,
                transform.new_source_path,
            )?;
            if argument_replacements != 1 || source_replacements != 1 {
                return Ok(false);
            }
            relocated_member.argv = argv;
            relocated_member.source_paths = source_paths;
            relocated_member.covered_paths = covered_paths;
            relocated_member.source_semantic_hash = transform.amended_semantic_hash.to_owned();
            relocated_member.contract_hash.clear();
            relocated_member.contract_hash = normalized_hash(relocated_member);
            set_touched = true;
        }
        if set_touched {
            relocated_set.selection_hash = normalized_hash(
                &relocated_set
                    .members
                    .iter()
                    .map(|member| {
                        (
                            member.source_node_id.as_str(),
                            member.child_check_id.as_str(),
                            member.contract_hash.as_str(),
                        )
                    })
                    .collect::<Vec<_>>(),
            );
            relocated_set.contract_hash.clear();
            relocated_set.contract_hash = normalized_hash(&relocated_set);
        }
        if &relocated_set != expected_set {
            return Ok(false);
        }
    }
    Ok(true)
}

fn planned_proof_source_relocation_path_authority_matches(
    blocked: &Ticket,
    expected: &Ticket,
    transform: &PlannedProofSourceRelocationTransform<'_>,
) -> Result<bool> {
    let (read_paths, _) = relocated_planned_proof_path_set(
        transform.root,
        &blocked.scope.read_paths,
        transform.old_source_path,
        transform.new_source_path,
    )?;
    let (write_paths, ticket_write_replacements) = relocated_planned_proof_path_set(
        transform.root,
        &blocked.scope.write_paths,
        transform.old_source_path,
        transform.new_source_path,
    )?;
    if read_paths != expected.scope.read_paths
        || write_paths != expected.scope.write_paths
        || ticket_write_replacements != 1
        || blocked.workflow.len() != expected.workflow.len()
    {
        return Ok(false);
    }
    for (blocked_step, expected_step) in blocked.workflow.iter().zip(&expected.workflow) {
        if blocked_step.id != expected_step.id {
            return Ok(false);
        }
        let relocated_read = blocked_step
            .read_paths
            .as_ref()
            .map(|paths| {
                relocated_planned_proof_path_set(
                    transform.root,
                    paths,
                    transform.old_source_path,
                    transform.new_source_path,
                )
                .map(|(paths, _)| paths)
            })
            .transpose()?;
        let relocated_write = blocked_step
            .write_paths
            .as_ref()
            .map(|paths| {
                relocated_planned_proof_path_set(
                    transform.root,
                    paths,
                    transform.old_source_path,
                    transform.new_source_path,
                )
                .map(|(paths, _)| paths)
            })
            .transpose()?;
        if relocated_read != expected_step.read_paths
            || relocated_write != expected_step.write_paths
            || !planned_proof_source_relocation_compiled_checks_match(
                blocked_step,
                expected_step,
                transform,
            )?
            || expected_step.context_hash
                != planned_proof_source_relocation_step_context_hash(expected, expected_step)
        {
            return Ok(false);
        }
    }

    let blocked_binding = blocked
        .extensions
        .get(PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION)
        .cloned()
        .map(|value| {
            serde_json::from_value::<ProofSourceWriteAuthorityBinding>(value).map_err(|error| {
                KoniError::Action(format!(
                    "planned-proof source relocation blocked ticket has an invalid proof-source authority binding: {error}"
                ))
            })
        })
        .transpose()?;
    let expected_binding = expected
        .extensions
        .get(PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION)
        .cloned()
        .map(|value| {
            serde_json::from_value::<ProofSourceWriteAuthorityBinding>(value).map_err(|error| {
                KoniError::Action(format!(
                    "planned-proof source relocation staged ticket has an invalid proof-source authority binding: {error}"
                ))
            })
        })
        .transpose()?;
    let relocated_binding = blocked_binding
        .map(|mut binding| -> Result<ProofSourceWriteAuthorityBinding> {
            for grant in &mut binding.grants {
                if project_authority_paths_equal(
                    transform.root,
                    &grant.path,
                    transform.old_source_path,
                )? {
                    grant.path = transform.new_source_path.to_owned();
                } else if project_authority_paths_equal(
                    transform.root,
                    &grant.path,
                    transform.new_source_path,
                )? {
                    return Err(KoniError::Action(
                        "planned-proof source relocation blocked proof-source binding already contains the new path"
                            .to_owned(),
                    ));
                }
            }
            binding.binding_hash = proof_source_write_authority_hash(&binding);
            Ok(binding)
        })
        .transpose()?;
    Ok(relocated_binding == expected_binding)
}

fn planned_proof_source_relocation_step_context_hash(ticket: &Ticket, step: &Step) -> String {
    let legacy_context = (
        ticket.id.as_str(),
        step.id.as_str(),
        &ticket.scope.read_nodes,
        &ticket.scope.write_nodes,
        &ticket.scope.read_paths,
        &ticket.scope.write_paths,
        &step.read_paths,
        &step.write_paths,
        &ticket.profile_hash,
    );
    if step.compiled_check_sets.is_empty()
        && step.preserve_source_paths_from.is_none()
        && step.read_nodes.is_none()
        && step.write_nodes.is_none()
    {
        normalized_hash(&legacy_context)
    } else {
        normalized_hash(&(
            legacy_context,
            &step.compiled_check_sets,
            &step.preserve_source_paths_from,
            &step.read_nodes,
            &step.write_nodes,
        ))
    }
}

fn full_compile_event_bindings(
    store: &StateStore,
    run_id: &str,
) -> Result<BTreeMap<String, String>> {
    Ok(store
        .events()?
        .into_iter()
        .filter(|event| event.run_id == run_id && event.event_type == "compiler.compile.full")
        .map(|event| (event.id.clone(), normalized_hash(&event)))
        .collect())
}

fn expected_planned_proof_source_relocation_compile_event_data(
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Value {
    json!({
        "graph_hash": transaction.expected_compiled_graph_hash,
        "derived_tickets": transaction.expected_derived_ticket_ids,
    })
}

fn planned_proof_source_relocation_full_compile_event(
    store: &StateStore,
    run: &RunManifest,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<Option<Event>> {
    let events = store
        .events()?
        .into_iter()
        .filter(|event| event.run_id == run.id && event.event_type == "compiler.compile.full")
        .collect::<Vec<_>>();
    for (event_id, event_hash) in &transaction.base_full_compile_events {
        if events
            .iter()
            .find(|event| &event.id == event_id)
            .is_none_or(|event| normalized_hash(event) != *event_hash)
        {
            return Err(KoniError::Action(
                "planned-proof source relocation lost or changed its pre-transaction full-compile history"
                    .to_owned(),
            ));
        }
    }
    if let (Some(event_id), Some(event_hash)) = (
        transaction.full_compile_event_id.as_deref(),
        transaction.full_compile_event_hash.as_deref(),
    ) {
        let event = events
            .into_iter()
            .find(|event| event.id == event_id)
            .ok_or_else(|| {
                KoniError::Action(
                    "planned-proof source relocation lost its sealed full-compile completion"
                        .to_owned(),
                )
            })?;
        if normalized_hash(&event) != event_hash
            || event.schema_version != "1.0"
            || event.ticket_id.is_some()
            || event.actor != "compiler"
            || event.data
                != expected_planned_proof_source_relocation_compile_event_data(transaction)
        {
            return Err(KoniError::Action(
                "planned-proof source relocation sealed full-compile completion changed".to_owned(),
            ));
        }
        return Ok(Some(event));
    }
    let mut added = events
        .into_iter()
        .filter(|event| !transaction.base_full_compile_events.contains_key(&event.id))
        .collect::<Vec<_>>();
    if added.len() > 1 {
        return Err(KoniError::Action(
            "planned-proof source relocation found multiple unbound full-compile completions"
                .to_owned(),
        ));
    }
    let Some(event) = added.pop() else {
        if transaction.full_compile_event_id.is_some()
            || transaction.full_compile_event_hash.is_some()
        {
            return Err(KoniError::Action(
                "planned-proof source relocation lost its sealed full-compile completion"
                    .to_owned(),
            ));
        }
        return Ok(None);
    };
    if event.schema_version != "1.0"
        || event.ticket_id.is_some()
        || event.actor != "compiler"
        || event.data != expected_planned_proof_source_relocation_compile_event_data(transaction)
    {
        return Err(KoniError::Action(
            "planned-proof source relocation full-compile completion does not match its staged graph and ticket set"
                .to_owned(),
        ));
    }
    Ok(Some(event))
}

fn validate_duplicate_planned_proof_source_relocation_event(
    event: &Event,
    request: &PlannedProofSourceRelocationRequest,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<()> {
    let duplicate_request = planned_proof_source_relocation_request(event)?;
    let targets = event
        .data
        .get("target_nodes")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|target| target.as_str().map(ToOwned::to_owned))
        .collect::<Option<BTreeSet<_>>>()
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation duplicate has invalid target_nodes".to_owned(),
            )
        })?;
    if event.event_type != "compiler.steering.recorded"
        || event.data.get("kind").and_then(Value::as_str)
            != Some(PLANNED_PROOF_SOURCE_RELOCATION_KIND)
        || event.ticket_id.as_deref()
            != Some(transaction.conflicting_preparation_ticket_id.as_str())
        || event.data.get("ticket_id").and_then(Value::as_str)
            != Some(transaction.conflicting_preparation_ticket_id.as_str())
        || duplicate_request != *request
        || targets != BTreeSet::from([transaction.proof_node_id.clone()])
    {
        return Err(KoniError::Action(
            "planned-proof source relocation duplicate conflicts with the transaction-owning request"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_planned_proof_source_relocation_transaction(
    transaction: &PlannedProofSourceRelocationTransaction,
    owner: &Event,
    profile: &CompiledProfile,
) -> Result<()> {
    let request = planned_proof_source_relocation_request(owner)?;
    validate_duplicate_planned_proof_source_relocation_event(owner, &request, transaction)?;
    let steer_action = profile.action("steer").ok_or_else(|| {
        KoniError::Profile(
            "planned-proof source relocation requires a configured steer action".to_owned(),
        )
    })?;
    let expected_action_input = action_retry_input_hash(
        steer_action,
        &planned_proof_source_relocation_action_params(owner)?,
    );
    let status_has_compile = matches!(transaction.status.as_str(), "compiled" | "complete");
    let status_is_complete = transaction.status == "complete";
    if transaction.schema_version != "1.0"
        || !matches!(
            transaction.status.as_str(),
            "prepared" | "graph_published" | "compiled" | "complete"
        )
        || status_is_complete != transaction.completed_at.is_some()
        || status_has_compile != transaction.full_compile_event_id.is_some()
        || status_has_compile != transaction.full_compile_event_hash.is_some()
        || transaction.profile_hash != profile.hash
        || owner.schema_version != "1.0"
        || owner.actor != "lead"
        || transaction.run_id != owner.run_id
        || transaction.request_event_id != owner.id
        || transaction.request_event_hash != normalized_hash(owner)
        || transaction.request_action_journal_id != transaction.request_action_journal.id
        || transaction.request_action_journal_hash
            != normalized_hash(&transaction.request_action_journal)
        || transaction.request_action_journal.action != steer_action.id
        || transaction.request_action_journal.profile_hash != profile.hash
        || transaction.request_action_journal.input_hash.as_deref()
            != Some(expected_action_input.as_str())
        || owner
            .data
            .get("compiler_transaction_action")
            .and_then(Value::as_str)
            != Some(steer_action.id.as_str())
        || owner
            .data
            .get("compiler_transaction_journal")
            .and_then(Value::as_str)
            != Some(transaction.request_action_journal_id.as_str())
        || transaction.request_hash != normalized_hash(&request)
        || transaction.failed_compile_journal_id != transaction.failed_compile_journal.id
        || transaction.failed_compile_journal_hash
            != normalized_hash(&transaction.failed_compile_journal)
        || transaction.failed_compile_input_hash
            != normalized_hash(&transaction.failed_compile_journal.input_hash)
        || transaction.failed_compile_error_hash
            != normalized_hash(&transaction.failed_compile_journal.error)
        || transaction.failed_compile_journal.status != JournalStatus::Failed
        || transaction.failed_compile_journal.action != "compile"
        || transaction.base_node_hash != normalized_hash(&transaction.base_node)
        || transaction.amended_node_hash != normalized_hash(&transaction.amended_node)
        || transaction.base_node.id != transaction.proof_node_id
        || transaction.amended_node.id != transaction.proof_node_id
        || transaction.conflicting_preparation_hash
            != normalized_hash(&transaction.conflicting_preparation)
        || transaction.conflicting_preparation_ticket_id
            != transaction.conflicting_preparation.ticket_id
        || transaction.conflicting_preparation_node_id
            != transaction.conflicting_preparation.source_node_id
        || transaction.expected_ticket_id != transaction.expected_ticket.id
        || transaction.expected_rule_id != transaction.expected_ticket.rule_id
        || transaction.expected_ticket_hash != normalized_hash(&transaction.expected_ticket)
        || transaction.blocked_candidate_hash != normalized_hash(&transaction.blocked_candidate)
        || transaction.blocked_candidate.id != transaction.expected_ticket_id
        || transaction.blocked_candidate.rule_id != transaction.expected_rule_id
        || planned_proof_source_relocation_ticket_fixed_identity(&transaction.blocked_candidate)
            != planned_proof_source_relocation_ticket_fixed_identity(&transaction.expected_ticket)
        || !transaction
            .expected_derived_ticket_ids
            .contains(&transaction.expected_ticket_id)
        || request.failed_compile_journal_id != transaction.failed_compile_journal_id
        || request.proof_node_id != transaction.proof_node_id
        || request.old_source_path != transaction.old_source_path
        || request.new_source_path != transaction.new_source_path
        || request.expected_rule_id != transaction.expected_rule_id
        || request.expected_ticket_id != transaction.expected_ticket_id
        || planned_proof_source_relocation_transaction_hash(transaction)
            != transaction.transaction_hash
    {
        return Err(KoniError::Action(
            "planned-proof source relocation transaction failed its compiler-owned integrity binding"
                .to_owned(),
        ));
    }
    let reconstructed = relocated_planned_proof_node(
        &transaction.base_node,
        &transaction.old_source_path,
        &transaction.new_source_path,
        &transaction.old_command_argument,
        &transaction.new_command_argument,
    )?;
    if normalized_hash(&reconstructed) != transaction.amended_node_hash {
        return Err(KoniError::Action(
            "planned-proof source relocation transaction contains graph changes beyond the exact source path and command argument"
                .to_owned(),
        ));
    }
    Ok(())
}

fn planned_proof_source_relocation_completion_event_data(
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Value {
    json!({
        "transaction_id": transaction.id,
        "transaction_hash": transaction.transaction_hash,
        "request_hash": transaction.request_hash,
        "proof_node_id": transaction.proof_node_id,
        "old_source_path": transaction.old_source_path,
        "new_source_path": transaction.new_source_path,
        "conflicting_preparation_ticket_id": transaction.conflicting_preparation_ticket_id,
        "conflicting_preparation_node_id": transaction.conflicting_preparation_node_id,
        "failed_compile_journal_id": transaction.failed_compile_journal_id,
        "expected_rule_id": transaction.expected_rule_id,
        "expected_ticket_id": transaction.expected_ticket_id,
        "base_graph_hash": transaction.base_graph_hash,
        "amended_graph_hash": transaction.amended_graph_hash,
        "expected_compiled_graph_hash": transaction.expected_compiled_graph_hash,
        "full_compile_event_id": transaction.full_compile_event_id,
        "full_compile_event_hash": transaction.full_compile_event_hash,
        "integration_ref": transaction.integration_ref,
        "integration_head": transaction.integration_head,
        "authority_changed": true,
        "write_authority_changed": true,
    })
}

fn completed_planned_proof_source_relocation_event<'a>(
    events: &'a [Event],
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<Option<&'a Event>> {
    let matches = events
        .iter()
        .filter(|event| {
            event.event_type == PLANNED_PROOF_SOURCE_RELOCATION_EVENT_TYPE
                && (event.data.get("transaction_id").and_then(Value::as_str)
                    == Some(transaction.id.as_str())
                    || event.data.get("request_hash").and_then(Value::as_str)
                        == Some(transaction.request_hash.as_str()))
        })
        .collect::<Vec<_>>();
    if matches.len() > 1 {
        return Err(KoniError::Action(
            "planned-proof source relocation completion event is duplicated".to_owned(),
        ));
    }
    Ok(matches.first().copied())
}

/// Prove that a compiler-owned checkpoint published only its named authority
/// files (plus removal of configured transient tree entries) and that every
/// named file is byte-for-byte identical to the durable worktree poststate.
/// The explicit tree comparison closes both racy-clean status gaps and any
/// accidental broad-index additions that a status-derived path list could
/// otherwise fail to report.
fn validate_planned_proof_source_relocation_checkpoint_tree(
    git: &GitBackend,
    commit_id: &str,
    checkpoint: Option<&CheckpointCommit>,
    required_paths: &[PathBuf],
    required_changed_paths: &[PathBuf],
    tree_excluded_paths: &[PathBuf],
    phase: &str,
) -> Result<()> {
    let repository = git2::Repository::discover(git.workdir())?;
    let commit_oid = Oid::from_str(commit_id).map_err(KoniError::Git)?;
    let commit = repository.find_commit(commit_oid)?;
    let tree = commit.tree()?;
    ensure_planned_proof_source_relocation_tree_exclusions_absent(
        &tree,
        tree_excluded_paths,
        phase,
    )?;
    if commit.parent_count() != 1 {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation {phase} checkpoint is not a single-parent commit"
        )));
    }
    if let Some(checkpoint) = checkpoint
        && (checkpoint.commit != commit_id
            || checkpoint.tree != tree.id().to_string()
            || checkpoint.parent != commit.parent_id(0)?.to_string())
    {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation {phase} checkpoint record disagrees with its Git commit"
        )));
    }
    let parent_tree = commit.parent(0)?.tree()?;
    let diff = repository.diff_tree_to_tree(Some(&parent_tree), Some(&tree), None)?;
    let mut actual_changed_paths = BTreeSet::new();
    for delta in diff.deltas() {
        if let Some(path) = delta.old_file().path() {
            actual_changed_paths.insert(path.to_path_buf());
        }
        if let Some(path) = delta.new_file().path() {
            actual_changed_paths.insert(path.to_path_buf());
        }
    }
    let required_path_set = required_paths.iter().cloned().collect::<BTreeSet<_>>();
    let required_changed_path_set = required_changed_paths
        .iter()
        .cloned()
        .collect::<BTreeSet<_>>();
    if !required_changed_path_set.is_subset(&required_path_set) {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation {phase} checkpoint change contract escapes its authority paths"
        )));
    }
    let path_is_allowed = |path: &Path| {
        required_path_set.contains(path)
            || tree_excluded_paths
                .iter()
                .any(|excluded| path == excluded || path.starts_with(excluded))
    };
    let unexpected = actual_changed_paths
        .iter()
        .filter(|path| !path_is_allowed(path))
        .cloned()
        .collect::<Vec<_>>();
    if !unexpected.is_empty() {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation {phase} checkpoint contains unrelated tree changes: {}",
            unexpected
                .iter()
                .map(|path| path.display().to_string())
                .collect::<Vec<_>>()
                .join(", ")
        )));
    }
    let missing_required_changes = required_changed_path_set
        .difference(&actual_changed_paths)
        .cloned()
        .collect::<Vec<_>>();
    if !missing_required_changes.is_empty() {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation {phase} checkpoint did not introduce required authority changes: {}",
            missing_required_changes
                .iter()
                .map(|path| path.display().to_string())
                .collect::<Vec<_>>()
                .join(", ")
        )));
    }
    if let Some(checkpoint) = checkpoint {
        let unexpected_recorded = checkpoint
            .changed_paths
            .iter()
            .filter(|path| !path_is_allowed(path))
            .cloned()
            .collect::<Vec<_>>();
        if !unexpected_recorded.is_empty() {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation {phase} checkpoint recorded unrelated changed paths: {}",
                unexpected_recorded
                    .iter()
                    .map(|path| path.display().to_string())
                    .collect::<Vec<_>>()
                    .join(", ")
            )));
        }
    }
    for path in required_paths {
        let absolute = git.workdir().join(path);
        let metadata =
            fs::symlink_metadata(&absolute).map_err(|error| io_error(&absolute, error))?;
        if !metadata.file_type().is_file() {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation {phase} authority path is not a regular file: {}",
                path.display()
            )));
        }
        let entry = tree.get_path(path).map_err(|error| {
            KoniError::Action(format!(
                "planned-proof source relocation {phase} checkpoint lost authority path {}: {error}",
                path.display()
            ))
        })?;
        if entry.kind() != Some(git2::ObjectType::Blob) {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation {phase} checkpoint authority is not a blob: {}",
                path.display()
            )));
        }
        let current = fs::read(&absolute).map_err(|error| io_error(&absolute, error))?;
        if repository.find_blob(entry.id())?.content() != current {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation {phase} checkpoint does not byte-bind current authority path {}",
                path.display()
            )));
        }
    }
    Ok(())
}

fn planned_proof_source_relocation_checkpoint_binds_current_authority(
    git: &GitBackend,
    commit_id: &str,
    required_paths: &[PathBuf],
) -> Result<bool> {
    let repository = git2::Repository::discover(git.workdir())?;
    let commit = repository.find_commit(Oid::from_str(commit_id).map_err(KoniError::Git)?)?;
    let tree = commit.tree()?;
    for path in required_paths {
        let absolute = git.workdir().join(path);
        let metadata =
            fs::symlink_metadata(&absolute).map_err(|error| io_error(&absolute, error))?;
        if !metadata.file_type().is_file() {
            return Err(KoniError::Action(format!(
                "planned-proof source relocation authority path is not a regular file: {}",
                path.display()
            )));
        }
        let entry = match tree.get_path(path) {
            Ok(entry) => entry,
            Err(error) if error.code() == git2::ErrorCode::NotFound => return Ok(false),
            Err(error) => return Err(KoniError::Git(error)),
        };
        if entry.kind() != Some(git2::ObjectType::Blob) {
            return Ok(false);
        }
        let current = fs::read(&absolute).map_err(|error| io_error(&absolute, error))?;
        if repository.find_blob(entry.id())?.content() != current {
            return Ok(false);
        }
    }
    Ok(true)
}

fn ensure_planned_proof_source_relocation_tree_exclusions_absent(
    tree: &git2::Tree<'_>,
    tree_excluded_paths: &[PathBuf],
    phase: &str,
) -> Result<()> {
    for path in tree_excluded_paths {
        match tree.get_path(path) {
            Ok(_) => {
                return Err(KoniError::Action(format!(
                    "planned-proof source relocation {phase} checkpoint retained tree-excluded authority at {}",
                    path.display()
                )));
            }
            Err(error) if error.code() == git2::ErrorCode::NotFound => {}
            Err(error) => return Err(KoniError::Git(error)),
        }
    }
    Ok(())
}

fn planned_proof_source_relocation_tracked_checkpoint_commit(
    profile: &CompiledProfile,
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<Option<String>> {
    if profile.manifest.storage.backend != StorageBackend::Tracked {
        return Ok(None);
    }
    let repository = git2::Repository::discover(store.root())?;
    let workdir = repository.workdir().ok_or_else(|| {
        KoniError::Action(
            "planned-proof source relocation tracked checkpoint has no repository worktree"
                .to_owned(),
        )
    })?;
    let graph_path = store
        .graph_dir()
        .join(&transaction.amended_node.node_type)
        .join(format!(
            "{}--{}.yaml",
            slugify(&transaction.amended_node.title),
            transaction.amended_node.id
        ));
    let transaction_path =
        planned_proof_source_relocation_transaction_path(store, &transaction.request_hash)?;
    let events_path = store.root().join("events.jsonl");
    let action_journal_path = store
        .root()
        .join("journals")
        .join(format!("{}.yaml", transaction.request_action_journal_id));
    let failed_journal_path = store
        .root()
        .join("journals")
        .join(format!("{}.yaml", transaction.failed_compile_journal_id));
    let ticket_path = store.ticket_path(&transaction.expected_ticket);
    let relative = |path: &Path| {
        path.strip_prefix(workdir).map(Path::to_path_buf).map_err(|_| {
            KoniError::Action(format!(
                "planned-proof source relocation tracked checkpoint path {} is outside repository {}",
                path.display(),
                workdir.display()
            ))
        })
    };
    let transaction_path = relative(&transaction_path)?;
    let events_path = relative(&events_path)?;
    let action_journal_path = relative(&action_journal_path)?;
    let failed_journal_path = relative(&failed_journal_path)?;
    let ticket_path = relative(&ticket_path)?;
    let graph_path = relative(&graph_path)?;
    let required_paths = BTreeSet::from([
        transaction_path.clone(),
        events_path.clone(),
        action_journal_path.clone(),
        failed_journal_path.clone(),
        ticket_path.clone(),
        graph_path.clone(),
    ]);
    let expected_changed_paths = BTreeSet::from([
        transaction_path.clone(),
        events_path.clone(),
        failed_journal_path.clone(),
        ticket_path.clone(),
        graph_path.clone(),
    ]);
    let tree_excluded_paths = tracked_state_tree_exclusions(profile, workdir)?;
    let integration_head = Oid::from_str(&transaction.integration_head).map_err(KoniError::Git)?;
    let tip = repository
        .find_reference(&transaction.integration_ref)?
        .peel_to_commit()?;
    if tip.id() == integration_head
        || !repository.graph_descendant_of(tip.id(), integration_head)?
    {
        return Ok(None);
    }
    let mut first_parent_checkpoint_ids = Vec::new();
    let mut cursor = tip;
    while cursor.id() != integration_head {
        first_parent_checkpoint_ids.push(cursor.id());
        if cursor.parent_count() == 0 {
            return Ok(None);
        }
        cursor = cursor.parent(0)?;
    }
    for checkpoint_id in first_parent_checkpoint_ids {
        let cursor = repository.find_commit(checkpoint_id)?;
        if cursor.parent_count() != 1 || cursor.parent_id(0)? != integration_head {
            continue;
        }
        let tree = cursor.tree()?;
        ensure_planned_proof_source_relocation_tree_exclusions_absent(
            &tree,
            &tree_excluded_paths,
            "historical final",
        )?;
        let parent_tree = cursor.parent(0)?.tree()?;
        let diff = repository.diff_tree_to_tree(Some(&parent_tree), Some(&tree), None)?;
        let mut changed_paths = BTreeSet::new();
        for delta in diff.deltas() {
            if let Some(path) = delta.old_file().path() {
                changed_paths.insert(path.to_path_buf());
            }
            if let Some(path) = delta.new_file().path() {
                changed_paths.insert(path.to_path_buf());
            }
        }
        let outside_authority = changed_paths.iter().any(|path| {
            !required_paths.contains(path)
                && !tree_excluded_paths
                    .iter()
                    .any(|excluded| path == excluded || path.starts_with(excluded))
        });
        let changed_authority = changed_paths
            .iter()
            .filter(|path| required_paths.contains(*path))
            .cloned()
            .collect::<BTreeSet<_>>();
        if outside_authority || changed_authority != expected_changed_paths {
            continue;
        }
        let blob_at = |path: &Path| -> Result<Option<Vec<u8>>> {
            let entry = match tree.get_path(path) {
                Ok(entry) => entry,
                Err(error) if error.code() == git2::ErrorCode::NotFound => return Ok(None),
                Err(error) => return Err(KoniError::Git(error)),
            };
            if entry.kind() != Some(git2::ObjectType::Blob) {
                return Ok(None);
            }
            Ok(Some(repository.find_blob(entry.id())?.content().to_vec()))
        };
        let candidate_matches = (|| -> Result<bool> {
            let Some(transaction_bytes) = blob_at(&transaction_path)? else {
                return Ok(false);
            };
            let checkpoint_transaction: PlannedProofSourceRelocationTransaction =
                serde_yaml::from_slice(&transaction_bytes).map_err(|source| KoniError::Yaml {
                    path: transaction_path.clone(),
                    source,
                })?;
            if normalized_hash(&checkpoint_transaction) != normalized_hash(transaction) {
                return Ok(false);
            }
            let Some(action_journal_bytes) = blob_at(&action_journal_path)? else {
                return Ok(false);
            };
            let action_journal: Journal =
                serde_yaml::from_slice(&action_journal_bytes).map_err(|source| {
                    KoniError::Yaml {
                        path: action_journal_path.clone(),
                        source,
                    }
                })?;
            if normalized_hash(&action_journal) != transaction.request_action_journal_hash {
                return Ok(false);
            }
            let Some(failed_journal_bytes) = blob_at(&failed_journal_path)? else {
                return Ok(false);
            };
            let recovered_journal: Journal = serde_yaml::from_slice(&failed_journal_bytes)
                .map_err(|source| KoniError::Yaml {
                    path: failed_journal_path.clone(),
                    source,
                })?;
            let mut expected_recovered = transaction.failed_compile_journal.clone();
            expected_recovered.status = JournalStatus::Recovered;
            if normalized_hash(&recovered_journal) != normalized_hash(&expected_recovered) {
                return Ok(false);
            }
            let Some(ticket_bytes) = blob_at(&ticket_path)? else {
                return Ok(false);
            };
            let ticket: Ticket =
                serde_yaml::from_slice(&ticket_bytes).map_err(|source| KoniError::Yaml {
                    path: ticket_path.clone(),
                    source,
                })?;
            if normalized_hash(&ticket) != transaction.expected_ticket_hash {
                return Ok(false);
            }
            let Some(graph_bytes) = blob_at(&graph_path)? else {
                return Ok(false);
            };
            let node: Node =
                serde_yaml::from_slice(&graph_bytes).map_err(|source| KoniError::Yaml {
                    path: graph_path.clone(),
                    source,
                })?;
            if normalized_hash(&node) != transaction.amended_node_hash {
                return Ok(false);
            }
            let Some(events_bytes) = blob_at(&events_path)? else {
                return Ok(false);
            };
            let events = BufReader::new(events_bytes.as_slice())
                .lines()
                .filter(|line| line.as_ref().is_ok_and(|line| !line.trim().is_empty()))
                .map(|line| {
                    let line = line.map_err(|error| io_error(&events_path, error))?;
                    serde_json::from_str::<Event>(&line).map_err(|source| KoniError::Json {
                        path: events_path.clone(),
                        source,
                    })
                })
                .collect::<Result<Vec<_>>>()?;
            let completion = completed_planned_proof_source_relocation_event(&events, transaction)?;
            let owner = events
                .iter()
                .find(|event| event.id == transaction.request_event_id);
            let full_compile = transaction
                .full_compile_event_id
                .as_deref()
                .and_then(|id| events.iter().find(|event| event.id == id));
            let events_match = completion.is_some_and(|event| {
                event.schema_version == "1.0"
                    && event.run_id == transaction.run_id
                    && event.actor == "compiler"
                    && event.ticket_id.as_deref()
                        == Some(transaction.conflicting_preparation_ticket_id.as_str())
                    && event.data
                        == planned_proof_source_relocation_completion_event_data(transaction)
            }) && owner
                .is_some_and(|event| normalized_hash(event) == transaction.request_event_hash)
                && full_compile.is_some_and(|event| {
                    transaction.full_compile_event_hash.as_deref()
                        == Some(normalized_hash(event).as_str())
                });
            Ok(events_match)
        })()?;
        if candidate_matches {
            return Ok(Some(checkpoint_id.to_string()));
        }
    }
    Ok(None)
}

fn planned_proof_source_relocation_tracked_checkpoint_current(
    profile: &CompiledProfile,
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<bool> {
    if profile.manifest.storage.backend != StorageBackend::Tracked {
        return Ok(true);
    }
    Ok(
        planned_proof_source_relocation_tracked_checkpoint_commit(profile, store, transaction)?
            .is_some(),
    )
}

fn finalize_planned_proof_source_relocation_tracked_checkpoint(
    engine: &Engine,
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
    seal_commit: &str,
) -> Result<()> {
    let git = GitBackend::discover(&engine.root)?;
    if git.branch_ref()? != transaction.integration_ref {
        return Err(KoniError::Action(
            "planned-proof source relocation checkpoint synchronization is outside its integration branch"
                .to_owned(),
        ));
    }
    let current = git.reference_oid(&transaction.integration_ref)?;
    if git.head_oid()? != current {
        return Err(KoniError::Action(
            "planned-proof source relocation checkpoint synchronization found a detached integration checkout"
                .to_owned(),
        ));
    }
    let seal = Oid::from_str(seal_commit).map_err(KoniError::Git)?;
    let repository = git2::Repository::discover(git.workdir())?;
    if current != seal && !repository.graph_descendant_of(current, seal)? {
        return Err(KoniError::Action(
            "planned-proof source relocation synchronization seal is not in current integration history"
                .to_owned(),
        ));
    }
    engine.synchronize_empty_ticket_worktrees_from(
        &current.to_string(),
        &[transaction.integration_head.as_str()],
    )?;
    engine.repair_terminal_ticket_transient_trees()?;
    if GitBackend::discover(&engine.root)?.head_oid()? != current {
        return Err(KoniError::Action(
            "planned-proof source relocation integration HEAD changed during checkpoint synchronization"
                .to_owned(),
        ));
    }
    write_planned_proof_source_relocation_sync_marker(store, transaction, seal_commit)?;
    if !planned_proof_source_relocation_sync_marker_current(store, transaction, seal_commit)? {
        return Err(KoniError::Action(
            "planned-proof source relocation checkpoint synchronization marker is not current"
                .to_owned(),
        ));
    }
    Ok(())
}

fn ensure_planned_proof_source_relocation_tracked_checkpoint(
    engine: &Engine,
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<()> {
    if engine.profile.manifest.storage.backend != StorageBackend::Tracked {
        return Ok(());
    }
    let git = GitBackend::discover(&engine.root)?;
    if let Some(seal_commit) = planned_proof_source_relocation_tracked_checkpoint_commit(
        &engine.profile,
        store,
        transaction,
    )? {
        finalize_planned_proof_source_relocation_tracked_checkpoint(
            engine,
            store,
            transaction,
            &seal_commit,
        )?;
        return Ok(());
    }
    let graph_path = store
        .graph_dir()
        .join(&transaction.amended_node.node_type)
        .join(format!(
            "{}--{}.yaml",
            slugify(&transaction.amended_node.title),
            transaction.amended_node.id
        ));
    let authority_paths = vec![
        planned_proof_source_relocation_transaction_path(store, &transaction.request_hash)?,
        store.root().join("events.jsonl"),
        store
            .root()
            .join("journals")
            .join(format!("{}.yaml", transaction.request_action_journal_id)),
        store
            .root()
            .join("journals")
            .join(format!("{}.yaml", transaction.failed_compile_journal_id)),
        store.ticket_path(&transaction.expected_ticket),
        graph_path,
    ];
    let mut required_paths = authority_paths
        .into_iter()
        .map(|path| {
            path.strip_prefix(git.workdir())
                .map(Path::to_path_buf)
                .map_err(|_| {
                    KoniError::Action(format!(
                        "planned-proof source relocation seal path {} is outside integration checkout {}",
                        path.display(),
                        git.workdir().display()
                    ))
                })
        })
        .collect::<Result<Vec<_>>>()?;
    required_paths.sort();
    required_paths.dedup();
    let unchanged_action_journal_path = store
        .root()
        .join("journals")
        .join(format!("{}.yaml", transaction.request_action_journal_id))
        .strip_prefix(git.workdir())
        .map(Path::to_path_buf)
        .map_err(|_| {
            KoniError::Action(
                "planned-proof source relocation owning action Journal is outside integration checkout"
                    .to_owned(),
            )
        })?;
    let final_required_changed_paths = required_paths
        .iter()
        .filter(|path| **path != unchanged_action_journal_path)
        .cloned()
        .collect::<Vec<_>>();
    let required_path_set = required_paths.iter().cloned().collect::<BTreeSet<_>>();
    let status_exclusions = tracked_state_status_exclusions(&engine.profile, git.workdir())?;
    let unexpected = git
        .status(&status_exclusions)?
        .into_iter()
        .filter(|change| !required_path_set.contains(&change.path))
        .collect::<Vec<_>>();
    if !unexpected.is_empty() {
        return Err(KoniError::Action(format!(
            "planned-proof source relocation final checkpoint refuses unrelated changed paths: {}",
            unexpected
                .iter()
                .map(|change| change.path.display().to_string())
                .collect::<Vec<_>>()
                .join(", ")
        )));
    }
    let expected_parent = Oid::from_str(&transaction.integration_head).map_err(KoniError::Git)?;
    let tree_excluded_paths = tracked_state_tree_exclusions(&engine.profile, git.workdir())?;
    let checkpoint = git
        .checkpoint_from_with_required_paths(
            &CheckpointRequest {
                subject: "chore(koni): complete planned proof-source relocation".to_owned(),
                body: None,
                trailers: Vec::new(),
                excluded_paths: pinned_codex_project_config_exclusions(git.workdir())?,
                tree_excluded_paths: tree_excluded_paths.clone(),
                identity: Some(CommitIdentity::default()),
            },
            expected_parent,
            &required_paths,
        )?
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation complete authority produced no tracked checkpoint"
                    .to_owned(),
            )
        })?;
    validate_planned_proof_source_relocation_checkpoint_tree(
        &git,
        &checkpoint.commit,
        Some(&checkpoint),
        &required_paths,
        &final_required_changed_paths,
        &tree_excluded_paths,
        "final",
    )?;
    if checkpoint.parent != transaction.integration_head
        || GitBackend::discover(&engine.root)?.head_oid()?.to_string() != checkpoint.commit
    {
        return Err(KoniError::Action(
            "planned-proof source relocation final checkpoint changed its pinned parent or integration HEAD"
                .to_owned(),
        ));
    }
    finalize_planned_proof_source_relocation_tracked_checkpoint(
        engine,
        store,
        transaction,
        &checkpoint.commit,
    )?;
    validate_planned_proof_source_relocation_checkpoint_tree(
        &git,
        &checkpoint.commit,
        None,
        &required_paths,
        &final_required_changed_paths,
        &tree_excluded_paths,
        "final post-synchronization",
    )?;
    if !planned_proof_source_relocation_tracked_checkpoint_current(
        &engine.profile,
        store,
        transaction,
    )? || !planned_proof_source_relocation_sync_marker_current(
        store,
        transaction,
        &checkpoint.commit,
    )? {
        return Err(KoniError::Action(
            "planned-proof source relocation tracked checkpoint did not durably bind and synchronize its complete graph, ticket, Journal, transaction, and event poststate"
                .to_owned(),
        ));
    }
    Ok(())
}

fn planned_proof_source_relocation_is_fully_sealed(
    profile: &CompiledProfile,
    store: &StateStore,
    run: &RunManifest,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<bool> {
    if transaction.schema_version != "1.0"
        || transaction.status != "complete"
        || transaction.completed_at.is_none()
        || transaction.transaction_hash
            != planned_proof_source_relocation_transaction_hash(transaction)
    {
        return Ok(false);
    }
    let events = store.events()?;
    let Some(event) = completed_planned_proof_source_relocation_event(&events, transaction)? else {
        return Ok(false);
    };
    if event.schema_version != "1.0"
        || event.run_id != run.id
        || event.actor != "compiler"
        || event.ticket_id.as_deref()
            != Some(transaction.conflicting_preparation_ticket_id.as_str())
        || event.data != planned_proof_source_relocation_completion_event_data(transaction)
    {
        return Ok(false);
    }
    let owner = events
        .iter()
        .find(|candidate| candidate.id == transaction.request_event_id)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation sealed transaction lost its owning event"
                    .to_owned(),
            )
        })?;
    validate_completed_planned_proof_source_relocation_immutable_history(
        profile,
        store,
        run,
        transaction,
        owner,
    )?;
    if profile.manifest.storage.backend == StorageBackend::Tracked {
        let Some(seal_commit) =
            planned_proof_source_relocation_tracked_checkpoint_commit(profile, store, transaction)?
        else {
            return Ok(false);
        };
        if !planned_proof_source_relocation_sync_marker_current(store, transaction, &seal_commit)? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn append_planned_proof_source_relocation_event_once(
    store: &StateStore,
    run: &RunManifest,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<()> {
    let expected_data = planned_proof_source_relocation_completion_event_data(transaction);
    let events = store.events()?;
    if let Some(existing) = completed_planned_proof_source_relocation_event(&events, transaction)? {
        if existing.schema_version == "1.0"
            && existing.run_id == run.id
            && existing.actor == "compiler"
            && existing.ticket_id.as_deref()
                == Some(transaction.conflicting_preparation_ticket_id.as_str())
            && existing.data == expected_data
        {
            return Ok(());
        }
        return Err(KoniError::Action(
            "planned-proof source relocation completion event conflicts with its immutable transaction"
                .to_owned(),
        ));
    }
    store.append_event(&Event::new(
        &run.id,
        PLANNED_PROOF_SOURCE_RELOCATION_EVENT_TYPE,
        Some(transaction.conflicting_preparation_ticket_id.clone()),
        expected_data,
    ))
}

fn validate_planned_proof_source_relocation_owning_action_history(
    profile: &CompiledProfile,
    store: &StateStore,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<()> {
    let steer_action = profile.action("steer").ok_or_else(|| {
        KoniError::Profile(
            "planned-proof source relocation requires a configured steer action".to_owned(),
        )
    })?;
    let expected_steps = (0..steer_action.recipe.len()).collect::<Vec<_>>();
    if transaction.request_action_journal.status != JournalStatus::Complete
        || transaction.request_action_journal.completed_steps != expected_steps
    {
        return Err(KoniError::Action(
            "planned-proof source relocation owning action Journal is not durably complete"
                .to_owned(),
        ));
    }
    let current_action_journal = store
        .journals()?
        .into_iter()
        .find(|journal| journal.id == transaction.request_action_journal_id)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation lost its owning action Journal".to_owned(),
            )
        })?;
    if normalized_hash(&current_action_journal) != transaction.request_action_journal_hash {
        return Err(KoniError::Action(
            "planned-proof source relocation owning action Journal changed after commit".to_owned(),
        ));
    }
    Ok(())
}

fn validate_completed_planned_proof_source_relocation_immutable_history(
    profile: &CompiledProfile,
    store: &StateStore,
    run: &RunManifest,
    transaction: &PlannedProofSourceRelocationTransaction,
    owner: &Event,
) -> Result<()> {
    validate_planned_proof_source_relocation_transaction(transaction, owner, profile)?;
    if transaction.status != "complete" || transaction.completed_at.is_none() {
        return Err(KoniError::Action(
            "planned-proof source relocation historical validation requires a complete transaction"
                .to_owned(),
        ));
    }
    validate_planned_proof_source_relocation_owning_action_history(profile, store, transaction)?;
    let mut recovered = transaction.failed_compile_journal.clone();
    recovered.status = JournalStatus::Recovered;
    let current = store
        .journals()?
        .into_iter()
        .find(|journal| journal.id == transaction.failed_compile_journal_id)
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation lost its recovered compile journal".to_owned(),
            )
        })?;
    if normalized_hash(&current) != normalized_hash(&recovered) {
        return Err(KoniError::Action(
            "planned-proof source relocation recovered compile journal changed after completion"
                .to_owned(),
        ));
    }
    let compile_event =
        planned_proof_source_relocation_full_compile_event(store, run, transaction)?.ok_or_else(
            || {
                KoniError::Action(
                    "planned-proof source relocation lost its successful full-compile binding"
                        .to_owned(),
                )
            },
        )?;
    let compile_event_hash = normalized_hash(&compile_event);
    if transaction.full_compile_event_id.as_deref() != Some(compile_event.id.as_str())
        || transaction.full_compile_event_hash.as_deref() != Some(compile_event_hash.as_str())
    {
        return Err(KoniError::Action(
            "planned-proof source relocation successful full-compile binding changed after completion"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_unsealed_complete_planned_proof_source_relocation_poststate(
    profile: &CompiledProfile,
    store: &StateStore,
    root: &Path,
    transaction: &PlannedProofSourceRelocationTransaction,
) -> Result<()> {
    if transaction.status != "complete" {
        return Err(KoniError::Action(
            "planned-proof source relocation poststate sealing requires a complete transaction"
                .to_owned(),
        ));
    }
    let graph = store.graph()?;
    if graph.normalized_hash() != transaction.amended_graph_hash
        || graph
            .node(&transaction.proof_node_id)
            .is_none_or(|node| normalized_hash(node) != transaction.amended_node_hash)
    {
        return Err(KoniError::Action(
            "planned-proof source relocation cannot seal a completion event after its amended graph poststate changed"
                .to_owned(),
        ));
    }
    let preparations = current_proof_preparation_bindings(profile, store, root, &graph)?;
    if normalized_hash(&preparations) != transaction.prepared_sources_hash {
        return Err(KoniError::Action(
            "planned-proof source relocation cannot seal a completion event after preparation authority changed"
                .to_owned(),
        ));
    }
    let tickets = store.tickets()?;
    let expected_ticket_is_exact = tickets
        .iter()
        .find(|ticket| ticket.id == transaction.expected_ticket_id)
        .is_some_and(|ticket| normalized_hash(ticket) == transaction.expected_ticket_hash);
    let prior_tickets = tickets
        .iter()
        .filter(|ticket| ticket.id != transaction.expected_ticket_id)
        .cloned()
        .collect::<Vec<_>>();
    if !expected_ticket_is_exact || normalized_hash(&prior_tickets) != transaction.base_tickets_hash
    {
        return Err(KoniError::Action(
            "planned-proof source relocation cannot seal a completion event after its exact ticket-board poststate changed"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_completed_planned_proof_source_relocation_history(
    profile: &CompiledProfile,
    store: &StateStore,
    run: &RunManifest,
    transaction: &PlannedProofSourceRelocationTransaction,
    owner: &Event,
) -> Result<()> {
    validate_completed_planned_proof_source_relocation_immutable_history(
        profile,
        store,
        run,
        transaction,
        owner,
    )?;
    let events = store.events()?;
    let completion = completed_planned_proof_source_relocation_event(&events, transaction)?
        .ok_or_else(|| {
            KoniError::Action(
                "planned-proof source relocation complete transaction has no completion event"
                    .to_owned(),
            )
        })?;
    if completion.schema_version != "1.0"
        || completion.run_id != run.id
        || completion.actor != "compiler"
        || completion.ticket_id.as_deref()
            != Some(transaction.conflicting_preparation_ticket_id.as_str())
        || completion.data != planned_proof_source_relocation_completion_event_data(transaction)
    {
        return Err(KoniError::Action(
            "planned-proof source relocation completion event envelope or payload disagrees with its immutable transaction"
                .to_owned(),
        ));
    }
    Ok(())
}

fn read_scope_replan_request(event: &Event) -> Result<ReadScopeReplanRequest> {
    let encoded = event
        .data
        .get("message")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            KoniError::Action(
                "read-scope-repair requires one versioned JSON object in message".to_owned(),
            )
        })?;
    serde_json::from_str::<ReadScopeReplanRequest>(encoded).map_err(|error| {
        KoniError::Action(format!(
            "read-scope-repair message is not the exact versioned JSON contract: {error}"
        ))
    })
}

fn read_scope_rebind_transaction_hash(transaction: &ReadScopeRebindTransaction) -> String {
    let mut candidate = serde_json::to_value(transaction).expect("rebind transaction serializes");
    candidate["transaction_hash"] = Value::String(String::new());
    normalized_hash(&candidate)
}

fn read_scope_rebind_transaction_path(store: &StateStore, request_hash: &str) -> Result<PathBuf> {
    let suffix = request_hash.strip_prefix("sha256:").ok_or_else(|| {
        KoniError::Action("read-scope-rebind request hash has an unknown format".to_owned())
    })?;
    if suffix.len() != 64 || !suffix.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(KoniError::Action(
            "read-scope-rebind request hash is not a canonical SHA-256 identity".to_owned(),
        ));
    }
    Ok(store
        .root()
        .join("recovery/read-scope-rebind")
        .join(format!("{suffix}.yaml")))
}

fn read_scope_rebind_transaction(
    store: &StateStore,
    request_hash: &str,
) -> Result<Option<ReadScopeRebindTransaction>> {
    let path = read_scope_rebind_transaction_path(store, request_hash)?;
    read_optional_yaml_value(&path)?
        .map(|value| {
            serde_json::from_value::<ReadScopeRebindTransaction>(value).map_err(|error| {
                KoniError::Action(format!(
                    "read-scope-rebind transaction {} is unreadable: {error}",
                    path.display()
                ))
            })
        })
        .transpose()
}

fn read_scope_rebind_transactions(store: &StateStore) -> Result<Vec<ReadScopeRebindTransaction>> {
    let root = store.root().join("recovery/read-scope-rebind");
    if !root.exists() {
        return Ok(Vec::new());
    }
    let mut transactions = Vec::new();
    for entry in fs::read_dir(&root).map_err(|error| io_error(&root, error))? {
        let entry = entry.map_err(|error| io_error(&root, error))?;
        let path = entry.path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("yaml") {
            continue;
        }
        let value = read_optional_yaml_value(&path)?.ok_or_else(|| {
            KoniError::Action(format!(
                "read-scope-rebind transaction disappeared: {}",
                path.display()
            ))
        })?;
        transactions.push(
            serde_json::from_value::<ReadScopeRebindTransaction>(value).map_err(|error| {
                KoniError::Action(format!(
                    "read-scope-rebind transaction {} is unreadable: {error}",
                    path.display()
                ))
            })?,
        );
    }
    transactions.sort_by(|left, right| left.id.cmp(&right.id));
    Ok(transactions)
}

fn validate_duplicate_read_scope_replan_event(
    event: &Event,
    request: &ReadScopeReplanRequest,
    transaction: &ReadScopeRebindTransaction,
) -> Result<()> {
    let targets = event
        .data
        .get("target_nodes")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|target| target.as_str().map(ToOwned::to_owned))
        .collect::<Option<BTreeSet<_>>>()
        .ok_or_else(|| {
            KoniError::Action("read-scope-repair duplicate has invalid target_nodes".to_owned())
        })?;
    let expected = BTreeSet::from([
        request.source_node_id.clone(),
        request.amend_node_id.clone(),
    ]);
    if event.event_type != "compiler.steering.recorded"
        || event.data.get("kind").and_then(Value::as_str) != Some(READ_SCOPE_REPLAN_KIND)
        || event.ticket_id.as_deref() != Some(request.ticket_id.as_str())
        || event.data.get("ticket_id").and_then(Value::as_str) != Some(request.ticket_id.as_str())
        || request.ticket_id != transaction.ticket_id
        || request.amend_node_id != transaction.amended_node.id
        || request.path != transaction.path
        || normalized_hash(request) != transaction.blocker_request_hash
        || targets != expected
    {
        return Err(KoniError::Action(
            "read-scope-repair duplicate conflicts with the completed semantic rebind".to_owned(),
        ));
    }
    Ok(())
}

fn validate_duplicate_read_scope_rebind_event(
    event: &Event,
    request: &ReadScopeRebindRequest,
    amend_node_id: &str,
) -> Result<()> {
    let duplicate_request = read_scope_rebind_request(event)?;
    let targets = event
        .data
        .get("target_nodes")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|target| target.as_str().map(ToOwned::to_owned))
        .collect::<Option<BTreeSet<_>>>()
        .ok_or_else(|| {
            KoniError::Action("read-scope-rebind duplicate has invalid target_nodes".to_owned())
        })?;
    if event.event_type != "compiler.steering.recorded"
        || event.data.get("kind").and_then(Value::as_str) != Some(READ_SCOPE_REBIND_KIND)
        || event.ticket_id.as_deref() != Some(request.ticket_id.as_str())
        || event.data.get("ticket_id").and_then(Value::as_str) != Some(request.ticket_id.as_str())
        || duplicate_request != *request
        || targets != BTreeSet::from([amend_node_id.to_owned()])
    {
        return Err(KoniError::Action(
            "read-scope-rebind duplicate conflicts with the transaction-owning request".to_owned(),
        ));
    }
    Ok(())
}

fn reconstruct_pre_replan_ticket(
    blocked: &Ticket,
    binding: &ReadScopeReplanBinding,
) -> Result<Ticket> {
    let mut reconstructed = blocked.clone();
    let instruction = read_scope_replan_instruction(binding);
    let matching_blockers = reconstructed
        .blockers
        .iter()
        .filter(|blocker| {
            blocker.kind == READ_SCOPE_REPLAN_BLOCKER_KIND
                && blocker.related_ticket.as_deref() == Some(binding.step_id.as_str())
                && blocker.created_at == binding.recorded_at
                && blocker.message == instruction
        })
        .count();
    if matching_blockers != 1 {
        return Err(KoniError::Action(format!(
            "read-scope-rebind expected one exact blocker, found {matching_blockers}"
        )));
    }
    reconstructed.blockers.retain(|blocker| {
        !(blocker.kind == READ_SCOPE_REPLAN_BLOCKER_KIND
            && blocker.related_ticket.as_deref() == Some(binding.step_id.as_str())
            && blocker.created_at == binding.recorded_at
            && blocker.message == instruction)
    });
    let history = reconstructed
        .extensions
        .get_mut(READ_SCOPE_REPLAN_EXTENSION)
        .and_then(Value::as_array_mut)
        .ok_or_else(|| {
            KoniError::Action(
                "read-scope-rebind cannot reconstruct the blocker generation".to_owned(),
            )
        })?;
    if history
        .last()
        .and_then(|entry| entry.get("binding_hash").and_then(Value::as_str))
        != Some(binding.binding_hash.as_str())
    {
        return Err(KoniError::Action(
            "read-scope-rebind blocker is not the latest exact replan generation".to_owned(),
        ));
    }
    history.pop();
    if history.is_empty() {
        reconstructed.extensions.remove(READ_SCOPE_REPLAN_EXTENSION);
    }
    reconstructed
        .status
        .clone_from(&binding.prior_ticket_status);
    if normalized_hash(&reconstructed) != binding.base_ticket_hash {
        return Err(KoniError::Action(
            "read-scope-rebind blocked ticket contains changes beyond the compiler-published blocker"
                .to_owned(),
        ));
    }
    Ok(reconstructed)
}

fn read_scope_rebind_clean_lease_binding(
    profile: &CompiledProfile,
    ticket: &Ticket,
) -> Result<(String, String)> {
    let lease = ticket.lease.as_ref().ok_or_else(|| {
        KoniError::Action("read-scope-rebind ticket has no retained worktree lease".to_owned())
    })?;
    let git = GitBackend::discover(&lease.worktree)?;
    let discovered_worktree = git
        .workdir()
        .canonicalize()
        .map_err(|error| io_error(git.workdir(), error))?;
    let expected_worktree = lease
        .worktree
        .canonicalize()
        .map_err(|error| io_error(&lease.worktree, error))?;
    if discovered_worktree != expected_worktree {
        return Err(KoniError::Action(format!(
            "read-scope-rebind discovered git worktree {} instead of retained lease {}",
            discovered_worktree.display(),
            expected_worktree.display()
        )));
    }
    let branch_ref = git.branch_ref()?;
    let expected_branch_ref = if lease.branch.starts_with("refs/") {
        lease.branch.clone()
    } else {
        format!("refs/heads/{}", lease.branch)
    };
    if branch_ref != expected_branch_ref {
        return Err(KoniError::Action(format!(
            "read-scope-rebind retained worktree branch changed: expected {expected_branch_ref}, found {branch_ref}"
        )));
    }
    let head = git.head_oid()?;
    if git.reference_oid(&branch_ref)? != head {
        return Err(KoniError::Action(
            "read-scope-rebind retained worktree HEAD differs from its branch ref".to_owned(),
        ));
    }
    let changes = git.status(&tracked_state_status_exclusions(profile, git.workdir())?)?;
    if !changes.is_empty() {
        return Err(KoniError::Action(format!(
            "read-scope-rebind retained worktree must be clean; found {} changed path(s)",
            changes.len()
        )));
    }
    Ok((branch_ref, head.to_string()))
}

fn exact_read_scope_addition(
    before: &BTreeSet<String>,
    after: &BTreeSet<String>,
    path: &str,
    required: bool,
    label: &str,
) -> Result<()> {
    if !before.is_subset(after) {
        return Err(KoniError::Action(format!(
            "read-scope-rebind {label} removed existing read authority"
        )));
    }
    let added = after.difference(before).cloned().collect::<BTreeSet<_>>();
    let exact = BTreeSet::from([path.to_owned()]);
    if (!added.is_empty() || required) && added != exact {
        return Err(KoniError::Action(format!(
            "read-scope-rebind {label} changed read authority by {:?}; only {path} is permitted",
            added
        )));
    }
    Ok(())
}

fn read_scope_rebind_step_structure(step: &Step) -> Value {
    let mut value = serde_json::to_value(step).expect("step serializes");
    let object = value.as_object_mut().expect("step is an object");
    object.remove("read_paths");
    object.remove("compiled_check_sets");
    object.remove("context_hash");
    value
}

fn validate_read_scope_rebind_compiled_checks(
    profile: &CompiledProfile,
    before: &Step,
    after: &Step,
    binding: &ReadScopeReplanBinding,
    base_node: &Node,
    amended_node: &Node,
) -> Result<bool> {
    if before.compiled_check_sets.len() != after.compiled_check_sets.len() {
        return Err(KoniError::Action(
            "read-scope-rebind changed the number of compiled check sets".to_owned(),
        ));
    }
    let definition = profile
        .node_types
        .get(&amended_node.node_type)
        .ok_or_else(|| {
            KoniError::Profile(format!(
                "read-scope-rebind amendment node type {} disappeared",
                amended_node.node_type
            ))
        })?;
    let base_semantic_hash = semantic_receipt_node_hash(
        base_node,
        &definition.semantic_fields,
        &definition.compiler_owned_fields,
    );
    let amended_semantic_hash = semantic_receipt_node_hash(
        amended_node,
        &definition.semantic_fields,
        &definition.compiler_owned_fields,
    );
    let mut saw_amended_member = false;
    for (old_set, new_set) in before
        .compiled_check_sets
        .iter()
        .zip(&after.compiled_check_sets)
    {
        if old_set.schema_version != new_set.schema_version
            || old_set.parent_check_id != new_set.parent_check_id
            || old_set.receipt_type != new_set.receipt_type
            || old_set.parent_check_hash != new_set.parent_check_hash
            || old_set.selector_hash != new_set.selector_hash
            || old_set.anchor_nodes != new_set.anchor_nodes
            || old_set.members.len() != new_set.members.len()
            || old_set.anchor_hashes.keys().collect::<Vec<_>>()
                != new_set.anchor_hashes.keys().collect::<Vec<_>>()
        {
            return Err(KoniError::Action(
                "read-scope-rebind changed compiled check identity or selection structure"
                    .to_owned(),
            ));
        }
        for (node_id, old_hash) in &old_set.anchor_hashes {
            let new_hash = &new_set.anchor_hashes[node_id];
            if node_id == &binding.amend_node_id {
                if old_hash != &base_semantic_hash || new_hash != &amended_semantic_hash {
                    return Err(KoniError::Action(
                        "read-scope-rebind proof anchor semantic hash is not the exact old/new node binding"
                            .to_owned(),
                    ));
                }
            } else if old_hash != new_hash {
                return Err(KoniError::Action(
                    "read-scope-rebind changed an unrelated compiled check anchor".to_owned(),
                ));
            }
        }
        let mut set_contains_amended_member = false;
        for (old_member, new_member) in old_set.members.iter().zip(&new_set.members) {
            if old_member.source_node_id != new_member.source_node_id
                || old_member.source_node_type != new_member.source_node_type
                || old_member.child_check_id != new_member.child_check_id
                || old_member.child_check_hash != new_member.child_check_hash
                || old_member.argv != new_member.argv
                || old_member.working_directory != new_member.working_directory
                || old_member.source_paths != new_member.source_paths
            {
                return Err(KoniError::Action(
                    "read-scope-rebind changed compiled proof member identity, command, or source authority"
                        .to_owned(),
                ));
            }
            if old_member.source_node_id == binding.amend_node_id {
                exact_read_scope_addition(
                    &old_member.covered_paths,
                    &new_member.covered_paths,
                    &binding.path,
                    true,
                    "compiled proof member covered_paths",
                )?;
                if old_member.source_semantic_hash != base_semantic_hash
                    || new_member.source_semantic_hash != amended_semantic_hash
                {
                    return Err(KoniError::Action(
                        "read-scope-rebind compiled proof member semantic hashes are not exact"
                            .to_owned(),
                    ));
                }
                set_contains_amended_member = true;
                saw_amended_member = true;
            } else if old_member != new_member {
                return Err(KoniError::Action(
                    "read-scope-rebind changed an unrelated compiled proof member".to_owned(),
                ));
            }
        }
        if !set_contains_amended_member && old_set != new_set {
            return Err(KoniError::Action(
                "read-scope-rebind changed a compiled check set unrelated to the amended proof"
                    .to_owned(),
            ));
        }
    }
    Ok(saw_amended_member)
}

fn validate_read_scope_rebind_candidate(
    profile: &CompiledProfile,
    blocked: &Ticket,
    candidate: &Ticket,
    binding: &ReadScopeReplanBinding,
    base_node: &Node,
    amended_node: &Node,
) -> Result<()> {
    let fixed_ticket_identity = |ticket: &Ticket| {
        json!({
            "schema_version": ticket.schema_version,
            "id": ticket.id,
            "operation": ticket.operation,
            "title": ticket.title,
            "target_nodes": ticket.target_nodes,
            "read_nodes": ticket.scope.read_nodes,
            "write_nodes": ticket.scope.write_nodes,
            "write_paths": ticket.scope.write_paths,
            "source_state_key": ticket.source_state_key,
            "target_state_key": ticket.target_state_key,
            "obligation_keys": ticket.obligation_keys,
            "profile_hash": ticket.profile_hash,
            "rule_id": ticket.rule_id,
        })
    };
    if fixed_ticket_identity(blocked) != fixed_ticket_identity(candidate) {
        return Err(KoniError::Action(
            "read-scope-rebind same-rule candidate changed ticket identity, nodes, or write authority"
                .to_owned(),
        ));
    }
    for key in [
        "phase",
        "operation_registry_id",
        "workflow_id",
        "dispatch_priority",
        "ranking_hints",
        "rule_anchor_node_id",
        "review_failure_reopen_from",
        REVIEW_FAILURE_ROUTES_EXTENSION,
        PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION,
    ] {
        if blocked.extensions.get(key) != candidate.extensions.get(key) {
            return Err(KoniError::Action(format!(
                "read-scope-rebind candidate changed or omitted compiler-derived ticket metadata {key}"
            )));
        }
    }
    for (key, value) in &candidate.extensions {
        if blocked.extensions.get(key) != Some(value) {
            return Err(KoniError::Action(format!(
                "read-scope-rebind candidate changed compiler-derived ticket metadata {key}"
            )));
        }
    }
    exact_read_scope_addition(
        &blocked.scope.read_paths,
        &candidate.scope.read_paths,
        &binding.path,
        true,
        "ticket scope",
    )?;
    if blocked.workflow.len() != candidate.workflow.len() {
        return Err(KoniError::Action(
            "read-scope-rebind changed workflow length".to_owned(),
        ));
    }
    let mut named_step_gained_path = false;
    let mut named_step_recompiled_member = false;
    for (before, after) in blocked.workflow.iter().zip(&candidate.workflow) {
        if read_scope_rebind_step_structure(before) != read_scope_rebind_step_structure(after) {
            return Err(KoniError::Action(format!(
                "read-scope-rebind changed workflow structure at step {}",
                before.id
            )));
        }
        let before_reads = effective_step_read_paths(blocked, before);
        let after_reads = effective_step_read_paths(candidate, after);
        exact_read_scope_addition(
            before_reads,
            after_reads,
            &binding.path,
            before.id == binding.step_id,
            &format!("step {}", before.id),
        )?;
        if after_reads
            .difference(before_reads)
            .any(|path| path == &binding.path)
            && before.id == binding.step_id
        {
            named_step_gained_path = true;
        }
        if effective_step_write_paths(blocked, before)
            != effective_step_write_paths(candidate, after)
        {
            return Err(KoniError::Action(format!(
                "read-scope-rebind changed effective write authority at step {}",
                before.id
            )));
        }
        let recompiled = validate_read_scope_rebind_compiled_checks(
            profile,
            before,
            after,
            binding,
            base_node,
            amended_node,
        )?;
        let inputs_changed =
            before_reads != after_reads || before.compiled_check_sets != after.compiled_check_sets;
        if (before.context_hash != after.context_hash) != inputs_changed {
            return Err(KoniError::Action(format!(
                "read-scope-rebind step {} context hash does not exactly track its recompiled inputs",
                before.id
            )));
        }
        if inputs_changed && current_step_output(blocked, before).is_some() {
            return Err(KoniError::Action(format!(
                "read-scope-rebind step {} still has a current output under its old context hash",
                before.id
            )));
        }
        if before.id == binding.step_id {
            named_step_recompiled_member = recompiled;
        } else if recompiled {
            return Err(KoniError::Action(format!(
                "read-scope-rebind unexpectedly changed proof-member coverage at step {}",
                before.id
            )));
        }
    }
    if !named_step_gained_path || !named_step_recompiled_member {
        return Err(KoniError::Action(
            "read-scope-rebind reopened step did not gain the exact read path and regenerated proof member"
                .to_owned(),
        ));
    }
    Ok(())
}

fn validate_read_scope_rebind_transaction(
    transaction: &ReadScopeRebindTransaction,
    event: &Event,
    profile: &CompiledProfile,
) -> Result<()> {
    if transaction.schema_version != "1.0"
        || !matches!(transaction.status.as_str(), "prepared" | "complete")
        || (transaction.status == "prepared") != transaction.completed_at.is_none()
        || transaction.profile_hash != profile.hash
        || transaction.request_event_id != event.id
        || transaction.request_event_hash != normalized_hash(event)
        || transaction.request_hash != normalized_hash(&read_scope_rebind_request(event)?)
        || transaction.ticket_id != transaction.rebound_ticket.id
        || transaction.rebound_ticket.status != transaction.prior_ticket_status
        || transaction.rebound_ticket_hash != normalized_hash(&transaction.rebound_ticket)
        || transaction.base_node_hash != normalized_hash(&transaction.base_node)
        || transaction.amended_node_hash != normalized_hash(&transaction.amended_node)
        || transaction.amended_node.id != transaction.base_node.id
        || transaction.receipt_hash
            != transaction
                .receipt
                .get("receipt_hash")
                .and_then(Value::as_str)
                .unwrap_or_default()
        || transaction.receipt_id
            != transaction
                .receipt
                .get("id")
                .and_then(Value::as_str)
                .unwrap_or_default()
        || !durable_receipt_integrity_current(&transaction.receipt)
        || normalized_hash(&transaction.rebound_ticket.lease) != transaction.lease_hash
        || read_scope_rebind_transaction_hash(transaction) != transaction.transaction_hash
    {
        return Err(KoniError::Action(
            "read-scope-rebind transaction failed its compiler-owned integrity binding".to_owned(),
        ));
    }
    let mut expected_node = transaction.base_node.clone();
    let covered = expected_node
        .spec
        .get_mut("covered_paths")
        .and_then(Value::as_array_mut)
        .ok_or_else(|| {
            KoniError::Action(
                "read-scope-rebind transaction base node has no covered_paths list".to_owned(),
            )
        })?;
    covered.push(Value::String(transaction.path.clone()));
    if normalized_hash(&expected_node) != transaction.amended_node_hash {
        return Err(KoniError::Action(
            "read-scope-rebind transaction contains more than one graph-field amendment".to_owned(),
        ));
    }
    Ok(())
}

fn ensure_read_scope_rebind_transaction_quiescent(
    engine: &Engine,
    run: &RunManifest,
    _store: &StateStore,
    transaction: &ReadScopeRebindTransaction,
) -> Result<()> {
    ensure_read_scope_replan_quiescent(engine, run, &transaction.rebound_ticket)?;
    let (branch_ref, head) =
        read_scope_rebind_clean_lease_binding(&engine.profile, &transaction.rebound_ticket)?;
    if branch_ref != transaction.lease_branch_ref || head != transaction.lease_head {
        return Err(KoniError::Action(
            "read-scope-rebind retained branch or HEAD changed after preparation".to_owned(),
        ));
    }
    Ok(())
}

fn read_scope_rebind_ticket_copies(
    store: &StateStore,
    ticket_id: &str,
) -> Result<Vec<(PathBuf, Ticket)>> {
    let mut copies = Vec::new();
    if !store.tickets_dir().exists() {
        return Ok(copies);
    }
    for lane in
        fs::read_dir(store.tickets_dir()).map_err(|error| io_error(store.tickets_dir(), error))?
    {
        let lane = lane.map_err(|error| io_error(store.tickets_dir(), error))?;
        if !lane
            .file_type()
            .map_err(|error| io_error(lane.path(), error))?
            .is_dir()
        {
            continue;
        }
        let path = lane.path().join(format!("{ticket_id}.yaml"));
        if !path.exists() {
            continue;
        }
        let text = fs::read_to_string(&path).map_err(|error| io_error(&path, error))?;
        let ticket = serde_yaml::from_str::<Ticket>(&text).map_err(|source| KoniError::Yaml {
            path: path.clone(),
            source,
        })?;
        copies.push((path, ticket));
    }
    copies.sort_by(|left, right| left.0.cmp(&right.0));
    Ok(copies)
}

fn publish_read_scope_replan_ticket(
    store: &StateStore,
    binding: &ReadScopeReplanBinding,
    blocked: &Ticket,
) -> Result<()> {
    if binding.prior_ticket_status == "blocked" || blocked.status != "blocked" {
        return Err(KoniError::Action(
            "read-scope-repair cannot publish an invalid blocker lane transition".to_owned(),
        ));
    }
    let source = store
        .tickets_dir()
        .join(&binding.prior_ticket_status)
        .join(format!("{}.yaml", binding.ticket_id));
    let target = store
        .tickets_dir()
        .join("blocked")
        .join(format!("{}.yaml", binding.ticket_id));
    let copies = read_scope_rebind_ticket_copies(store, &binding.ticket_id)?;
    if copies.len() != 1 {
        return Err(KoniError::Action(format!(
            "read-scope-repair expected one durable ticket file, found {}",
            copies.len()
        )));
    }
    let (path, ticket) = &copies[0];
    let hash = normalized_hash(ticket);
    if path == &target && hash == normalized_hash(blocked) {
        return Ok(());
    }
    if hash != binding.base_ticket_hash || (path != &source && path != &target) {
        return Err(KoniError::Action(
            "read-scope-repair ticket is neither its exact active prestate nor lane-move midpoint"
                .to_owned(),
        ));
    }
    if path == &source {
        if target.exists() {
            return Err(KoniError::Action(
                "read-scope-repair blocked lifecycle lane already exists".to_owned(),
            ));
        }
        let parent = target.parent().expect("ticket lane has a parent");
        fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
        fs::rename(&source, &target).map_err(|error| io_error(&source, error))?;
    }
    // A crash after rename has one blocked-lane file whose content still
    // names the prior state. Atomic replacement finishes the transition
    // without ever publishing duplicate ticket authority.
    atomic_write_yaml(&target, blocked)?;
    Ok(())
}

fn publish_read_scope_rebind_ticket(
    store: &StateStore,
    transaction: &ReadScopeRebindTransaction,
) -> Result<()> {
    if transaction.prior_ticket_status == "blocked" {
        return Err(KoniError::Action(
            "read-scope-rebind cannot restore into the blocker lane".to_owned(),
        ));
    }
    let source = store
        .tickets_dir()
        .join("blocked")
        .join(format!("{}.yaml", transaction.ticket_id));
    let target = store
        .tickets_dir()
        .join(&transaction.prior_ticket_status)
        .join(format!("{}.yaml", transaction.ticket_id));
    let copies = read_scope_rebind_ticket_copies(store, &transaction.ticket_id)?;
    if copies.len() != 1 {
        return Err(KoniError::Action(format!(
            "read-scope-rebind expected one durable ticket file, found {}",
            copies.len()
        )));
    }
    let (path, ticket) = &copies[0];
    let hash = normalized_hash(ticket);
    if path == &target && hash == transaction.rebound_ticket_hash {
        return Ok(());
    }
    if hash != transaction.blocked_ticket_hash || (path != &source && path != &target) {
        return Err(KoniError::Action(
            "read-scope-rebind ticket is neither its exact blocked prestate nor lane-move midpoint"
                .to_owned(),
        ));
    }
    if path == &source {
        if target.exists() {
            return Err(KoniError::Action(
                "read-scope-rebind target lifecycle lane already exists".to_owned(),
            ));
        }
        let parent = target.parent().expect("ticket lane has a parent");
        fs::create_dir_all(parent).map_err(|error| io_error(parent, error))?;
        fs::rename(&source, &target).map_err(|error| io_error(&source, error))?;
    }
    // A crash after the rename leaves one target-lane file whose contents
    // still say `blocked`. Replaying this atomic replace completes the move
    // without ever materializing duplicate ticket authority.
    atomic_write_yaml(&target, &transaction.rebound_ticket)?;
    Ok(())
}

fn append_read_scope_rebind_event_once(
    store: &StateStore,
    run: &RunManifest,
    transaction: &ReadScopeRebindTransaction,
) -> Result<()> {
    let expected_data = read_scope_rebind_completion_event_data(transaction);
    let matches = store
        .events()?
        .into_iter()
        .filter(|event| {
            event.event_type == READ_SCOPE_REBIND_EVENT_TYPE
                && event.ticket_id.as_deref() == Some(transaction.ticket_id.as_str())
                && event.data.get("request_hash").and_then(Value::as_str)
                    == Some(transaction.request_hash.as_str())
        })
        .collect::<Vec<_>>();
    if !matches.is_empty() {
        if matches.len() == 1
            && matches[0].schema_version == "1.0"
            && matches[0].run_id == run.id
            && matches[0].actor == "compiler"
            && matches[0].data == expected_data
        {
            return Ok(());
        }
        return Err(KoniError::Action(
            "read-scope-rebind completion event conflicts with its immutable transaction"
                .to_owned(),
        ));
    }
    store.append_event(&Event::new(
        &run.id,
        READ_SCOPE_REBIND_EVENT_TYPE,
        Some(transaction.ticket_id.clone()),
        expected_data,
    ))
}

fn read_scope_rebind_completion_event_data(transaction: &ReadScopeRebindTransaction) -> Value {
    json!({
        "transaction_id": transaction.id,
        "transaction_hash": transaction.transaction_hash,
        "request_hash": transaction.request_hash,
        "blocker_request_hash": transaction.blocker_request_hash,
        "blocker_binding_hash": transaction.blocker_binding_hash,
        "path": transaction.path,
        "base_graph_hash": transaction.base_graph_hash,
        "amended_graph_hash": transaction.amended_graph_hash,
        "blocked_ticket_hash": transaction.blocked_ticket_hash,
        "rebound_ticket_hash": transaction.rebound_ticket_hash,
        "candidate_ticket_hash": transaction.candidate_ticket_hash,
        "base_read_scope_hash": transaction.base_read_scope_hash,
        "rebound_read_scope_hash": transaction.rebound_read_scope_hash,
        "base_write_scope_hash": transaction.base_write_scope_hash,
        "rebound_write_scope_hash": transaction.rebound_write_scope_hash,
        "lease_hash": transaction.lease_hash,
        "lease_branch_ref": transaction.lease_branch_ref,
        "lease_head": transaction.lease_head,
        "receipt_id": transaction.receipt_id,
        "receipt_hash": transaction.receipt_hash,
        "authority_changed": true,
        "write_authority_changed": false,
    })
}

fn completed_read_scope_rebind_event<'a>(
    events: &'a [Event],
    transaction: &ReadScopeRebindTransaction,
) -> Result<Option<&'a Event>> {
    let matches = events
        .iter()
        .filter(|event| {
            event.event_type == READ_SCOPE_REBIND_EVENT_TYPE
                && event.ticket_id.as_deref() == Some(transaction.ticket_id.as_str())
                && event.data.get("transaction_id").and_then(Value::as_str)
                    == Some(transaction.id.as_str())
                && event.data.get("request_hash").and_then(Value::as_str)
                    == Some(transaction.request_hash.as_str())
        })
        .collect::<Vec<_>>();
    if matches.len() > 1 {
        return Err(KoniError::Action(
            "read-scope-rebind completion event is duplicated".to_owned(),
        ));
    }
    Ok(matches.first().copied())
}

fn validate_completed_read_scope_rebind_history(
    profile: &CompiledProfile,
    store: &StateStore,
    transaction: &ReadScopeRebindTransaction,
    owner: &Event,
) -> Result<()> {
    validate_read_scope_rebind_transaction(transaction, owner, profile)?;
    if transaction.status != "complete" || transaction.completed_at.is_none() {
        return Err(KoniError::Action(
            "read-scope-rebind historical validation requires a complete transaction".to_owned(),
        ));
    }
    let events = store.events()?;
    let completion = completed_read_scope_rebind_event(&events, transaction)?.ok_or_else(|| {
        KoniError::Action(
            "read-scope-rebind complete transaction has no completion event".to_owned(),
        )
    })?;
    if completion.schema_version != "1.0"
        || completion.run_id != owner.run_id
        || completion.actor != "compiler"
        || completion.data != read_scope_rebind_completion_event_data(transaction)
    {
        return Err(KoniError::Action(
            "read-scope-rebind completion event envelope or payload disagrees with its immutable transaction".to_owned(),
        ));
    }
    let receipt_path = store
        .receipts_dir()
        .join(format!("{}.yaml", transaction.receipt_id));
    if read_optional_yaml_value(&receipt_path)?.as_ref() != Some(&transaction.receipt) {
        return Err(KoniError::Action(
            "read-scope-rebind historical receipt is missing or changed".to_owned(),
        ));
    }
    Ok(())
}

fn ticket_scoped_review_rework_steering_after<'a>(
    ticket: &Ticket,
    steering_events: &'a [Event],
    boundary_at: DateTime<Utc>,
) -> Option<&'a Event> {
    steering_events
        .iter()
        .filter(|event| {
            let envelope_ticket = event.ticket_id.as_deref();
            let data_ticket = event.data.get("ticket_id").and_then(Value::as_str);
            let exact_ticket = (envelope_ticket == Some(ticket.id.as_str())
                || data_ticket == Some(ticket.id.as_str()))
                && envelope_ticket.is_none_or(|id| id == ticket.id)
                && data_ticket.is_none_or(|id| id == ticket.id);
            event.event_type == "compiler.steering.recorded"
                && event.at > boundary_at
                && exact_ticket
                && event.data.get("kind").and_then(Value::as_str) == Some("review-rework")
                && event
                    .data
                    .get("message")
                    .and_then(Value::as_str)
                    .is_some_and(|message| !message.trim().is_empty())
        })
        .max_by_key(|event| (&event.at, &event.id))
}

fn current_passed_review_rework_supersession(
    ticket: &Ticket,
    steering_events: &[Event],
    control: &RunControlStore,
) -> Result<Option<(Review, Event)>> {
    let current_output_hash = normalized_hash(&ticket.outputs);
    let current_passes = ticket
        .reviews
        .iter()
        .filter(|review| review.status == "passed" && review.output_hash == current_output_hash)
        .collect::<Vec<_>>();
    let mut supersessions = Vec::new();
    // Do not let a later same-output pass shadow an earlier review whose input
    // was already revoked. Public workflow readiness prevents that ordering,
    // but recovery must remain fail-closed for legacy/tampered durable state
    // and for profiles with more than one review step.
    for review in current_passes {
        let review_input_started_at = review
            .agent_binding
            .as_ref()
            .map(|binding| control.agent(&binding.agent_id))
            .transpose()?
            .flatten()
            .and_then(|record| record.started_at)
            .unwrap_or(review.reviewed_at);
        if let Some(steering) = ticket_scoped_review_rework_steering_after(
            ticket,
            steering_events,
            review_input_started_at,
        ) {
            supersessions.push((review.clone(), steering.clone()));
        }
    }
    Ok(supersessions
        .into_iter()
        .max_by_key(|(review, steering)| (steering.at, steering.id.clone(), review.id.clone())))
}

fn apply_passed_review_rework_supersession(
    ticket: &mut Ticket,
    review: &Review,
    steering: &Event,
) -> Result<bool> {
    let already_recorded = ticket
        .extensions
        .get(REVIEW_REWORK_SUPERSESSIONS_EXTENSION)
        .and_then(Value::as_array)
        .is_some_and(|history| {
            history.iter().any(|entry| {
                entry.get("review_id").and_then(Value::as_str) == Some(review.id.as_str())
                    && entry.get("steering_event_id").and_then(Value::as_str)
                        == Some(steering.id.as_str())
            })
        });
    if already_recorded {
        return Ok(false);
    }

    if !supersede_integration_outputs_for_rework(ticket) {
        return Err(KoniError::Workflow(format!(
            "ticket {} cannot supersede review {} because no configured rework output or worker was reopened",
            ticket.id, review.id
        )));
    }
    let entry = json!({
        "schema_version": "1.0",
        "status": "reopened",
        "review_id": review.id,
        "review_reviewed_at": review.reviewed_at,
        "review_output_hash": review.output_hash,
        "steering_event_id": steering.id,
        "steering_event_hash": normalized_hash(steering),
        "steering_recorded_at": steering.at,
        "message": steering.data.get("message"),
        "dispositioned_at": Utc::now(),
        "instruction": "A newer authoritative ticket-scoped correction superseded this passed review. The configured author step is reopened, the historical review remains durable, and finish/integration require a replacement output plus an independent review begun after the correction."
    });
    match ticket
        .extensions
        .entry(REVIEW_REWORK_SUPERSESSIONS_EXTENSION.to_owned())
        .or_insert_with(|| Value::Array(Vec::new()))
    {
        Value::Array(history) => history.push(entry),
        _ => {
            return Err(KoniError::Workflow(format!(
                "ticket {} has invalid {} state",
                ticket.id, REVIEW_REWORK_SUPERSESSIONS_EXTENSION
            )));
        }
    }
    Ok(true)
}

fn review_rework_recovery_steering<'a>(
    ticket: &Ticket,
    steering_events: &'a [Event],
) -> Option<&'a Event> {
    let state = ticket.extensions.get(REVIEW_REWORK_EXHAUSTED_EXTENSION)?;
    if state.get("status").and_then(Value::as_str) != Some("open") {
        return None;
    }
    let opened_at = state
        .get("opened_at")
        .cloned()
        .and_then(|value| serde_json::from_value::<DateTime<Utc>>(value).ok())?;
    ticket_scoped_review_rework_steering_after(ticket, steering_events, opened_at)
}

fn reconcile_recoverable_ticket_blockers(
    profile: &CompiledProfile,
    ticket: &mut Ticket,
    runtime_repo_path: Option<&Path>,
    cleanup_index: &git2::Index,
    steering_events: &[Event],
) -> bool {
    if ticket.status != "blocked" {
        return false;
    }
    let review_rework_steering = review_rework_recovery_steering(ticket, steering_events).cloned();
    let before = ticket.blockers.len();
    let open_worker_circuit = ticket
        .extensions
        .get(WORKER_NO_OUTPUT_EXTENSION)
        .is_some_and(|state| state.get("status").and_then(Value::as_str) == Some("open"));
    ticket.blockers.retain(|blocker| {
        let resolved_runtime_blocker = runtime_repo_path.is_some_and(|runtime_root| {
            resolved_agent_runtime_blocker(&blocker.message, runtime_root, cleanup_index)
        });
        let resolved_worker_circuit =
            open_worker_circuit && blocker.kind == WORKER_NO_OUTPUT_BLOCKER_KIND;
        let explicitly_dispositioned_review = review_rework_steering.is_some()
            && blocker.kind == REVIEW_REWORK_EXHAUSTED_BLOCKER_KIND;
        !(blocker.kind == "integration-failure"
            || resolved_runtime_blocker
            || resolved_worker_circuit
            || explicitly_dispositioned_review)
    });
    if ticket.blockers.len() == before {
        return false;
    }
    if open_worker_circuit
        && let Some(state) = ticket
            .extensions
            .get_mut(WORKER_NO_OUTPUT_EXTENSION)
            .and_then(Value::as_object_mut)
    {
        state.insert(
            "status".to_owned(),
            Value::String("explicitly_recovered".to_owned()),
        );
        state.insert(
            "dispositioned_at".to_owned(),
            serde_json::to_value(Utc::now()).expect("UTC timestamp serializes"),
        );
        state.insert(
            "instruction".to_owned(),
            Value::String(
                "The compiler-owned recovery boundary explicitly reopened this step. A fresh pair of post-recovery no-output sessions will reopen the circuit."
                    .to_owned(),
            ),
        );
    }
    if let Some(steering) = review_rework_steering {
        supersede_integration_outputs_for_rework(ticket);
        if let Some(state) = ticket
            .extensions
            .get_mut(REVIEW_REWORK_EXHAUSTED_EXTENSION)
            .and_then(Value::as_object_mut)
        {
            state.insert(
                "status".to_owned(),
                Value::String("explicitly_recovered".to_owned()),
            );
            state.insert(
                "dispositioned_at".to_owned(),
                serde_json::to_value(Utc::now()).expect("UTC timestamp serializes"),
            );
            state.insert(
                "steering_event_id".to_owned(),
                Value::String(steering.id.clone()),
            );
            state.insert(
                "steering_event_hash".to_owned(),
                Value::String(normalized_hash(&steering)),
            );
            state.insert(
                "instruction".to_owned(),
                Value::String(
                    "Explicit ticket-scoped review rework steering reopened the configured correction step. The rejected candidate and both reviews remain durable history; the replacement worker receives the latest findings and steering."
                        .to_owned(),
                ),
            );
        }
    }
    if ticket.blockers.is_empty()
        && validate_ticket_transition(profile, "blocked", "todo", "compiler").is_ok()
        // Older pinned coding profiles assigned ordinary start authority only
        // to Lead. Recovery is replaying that already-leased active state, so
        // accept either the newer explicit compiler authority or the legacy
        // Lead transition rather than stranding an otherwise recovered run.
        && ["compiler", "lead"].into_iter().any(|actor| {
            validate_ticket_transition(profile, "todo", "in_progress", actor).is_ok()
        })
    {
        ticket.status = "in_progress".to_owned();
    }
    true
}

fn ticket_check_value(ticket: &Ticket, graph: &Graph) -> Value {
    let mut value = serde_json::to_value(ticket).expect("ticket serializes");
    let object = value.as_object_mut().expect("ticket serializes as object");
    if let Some(spec) = ticket
        .target_nodes
        .first()
        .and_then(|id| graph.node(id))
        .and_then(|node| node.spec.as_object())
    {
        for (key, value) in spec {
            object.entry(key.clone()).or_insert_with(|| value.clone());
        }
    }
    for (key, value) in &ticket.extensions {
        object.insert(key.clone(), value.clone());
    }
    value
}

#[derive(Clone)]
struct EffectiveCommandSource {
    kind: DynamicSourceKind,
    field: String,
    role: String,
    selection: Option<DynamicNodeSelection>,
    node_types: Vec<String>,
    gate_policy: Option<String>,
}

fn effective_command_source(
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    graph: &Graph,
) -> Result<Option<EffectiveCommandSource>> {
    if let Some(source) = &check.command_source {
        return Ok(Some(EffectiveCommandSource {
            kind: source.kind,
            field: source.field.clone(),
            role: source.role.clone(),
            selection: source.selection,
            node_types: source.node_types.clone(),
            gate_policy: source.gate_policy.clone(),
        }));
    }
    let Some(legacy) = check.argv_from.as_ref().and_then(Value::as_str) else {
        return Ok(None);
    };
    let (root, field) = legacy.split_once('.').unwrap_or(("target", legacy));
    if field.trim().is_empty() {
        return Err(KoniError::Profile(format!(
            "check {} has an empty legacy argv_from field",
            check.id
        )));
    }
    if root == "ticket" {
        return Ok(Some(EffectiveCommandSource {
            kind: DynamicSourceKind::Ticket,
            field: field.to_owned(),
            role: "ticket".to_owned(),
            selection: None,
            node_types: Vec::new(),
            gate_policy: None,
        }));
    }
    if root == "target" {
        let node_types = ticket
            .into_iter()
            .flat_map(|ticket| &ticket.target_nodes)
            .filter_map(|id| graph.node(id).map(|node| node.node_type.clone()))
            .collect::<BTreeSet<_>>()
            .into_iter()
            .collect();
        return Ok(Some(EffectiveCommandSource {
            kind: DynamicSourceKind::Node,
            field: field.to_owned(),
            role: "target".to_owned(),
            selection: Some(DynamicNodeSelection::Target),
            node_types,
            gate_policy: None,
        }));
    }
    Ok(Some(EffectiveCommandSource {
        kind: DynamicSourceKind::Node,
        field: field.to_owned(),
        role: root.to_owned(),
        selection: Some(DynamicNodeSelection::ReadScope),
        node_types: vec![root.to_owned()],
        gate_policy: None,
    }))
}

fn command_variables(ticket: Option<&Ticket>, graph: &Graph) -> BTreeMap<String, String> {
    let mut variables = BTreeMap::new();
    if let Some(ticket) = ticket {
        variables.insert("ticket.id".to_owned(), ticket.id.clone());
        if let Some(target) = ticket_rule_anchor_node_id(ticket).and_then(|id| graph.node(id)) {
            variables.insert("target.id".to_owned(), target.id.clone());
            variables.insert(format!("{}.id", target.node_type), target.id.clone());
        }
    }
    variables
}

fn resolve_execution_candidate(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    source: &EffectiveCommandSource,
    invocation: CheckInvocation<'_>,
    graph: &Graph,
    project_root: &Path,
    policy_store: &StateStore,
) -> Result<ResolvedExecutionCandidate> {
    let ticket = invocation_ticket(invocation);
    if let CheckInvocation::CompiledMember { member, .. } = invocation {
        if source.kind != DynamicSourceKind::Node || source.gate_policy.is_some() {
            return Err(KoniError::Profile(format!(
                "compiled graph-set member {} check {} must use a bounded node command source",
                member.source_node_id, check.id
            )));
        }
        let ticket = ticket.expect("compiled member invocation has a ticket");
        if !ticket.scope.read_nodes.contains(&member.source_node_id) {
            return Err(KoniError::Action(format!(
                "compiled graph-set member {} is outside ticket {} read scope",
                member.source_node_id, ticket.id
            )));
        }
        let node = graph.node(&member.source_node_id).ok_or_else(|| {
            KoniError::Action(format!(
                "compiled graph-set command source {} is missing",
                member.source_node_id
            ))
        })?;
        if !source.node_types.contains(&node.node_type) {
            return Err(KoniError::Action(format!(
                "compiled graph-set member {} has unauthorized type {} for check {}",
                node.id, node.node_type, check.id
            )));
        }
        let definition = profile.node_types.get(&node.node_type).ok_or_else(|| {
            KoniError::Profile(format!(
                "compiled graph-set member {} has unknown type {}",
                node.id, node.node_type
            ))
        })?;
        let value = node.as_value();
        let mut variables = command_variables(Some(ticket), graph);
        variables.insert(format!("{}.id", source.role), node.id.clone());
        variables.insert(format!("{}.id", node.node_type), node.id.clone());
        let command = lookup_dynamic_path(&value, &source.field, &variables).ok_or_else(|| {
            KoniError::Action(format!(
                "compiled graph-set member {} lacks command field {}",
                node.id, source.field
            ))
        })?;
        let argv = command_value_argv(check, command)?;
        return Ok(ResolvedExecutionCandidate {
            kind: "compiled_graph_member".to_owned(),
            role: source.role.clone(),
            id: node.id.clone(),
            node_type: Some(node.node_type.clone()),
            field: source.field.clone(),
            semantic_hash: semantic_receipt_node_hash(
                node,
                &definition.semantic_fields,
                &definition.compiler_owned_fields,
            ),
            value,
            argv,
            variables,
            gate_policy_binding: None,
        });
    }
    if source.kind == DynamicSourceKind::Ticket {
        let ticket = ticket.ok_or_else(|| {
            KoniError::Action(format!(
                "dynamic check {} ticket command source cannot run automatically",
                check.id
            ))
        })?;
        let base_variables = command_variables(Some(ticket), graph);
        let value = ticket_check_value(ticket, graph);
        let command =
            lookup_dynamic_path(&value, &source.field, &base_variables).ok_or_else(|| {
                KoniError::Action(format!(
                    "check {} ticket source {} is missing",
                    check.id, source.field
                ))
            })?;
        let argv = command_value_argv(check, command)?;
        let semantic = json!({
            "ticket_id": ticket.id,
            "operation": ticket.operation,
            "target_nodes": ticket.target_nodes,
            "scope": ticket.scope,
            "command_field": source.field,
            "command": command,
        });
        return Ok(ResolvedExecutionCandidate {
            kind: "ticket".to_owned(),
            role: source.role.clone(),
            id: ticket.id.clone(),
            node_type: None,
            field: source.field.clone(),
            semantic_hash: normalized_hash(&semantic),
            value,
            argv,
            variables: base_variables,
            gate_policy_binding: None,
        });
    }

    if let Some(policy_id) = &source.gate_policy {
        let (invocation_policy_id, gate_id) = match invocation {
            CheckInvocation::GatePolicy { policy_id, gate_id } => (policy_id, gate_id),
            CheckInvocation::Ticket(ticket) => {
                let policy = profile.gate_policies.get(policy_id).ok_or_else(|| {
                    KoniError::Profile(format!(
                        "check {} references missing gate policy {}",
                        check.id, policy_id
                    ))
                })?;
                let gates = ticket
                    .target_nodes
                    .iter()
                    .filter_map(|id| graph.node(id))
                    .filter(|node| policy.gate_node_types.contains(&node.node_type))
                    .collect::<Vec<_>>();
                if gates.len() != 1 {
                    return Err(KoniError::Action(format!(
                        "check {} gate policy {} requires exactly one ticket-authorized gate target, found {}",
                        check.id,
                        policy_id,
                        gates.len()
                    )));
                }
                (policy_id.as_str(), gates[0].id.as_str())
            }
            CheckInvocation::Unscoped => {
                return Err(KoniError::Action(format!(
                    "check {} gate policy command requires a gate subject",
                    check.id
                )));
            }
            CheckInvocation::CompiledMember { .. } => {
                return Err(KoniError::Profile(format!(
                    "compiled graph-set check {} may not use a gate-policy command source",
                    check.id
                )));
            }
        };
        if invocation_policy_id != policy_id {
            return Err(KoniError::Profile(format!(
                "check {} is bound to gate policy {}, not {}",
                check.id, policy_id, invocation_policy_id
            )));
        }
        let resolver = GraphResolver::new(graph, profile, policy_store, project_root);
        let binding = resolver.gate_policy_binding(policy_id, gate_id)?;
        let winner = binding.selection.winner_id.as_deref().ok_or_else(|| {
            KoniError::Action(format!(
                "check {} gate policy {} selected no winner from {} compatible candidates",
                check.id,
                policy_id,
                binding.selection.compatible_candidates.len()
            ))
        })?;
        let node = graph.node(winner).ok_or_else(|| {
            KoniError::Action(format!(
                "check {} gate policy {} winner {} is missing",
                check.id, policy_id, winner
            ))
        })?;
        if !source.node_types.contains(&node.node_type) {
            return Err(KoniError::Action(format!(
                "check {} gate policy {} winner {} has unauthorized type {}",
                check.id, policy_id, winner, node.node_type
            )));
        }
        let value = node.as_value();
        let mut variables = BTreeMap::new();
        variables.insert("gate.id".to_owned(), gate_id.to_owned());
        if binding.evaluation_targets.len() == 1
            && let Some(target_id) = binding.evaluation_targets.keys().next()
        {
            variables.insert("target.id".to_owned(), target_id.clone());
            if let Some(target) = graph.node(target_id) {
                variables.insert(format!("{}.id", target.node_type), target.id.clone());
            }
        }
        variables.insert(format!("{}.id", source.role), node.id.clone());
        variables.insert(format!("{}.id", node.node_type), node.id.clone());
        let command = lookup_dynamic_path(&value, &source.field, &variables).ok_or_else(|| {
            KoniError::Action(format!(
                "check {} gate policy {} winner {} lacks command field {}; selection will not fall through",
                check.id, policy_id, node.id, source.field
            ))
        })?;
        let argv = command_value_argv(check, command)?;
        let definition = &profile.node_types[&node.node_type];
        return Ok(ResolvedExecutionCandidate {
            kind: "gate_policy".to_owned(),
            role: source.role.clone(),
            id: node.id.clone(),
            node_type: Some(node.node_type.clone()),
            field: source.field.clone(),
            semantic_hash: semantic_receipt_node_hash(
                node,
                &definition.semantic_fields,
                &definition.compiler_owned_fields,
            ),
            value,
            argv,
            variables,
            gate_policy_binding: Some(binding),
        });
    }

    let ticket = ticket.ok_or_else(|| {
        KoniError::Action(format!(
            "dynamic check {} requires an exact ticket",
            check.id
        ))
    })?;
    let base_variables = command_variables(Some(ticket), graph);

    let authorized_ids = match source.selection {
        Some(DynamicNodeSelection::Target) => ticket.target_nodes.iter().collect::<BTreeSet<_>>(),
        Some(DynamicNodeSelection::ReadScope) => {
            ticket.scope.read_nodes.iter().collect::<BTreeSet<_>>()
        }
        None => {
            return Err(KoniError::Profile(format!(
                "node command source for check {} has no bounded selection",
                check.id
            )));
        }
    };
    let mut matches = Vec::new();
    for id in authorized_ids {
        let node = graph.node(id).ok_or_else(|| {
            KoniError::Action(format!(
                "check {} authorized command source node {} is missing",
                check.id, id
            ))
        })?;
        if !source.node_types.contains(&node.node_type) {
            continue;
        }
        let value = node.as_value();
        let mut variables = base_variables.clone();
        variables.insert(format!("{}.id", source.role), node.id.clone());
        variables.insert(format!("{}.id", node.node_type), node.id.clone());
        let Some(command) = lookup_dynamic_path(&value, &source.field, &variables) else {
            continue;
        };
        let argv = command_value_argv(check, command)?;
        let definition = profile.node_types.get(&node.node_type).ok_or_else(|| {
            KoniError::Profile(format!(
                "check {} source node {} has unknown type {}",
                check.id, node.id, node.node_type
            ))
        })?;
        matches.push(ResolvedExecutionCandidate {
            kind: "node".to_owned(),
            role: source.role.clone(),
            id: node.id.clone(),
            node_type: Some(node.node_type.clone()),
            field: source.field.clone(),
            semantic_hash: semantic_receipt_node_hash(
                node,
                &definition.semantic_fields,
                &definition.compiler_owned_fields,
            ),
            value,
            argv,
            variables,
            gate_policy_binding: None,
        });
    }
    if matches.len() != 1 {
        return Err(KoniError::Action(format!(
            "check {} resolved {} authorized {} command sources for role {}, expected exactly one",
            check.id,
            matches.len(),
            source
                .node_types
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>()
                .join("/"),
            source.role,
        )));
    }
    Ok(matches.pop().expect("one dynamic command source"))
}

fn command_value_argv(check: &crate::config::CheckDef, value: &Value) -> Result<Vec<String>> {
    let values = value.as_array().ok_or_else(|| {
        KoniError::Action(format!(
            "check {} command source is not an argv array",
            check.id
        ))
    })?;
    let argv = values
        .iter()
        .map(|value| value.as_str().map(ToOwned::to_owned))
        .collect::<Option<Vec<_>>>()
        .ok_or_else(|| {
            KoniError::Action(format!(
                "check {} command source contains a non-string argument",
                check.id
            ))
        })?;
    if !exact_argv_value_is_valid(value) {
        return Err(KoniError::Action(format!(
            "check {} command source must be one exact argv array with the executable first and one element per argument",
            check.id
        )));
    }
    Ok(argv)
}

fn semantic_command_bindings(
    profile: &CompiledProfile,
    graph: &Graph,
    ids: impl IntoIterator<Item = String>,
    owner: &str,
) -> Result<BTreeMap<String, SemanticCommandBinding>> {
    ids.into_iter()
        .collect::<BTreeSet<_>>()
        .into_iter()
        .map(|id| {
            let node = graph.node(&id).ok_or_else(|| {
                KoniError::Action(format!("{owner} references missing node {id}"))
            })?;
            let definition = profile.node_types.get(&node.node_type).ok_or_else(|| {
                KoniError::Profile(format!(
                    "{owner} references unknown node type {}",
                    node.node_type
                ))
            })?;
            Ok((
                id,
                SemanticCommandBinding {
                    node_type: node.node_type.clone(),
                    semantic_hash: semantic_receipt_node_hash(
                        node,
                        &definition.semantic_fields,
                        &definition.compiler_owned_fields,
                    ),
                },
            ))
        })
        .collect()
}

fn dynamic_bound_value<'a>(
    source: &crate::config::DynamicBoundValueSourceDef,
    candidate: &'a ResolvedExecutionCandidate,
    ticket_value: &'a Value,
) -> Option<&'a Value> {
    let root = if source.role == "ticket" {
        ticket_value
    } else if source.role == candidate.role {
        &candidate.value
    } else {
        return None;
    };
    lookup_dynamic_path(root, &source.field, &candidate.variables)
}

fn path_is_covered_by_ticket_scope(path: &str, scopes: &BTreeSet<String>) -> bool {
    scopes.iter().any(|allowed| {
        allowed == "."
            || normalized_relative_filesystem_path(allowed).is_ok_and(|allowed| {
                Path::new(path) == allowed || Path::new(path).starts_with(allowed)
            })
    })
}

fn dynamic_path_authority_matches(
    authority: &crate::config::DynamicPathAuthorityDef,
    path: &str,
    ticket: &Ticket,
) -> bool {
    match authority.authority {
        crate::config::TicketPathAuthority::ReadPaths => {
            path_is_covered_by_ticket_scope(path, &ticket.scope.read_paths)
        }
        crate::config::TicketPathAuthority::WritePaths => {
            path_is_covered_by_ticket_scope(path, &ticket.scope.write_paths)
        }
    }
}

fn dynamic_path_authorities_have_scope(
    authorities: &[crate::config::DynamicPathAuthorityDef],
    ticket: &Ticket,
) -> bool {
    authorities
        .iter()
        .any(|authority| match authority.authority {
            crate::config::TicketPathAuthority::ReadPaths => !ticket.scope.read_paths.is_empty(),
            crate::config::TicketPathAuthority::WritePaths => !ticket.scope.write_paths.is_empty(),
        })
}

fn resolved_dynamic_requirements(
    check: &crate::config::CheckDef,
    candidate: &ResolvedExecutionCandidate,
    ticket_value: &Value,
    ticket: Option<&Ticket>,
    project_root: &Path,
) -> Result<(Value, Option<String>)> {
    let Some(configured) = &check.dynamic_result else {
        return Ok((json!({}), None));
    };
    let mut requirements = Map::new();
    if let Some(required) = &configured.required_keys {
        let values = dynamic_bound_value(&required.source, candidate, ticket_value)
            .and_then(Value::as_array)
            .ok_or_else(|| {
                KoniError::Action(format!(
                    "check {} required-key source {}.{} is not an array",
                    check.id, required.source.role, required.source.field
                ))
            })?;
        let expected = values
            .iter()
            .map(Value::as_str)
            .collect::<Option<Vec<_>>>()
            .ok_or_else(|| {
                KoniError::Action(format!(
                    "check {} required-key source contains a non-string value",
                    check.id
                ))
            })?;
        let unique = expected.iter().copied().collect::<BTreeSet<_>>();
        if expected.is_empty()
            || unique.len() != expected.len()
            || expected.iter().any(|value| value.trim().is_empty())
        {
            return Err(KoniError::Action(format!(
                "check {} required-key source must be nonempty, unique, and contain nonempty strings",
                check.id
            )));
        }
        requirements.insert(
            "required_keys".to_owned(),
            json!({
                "source_role": required.source.role,
                "source_field": required.source.field,
                "actual_field": required.actual_field,
                "relation": required.relation,
                "expected": unique,
            }),
        );
    }
    if configured.result_path.is_none() && configured.artifacts.is_none() {
        return Ok((Value::Object(requirements), None));
    }
    let ticket = ticket.ok_or_else(|| {
        KoniError::Action(format!(
            "check {} dynamic result path authority requires an exact ticket",
            check.id
        ))
    })?;
    let result_path = if let Some(configured_path) = &configured.result_path {
        let source = &configured_path.source;
        match dynamic_bound_value(source, candidate, ticket_value) {
            None | Some(Value::Null) => None,
            Some(Value::String(raw)) if raw.trim().is_empty() => {
                return Err(KoniError::Action(format!(
                    "check {} result-path source {}.{} must be a nonempty project-relative path when present",
                    check.id, source.role, source.field
                )));
            }
            Some(Value::String(raw)) => {
                if !dynamic_path_authorities_have_scope(&configured_path.path_authorities, ticket) {
                    return Err(KoniError::Action(format!(
                        "check {} result path has no configured nonempty ticket path authority",
                        check.id
                    )));
                }
                let normalized = normalized_relative_path(raw)?;
                // The file may be created by the command, but its parent and
                // eventual resolution must already be project-contained.
                contained_process_path(project_root, &normalized)?;
                if !configured_path
                    .path_authorities
                    .iter()
                    .any(|authority| dynamic_path_authority_matches(authority, &normalized, ticket))
                {
                    return Err(KoniError::Action(format!(
                        "check {} result path is outside its configured ticket path authorities: {normalized}",
                        check.id
                    )));
                }
                requirements.insert(
                    "result_path".to_owned(),
                    json!({
                        "source_role": source.role,
                        "source_field": source.field,
                        "path": normalized,
                        "path_authorities": configured_path.path_authorities,
                    }),
                );
                Some(normalized)
            }
            Some(_) => {
                return Err(KoniError::Action(format!(
                    "check {} result-path source {}.{} must be a string when present",
                    check.id, source.role, source.field
                )));
            }
        }
    } else {
        None
    };
    if let Some(artifacts) = &configured.artifacts {
        requirements.insert(
            "artifacts".to_owned(),
            json!({
                "field": artifacts.field,
                "allow_path_strings": artifacts.allow_path_strings,
                "path_field": artifacts.path_field,
                "path_authorities": artifacts.path_authorities,
            }),
        );
    }
    Ok((Value::Object(requirements), result_path))
}

fn argv_input_rows(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    candidate: &ResolvedExecutionCandidate,
    graph: &Graph,
    project_root: &Path,
    ticket: Option<&Ticket>,
) -> Result<Vec<Value>> {
    let Some(bindings) = &check.argv_input_bindings else {
        return Ok(Vec::new());
    };
    validate_argv_input_bindings(
        Some(bindings),
        &candidate.value,
        &candidate.argv,
        project_root,
        &candidate.variables,
    )?;
    let inputs = lookup_dynamic_path(&candidate.value, &bindings.from, &candidate.variables)
        .and_then(Value::as_array)
        .expect("validated argv input array");
    inputs
        .iter()
        .map(|input| {
            let path = lookup_dynamic_path(input, &bindings.path_field, &candidate.variables)
                .and_then(Value::as_str)
                .unwrap_or_default();
            let file = if path.is_empty() {
                Value::Null
            } else {
                let path = normalized_relative_path(path)?;
                if let Some(ticket) = ticket
                    && !ticket.scope.read_paths.iter().any(|allowed| {
                        allowed == "."
                            || normalized_relative_filesystem_path(allowed).is_ok_and(|allowed| {
                                Path::new(&path) == allowed || Path::new(&path).starts_with(allowed)
                            })
                    })
                {
                    return Err(KoniError::Action(format!(
                        "check {} argv input path is outside ticket read scope: {path}",
                        check.id
                    )));
                }
                let concrete = contained_process_path(project_root, &path)?;
                let bytes = fs::read(&concrete).map_err(|error| io_error(&concrete, error))?;
                json!({"path": path, "bytes": bytes.len(), "sha256": raw_sha256(&bytes)})
            };
            let mut referenced_ids = BTreeSet::new();
            collect_graph_node_references(input, graph, &mut referenced_ids);
            if let Some(ticket) = ticket {
                let authorized = ticket
                    .target_nodes
                    .iter()
                    .chain(&ticket.scope.read_nodes)
                    .collect::<BTreeSet<_>>();
                let outside = referenced_ids
                    .iter()
                    .filter(|id| !authorized.contains(id))
                    .cloned()
                    .collect::<Vec<_>>();
                if !outside.is_empty() {
                    return Err(KoniError::Action(format!(
                        "check {} argv inputs reference out-of-scope graph nodes: {}",
                        check.id,
                        outside.join(", ")
                    )));
                }
            }
            let referenced_node_hashes = referenced_ids
                .into_iter()
                .map(|id| {
                    let node = graph.node(&id).expect("collected graph node exists");
                    let definition = &profile.node_types[&node.node_type];
                    (
                        id,
                        semantic_receipt_node_hash(
                            node,
                            &definition.semantic_fields,
                            &definition.compiler_owned_fields,
                        ),
                    )
                })
                .collect::<BTreeMap<_, _>>();
            Ok(json!({
                "binding": input,
                "file": file,
                "referenced_node_hashes": referenced_node_hashes,
            }))
        })
        .collect()
}

fn resolve_check_execution_with_store(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    graph: &Graph,
    project_root: &Path,
    policy_store: &StateStore,
) -> Result<ResolvedCheckExecution> {
    let invocation = ticket.map_or(CheckInvocation::Unscoped, CheckInvocation::Ticket);
    resolve_check_execution_for_invocation(
        profile,
        check,
        invocation,
        graph,
        project_root,
        policy_store,
        &mut ExecutionResolutionCache::default(),
    )
}

#[allow(clippy::too_many_arguments)]
fn resolve_current_compiled_member_execution(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    binding: &CompiledMemberExecutionBinding,
    graph: &Graph,
    project_root: &Path,
    store: &StateStore,
    cache: &mut ExecutionResolutionCache,
) -> Result<ResolvedCheckExecution> {
    let ticket = ticket.ok_or_else(|| {
        KoniError::Action(format!(
            "compiled graph-set receipt references missing ticket {}",
            binding.ticket_id
        ))
    })?;
    if ticket.id != binding.ticket_id {
        return Err(KoniError::Action(format!(
            "compiled graph-set receipt ticket {} does not match {}",
            binding.ticket_id, ticket.id
        )));
    }
    let step = ticket
        .workflow
        .iter()
        .find(|step| step.id == binding.step_id)
        .ok_or_else(|| {
            KoniError::Action(format!(
                "ticket {} no longer has compiled graph-set step {}",
                ticket.id, binding.step_id
            ))
        })?;
    let compiled_now =
        compile_graph_check_sets_for_step(profile, store, project_root, graph, ticket, step)?;
    if compiled_now != step.compiled_check_sets {
        return Err(KoniError::Action(format!(
            "ticket {} step {} graph-selected check set drifted",
            ticket.id, step.id
        )));
    }
    let set = step
        .compiled_check_sets
        .iter()
        .find(|set| {
            set.parent_check_id == binding.parent_check_id
                && set.contract_hash == binding.set_contract_hash
        })
        .ok_or_else(|| {
            KoniError::Action(format!(
                "ticket {} step {} no longer has compiled set {}",
                ticket.id, step.id, binding.parent_check_id
            ))
        })?;
    let member = set
        .members
        .iter()
        .find(|member| {
            member.source_node_id == binding.source_node_id
                && member.child_check_id == check.id
                && member.contract_hash == binding.member_contract_hash
        })
        .ok_or_else(|| {
            KoniError::Action(format!(
                "ticket {} step {} no longer has compiled member {}/{}",
                ticket.id, step.id, binding.source_node_id, check.id
            ))
        })?;
    let scoped_ticket = ticket_with_step_scope(ticket, step);
    resolve_check_execution_for_invocation(
        profile,
        check,
        CheckInvocation::CompiledMember {
            ticket: &scoped_ticket,
            step,
            set,
            member,
        },
        graph,
        project_root,
        store,
        cache,
    )
}

#[allow(clippy::too_many_arguments)]
fn resolve_gate_policy_check_execution_with_store(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    policy_id: &str,
    gate_id: &str,
    graph: &Graph,
    project_root: &Path,
    policy_store: &StateStore,
    cache: &mut ExecutionResolutionCache,
) -> Result<ResolvedCheckExecution> {
    resolve_check_execution_for_invocation(
        profile,
        check,
        CheckInvocation::GatePolicy { policy_id, gate_id },
        graph,
        project_root,
        policy_store,
        cache,
    )
}

fn resolve_check_execution_for_invocation(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    invocation: CheckInvocation<'_>,
    graph: &Graph,
    project_root: &Path,
    policy_store: &StateStore,
    cache: &mut ExecutionResolutionCache,
) -> Result<ResolvedCheckExecution> {
    let ticket = invocation_ticket(invocation);
    let source = effective_command_source(check, ticket, graph)?;
    let candidate = if let Some(source) = &source {
        resolve_execution_candidate(
            profile,
            check,
            source,
            invocation,
            graph,
            project_root,
            policy_store,
        )?
    } else {
        let argv = check.argv.clone();
        if argv.is_empty() {
            return Err(KoniError::Profile(format!(
                "check {} has no configured command",
                check.id
            )));
        }
        ResolvedExecutionCandidate {
            kind: "static".to_owned(),
            role: "configured".to_owned(),
            id: check.id.clone(),
            node_type: None,
            field: "argv".to_owned(),
            semantic_hash: normalized_hash(&argv),
            value: json!({"argv": argv}),
            argv,
            variables: command_variables(ticket, graph),
            gate_policy_binding: None,
        }
    };
    let ticket_value = ticket
        .map(|ticket| ticket_check_value(ticket, graph))
        .unwrap_or_else(|| json!({}));
    let (dynamic_requirements, result_path) =
        resolved_dynamic_requirements(check, &candidate, &ticket_value, ticket, project_root)?;
    let argv_input_rows = argv_input_rows(profile, check, &candidate, graph, project_root, ticket)?;
    let (
        target_bindings,
        read_scope_bindings,
        read_path_manifest,
        read_path_exclusions,
        produced_path_roots,
    ) = if let Some(binding) = &candidate.gate_policy_binding {
        if let Some(ticket) = ticket {
            authorize_ticket_gate_policy_execution(check, ticket, binding)?;
            for path in &binding.context_read_paths {
                if !path_is_covered_by_ticket_scope(path, &ticket.scope.read_paths) {
                    return Err(KoniError::Action(format!(
                        "check {} gate policy {} context read path {} is outside ticket read scope",
                        check.id, binding.selection.policy_id, path
                    )));
                }
            }
        }
        let read_path_exclusions =
            command_read_path_exclusions(profile, std::iter::empty::<&str>())?;
        (
            BTreeMap::new(),
            BTreeMap::new(),
            project_read_path_manifest(
                project_root,
                &binding.context_read_paths.iter().cloned().collect(),
                &read_path_exclusions,
            )?,
            read_path_exclusions.into_iter().collect(),
            Vec::new(),
        )
    } else if let Some(ticket) = ticket {
        let produced_path_roots = if check.effect == crate::config::ProcessEffect::WorkspaceWrite
            && dynamic_result_allows_produced_output(check)
        {
            ticket
                .scope
                .write_paths
                .iter()
                .map(|path| {
                    if path == "." {
                        Ok(".".to_owned())
                    } else {
                        normalized_relative_path(path)
                    }
                })
                .collect::<Result<Vec<_>>>()?
        } else {
            Vec::new()
        };
        let read_path_exclusions =
            command_read_path_exclusions(profile, produced_path_roots.iter().map(String::as_str))?;
        (
            semantic_command_bindings(
                profile,
                graph,
                ticket.target_nodes.clone(),
                &format!("check {} target scope", check.id),
            )?,
            semantic_command_bindings(
                profile,
                graph,
                ticket.scope.read_nodes.iter().cloned(),
                &format!("check {} read scope", check.id),
            )?,
            project_ticket_read_path_manifest(project_root, ticket, &read_path_exclusions)?,
            read_path_exclusions.into_iter().collect(),
            produced_path_roots,
        )
    } else {
        (
            BTreeMap::new(),
            BTreeMap::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
        )
    };
    let sandbox_read_paths = candidate
        .gate_policy_binding
        .as_ref()
        .map(|binding| binding.context_read_paths.clone())
        .or_else(|| {
            ticket.map(|ticket| ticket.scope.read_paths.iter().cloned().collect::<Vec<_>>())
        })
        .unwrap_or_default();
    let environment_policy = EnvironmentPolicy {
        inherit: !check.environment.inherit.is_empty(),
        allow: check.environment.inherit.iter().cloned().collect(),
        deny: check.environment.remove.iter().cloned().collect(),
        set: check.environment.set.clone(),
    };
    let mut environment = resolved_environment(&environment_policy, &candidate.variables)?;
    let private_temp_required = check.effect == crate::config::ProcessEffect::ReadOnly;
    if private_temp_required {
        for (key, value) in [
            ("TMPDIR", "<PRIVATE_TMP>"),
            ("XDG_CACHE_HOME", "<PRIVATE_TMP>/xdg-cache"),
            ("npm_config_cache", "<PRIVATE_TMP>/npm-cache"),
            ("CARGO_TARGET_DIR", "<PRIVATE_TMP>/cargo-target"),
            ("PYTHONPYCACHEPREFIX", "<PRIVATE_TMP>/python-cache"),
            ("COVERAGE_FILE", "<PRIVATE_TMP>/coverage"),
            ("NEXT_TELEMETRY_DISABLED", "1"),
        ] {
            environment.insert(key.to_owned(), value.to_owned());
        }
    }
    let environment_bindings = environment
        .iter()
        .map(|(name, value)| (name.clone(), raw_sha256(value.as_bytes())))
        .collect::<BTreeMap<_, _>>();
    let mut argv = candidate
        .argv
        .iter()
        .map(|argument| interpolate_command(argument, &candidate.variables))
        .collect::<Result<Vec<_>>>()?;
    if argv.is_empty() {
        return Err(KoniError::Profile(format!(
            "check {} has no resolved command",
            check.id
        )));
    }
    if let CheckInvocation::CompiledMember { member, .. } = invocation
        && argv != member.argv
    {
        return Err(KoniError::Action(format!(
            "compiled graph-set member {} command changed after ticket compilation",
            member.source_node_id
        )));
    }
    let cwd = match invocation {
        CheckInvocation::CompiledMember { member, .. } => member.working_directory.clone(),
        _ => interpolate_command(&check.cwd.to_string_lossy(), &candidate.variables)?,
    };
    let executable = resolve_executable_binding(project_root, &cwd, &argv[0], &environment, cache)?;
    if let CheckInvocation::CompiledMember { member, step, .. } = invocation {
        for path in compiled_member_project_executable_sources(
            project_root,
            &cwd,
            &member.argv,
            &executable,
        )? {
            if !member.source_paths.contains(&path) {
                return Err(KoniError::Action(format!(
                    "compiled graph-set member {} project-local executable or script {} is absent from source_paths for step {}",
                    member.source_node_id, path, step.id
                )));
            }
        }
    }
    let repository_tool = resolve_repository_tool_binding(
        check.effect,
        &argv,
        project_root,
        &cwd,
        &environment,
        profile,
        cache,
    )?;
    argv[0] = executable.resolved_path.clone();
    let script_interpreter =
        resolve_script_interpreter_binding(&executable, project_root, &cwd, &environment, cache)?;
    let (sandbox_executable, sandbox_profile_hash) = resolve_read_only_sandbox(
        check.effect,
        project_root,
        &cwd,
        &sandbox_read_paths,
        &argv,
        &environment,
        repository_tool.as_ref(),
        cache,
    )?;
    let compiled_member_binding = match invocation {
        CheckInvocation::CompiledMember {
            ticket,
            step,
            set,
            member,
        } => {
            if member.child_check_id != check.id {
                return Err(KoniError::Action(format!(
                    "compiled graph-set member expects check {}, not {}",
                    member.child_check_id, check.id
                )));
            }
            if candidate.kind != "static"
                && (candidate.id != member.source_node_id
                    || candidate.node_type.as_deref() != Some(member.source_node_type.as_str())
                    || candidate.semantic_hash != member.source_semantic_hash)
            {
                return Err(KoniError::Action(format!(
                    "compiled graph-set member {} source binding changed",
                    member.source_node_id
                )));
            }
            if member
                .source_paths
                .iter()
                .chain(&member.covered_paths)
                .any(|path| !path_is_covered_by_ticket_scope(path, &ticket.scope.read_paths))
            {
                return Err(KoniError::Action(format!(
                    "compiled graph-set member {} paths exceed step {} read authority",
                    member.source_node_id, step.id
                )));
            }
            let exclusions = command_read_path_exclusions(profile, std::iter::empty::<&str>())?;
            let source_path_manifest =
                project_source_path_manifest(project_root, &member.source_paths, &exclusions)?;
            if let Some(baseline_manifest) =
                preserved_baseline_source_path_manifest(policy_store, ticket, step, set, member)?
                && baseline_manifest != source_path_manifest
            {
                return Err(KoniError::Action(format!(
                    "ticket {} step {} source bytes changed after baseline for member {}",
                    ticket.id, step.id, member.source_node_id
                )));
            }
            let mut binding = CompiledMemberExecutionBinding {
                schema_version: "1.0".to_owned(),
                ticket_id: ticket.id.clone(),
                step_id: step.id.clone(),
                parent_check_id: set.parent_check_id.clone(),
                set_contract_hash: set.contract_hash.clone(),
                member_contract_hash: member.contract_hash.clone(),
                source_node_id: member.source_node_id.clone(),
                source_path_manifest,
                binding_hash: String::new(),
            };
            binding.binding_hash = normalized_hash(&binding);
            Some(binding)
        }
        _ => None,
    };
    let mut resolved = ResolvedCheckExecution {
        schema_version: "1.0".to_owned(),
        profile_hash: profile.hash.clone(),
        check_id: check.id.clone(),
        source_kind: candidate.kind,
        source_role: candidate.role,
        source_id: candidate.id,
        source_node_type: candidate.node_type,
        source_field: candidate.field,
        source_semantic_hash: candidate.semantic_hash,
        cwd,
        command_hash: normalized_hash(&argv),
        argv,
        environment_policy_hash: normalized_hash(&environment_policy),
        environment_bindings,
        executable,
        script_interpreter,
        repository_tool,
        sandbox_executable,
        sandbox_profile_hash,
        private_temp_required,
        target_bindings,
        read_scope_bindings,
        read_path_manifest,
        read_path_exclusions,
        produced_path_roots,
        argv_input_rows,
        dynamic_requirements,
        result_path,
        gate_policy_binding: candidate.gate_policy_binding,
        compiled_member_binding,
        binding_hash: String::new(),
    };
    resolved.binding_hash = normalized_hash(&resolved);
    Ok(resolved)
}

fn authorize_ticket_gate_policy_execution(
    check: &crate::config::CheckDef,
    ticket: &Ticket,
    binding: &GatePolicyBinding,
) -> Result<()> {
    if !ticket.target_nodes.contains(&binding.selection.gate.id) {
        return Err(KoniError::Action(format!(
            "check {} gate policy {} subject {} is not a ticket target",
            check.id, binding.selection.policy_id, binding.selection.gate.id
        )));
    }
    let authorized = ticket
        .target_nodes
        .iter()
        .chain(&ticket.scope.read_nodes)
        .chain(&ticket.scope.write_nodes)
        .cloned()
        .collect::<BTreeSet<_>>();
    let required = std::iter::once(binding.selection.gate.id.clone())
        .chain(binding.selection.winner_id.iter().cloned())
        .chain(binding.evaluation_targets.keys().cloned())
        .chain(binding.direct_gate_bindings.keys().cloned())
        .chain(binding.inherited_gate_bindings.keys().cloned())
        .chain(binding.applicability_context_bindings.keys().cloned())
        .chain(binding.context_bindings.keys().cloned())
        .collect::<BTreeSet<_>>();
    let unauthorized = required
        .difference(&authorized)
        .cloned()
        .collect::<Vec<_>>();
    if !unauthorized.is_empty() {
        return Err(KoniError::Action(format!(
            "check {} gate policy {} requires graph context outside ticket scope: {}",
            check.id,
            binding.selection.policy_id,
            unauthorized.join(", ")
        )));
    }
    Ok(())
}

fn execution_variables(
    invocation: CheckInvocation<'_>,
    execution: &ResolvedCheckExecution,
    graph: &Graph,
) -> BTreeMap<String, String> {
    let mut variables = match invocation {
        CheckInvocation::Ticket(ticket) | CheckInvocation::CompiledMember { ticket, .. } => {
            command_variables(Some(ticket), graph)
        }
        CheckInvocation::Unscoped | CheckInvocation::GatePolicy { .. } => BTreeMap::new(),
    };
    if let Some(binding) = &execution.gate_policy_binding {
        variables.insert("gate.id".to_owned(), binding.selection.gate.id.clone());
        if binding.evaluation_targets.len() == 1
            && let Some(target_id) = binding.evaluation_targets.keys().next()
        {
            variables.insert("target.id".to_owned(), target_id.clone());
            if let Some(target) = graph.node(target_id) {
                variables.insert(format!("{}.id", target.node_type), target.id.clone());
            }
        }
        variables.insert(
            format!("{}.id", execution.source_role),
            execution.source_id.clone(),
        );
        if let Some(node_type) = &execution.source_node_type {
            variables.insert(format!("{node_type}.id"), execution.source_id.clone());
        }
    }
    variables
}

fn compiled_member_project_executable_sources(
    project_root: &Path,
    cwd: &str,
    semantic_argv: &[String],
    executable: &ExecutableBinding,
) -> Result<BTreeSet<String>> {
    let mut sources = BTreeSet::new();
    if executable.path_kind == "project_relative" {
        sources.insert(normalized_relative_path(&executable.resolved_path)?);
    }
    if semantic_argv
        .first()
        .is_some_and(|argument| compiled_command_basename(argument) == "env")
    {
        return Err(KoniError::Action(
            "compiled graph-set members cannot use an env command wrapper; declare the exact environment in the check policy and invoke the executable directly"
                .to_owned(),
        ));
    }
    let interpreter = compiled_member_interpreter(semantic_argv);
    if interpreter.as_ref().is_some_and(|(index, name)| {
        compiled_member_shell_uses_command_string(name, &semantic_argv[index + 1..])
    }) {
        return Err(KoniError::Action(
            "compiled graph-set members cannot use a shell command string; encode one executable and its arguments directly in argv"
                .to_owned(),
        ));
    }
    let infer_interpreter_script = interpreter
        .as_ref()
        .is_some_and(|(_, name)| compiled_member_interpreter_names_script(name))
        && !interpreter.as_ref().is_some_and(|(index, name)| {
            compiled_member_interpreter_uses_inline_program(name, &semantic_argv[index + 1..])
        });
    let interpreter_index = interpreter.as_ref().map(|(index, _)| *index);
    let mut interpreter_script_bound = false;
    for (index, argument) in semantic_argv.iter().enumerate().skip(1) {
        if Some(index) == interpreter_index {
            continue;
        }
        if argument.starts_with('-') || argument.trim().is_empty() {
            continue;
        }
        let argument_path = Path::new(argument);
        let relative = if argument_path.is_absolute() {
            let Ok(relative) = argument_path.strip_prefix(project_root) else {
                continue;
            };
            normalized_project_path(relative)
        } else {
            normalized_relative_path(&Path::new(cwd).join(argument_path).to_string_lossy())?
        };
        let path = contained_process_path(project_root, &relative)?;
        let Ok(metadata) = fs::symlink_metadata(&path) else {
            continue;
        };
        if metadata.is_dir() {
            continue;
        }
        if infer_interpreter_script && !interpreter_script_bound {
            sources.insert(relative);
            interpreter_script_bound = true;
            continue;
        }
        let bytes = fs::read(&path).map_err(|error| io_error(&path, error))?;
        #[cfg(unix)]
        let executable_mode = metadata.mode() & 0o111 != 0;
        #[cfg(not(unix))]
        let executable_mode = false;
        if executable_mode || bytes.starts_with(b"#!") {
            sources.insert(relative);
        }
    }
    Ok(sources)
}

fn compiled_member_interpreter(semantic_argv: &[String]) -> Option<(usize, String)> {
    Some((0, compiled_command_basename(semantic_argv.first()?)))
}

fn compiled_command_basename(argument: &str) -> String {
    Path::new(argument)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(argument)
        .trim_end_matches(".exe")
        .to_ascii_lowercase()
}

fn compiled_member_shell_uses_command_string(name: &str, arguments: &[String]) -> bool {
    if !matches!(
        name,
        "sh" | "bash" | "dash" | "zsh" | "ksh" | "mksh" | "fish"
    ) {
        return false;
    }
    let mut index = 0;
    while let Some(argument) = arguments.get(index) {
        if argument == "--" || !argument.starts_with('-') {
            return false;
        }
        if argument == "--command"
            || argument.starts_with("--command=")
            || (!argument.starts_with("--") && argument[1..].chars().any(|option| option == 'c'))
        {
            return true;
        }
        index += if matches!(argument.as_str(), "-o" | "+o" | "-O" | "+O") {
            2
        } else {
            1
        };
    }
    false
}

fn compiled_member_interpreter_names_script(name: &str) -> bool {
    matches!(
        name,
        "sh" | "bash"
            | "dash"
            | "zsh"
            | "ksh"
            | "mksh"
            | "fish"
            | "ruby"
            | "perl"
            | "php"
            | "lua"
            | "luajit"
            | "node"
            | "bun"
            | "deno"
            | "rscript"
    ) || compiled_member_python_interpreter(name)
}

fn compiled_member_interpreter_uses_inline_program(name: &str, arguments: &[String]) -> bool {
    let flags = arguments
        .iter()
        .take_while(|argument| argument.starts_with('-'))
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    if compiled_member_python_interpreter(name) {
        return flags.contains("-c") || flags.contains("-m");
    }
    if matches!(name, "node" | "bun" | "deno") {
        return flags.contains("-e")
            || flags.contains("--eval")
            || flags.contains("-p")
            || flags.contains("--print");
    }
    if matches!(name, "ruby" | "perl" | "lua" | "luajit" | "rscript") {
        return flags.contains("-e") || flags.contains("-E") || flags.contains("--eval");
    }
    name == "php" && flags.contains("-r")
}

fn compiled_member_python_interpreter(name: &str) -> bool {
    ["python", "pypy"].iter().any(|prefix| {
        name.strip_prefix(prefix).is_some_and(|suffix| {
            suffix.is_empty()
                || suffix
                    .chars()
                    .all(|character| character.is_ascii_digit() || character == '.')
        })
    })
}

fn resolve_executable_binding(
    project_root: &Path,
    cwd: &str,
    requested: &str,
    environment: &BTreeMap<String, String>,
    cache: &mut ExecutionResolutionCache,
) -> Result<ExecutableBinding> {
    if requested.trim().is_empty() || requested.contains('\0') {
        return Err(KoniError::Process(
            "resolved executable must be nonempty and NUL-free".to_owned(),
        ));
    }
    let command_cwd = contained_process_path(project_root, cwd)?;
    let requested_path = Path::new(requested);
    let resolved = if requested_path.is_absolute() || requested.contains('/') {
        let candidate = if requested_path.is_absolute() {
            requested_path.to_path_buf()
        } else {
            command_cwd.join(requested_path)
        };
        canonical_regular_executable(&candidate, requested)?
    } else {
        let path_value = environment.get("PATH").ok_or_else(|| {
            KoniError::Process(format!(
                "cannot resolve executable {requested}: the bound environment has no PATH"
            ))
        })?;
        let mut found = None;
        for entry in std::env::split_paths(path_value) {
            let directory = if entry.as_os_str().is_empty() {
                command_cwd.clone()
            } else if entry.is_absolute() {
                entry
            } else {
                command_cwd.join(entry)
            };
            let candidate = directory.join(requested);
            if !candidate.exists() {
                continue;
            }
            found = Some(canonical_regular_executable(&candidate, requested)?);
            break;
        }
        found.ok_or_else(|| {
            KoniError::Process(format!(
                "cannot resolve executable {requested} from the bound PATH"
            ))
        })?
    };
    let metadata = fs::metadata(&resolved).map_err(|error| io_error(&resolved, error))?;
    #[cfg(unix)]
    if metadata.mode() & 0o111 == 0 {
        return Err(KoniError::Process(format!(
            "resolved executable {requested} at {} has no executable permission bit",
            resolved.display()
        )));
    }
    let modified = metadata
        .modified()
        .ok()
        .and_then(|value| value.duration_since(UNIX_EPOCH).ok())
        .map(|value| value.as_nanos());
    let resolved_path = resolved.to_str().ok_or_else(|| {
        KoniError::Process(format!(
            "resolved executable path is not UTF-8: {}",
            resolved.display()
        ))
    })?;
    let path_hash = raw_sha256(
        environment
            .get("PATH")
            .map(String::as_bytes)
            .unwrap_or_default(),
    );
    let key = (resolved_path.to_owned(), path_hash);
    if let Some((size, cached_modified, binding)) = cache.executables.get(&key)
        && *size == metadata.len()
        && *cached_modified == modified
    {
        return Ok(binding.clone());
    }
    let bytes = fs::read(&resolved).map_err(|error| io_error(&resolved, error))?;
    let canonical_project_root = project_root.canonicalize().ok();
    let project_relative = canonical_project_root
        .as_ref()
        .and_then(|root| resolved.strip_prefix(root).ok())
        .map(normalized_project_path);
    let binding = ExecutableBinding {
        requested: requested.to_owned(),
        path_kind: if project_relative.is_some() {
            "project_relative"
        } else {
            "external_absolute"
        }
        .to_owned(),
        resolved_path: project_relative.unwrap_or_else(|| resolved_path.to_owned()),
        size_bytes: bytes.len() as u64,
        sha256: raw_sha256(&bytes),
        #[cfg(unix)]
        mode: Some(metadata.mode()),
        #[cfg(not(unix))]
        mode: None,
        #[cfg(unix)]
        device: canonical_project_root
            .as_ref()
            .is_none_or(|root| !resolved.starts_with(root))
            .then_some(metadata.dev()),
        #[cfg(not(unix))]
        device: None,
        #[cfg(unix)]
        inode: canonical_project_root
            .as_ref()
            .is_none_or(|root| !resolved.starts_with(root))
            .then_some(metadata.ino()),
        #[cfg(not(unix))]
        inode: None,
        modified_ns: canonical_project_root
            .as_ref()
            .is_none_or(|root| !resolved.starts_with(root))
            .then_some(modified)
            .flatten(),
    };
    cache
        .executables
        .insert(key, (metadata.len(), modified, binding.clone()));
    Ok(binding)
}

fn canonical_regular_executable(path: &Path, requested: &str) -> Result<PathBuf> {
    let metadata = fs::symlink_metadata(path).map_err(|error| {
        KoniError::Process(format!(
            "cannot inspect executable {requested} at {}: {error}",
            path.display()
        ))
    })?;
    if metadata.file_type().is_symlink() {
        let target = path.canonicalize().map_err(|error| io_error(path, error))?;
        let target_metadata = fs::metadata(&target).map_err(|error| io_error(&target, error))?;
        if !target_metadata.is_file() {
            return Err(KoniError::Process(format!(
                "resolved executable {requested} symlink target is not a regular file"
            )));
        }
        return Ok(target);
    }
    if !metadata.is_file() {
        return Err(KoniError::Process(format!(
            "resolved executable {requested} is not a regular file"
        )));
    }
    path.canonicalize().map_err(|error| io_error(path, error))
}

fn resolve_script_interpreter_binding(
    executable: &ExecutableBinding,
    project_root: &Path,
    cwd: &str,
    environment: &BTreeMap<String, String>,
    cache: &mut ExecutionResolutionCache,
) -> Result<Option<ScriptInterpreterBinding>> {
    let script_path = executable_spawn_path(executable, project_root)?;
    let mut prefix = Vec::new();
    fs::File::open(&script_path)
        .map_err(|error| io_error(&script_path, error))?
        .take(4096)
        .read_to_end(&mut prefix)
        .map_err(|error| io_error(&script_path, error))?;
    if !prefix.starts_with(b"#!") {
        return Ok(None);
    }
    let line_end = prefix
        .iter()
        .position(|byte| *byte == b'\n')
        .unwrap_or(prefix.len());
    let line = std::str::from_utf8(&prefix[2..line_end]).map_err(|_| {
        KoniError::Process(format!(
            "executable script {} has a non-UTF-8 shebang",
            script_path.display()
        ))
    })?;
    let mut words = line
        .trim_end_matches('\r')
        .split_ascii_whitespace()
        .map(str::to_owned)
        .collect::<Vec<_>>();
    if words.is_empty() {
        return Err(KoniError::Process(format!(
            "executable script {} has an empty shebang",
            script_path.display()
        )));
    }
    let launcher = words.remove(0);
    let launcher_name = Path::new(&launcher)
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(&launcher);
    let (requested, arguments) = if launcher_name == "env" {
        if words
            .first()
            .is_some_and(|word| matches!(word.as_str(), "-S" | "--split-string" | "--"))
        {
            words.remove(0);
        }
        let requested = words.first().cloned().ok_or_else(|| {
            KoniError::Process(format!(
                "executable script {} uses env without an interpreter",
                script_path.display()
            ))
        })?;
        if requested.starts_with('-') || requested.contains('=') {
            return Err(KoniError::Process(format!(
                "executable script {} uses unsupported env shebang options; use `env -S <interpreter> [args]`",
                script_path.display()
            )));
        }
        words.remove(0);
        (requested, words)
    } else {
        (launcher, words)
    };
    let interpreter =
        resolve_executable_binding(project_root, cwd, &requested, environment, cache)?;
    let interpreter_path = executable_spawn_path(&interpreter, project_root)?;
    if interpreter_path == script_path {
        return Err(KoniError::Process(format!(
            "executable script {} resolves its shebang back to itself",
            script_path.display()
        )));
    }
    let mut interpreter_prefix = [0_u8; 2];
    let mut interpreter_file =
        fs::File::open(&interpreter_path).map_err(|error| io_error(&interpreter_path, error))?;
    let count = interpreter_file
        .read(&mut interpreter_prefix)
        .map_err(|error| io_error(&interpreter_path, error))?;
    if count == interpreter_prefix.len() && interpreter_prefix == *b"#!" {
        return Err(KoniError::Process(format!(
            "script interpreter {} is itself a script; declare a native interpreter explicitly",
            interpreter_path.display()
        )));
    }
    let support = (executable.path_kind == "external_absolute")
        .then(|| script_support_binding(&script_path))
        .transpose()?;
    Ok(Some(ScriptInterpreterBinding {
        executable: interpreter,
        arguments,
        support,
    }))
}

fn script_support_binding(script_path: &Path) -> Result<ScriptSupportBinding> {
    const MAX_SUPPORT_FILES: usize = 4096;
    const MAX_SUPPORT_BYTES: u64 = 128 * 1024 * 1024;

    let parent = script_path.parent().ok_or_else(|| {
        KoniError::Process(format!(
            "executable script {} has no support directory",
            script_path.display()
        ))
    })?;
    // Package-manager shims commonly live in `<package>/dist` but resolve
    // their own package manifest and bundled modules from `<package>`. Bind
    // the nearest package root instead of authorizing an unhashed parent at
    // runtime. The bounded ancestor search avoids accidentally inventorying a
    // user's entire home or toolchain tree for an unrelated loose script.
    let root = parent
        .ancestors()
        .take(5)
        .find(|ancestor| ancestor.join("package.json").is_file())
        .unwrap_or(parent);
    let root = root.canonicalize().map_err(|error| io_error(root, error))?;
    let mut files = Vec::new();
    let mut total_bytes = 0_u64;
    for entry in WalkDir::new(&root).follow_links(false) {
        let entry = entry.map_err(|error| {
            KoniError::Process(format!(
                "could not inventory script support directory {}: {error}",
                root.display()
            ))
        })?;
        if entry.path() == root {
            continue;
        }
        if entry.file_type().is_symlink() {
            return Err(KoniError::Process(format!(
                "script support directory {} contains unsupported symlink {}",
                root.display(),
                entry.path().display()
            )));
        }
        let metadata = entry
            .metadata()
            .map_err(|error| KoniError::Process(error.to_string()))?;
        if !metadata.is_file() {
            continue;
        }
        total_bytes = total_bytes.checked_add(metadata.len()).ok_or_else(|| {
            KoniError::Process("script support inventory size overflowed".to_owned())
        })?;
        if files.len() >= MAX_SUPPORT_FILES || total_bytes > MAX_SUPPORT_BYTES {
            return Err(KoniError::Process(format!(
                "script support directory {} exceeds the bound inventory limit of {MAX_SUPPORT_FILES} files or {MAX_SUPPORT_BYTES} bytes",
                root.display()
            )));
        }
        let bytes = fs::read(entry.path()).map_err(|error| io_error(entry.path(), error))?;
        let relative = entry.path().strip_prefix(&root).map_err(|_| {
            KoniError::Process("script support inventory escaped its root".to_owned())
        })?;
        files.push(ScriptSupportFileBinding {
            path: normalized_project_path(relative),
            size_bytes: metadata.len(),
            sha256: raw_sha256(&bytes),
        });
    }
    files.sort_by(|left, right| left.path.cmp(&right.path));
    Ok(ScriptSupportBinding {
        root: root.to_string_lossy().into_owned(),
        files,
    })
}

#[allow(clippy::too_many_arguments)]
fn resolve_repository_tool_binding(
    effect: crate::config::ProcessEffect,
    argv: &[String],
    project_root: &Path,
    cwd: &str,
    environment: &BTreeMap<String, String>,
    profile: &CompiledProfile,
    cache: &mut ExecutionResolutionCache,
) -> Result<Option<RepositoryToolBinding>> {
    if effect != crate::config::ProcessEffect::ReadOnly
        || argv.len() < 3
        || compiled_command_basename(&argv[0]) != "pnpm"
        || argv[1] != "exec"
    {
        return Ok(None);
    }
    let tool = argv[2].trim();
    if tool.is_empty()
        || tool.starts_with('-')
        || tool.contains('/')
        || tool.contains('\\')
        || tool.contains('\0')
    {
        return Err(KoniError::Process(
            "pnpm exec requires one plain repository-local tool name".to_owned(),
        ));
    }
    let command_cwd = contained_process_path(project_root, cwd)?;
    let shim = command_cwd.join("node_modules").join(".bin").join(tool);
    let metadata = fs::symlink_metadata(&shim).map_err(|error| {
        KoniError::Process(format!(
            "cannot bind pnpm exec tool {tool} at {}: {error}",
            shim.display()
        ))
    })?;
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() > 256 * 1024 {
        return Err(KoniError::Process(format!(
            "pnpm exec tool shim must be a bounded regular file: {}",
            shim.display()
        )));
    }
    let shim_text = fs::read_to_string(&shim).map_err(|error| io_error(&shim, error))?;
    let target = shim_text
        .lines()
        .find_map(|line| line.strip_prefix("# cmd-shim-target="))
        .filter(|target| !target.trim().is_empty())
        .ok_or_else(|| {
            KoniError::Process(format!(
                "pnpm exec tool shim {} has no compiler-bindable cmd-shim target",
                shim.display()
            ))
        })?;
    let target = PathBuf::from(target);
    let target = if target.is_absolute() {
        target
    } else {
        shim.parent().expect("tool shim has a parent").join(target)
    };
    let target = target
        .canonicalize()
        .map_err(|error| io_error(&target, error))?;
    let canonical_root = project_root
        .canonicalize()
        .map_err(|error| io_error(project_root, error))?;
    let target_relative = target.strip_prefix(&canonical_root).map_err(|_| {
        KoniError::Process(format!(
            "pnpm exec tool {tool} resolved outside the project: {}",
            target.display()
        ))
    })?;
    if !target_relative
        .components()
        .any(|component| component.as_os_str() == "node_modules")
    {
        return Err(KoniError::Process(format!(
            "pnpm exec tool {tool} did not resolve inside project node_modules"
        )));
    }
    let executable = resolve_executable_binding(
        project_root,
        cwd,
        target.to_str().ok_or_else(|| {
            KoniError::Process("repository tool target path is not UTF-8".to_owned())
        })?,
        environment,
        cache,
    )?;
    let script_interpreter =
        resolve_script_interpreter_binding(&executable, project_root, cwd, environment, cache)?;

    let mut package_state_paths = BTreeSet::from([
        canonical_root.join("package.json"),
        canonical_root.join("pnpm-lock.yaml"),
        canonical_root.join("pnpm-workspace.yaml"),
        canonical_root.join("node_modules/.modules.yaml"),
        canonical_root.join("node_modules/.pnpm-workspace-state-v1.json"),
        command_cwd.join("package.json"),
        command_cwd.join("tsconfig.json"),
    ]);
    for ancestor in target
        .ancestors()
        .take_while(|path| path.starts_with(&canonical_root))
    {
        let manifest = ancestor.join("package.json");
        if manifest.is_file() {
            package_state_paths.insert(manifest);
            break;
        }
    }
    for name in [
        "vitest.config.ts",
        "vitest.config.mts",
        "vitest.config.js",
        "vitest.config.mjs",
        "vite.config.ts",
        "vite.config.mts",
        "vite.config.js",
        "vite.config.mjs",
    ] {
        package_state_paths.insert(command_cwd.join(name));
    }
    let mut package_state = Vec::new();
    for path in package_state_paths {
        let Ok(metadata) = fs::symlink_metadata(&path) else {
            continue;
        };
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err(KoniError::Process(format!(
                "repository package state is redirected or not a file: {}",
                path.display()
            )));
        }
        let bytes = fs::read(&path).map_err(|error| io_error(&path, error))?;
        let relative = path.strip_prefix(&canonical_root).map_err(|_| {
            KoniError::Process("repository package state escaped its project".to_owned())
        })?;
        package_state.push(ScriptSupportFileBinding {
            path: normalized_project_path(relative),
            size_bytes: metadata.len(),
            sha256: raw_sha256(&bytes),
        });
    }
    package_state.sort_by(|left, right| left.path.cmp(&right.path));
    let workspace_snapshot_hash = repository_source_snapshot_hash(&canonical_root, profile)?;
    let mut binding = RepositoryToolBinding {
        schema_version: "1.0".to_owned(),
        manager: "pnpm".to_owned(),
        tool: tool.to_owned(),
        argument_start: 3,
        executable,
        script_interpreter,
        workspace_snapshot_hash,
        package_state,
        binding_hash: String::new(),
    };
    binding.binding_hash = normalized_hash(&binding);
    Ok(Some(binding))
}

/// Bind the repository bytes available to a dynamically loading test runner
/// without traversing generated dependency stores. The Git index binds every
/// tracked blob cheaply; exact worktree fingerprints bind only modified or
/// untracked, non-ignored product paths. Ignored credentials are excluded from
/// this hash and denied explicitly by the read-only sandbox.
fn repository_source_snapshot_hash(root: &Path, profile: &CompiledProfile) -> Result<String> {
    let canonical_root = root.canonicalize().map_err(|error| io_error(root, error))?;
    let repository = git2::Repository::discover(&canonical_root).map_err(|error| {
        KoniError::Process(format!(
            "repository-native tool execution requires a Git worktree: {error}"
        ))
    })?;
    let workdir = repository.workdir().ok_or_else(|| {
        KoniError::Process(
            "repository-native tool execution requires a non-bare Git worktree".to_owned(),
        )
    })?;
    let canonical_workdir = workdir
        .canonicalize()
        .map_err(|error| io_error(workdir, error))?;
    let project_prefix = canonical_root
        .strip_prefix(&canonical_workdir)
        .map_err(|_| {
            KoniError::Process("repository-native tool root escaped its Git worktree".to_owned())
        })?;
    let head = repository.head().ok().map(|head| {
        format!(
            "{}:{}",
            head.name().unwrap_or("DETACHED"),
            head.target()
                .map(|oid| oid.to_string())
                .unwrap_or_else(|| "UNBORN".to_owned())
        )
    });
    let index_path = repository.path().join("index");
    let index_hash = fs::read(&index_path)
        .map_err(|error| io_error(&index_path, error))
        .map(|bytes| raw_sha256(&bytes))?;
    let mut paths = BTreeMap::new();
    for (repository_relative, status_bits) in
        repository_native_status_paths(&canonical_workdir, project_prefix)?
    {
        let Ok(project_relative) = repository_relative.strip_prefix(project_prefix) else {
            continue;
        };
        if project_relative.as_os_str().is_empty()
            || workspace_guard_path_excluded(profile, project_relative)
        {
            continue;
        }
        paths.insert(
            normalized_project_path(project_relative),
            workspace_path_fingerprint(
                &canonical_root.join(project_relative),
                Some(status_bits),
                None,
            )?,
        );
    }
    Ok(normalized_hash(&json!({
        "schema_version": "1.0",
        "head": head,
        "index_hash": index_hash,
        "paths": paths,
    })))
}

/// Ask the repository's native Git implementation for only tracked-dirty and
/// non-ignored untracked paths. libgit2's recursive status iterator walks
/// ignored dependency stores before it can prune them in large linked
/// worktrees; native Git applies the repository's ignore/index machinery at
/// the directory boundary and avoids turning a sub-second check into minutes
/// of compiler CPU. The index bytes are hashed separately by the caller, and
/// every path returned here is still content-fingerprinted before admission.
fn repository_native_status_paths(
    canonical_workdir: &Path,
    project_prefix: &Path,
) -> Result<Vec<(PathBuf, u32)>> {
    #[cfg(target_os = "macos")]
    let git = Path::new("/usr/bin/git");
    #[cfg(not(target_os = "macos"))]
    let git = Path::new("git");

    let pathspec = if project_prefix.as_os_str().is_empty() {
        ".".to_owned()
    } else {
        project_prefix
            .to_str()
            .ok_or_else(|| {
                KoniError::Process("repository-native tool project prefix is not UTF-8".to_owned())
            })?
            .to_owned()
    };
    let output = Command::new(git)
        .current_dir(canonical_workdir)
        .args([
            "--no-optional-locks",
            "-c",
            "status.relativePaths=false",
            "-c",
            "core.fsmonitor=false",
            "status",
            "--porcelain=v1",
            "-z",
            "--untracked-files=all",
            "--ignored=no",
            "--no-renames",
            "--",
            &pathspec,
        ])
        .env("GIT_OPTIONAL_LOCKS", "0")
        .env("GIT_PAGER", "cat")
        .env("LC_ALL", "C")
        .env_remove("GIT_DIR")
        .env_remove("GIT_WORK_TREE")
        .env_remove("GIT_INDEX_FILE")
        .env_remove("GIT_OBJECT_DIRECTORY")
        .env_remove("GIT_ALTERNATE_OBJECT_DIRECTORIES")
        .output()
        .map_err(|error| {
            KoniError::Process(format!(
                "could not inspect repository-native tool source state with {}: {error}",
                git.display()
            ))
        })?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(KoniError::Process(format!(
            "repository-native tool source-state inspection failed: {}",
            stderr.chars().take(2048).collect::<String>()
        )));
    }

    let mut rows = Vec::new();
    for row in output.stdout.split(|byte| *byte == 0) {
        if row.is_empty() {
            continue;
        }
        if row.len() < 4 || row[2] != b' ' {
            return Err(KoniError::Process(
                "native Git returned malformed porcelain status".to_owned(),
            ));
        }
        if &row[..2] == b"!!" {
            continue;
        }
        let path = std::str::from_utf8(&row[3..]).map_err(|_| {
            KoniError::Process("native Git returned a non-UTF-8 status path".to_owned())
        })?;
        rows.push((
            PathBuf::from(path),
            git_porcelain_status_bits(row[0], row[1])?,
        ));
    }
    rows.sort_by(|left, right| left.0.cmp(&right.0));
    Ok(rows)
}

fn git_porcelain_status_bits(index: u8, worktree: u8) -> Result<u32> {
    if index == b'?' && worktree == b'?' {
        return Ok(Status::WT_NEW.bits());
    }
    if index == b'U' || worktree == b'U' || matches!((index, worktree), (b'A', b'A') | (b'D', b'D'))
    {
        return Ok(Status::CONFLICTED.bits());
    }
    let mut status = Status::CURRENT;
    status |= match index {
        b' ' => Status::CURRENT,
        b'A' => Status::INDEX_NEW,
        b'M' => Status::INDEX_MODIFIED,
        b'D' => Status::INDEX_DELETED,
        b'R' | b'C' => Status::INDEX_RENAMED,
        b'T' => Status::INDEX_TYPECHANGE,
        other => {
            return Err(KoniError::Process(format!(
                "native Git returned unsupported index status byte {other}"
            )));
        }
    };
    status |= match worktree {
        b' ' => Status::CURRENT,
        b'M' => Status::WT_MODIFIED,
        b'D' => Status::WT_DELETED,
        b'R' | b'C' => Status::WT_RENAMED,
        b'T' => Status::WT_TYPECHANGE,
        other => {
            return Err(KoniError::Process(format!(
                "native Git returned unsupported worktree status byte {other}"
            )));
        }
    };
    Ok(status.bits())
}

#[allow(clippy::too_many_arguments)]
fn resolve_read_only_sandbox(
    effect: crate::config::ProcessEffect,
    project_root: &Path,
    cwd: &str,
    read_paths: &[String],
    argv: &[String],
    environment: &BTreeMap<String, String>,
    repository_tool: Option<&RepositoryToolBinding>,
    cache: &mut ExecutionResolutionCache,
) -> Result<(Option<ExecutableBinding>, Option<String>)> {
    if effect != crate::config::ProcessEffect::ReadOnly {
        return Ok((None, None));
    }
    #[cfg(target_os = "macos")]
    {
        let sandbox_path = Path::new("/usr/bin/sandbox-exec");
        if !sandbox_path.is_file() {
            return Err(KoniError::Process(
                "read-only checks require /usr/bin/sandbox-exec on macOS".to_owned(),
            ));
        }
        let sandbox = resolve_executable_binding(
            project_root,
            cwd,
            sandbox_path.to_str().expect("static sandbox path is UTF-8"),
            environment,
            cache,
        )?;
        let contract = json!({
            "version": "macos-seatbelt.v2",
            "read_paths": read_paths,
            "private_tmp": true,
            "network": "denied",
            "semantic_argv": argv,
            "repository_tool": repository_tool,
        });
        Ok((Some(sandbox), Some(normalized_hash(&contract))))
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = (
            project_root,
            cwd,
            read_paths,
            argv,
            environment,
            repository_tool,
            cache,
        );
        Ok((None, None))
    }
}

fn create_private_check_temp(
    required: bool,
    project_root: &Path,
    state_root: &Path,
) -> Result<Option<PathBuf>> {
    if !required {
        return Ok(None);
    }
    #[cfg(target_os = "macos")]
    let base = Path::new("/private/tmp");
    #[cfg(not(target_os = "macos"))]
    let base = Path::new("/tmp");
    let base = base.canonicalize().map_err(|error| io_error(base, error))?;
    let project_root = project_root
        .canonicalize()
        .map_err(|error| io_error(project_root, error))?;
    let state_root = state_root
        .canonicalize()
        .map_err(|error| io_error(state_root, error))?;
    for _ in 0..16 {
        let path = base.join(format!(".koni-read-only-{}", Uuid::now_v7()));
        if path.starts_with(&project_root)
            || path.starts_with(&state_root)
            || project_root.starts_with(&path)
            || state_root.starts_with(&path)
        {
            continue;
        }
        let mut builder = fs::DirBuilder::new();
        #[cfg(unix)]
        builder.mode(0o700);
        match builder.create(&path) {
            Ok(()) => return Ok(Some(path)),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) => return Err(io_error(&path, error)),
        }
    }
    Err(KoniError::Process(
        "could not allocate a private read-only command scratch directory".to_owned(),
    ))
}

fn cleanup_private_check_temp(path: Option<&Path>) -> Result<()> {
    let Some(path) = path else {
        return Ok(());
    };
    let metadata = fs::symlink_metadata(path).map_err(|error| io_error(path, error))?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(KoniError::Process(format!(
            "refusing to clean untrusted scratch path {}",
            path.display()
        )));
    }
    fs::remove_dir_all(path).map_err(|error| io_error(path, error))
}

fn rendered_command_argv(
    execution: &ResolvedCheckExecution,
    project_root: &Path,
    state_root: &Path,
    profile: &CompiledProfile,
    private_temp: Option<&Path>,
) -> Result<(Vec<String>, Value)> {
    let (executable_path, active_interpreter, mut semantic_argv) =
        if let Some(repository_tool) = &execution.repository_tool {
            if repository_tool.argument_start > execution.argv.len() {
                return Err(KoniError::Process(
                    "repository tool argument boundary exceeds its command".to_owned(),
                ));
            }
            let executable_path = executable_spawn_path(&repository_tool.executable, project_root)?;
            let mut semantic_argv = vec![executable_path.to_string_lossy().into_owned()];
            semantic_argv.extend(
                execution
                    .argv
                    .iter()
                    .skip(repository_tool.argument_start)
                    .cloned(),
            );
            (
                executable_path,
                repository_tool.script_interpreter.as_ref(),
                semantic_argv,
            )
        } else {
            let executable_path = executable_spawn_path(&execution.executable, project_root)?;
            let mut semantic_argv = execution.argv.clone();
            if let Some(program) = semantic_argv.first_mut() {
                *program = executable_path.to_string_lossy().into_owned();
            }
            (
                executable_path,
                execution.script_interpreter.as_ref(),
                semantic_argv,
            )
        };
    if let Some(binding) = active_interpreter {
        let interpreter_path = executable_spawn_path(&binding.executable, project_root)?;
        let mut interpreted =
            Vec::with_capacity(2 + binding.arguments.len() + semantic_argv.len().saturating_sub(1));
        interpreted.push(interpreter_path.to_string_lossy().into_owned());
        interpreted.extend(binding.arguments.iter().cloned());
        interpreted.push(executable_path.to_string_lossy().into_owned());
        interpreted.extend(semantic_argv.into_iter().skip(1));
        semantic_argv = interpreted;
    }
    let Some(sandbox) = &execution.sandbox_executable else {
        return Ok((
            semantic_argv,
            json!({
                "kind": "none",
                "semantic_argv_hash": normalized_hash(&execution.argv),
                "script_interpreter": execution.script_interpreter,
                "repository_tool": execution.repository_tool,
            }),
        ));
    };
    #[cfg(target_os = "macos")]
    {
        let project_root = project_root
            .canonicalize()
            .map_err(|error| io_error(project_root, error))?;
        let state_root = state_root
            .canonicalize()
            .map_err(|error| io_error(state_root, error))?;
        let mut readable_roots = BTreeSet::from([
            PathBuf::from("/System"),
            PathBuf::from("/usr"),
            PathBuf::from("/bin"),
            PathBuf::from("/sbin"),
            PathBuf::from("/Library"),
            // `/etc` is the public alias applications open while its
            // canonical contents live under the already-authorized
            // `/private/etc`. Seatbelt evaluates the user-space spelling,
            // so both equivalent roots are required for libc resolution of
            // local names such as `localhost`.
            PathBuf::from("/etc"),
            PathBuf::from("/private/etc"),
            PathBuf::from("/private/var/db/timezone"),
        ]);
        let mut readable_files = BTreeSet::from([executable_path.clone()]);
        if execution.repository_tool.is_some() {
            // Test runners resolve configuration, workspace packages, and
            // transitive source imports dynamically. The exact Git/index/
            // dirty snapshot is part of RepositoryToolBinding, so this broad
            // read remains content-bound while all writes and compiler-owned
            // paths stay denied below.
            readable_roots.insert(project_root.clone());
        }
        // Native runtimes such as Node call `getcwd(3)` during bootstrap. On
        // macOS Seatbelt, ancestor metadata plus the root data literal is not
        // sufficient for that lookup: the exact current directory also needs
        // file-read-data authority. Keep this a literal (never a subpath) so
        // it permits cwd resolution without widening the declared source-file
        // manifest to the rest of the working tree.
        let working_directory_path = contained_process_path(&project_root, &execution.cwd)?;
        let working_directory = working_directory_path
            .canonicalize()
            .map_err(|error| io_error(&working_directory_path, error))?;
        readable_files.insert(working_directory.clone());
        if let Some(binding) = active_interpreter {
            readable_files.insert(executable_spawn_path(&binding.executable, &project_root)?);
            if let Some(support) = &binding.support {
                readable_roots.insert(PathBuf::from(&support.root));
            }
        }
        for runtime_file in &readable_files {
            if runtime_file.starts_with("/opt/homebrew/") {
                readable_roots.insert(PathBuf::from("/opt/homebrew"));
            }
            if runtime_file.starts_with("/usr/local/") {
                readable_roots.insert(PathBuf::from("/usr/local"));
            }
        }
        let manifest_files = execution
            .read_path_manifest
            .iter()
            .filter_map(|manifest| manifest.get("files").and_then(Value::as_array))
            .flatten()
            .filter_map(|file| file.get("path").and_then(Value::as_str))
            .collect::<Vec<_>>();
        for configured in manifest_files {
            let resolved = contained_process_path(&project_root, configured)?;
            readable_files.insert(
                resolved
                    .canonicalize()
                    .map_err(|error| io_error(&resolved, error))?,
            );
        }
        let read_rules = readable_roots
            .iter()
            .map(|path| {
                let path = sandbox_string_literal(&path.to_string_lossy());
                format!("(allow file-read* (literal \"{path}\") (subpath \"{path}\"))")
            })
            .chain(readable_files.iter().map(|path| {
                let path = sandbox_string_literal(&path.to_string_lossy());
                format!("(allow file-read* (literal \"{path}\"))")
            }))
            .collect::<Vec<_>>()
            .join(" ");
        let mut writable_roots = BTreeSet::new();
        if let Some(private_temp) = private_temp {
            writable_roots.insert(private_temp.to_path_buf());
        }
        let storage = &profile.manifest.storage;
        let state_prefix = storage
            .state_path
            .parent()
            .filter(|path| !path.as_os_str().is_empty())
            .unwrap_or(Path::new("."));
        let protected_roots = BTreeSet::from([
            state_root.clone(),
            project_root.join(&storage.graph_dir),
            project_root.join(&storage.tickets_dir),
            project_root.join(&storage.receipts_dir),
            project_root.join(&storage.reports_dir),
            project_root.join(&storage.work_dir),
            project_root.join(&storage.state_path),
            project_root.join(state_prefix.join("locks")),
            project_root.join(".git"),
            project_root.join(&profile.manifest.git.worktree_root),
        ]);
        for writable in &writable_roots {
            if protected_roots
                .iter()
                .any(|protected| writable.starts_with(protected) || protected.starts_with(writable))
            {
                return Err(KoniError::Profile(format!(
                    "sandbox cache root {} overlaps compiler authority",
                    writable.display()
                )));
            }
        }
        let write_rules = writable_roots
            .iter()
            .map(|path| {
                let path = sandbox_string_literal(&path.to_string_lossy());
                format!("(allow file-read* file-write* (literal \"{path}\") (subpath \"{path}\"))")
            })
            .collect::<Vec<_>>()
            .join(" ");
        let deny_rules = protected_roots
            .iter()
            .map(|path| {
                let path = sandbox_string_literal(&path.to_string_lossy());
                format!("(deny file-write* (literal \"{path}\") (subpath \"{path}\"))")
            })
            .collect::<Vec<_>>()
            .join(" ");
        let protected_read_rules =
            execution
                .repository_tool
                .as_ref()
                .map_or_else(String::new, |_| {
                    let mut protected_reads = protected_roots.clone();
                    for path in AGENT_CONTROL_PLANE_PREFIXES {
                        protected_reads.insert(project_root.join(path));
                    }
                    for root in [&project_root, &working_directory] {
                        for name in [
                            ".env",
                            ".env.local",
                            ".env.development",
                            ".env.test",
                            ".env.production",
                            ".npmrc",
                            ".yarnrc.yml",
                        ] {
                            protected_reads.insert(root.join(name));
                        }
                    }
                    protected_reads
                        .iter()
                        .map(|path| {
                            let path = sandbox_string_literal(&path.to_string_lossy());
                            format!("(deny file-read* (literal \"{path}\") (subpath \"{path}\"))")
                        })
                        .collect::<Vec<_>>()
                        .join(" ")
                });
        let mut metadata_roots = BTreeSet::new();
        for path in readable_roots
            .iter()
            .chain(&readable_files)
            .chain(&writable_roots)
        {
            let mut cursor = Some(path.as_path());
            while let Some(current) = cursor {
                metadata_roots.insert(current.to_path_buf());
                cursor = current.parent();
            }
        }
        let metadata_rules = metadata_roots
            .iter()
            .map(|path| {
                let path = sandbox_string_literal(&path.to_string_lossy());
                format!("(allow file-read-metadata (literal \"{path}\"))")
            })
            .collect::<Vec<_>>()
            .join(" ");
        let sandbox_profile = format!(
            "(version 1) (deny default) (allow process*) (allow signal) (allow sysctl-read) (allow file-read-data (literal \"/\")) {metadata_rules} {read_rules} {write_rules} (allow file-read* (literal \"/dev/null\") (literal \"/dev/urandom\")) (allow file-write* (literal \"/dev/null\")) {protected_read_rules} {deny_rules}"
        );
        let mut argv = vec![
            sandbox.resolved_path.clone(),
            "-p".to_owned(),
            sandbox_profile.clone(),
            "--".to_owned(),
        ];
        argv.extend(semantic_argv);
        Ok((
            argv,
            json!({
                "kind": "macos-seatbelt.v2",
                "rendered_profile_hash": raw_sha256(sandbox_profile.as_bytes()),
                "project_root": project_root,
                "state_root": state_root,
                "semantic_profile_hash": execution.sandbox_profile_hash,
                "private_temp": private_temp,
            }),
        ))
    }
    #[cfg(not(target_os = "macos"))]
    {
        let _ = (sandbox, project_root, state_root, profile, private_temp);
        Ok((semantic_argv, json!({"kind": "unsupported"})))
    }
}

fn executable_spawn_path(binding: &ExecutableBinding, project_root: &Path) -> Result<PathBuf> {
    match binding.path_kind.as_str() {
        "project_relative" => {
            let path = contained_process_path(project_root, &binding.resolved_path)?;
            path.canonicalize().map_err(|error| io_error(&path, error))
        }
        "external_absolute" => Ok(PathBuf::from(&binding.resolved_path)),
        other => Err(KoniError::Process(format!(
            "unknown executable path binding kind {other}"
        ))),
    }
}

#[cfg(target_os = "macos")]
fn sandbox_string_literal(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

/// Convenience used by isolated unit-level resolution. Engine runtime and
/// receipt currentness always call `resolve_check_execution_with_store` with
/// their authoritative backend store.
#[cfg(test)]
fn resolve_check_execution(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    graph: &Graph,
    project_root: &Path,
) -> Result<ResolvedCheckExecution> {
    let state_prefix = profile
        .manifest
        .storage
        .state_path
        .parent()
        .filter(|path| !path.as_os_str().is_empty())
        .unwrap_or(Path::new("."));
    let store =
        StateStore::with_storage(project_root.join(state_prefix), &profile.manifest.storage)?;
    resolve_check_execution_with_store(profile, check, ticket, graph, project_root, &store)
}

fn dynamic_result_allows_produced_output(check: &crate::config::CheckDef) -> bool {
    check.dynamic_result.as_ref().is_some_and(|dynamic| {
        dynamic
            .result_path
            .as_ref()
            .into_iter()
            .flat_map(|path| &path.path_authorities)
            .chain(
                dynamic
                    .artifacts
                    .as_ref()
                    .into_iter()
                    .flat_map(|artifacts| &artifacts.path_authorities),
            )
            .any(|authority| {
                authority.provenance == crate::config::DynamicPathProvenance::ProducedOutput
            })
    })
}

fn command_read_path_exclusions<'a>(
    profile: &CompiledProfile,
    produced_roots: impl IntoIterator<Item = &'a str>,
) -> Result<BTreeSet<CommandPathExclusion>> {
    let storage = &profile.manifest.storage;
    let mut exclusions = BTreeSet::new();
    for path in &profile.manifest.storage.filesystem_scope_excludes {
        let normalized = normalized_command_exclusion_path(path)?;
        let match_mode = if Path::new(&normalized).components().count() == 1 {
            CommandPathExclusionMode::Component
        } else {
            CommandPathExclusionMode::Prefix
        };
        exclusions.insert(CommandPathExclusion {
            path: normalized,
            match_mode,
        });
    }
    let mut prefixes = vec![
        PathBuf::from(".git"),
        profile.manifest.git.worktree_root.clone(),
    ];
    prefixes.extend(AGENT_CONTROL_PLANE_PREFIXES.map(PathBuf::from));
    prefixes.extend(compiler_owned_state_catalog(storage).paths().cloned());
    prefixes.extend(produced_roots.into_iter().map(PathBuf::from));
    for path in prefixes {
        exclusions.insert(CommandPathExclusion {
            path: normalized_command_exclusion_path(&path)?,
            match_mode: CommandPathExclusionMode::Prefix,
        });
    }
    Ok(exclusions)
}

fn read_only_workspace_fingerprint(
    root: &Path,
    profile: &CompiledProfile,
    authority_root: &Path,
) -> Result<WorkspaceFingerprint> {
    let canonical_root = root.canonicalize().map_err(|error| io_error(root, error))?;
    let mut fingerprint = if let Ok(repository) = git2::Repository::discover(&canonical_root)
        && let Some(workdir) = repository.workdir()
    {
        let canonical_workdir = workdir
            .canonicalize()
            .map_err(|error| io_error(workdir, error))?;
        if canonical_root.starts_with(&canonical_workdir) {
            git_workspace_fingerprint(&repository, &canonical_root, &canonical_workdir, profile)?
        } else {
            filesystem_workspace_fingerprint(&canonical_root, profile)?
        }
    } else {
        filesystem_workspace_fingerprint(&canonical_root, profile)?
    };
    let authority_root = authority_root
        .canonicalize()
        .map_err(|error| io_error(authority_root, error))?;
    if !authority_root.starts_with(&canonical_root) {
        fingerprint.authority_root = Some(authority_root.to_string_lossy().into_owned());
        fingerprint.authority_paths = authority_workspace_paths(&authority_root, profile)?;
    }
    fingerprint.hash.clear();
    fingerprint.hash = normalized_hash(&fingerprint);
    Ok(fingerprint)
}

fn git_workspace_fingerprint(
    repository: &git2::Repository,
    root: &Path,
    workdir: &Path,
    profile: &CompiledProfile,
) -> Result<WorkspaceFingerprint> {
    let project_prefix = root.strip_prefix(workdir).unwrap_or(Path::new(""));
    let head = repository.head().ok().map(|head| {
        format!(
            "{}:{}",
            head.name().unwrap_or("DETACHED"),
            head.target()
                .map(|oid| oid.to_string())
                .unwrap_or_else(|| "UNBORN".to_owned())
        )
    });
    let index = repository.index()?;
    let index_rows = index
        .iter()
        .map(|entry| {
            json!({
                "path": String::from_utf8_lossy(&entry.path),
                "oid": entry.id.to_string(),
                "mode": entry.mode,
                "flags": entry.flags,
                "flags_extended": entry.flags_extended,
            })
        })
        .collect::<Vec<_>>();
    let index_file_hash = repository
        .path()
        .join("index")
        .is_file()
        .then(|| fs::read(repository.path().join("index")))
        .transpose()
        .map_err(|error| io_error(repository.path().join("index"), error))?
        .map(|bytes| raw_sha256(&bytes));
    let index_hash = Some(normalized_hash(&json!({
        "file": index_file_hash,
        "entries": index_rows,
    })));
    let mut options = git2::StatusOptions::new();
    options
        .include_untracked(true)
        .recurse_untracked_dirs(true)
        .include_ignored(true)
        .recurse_ignored_dirs(true)
        .include_unmodified(false)
        .exclude_submodules(false);
    let statuses = repository.statuses(Some(&mut options))?;
    let mut paths = BTreeMap::new();
    for entry in statuses.iter() {
        let repository_relative = PathBuf::from(entry.path()?);
        let Ok(project_relative) = repository_relative.strip_prefix(project_prefix) else {
            continue;
        };
        if project_relative.as_os_str().is_empty()
            || workspace_guard_path_excluded(profile, project_relative)
        {
            continue;
        }
        let normalized = normalized_project_path(project_relative);
        let index_oid = index
            .get_path(&repository_relative, 0)
            .map(|entry| entry.id.to_string());
        paths.insert(
            normalized,
            workspace_path_fingerprint(
                &root.join(project_relative),
                Some(entry.status().bits()),
                index_oid,
            )?,
        );
    }
    for entry in WalkDir::new(root)
        .follow_links(false)
        .sort_by_file_name()
        .into_iter()
        .filter_entry(|entry| {
            if entry.path() == root {
                return true;
            }
            entry.path().strip_prefix(root).ok().is_some_and(|path| {
                path != Path::new(".git")
                    && !path.starts_with(".git")
                    && !workspace_guard_path_excluded(profile, path)
            })
        })
    {
        let entry = entry.map_err(|error| {
            KoniError::Process(format!("workspace directory inventory failed: {error}"))
        })?;
        if entry.path() == root || !entry.file_type().is_dir() {
            continue;
        }
        let relative = entry.path().strip_prefix(root).map_err(|_| {
            KoniError::Process("workspace directory inventory escaped project".to_owned())
        })?;
        paths
            .entry(normalized_project_path(relative))
            .or_insert(workspace_path_fingerprint(entry.path(), None, None)?);
    }
    finish_workspace_fingerprint("git", head, index_hash, paths)
}

fn filesystem_workspace_fingerprint(
    root: &Path,
    profile: &CompiledProfile,
) -> Result<WorkspaceFingerprint> {
    let mut paths = BTreeMap::new();
    for entry in WalkDir::new(root)
        .follow_links(false)
        .sort_by_file_name()
        .into_iter()
        .filter_entry(|entry| {
            if entry.path() == root {
                return true;
            }
            entry.path().strip_prefix(root).ok().is_some_and(|path| {
                path != Path::new(".git")
                    && !path.starts_with(".git")
                    && !workspace_guard_path_excluded(profile, path)
            })
        })
    {
        let entry = entry
            .map_err(|error| KoniError::Process(format!("workspace inventory failed: {error}")))?;
        if entry.path() == root {
            continue;
        }
        let relative = entry.path().strip_prefix(root).map_err(|_| {
            KoniError::Process("workspace inventory escaped project root".to_owned())
        })?;
        paths.insert(
            normalized_project_path(relative),
            workspace_path_fingerprint(entry.path(), None, None)?,
        );
    }
    finish_workspace_fingerprint("filesystem", None, None, paths)
}

fn workspace_guard_path_excluded(profile: &CompiledProfile, path: &Path) -> bool {
    let storage = &profile.manifest.storage;
    if path.starts_with(&storage.graph_dir) || path.starts_with(&storage.tickets_dir) {
        return false;
    }
    if storage.filesystem_scope_excludes.iter().any(|excluded| {
        if excluded.components().count() == 1 {
            path.components()
                .any(|component| component.as_os_str() == excluded)
        } else {
            path.starts_with(excluded)
        }
    }) {
        return true;
    }
    if path.starts_with(&storage.work_dir) {
        return path.file_name().is_some_and(volatile_agent_work_file_name);
    }
    false
}

fn volatile_agent_work_file_name(name: &std::ffi::OsStr) -> bool {
    name.to_str().is_some_and(|name| {
        matches!(
            name,
            "worker.pid" | "worker.jsonl" | "stdout.log" | "stderr.log"
        ) || (name.starts_with("worker.") && name.ends_with(".log"))
    })
}

fn workspace_path_fingerprint(
    path: &Path,
    status: Option<u32>,
    index_oid: Option<String>,
) -> Result<WorkspacePathFingerprint> {
    let Ok(metadata) = fs::symlink_metadata(path) else {
        return Ok(WorkspacePathFingerprint {
            status,
            kind: "missing".to_owned(),
            mode: None,
            size_bytes: None,
            sha256: None,
            index_oid,
            link_target: None,
        });
    };
    if metadata.file_type().is_symlink() {
        let target = fs::read_link(path).map_err(|error| io_error(path, error))?;
        let target = target.to_string_lossy().into_owned();
        return Ok(WorkspacePathFingerprint {
            status,
            kind: "symlink".to_owned(),
            #[cfg(unix)]
            mode: Some(metadata.mode()),
            #[cfg(not(unix))]
            mode: None,
            size_bytes: Some(metadata.len()),
            sha256: Some(raw_sha256(target.as_bytes())),
            index_oid,
            link_target: Some(target),
        });
    }
    if metadata.is_file() {
        let bytes = fs::read(path).map_err(|error| io_error(path, error))?;
        return Ok(WorkspacePathFingerprint {
            status,
            kind: "file".to_owned(),
            #[cfg(unix)]
            mode: Some(metadata.mode()),
            #[cfg(not(unix))]
            mode: None,
            size_bytes: Some(bytes.len() as u64),
            sha256: Some(raw_sha256(&bytes)),
            index_oid,
            link_target: None,
        });
    }
    Ok(WorkspacePathFingerprint {
        status,
        kind: if metadata.is_dir() {
            "directory"
        } else {
            "other"
        }
        .to_owned(),
        #[cfg(unix)]
        mode: Some(metadata.mode()),
        #[cfg(not(unix))]
        mode: None,
        size_bytes: (!metadata.is_dir()).then_some(metadata.len()),
        sha256: None,
        index_oid,
        link_target: None,
    })
}

fn finish_workspace_fingerprint(
    backend: &str,
    head: Option<String>,
    index_hash: Option<String>,
    paths: BTreeMap<String, WorkspacePathFingerprint>,
) -> Result<WorkspaceFingerprint> {
    let mut fingerprint = WorkspaceFingerprint {
        schema_version: "1.0".to_owned(),
        backend: backend.to_owned(),
        head,
        index_hash,
        paths,
        authority_root: None,
        authority_paths: BTreeMap::new(),
        hash: String::new(),
    };
    fingerprint.hash = normalized_hash(&fingerprint);
    Ok(fingerprint)
}

fn workspace_fingerprint_changed_paths(
    pre: &WorkspaceFingerprint,
    post: &WorkspaceFingerprint,
) -> Vec<String> {
    let mut changed = pre
        .paths
        .keys()
        .chain(post.paths.keys())
        .filter(|path| pre.paths.get(*path) != post.paths.get(*path))
        .cloned()
        .collect::<BTreeSet<_>>();
    changed.extend(
        pre.authority_paths
            .keys()
            .chain(post.authority_paths.keys())
            .filter(|path| pre.authority_paths.get(*path) != post.authority_paths.get(*path))
            .map(|path| format!("<state>/{path}")),
    );
    if pre.head != post.head {
        changed.insert(".git/HEAD".to_owned());
    }
    if pre.index_hash != post.index_hash {
        changed.insert(".git/index".to_owned());
    }
    changed.into_iter().collect()
}

fn workspace_fingerprint_changes(
    pre: &WorkspaceFingerprint,
    post: &WorkspaceFingerprint,
) -> Vec<Value> {
    workspace_fingerprint_changed_paths(pre, post)
        .into_iter()
        .map(|path| {
            let pre_value = workspace_fingerprint_entry(pre, &path);
            let post_value = workspace_fingerprint_entry(post, &path);
            json!({
                "path": path,
                "pre": pre_value,
                "post": post_value,
            })
        })
        .collect()
}

fn workspace_fingerprint_entry(fingerprint: &WorkspaceFingerprint, path: &str) -> Value {
    match path {
        ".git/HEAD" => fingerprint.head.clone().map_or(Value::Null, Value::String),
        ".git/index" => fingerprint
            .index_hash
            .clone()
            .map_or(Value::Null, Value::String),
        _ if path.starts_with("<state>/") => fingerprint
            .authority_paths
            .get(path.trim_start_matches("<state>/"))
            .map(|value| serde_json::to_value(value).expect("workspace entry serializes"))
            .unwrap_or(Value::Null),
        _ => fingerprint
            .paths
            .get(path)
            .map(|value| serde_json::to_value(value).expect("workspace entry serializes"))
            .unwrap_or(Value::Null),
    }
}

fn direct_workspace_fingerprint_entry(
    workspace_root: &Path,
    state_root: &Path,
    path: &str,
) -> Result<Value> {
    if path == ".git/HEAD" {
        let repository = git2::Repository::discover(workspace_root)?;
        return Ok(repository.head().ok().map_or(Value::Null, |head| {
            Value::String(format!(
                "{}:{}",
                head.name().unwrap_or("DETACHED"),
                head.target()
                    .map(|oid| oid.to_string())
                    .unwrap_or_else(|| "UNBORN".to_owned())
            ))
        }));
    }
    if path == ".git/index" {
        let repository = git2::Repository::discover(workspace_root)?;
        let index = repository.index()?;
        let rows = index
            .iter()
            .map(|entry| {
                json!({
                    "path": String::from_utf8_lossy(&entry.path),
                    "oid": entry.id.to_string(),
                    "mode": entry.mode,
                    "flags": entry.flags,
                    "flags_extended": entry.flags_extended,
                })
            })
            .collect::<Vec<_>>();
        let index_file = repository.path().join("index");
        let file_hash = index_file
            .is_file()
            .then(|| fs::read(&index_file))
            .transpose()
            .map_err(|error| io_error(&index_file, error))?
            .map(|bytes| raw_sha256(&bytes));
        return Ok(Value::String(normalized_hash(&json!({
            "file": file_hash,
            "entries": rows,
        }))));
    }
    if let Some(relative) = path.strip_prefix("<state>/") {
        let absolute = state_root.join(relative);
        if !absolute.exists() {
            return Ok(Value::Null);
        }
        let entry = workspace_path_fingerprint(&absolute, None, None)?;
        return Ok(serde_json::to_value(entry).expect("workspace entry serializes"));
    }
    let relative = Path::new(path);
    validate_project_relative_scope_path(relative)?;
    let repository = git2::Repository::discover(workspace_root).ok();
    let (status, index_oid) = if let Some(repository) = repository.as_ref()
        && let Some(workdir) = repository.workdir()
        && let Ok(prefix) = workspace_root.strip_prefix(workdir)
    {
        let repository_relative = prefix.join(relative);
        (
            repository
                .status_file(&repository_relative)
                .ok()
                .map(|status| status.bits()),
            repository
                .index()
                .ok()
                .and_then(|index| index.get_path(&repository_relative, 0))
                .map(|entry| entry.id.to_string()),
        )
    } else {
        (None, None)
    };
    let absolute = workspace_root.join(relative);
    if !absolute.is_dir()
        && status.is_none_or(|status| status == 0)
        && ((absolute.exists() && index_oid.is_some())
            || (!absolute.exists() && index_oid.is_none()))
    {
        return Ok(Value::Null);
    }
    let entry = workspace_path_fingerprint(&absolute, status, index_oid)?;
    Ok(serde_json::to_value(entry).expect("workspace entry serializes"))
}

#[derive(Debug, Clone)]
struct ValidatedCommandJournalAuthority {
    workspace_root: PathBuf,
    state_root: PathBuf,
    receipts_root: PathBuf,
}

struct CommandJournalValidationContext {
    manifest: RunManifest,
    current_git: GitBackend,
    managed_workspaces: BTreeSet<PathBuf>,
}

fn command_journal_validation_context(
    project_root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<CommandJournalValidationContext> {
    let manifest = store.manifest()?;
    let current_git = GitBackend::discover(project_root)?;
    let managed_workspaces =
        managed_run_workspace_roots(project_root, profile, store, &manifest.id)?;
    Ok(CommandJournalValidationContext {
        manifest,
        current_git,
        managed_workspaces,
    })
}

fn command_journal_provenance_error(journal: &Value, message: impl Into<String>) -> KoniError {
    KoniError::Process(format!(
        "read-only command journal {} failed authority provenance: {}",
        journal
            .get("sequence")
            .and_then(Value::as_u64)
            .map(|sequence| sequence.to_string())
            .unwrap_or_else(|| "<unknown>".to_owned()),
        message.into()
    ))
}

fn journal_absolute_path_field(journal: &Value, field: &str) -> Result<PathBuf> {
    let path = journal
        .get(field)
        .and_then(Value::as_str)
        .filter(|path| !path.is_empty())
        .map(PathBuf::from)
        .ok_or_else(|| command_journal_provenance_error(journal, format!("missing {field}")))?;
    if !path.is_absolute()
        || path.components().any(|component| {
            matches!(
                component,
                std::path::Component::CurDir | std::path::Component::ParentDir
            )
        })
    {
        return Err(command_journal_provenance_error(
            journal,
            format!("{field} is not a lexical canonical absolute path"),
        ));
    }
    Ok(path)
}

fn extend_managed_ticket_workspaces(
    candidates: &mut BTreeSet<PathBuf>,
    store: &StateStore,
    run_id: &str,
    profile_hash: &str,
) -> Result<()> {
    if !store.manifest_path().exists() {
        return Ok(());
    }
    let manifest = store.manifest()?;
    if manifest.id != run_id || manifest.profile_hash != profile_hash {
        return Err(KoniError::Process(
            "compiler-owned ticket store does not match the current run identity".to_owned(),
        ));
    }
    candidates.extend(
        store
            .tickets()?
            .into_iter()
            .filter_map(|ticket| ticket.lease.map(|lease| lease.worktree)),
    );
    Ok(())
}

fn managed_run_workspace_roots(
    project_root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
    run_id: &str,
) -> Result<BTreeSet<PathBuf>> {
    let current_git = GitBackend::discover(project_root)?;
    let mut candidates = BTreeSet::from([current_git.workdir().to_path_buf()]);
    extend_managed_ticket_workspaces(&mut candidates, store, run_id, &profile.hash)?;

    let registry_path = current_git.sidecar_root().join("project.yaml");
    if registry_path.exists() {
        let registered_project_root = registry_project_root(project_root)?;
        let registry =
            ProjectRegistryStore::new(current_git.sidecar_root(), registered_project_root.clone())?;
        let registration = registry.run(run_id)?;
        if registration.profile_hash != profile.hash {
            return Err(KoniError::Process(format!(
                "registered run {run_id} does not match the active profile"
            )));
        }
        candidates.insert(registered_project_root);
        candidates.extend(registration.planning_worktree.iter().cloned());
        candidates.extend(registration.integration_worktree.iter().cloned());
        let canonical_store = match profile.manifest.storage.backend {
            StorageBackend::Tracked => registration
                .integration_worktree
                .as_ref()
                .map(|worktree| {
                    StateStore::with_storage(
                        tracked_state_root(worktree, profile),
                        &profile.manifest.storage,
                    )
                })
                .transpose()?,
            StorageBackend::GitCommonDir => {
                Some(registry.run_store(run_id, &profile.manifest.storage)?)
            }
        };
        if let Some(canonical_store) = canonical_store {
            extend_managed_ticket_workspaces(
                &mut candidates,
                &canonical_store,
                run_id,
                &profile.hash,
            )?;
        }
    }

    let mut managed = BTreeSet::new();
    for candidate in candidates {
        if !candidate.exists() {
            continue;
        }
        let canonical = candidate
            .canonicalize()
            .map_err(|error| io_error(&candidate, error))?;
        let candidate_git = GitBackend::discover(&canonical)?;
        if candidate_git.workdir() != canonical
            || candidate_git.common_dir() != current_git.common_dir()
        {
            continue;
        }
        managed.insert(canonical);
    }
    Ok(managed)
}

fn canonical_trusted_journal_root(journal: &Value, path: &Path, label: &str) -> Result<PathBuf> {
    let canonical = path
        .canonicalize()
        .map_err(|_| command_journal_provenance_error(journal, format!("{label} is missing")))?;
    if canonical != path {
        return Err(command_journal_provenance_error(
            journal,
            format!("{label} is noncanonical or contains a symlink"),
        ));
    }
    Ok(canonical)
}

fn validate_command_attempt_journal_authority_with_context(
    journal: &Value,
    profile: &CompiledProfile,
    store: &StateStore,
    context: &CommandJournalValidationContext,
) -> Result<ValidatedCommandJournalAuthority> {
    if !command_attempt_journal_integrity_current(journal) {
        return Err(command_journal_provenance_error(
            journal,
            "journal integrity is invalid",
        ));
    }
    let manifest = &context.manifest;
    if !command_attempt_journal_is_configured_read_only(profile, &manifest.id, journal) {
        return Err(command_journal_provenance_error(
            journal,
            "kind, producer, run, profile, or read-only check identity is invalid",
        ));
    }

    // These are parsed syntactically only. No journal-supplied path is touched
    // until the workspace is equal to a compiler-derived managed worktree.
    let workspace_root = journal_absolute_path_field(journal, "workspace_root")?;
    let state_root = journal_absolute_path_field(journal, "state_root")?;
    let receipts_root = journal_absolute_path_field(journal, "receipts_root")?;
    let workspace_root = context
        .managed_workspaces
        .get(&workspace_root)
        .cloned()
        .ok_or_else(|| {
            command_journal_provenance_error(
                journal,
                "workspace_root is not a managed worktree for this run",
            )
        })?;
    let workspace_git = GitBackend::discover(&workspace_root)?;
    if workspace_git.common_dir() != context.current_git.common_dir() {
        return Err(command_journal_provenance_error(
            journal,
            "workspace_root belongs to another Git common repository",
        ));
    }

    let candidate_store = match profile.manifest.storage.backend {
        StorageBackend::Tracked => {
            let derived_state_root = tracked_state_root(&workspace_root, profile);
            let canonical_state_root =
                canonical_trusted_journal_root(journal, &derived_state_root, "state_root")?;
            if state_root != canonical_state_root
                || !canonical_state_root.starts_with(&workspace_root)
            {
                return Err(command_journal_provenance_error(
                    journal,
                    "state_root is not the exact tracked state root for workspace_root",
                ));
            }
            StateStore::with_storage(canonical_state_root, &profile.manifest.storage)?
        }
        StorageBackend::GitCommonDir => {
            let expected_run_root = context
                .current_git
                .sidecar_path(format!("runs/{}", manifest.id))?;
            let expected_store =
                StateStore::with_storage(expected_run_root, &profile.manifest.storage)?;
            let canonical_state_root = canonical_trusted_journal_root(
                journal,
                expected_store.root(),
                "registered run state_root",
            )?;
            let current_state_root =
                canonical_trusted_journal_root(journal, store.root(), "current run state_root")?;
            if state_root != canonical_state_root || current_state_root != canonical_state_root {
                return Err(command_journal_provenance_error(
                    journal,
                    "state_root is not the exact registered Git-common run store",
                ));
            }
            expected_store
        }
    };
    let candidate_manifest = candidate_store.manifest()?;
    if candidate_manifest.id != manifest.id
        || candidate_manifest.profile_hash != profile.hash
        || candidate_manifest.repository_root != manifest.repository_root
    {
        return Err(command_journal_provenance_error(
            journal,
            "state_root manifest does not match the current run identity",
        ));
    }
    let canonical_receipts_root =
        canonical_trusted_journal_root(journal, candidate_store.receipts_dir(), "receipts_root")?;
    if receipts_root != canonical_receipts_root
        || !canonical_receipts_root.starts_with(candidate_store.root())
    {
        return Err(command_journal_provenance_error(
            journal,
            "receipts_root is not the exact configured receipts directory",
        ));
    }
    Ok(ValidatedCommandJournalAuthority {
        workspace_root,
        state_root,
        receipts_root,
    })
}

fn validate_command_attempt_journal_authority(
    journal: &Value,
    project_root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<ValidatedCommandJournalAuthority> {
    let context = command_journal_validation_context(project_root, profile, store)?;
    validate_command_attempt_journal_authority_with_context(journal, profile, store, &context)
}

struct CommandAuthorityProjection {
    rows: Vec<Value>,
    journals: Vec<Value>,
    retired: Vec<(Value, Value, Option<Value>)>,
    matched_hashes: BTreeSet<String>,
}

fn ensure_read_only_invalid_contract_rows_authorized(
    profile: &CompiledProfile,
    rows: &[Value],
    matched_hashes: &BTreeSet<String>,
) -> Result<()> {
    for receipt in rows {
        if !receipt_claims_configured_read_only_invalid_contract(profile, receipt)
            || matched_hashes.contains(&normalized_hash(receipt))
            || (command_receipt_integrity_current(receipt)
                && receipt_is_configured_read_only_command(profile, receipt)
                && read_only_workspace_guard_evidence(receipt)
                    == ReadOnlyWorkspaceGuardEvidence::ValidUnchanged)
        {
            continue;
        }
        return Err(KoniError::Process(format!(
            "read-only invalid-contract receipt {} has no exact validated command journal authority",
            receipt
                .get("id")
                .and_then(Value::as_str)
                .unwrap_or("<unknown>")
        )));
    }
    Ok(())
}

fn command_authority_projection(
    profile: &CompiledProfile,
    store: &StateStore,
    project_root: &Path,
) -> Result<CommandAuthorityProjection> {
    let authority = command_authority_store(store, project_root)?;
    let local_rows = load_all_receipt_rows(store.receipts_dir())?;
    let journals = load_all_receipt_rows(&authority.work_dir().join("command-journals"))?;
    // Managed workspaces and run identity are compiler-derived, but expensive
    // to reconstruct because they include every ticket lease. Build that
    // authority once per projection, then validate every journal against the
    // same immutable read context.
    let validation_context = command_journal_validation_context(project_root, profile, store)?;
    let validated = journals
        .iter()
        .map(|journal| {
            validate_command_attempt_journal_authority_with_context(
                journal,
                profile,
                store,
                &validation_context,
            )
            .map(|authority| (journal, authority))
        })
        .collect::<Result<Vec<_>>>()?;
    let retired = retired_command_attempt_records(&authority, project_root, profile, store)?;
    let mut sequence_authority = BTreeMap::<u64, &str>::new();
    for journal in &journals {
        let sequence = journal
            .get("sequence")
            .and_then(Value::as_u64)
            .ok_or_else(|| KoniError::Process("live command journal has no sequence".to_owned()))?;
        let hash = journal
            .get("journal_hash")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                KoniError::Process("live command journal has no integrity hash".to_owned())
            })?;
        if sequence_authority.insert(sequence, hash).is_some() {
            return Err(KoniError::Process(format!(
                "compiler authority contains duplicate live command sequence {sequence}"
            )));
        }
    }
    for (_, journal, _) in &retired {
        let sequence = journal
            .get("sequence")
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                KoniError::Process("retired command journal has no sequence".to_owned())
            })?;
        let hash = journal
            .get("journal_hash")
            .and_then(Value::as_str)
            .ok_or_else(|| {
                KoniError::Process("retired command journal has no integrity hash".to_owned())
            })?;
        if let Some(existing) = sequence_authority.insert(sequence, hash)
            && existing != hash
        {
            return Err(KoniError::Process(format!(
                "live and retired command authority conflict at sequence {sequence}"
            )));
        }
    }
    let mut rows_by_root = BTreeMap::<PathBuf, Vec<Value>>::new();
    if store.receipts_dir().exists() {
        rows_by_root.insert(
            store
                .receipts_dir()
                .canonicalize()
                .map_err(|error| io_error(store.receipts_dir(), error))?,
            local_rows.clone(),
        );
    }
    for (_, validated) in &validated {
        if !rows_by_root.contains_key(&validated.receipts_root) {
            rows_by_root.insert(
                validated.receipts_root.clone(),
                load_all_receipt_rows(&validated.receipts_root)?,
            );
        }
    }
    let mut matched = Vec::new();
    let mut matched_hashes = BTreeSet::new();
    for (journal, validated) in &validated {
        for receipt in &rows_by_root[&validated.receipts_root] {
            if command_attempt_journal_matches_receipt(journal, receipt, profile) {
                let hash = normalized_hash(receipt);
                if matched_hashes.insert(hash) {
                    matched.push(receipt.clone());
                }
            }
        }
    }
    for (_, _, receipt) in &retired {
        if let Some(receipt) = receipt {
            let hash = normalized_hash(receipt);
            if matched_hashes.insert(hash) {
                matched.push(receipt.clone());
            }
        }
    }

    // Local semantic rows remain available for compatibility and non-command
    // checks. A read-only invalid-contract may influence global authority only
    // when its exact receipt is bound to one validated command journal. The one
    // exception is a valid unchanged guard, which is a local execution failure
    // and carries no workspace authority to dereference.
    let mut rows = local_rows;
    for receipt_rows in rows_by_root.values() {
        ensure_read_only_invalid_contract_rows_authorized(profile, receipt_rows, &matched_hashes)?;
    }
    rows.extend(matched);
    rows.extend(load_all_receipt_rows(
        &authority.work_dir().join("remediations"),
    )?);
    let rows = rows
        .into_iter()
        .map(|row| (normalized_hash(&row), row))
        .collect::<BTreeMap<_, _>>()
        .into_values()
        .collect();
    drop(sequence_authority);
    drop(validated);
    Ok(CommandAuthorityProjection {
        rows,
        journals,
        retired,
        matched_hashes,
    })
}

fn command_authority_receipt_rows(
    profile: &CompiledProfile,
    store: &StateStore,
    project_root: &Path,
) -> Result<Vec<Value>> {
    Ok(command_authority_projection(profile, store, project_root)?.rows)
}

fn receipt_is_configured_read_only_command(profile: &CompiledProfile, receipt: &Value) -> bool {
    configured_command_check_for_receipt(profile, receipt).is_some_and(|check| {
        check.effect == crate::config::ProcessEffect::ReadOnly
            && receipt
                .get("process_effect")
                .and_then(Value::as_str)
                .is_none_or(|effect| effect == "read_only")
    })
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReadOnlyWorkspaceGuardEvidence {
    ValidUnchanged,
    ValidViolation,
    Invalid,
}

fn read_only_workspace_guard_evidence(receipt: &Value) -> ReadOnlyWorkspaceGuardEvidence {
    let Some(guard) = receipt.get("workspace_guard").and_then(Value::as_object) else {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    };
    let Some(pre_hash) = guard.get("pre_hash").and_then(Value::as_str) else {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    };
    let Some(post_hash) = guard.get("post_hash").and_then(Value::as_str) else {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    };
    let Some(changed_paths) = guard.get("changed_paths").and_then(Value::as_array) else {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    };
    let Some(changes) = guard.get("changes").and_then(Value::as_array) else {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    };
    if pre_hash.is_empty() || post_hash.is_empty() {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    }
    if guard.get("unchanged").and_then(Value::as_bool) == Some(true)
        && pre_hash == post_hash
        && changed_paths.is_empty()
        && changes.is_empty()
    {
        return ReadOnlyWorkspaceGuardEvidence::ValidUnchanged;
    }
    if guard.get("unchanged").and_then(Value::as_bool) != Some(false)
        || pre_hash == post_hash
        || changed_paths.is_empty()
        || changes.is_empty()
    {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    }
    let changed_paths = changed_paths
        .iter()
        .filter_map(Value::as_str)
        .collect::<BTreeSet<_>>();
    if changed_paths.len() != changes.len() {
        return ReadOnlyWorkspaceGuardEvidence::Invalid;
    }
    let change_paths = changes
        .iter()
        .filter_map(|change| {
            let object = change.as_object()?;
            if object.len() != 3
                || !object
                    .keys()
                    .all(|key| matches!(key.as_str(), "path" | "pre" | "post"))
            {
                return None;
            }
            let path = object.get("path")?.as_str()?;
            let pre = object.get("pre")?;
            let post = object.get("post")?;
            (!path.is_empty() && pre != post).then_some(path)
        })
        .collect::<BTreeSet<_>>();
    if change_paths.len() == changes.len() && change_paths == changed_paths {
        ReadOnlyWorkspaceGuardEvidence::ValidViolation
    } else {
        ReadOnlyWorkspaceGuardEvidence::Invalid
    }
}

fn receipt_claims_configured_read_only_invalid_contract(
    profile: &CompiledProfile,
    receipt: &Value,
) -> bool {
    receipt.get("status").and_then(Value::as_str) == Some("invalid_contract")
        && configured_command_check_for_receipt(profile, receipt)
            .is_some_and(|check| check.effect == crate::config::ProcessEffect::ReadOnly)
}

fn receipt_is_read_only_workspace_violation(profile: &CompiledProfile, receipt: &Value) -> bool {
    receipt_claims_configured_read_only_invalid_contract(profile, receipt)
        && receipt_is_configured_read_only_command(profile, receipt)
        && read_only_workspace_guard_evidence(receipt)
            == ReadOnlyWorkspaceGuardEvidence::ValidViolation
        && !receipt_workspace_changes_are_volatile_agent_files(profile, receipt)
}

fn receipt_workspace_changes_are_volatile_agent_files(
    profile: &CompiledProfile,
    receipt: &Value,
) -> bool {
    receipt
        .get("workspace_guard")
        .and_then(|guard| guard.get("changed_paths"))
        .and_then(Value::as_array)
        .filter(|paths| !paths.is_empty())
        .is_some_and(|paths| {
            paths.iter().all(|path| {
                path.as_str()
                    .is_some_and(|path| volatile_authority_agent_path(profile, path))
            })
        })
}

fn volatile_authority_agent_path(profile: &CompiledProfile, path: &str) -> bool {
    let Some(path) = path.strip_prefix("<state>/") else {
        return false;
    };
    let state_prefix = profile
        .manifest
        .storage
        .state_path
        .parent()
        .filter(|path| !path.as_os_str().is_empty())
        .unwrap_or(Path::new("."));
    let Ok(work_dir) = profile.manifest.storage.work_dir.strip_prefix(state_prefix) else {
        return false;
    };
    let path = Path::new(path);
    path.starts_with(work_dir) && path.file_name().is_some_and(volatile_agent_work_file_name)
}

fn corrupt_or_malformed_read_only_invalid_contract(
    profile: &CompiledProfile,
    receipt: &Value,
) -> bool {
    receipt_claims_configured_read_only_invalid_contract(profile, receipt)
        && (!command_receipt_integrity_current(receipt)
            || !receipt_is_configured_read_only_command(profile, receipt)
            || read_only_workspace_guard_evidence(receipt)
                == ReadOnlyWorkspaceGuardEvidence::Invalid)
}

fn command_attempt_journal_is_configured_read_only(
    profile: &CompiledProfile,
    run_id: &str,
    journal: &Value,
) -> bool {
    journal.get("schema_version").and_then(Value::as_str) == Some("1.0")
        && journal.get("kind").and_then(Value::as_str) == Some("compiler.read-only-command-attempt")
        && journal.get("producer").and_then(Value::as_str) == Some("compiler.read-only-quarantine")
        && journal.get("run_id").and_then(Value::as_str) == Some(run_id)
        && journal.get("profile_hash").and_then(Value::as_str) == Some(profile.hash.as_str())
        && journal
            .get("check_id")
            .and_then(Value::as_str)
            .and_then(|check_id| profile.checks.get(check_id))
            .is_some_and(|check| {
                check.kind == CheckKind::Command
                    && check.effect == crate::config::ProcessEffect::ReadOnly
            })
}

fn read_only_violation_watermark_from_projection(
    profile: &CompiledProfile,
    run_id: &str,
    projection: &CommandAuthorityProjection,
) -> Result<Option<u64>> {
    let mut found = false;
    let mut watermark = 0;
    let receipts = &projection.rows;
    for receipt in receipts {
        if corrupt_or_malformed_read_only_invalid_contract(profile, receipt) {
            return Err(KoniError::Process(format!(
                "compiler authority contains corrupt or malformed read-only invalid-contract receipt {}",
                receipt
                    .get("id")
                    .and_then(Value::as_str)
                    .unwrap_or("<unknown>")
            )));
        }
        if !receipt_is_read_only_workspace_violation(profile, receipt)
            || !command_receipt_integrity_current(receipt)
        {
            continue;
        }
        found = true;
        watermark = watermark.max(
            receipt
                .get("command_attempt_sequence")
                .and_then(Value::as_u64)
                .unwrap_or(0),
        );
    }
    for journal in &projection.journals {
        if !command_attempt_journal_integrity_current(journal) {
            return Err(KoniError::Process(
                "compiler authority contains a corrupt read-only command journal".to_owned(),
            ));
        }
        if journal.get("kind").and_then(Value::as_str) != Some("compiler.read-only-command-attempt")
        {
            continue;
        }
        if !command_attempt_journal_is_configured_read_only(profile, run_id, journal) {
            return Err(KoniError::Process(
                "compiler authority contains an unbound read-only command journal".to_owned(),
            ));
        }
        if receipts
            .iter()
            .any(|receipt| command_attempt_journal_matches_receipt(journal, receipt, profile))
        {
            continue;
        }
        let sequence = journal
            .get("sequence")
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                KoniError::Process(
                    "compiler authority contains a read-only journal without a sequence".to_owned(),
                )
            })?;
        found = true;
        watermark = watermark.max(sequence);
    }
    for (_, journal, receipt) in &projection.retired {
        if receipt.is_some() {
            continue;
        }
        let sequence = journal
            .get("sequence")
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                KoniError::Process(
                    "retired receipt-free command attempt has no sequence".to_owned(),
                )
            })?;
        found = true;
        watermark = watermark.max(sequence);
    }
    Ok(found.then_some(watermark))
}

fn read_only_violation_watermark(
    profile: &CompiledProfile,
    store: &StateStore,
    project_root: &Path,
) -> Result<Option<u64>> {
    let run_id = store.manifest()?.id;
    let projection = command_authority_projection(profile, store, project_root)?;
    read_only_violation_watermark_from_projection(profile, &run_id, &projection)
}

fn read_only_remediation_receipt_is_valid(receipt: &Value) -> bool {
    const FIELDS: &[&str] = &[
        "schema_version",
        "id",
        "receipt_type",
        "producer",
        "status",
        "violation_id",
        "violation_receipt_hash",
        "workspace_root",
        "state_root",
        "workspace_hash_at_remediation",
        "violation_profile_hash",
        "recorded_at",
        "profile_hash",
        "receipt_hash",
    ];
    let Some(object) = receipt.as_object() else {
        return false;
    };
    object.len() == FIELDS.len()
        && object.keys().all(|key| FIELDS.contains(&key.as_str()))
        && receipt.get("schema_version").and_then(Value::as_str) == Some("1.0")
        && receipt_kind(receipt) == Some("compiler.read-only-remediation")
        && receipt.get("producer").and_then(Value::as_str) == Some("compiler.read-only-quarantine")
        && receipt.get("status").and_then(Value::as_str) == Some("passed")
        && [
            "id",
            "violation_id",
            "violation_receipt_hash",
            "workspace_root",
            "state_root",
            "workspace_hash_at_remediation",
            "violation_profile_hash",
            "recorded_at",
            "profile_hash",
            "receipt_hash",
        ]
        .iter()
        .all(|field| {
            receipt
                .get(*field)
                .and_then(Value::as_str)
                .is_some_and(|value| !value.trim().is_empty())
        })
        && durable_receipt_integrity_current(receipt)
}

fn command_attempt_journal_matches_receipt(
    journal: &Value,
    receipt: &Value,
    profile: &CompiledProfile,
) -> bool {
    let completion_linkage_current = journal.get("status").and_then(Value::as_str)
        != Some("completed")
        || (journal
            .get("receipt_id")
            .and_then(Value::as_str)
            .is_some_and(|id| receipt.get("id").and_then(Value::as_str) == Some(id))
            && journal
                .get("receipt_hash")
                .and_then(Value::as_str)
                .is_some_and(|hash| {
                    receipt.get("receipt_hash").and_then(Value::as_str) == Some(hash)
                }));
    let workspace_pre_current = journal
        .get("workspace_pre")
        .and_then(|pre| pre.get("hash"))
        .and_then(Value::as_str)
        .is_some_and(|hash| {
            receipt
                .get("workspace_guard")
                .and_then(|guard| guard.get("pre_hash"))
                .and_then(Value::as_str)
                == Some(hash)
        });
    let workspace_post_current = journal
        .get("workspace_post")
        .filter(|post| !post.is_null())
        .is_none_or(|post| {
            post.get("hash")
                .and_then(Value::as_str)
                .is_some_and(|hash| {
                    receipt
                        .get("workspace_guard")
                        .and_then(|guard| guard.get("post_hash"))
                        .and_then(Value::as_str)
                        == Some(hash)
                })
        });
    let guard_evidence = read_only_workspace_guard_evidence(receipt);
    let guard_contract_current = guard_evidence != ReadOnlyWorkspaceGuardEvidence::Invalid
        && (guard_evidence != ReadOnlyWorkspaceGuardEvidence::ValidViolation
            || receipt.get("status").and_then(Value::as_str) == Some("invalid_contract"))
        && (receipt.get("status").and_then(Value::as_str) == Some("invalid_contract")
            || guard_evidence == ReadOnlyWorkspaceGuardEvidence::ValidUnchanged);
    completion_linkage_current
        && workspace_pre_current
        && workspace_post_current
        && guard_contract_current
        && receipt
            .get("command_attempt_sequence")
            .and_then(Value::as_u64)
            == journal.get("sequence").and_then(Value::as_u64)
        && command_receipt_integrity_current(receipt)
        && receipt.get("run_id").and_then(Value::as_str)
            == journal.get("run_id").and_then(Value::as_str)
        && receipt.get("check_id").and_then(Value::as_str)
            == journal.get("check_id").and_then(Value::as_str)
        && receipt.get("profile_hash").and_then(Value::as_str)
            == journal.get("profile_hash").and_then(Value::as_str)
        && receipt
            .get("execution_binding_hash")
            .and_then(Value::as_str)
            == journal
                .get("execution_binding_hash")
                .and_then(Value::as_str)
        && receipt.get("workspace_root").and_then(Value::as_str)
            == journal.get("workspace_root").and_then(Value::as_str)
        && receipt.get("state_root").and_then(Value::as_str)
            == journal.get("state_root").and_then(Value::as_str)
        && receipt.get("receipts_root").and_then(Value::as_str)
            == journal.get("receipts_root").and_then(Value::as_str)
        && receipt.get("process_effect").and_then(Value::as_str) == Some("read_only")
        && receipt.get("execution_binding") == journal.get("execution_binding")
        && receipt.get("spawn_binding") == journal.get("spawn_binding")
        && configured_command_check_for_receipt(profile, receipt).is_some_and(|check| {
            Some(check.id.as_str()) == journal.get("check_id").and_then(Value::as_str)
        })
}

fn recover_or_block_command_attempt_journals(
    root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<()> {
    let authority = command_authority_store(store, root)?;
    let directory = authority.work_dir().join("command-journals");
    if !directory.exists() {
        return Ok(());
    }
    for entry in fs::read_dir(&directory).map_err(|error| io_error(&directory, error))? {
        let path = entry.map_err(|error| io_error(&directory, error))?.path();
        if path.extension().and_then(|extension| extension.to_str()) != Some("yaml") {
            continue;
        }
        let journal = read_optional_yaml_value(&path)?.ok_or_else(|| {
            KoniError::Process(format!(
                "command attempt journal disappeared: {}",
                path.display()
            ))
        })?;
        let validated = validate_command_attempt_journal_authority(&journal, root, profile, store)?;
        let authority_receipts = load_all_receipt_rows(&validated.receipts_root)?;
        let matching_receipt = authority_receipts
            .iter()
            .find(|receipt| command_attempt_journal_matches_receipt(&journal, receipt, profile));
        if journal.get("status").and_then(Value::as_str) == Some("completed")
            && matching_receipt.is_some()
        {
            continue;
        }
        if journal.get("status").and_then(Value::as_str) == Some("recovered_no_receipt") {
            continue;
        }
        let sequence = journal
            .get("sequence")
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                KoniError::Process(format!(
                    "command attempt journal has no sequence: {}",
                    path.display()
                ))
            })?;
        if let Some(receipt) = matching_receipt {
            let workspace_post = journal
                .get("workspace_post")
                .cloned()
                .and_then(|value| serde_json::from_value(value).ok());
            complete_command_attempt_journal(
                Some(&path),
                "completed",
                workspace_post.as_ref(),
                Some(receipt),
            )?;
            continue;
        }
        let pre = journal
            .get("workspace_pre")
            .cloned()
            .and_then(|value| serde_json::from_value::<WorkspaceFingerprint>(value).ok())
            .ok_or_else(|| {
                KoniError::Process(format!(
                    "command attempt journal has no exact prestate: {}",
                    path.display()
                ))
            })?;
        let current = read_only_workspace_fingerprint(
            &validated.workspace_root,
            profile,
            &validated.state_root,
        )?;
        if current.hash != pre.hash {
            complete_command_attempt_journal(Some(&path), "quarantined", Some(&current), None)?;
            return Err(KoniError::Process(format!(
                "compiler authority is quarantined by unresolved command attempt {} whose workspace differs from its exact prestate",
                sequence
            )));
        }
        complete_command_attempt_journal(
            Some(&path),
            "recovered_no_receipt",
            Some(&current),
            None,
        )?;
    }
    Ok(())
}

fn ensure_global_read_only_quarantine_clear(
    root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<()> {
    let (_barrier, sidecar_root, manifest) = acquire_run_authority_barrier(store, root)?;
    ensure_run_identity_current_under_barrier(&sidecar_root, &manifest, profile, store)?;
    ensure_global_read_only_quarantine_clear_under_barrier(root, profile, store)
}

fn ensure_global_read_only_quarantine_clear_under_barrier(
    root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<()> {
    ensure_global_read_only_quarantine_clear_under_barrier_inner(root, profile, store, false, false)
}

fn ensure_global_read_only_quarantine_clear_under_barrier_allow_prepared_rebind(
    root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<()> {
    // `recover` is the sole public authority that may enter either prepared
    // compiler transaction and finish its exact journal-bound publication.
    ensure_global_read_only_quarantine_clear_under_barrier_inner(root, profile, store, true, true)
}

fn ensure_global_read_only_quarantine_clear_under_barrier_allow_planned_proof_source_relocation(
    root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
) -> Result<()> {
    ensure_global_read_only_quarantine_clear_under_barrier_inner(root, profile, store, false, true)
}

fn ensure_global_read_only_quarantine_clear_under_barrier_inner(
    root: &Path,
    profile: &CompiledProfile,
    store: &StateStore,
    allow_prepared_rebind: bool,
    allow_planned_proof_source_relocation: bool,
) -> Result<()> {
    if !allow_prepared_rebind {
        let prepared_rebinds = read_scope_rebind_transactions(store)?
            .into_iter()
            .filter(|transaction| transaction.status != "complete")
            .map(|transaction| transaction.id)
            .collect::<Vec<_>>();
        if !prepared_rebinds.is_empty() {
            return Err(KoniError::Action(format!(
                "compiler authority is quarantined by unfinished read-scope rebind transaction(s) {}; run `koni recover --root .` before issuing context, worker, review, resume, or action authority",
                prepared_rebinds.join(", ")
            )));
        }
    }
    if !allow_planned_proof_source_relocation {
        let run = store.manifest()?;
        let mut prepared_relocations = Vec::new();
        for transaction in planned_proof_source_relocation_transactions(store)? {
            if !planned_proof_source_relocation_is_fully_sealed(profile, store, &run, &transaction)?
            {
                prepared_relocations.push(transaction.id);
            }
        }
        let committed_relocation_pending =
            committed_planned_proof_source_relocation_pending(profile, store, &run)?;
        if committed_relocation_pending {
            if prepared_relocations.is_empty() {
                prepared_relocations.push("committed-request-awaiting-transaction".to_owned());
            }
            return Err(KoniError::Action(format!(
                "compiler authority is quarantined by unfinished planned-proof source relocation transaction(s) {}; run `koni recover --root .` before issuing context, worker, review, resume, or action authority",
                prepared_relocations.join(", ")
            )));
        }
    }
    let canonical_current_root = root
        .canonicalize()
        .map_err(|error| io_error(root, error))?
        .to_string_lossy()
        .into_owned();
    let canonical_current_state_root = store
        .root()
        .canonicalize()
        .map_err(|error| io_error(store.root(), error))?
        .to_string_lossy()
        .into_owned();
    recover_or_block_command_attempt_journals(root, profile, store)?;
    let rows = command_authority_receipt_rows(profile, store, root)?;
    let corrupt_violations = rows
        .iter()
        .filter(|receipt| corrupt_or_malformed_read_only_invalid_contract(profile, receipt))
        .map(|receipt| {
            receipt
                .get("id")
                .and_then(Value::as_str)
                .unwrap_or("<unknown>")
                .to_owned()
        })
        .collect::<Vec<_>>();
    if !corrupt_violations.is_empty() {
        return Err(KoniError::Process(format!(
            "compiler authority is quarantined by corrupt read-only violation receipt(s): {}",
            corrupt_violations.join(", ")
        )));
    }
    let remediated = rows
        .iter()
        .filter(|receipt| read_only_remediation_receipt_is_valid(receipt))
        .filter_map(|receipt| {
            Some((
                receipt.get("violation_id")?.as_str()?.to_owned(),
                receipt.get("violation_receipt_hash")?.as_str()?.to_owned(),
                receipt.get("workspace_root")?.as_str()?.to_owned(),
                receipt.get("state_root")?.as_str()?.to_owned(),
                receipt.get("violation_profile_hash")?.as_str()?.to_owned(),
            ))
        })
        .collect::<BTreeSet<_>>();
    let violations = rows
        .into_iter()
        .filter(|receipt| {
            receipt_is_read_only_workspace_violation(profile, receipt)
                && command_receipt_integrity_current(receipt)
                && !remediated.contains(&(
                    receipt
                        .get("id")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_owned(),
                    receipt
                        .get("receipt_hash")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_owned(),
                    receipt
                        .get("workspace_root")
                        .and_then(Value::as_str)
                        .unwrap_or(&canonical_current_root)
                        .to_owned(),
                    receipt
                        .get("state_root")
                        .and_then(Value::as_str)
                        .unwrap_or(&canonical_current_state_root)
                        .to_owned(),
                    receipt
                        .get("profile_hash")
                        .and_then(Value::as_str)
                        .unwrap_or_default()
                        .to_owned(),
                ))
        })
        .collect::<Vec<_>>();
    if violations.is_empty() {
        return Ok(());
    }
    let mut workspace_cache = BTreeMap::<(String, String), WorkspaceFingerprint>::new();
    let mut unresolved = Vec::new();
    let mut newly_remediated = Vec::new();
    for violation in violations {
        let id = violation
            .get("id")
            .and_then(Value::as_str)
            .unwrap_or("<unknown>");
        let workspace_root = violation
            .get("workspace_root")
            .and_then(Value::as_str)
            .unwrap_or(&canonical_current_root)
            .to_owned();
        let state_root = violation
            .get("state_root")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
            .unwrap_or_else(|| canonical_current_state_root.clone());
        let violation_profile_hash = violation
            .get("profile_hash")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_owned();
        if !command_receipt_integrity_current(&violation) {
            unresolved.push(format!("{id} (receipt integrity is invalid)"));
            continue;
        }
        let Some(changes) = violation
            .get("workspace_guard")
            .and_then(|guard| guard.get("changes"))
            .and_then(Value::as_array)
        else {
            unresolved.push(format!("{id} (workspace preimages are missing)"));
            continue;
        };
        let workspace_key = (workspace_root.clone(), state_root.clone());
        if !workspace_cache.contains_key(&workspace_key) {
            let workspace_path = Path::new(&workspace_root);
            if !workspace_path.is_dir() {
                unresolved.push(format!("{id} (recorded workspace is missing)"));
                continue;
            }
            let fingerprint =
                read_only_workspace_fingerprint(workspace_path, profile, Path::new(&state_root))?;
            workspace_cache.insert(workspace_key.clone(), fingerprint);
        }
        let current = workspace_cache
            .get(&workspace_key)
            .expect("inserted workspace fingerprint");
        let mut restored = true;
        for change in changes {
            let Some(path) = change.get("path").and_then(Value::as_str) else {
                restored = false;
                break;
            };
            let Some(pre) = change.get("pre") else {
                restored = false;
                break;
            };
            if direct_workspace_fingerprint_entry(
                Path::new(&workspace_root),
                Path::new(&state_root),
                path,
            )? != *pre
            {
                restored = false;
                break;
            }
        }
        if !restored {
            unresolved.push(id.to_owned());
        } else {
            newly_remediated.push((
                id.to_owned(),
                violation
                    .get("receipt_hash")
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_owned(),
                workspace_root,
                state_root,
                current.hash.clone(),
                violation_profile_hash,
            ));
        }
    }
    if !unresolved.is_empty() {
        return Err(KoniError::Process(format!(
            "compiler authority is quarantined by unresolved read-only violation receipt(s): {}. Restore every recorded preimage before compiling again",
            unresolved.join(", ")
        )));
    }
    let remediation_authority = command_authority_store(store, root)?;
    let remediation_dir = remediation_authority.work_dir().join("remediations");
    for (
        violation_id,
        violation_receipt_hash,
        workspace_root,
        state_root,
        workspace_hash,
        violation_profile_hash,
    ) in newly_remediated
    {
        let mut receipt = json!({
            "schema_version": "1.0",
            "id": Uuid::now_v7().to_string(),
            "receipt_type": "compiler.read-only-remediation",
            "producer": "compiler.read-only-quarantine",
            "status": "passed",
            "violation_id": violation_id,
            "violation_receipt_hash": violation_receipt_hash,
            "workspace_root": workspace_root,
            "state_root": state_root,
            "workspace_hash_at_remediation": workspace_hash,
            "violation_profile_hash": violation_profile_hash,
            "recorded_at": Utc::now(),
            "profile_hash": profile.hash,
            "receipt_hash": "",
        });
        rehash_durable_receipt(&mut receipt);
        let id = receipt["id"].as_str().expect("remediation receipt id");
        durable_atomic_write_yaml(&remediation_dir.join(format!("{id}.yaml")), &receipt)?;
    }
    Ok(())
}

fn authority_workspace_paths(
    root: &Path,
    profile: &CompiledProfile,
) -> Result<BTreeMap<String, WorkspacePathFingerprint>> {
    let mut paths = BTreeMap::new();
    let storage = &profile.manifest.storage;
    let state_prefix = storage
        .state_path
        .parent()
        .filter(|path| !path.as_os_str().is_empty())
        .unwrap_or(Path::new("."));
    let under_authority_root = |configured: &Path| -> Result<PathBuf> {
        let relative = if state_prefix == Path::new(".") {
            configured
        } else {
            configured.strip_prefix(state_prefix).map_err(|_| {
                KoniError::Profile(format!(
                    "compiler-owned path {} is outside state root {}",
                    configured.display(),
                    state_prefix.display()
                ))
            })?
        };
        Ok(root.join(relative))
    };
    let catalog = compiler_owned_state_catalog(storage);
    let semantic_work_dir = under_authority_root(&storage.work_dir)?;
    let mut roots = catalog
        .directories()
        .map(|path| under_authority_root(path))
        .collect::<Result<Vec<_>>>()?;
    roots.sort();
    roots.dedup();
    for semantic_root in roots {
        if !semantic_root.exists() {
            continue;
        }
        for entry in WalkDir::new(&semantic_root)
            .follow_links(false)
            .sort_by_file_name()
        {
            let entry = entry.map_err(|error| {
                KoniError::Process(format!("state authority inventory failed: {error}"))
            })?;
            let relative = entry.path().strip_prefix(root).map_err(|_| {
                KoniError::Process("state authority inventory escaped its root".to_owned())
            })?;
            let volatile_work_file = entry.path().starts_with(&semantic_work_dir)
                && entry
                    .path()
                    .file_name()
                    .is_some_and(volatile_agent_work_file_name);
            if relative.as_os_str().is_empty() || volatile_work_file {
                continue;
            }
            paths.insert(
                normalized_project_path(relative),
                workspace_path_fingerprint(entry.path(), None, None)?,
            );
        }
    }
    for file in catalog
        .preserved_files
        .iter()
        .map(|path| under_authority_root(path))
        .collect::<Result<Vec<_>>>()?
    {
        if file.exists() {
            let relative = file.strip_prefix(root).map_err(|_| {
                KoniError::Process("state authority file escaped its root".to_owned())
            })?;
            paths.insert(
                normalized_project_path(relative),
                workspace_path_fingerprint(&file, None, None)?,
            );
        }
    }
    Ok(paths)
}

fn normalized_command_exclusion_path(path: &Path) -> Result<String> {
    let path = path.to_str().ok_or_else(|| {
        KoniError::Profile("filesystem scope exclusion is not valid UTF-8".to_owned())
    })?;
    if path == "." {
        Ok(".".to_owned())
    } else {
        normalized_relative_path(path)
    }
}

fn project_path_is_excluded(path: &str, exclusions: &BTreeSet<CommandPathExclusion>) -> bool {
    exclusions.iter().any(|excluded| {
        if excluded.path == "." {
            return true;
        }
        let excluded_path = Path::new(&excluded.path);
        match excluded.match_mode {
            CommandPathExclusionMode::Component => Path::new(path)
                .components()
                .any(|component| component.as_os_str() == excluded_path.as_os_str()),
            CommandPathExclusionMode::Prefix => {
                Path::new(path) == excluded_path || Path::new(path).starts_with(excluded_path)
            }
        }
    })
}

fn reject_project_path_symlink_components(root: &Path, path: &str, authority: &str) -> Result<()> {
    let mut current = root.to_path_buf();
    for component in Path::new(path).components() {
        if matches!(component, std::path::Component::CurDir) {
            continue;
        }
        current.push(component.as_os_str());
        if fs::symlink_metadata(&current).is_ok_and(|metadata| metadata.file_type().is_symlink()) {
            return Err(KoniError::Action(format!(
                "{authority} rejects symlink component: {}",
                current.display()
            )));
        }
    }
    Ok(())
}

/// Bind a narrow, repository-authored compatibility alias without following
/// arbitrary filesystem links. Only a direct sibling regular file is allowed;
/// the canonical target must remain inside both the project and the declared
/// ticket read scope, and its bytes are hashed into the alias entry. Directory,
/// chained, parent-relative, absolute, excluded, and out-of-scope links remain
/// fail-closed.
fn project_read_scope_symlink_manifest(
    root: &Path,
    canonical_root: &Path,
    link: &Path,
    scopes: &BTreeSet<String>,
    exclusions: &BTreeSet<CommandPathExclusion>,
) -> Result<Value> {
    let relative = link
        .strip_prefix(root)
        .map_err(|_| KoniError::Action("read scope symlink escaped project root".to_owned()))?;
    let path = normalized_project_path(relative);
    let target = fs::read_link(link).map_err(|error| io_error(link, error))?;
    let mut components = target.components();
    let direct_sibling = matches!(
        (components.next(), components.next()),
        (Some(std::path::Component::Normal(_)), None)
    );
    if !direct_sibling {
        return Err(KoniError::Action(format!(
            "read scope inventory rejects non-sibling symlink: {}",
            link.display()
        )));
    }
    let target_name = target.to_str().ok_or_else(|| {
        KoniError::Action(format!(
            "read scope inventory rejects non-UTF-8 symlink target: {}",
            link.display()
        ))
    })?;
    let target_file = link
        .parent()
        .ok_or_else(|| KoniError::Action("read scope symlink has no parent".to_owned()))?
        .join(&target);
    let target_relative = target_file.strip_prefix(root).map_err(|_| {
        KoniError::Action(format!(
            "read scope inventory symlink target escapes project: {}",
            link.display()
        ))
    })?;
    let target_path = normalized_project_path(target_relative);
    if project_path_is_excluded(&target_path, exclusions) {
        return Err(KoniError::Action(format!(
            "read scope inventory symlink targets excluded path: {path}"
        )));
    }
    if !path_is_covered_by_ticket_scope(&target_path, scopes) {
        return Err(KoniError::Action(format!(
            "read scope inventory symlink target is outside declared scope: {path}"
        )));
    }
    reject_project_path_symlink_components(root, &target_path, "read scope symlink target")?;
    let metadata =
        fs::symlink_metadata(&target_file).map_err(|error| io_error(&target_file, error))?;
    if !metadata.is_file() {
        return Err(KoniError::Action(format!(
            "read scope inventory rejects non-file symlink: {}",
            link.display()
        )));
    }
    let resolved = target_file
        .canonicalize()
        .map_err(|error| io_error(&target_file, error))?;
    if !resolved.starts_with(canonical_root) {
        return Err(KoniError::Action(format!(
            "read scope inventory symlink target escapes project: {}",
            link.display()
        )));
    }
    let bytes = fs::read(&target_file).map_err(|error| io_error(&target_file, error))?;
    Ok(json!({
        "path": path,
        "kind": "symlink",
        "link_target": target_name,
        "target_path": target_path,
        "bytes": bytes.len(),
        "sha256": raw_sha256(&bytes),
    }))
}

fn project_read_path_manifest(
    root: &Path,
    paths: &BTreeSet<String>,
    exclusions: &BTreeSet<CommandPathExclusion>,
) -> Result<Vec<Value>> {
    project_read_path_manifest_with_allowed_missing(root, paths, exclusions, &BTreeSet::new())
}

/// A compiled proof may intentionally cover a production file that the
/// approved change will create later. Its historical baseline must bind that
/// exact absence without pretending the proof source itself may be absent.
fn project_ticket_read_path_manifest(
    root: &Path,
    ticket: &Ticket,
    exclusions: &BTreeSet<CommandPathExclusion>,
) -> Result<Vec<Value>> {
    let source_paths = ticket
        .workflow
        .iter()
        .flat_map(|step| &step.compiled_check_sets)
        .flat_map(|set| &set.members)
        .flat_map(|member| &member.source_paths)
        .cloned()
        .collect::<BTreeSet<_>>();
    let allowed_missing = ticket
        .workflow
        .iter()
        .flat_map(|step| &step.compiled_check_sets)
        .flat_map(|set| &set.members)
        .flat_map(|member| &member.covered_paths)
        .filter(|path| !source_paths.contains(*path) && ticket.scope.read_paths.contains(*path))
        .cloned()
        .collect::<BTreeSet<_>>();
    project_read_path_manifest_with_allowed_missing(
        root,
        &ticket.scope.read_paths,
        exclusions,
        &allowed_missing,
    )
}

/// Bind the complete ticket read prestate for a scoped-compile receipt. A
/// reviewed graph may name an exact production path that a later implementation
/// step will create, so absence is a meaningful, hash-bound input here rather
/// than a command-launch error. Compiled proof sources remain required to exist:
/// they are executable evidence, not future product context. Command resolution
/// continues to use `project_ticket_read_path_manifest`, which permits only the
/// narrower compiled-covered-path absence and otherwise fails before spawn.
fn scoped_compile_read_path_manifest(
    root: &Path,
    ticket: &Ticket,
    exclusions: &BTreeSet<CommandPathExclusion>,
) -> Result<Vec<Value>> {
    let source_paths = ticket
        .workflow
        .iter()
        .flat_map(|step| &step.compiled_check_sets)
        .flat_map(|set| &set.members)
        .flat_map(|member| &member.source_paths)
        .cloned()
        .collect::<BTreeSet<_>>();
    let allowed_missing = ticket
        .scope
        .read_paths
        .difference(&source_paths)
        .cloned()
        .collect::<BTreeSet<_>>();
    project_read_path_manifest_with_allowed_missing(
        root,
        &ticket.scope.read_paths,
        exclusions,
        &allowed_missing,
    )
}

fn project_read_path_manifest_with_allowed_missing(
    root: &Path,
    paths: &BTreeSet<String>,
    exclusions: &BTreeSet<CommandPathExclusion>,
    allowed_missing: &BTreeSet<String>,
) -> Result<Vec<Value>> {
    let canonical_root = root.canonicalize().map_err(|error| io_error(root, error))?;
    let mut manifests = Vec::new();
    for configured in paths {
        let normalized = if configured == "." {
            ".".to_owned()
        } else {
            normalized_relative_path(configured)?
        };
        let concrete = if normalized == "." {
            root.to_path_buf()
        } else {
            root.join(&normalized)
        };
        if project_path_is_excluded(&normalized, exclusions) {
            return Err(KoniError::Action(format!(
                "command read scope path is wholly excluded by its configured inventory policy: {normalized}"
            )));
        }
        reject_project_path_symlink_components(root, &normalized, "read scope inventory")?;
        if !concrete.exists() {
            if allowed_missing.contains(&normalized) {
                let mut manifest = json!({
                    "path": normalized,
                    "kind": "missing",
                    "files": [],
                });
                manifest["hash"] = Value::String(normalized_hash(&manifest));
                manifests.push(manifest);
                continue;
            }
            return Err(KoniError::Action(format!(
                "dynamic command read scope path does not exist: {normalized}"
            )));
        }
        let resolved = concrete
            .canonicalize()
            .map_err(|error| io_error(&concrete, error))?;
        if !resolved.starts_with(&canonical_root) {
            return Err(KoniError::Action(format!(
                "read scope path escapes project root: {normalized}"
            )));
        }
        let mut files = Vec::new();
        if resolved.is_file() {
            let bytes = fs::read(&resolved).map_err(|error| io_error(&resolved, error))?;
            files.push(json!({
                "path": normalized,
                "bytes": bytes.len(),
                "sha256": raw_sha256(&bytes),
            }));
        } else if resolved.is_dir() {
            for entry in WalkDir::new(&concrete)
                .follow_links(false)
                .sort_by_file_name()
                .into_iter()
                .filter_entry(|entry| {
                    if entry.path() == concrete {
                        return true;
                    }
                    entry
                        .path()
                        .strip_prefix(root)
                        .ok()
                        .map(normalized_project_path)
                        .is_none_or(|path| !project_path_is_excluded(&path, exclusions))
                })
            {
                let entry = entry.map_err(|error| {
                    KoniError::Action(format!("read scope inventory failed: {error}"))
                })?;
                if entry.path() == concrete {
                    continue;
                }
                let metadata = fs::symlink_metadata(entry.path())
                    .map_err(|error| io_error(entry.path(), error))?;
                if metadata.file_type().is_symlink() {
                    files.push(project_read_scope_symlink_manifest(
                        root,
                        &canonical_root,
                        entry.path(),
                        paths,
                        exclusions,
                    )?);
                    continue;
                }
                if !metadata.is_file() {
                    continue;
                }
                let relative = entry.path().strip_prefix(root).map_err(|_| {
                    KoniError::Action("read scope inventory escaped project".to_owned())
                })?;
                let path = normalized_project_path(relative);
                let bytes =
                    fs::read(entry.path()).map_err(|error| io_error(entry.path(), error))?;
                files.push(json!({
                    "path": path,
                    "bytes": bytes.len(),
                    "sha256": raw_sha256(&bytes),
                }));
            }
        } else {
            return Err(KoniError::Action(format!(
                "read scope path is neither file nor directory: {normalized}"
            )));
        }
        if files.is_empty() {
            return Err(KoniError::Action(format!(
                "dynamic command read scope path has no regular files: {normalized}"
            )));
        }
        files.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
        let kind = if resolved.is_file() {
            "file"
        } else {
            "directory"
        };
        let mut manifest = json!({"path": normalized, "kind": kind, "files": files});
        manifest["hash"] = Value::String(normalized_hash(&manifest));
        manifests.push(manifest);
    }
    manifests.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
    Ok(manifests)
}

/// Snapshot the prestate of paths a ticket may write without pretending those
/// paths are already readable inputs. Planned files and empty directories are
/// valid write authority, while every existing byte and an explicit `missing`
/// state remain bound so creation, deletion, or mutation invalidates the
/// scoped-compile receipt. Unlike the narrow read-scope compatibility alias,
/// write authority never follows symlinks.
fn project_write_path_manifest(
    root: &Path,
    paths: &BTreeSet<String>,
    exclusions: &BTreeSet<CommandPathExclusion>,
) -> Result<Vec<Value>> {
    let canonical_root = root.canonicalize().map_err(|error| io_error(root, error))?;
    let mut manifests = Vec::new();
    for configured in paths {
        let normalized = if configured == "." {
            ".".to_owned()
        } else {
            normalized_relative_path(configured)?
        };
        if project_path_is_excluded(&normalized, exclusions) {
            return Err(KoniError::Action(format!(
                "command write scope path is wholly excluded by its configured inventory policy: {normalized}"
            )));
        }
        reject_project_path_symlink_components(root, &normalized, "write scope inventory")?;
        let concrete = if normalized == "." {
            root.to_path_buf()
        } else {
            root.join(&normalized)
        };
        let mut files = Vec::new();
        let kind = if !concrete.exists() {
            "missing"
        } else {
            let metadata =
                fs::symlink_metadata(&concrete).map_err(|error| io_error(&concrete, error))?;
            if metadata.file_type().is_symlink() {
                return Err(KoniError::Action(format!(
                    "write scope inventory rejects symlink: {}",
                    concrete.display()
                )));
            }
            let resolved = concrete
                .canonicalize()
                .map_err(|error| io_error(&concrete, error))?;
            if !resolved.starts_with(&canonical_root) {
                return Err(KoniError::Action(format!(
                    "write scope path escapes project root: {normalized}"
                )));
            }
            if resolved.is_file() {
                let bytes = fs::read(&resolved).map_err(|error| io_error(&resolved, error))?;
                files.push(json!({
                    "path": normalized,
                    "bytes": bytes.len(),
                    "sha256": raw_sha256(&bytes),
                }));
                "file"
            } else if resolved.is_dir() {
                for entry in WalkDir::new(&concrete)
                    .follow_links(false)
                    .sort_by_file_name()
                    .into_iter()
                    .filter_entry(|entry| {
                        if entry.path() == concrete {
                            return true;
                        }
                        entry
                            .path()
                            .strip_prefix(root)
                            .ok()
                            .map(normalized_project_path)
                            .is_none_or(|path| !project_path_is_excluded(&path, exclusions))
                    })
                {
                    let entry = entry.map_err(|error| {
                        KoniError::Action(format!("write scope prestate inventory failed: {error}"))
                    })?;
                    if entry.path() == concrete {
                        continue;
                    }
                    let metadata = fs::symlink_metadata(entry.path())
                        .map_err(|error| io_error(entry.path(), error))?;
                    if metadata.file_type().is_symlink() {
                        return Err(KoniError::Action(format!(
                            "write scope inventory rejects symlink: {}",
                            entry.path().display()
                        )));
                    }
                    if !metadata.is_file() {
                        continue;
                    }
                    let relative = entry.path().strip_prefix(root).map_err(|_| {
                        KoniError::Action("write scope prestate escaped project".to_owned())
                    })?;
                    let path = normalized_project_path(relative);
                    let bytes =
                        fs::read(entry.path()).map_err(|error| io_error(entry.path(), error))?;
                    files.push(json!({
                        "path": path,
                        "bytes": bytes.len(),
                        "sha256": raw_sha256(&bytes),
                    }));
                }
                "directory"
            } else {
                return Err(KoniError::Action(format!(
                    "write scope path is neither a file nor directory: {normalized}"
                )));
            }
        };
        files.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
        let mut manifest = json!({"path": normalized, "kind": kind, "files": files});
        manifest["hash"] = Value::String(normalized_hash(&manifest));
        manifests.push(manifest);
    }
    manifests.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
    Ok(manifests)
}

/// Exact source bytes for a graph-selected proof/test member. Source evidence
/// is stricter than ordinary ticket read authority: it must already exist,
/// contain at least one regular file, and contain no symlink at any depth.
/// Reusing the write-prestate walker gives us those no-follow guarantees; the
/// post-validation below removes its intentional missing/empty allowances.
fn project_source_path_manifest(
    root: &Path,
    paths: &BTreeSet<String>,
    exclusions: &BTreeSet<CommandPathExclusion>,
) -> Result<Vec<Value>> {
    if paths.is_empty() {
        return Err(KoniError::Action(
            "compiled graph-set member has no source paths".to_owned(),
        ));
    }
    let manifests = project_write_path_manifest(root, paths, exclusions)?;
    for manifest in &manifests {
        let path = manifest
            .get("path")
            .and_then(Value::as_str)
            .unwrap_or("<unknown>");
        if manifest.get("kind").and_then(Value::as_str) == Some("missing") {
            return Err(KoniError::Action(format!(
                "compiled graph-set source path does not exist: {path}"
            )));
        }
        if manifest
            .get("files")
            .and_then(Value::as_array)
            .is_none_or(Vec::is_empty)
        {
            return Err(KoniError::Action(format!(
                "compiled graph-set source path has no regular files: {path}"
            )));
        }
    }
    Ok(manifests)
}

fn dynamic_path_prestate(root: &Path, roots: &[String]) -> Result<Value> {
    let canonical_root = root.canonicalize().map_err(|error| io_error(root, error))?;
    let mut manifests = Vec::new();
    for configured in roots {
        if configured == "." {
            return Err(KoniError::Action(
                "produced-output authority may not cover the entire project".to_owned(),
            ));
        }
        let normalized = normalized_relative_path(configured)?;
        reject_project_path_symlink_components(root, &normalized, "produced-output scope")?;
        let concrete = root.join(&normalized);
        let mut files = Vec::new();
        let kind = if !concrete.exists() {
            "missing"
        } else {
            if fs::symlink_metadata(&concrete)
                .is_ok_and(|metadata| metadata.file_type().is_symlink())
            {
                return Err(KoniError::Action(format!(
                    "produced-output scope rejects symlink: {}",
                    concrete.display()
                )));
            }
            let resolved = concrete
                .canonicalize()
                .map_err(|error| io_error(&concrete, error))?;
            if !resolved.starts_with(&canonical_root) {
                return Err(KoniError::Action(format!(
                    "produced-output scope escapes project root: {normalized}"
                )));
            }
            if resolved.is_file() {
                let bytes = fs::read(&resolved).map_err(|error| io_error(&resolved, error))?;
                files.push(json!({
                    "path": normalized,
                    "bytes": bytes.len(),
                    "sha256": raw_sha256(&bytes),
                }));
                "file"
            } else if resolved.is_dir() {
                for entry in WalkDir::new(&concrete)
                    .follow_links(false)
                    .sort_by_file_name()
                {
                    let entry = entry.map_err(|error| {
                        KoniError::Action(format!(
                            "produced-output prestate inventory failed: {error}"
                        ))
                    })?;
                    if entry.path() == concrete {
                        continue;
                    }
                    let metadata = fs::symlink_metadata(entry.path())
                        .map_err(|error| io_error(entry.path(), error))?;
                    if metadata.file_type().is_symlink() {
                        return Err(KoniError::Action(format!(
                            "produced-output scope rejects symlink: {}",
                            entry.path().display()
                        )));
                    }
                    if !metadata.is_file() {
                        continue;
                    }
                    let relative = entry.path().strip_prefix(root).map_err(|_| {
                        KoniError::Action("produced-output prestate escaped project".to_owned())
                    })?;
                    let path = normalized_project_path(relative);
                    let bytes =
                        fs::read(entry.path()).map_err(|error| io_error(entry.path(), error))?;
                    files.push(json!({
                        "path": path,
                        "bytes": bytes.len(),
                        "sha256": raw_sha256(&bytes),
                    }));
                }
                "directory"
            } else {
                return Err(KoniError::Action(format!(
                    "produced-output scope is neither a file nor directory: {normalized}"
                )));
            }
        };
        files.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
        let mut manifest = json!({"path": normalized, "kind": kind, "files": files});
        manifest["hash"] = Value::String(normalized_hash(&manifest));
        manifests.push(manifest);
    }
    manifests.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
    let mut prestate = json!({"schema_version": "1.0", "roots": manifests});
    prestate["hash"] = Value::String(normalized_hash(&prestate));
    Ok(prestate)
}

fn path_manifest_sha256<'a>(manifests: &'a [Value], path: &str) -> Option<&'a str> {
    manifests
        .iter()
        .filter_map(|manifest| manifest.get("files").and_then(Value::as_array))
        .flatten()
        .find(|file| file.get("path").and_then(Value::as_str) == Some(path))
        .and_then(|file| file.get("sha256"))
        .and_then(Value::as_str)
}

fn dynamic_prestate_sha256<'a>(prestate: &'a Value, path: &str) -> Option<&'a str> {
    prestate
        .get("roots")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|manifest| manifest.get("files").and_then(Value::as_array))
        .flatten()
        .find(|file| file.get("path").and_then(Value::as_str) == Some(path))
        .and_then(|file| file.get("sha256"))
        .and_then(Value::as_str)
}

fn collect_graph_node_references(value: &Value, graph: &Graph, output: &mut BTreeSet<NodeId>) {
    match value {
        Value::String(candidate) if graph.node(candidate).is_some() => {
            output.insert(candidate.clone());
        }
        Value::Array(items) => {
            for item in items {
                collect_graph_node_references(item, graph, output);
            }
        }
        Value::Object(object) => {
            for item in object.values() {
                collect_graph_node_references(item, graph, output);
            }
        }
        _ => {}
    }
}

fn receipt_sort_key(value: &Value) -> (String, String) {
    let timestamp = value
        .get("recorded_at")
        .or_else(|| value.get("finished_at"))
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_owned();
    let receipt_id = value
        .get("id")
        .or_else(|| value.get("receipt_id"))
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_owned();
    (timestamp, receipt_id)
}

fn load_receipt_rows_with_input_currentness(
    profile: &CompiledProfile,
    store: &StateStore,
    project_root: &Path,
    graph: &Graph,
    receipt_type: &str,
) -> Result<Vec<Value>> {
    let mut rows = load_receipt_rows(store.receipts_dir(), receipt_type)?;
    let violation_watermark = read_only_violation_watermark(profile, store, project_root)?;
    for receipt in &mut rows {
        strip_receipt_currentness_markers(receipt);
        if receipt_kind(receipt) == Some("scoped-compile") {
            let current = receipt
                .get("ticket_id")
                .and_then(Value::as_str)
                .and_then(|id| store.ticket(id).ok())
                .is_some_and(|ticket| {
                    scoped_compile_receipt_is_current(
                        profile,
                        &ticket,
                        receipt,
                        graph,
                        project_root,
                    )
                });
            mark_scoped_compile_currentness(receipt, current);
            continue;
        }
        let Some(check) = configured_command_check_for_receipt(profile, receipt) else {
            if receipt_names_configured_command(profile, receipt)
                || profile
                    .checks
                    .get(receipt_type)
                    .is_some_and(|check| check.kind == CheckKind::Command)
                || receipt_type_has_configured_command(profile, receipt_type)
            {
                mark_command_receipt_not_current(receipt);
            }
            continue;
        };
        let ticket = receipt
            .get("ticket_id")
            .and_then(Value::as_str)
            .and_then(|id| store.ticket(id).ok());
        decorate_command_receipt_currentness(
            profile,
            check,
            ticket.as_ref(),
            graph,
            project_root,
            store,
            receipt,
            violation_watermark,
        );
    }
    Ok(rows)
}

fn decorate_receipt_rows_for_ticket(
    profile: &CompiledProfile,
    store: &StateStore,
    ticket: &Ticket,
    graph: &Graph,
    project_root: &Path,
    rows: &mut [Value],
) {
    let violation_watermark = match read_only_violation_watermark(profile, store, project_root) {
        Ok(watermark) => watermark,
        Err(_) => {
            for receipt in rows {
                strip_receipt_currentness_markers(receipt);
                mark_command_receipt_not_current(receipt);
            }
            return;
        }
    };
    decorate_receipt_rows_for_ticket_with_watermark(
        profile,
        store,
        ticket,
        graph,
        project_root,
        rows,
        violation_watermark,
    );
}

fn decorate_receipt_rows_for_ticket_with_watermark(
    profile: &CompiledProfile,
    store: &StateStore,
    ticket: &Ticket,
    graph: &Graph,
    project_root: &Path,
    rows: &mut [Value],
    violation_watermark: Option<u64>,
) {
    for receipt in rows {
        strip_receipt_currentness_markers(receipt);
        if receipt_kind(receipt) == Some("scoped-compile") {
            let current =
                scoped_compile_receipt_is_current(profile, ticket, receipt, graph, project_root);
            mark_scoped_compile_currentness(receipt, current);
            continue;
        }
        if let Some(check) = configured_command_check_for_receipt(profile, receipt) {
            decorate_command_receipt_currentness(
                profile,
                check,
                Some(ticket),
                graph,
                project_root,
                store,
                receipt,
                violation_watermark,
            );
        } else if receipt_names_configured_command(profile, receipt) {
            mark_command_receipt_not_current(receipt);
        }
    }
}

fn strip_receipt_currentness_markers(receipt: &mut Value) {
    if let Some(object) = receipt.as_object_mut() {
        object.retain(|key, _| !key.starts_with('_'));
    }
}

fn mark_scoped_compile_currentness(receipt: &mut Value, current: bool) {
    if let Some(object) = receipt.as_object_mut() {
        object.insert("_scoped_compile_current".to_owned(), Value::Bool(current));
    }
}

fn receipt_type_has_configured_command(profile: &CompiledProfile, receipt_type: &str) -> bool {
    profile
        .checks
        .values()
        .any(|check| check.kind == CheckKind::Command && check.receipt_type == receipt_type)
}

fn receipt_names_configured_command(profile: &CompiledProfile, receipt: &Value) -> bool {
    receipt
        .get("check_id")
        .and_then(Value::as_str)
        .and_then(|id| profile.checks.get(id))
        .is_some_and(|check| check.kind == CheckKind::Command)
        || receipt_kind(receipt)
            .is_some_and(|kind| receipt_type_has_configured_command(profile, kind))
}

fn configured_command_check_for_receipt<'a>(
    profile: &'a CompiledProfile,
    receipt: &Value,
) -> Option<&'a crate::config::CheckDef> {
    let receipt_type = receipt.get("receipt_type").and_then(Value::as_str)?;
    if let Some(check_id) = receipt.get("check_id").and_then(Value::as_str) {
        return profile.checks.get(check_id).filter(|check| {
            check.kind == CheckKind::Command && check.receipt_type == receipt_type
        });
    }
    let mut matching_type = profile
        .checks
        .values()
        .filter(|check| check.kind == CheckKind::Command && check.receipt_type == receipt_type);
    let unique = matching_type.next()?;
    if matching_type.next().is_some() {
        return None;
    }
    Some(unique)
}

fn mark_command_receipt_not_current(receipt: &mut Value) {
    let Some(object) = receipt.as_object_mut() else {
        return;
    };
    for marker in [
        "_receipt_integrity_current",
        "_profile_current",
        "_execution_binding_current",
        "_target_scope_current",
        "_artifact_manifest_current",
        "_result_source_current",
        "_dynamic_paths_current",
        "_workspace_guard_current",
        "_terminal_evidence_current",
        "_spawn_binding_current",
        "_violation_precedence_current",
        "_input_binding_current",
        "_historical_evidence_valid",
        "_command_current",
    ] {
        object.insert(marker.to_owned(), Value::Bool(false));
    }
}

fn command_receipt_historical_evidence_valid(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    receipt: &Value,
    violation_watermark: Option<u64>,
) -> bool {
    if check.receipt_freshness != crate::config::ReceiptFreshness::Historical {
        return false;
    }
    let Some(ticket) = ticket else {
        return false;
    };
    let recorded = receipt
        .get("execution_binding")
        .cloned()
        .and_then(|value| serde_json::from_value::<ResolvedCheckExecution>(value).ok());
    let recorded_post = receipt
        .get("post_execution_binding")
        .cloned()
        .and_then(|value| serde_json::from_value::<ResolvedCheckExecution>(value).ok());
    let expected_codes = if check.expected_exit_codes.is_empty() {
        vec![0]
    } else {
        check.expected_exit_codes.clone()
    };
    let target_ids = receipt
        .get("target_node_ids")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(ToOwned::to_owned)
        .collect::<BTreeSet<_>>();
    let configured_targets = ticket.target_nodes.iter().cloned().collect::<BTreeSet<_>>();
    let binding_unchanged =
        recorded
            .as_ref()
            .zip(recorded_post.as_ref())
            .is_some_and(|(pre, post)| {
                resolved_execution_binding_integrity_current(pre)
                    && resolved_execution_binding_integrity_current(post)
                    && pre.binding_hash == post.binding_hash
                    && receipt
                        .get("execution_binding_hash")
                        .and_then(Value::as_str)
                        == Some(pre.binding_hash.as_str())
                    && receipt
                        .get("post_execution_binding_hash")
                        .and_then(Value::as_str)
                        == Some(post.binding_hash.as_str())
                    && command_spawn_binding_current(receipt, pre)
            });
    let after_last_read_only_violation = violation_watermark.is_none_or(|watermark| {
        receipt
            .get("command_attempt_sequence")
            .and_then(Value::as_u64)
            .unwrap_or(0)
            > watermark
    });

    command_receipt_integrity_current(receipt)
        && receipt.get("check_id").and_then(Value::as_str) == Some(check.id.as_str())
        && receipt.get("receipt_type").and_then(Value::as_str) == Some(check.receipt_type.as_str())
        && receipt.get("receipt_freshness").and_then(Value::as_str) == Some("historical")
        && receipt.get("process_effect").and_then(Value::as_str) == Some("read_only")
        && receipt.get("profile_hash").and_then(Value::as_str) == Some(profile.hash.as_str())
        && receipt.get("ticket_id").and_then(Value::as_str) == Some(ticket.id.as_str())
        && receipt.get("status").and_then(Value::as_str) == Some("passed")
        && receipt.get("expected_exit_codes") == Some(&json!(expected_codes))
        && target_ids == configured_targets
        && binding_unchanged
        && receipt
            .get("execution_bindings_unchanged")
            .and_then(Value::as_bool)
            == Some(true)
        && receipt
            .get("input_bindings_unchanged")
            .and_then(Value::as_bool)
            == Some(true)
        && command_workspace_guard_current(receipt, check)
        && command_terminal_evidence_current(receipt, &check.expected_exit_codes)
        && after_last_read_only_violation
}

#[allow(clippy::too_many_arguments)]
fn decorate_command_receipt_currentness(
    profile: &CompiledProfile,
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    graph: &Graph,
    project_root: &Path,
    store: &StateStore,
    receipt: &mut Value,
    violation_watermark: Option<u64>,
) {
    let integrity = command_receipt_integrity_current(receipt)
        && receipt.get("check_id").and_then(Value::as_str) == Some(check.id.as_str())
        && receipt.get("receipt_type").and_then(Value::as_str) == Some(check.receipt_type.as_str());
    let profile_current =
        receipt.get("profile_hash").and_then(Value::as_str) == Some(profile.hash.as_str());
    let recorded = receipt
        .get("execution_binding")
        .cloned()
        .and_then(|value| serde_json::from_value::<ResolvedCheckExecution>(value).ok());
    let recorded_post = receipt
        .get("post_execution_binding")
        .cloned()
        .and_then(|value| serde_json::from_value::<ResolvedCheckExecution>(value).ok());
    let recorded_integrity = recorded
        .as_ref()
        .is_some_and(resolved_execution_binding_integrity_current);
    let recorded_post_integrity = recorded_post
        .as_ref()
        .is_some_and(resolved_execution_binding_integrity_current);
    let mut cache = ExecutionResolutionCache::default();
    let current = if let Some(binding) = recorded
        .as_ref()
        .and_then(|binding| binding.compiled_member_binding.as_ref())
    {
        resolve_current_compiled_member_execution(
            profile,
            check,
            ticket,
            binding,
            graph,
            project_root,
            store,
            &mut cache,
        )
        .ok()
    } else if let Some(binding) = recorded
        .as_ref()
        .and_then(|binding| binding.gate_policy_binding.as_ref())
    {
        Some(
            resolve_gate_policy_check_execution_with_store(
                profile,
                check,
                &binding.selection.policy_id,
                &binding.selection.gate.id,
                graph,
                project_root,
                store,
                &mut cache,
            )
            .ok(),
        )
        .flatten()
    } else {
        Some(
            resolve_check_execution_with_store(profile, check, ticket, graph, project_root, store)
                .ok(),
        )
        .flatten()
    };
    let execution_current = recorded
        .as_ref()
        .zip(recorded_post.as_ref())
        .zip(current.as_ref())
        .is_some_and(|((recorded, recorded_post), current)| {
            (recorded.binding_hash == current.binding_hash
                || gate_policy_execution_equivalent(recorded, current))
                && recorded_post.binding_hash == recorded.binding_hash
                && receipt
                    .get("execution_binding_hash")
                    .and_then(Value::as_str)
                    == Some(recorded.binding_hash.as_str())
                && receipt
                    .get("post_execution_binding_hash")
                    .and_then(Value::as_str)
                    == Some(recorded_post.binding_hash.as_str())
                && receipt
                    .get("execution_bindings_unchanged")
                    .and_then(Value::as_bool)
                    == Some(true)
                && receipt
                    .get("input_bindings_unchanged")
                    .and_then(Value::as_bool)
                    == Some(true)
                && receipt
                    .get("semantic_argv")
                    .and_then(Value::as_array)
                    .is_some_and(|argv| {
                        argv.iter().map(Value::as_str).collect::<Option<Vec<_>>>()
                            == Some(recorded.argv.iter().map(String::as_str).collect())
                    })
        });
    let target_scope_current = match recorded
        .as_ref()
        .and_then(|binding| binding.gate_policy_binding.as_ref())
    {
        Some(binding) => {
            let subject_ids = receipt
                .get("subject_node_ids")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .collect::<BTreeSet<_>>();
            let evaluation_ids = receipt
                .get("evaluation_target_node_ids")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(Value::as_str)
                .collect::<BTreeSet<_>>();
            subject_ids == BTreeSet::from([binding.selection.gate.id.as_str()])
                && evaluation_ids
                    == binding
                        .evaluation_targets
                        .keys()
                        .map(String::as_str)
                        .collect()
                && receipt.get("gate_policy_id").and_then(Value::as_str)
                    == Some(binding.selection.policy_id.as_str())
        }
        None => match (ticket, recorded.as_ref()) {
            (Some(ticket), Some(binding)) => {
                let target_ids = ticket.target_nodes.iter().cloned().collect::<BTreeSet<_>>();
                let recorded_ids = receipt
                    .get("target_node_ids")
                    .and_then(Value::as_array)
                    .into_iter()
                    .flatten()
                    .filter_map(Value::as_str)
                    .map(ToOwned::to_owned)
                    .collect::<BTreeSet<_>>();
                let target_hashes = receipt.get("target_hashes").and_then(Value::as_object);
                target_ids == recorded_ids
                    && binding.target_bindings.len() == target_ids.len()
                    && target_hashes.is_some_and(|hashes| {
                        target_ids.iter().all(|id| {
                            binding.target_bindings.get(id).is_some_and(|semantic| {
                                hashes.get(id).and_then(Value::as_str)
                                    == Some(semantic.semantic_hash.as_str())
                            })
                        })
                    })
            }
            (None, Some(binding)) => {
                receipt.get("ticket_id").is_none_or(Value::is_null)
                    && binding.target_bindings.is_empty()
                    && binding.read_scope_bindings.is_empty()
            }
            _ => false,
        },
    };
    let artifact_current = command_artifact_manifest_current(receipt, project_root);
    let result_source_current = command_result_source_current(receipt, project_root, check);
    let dynamic_paths_current = command_dynamic_path_manifest_current(
        receipt,
        project_root,
        check,
        ticket,
        recorded.as_ref(),
    );
    let workspace_guard_current = command_workspace_guard_current(receipt, check);
    let terminal_evidence_current =
        command_terminal_evidence_current(receipt, &check.expected_exit_codes);
    let spawn_binding_current = recorded
        .as_ref()
        .is_some_and(|recorded| command_spawn_binding_current(receipt, recorded));
    let violation_precedence_current = check.effect != crate::config::ProcessEffect::ReadOnly
        || violation_watermark.is_none_or(|watermark| {
            receipt
                .get("command_attempt_sequence")
                .and_then(Value::as_u64)
                .unwrap_or(0)
                > watermark
        });
    let historical_evidence_valid = command_receipt_historical_evidence_valid(
        profile,
        check,
        ticket,
        receipt,
        violation_watermark,
    );
    let current = integrity
        && profile_current
        && recorded_integrity
        && recorded_post_integrity
        && execution_current
        && target_scope_current
        && artifact_current
        && result_source_current
        && dynamic_paths_current
        && workspace_guard_current
        && terminal_evidence_current
        && spawn_binding_current
        && violation_precedence_current;
    let object = receipt.as_object_mut().expect("receipt row is an object");
    object.insert(
        "_receipt_integrity_current".to_owned(),
        Value::Bool(integrity),
    );
    object.insert("_profile_current".to_owned(), Value::Bool(profile_current));
    object.insert(
        "_execution_binding_current".to_owned(),
        Value::Bool(recorded_integrity && recorded_post_integrity && execution_current),
    );
    object.insert(
        "_target_scope_current".to_owned(),
        Value::Bool(target_scope_current),
    );
    object.insert(
        "_artifact_manifest_current".to_owned(),
        Value::Bool(artifact_current),
    );
    object.insert(
        "_result_source_current".to_owned(),
        Value::Bool(result_source_current),
    );
    object.insert(
        "_dynamic_paths_current".to_owned(),
        Value::Bool(dynamic_paths_current),
    );
    object.insert(
        "_workspace_guard_current".to_owned(),
        Value::Bool(workspace_guard_current),
    );
    object.insert(
        "_terminal_evidence_current".to_owned(),
        Value::Bool(terminal_evidence_current),
    );
    object.insert(
        "_spawn_binding_current".to_owned(),
        Value::Bool(spawn_binding_current),
    );
    object.insert(
        "_violation_precedence_current".to_owned(),
        Value::Bool(violation_precedence_current),
    );
    object.insert("_input_binding_current".to_owned(), Value::Bool(current));
    object.insert(
        "_historical_evidence_valid".to_owned(),
        Value::Bool(historical_evidence_valid),
    );
    object.insert("_command_current".to_owned(), Value::Bool(current));
}

fn command_spawn_binding_current(receipt: &Value, execution: &ResolvedCheckExecution) -> bool {
    let Some(binding) = receipt.get("spawn_binding") else {
        return false;
    };
    if execution.sandbox_executable.is_none() {
        let semantic_argv_hash = normalized_hash(&execution.argv);
        return binding.get("kind").and_then(Value::as_str) == Some("none")
            && binding.get("semantic_argv_hash").and_then(Value::as_str)
                == Some(semantic_argv_hash.as_str());
    }
    let rendered_hash = binding.get("rendered_profile_hash").and_then(Value::as_str);
    binding.get("kind").and_then(Value::as_str) == Some("macos-seatbelt.v2")
        && binding.get("semantic_profile_hash").and_then(Value::as_str)
            == execution.sandbox_profile_hash.as_deref()
        && rendered_hash.is_some_and(|hash| {
            hash.strip_prefix("sha256:").is_some_and(|digest| {
                digest.len() == 64 && digest.bytes().all(|byte| byte.is_ascii_hexdigit())
            })
        })
        && binding
            .get("project_root")
            .and_then(Value::as_str)
            .is_some()
        && binding.get("state_root").and_then(Value::as_str).is_some()
        && binding
            .get("private_temp")
            .and_then(Value::as_str)
            .is_some()
}

fn gate_policy_execution_equivalent(
    recorded: &ResolvedCheckExecution,
    current: &ResolvedCheckExecution,
) -> bool {
    let (Some(recorded_gate), Some(current_gate)) = (
        recorded.gate_policy_binding.as_ref(),
        current.gate_policy_binding.as_ref(),
    ) else {
        return false;
    };
    if !gate_policy_selection_equivalent_except_compiler_ranks(
        &recorded_gate.selection,
        &current_gate.selection,
    ) {
        return false;
    }
    let mut normalized = current.clone();
    let gate = normalized
        .gate_policy_binding
        .as_mut()
        .expect("checked current gate binding");
    gate.selection = recorded_gate.selection.clone();
    gate.binding_hash.clear();
    gate.binding_hash = normalized_hash(gate);
    normalized.binding_hash.clear();
    normalized.binding_hash = normalized_hash(&normalized);
    normalized == *recorded
}

fn gate_policy_selection_equivalent_except_compiler_ranks(
    recorded: &GatePolicySelectionBinding,
    current: &GatePolicySelectionBinding,
) -> bool {
    if recorded.policy_id != current.policy_id
        || recorded.policy_hash != current.policy_hash
        || recorded.gate != current.gate
        || recorded.required_capability_name != current.required_capability_name
        || recorded.required_version_requirement != current.required_version_requirement
        || recorded.capability_contract_valid != current.capability_contract_valid
        || recorded.capability_contract_hash != current.capability_contract_hash
        || recorded.selection_mode != current.selection_mode
        || recorded.selection_contract != current.selection_contract
        || recorded.winner_id != current.winner_id
    {
        return false;
    }
    if recorded
        .candidate_pool_projection
        .iter()
        .map(|candidate| (&candidate.id, &candidate.node_type))
        .collect::<Vec<_>>()
        != current
            .candidate_pool_projection
            .iter()
            .map(|candidate| (&candidate.id, &candidate.node_type))
            .collect::<Vec<_>>()
    {
        return false;
    }
    let normalize = |candidate: &GateCandidateBinding| {
        json!({
            "id": candidate.id,
            "node_type": candidate.node_type,
            "semantic_hash": candidate.semantic_hash,
            "matched_capability_index": candidate.matched_capability_index,
            "matched_capability": candidate.matched_capability,
            "matched_capability_hash": candidate.matched_capability_hash,
            "tie_break_value": candidate.tie_break_value,
            "tie_break_hash": candidate.tie_break_hash,
        })
    };
    recorded
        .compatible_candidates
        .iter()
        .map(normalize)
        .collect::<Vec<_>>()
        == current
            .compatible_candidates
            .iter()
            .map(normalize)
            .collect::<Vec<_>>()
}

fn resolved_execution_binding_integrity_current(binding: &ResolvedCheckExecution) -> bool {
    let expected = binding.binding_hash.clone();
    if expected.is_empty() {
        return false;
    }
    let mut candidate = binding.clone();
    candidate.binding_hash.clear();
    normalized_hash(&candidate) == expected
        && binding
            .gate_policy_binding
            .as_ref()
            .is_none_or(gate_policy_binding_integrity_current)
        && binding
            .compiled_member_binding
            .as_ref()
            .is_none_or(compiled_member_execution_binding_integrity_current)
        && binding
            .repository_tool
            .as_ref()
            .is_none_or(repository_tool_binding_integrity_current)
}

fn repository_tool_binding_integrity_current(binding: &RepositoryToolBinding) -> bool {
    if binding.binding_hash.is_empty() {
        return false;
    }
    let expected = binding.binding_hash.clone();
    let mut candidate = binding.clone();
    candidate.binding_hash.clear();
    normalized_hash(&candidate) == expected
}

fn compiled_member_execution_binding_integrity_current(
    binding: &CompiledMemberExecutionBinding,
) -> bool {
    if binding.binding_hash.is_empty() {
        return false;
    }
    let expected = binding.binding_hash.clone();
    let mut candidate = binding.clone();
    candidate.binding_hash.clear();
    normalized_hash(&candidate) == expected
}

fn gate_policy_binding_integrity_current(binding: &GatePolicyBinding) -> bool {
    if binding.binding_hash.is_empty()
        || binding
            .selection
            .compatible_candidates
            .iter()
            .any(|candidate| {
                normalized_hash(&candidate.matched_capability) != candidate.matched_capability_hash
                    || normalized_hash(&candidate.tie_break_value) != candidate.tie_break_hash
                    || candidate
                        .ranks
                        .iter()
                        .any(|rank| normalized_hash(&rank.observed) != rank.observed_hash)
            })
    {
        return false;
    }
    let expected = binding.binding_hash.clone();
    let mut candidate = binding.clone();
    candidate.binding_hash.clear();
    normalized_hash(&candidate) == expected
        && gate_policy_selection_binding_integrity_current(&binding.selection)
}

fn gate_policy_selection_binding_integrity_current(binding: &GatePolicySelectionBinding) -> bool {
    if binding.binding_hash.is_empty() {
        return false;
    }
    let expected = binding.binding_hash.clone();
    let mut candidate = binding.clone();
    candidate.binding_hash.clear();
    normalized_hash(&candidate) == expected
}

fn command_receipt_integrity_current(receipt: &Value) -> bool {
    durable_receipt_integrity_current(receipt) && command_attempt_hashes_current(receipt)
}

fn command_attempt_hashes_current(receipt: &Value) -> bool {
    receipt
        .get("attempts")
        .and_then(Value::as_array)
        .is_some_and(|attempts| {
            attempts.iter().enumerate().all(|(index, attempt)| {
                let stdout = attempt.get("stdout").and_then(Value::as_str);
                let stderr = attempt.get("stderr").and_then(Value::as_str);
                attempt.get("attempt").and_then(Value::as_u64) == Some((index + 1) as u64)
                    && stdout.is_some_and(|stdout| {
                        attempt.get("stdout_hash").and_then(Value::as_str)
                            == Some(raw_sha256(stdout.as_bytes()).as_str())
                    })
                    && stderr.is_some_and(|stderr| {
                        attempt.get("stderr_hash").and_then(Value::as_str)
                            == Some(raw_sha256(stderr.as_bytes()).as_str())
                    })
            })
        })
}

fn command_workspace_guard_current(receipt: &Value, check: &crate::config::CheckDef) -> bool {
    let Some(guard) = receipt.get("workspace_guard").and_then(Value::as_object) else {
        return false;
    };
    if check.effect != crate::config::ProcessEffect::ReadOnly {
        return guard.get("pre_hash").is_some_and(Value::is_null)
            && guard.get("post_hash").is_some_and(Value::is_null)
            && guard.get("unchanged").and_then(Value::as_bool) == Some(true);
    }
    let pre = guard.get("pre_hash").and_then(Value::as_str);
    let post = guard.get("post_hash").and_then(Value::as_str);
    pre.is_some()
        && pre == post
        && guard.get("unchanged").and_then(Value::as_bool) == Some(true)
        && guard
            .get("changed_paths")
            .and_then(Value::as_array)
            .is_some_and(Vec::is_empty)
        && receipt.get("status").and_then(Value::as_str) != Some("invalid_contract")
}

fn command_terminal_evidence_current(receipt: &Value, configured_expected: &[i32]) -> bool {
    let status = receipt.get("status").and_then(Value::as_str);
    let attempts = receipt.get("attempts").and_then(Value::as_array);
    let expected = if configured_expected.is_empty() {
        BTreeSet::from([0_i64])
    } else {
        configured_expected
            .iter()
            .map(|code| i64::from(*code))
            .collect()
    };
    match status {
        Some("interrupted" | "invalid_contract") | None => false,
        Some("timed_out") => attempts
            .and_then(|attempts| attempts.last())
            .is_some_and(|attempt| {
                attempt.get("timed_out").and_then(Value::as_bool) == Some(true)
                    && attempt.get("interrupted").and_then(Value::as_bool) == Some(false)
            }),
        Some("failed") => attempts
            .and_then(|attempts| attempts.last())
            .is_some_and(|attempt| {
                attempt.get("timed_out").and_then(Value::as_bool) == Some(false)
                    && attempt.get("interrupted").and_then(Value::as_bool) == Some(false)
            }),
        Some("passed" | "invalid_result") => attempts
            .and_then(|attempts| attempts.last())
            .is_some_and(|attempt| {
                let exit_code = attempt.get("exit_code").and_then(Value::as_i64);
                let infrastructure_failed = exit_code.is_some_and(|code| code != 0)
                    && command_infrastructure_failure(
                        attempt
                            .get("stdout")
                            .and_then(Value::as_str)
                            .unwrap_or_default(),
                        attempt
                            .get("stderr")
                            .and_then(Value::as_str)
                            .unwrap_or_default(),
                    )
                    .is_some();
                attempt.get("timed_out").and_then(Value::as_bool) == Some(false)
                    && attempt.get("interrupted").and_then(Value::as_bool) == Some(false)
                    && exit_code.is_some_and(|code| expected.contains(&code))
                    && !infrastructure_failed
            }),
        Some(_) => false,
    }
}

fn command_artifact_manifest_current(receipt: &Value, project_root: &Path) -> bool {
    let Some(recorded) = receipt.get("artifact_manifest").and_then(Value::as_object) else {
        return false;
    };
    let Some(expected_hash) = recorded.get("hash").and_then(Value::as_str) else {
        return false;
    };
    let mut recorded_without_hash = Value::Object(recorded.clone());
    recorded_without_hash
        .as_object_mut()
        .expect("artifact manifest object")
        .remove("hash");
    if normalized_hash(&recorded_without_hash) != expected_hash {
        return false;
    }
    let Some(rows) = recorded.get("artifacts").and_then(Value::as_array) else {
        return false;
    };
    let mut seen = BTreeSet::new();
    let mut current = Vec::new();
    for row in rows {
        let Some(path) = row.get("path").and_then(Value::as_str) else {
            return false;
        };
        if !seen.insert(path.to_owned()) {
            return false;
        }
        let Ok(artifact) = artifact_receipt(project_root, path) else {
            return false;
        };
        if !artifact.exists || artifact.error.is_some() {
            return false;
        }
        current.push(serde_json::to_value(artifact).expect("artifact receipt serializes"));
    }
    current.sort_by(|left, right| left["path"].as_str().cmp(&right["path"].as_str()));
    let mut current_manifest = json!({
        "schema_version": "1.0",
        "count": current.len(),
        "artifacts": current,
    });
    current_manifest["hash"] = Value::String(normalized_hash(&current_manifest));
    Value::Object(recorded.clone()) == current_manifest
}

fn command_result_source_current(
    receipt: &Value,
    project_root: &Path,
    check: &crate::config::CheckDef,
) -> bool {
    let manifest = receipt.get("result_source_manifest");
    if check.result_protocol.is_none() {
        return manifest.is_some_and(Value::is_null);
    }
    let status = receipt.get("status").and_then(Value::as_str);
    if manifest.is_some_and(Value::is_null) {
        return receipt.get("result_source").is_none_or(Value::is_null)
            && receipt.get("result").is_none_or(Value::is_null)
            && matches!(status, Some("failed" | "timed_out" | "invalid_result"));
    }
    let Some(manifest) = manifest.and_then(Value::as_object) else {
        return false;
    };
    let Some(expected_hash) = manifest.get("hash").and_then(Value::as_str) else {
        return false;
    };
    let mut without_hash = Value::Object(manifest.clone());
    without_hash
        .as_object_mut()
        .expect("result source manifest object")
        .remove("hash");
    if normalized_hash(&without_hash) != expected_hash {
        return false;
    }
    let Some(source) = manifest.get("source") else {
        return false;
    };
    if receipt.get("result_source") != Some(source) {
        return false;
    }
    let source_current = match source.get("kind").and_then(Value::as_str) {
        Some("stdout") => {
            let Some(stdout) = receipt
                .get("attempts")
                .and_then(Value::as_array)
                .and_then(|attempts| attempts.last())
                .and_then(|attempt| attempt.get("stdout"))
                .and_then(Value::as_str)
            else {
                return false;
            };
            let hash = raw_sha256(stdout.as_bytes());
            source.get("path").is_none_or(Value::is_null)
                && source.get("size_bytes").and_then(Value::as_u64) == Some(stdout.len() as u64)
                && source.get("sha256").and_then(Value::as_str) == Some(hash.as_str())
        }
        Some("file") => {
            let Some(path) = source.get("path").and_then(Value::as_str) else {
                return false;
            };
            let Ok(resolved) = contained_process_path(project_root, path) else {
                return false;
            };
            let Ok(bytes) = fs::read(resolved) else {
                return false;
            };
            let hash = raw_sha256(&bytes);
            !bytes.is_empty()
                && source.get("size_bytes").and_then(Value::as_u64) == Some(bytes.len() as u64)
                && source.get("sha256").and_then(Value::as_str) == Some(hash.as_str())
        }
        _ => false,
    };
    source_current
        && !matches!(
            status,
            Some("timed_out" | "interrupted" | "invalid_contract")
        )
}

fn command_dynamic_path_manifest_current(
    receipt: &Value,
    project_root: &Path,
    check: &crate::config::CheckDef,
    ticket: Option<&Ticket>,
    execution: Option<&ResolvedCheckExecution>,
) -> bool {
    let Some(execution) = execution else {
        return false;
    };
    if check.dynamic_result.is_none() {
        return true;
    };
    let Some(manifest) = receipt
        .get("dynamic_path_manifest")
        .and_then(Value::as_object)
    else {
        return false;
    };
    let Some(expected_hash) = manifest.get("hash").and_then(Value::as_str) else {
        return false;
    };
    let mut without_hash = Value::Object(manifest.clone());
    without_hash
        .as_object_mut()
        .expect("dynamic path manifest is an object")
        .remove("hash");
    if normalized_hash(&without_hash) != expected_hash {
        return false;
    }
    let Some(prestate) = receipt.get("dynamic_path_prestate") else {
        return false;
    };
    let Some(prestate_hash) = prestate.get("hash").and_then(Value::as_str) else {
        return false;
    };
    let mut prestate_without_hash = prestate.clone();
    let Some(prestate_object) = prestate_without_hash.as_object_mut() else {
        return false;
    };
    prestate_object.remove("hash");
    if normalized_hash(&prestate_without_hash) != prestate_hash {
        return false;
    }
    let Some(rows) = manifest.get("paths").and_then(Value::as_array) else {
        return false;
    };
    let has_path_authority = check
        .dynamic_result
        .as_ref()
        .is_some_and(|dynamic| dynamic.result_path.is_some() || dynamic.artifacts.is_some());
    if !has_path_authority {
        return rows.is_empty() && execution.result_path.is_none();
    }
    let Some(ticket) = ticket else {
        return false;
    };
    let mut seen = BTreeSet::new();
    for row in rows {
        let (Some(path), Some(authority), Some(provenance), Some(post_sha256)) = (
            row.get("path").and_then(Value::as_str),
            row.get("authority").and_then(Value::as_str),
            row.get("provenance").and_then(Value::as_str),
            row.get("post_sha256").and_then(Value::as_str),
        ) else {
            return false;
        };
        if !seen.insert(path.to_owned()) {
            return false;
        }
        let configured = check.dynamic_result.as_ref().is_some_and(|dynamic| {
            let result_authorities = dynamic
                .result_path
                .as_ref()
                .filter(|_| execution.result_path.as_deref() == Some(path))
                .into_iter()
                .flat_map(|path| &path.path_authorities);
            let artifact_authorities = dynamic
                .artifacts
                .as_ref()
                .into_iter()
                .flat_map(|artifacts| &artifacts.path_authorities);
            result_authorities
                .chain(artifact_authorities)
                .any(|allowed| {
                    serde_json::to_value(allowed.authority)
                        .ok()
                        .and_then(|value| value.as_str().map(|value| value == authority))
                        == Some(true)
                        && serde_json::to_value(allowed.provenance)
                            .ok()
                            .and_then(|value| value.as_str().map(|value| value == provenance))
                            == Some(true)
                })
        });
        if !configured {
            return false;
        }
        let Ok(current) = artifact_receipt(project_root, path) else {
            return false;
        };
        if !current.exists
            || current.error.is_some()
            || current.hash.as_deref() != Some(post_sha256)
        {
            return false;
        }
        let pre_sha256 = row.get("pre_sha256").and_then(Value::as_str);
        match (authority, provenance) {
            ("read_paths", "read_evidence") => {
                if !path_is_covered_by_ticket_scope(path, &ticket.scope.read_paths)
                    || pre_sha256 != Some(post_sha256)
                    || path_manifest_sha256(&execution.read_path_manifest, path)
                        != Some(post_sha256)
                {
                    return false;
                }
            }
            ("write_paths", "produced_output") => {
                if !path_is_covered_by_ticket_scope(path, &ticket.scope.write_paths)
                    || pre_sha256 == Some(post_sha256)
                    || dynamic_prestate_sha256(prestate, path) != pre_sha256
                {
                    return false;
                }
            }
            _ => return false,
        }
    }
    if let Some(path) = execution.result_path.as_deref()
        && !seen.contains(path)
    {
        return false;
    }
    receipt
        .get("result_validation")
        .and_then(|validation| validation.get("dynamic_artifacts"))
        .and_then(|artifacts| artifacts.get("declared_paths"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .all(|path| seen.contains(path))
}

fn validate_argv_input_bindings(
    bindings: Option<&crate::config::ArgvInputBindingsDef>,
    candidate: &Value,
    argv: &[String],
    project_root: &Path,
    variables: &BTreeMap<String, String>,
) -> Result<()> {
    let Some(bindings) = bindings else {
        return Ok(());
    };
    let inputs = lookup_dynamic_path(candidate, &bindings.from, variables)
        .and_then(Value::as_array)
        .ok_or_else(|| {
            KoniError::Action(format!(
                "argv input binding source {} is not an array",
                bindings.from
            ))
        })?;
    if bindings.require_nonempty && inputs.is_empty() {
        return Err(KoniError::Action(format!(
            "argv input binding source {} must not be empty",
            bindings.from
        )));
    }
    let canonical_root = project_root
        .canonicalize()
        .map_err(|error| io_error(project_root, error))?;
    let mut errors = Vec::new();
    for (index, input) in inputs.iter().enumerate() {
        for field in &bindings.required_fields {
            if lookup_dynamic_path(input, field, variables).is_none_or(value_is_empty) {
                errors.push(format!("argv input {index} requires field {field}"));
            }
        }
        let path = lookup_dynamic_path(input, &bindings.path_field, variables)
            .and_then(Value::as_str)
            .unwrap_or_default();
        if path.is_empty() {
            errors.push(format!(
                "argv input {index} requires string path field {}",
                bindings.path_field
            ));
            continue;
        }
        if bindings.require_project_file {
            let relative = Path::new(path);
            let joined = match contained_join(project_root, relative) {
                Ok(joined) => joined,
                Err(_) => {
                    errors.push(format!(
                        "argv input {index} escapes the project root: {path}"
                    ));
                    continue;
                }
            };
            match joined.canonicalize() {
                Ok(canonical) if canonical.starts_with(&canonical_root) && canonical.is_file() => {}
                Ok(_) => errors.push(format!("argv input {index} is not a project file: {path}")),
                Err(_) => errors.push(format!("argv input {index} path does not exist: {path}")),
            }
        }
        if bindings.require_exact_argument && !argv.iter().any(|argument| argument == path) {
            errors.push(format!(
                "argv input {index} is not bound as an exact command argument: {path}"
            ));
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(KoniError::Action(errors.join("; ")))
    }
}

