    fn commit_read_scope_fixture(root: &Path, message: &str) -> String {
        let repository = git2::Repository::open(root).unwrap();
        let mut index = repository.index().unwrap();
        index
            .add_all(["*"], git2::IndexAddOption::DEFAULT, None)
            .unwrap();
        index.write().unwrap();
        let tree_id = index.write_tree().unwrap();
        let tree = repository.find_tree(tree_id).unwrap();
        let parent = repository.head().unwrap().peel_to_commit().unwrap();
        let signature = git2::Signature::now("Koni Test", "koni@example.local").unwrap();
        repository
            .commit(
                Some("HEAD"),
                &signature,
                &signature,
                message,
                &tree,
                &[&parent],
            )
            .unwrap()
            .to_string()
    }

    fn read_scope_steer_params(
        kind: &str,
        ticket_id: &str,
        message: String,
        target_nodes: &[&str],
        priority: &str,
    ) -> BTreeMap<String, String> {
        BTreeMap::from([
            ("kind".to_owned(), kind.to_owned()),
            ("ticket".to_owned(), ticket_id.to_owned()),
            ("message".to_owned(), message),
            (
                "target_nodes".to_owned(),
                serde_json::to_string(target_nodes).unwrap(),
            ),
            ("priority".to_owned(), priority.to_owned()),
        ])
    }

