    fn read_scope_repair_request(fixture: &ReadScopeRecoveryFixture) -> ReadScopeReplanRequest {
        ReadScopeReplanRequest {
            schema_version: "1.0".to_owned(),
            ticket_id: fixture.ticket_id.clone(),
            step_id: "author-historical-baseline".to_owned(),
            path: "src/seam.ts".to_owned(),
            source_node_id: fixture.system_id.clone(),
            source_field: "owned_paths".to_owned(),
            amend_node_id: fixture.proof_id.clone(),
            amend_field: "covered_paths".to_owned(),
            review_id: fixture.review_id.clone(),
            correction_event_id: fixture.correction.id.clone(),
            correction_event_hash: normalized_hash(&fixture.correction),
            reason:
                "The invoked production seam must be semantic proof authority before recompilation."
                    .to_owned(),
        }
    }

    fn execute_read_scope_repair(fixture: &mut ReadScopeRecoveryFixture, priority: &str) -> Value {
        let request = read_scope_repair_request(fixture);
        fixture
            .engine
            .execute_action(
                "steer",
                read_scope_steer_params(
                    READ_SCOPE_REPLAN_KIND,
                    &fixture.ticket_id,
                    serde_json::to_string(&request).unwrap(),
                    &[&fixture.system_id, &fixture.proof_id],
                    priority,
                ),
            )
            .unwrap()
    }

    fn read_scope_rebind_request(fixture: &ReadScopeRecoveryFixture) -> ReadScopeRebindRequest {
        let repair = read_scope_repair_request(fixture);
        let binding = read_scope_replan_binding(
            &fixture.store.ticket(&fixture.ticket_id).unwrap(),
            &normalized_hash(&repair),
        )
        .unwrap()
        .unwrap();
        ReadScopeRebindRequest {
            schema_version: "1.0".to_owned(),
            ticket_id: fixture.ticket_id.clone(),
            blocker_request_hash: binding.request_hash,
            blocker_binding_hash: binding.binding_hash,
        }
    }

    fn execute_read_scope_rebind(fixture: &mut ReadScopeRecoveryFixture, priority: &str) -> Value {
        let request = read_scope_rebind_request(fixture);
        fixture
            .engine
            .execute_action(
                "steer",
                read_scope_steer_params(
                    READ_SCOPE_REBIND_KIND,
                    &fixture.ticket_id,
                    serde_json::to_string(&request).unwrap(),
                    &[&fixture.proof_id],
                    priority,
                ),
            )
            .unwrap()
    }

    fn prepare_read_scope_rebind_without_publication(
        fixture: &ReadScopeRecoveryFixture,
    ) -> (ReadScopeRebindRequest, Event, ReadScopeRebindTransaction) {
        let request = read_scope_rebind_request(fixture);
        let journal_id = format!("journal-rebind-{}", Uuid::now_v7());
        let mut event = Event::new(
            &fixture.run.id,
            "compiler.steering.recorded",
            Some(fixture.ticket_id.clone()),
            json!({
                "kind": READ_SCOPE_REBIND_KIND,
                "message": serde_json::to_string(&request).unwrap(),
                "ticket_id": fixture.ticket_id,
                "target_nodes": [fixture.proof_id],
                "priority": "normal",
                "compiler_transaction_action": "steer",
                "compiler_transaction_journal": journal_id,
            }),
        );
        event.actor = "lead".to_owned();
        let (request_hash, blocker) = fixture
            .engine
            .validate_read_scope_rebind_event(&fixture.store, &fixture.run, &event)
            .unwrap();
        fixture.store.append_event(&event).unwrap();
        fixture
            .store
            .write_journal(&Journal {
                id: journal_id,
                action: "steer".to_owned(),
                input_hash: Some(normalized_hash(&request)),
                status: JournalStatus::Complete,
                started_at: event.at,
                profile_hash: fixture.engine.profile.hash.clone(),
                completed_steps: vec![0, 1, 2],
                outputs: BTreeMap::new(),
                error: None,
            })
            .unwrap();
        let transaction = fixture
            .engine
            .prepare_read_scope_rebind_transaction(
                &fixture.store,
                &fixture.run,
                &event,
                &request_hash,
                &blocker,
            )
            .unwrap();
        let path = read_scope_rebind_transaction_path(&fixture.store, &request_hash).unwrap();
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        atomic_write_yaml(&path, &transaction).unwrap();
        (request, event, transaction)
    }

    #[test]
    fn read_scope_rebind_recompiles_exact_authority_and_replays_after_progress() {
        let mut fixture = read_scope_recovery_fixture();
        let original = fixture.store.ticket(&fixture.ticket_id).unwrap();
        let original_lease_hash = normalized_hash(&original.lease);
        let original_reviews_hash = normalized_hash(&original.reviews);
        let original_outputs_hash = normalized_hash(&original.outputs);
        let original_write_scope = original.scope.write_paths.clone();
        let original_steps = original
            .workflow
            .iter()
            .map(|step| {
                (
                    step.id.clone(),
                    (
                        effective_step_read_paths(&original, step).clone(),
                        effective_step_write_paths(&original, step).clone(),
                        step.context_hash.clone(),
                        step.compiled_check_sets.clone(),
                    ),
                )
            })
            .collect::<BTreeMap<_, _>>();
        assert!(!original.scope.read_paths.contains("src/seam.ts"));

        execute_read_scope_repair(&mut fixture, "normal");
        let blocked = fixture.store.ticket(&fixture.ticket_id).unwrap();
        assert_eq!(blocked.status, "blocked");
        assert_eq!(blocked.scope, original.scope);
        assert_eq!(normalized_hash(&blocked.lease), original_lease_hash);
        let repair = read_scope_repair_request(&fixture);
        let binding = read_scope_replan_binding(&blocked, &normalized_hash(&repair))
            .unwrap()
            .unwrap();
        assert_eq!(
            binding.base_graph_hash,
            fixture.store.graph().unwrap().normalized_hash()
        );
        assert_eq!(
            (binding.lease_branch_ref.clone(), binding.lease_head.clone()),
            read_scope_rebind_clean_lease_binding(&fixture.engine.profile, &blocked).unwrap()
        );

        let rebind = read_scope_rebind_request(&fixture);
        execute_read_scope_rebind(&mut fixture, "normal");
        let rebound = fixture.store.ticket(&fixture.ticket_id).unwrap();
        assert_eq!(rebound.status, "in_progress");
        assert!(rebound.scope.read_paths.contains("src/seam.ts"));
        assert!(!rebound.scope.read_paths.contains("src/unrelated-owned.ts"));
        assert_eq!(rebound.scope.write_paths, original_write_scope);
        assert_eq!(normalized_hash(&rebound.lease), original_lease_hash);
        assert_eq!(normalized_hash(&rebound.reviews), original_reviews_hash);
        assert_eq!(normalized_hash(&rebound.outputs), original_outputs_hash);
        assert!(rebound.blockers.is_empty());
        assert!(!rebound.extensions.contains_key("issued_context_hash"));
        assert!(!rebound.extensions.contains_key("issued_context_hashes"));

        for step in &rebound.workflow {
            let (before_reads, before_writes, before_context, before_sets) =
                &original_steps[&step.id];
            assert_eq!(
                effective_step_write_paths(&rebound, step),
                before_writes,
                "{} retained exact write authority",
                step.id
            );
            let inputs_changed = before_reads != effective_step_read_paths(&rebound, step)
                || before_sets != &step.compiled_check_sets;
            assert_eq!(
                before_context != &step.context_hash,
                inputs_changed,
                "{} context identity follows its exact compiled inputs",
                step.id
            );
            assert!(
                !effective_step_read_paths(&rebound, step).contains("src/unrelated-owned.ts"),
                "{} must not inherit unrelated linked-system ownership",
                step.id
            );
        }
        let author = rebound
            .workflow
            .iter()
            .find(|step| step.id == "author-historical-baseline")
            .unwrap();
        let member = author
            .compiled_check_sets
            .iter()
            .flat_map(|set| &set.members)
            .find(|member| member.source_node_id == fixture.proof_id)
            .unwrap();
        assert!(member.covered_paths.contains("src/seam.ts"));
        assert!(!member.covered_paths.contains("src/unrelated-owned.ts"));

        let graph = fixture.store.graph().unwrap();
        assert!(
            graph.node(&fixture.proof_id).unwrap().spec["covered_paths"]
                .as_array()
                .unwrap()
                .contains(&json!("src/seam.ts"))
        );
        let transaction = read_scope_rebind_transaction(&fixture.store, &normalized_hash(&rebind))
            .unwrap()
            .unwrap();
        assert_eq!(transaction.status, "complete");
        assert!(transaction.completed_at.is_some());
        assert!(scoped_compile_receipt_is_current(
            &fixture.engine.profile,
            &rebound,
            &transaction.receipt,
            &graph,
            rebound.lease.as_ref().unwrap().worktree.as_path(),
        ));
        assert_eq!(
            fixture
                .store
                .events()
                .unwrap()
                .iter()
                .filter(|event| event.event_type == READ_SCOPE_REBIND_EVENT_TYPE)
                .count(),
            1
        );

        let ticket_id_shaped = BTreeMap::from([
            ("kind".to_owned(), json!(READ_SCOPE_REBIND_KIND)),
            ("ticket_id".to_owned(), json!(fixture.ticket_id)),
            (
                "message".to_owned(),
                json!(serde_json::to_string(&rebind).unwrap()),
            ),
            ("target_nodes".to_owned(), json!([fixture.proof_id])),
            ("priority".to_owned(), json!("normal")),
        ]);
        assert_eq!(
            fixture
                .engine
                .completed_read_scope_action_replay(
                    &fixture.store,
                    &fixture.store.manifest().unwrap(),
                    &ticket_id_shaped,
                )
                .unwrap()
                .unwrap()["status"],
            "already_rebound"
        );

        // Legitimate repository and lifecycle progress cannot turn a sealed
        // historical retry into a fresh authority check. Removing the current
        // ticket proves the early action path does not consult mutable state.
        let progress = fixture.engine.root.join("docs/progress.md");
        fs::create_dir_all(progress.parent().unwrap()).unwrap();
        fs::write(&progress, "later legitimate progress\n").unwrap();
        commit_read_scope_fixture(&fixture.engine.root, "test: subsequent progress");
        let ticket_path = read_scope_rebind_ticket_copies(&fixture.store, &fixture.ticket_id)
            .unwrap()
            .pop()
            .unwrap()
            .0;
        fs::remove_file(ticket_path).unwrap();
        let mut concluded = fixture.store.manifest().unwrap();
        concluded.status = "concluded".to_owned();
        fixture.store.write_manifest(&concluded).unwrap();

        let repair_replay = fixture
            .engine
            .execute_action(
                "steer",
                read_scope_steer_params(
                    READ_SCOPE_REPLAN_KIND,
                    &fixture.ticket_id,
                    serde_json::to_string(&repair).unwrap(),
                    &[&fixture.system_id, &fixture.proof_id],
                    "high",
                ),
            )
            .unwrap();
        assert_eq!(repair_replay["status"], "already_rebound");
        let rebind_replay = fixture
            .engine
            .execute_action(
                "steer",
                read_scope_steer_params(
                    READ_SCOPE_REBIND_KIND,
                    &fixture.ticket_id,
                    serde_json::to_string(&rebind).unwrap(),
                    &[&fixture.proof_id],
                    "high",
                ),
            )
            .unwrap();
        assert_eq!(rebind_replay["status"], "already_rebound");
        assert_eq!(
            read_scope_rebind_transactions(&fixture.store)
                .unwrap()
                .len(),
            1
        );
    }

