    #[test]
    fn read_scope_rebind_lane_midpoint_is_quarantined_until_recovery() {
        let mut fixture = read_scope_recovery_fixture();
        execute_read_scope_repair(&mut fixture, "normal");
        let (request, _event, transaction) =
            prepare_read_scope_rebind_without_publication(&fixture);

        let compile_error = fixture.engine.compile(None, false).unwrap_err().to_string();
        assert!(
            compile_error.contains("unfinished read-scope rebind"),
            "{compile_error}"
        );

        let mut graph = fixture.store.graph().unwrap();
        graph.upsert(transaction.amended_node.clone());
        graph
            .save_node(&fixture.store.graph_dir(), &transaction.amended_node.id)
            .unwrap();
        atomic_write_yaml(
            &fixture
                .store
                .receipts_dir()
                .join(format!("{}.yaml", transaction.receipt_id)),
            &transaction.receipt,
        )
        .unwrap();
        let source = fixture
            .store
            .tickets_dir()
            .join("blocked")
            .join(format!("{}.yaml", fixture.ticket_id));
        let target = fixture
            .store
            .tickets_dir()
            .join("in_progress")
            .join(format!("{}.yaml", fixture.ticket_id));
        fs::create_dir_all(target.parent().unwrap()).unwrap();
        fs::rename(&source, &target).unwrap();
        assert_eq!(
            read_scope_rebind_ticket_copies(&fixture.store, &fixture.ticket_id)
                .unwrap()
                .len(),
            1
        );

        let action_error = fixture
            .engine
            .execute_action("report", BTreeMap::new())
            .unwrap_err()
            .to_string();
        assert!(
            action_error.contains("unfinished read-scope rebind"),
            "{action_error}"
        );
        fixture
            .engine
            .execute_action("recover", BTreeMap::new())
            .unwrap();
        let rebound = fixture.store.ticket(&fixture.ticket_id).unwrap();
        assert_eq!(rebound.status, "in_progress");
        assert!(rebound.scope.read_paths.contains("src/seam.ts"));
        let completed = read_scope_rebind_transaction(&fixture.store, &normalized_hash(&request))
            .unwrap()
            .unwrap();
        assert_eq!(completed.status, "complete");
        assert!(completed.completed_at.is_some());
        ensure_global_read_only_quarantine_clear(
            &fixture.engine.root,
            &fixture.engine.profile,
            &fixture.store,
        )
        .unwrap();
    }

