    #[test]
    fn read_scope_rebind_candidate_rejects_extra_read_write_and_member_deltas() {
        let mut fixture = read_scope_recovery_fixture();
        execute_read_scope_repair(&mut fixture, "normal");
        let (_request, _event, transaction) =
            prepare_read_scope_rebind_without_publication(&fixture);
        let blocked = fixture.store.ticket(&fixture.ticket_id).unwrap();
        let mut candidate = transaction.rebound_ticket.clone();
        candidate.extensions = [
            "phase",
            "operation_registry_id",
            "workflow_id",
            "dispatch_priority",
            "ranking_hints",
            "rule_anchor_node_id",
            "review_failure_reopen_from",
            REVIEW_FAILURE_ROUTES_EXTENSION,
            PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION,
        ]
        .into_iter()
        .filter_map(|key| {
            blocked
                .extensions
                .get(key)
                .cloned()
                .map(|value| (key.to_owned(), value))
        })
        .collect();
        let repair = read_scope_repair_request(&fixture);
        let binding = read_scope_replan_binding(&blocked, &normalized_hash(&repair))
            .unwrap()
            .unwrap();
        validate_read_scope_rebind_candidate(
            &fixture.engine.profile,
            &blocked,
            &candidate,
            &binding,
            &transaction.base_node,
            &transaction.amended_node,
        )
        .unwrap();

        let mut added_write = candidate.clone();
        added_write
            .scope
            .write_paths
            .insert("src/unauthorized-write.ts".to_owned());
        assert!(
            validate_read_scope_rebind_candidate(
                &fixture.engine.profile,
                &blocked,
                &added_write,
                &binding,
                &transaction.base_node,
                &transaction.amended_node,
            )
            .unwrap_err()
            .to_string()
            .contains("write authority")
        );

        let mut added_read = candidate.clone();
        added_read
            .scope
            .read_paths
            .insert("src/unrelated-read.ts".to_owned());
        assert!(
            validate_read_scope_rebind_candidate(
                &fixture.engine.profile,
                &blocked,
                &added_read,
                &binding,
                &transaction.base_node,
                &transaction.amended_node,
            )
            .unwrap_err()
            .to_string()
            .contains("only src/seam.ts is permitted")
        );

        let mut changed_member = candidate;
        changed_member
            .workflow
            .iter_mut()
            .flat_map(|step| &mut step.compiled_check_sets)
            .flat_map(|set| &mut set.members)
            .find(|member| member.source_node_id == fixture.proof_id)
            .unwrap()
            .source_paths
            .insert("tests/unrelated-proof.ts".to_owned());
        assert!(
            validate_read_scope_rebind_candidate(
                &fixture.engine.profile,
                &blocked,
                &changed_member,
                &binding,
                &transaction.base_node,
                &transaction.amended_node,
            )
            .unwrap_err()
            .to_string()
            .contains("source authority")
        );
    }

