    #[test]
    fn workflow_step_graph_mutation_policy_is_compiler_enforced() {
        let step = |policy| {
            serde_json::from_value::<Step>(json!({
                "id": "analyze",
                "persona": "analyst",
                "graph_mutation": policy,
                "context_hash": "sha256:context"
            }))
            .unwrap()
        };
        let empty = json!({"graph_delta": {"add_nodes": [], "add_edges": []}});
        let material = json!({"graph_delta": {"add_nodes": [{"id": "node"}]}});

        validate_step_graph_mutation_policy(&step("forbidden"), &json!({})).unwrap();
        validate_step_graph_mutation_policy(&step("forbidden"), &empty).unwrap();
        assert!(
            validate_step_graph_mutation_policy(&step("forbidden"), &material)
                .unwrap_err()
                .to_string()
                .contains("forbids graph mutation")
        );
        assert!(
            validate_step_graph_mutation_policy(&step("required"), &empty)
                .unwrap_err()
                .to_string()
                .contains("requires a nonempty graph_delta")
        );
        validate_step_graph_mutation_policy(&step("required"), &material).unwrap();
        validate_step_graph_mutation_policy(&step("allowed"), &material).unwrap();
    }

    #[test]
    fn workflow_step_scope_is_narrow_and_legacy_compatible() {
        let ticket = Ticket {
            schema_version: "1.0".to_owned(),
            id: "TK-step-scope".to_owned(),
            operation: "implement-change".to_owned(),
            status: "in_progress".to_owned(),
            title: "Bound red and green edits".to_owned(),
            target_nodes: Vec::new(),
            scope: Scope {
                read_nodes: BTreeSet::from(["change".to_owned(), "proof".to_owned()]),
                write_nodes: BTreeSet::from(["change".to_owned(), "proof".to_owned()]),
                read_paths: BTreeSet::from(["src".to_owned(), "tests".to_owned()]),
                write_paths: BTreeSet::from(["src".to_owned(), "tests".to_owned()]),
            },
            source_state_key: "planned".to_owned(),
            target_state_key: "implemented".to_owned(),
            obligation_keys: Vec::new(),
            profile_hash: "sha256:profile".to_owned(),
            rule_id: "change.implement".to_owned(),
            workflow: Vec::new(),
            outputs: Vec::new(),
            reviews: Vec::new(),
            blockers: Vec::new(),
            lease: None,
            change_control: TicketChangeControl::default(),
            extensions: BTreeMap::new(),
        };
        let red_step = serde_json::from_value::<Step>(json!({
            "id": "write-red-test",
            "persona": "implementer",
            "read_nodes": ["change", "proof"],
            "write_nodes": ["proof"],
            "read_paths": ["src", "tests"],
            "write_paths": ["tests"],
            "context_hash": "sha256:red"
        }))
        .unwrap();
        let implementation_step = serde_json::from_value::<Step>(json!({
            "id": "implement",
            "persona": "implementer",
            "read_paths": ["src", "tests"],
            "write_paths": ["src"],
            "context_hash": "sha256:implement"
        }))
        .unwrap();
        let legacy_step = serde_json::from_value::<Step>(json!({
            "id": "legacy",
            "persona": "implementer",
            "context_hash": "sha256:legacy"
        }))
        .unwrap();

        assert_eq!(
            effective_step_write_paths(&ticket, &red_step),
            &BTreeSet::from(["tests".to_owned()])
        );
        assert_eq!(
            effective_step_write_paths(&ticket, &implementation_step),
            &BTreeSet::from(["src".to_owned()])
        );
        assert_eq!(
            effective_step_write_paths(&ticket, &legacy_step),
            &ticket.scope.write_paths
        );
        let scoped = ticket_with_step_scope(&ticket, &red_step);
        assert_eq!(scoped.scope.read_nodes, ticket.scope.read_nodes);
        assert_eq!(
            scoped.scope.write_nodes,
            BTreeSet::from(["proof".to_owned()])
        );
        assert_eq!(scoped.scope.read_paths, ticket.scope.read_paths);
        assert_eq!(
            scoped.scope.write_paths,
            BTreeSet::from(["tests".to_owned()])
        );
    }

    #[test]
    fn graph_validation_enforces_each_nested_list_subset_before_dispatch() {
        let mut profile = compiled_updog_profile();
        let definition: crate::config::NodeTypeDef = serde_json::from_value(json!({
            "id": "subset-fixture",
            "description": "Exercises generic recursive field containment.",
            "statuses": ["active"],
            "fields": {
                "covered_paths": {
                    "type": "list",
                    "required": true,
                    "items": {"type": "path"}
                },
                "oracle_cases": {
                    "type": "list",
                    "required": true,
                    "unique_by": "id",
                    "items": {
                        "type": "object",
                        "additional_properties": false,
                        "properties": {
                            "id": {
                                "type": "string",
                                "required": true
                            },
                            "seam_paths": {
                                "type": "list",
                                "required": true,
                                "items": {"type": "path"},
                                "subset_of": "spec.covered_paths"
                            }
                        }
                    }
                }
            }
        }))
        .unwrap();
        profile.node_types.insert(definition.id.clone(), definition);
        let temp = tempfile::tempdir().unwrap();
        let store =
            StateStore::with_storage(temp.path().join("run"), &profile.manifest.storage).unwrap();
        store.ensure_layout().unwrap();
        let engine = Engine {
            root: temp.path().to_path_buf(),
            profile,
            store: Some(store),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let node = |oracle_cases| {
            let mut node = Node::new(
                "subset-fixture",
                "Nested subset fixture",
                json!({
                    "covered_paths": ["src/consumer.tsx", "src/shared.ts"],
                    "oracle_cases": oracle_cases
                }),
            );
            node.id = "ND-subset-fixture".to_owned();
            node
        };

        let mut valid = Graph::default();
        valid
            .insert(node(json!([
                {"id": "consumer", "seam_paths": ["src/./consumer.tsx"]},
                {"id": "shared", "seam_paths": ["src/shared.ts"]}
            ])))
            .unwrap();
        assert!(engine.validate_graph(&valid).unwrap().is_empty());

        let mut invalid = Graph::default();
        invalid
            .insert(node(json!([
                {"id": "consumer", "seam_paths": ["src/consumer.tsx"]},
                {"id": "uncovered", "seam_paths": ["src/uncovered.tsx"]}
            ])))
            .unwrap();
        let errors = engine.validate_graph(&invalid).unwrap();
        assert_eq!(
            errors
                .iter()
                .filter(|error| error.contains("must be a subset"))
                .count(),
            1,
            "{errors:#?}"
        );
        let error = errors
            .iter()
            .find(|error| error.contains("must be a subset"))
            .unwrap();
        assert!(error.contains("node ND-subset-fixture"), "{error}");
        assert!(
            error.contains("field oracle_cases[1].seam_paths"),
            "{error}"
        );
        assert!(error.contains("root field spec.covered_paths"), "{error}");
        assert!(
            error.contains("missing normalized paths [\"src/uncovered.tsx\"]"),
            "{error}"
        );
    }

    #[test]
    fn string_list_subset_uses_exact_identity_without_echoing_missing_values() {
        let definition: crate::config::FieldDef = serde_json::from_value(json!({
            "type": "list",
            "items": {"type": "string"},
            "subset_of": "spec.allowed_labels"
        }))
        .unwrap();
        let node = Node::new(
            "subset-fixture",
            "String subset fixture",
            json!({"allowed_labels": ["Exact Label"]}),
        );
        let mut valid_errors = Vec::new();
        validate_field_value(
            &node,
            "cases[0].labels",
            &definition,
            &json!(["Exact Label"]),
            &Graph::default(),
            Path::new("."),
            &mut valid_errors,
        );
        assert!(valid_errors.is_empty(), "{valid_errors:#?}");

        let mut invalid_errors = Vec::new();
        validate_field_value(
            &node,
            "cases[1].labels",
            &definition,
            &json!(["exact label"]),
            &Graph::default(),
            Path::new("."),
            &mut invalid_errors,
        );
        assert_eq!(invalid_errors.len(), 1, "{invalid_errors:#?}");
        let error = &invalid_errors[0];
        assert!(error.contains("field cases[1].labels"), "{error}");
        assert!(error.contains("root field spec.allowed_labels"), "{error}");
        assert!(error.contains("1 value(s) are not present"), "{error}");
        assert!(!error.contains("Exact Label"), "{error}");
        assert!(!error.contains("exact label"), "{error}");
    }

    #[test]
    fn path_list_disjointness_rejects_equality_and_both_authority_directions() {
        let definition: crate::config::FieldDef = serde_json::from_value(json!({
            "type": "list",
            "items": {"type": "path"},
            "disjoint_from": "spec.covered_paths"
        }))
        .unwrap();
        let node = Node::new(
            "disjoint-fixture",
            "Path disjointness fixture",
            json!({"covered_paths": ["src/product/button.tsx"]}),
        );

        for source_path in [
            "src/product/button.tsx",
            "src/product",
            "src/product/button.tsx/fixture",
        ] {
            let mut errors = Vec::new();
            validate_field_value(
                &node,
                "source_paths",
                &definition,
                &json!([source_path]),
                &Graph::default(),
                Path::new("."),
                &mut errors,
            );
            assert_eq!(errors.len(), 1, "{source_path}: {errors:#?}");
            assert!(
                errors[0].contains("must be disjoint from root field spec.covered_paths"),
                "{source_path}: {}",
                errors[0]
            );
            assert!(
                errors[0].contains(&format!("[\"{source_path}\"]")),
                "{source_path}: {}",
                errors[0]
            );
        }

        let mut valid_errors = Vec::new();
        validate_field_value(
            &node,
            "source_paths",
            &definition,
            &json!(["tests/button.test.tsx"]),
            &Graph::default(),
            Path::new("."),
            &mut valid_errors,
        );
        assert!(valid_errors.is_empty(), "{valid_errors:#?}");
    }

    #[test]
    fn filesystem_authority_identity_rejects_aliases_without_weakening_existing_distinct_paths() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path();
        fs::create_dir_all(root.join("Existing")).unwrap();
        fs::write(root.join("Existing/original.txt"), b"original\n").unwrap();
        fs::hard_link(
            root.join("Existing/original.txt"),
            root.join("Existing/hard-link.txt"),
        )
        .unwrap();

        assert!(
            project_authority_paths_equal(root, "Existing/original.txt", "Existing/hard-link.txt",)
                .unwrap(),
            "existing hard links are one filesystem authority identity"
        );
        assert!(
            project_authority_paths_overlap(
                root,
                "Existing/New/Proof.txt",
                "Existing/new/proof.txt",
            )
            .unwrap(),
            "unresolved case aliases below one existing directory fail closed"
        );
        assert!(
            project_authority_paths_overlap(
                root,
                "Future/Caf\u{e9}/Proof.txt",
                "future/cafe\u{301}/proof.txt",
            )
            .unwrap(),
            "fully unresolved case and Unicode-normalization aliases fail closed"
        );
        assert!(
            !project_authority_paths_equal(root, "Future/Proof.txt", "future/proof.txt").unwrap(),
            "conservative unresolved overlap must never grant exact-path authority"
        );

        fs::write(root.join("CasePath"), b"upper\n").unwrap();
        fs::write(root.join("casepath"), b"lower\n").unwrap();
        if !same_file::is_same_file(root.join("CasePath"), root.join("casepath")).unwrap() {
            assert!(
                !project_authority_paths_overlap(root, "CasePath", "casepath").unwrap(),
                "distinct existing case-sensitive files remain distinct"
            );
        }

        let alternate_case = root.join("existing/original.txt");
        if alternate_case.exists() {
            assert!(
                project_authority_paths_equal(
                    root,
                    "Existing/original.txt",
                    "existing/original.txt",
                )
                .unwrap(),
                "case-insensitive existing aliases resolve through filesystem identity"
            );
            assert!(
                project_authority_paths_overlap(
                    root,
                    "Existing/Missing/Child.txt",
                    "existing/missing/child.txt",
                )
                .unwrap(),
                "missing descendants inherit the identity of an aliased existing parent"
            );
        }

        let composed = "Existing/caf\u{e9}.txt";
        let decomposed = "Existing/cafe\u{301}.txt";
        fs::write(root.join(composed), b"unicode\n").unwrap();
        if root.join(decomposed).exists() {
            assert!(
                project_authority_paths_equal(root, composed, decomposed).unwrap(),
                "normalization-insensitive existing aliases resolve through filesystem identity"
            );
        }
    }

