    #[cfg(unix)]
    #[test]
    fn relocation_untracked_path_allows_only_disjoint_tracked_symlink_targets() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path();
        fs::create_dir_all(root.join(".agents/skills")).unwrap();
        fs::create_dir_all(root.join(".claude")).unwrap();
        fs::create_dir_all(root.join("apps/books")).unwrap();
        fs::create_dir_all(root.join("Tests")).unwrap();
        fs::write(root.join("README.md"), "tracked\n").unwrap();
        std::os::unix::fs::symlink("../.agents/skills", root.join(".claude/skills")).unwrap();
        std::os::unix::fs::symlink("../.agents/skills", root.join("Tests/Alias")).unwrap();
        std::os::unix::fs::symlink("../.agents/skills", root.join("Tests/Caf\u{e9}")).unwrap();

        let repository = git2::Repository::init(root).unwrap();
        let mut index = repository.index().unwrap();
        index.add_path(Path::new("README.md")).unwrap();
        index.add_path(Path::new(".claude/skills")).unwrap();
        index.add_path(Path::new("Tests/Alias")).unwrap();
        index.add_path(Path::new("Tests/Caf\u{e9}")).unwrap();
        index.write().unwrap();
        assert_eq!(
            index.get_path(Path::new(".claude/skills"), 0).unwrap().mode,
            0o120000
        );
        let tree_id = index.write_tree().unwrap();
        let tree = repository.find_tree(tree_id).unwrap();
        let signature = git2::Signature::now("Koni Test", "koni-test@example.local").unwrap();
        let initial = repository
            .commit(Some("HEAD"), &signature, &signature, "initial", &tree, &[])
            .unwrap();
        drop(tree);
        fs::remove_file(root.join("Tests/Alias")).unwrap();
        fs::remove_file(root.join("Tests/Caf\u{e9}")).unwrap();

        ensure_planned_proof_source_relocation_path_untracked(root, "apps/books/focused.test.tsx")
            .expect("an unrelated project-contained compatibility symlink is safe");
        for alias in ["tests/alias/proof.tsx", "tests/cafe\u{301}/proof.tsx"] {
            let error = ensure_planned_proof_source_relocation_path_untracked(root, alias)
                .expect_err("an omitted tracked symlink pathname alias must fail closed")
                .to_string();
            assert!(
                error.contains("ambiguously overlaps tracked Git symlink"),
                "{alias}: {error}"
            );
        }
        let exact = ensure_planned_proof_source_relocation_path_untracked(root, "README.md")
            .expect_err("an ordinary tracked path remains unavailable")
            .to_string();
        assert!(
            exact.contains("tracked Git index entry README.md"),
            "{exact}"
        );

        std::os::unix::fs::symlink("../apps/books", root.join(".claude/proof-alias")).unwrap();
        let mut index = repository.index().unwrap();
        index.add_path(Path::new(".claude/proof-alias")).unwrap();
        index.write().unwrap();
        let index_alias = ensure_planned_proof_source_relocation_path_untracked(
            root,
            "apps/books/focused.test.tsx",
        )
        .expect_err("an index symlink to the proposed source parent must fail closed")
        .to_string();
        assert!(
            index_alias.contains("aliases tracked Git symlink"),
            "{index_alias}"
        );

        let tree_id = index.write_tree().unwrap();
        let tree = repository.find_tree(tree_id).unwrap();
        let parent = repository.find_commit(initial).unwrap();
        repository
            .commit(
                Some("HEAD"),
                &signature,
                &signature,
                "tracked alias",
                &tree,
                &[&parent],
            )
            .unwrap();
        drop(tree);
        let mut index = repository.index().unwrap();
        index.remove_path(Path::new(".claude/proof-alias")).unwrap();
        index.write().unwrap();
        fs::remove_file(root.join(".claude/proof-alias")).unwrap();
        let head_alias = ensure_planned_proof_source_relocation_path_untracked(
            root,
            "apps/books/focused.test.tsx",
        )
        .expect_err("a pinned HEAD symlink to the proposed source parent must fail closed")
        .to_string();
        assert!(
            head_alias.contains("aliases tracked Git symlink"),
            "{head_alias}"
        );
    }

