    #[test]
    fn generic_disjoint_and_runtime_scope_checks_use_filesystem_identity() {
        let temp = tempfile::tempdir().unwrap();
        fs::create_dir_all(temp.path().join("covered")).unwrap();
        fs::create_dir_all(temp.path().join("source")).unwrap();
        fs::write(temp.path().join("covered/seam.rs"), b"seam\n").unwrap();
        fs::hard_link(
            temp.path().join("covered/seam.rs"),
            temp.path().join("source/proof.rs"),
        )
        .unwrap();
        let definition: crate::config::FieldDef = serde_json::from_value(json!({
            "type": "list",
            "items": {"type": "path"},
            "disjoint_from": "spec.covered_paths"
        }))
        .unwrap();
        let node = Node::new(
            "disjoint-fixture",
            "Filesystem identity fixture",
            json!({"covered_paths": ["covered/seam.rs"]}),
        );
        let mut errors = Vec::new();
        validate_field_value(
            &node,
            "source_paths",
            &definition,
            &json!(["source/proof.rs"]),
            &Graph::default(),
            temp.path(),
            &mut errors,
        );
        assert_eq!(errors.len(), 1, "{errors:#?}");
        assert!(errors[0].contains("must be disjoint"), "{}", errors[0]);

        let writer = Scope {
            write_paths: BTreeSet::from(["source/proof.rs".to_owned()]),
            ..Scope::default()
        };
        let reader = Scope {
            read_paths: BTreeSet::from(["covered/seam.rs".to_owned()]),
            ..Scope::default()
        };
        assert!(scopes_write_conflict(temp.path(), &writer, &reader).unwrap());
    }

