    fn proof_source_preparation_operation() -> OperationDef {
        serde_json::from_value(json!({
            "id": "assurance.proof.prepare",
            "operation": "prepare-proof",
            "stage": "assurance",
            "proof_source_preparation_check": "baseline-set"
        }))
        .expect("proof preparation operation deserializes")
    }

    fn proof_source_preparation_step() -> Step {
        serde_json::from_value(json!({
            "id": "baseline",
            "persona": "test-author",
            "write_paths": ["tests/proof.sh"],
            "compiled_check_sets": [{
                "schema_version": "1.0",
                "parent_check_id": "baseline-set",
                "parent_check_hash": "sha256:parent",
                "selector_hash": "sha256:selector",
                "anchor_nodes": ["change"],
                "anchor_hashes": {"change": "sha256:change"},
                "selection_hash": "sha256:selection",
                "members": [{
                    "source_node_id": "proof",
                    "source_node_type": "Proof",
                    "source_semantic_hash": "sha256:proof",
                    "child_check_id": "expected-red",
                    "child_check_hash": "sha256:child",
                    "argv": ["./tests/proof.sh"],
                    "working_directory": ".",
                    "source_paths": ["tests/proof.sh"],
                    "covered_paths": ["src/product.rs"],
                    "contract_hash": "sha256:member"
                }],
                "contract_hash": "sha256:set"
            }],
            "context_hash": "sha256:baseline-context"
        }))
        .expect("proof preparation step deserializes")
    }

    fn classified_source_grant(
        owner: &str,
        path: &str,
        parent_check_id: &str,
        source_node_id: &str,
    ) -> ResolvedWorkflowWriteGrant {
        ResolvedWorkflowWriteGrant {
            owner: owner.to_owned(),
            path: path.to_owned(),
            source_bindings: BTreeSet::from([GraphSourceWriteBinding {
                parent_check_id: parent_check_id.to_owned(),
                source_node_id: source_node_id.to_owned(),
            }]),
        }
    }

    #[test]
    fn runtime_preparation_lookup_requires_exact_operation_declaration_and_check() {
        let mut profile = compiled_research_profile();
        let operation = proof_source_preparation_operation();
        profile
            .operations
            .insert(operation.id.clone(), operation.clone());

        assert_eq!(
            declared_proof_preparation_operation(
                &profile,
                "assurance.proof.prepare",
                "baseline-set",
            )
            .map(|operation| operation.id.as_str()),
            Some("assurance.proof.prepare")
        );
        assert!(
            declared_proof_preparation_operation(&profile, "assurance.proof.prepare", "other-set",)
                .is_none(),
            "a persisted or forged predicate cannot substitute a different check"
        );
        assert!(
            declared_proof_preparation_operation(&profile, "other.operation", "baseline-set")
                .is_none(),
            "an unknown operation cannot inherit a declaration"
        );
    }

    #[test]
    fn newest_preparation_attempt_supersedes_before_any_predicate_target_filter() {
        let mut profile = compiled_research_profile();
        let operation = proof_source_preparation_operation();
        profile
            .operations
            .insert(operation.id.clone(), operation.clone());
        let review = |id: &str, status: &str, second: u32| Review {
            id: id.to_owned(),
            status: status.to_owned(),
            notes: format!("{status} preparation attempt"),
            reviewed_at: Utc.with_ymd_and_hms(2026, 7, 14, 19, 0, second).unwrap(),
            ticket_hash: format!("sha256:{id}-ticket"),
            output_hash: format!("sha256:{id}-output"),
            agent_binding: None,
        };
        let attempt = |id: &str, targets: &[&str], review: Review| {
            let mut ticket = worker_projection_ticket(false);
            ticket.id = id.to_owned();
            ticket.operation = operation.public_operation().to_owned();
            ticket.profile_hash = profile.hash.clone();
            ticket.target_nodes = targets.iter().map(|target| (*target).to_owned()).collect();
            ticket.workflow = vec![proof_source_preparation_step()];
            ticket.reviews = vec![review];
            ticket.extensions.insert(
                "operation_registry_id".to_owned(),
                Value::String(operation.id.clone()),
            );
            ticket
        };
        let older = attempt(
            "TK-older-narrow-pass",
            &["proof"],
            review("review-older-pass", "passed", 1),
        );
        let mut newer = attempt(
            "TK-newer-wide-fail",
            &["proof", "subject"],
            review("review-newer-fail", "failed", 2),
        );
        newer.extensions.insert(
            "prior_cycles".to_owned(),
            json!([{
                "id": "TK-newer-wide-fail",
                "reviews": [{"status": "passed", "reviewed_at": "2099-01-01T00:00:00Z"}]
            }]),
        );

        let tickets = vec![older, newer];
        let latest = latest_reviewed_proof_preparation_attempts(&profile, &tickets);
        let selected = latest
            .get(&(operation.id.clone(), "proof".to_owned()))
            .expect("the shared selector finds the exact operation/source attempt");
        assert_eq!(selected.id, "TK-newer-wide-fail");
        assert_eq!(
            selected.reviews.last().map(|review| review.status.as_str()),
            Some("failed"),
            "audit-only prior cycles cannot replace the current live review boundary"
        );
        let narrow_targets = BTreeSet::from(["proof".to_owned()]);
        let wide_targets = BTreeSet::from(["proof".to_owned(), "subject".to_owned()]);
        let selected_targets = selected
            .target_nodes
            .iter()
            .cloned()
            .collect::<BTreeSet<_>>();
        assert_ne!(selected_targets, narrow_targets);
        assert_eq!(selected_targets, wide_targets);
        assert_eq!(
            latest
                .get(&(operation.id, "proof".to_owned()))
                .map(|ticket| ticket.id.as_str()),
            Some("TK-newer-wide-fail"),
            "both predicate owners and the global source lock consume one newest-attempt key"
        );

        let newer_review = tickets[1].reviews.last().unwrap();
        let replay_cutoff = (
            newer_review.reviewed_at,
            tickets[1].id.clone(),
            newer_review.id.clone(),
        );
        let historical = latest_reviewed_proof_preparation_attempts_before(
            &profile,
            &tickets,
            Some(&replay_cutoff),
        );
        assert_eq!(
            historical
                .get(&("assurance.proof.prepare".to_owned(), "proof".to_owned(),))
                .map(|ticket| ticket.id.as_str()),
            Some("TK-older-narrow-pass"),
            "historical effect replay excludes future preparations before newest-attempt supersession, including preparations whose operation has no effects"
        );

        let mut rereviewed = tickets.clone();
        rereviewed[1]
            .reviews
            .push(review("review-newer-late-pass", "passed", 4));
        let successor_cutoff = (
            Utc.with_ymd_and_hms(2026, 7, 14, 19, 0, 3).unwrap(),
            "TK-successor".to_owned(),
            "review-successor".to_owned(),
        );
        let historical = latest_reviewed_proof_preparation_attempts_before(
            &profile,
            &rereviewed,
            Some(&successor_cutoff),
        );
        let selected = historical
            .get(&("assurance.proof.prepare".to_owned(), "proof".to_owned()))
            .expect("the newer ticket remains the historical supersession tombstone");
        assert_eq!(selected.id, "TK-newer-wide-fail");
        assert!(
            selected
                .reviews
                .last()
                .is_some_and(|review| review.reviewed_at >= successor_cutoff.0),
            "binding authentication sees the live post-cutoff re-review and fails this tombstone closed instead of reviving the older preparation"
        );
    }

    #[test]
    fn declared_preparation_operation_accepts_only_exact_selected_source_write_grants() {
        let operation = proof_source_preparation_operation();
        let step = proof_source_preparation_step();
        let exact = classified_source_grant(
            "workflow prepare baseline",
            "tests/proof.sh",
            "baseline-set",
            "proof",
        );
        let exact_authority = ResolvedTicketWriteAuthority {
            source_grants: vec![exact.clone()],
            other_grants: Vec::new(),
        };
        let binding = proof_source_write_authority_binding(
            Path::new("."),
            &operation,
            std::slice::from_ref(&step),
            &exact_authority,
        )
        .unwrap()
        .expect("exact selected source projection is compiler-bound");
        assert_eq!(
            binding.grants,
            vec![ProofSourceWriteGrantBinding {
                source_node_id: "proof".to_owned(),
                path: "tests/proof.sh".to_owned(),
            }]
        );

        for (label, path) in [
            ("literal exact", "tests/proof.sh"),
            ("broad", "tests"),
            ("root", "."),
            ("disjoint product", "src/product.rs"),
            ("sibling", "tests/other.sh"),
        ] {
            let authority = ResolvedTicketWriteAuthority {
                source_grants: vec![exact.clone()],
                other_grants: vec![ResolvedWorkflowWriteGrant {
                    owner: label.to_owned(),
                    path: path.to_owned(),
                    source_bindings: BTreeSet::new(),
                }],
            };
            let error = proof_source_write_authority_binding(
                Path::new("."),
                &operation,
                std::slice::from_ref(&step),
                &authority,
            )
            .expect_err("every non-projection preparation write must fail")
            .to_string();
            assert!(
                error.contains("not an exact compiler-selected source projection"),
                "{label}: {error}"
            );
        }

        for (label, grant) in [
            (
                "broad selected grant",
                classified_source_grant("baseline", "tests", "baseline-set", "proof"),
            ),
            (
                "sibling selected grant",
                classified_source_grant("baseline", "tests/other.sh", "baseline-set", "proof"),
            ),
            (
                "different declared source",
                classified_source_grant(
                    "baseline",
                    "tests/proof.sh",
                    "baseline-set",
                    "other-proof",
                ),
            ),
            (
                "different graph-set check",
                classified_source_grant("baseline", "tests/proof.sh", "other-set", "proof"),
            ),
        ] {
            let error = proof_source_write_authority_binding(
                Path::new("."),
                &operation,
                std::slice::from_ref(&step),
                &ResolvedTicketWriteAuthority {
                    source_grants: vec![grant],
                    other_grants: Vec::new(),
                },
            )
            .expect_err("broad or undeclared projections must not gain preparation authority")
            .to_string();
            assert!(
                error.contains("broad, undeclared, or belongs to a different graph-set check"),
                "{label}: {error}"
            );
        }
    }

    #[test]
    fn persisted_preparation_authority_must_cover_complete_ticket_and_step_write_scope() {
        let profile = compiled_research_profile();
        let operation = proof_source_preparation_operation();
        let step = proof_source_preparation_step();
        let authority = ResolvedTicketWriteAuthority {
            source_grants: vec![classified_source_grant(
                "workflow prepare baseline",
                "tests/proof.sh",
                "baseline-set",
                "proof",
            )],
            other_grants: Vec::new(),
        };
        let binding = proof_source_write_authority_binding(
            Path::new("."),
            &operation,
            std::slice::from_ref(&step),
            &authority,
        )
        .unwrap()
        .unwrap();
        let mut ticket = worker_projection_ticket(false);
        ticket.operation = operation.public_operation().to_owned();
        ticket.profile_hash = profile.hash.clone();
        ticket.scope.write_paths = BTreeSet::from(["tests/proof.sh".to_owned()]);
        ticket.workflow = vec![step];
        ticket.extensions.insert(
            "operation_registry_id".to_owned(),
            Value::String(operation.id.clone()),
        );
        ticket.extensions.insert(
            PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION.to_owned(),
            serde_json::to_value(&binding).unwrap(),
        );
        assert_eq!(
            validated_ticket_proof_source_write_authority(
                Path::new("."),
                &profile,
                &ticket,
                &operation,
            )
            .unwrap(),
            Some(binding.clone())
        );

        let mut missing = ticket.clone();
        missing
            .extensions
            .remove(PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION);
        assert!(
            validated_ticket_proof_source_write_authority(
                Path::new("."),
                &profile,
                &missing,
                &operation,
            )
            .unwrap_err()
            .to_string()
            .contains("write scope without compiler proof-source authority")
        );

        let mut extra_ticket_write = ticket.clone();
        extra_ticket_write
            .scope
            .write_paths
            .insert("src/product.rs".to_owned());
        assert!(
            validated_ticket_proof_source_write_authority(
                Path::new("."),
                &profile,
                &extra_ticket_write,
                &operation,
            )
            .unwrap_err()
            .to_string()
            .contains("outside its compiler proof-source authority")
        );

        let mut extra_step_write = ticket.clone();
        extra_step_write.workflow[0]
            .write_paths
            .as_mut()
            .unwrap()
            .insert("src/product.rs".to_owned());
        assert!(
            validated_ticket_proof_source_write_authority(
                Path::new("."),
                &profile,
                &extra_step_write,
                &operation,
            )
            .unwrap_err()
            .to_string()
            .contains("workflow step baseline write path src/product.rs is outside")
        );

        for (label, mutate) in [("profile", "profile"), ("public operation", "operation")] {
            let mut changed = ticket.clone();
            if mutate == "profile" {
                changed.profile_hash = "sha256:other-profile".to_owned();
            } else {
                changed.operation = "implement-product".to_owned();
            }
            let error = validated_ticket_proof_source_write_authority(
                Path::new("."),
                &profile,
                &changed,
                &operation,
            )
            .expect_err("persisted operation identity drift must fail")
            .to_string();
            assert!(
                error.contains("conflicts with proof-source preparation"),
                "{label}: {error}"
            );
        }

        let mut forged = ticket;
        let mut forged_binding = binding;
        forged_binding.grants[0].path = "tests".to_owned();
        forged_binding.binding_hash = proof_source_write_authority_hash(&forged_binding);
        forged.extensions.insert(
            PROOF_SOURCE_WRITE_AUTHORITY_EXTENSION.to_owned(),
            serde_json::to_value(forged_binding).unwrap(),
        );
        assert!(
            validated_ticket_proof_source_write_authority(
                Path::new("."),
                &profile,
                &forged,
                &operation,
            )
            .unwrap_err()
            .to_string()
            .contains("is not an exact compiled member source")
        );
    }

    #[test]
    fn lease_admission_rechecks_preparations_created_after_ticket_emission_and_on_retry() {
        let profile = compiled_research_profile();
        let operation: OperationDef = serde_json::from_value(json!({
            "id": "implementation.change",
            "operation": "implement-product",
            "stage": "implementation"
        }))
        .unwrap();
        let mut ticket = worker_projection_ticket(false);
        ticket.operation = operation.public_operation().to_owned();
        ticket.profile_hash = profile.hash.clone();
        ticket.scope.write_paths = BTreeSet::from(["tests/proof.sh".to_owned()]);
        ticket.extensions.insert(
            "operation_registry_id".to_owned(),
            Value::String(operation.id.clone()),
        );

        validate_persisted_ticket_prepared_source_admission(
            Path::new("."),
            &profile,
            &ticket,
            &operation,
            &[],
        )
        .expect("ticket emission predates any prepared source");

        let current = CurrentProofPreparationBinding {
            preparation_operation_id: "assurance.proof.prepare".to_owned(),
            preparation_check_id: "baseline-set".to_owned(),
            ticket_id: "TK-prepared-later".to_owned(),
            source_node_id: "proof".to_owned(),
            target_nodes: BTreeSet::from(["proof".to_owned()]),
            source_paths: BTreeSet::from(["tests/proof.sh".to_owned()]),
            reviewed_at: Utc.with_ymd_and_hms(2026, 7, 14, 12, 0, 0).unwrap(),
        };
        let error = validate_persisted_ticket_prepared_source_admission(
            Path::new("."),
            &profile,
            &ticket,
            &operation,
            std::slice::from_ref(&current),
        )
        .expect_err("late preparation must revoke the stale emitted ticket at lease time")
        .to_string();
        assert!(
            error.contains("cannot start ticket")
                && error.contains("overlaps current prepared proof source"),
            "{error}"
        );

        assert!(
            ticket.lease.is_some(),
            "fixture models an existing-lease retry"
        );
        assert!(
            validate_persisted_ticket_prepared_source_admission(
                Path::new("."),
                &profile,
                &ticket,
                &operation,
                std::slice::from_ref(&current),
            )
            .is_err(),
            "the admission check runs before acquire_lease's existing-lease fast path"
        );
    }

    #[test]
    fn prepared_source_conflict_allows_only_exact_same_operation_check_source_and_path() {
        let current = CurrentProofPreparationBinding {
            preparation_operation_id: "assurance.proof.prepare".to_owned(),
            preparation_check_id: "baseline-set".to_owned(),
            ticket_id: "TK-prepared".to_owned(),
            source_node_id: "proof".to_owned(),
            target_nodes: BTreeSet::from(["proof".to_owned()]),
            source_paths: BTreeSet::from(["tests/proof.sh".to_owned()]),
            reviewed_at: Utc.with_ymd_and_hms(2026, 7, 14, 12, 0, 0).unwrap(),
        };
        let grant = |path: &str| ResolvedWorkflowWriteGrant {
            owner: "candidate ticket".to_owned(),
            path: path.to_owned(),
            source_bindings: BTreeSet::new(),
        };
        for path in ["tests/proof.sh", "tests", "tests/proof.sh/generated", "."] {
            assert!(
                prepared_source_write_conflict(
                    Path::new("."),
                    std::slice::from_ref(&current),
                    &[grant(path)],
                    None,
                )
                .unwrap()
                .is_some(),
                "overlap {path} must be rejected without compiler authority"
            );
        }
        assert!(
            prepared_source_write_conflict(
                Path::new("."),
                std::slice::from_ref(&current),
                &[grant("src/product.rs")],
                None,
            )
            .unwrap()
            .is_none()
        );

        let allowed = |operation: &str, check: &str, source: &str, path: &str| {
            let mut binding = ProofSourceWriteAuthorityBinding {
                schema_version: "1.0".to_owned(),
                operation_registry_id: operation.to_owned(),
                preparation_check_id: check.to_owned(),
                grants: vec![ProofSourceWriteGrantBinding {
                    source_node_id: source.to_owned(),
                    path: path.to_owned(),
                }],
                binding_hash: String::new(),
            };
            binding.binding_hash = proof_source_write_authority_hash(&binding);
            binding
        };
        let exact = allowed(
            "assurance.proof.prepare",
            "baseline-set",
            "proof",
            "tests/proof.sh",
        );
        assert!(
            prepared_source_write_conflict(
                Path::new("."),
                std::slice::from_ref(&current),
                &[grant("tests/proof.sh")],
                Some(&exact),
            )
            .unwrap()
            .is_none(),
            "only exact compiler-proven re-preparation is admitted"
        );
        for invalid in [
            allowed("other.operation", "baseline-set", "proof", "tests/proof.sh"),
            allowed(
                "assurance.proof.prepare",
                "other-set",
                "proof",
                "tests/proof.sh",
            ),
            allowed(
                "assurance.proof.prepare",
                "baseline-set",
                "other-proof",
                "tests/proof.sh",
            ),
            allowed("assurance.proof.prepare", "baseline-set", "proof", "tests"),
        ] {
            assert!(
                prepared_source_write_conflict(
                    Path::new("."),
                    std::slice::from_ref(&current),
                    &[grant("tests/proof.sh")],
                    Some(&invalid),
                )
                .unwrap()
                .is_some()
            );
        }

        let broad_alongside_exact = vec![grant("tests/proof.sh"), grant("tests")];
        assert!(
            prepared_source_write_conflict(
                Path::new("."),
                std::slice::from_ref(&current),
                &broad_alongside_exact,
                Some(&exact),
            )
            .unwrap()
            .is_some(),
            "an exact grant cannot launder a broad companion grant"
        );
    }

    #[test]
    fn graph_set_members_bind_interpreted_scripts_and_reject_shell_command_strings() {
        let temp = tempfile::tempdir().unwrap();
        fs::create_dir_all(temp.path().join("tests")).unwrap();
        fs::write(temp.path().join("tests/harness.py"), b"print('ok')\n").unwrap();
        fs::write(temp.path().join("tests/input.txt"), b"input\n").unwrap();
        let executable = |requested: &str| ExecutableBinding {
            requested: requested.to_owned(),
            path_kind: "path_lookup".to_owned(),
            resolved_path: format!("/usr/bin/{requested}"),
            size_bytes: 1,
            sha256: "sha256:external".to_owned(),
            mode: None,
            device: None,
            inode: None,
            modified_ns: None,
        };

        let interpreted = compiled_member_project_executable_sources(
            temp.path(),
            ".",
            &["python3.12".to_owned(), "tests/harness.py".to_owned()],
            &executable("python3.12"),
        )
        .unwrap();
        assert_eq!(interpreted, BTreeSet::from(["tests/harness.py".to_owned()]));

        let inline_python = compiled_member_project_executable_sources(
            temp.path(),
            ".",
            &[
                "python3.12".to_owned(),
                "-c".to_owned(),
                "print('inline')".to_owned(),
                "tests/input.txt".to_owned(),
            ],
            &executable("python3.12"),
        )
        .unwrap();
        assert!(inline_python.is_empty());

        let error = compiled_member_project_executable_sources(
            temp.path(),
            ".",
            &[
                "/bin/sh".to_owned(),
                "-lc".to_owned(),
                "exec tests/harness.py".to_owned(),
            ],
            &executable("sh"),
        )
        .expect_err("shell command strings hide causal project paths")
        .to_string();
        assert!(error.contains("cannot use a shell command string"));

        let error = compiled_member_project_executable_sources(
            temp.path(),
            ".",
            &[
                "fish".to_owned(),
                "--command=exec tests/harness.py".to_owned(),
            ],
            &executable("fish"),
        )
        .expect_err("long shell command options also hide causal project paths")
        .to_string();
        assert!(error.contains("cannot use a shell command string"));

        let error = compiled_member_project_executable_sources(
            temp.path(),
            ".",
            &[
                "env".to_owned(),
                "-u".to_owned(),
                "NAME".to_owned(),
                "sh".to_owned(),
                "-c".to_owned(),
                "exec tests/harness.py".to_owned(),
            ],
            &executable("env"),
        )
        .expect_err("env wrappers can hide interpreter and shell boundaries")
        .to_string();
        assert!(error.contains("cannot use an env command wrapper"));
    }

    #[test]
    fn model_facing_dependency_output_compacts_materialized_node_bodies() {
        let output = serde_json::from_value::<crate::state::StepOutput>(json!({
            "id": "output-1",
            "step_id": "author",
            "persona": "designer",
            "context_hash": "sha256:context",
            "recorded_at": "2026-07-12T00:00:00Z",
            "typed": {
                "summary": "Authored runtime gate",
                "structured_output": {"decision": "keep this exact downstream contract"},
                "graph_delta": {
                    "add_nodes": [{
                        "id": "gate-1",
                        "type": "gate",
                        "title": "Runtime gate",
                        "spec": {"large_contract": "must not be duplicated in dependency context"},
                        "edges": {"applies_to": ["claim-1"]}
                    }],
                    "add_edges": [{"source":"claim-1","relation":"gates","target":"gate-1"}]
                }
            }
        }))
        .unwrap();

        let compact = model_facing_step_output(&output);
        assert_eq!(compact["typed"]["summary"], "Authored runtime gate");
        assert_eq!(
            compact["typed"]["structured_output"]["decision"],
            "keep this exact downstream contract"
        );
        assert_eq!(
            compact["typed"]["graph_delta"]["add_nodes"][0]["id"],
            "gate-1"
        );
        assert_eq!(
            compact["typed"]["graph_delta"]["add_edges"][0]["target"],
            "gate-1"
        );
        assert!(
            compact["typed"]["graph_delta"]["add_nodes"][0]
                .get("spec")
                .is_none()
        );
        assert_eq!(
            compact["typed"]["graph_delta"]["materialized_in_graph_closure"],
            true
        );
    }

    #[test]
    fn successful_output_retry_supersedes_only_its_exact_failed_boundary() {
        let profile = compiled_research_profile();
        let action = &profile.actions["output"];
        let params = |step: &str, payload: Value| {
            BTreeMap::from([
                ("ticket_id".to_owned(), json!("TK-retry")),
                ("step".to_owned(), json!(step)),
                ("persona".to_owned(), json!("gate-designer")),
                ("payload".to_owned(), payload),
            ])
        };
        let failed_hash = action_retry_input_hash(action, &params("author", json!({"bad": true})));
        assert_eq!(
            failed_hash,
            action_retry_input_hash(action, &params("author", json!({"fixed": true}))),
            "corrected output content belongs to the same logical retry boundary"
        );
        let unrelated_hash =
            action_retry_input_hash(action, &params("integrate", json!({"fixed": true})));
        assert_ne!(failed_hash, unrelated_hash);

        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let journal = |id: &str, input_hash: &str, status: JournalStatus| Journal {
            id: id.to_owned(),
            action: "output".to_owned(),
            input_hash: Some(input_hash.to_owned()),
            status,
            started_at: Utc::now(),
            profile_hash: profile.hash.clone(),
            completed_steps: Vec::new(),
            outputs: BTreeMap::new(),
            error: Some("schema correction required".to_owned()),
        };
        store
            .write_journal(&journal(
                "failed-matching",
                &failed_hash,
                JournalStatus::Failed,
            ))
            .unwrap();
        store
            .write_journal(&journal(
                "failed-other-step",
                &unrelated_hash,
                JournalStatus::Failed,
            ))
            .unwrap();
        let success = journal("successful-retry", &failed_hash, JournalStatus::Complete);
        store.write_journal(&success).unwrap();

        assert_eq!(
            acknowledge_failed_attempts_superseded_by_success(&store, &success).unwrap(),
            vec!["failed-matching"]
        );
        let statuses = store
            .journals()
            .unwrap()
            .into_iter()
            .map(|journal| (journal.id, (journal.status, journal.error)))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(statuses["failed-matching"].0, JournalStatus::Recovered);
        assert_eq!(
            statuses["failed-matching"].1.as_deref(),
            Some("schema correction required"),
            "the rejected attempt remains auditable after recovery"
        );
        assert_eq!(
            statuses["failed-other-step"].0,
            JournalStatus::Failed,
            "success on one step must not clear another failed boundary"
        );
    }

    #[test]
    fn integration_causal_receipts_bind_current_dependencies_not_review_history() {
        let mut ticket = serde_json::from_value::<Ticket>(json!({
            "schema_version": "1.0",
            "id": "TK-causal",
            "operation": "define-gates",
            "status": "in_progress",
            "title": "Bind current dependency",
            "source_state_key": "before",
            "target_state_key": "after",
            "profile_hash": "sha256:profile",
            "rule_id": "ticket.causal",
            "workflow": [
                {
                    "id": "author",
                    "persona": "designer",
                    "kind": "production",
                    "context_hash": "sha256:author"
                },
                {
                    "id": "integrate",
                    "persona": "integrator",
                    "kind": "integration",
                    "depends_on": ["author"],
                    "context_hash": "sha256:integrate"
                }
            ],
            "outputs": [{
                "id": "output-current",
                "step_id": "author",
                "persona": "designer",
                "context_hash": "sha256:author",
                "recorded_at": "2026-07-13T14:00:00Z",
                "typed": {"summary": "Authored current contract"}
            }]
        }))
        .unwrap();
        let output = &ticket.outputs[0];
        let output_hash = normalized_hash(output);
        let stale = json!({
            "id": "receipt-stale",
            "receipt_type": "structured-output",
            "ticket_id": ticket.id,
            "step": "author",
            "output_id": "output-superseded",
            "output_hash": "sha256:superseded",
            "recorded_at": "2026-07-13T14:01:00Z"
        });
        let current = json!({
            "id": "receipt-current",
            "receipt_type": "structured-output",
            "ticket_id": ticket.id,
            "step": "author",
            "output_id": output.id,
            "output_hash": output_hash,
            "recorded_at": "2026-07-13T14:00:01Z"
        });
        let pointers = canonical_dependency_causal_receipts(
            &ticket,
            &ticket.workflow[1],
            &[stale, current.clone()],
        )
        .unwrap();

        assert_eq!(
            pointers,
            vec![
                format!("output:{}@{}", output.id, normalized_hash(output)),
                format!("receipt:receipt-current@{}", normalized_hash(&current))
            ]
        );
        assert!(
            pointers
                .iter()
                .all(|pointer| !pointer.contains("superseded"))
        );

        ticket.outputs.push(
            serde_json::from_value(json!({
                "id": "integration-pre-upgrade",
                "step_id": "integrate",
                "persona": "integrator",
                "context_hash": "sha256:integrate",
                "recorded_at": "2026-07-13T14:02:00Z",
                "typed": {
                    "summary": "Integrated dependency",
                    "causal_receipts": [
                        "output:output-superseded@sha256:superseded",
                        "receipt:receipt-stale@sha256:superseded"
                    ]
                }
            }))
            .unwrap(),
        );
        let durable_hash = normalized_hash(&ticket.outputs);
        let projected = compiler_owned_causal_receipt_projection(&ticket, &[current]).unwrap();
        assert_eq!(
            ticket.outputs[1].typed["causal_receipts"],
            json!([
                "output:output-superseded@sha256:superseded",
                "receipt:receipt-stale@sha256:superseded"
            ]),
            "review compatibility must not rewrite the compiled source output"
        );
        assert_eq!(
            projected.outputs[1].typed["causal_receipts"],
            json!(pointers)
        );
        assert_eq!(normalized_hash(&ticket.outputs), durable_hash);
        assert_ne!(
            compiler_owned_causal_binding_hash(&ticket, &projected),
            compiler_owned_causal_binding_hash(&ticket, &ticket)
        );
        let rendered = model_facing_current_ticket_outputs_with_projection(&ticket, &projected);
        let integration = rendered
            .iter()
            .find(|output| output["step_id"] == "integrate")
            .unwrap();
        assert_eq!(integration["typed"]["causal_receipts"], json!(pointers));
        assert_eq!(
            integration["output_hash"],
            normalized_hash(&ticket.outputs[1])
        );
        assert_eq!(
            integration["compiler_projection"]["fields"],
            json!(["typed.causal_receipts"])
        );
    }

