    #[test]
    fn review_packet_hides_read_only_neighbor_obligations_and_filters_target_obligations() {
        let profile = compiled_research_profile();
        let ticket = serde_json::from_value::<Ticket>(json!({
            "schema_version": "1.0",
            "id": "TK-plan-change",
            "operation": "plan-change",
            "status": "in_progress",
            "title": "Plan a bounded change",
            "target_nodes": ["objective-1"],
            "scope": {
                "read_nodes": ["objective-1", "neighbor-system"],
                "write_nodes": ["objective-1"]
            },
            "source_state_key": "objective-without-change-plan",
            "target_state_key": "objective-has-bounded-change-plan",
            "obligation_keys": ["objective.change-plan"],
            "profile_hash": "sha256:profile",
            "rule_id": "objective.plan-change",
            "workflow": [{
                "id": "review",
                "persona": "reviewer",
                "kind": "review",
                "expected_outputs": ["bounded review"],
                "context_hash": "sha256:review-context"
            }],
            "extensions": {
                "operation_registry_id": "design.objective.plan-change"
            }
        }))
        .unwrap();

        let mut objective = Node::new("objective", "Requested outcome", json!({}));
        objective.id = "objective-1".to_owned();
        objective.status = "draft".to_owned();
        objective.extensions.insert(
            "readiness".to_owned(),
            json!({"state": "blocked", "reason": "Owned transition is incomplete"}),
        );
        objective.extensions.insert(
            "obligations".to_owned(),
            json!({"unmet": [
                {
                    "key": "objective.change-plan",
                    "reason": "TARGET_RELEVANT_SENTINEL",
                    "severity": "blocking"
                },
                {
                    "key": "delivery.unrelated",
                    "reason": "TARGET_UNRELATED_SENTINEL",
                    "severity": "blocking"
                }
            ]}),
        );
        let mut neighbor = Node::new("system", "Read-only dependency", json!({}));
        neighbor.id = "neighbor-system".to_owned();
        neighbor.status = "draft".to_owned();
        neighbor.extensions.insert(
            "obligations".to_owned(),
            json!({"unmet": [{
                "key": "system.contracts",
                "reason": "NEIGHBOR_OBLIGATION_SENTINEL",
                "severity": "blocking"
            }]}),
        );
        let mut graph = Graph::default();
        graph.insert(objective).unwrap();
        graph.insert(neighbor).unwrap();

        let packet = model_facing_review_evidence_packet(
            &profile,
            &ticket,
            &ticket,
            &graph,
            &[],
            &ticket.workflow[0],
            "Review only this ticket's bounded transition.",
            "bounded review",
            "sha256:review-input",
            "sha256:graph",
            None,
        );
        let nodes = packet["current_nodes"].as_array().unwrap();
        let objective = nodes
            .iter()
            .find(|node| node["id"] == "objective-1")
            .unwrap();
        let neighbor = nodes
            .iter()
            .find(|node| node["id"] == "neighbor-system")
            .unwrap();

        assert_eq!(objective["operational_state"]["status"], "draft");
        assert_eq!(
            objective["operational_state"]["obligations"]["unmet"],
            json!([{
                "key": "objective.change-plan",
                "reason": "TARGET_RELEVANT_SENTINEL",
                "severity": "blocking"
            }])
        );
        assert_eq!(
            objective["operational_state"]["readiness"]["state"],
            "blocked"
        );
        assert!(neighbor.get("operational_state").is_none());
        let serialized = serde_json::to_string(&packet).unwrap();
        assert!(!serialized.contains("NEIGHBOR_OBLIGATION_SENTINEL"));
        assert!(!serialized.contains("TARGET_UNRELATED_SENTINEL"));
        assert!(serialized.contains("TARGET_RELEVANT_SENTINEL"));
    }

