    #[test]
    fn ticket_review_result_rejects_evidence_outside_compiler_packet() {
        let result = TicketReviewAgentResult {
            schema_version: "1.0".to_owned(),
            verdict: TicketReviewVerdict::Passed,
            failure_domain: None,
            summary: "The bounded acceptance contract is satisfied.".to_owned(),
            findings: vec!["No blocking finding remains.".to_owned()],
            evidence_pointers: vec!["program/tickets/stale.yaml".to_owned()],
        };
        let allowed = BTreeSet::from(["packet://review/acceptance".to_owned()]);
        let error = result.validate_evidence_pointers(&allowed).unwrap_err();
        assert!(
            error
                .to_string()
                .contains("outside the compiler-bound packet")
        );
    }

    #[test]
    fn new_ticket_review_result_requires_an_advertised_failure_domain() {
        let allowed = BTreeSet::from(["ticket_rework".to_owned(), "upstream_proof".to_owned()]);
        let result =
            |schema_version: &str, verdict, failure_domain: Option<&str>| TicketReviewAgentResult {
                schema_version: schema_version.to_owned(),
                verdict,
                failure_domain: failure_domain.map(str::to_owned),
                summary: "Bounded assessment.".to_owned(),
                findings: vec!["One concrete finding.".to_owned()],
                evidence_pointers: vec!["packet://review/acceptance".to_owned()],
            };

        result("1.1", TicketReviewVerdict::Passed, Some("none"))
            .validate_for_new_invocation(&allowed)
            .unwrap();
        result("1.1", TicketReviewVerdict::Failed, Some("upstream_proof"))
            .validate_for_new_invocation(&allowed)
            .unwrap();
        assert!(
            result("1.0", TicketReviewVerdict::Failed, None)
                .validate()
                .is_ok(),
            "persisted schema-1.0 review history remains readable"
        );
        assert!(
            result("1.0", TicketReviewVerdict::Failed, None)
                .validate_for_new_invocation(&allowed)
                .is_err(),
            "a new invocation cannot omit its compiler-bound domain"
        );
        assert!(
            result("1.1", TicketReviewVerdict::Failed, Some("invented_domain"))
                .validate_for_new_invocation(&allowed)
                .is_err()
        );
        assert!(
            result("1.1", TicketReviewVerdict::Passed, Some("ticket_rework"))
                .validate()
                .is_err()
        );
    }

    fn install_active_test_run_identity(
        store: &StateStore,
        root: &Path,
        profile: &CompiledProfile,
    ) {
        ensure_repository_with_head(root).unwrap();
        if store.manifest_path().exists() {
            return;
        }
        let manifest = RunManifest::new(
            profile.manifest.profile.id.clone(),
            profile.manifest.profile.version.clone(),
            profile.hash.clone(),
            "command authority test fixture",
            root.canonicalize().unwrap(),
        );
        store.write_manifest(&manifest).unwrap();
    }

    #[test]
    fn run_authority_barrier_is_reentrant_and_keeps_one_persistent_inode() {
        let temp = tempfile::tempdir().unwrap();
        let sidecar = temp.path().canonicalize().unwrap().join("koni");
        let first = acquire_run_authority_barrier_at(&sidecar, "run-test").unwrap();
        let path = run_authority_barrier_path(&sidecar, "run-test").unwrap();
        let second = acquire_run_authority_barrier_at(&sidecar, "run-test").unwrap();
        drop(first);

        let probe = fs::OpenOptions::new()
            .read(true)
            .write(true)
            .open(&path)
            .unwrap();
        assert!(probe.try_lock_exclusive().is_err());
        drop(second);
        probe.try_lock_exclusive().unwrap();
        probe.unlock().unwrap();
        assert!(
            path.is_file(),
            "barrier rendezvous inode must never be unlinked"
        );
    }

