    #[test]
    fn completed_remote_journal_rejects_receipt_substitution_and_guard_tampering() {
        let fixture = tracked_journal_worktree_fixture();
        let pre = read_only_workspace_fingerprint(
            &fixture.remote_root,
            &fixture.profile,
            fixture.remote_store.root(),
        )
        .unwrap();
        let (journal_path, receipt) =
            write_bound_ticket_worktree_receipt(&fixture, 21, "passed", &pre, &pre, "completed");
        let journal = read_optional_yaml_value(&journal_path).unwrap().unwrap();
        assert!(command_attempt_journal_matches_receipt(
            &journal,
            &receipt,
            &fixture.profile,
        ));

        let mut substituted = receipt.clone();
        substituted["id"] = json!("replacement-receipt");
        rehash_durable_receipt(&mut substituted);
        assert!(!command_attempt_journal_matches_receipt(
            &journal,
            &substituted,
            &fixture.profile,
        ));
        let mut guard_tampered = receipt.clone();
        guard_tampered["workspace_guard"]["pre_hash"] = json!("sha256:replacement");
        guard_tampered["workspace_guard"]["post_hash"] = json!("sha256:replacement");
        rehash_durable_receipt(&mut guard_tampered);
        assert!(!command_attempt_journal_matches_receipt(
            &journal,
            &guard_tampered,
            &fixture.profile,
        ));

        atomic_write_yaml(
            &fixture
                .remote_store
                .receipts_dir()
                .join(format!("{}.yaml", receipt["id"].as_str().unwrap())),
            &substituted,
        )
        .unwrap();
        assert_eq!(
            read_only_violation_watermark(
                &fixture.profile,
                &fixture.caller_store,
                &fixture.caller_root,
            )
            .unwrap(),
            Some(21),
            "a completed journal with a substituted receipt remains uncertain"
        );
    }

    #[test]
    fn tracked_remote_violation_uses_its_own_workspace_and_state_authority() {
        let fixture = tracked_journal_worktree_fixture();
        let pre = read_only_workspace_fingerprint(
            &fixture.remote_root,
            &fixture.profile,
            fixture.remote_store.root(),
        )
        .unwrap();
        fs::write(fixture.remote_root.join("product.txt"), "violating").unwrap();
        let post = read_only_workspace_fingerprint(
            &fixture.remote_root,
            &fixture.profile,
            fixture.remote_store.root(),
        )
        .unwrap();
        let (_, receipt) = write_bound_ticket_worktree_receipt(
            &fixture,
            30,
            "invalid_contract",
            &pre,
            &post,
            "completed",
        );
        let remote_state_root = fixture.remote_store.root().canonicalize().unwrap();
        let remote_row = command_authority_receipt_rows(
            &fixture.profile,
            &fixture.caller_store,
            &fixture.caller_root,
        )
        .unwrap()
        .into_iter()
        .find(|row| row["id"] == receipt["id"])
        .expect("remote violation is admitted through its exact journal");
        assert_eq!(
            remote_row["state_root"],
            remote_state_root.to_string_lossy().as_ref()
        );
        assert_eq!(
            read_only_violation_watermark(
                &fixture.profile,
                &fixture.caller_store,
                &fixture.caller_root,
            )
            .unwrap(),
            Some(30)
        );
        let error = ensure_global_read_only_quarantine_clear(
            &fixture.caller_root,
            &fixture.profile,
            &fixture.caller_store,
        )
        .expect_err("the caller must observe the remote worktree violation");
        assert!(error.to_string().contains(receipt["id"].as_str().unwrap()));
        assert_eq!(
            fs::read_to_string(fixture.integration_root.join("product.txt")).unwrap(),
            "before"
        );
        assert_eq!(
            fs::read_to_string(fixture.remote_root.join("product.txt")).unwrap(),
            "violating"
        );

        fs::write(fixture.remote_root.join("product.txt"), "before").unwrap();
        ensure_global_read_only_quarantine_clear(
            &fixture.caller_root,
            &fixture.profile,
            &fixture.caller_store,
        )
        .unwrap();
        let remediation = command_authority_receipt_rows(
            &fixture.profile,
            &fixture.caller_store,
            &fixture.caller_root,
        )
        .unwrap()
        .into_iter()
        .find(read_only_remediation_receipt_is_valid)
        .expect("restoring the remote preimage records shared remediation");
        assert_eq!(remediation["violation_id"], receipt["id"]);
        assert_eq!(
            remediation["workspace_root"],
            fixture.remote_root.to_string_lossy().as_ref()
        );
        assert_eq!(
            remediation["state_root"],
            remote_state_root.to_string_lossy().as_ref()
        );
        fs::write(
            fixture.remote_root.join("product.txt"),
            "authorized-later-change",
        )
        .unwrap();
        ensure_global_read_only_quarantine_clear(
            &fixture.caller_root,
            &fixture.profile,
            &fixture.caller_store,
        )
        .expect("shared remediation must survive a later authorized remote edit");
    }

    #[test]
    fn escaped_journal_and_receipt_roots_fail_before_external_sentinel_traversal() {
        let fixture = tracked_journal_worktree_fixture();
        let external = tempfile::tempdir().unwrap();
        let sentinel = external.path().join("MUST_NOT_BE_READ.yaml");
        fs::write(&sentinel, ": [\n").unwrap();
        let pre = read_only_workspace_fingerprint(
            &fixture.caller_root,
            &fixture.profile,
            fixture.caller_store.root(),
        )
        .unwrap();
        let journal_path = write_test_command_journal(
            &fixture.caller_store,
            &fixture.caller_root,
            &fixture.profile,
            40,
            "prepared",
            &pre,
        );
        let mut escaped = read_optional_yaml_value(&journal_path).unwrap().unwrap();
        escaped["receipts_root"] = json!(external.path().canonicalize().unwrap());
        durable_atomic_write_yaml(&journal_path, &escaped).unwrap();
        let corrupt_error = command_authority_receipt_rows(
            &fixture.profile,
            &fixture.caller_store,
            &fixture.caller_root,
        )
        .expect_err("corrupt journal integrity must fail before root traversal");
        assert!(corrupt_error.to_string().contains("integrity"));
        assert!(!corrupt_error.to_string().contains("MUST_NOT_BE_READ"));

        rehash_command_attempt_journal(&mut escaped);
        durable_atomic_write_yaml(&journal_path, &escaped).unwrap();
        let escaped_error = command_authority_receipt_rows(
            &fixture.profile,
            &fixture.caller_store,
            &fixture.caller_root,
        )
        .expect_err("an integrity-valid escaped receipts root must fail provenance");
        assert!(escaped_error.to_string().contains("receipts_root"));
        assert!(!escaped_error.to_string().contains("MUST_NOT_BE_READ"));
        fs::remove_file(&journal_path).unwrap();

        let remote_pre = read_only_workspace_fingerprint(
            &fixture.remote_root,
            &fixture.profile,
            fixture.remote_store.root(),
        )
        .unwrap();
        let _ = write_bound_ticket_worktree_receipt(
            &fixture,
            41,
            "passed",
            &remote_pre,
            &remote_pre,
            "completed",
        );
        let mut forged = invalid_contract_receipt(
            &fixture.profile,
            "gate-verifier",
            "escaped-receipt",
            42,
            "read_only",
            json!({
                "pre_hash": "sha256:before",
                "post_hash": "sha256:after",
                "changed_paths": ["MUST_NOT_BE_READ.yaml"],
                "changes": [{"path": "MUST_NOT_BE_READ.yaml", "pre": null, "post": "changed"}],
                "unchanged": false,
            }),
        );
        forged["run_id"] = json!(fixture.remote_store.manifest().unwrap().id);
        forged["workspace_root"] = json!(external.path().canonicalize().unwrap());
        forged["state_root"] = json!(external.path().canonicalize().unwrap());
        forged["receipts_root"] = json!(external.path().canonicalize().unwrap());
        rehash_durable_receipt(&mut forged);
        atomic_write_yaml(
            &fixture
                .remote_store
                .receipts_dir()
                .join("escaped-receipt.yaml"),
            &forged,
        )
        .unwrap();
        let receipt_error = command_authority_receipt_rows(
            &fixture.profile,
            &fixture.caller_store,
            &fixture.caller_root,
        )
        .expect_err("an unbound escaped violation receipt must fail before dereference");
        assert!(receipt_error.to_string().contains("escaped-receipt"));
        assert!(!receipt_error.to_string().contains("MUST_NOT_BE_READ.yaml"));
        assert_eq!(fs::read_to_string(&sentinel).unwrap(), ": [\n");
    }

    #[test]
    fn git_common_journal_authority_requires_the_exact_shared_run_store() {
        let mut profile = compiled_research_profile();
        profile.manifest.storage.backend = StorageBackend::GitCommonDir;
        let project = tempfile::tempdir().unwrap();
        ensure_repository_with_head(project.path()).unwrap();
        let git = GitBackend::discover(project.path()).unwrap();
        let run_id = Uuid::now_v7().to_string();
        let store = StateStore::with_storage(
            git.sidecar_path(format!("runs/{run_id}")).unwrap(),
            &profile.manifest.storage,
        )
        .unwrap();
        store.ensure_layout().unwrap();
        let mut manifest = RunManifest::new(
            profile.manifest.profile.id.clone(),
            profile.manifest.profile.version.clone(),
            profile.hash.clone(),
            "Git-common journal authority",
            project.path().to_path_buf(),
        );
        manifest.id = run_id;
        store.write_manifest(&manifest).unwrap();
        let pre = read_only_workspace_fingerprint(project.path(), &profile, store.root()).unwrap();
        let journal_path =
            write_test_command_journal(&store, project.path(), &profile, 50, "prepared", &pre);
        let journal = read_optional_yaml_value(&journal_path).unwrap().unwrap();
        let validated =
            validate_command_attempt_journal_authority(&journal, project.path(), &profile, &store)
                .unwrap();
        assert_eq!(validated.state_root, store.root().canonicalize().unwrap());
        assert_eq!(
            validated.receipts_root,
            store.receipts_dir().canonicalize().unwrap()
        );

        let mut per_worktree = journal;
        per_worktree["state_root"] = json!(project.path().join("program"));
        per_worktree["receipts_root"] = json!(project.path().join("program/receipts"));
        rehash_command_attempt_journal(&mut per_worktree);
        durable_atomic_write_yaml(&journal_path, &per_worktree).unwrap();
        let error = validate_command_attempt_journal_authority(
            &per_worktree,
            project.path(),
            &profile,
            &store,
        )
        .expect_err("Git-common authority must never be substituted with per-worktree state");
        assert!(error.to_string().contains("exact registered Git-common"));
    }

    #[test]
    fn command_terminal_evidence_status_matrix_is_exact() {
        let receipt = |status: &str, attempt: Value| {
            json!({
                "status": status,
                "attempts": [attempt],
            })
        };
        let completed = |exit_code: i64| {
            json!({
                "exit_code": exit_code,
                "timed_out": false,
                "interrupted": false,
                "stdout": "",
                "stderr": "",
            })
        };
        for status in ["passed", "invalid_result"] {
            assert!(command_terminal_evidence_current(
                &receipt(status, completed(0)),
                &[]
            ));
        }
        assert!(command_terminal_evidence_current(
            &receipt("passed", completed(1)),
            &[1]
        ));
        let mut bootstrap_failure = completed(1);
        bootstrap_failure["stderr"] =
            json!("Error: EPERM: process.cwd failed with operation not permitted, uv_cwd");
        assert!(!command_terminal_evidence_current(
            &receipt("passed", bootstrap_failure),
            &[1]
        ));
        let mut startup_failure = completed(1);
        startup_failure["stderr"] = json!("Startup Error: getaddrinfo ENOTFOUND localhost");
        assert!(!command_terminal_evidence_current(
            &receipt("passed", startup_failure),
            &[1]
        ));
        for exit_code in [1, 2] {
            assert!(command_terminal_evidence_current(
                &receipt("failed", completed(exit_code)),
                &[]
            ));
        }
        assert!(command_terminal_evidence_current(
            &receipt(
                "timed_out",
                json!({"exit_code": null, "timed_out": true, "interrupted": false})
            ),
            &[]
        ));
        for status in ["interrupted", "invalid_contract"] {
            assert!(!command_terminal_evidence_current(
                &receipt(
                    status,
                    json!({"exit_code": null, "timed_out": false, "interrupted": true})
                ),
                &[]
            ));
        }
        for malformed in [
            json!({"status": "passed", "attempts": []}),
            receipt("passed", completed(1)),
            receipt("failed", json!({"exit_code": 1, "timed_out": false})),
            receipt(
                "timed_out",
                json!({"exit_code": null, "timed_out": true, "interrupted": true}),
            ),
            receipt("unknown", completed(0)),
            json!({"attempts": [completed(0)]}),
        ] {
            assert!(!command_terminal_evidence_current(&malformed, &[]));
        }
    }

    #[test]
    fn read_only_violation_restore_forces_newer_attempt_then_stays_remediated() {
        let profile = compiled_research_profile();
        let project = tempfile::tempdir().unwrap();
        let store = StateStore::with_storage(
            tracked_state_root(project.path(), &profile),
            &profile.manifest.storage,
        )
        .unwrap();
        store.ensure_layout().unwrap();
        let manifest = RunManifest::new(
            profile.manifest.profile.id.clone(),
            profile.manifest.profile.version.clone(),
            profile.hash.clone(),
            "quarantine regression",
            project.path().to_path_buf(),
        );
        store.write_manifest(&manifest).unwrap();
        fs::write(project.path().join("product.txt"), "before").unwrap();
        ensure_repository_with_head(project.path()).unwrap();

        let pre = read_only_workspace_fingerprint(project.path(), &profile, store.root()).unwrap();
        fs::write(project.path().join("product.txt"), "violating").unwrap();
        let post = read_only_workspace_fingerprint(project.path(), &profile, store.root()).unwrap();
        let changes = workspace_fingerprint_changes(&pre, &post);
        assert!(changes.iter().any(|change| change["path"] == "product.txt"));
        let execution_binding = json!({"test_binding": "violation-v"});
        let execution_binding_hash = normalized_hash(&execution_binding);
        let spawn_binding = json!({"kind": "none", "test_binding": "violation-v"});
        let mut violation = json!({
            "schema_version": "1.0",
            "id": "violation-v",
            "receipt_type": "gate.receipt",
            "check_id": "gate-verifier",
            "process_effect": "read_only",
            "status": "invalid_contract",
            "profile_hash": profile.hash,
            "run_id": manifest.id,
            "workspace_root": project.path().canonicalize().unwrap(),
            "state_root": store.root().canonicalize().unwrap(),
            "receipts_root": store.receipts_dir().canonicalize().unwrap(),
            "command_attempt_sequence": 2,
            "execution_binding": execution_binding,
            "execution_binding_hash": execution_binding_hash,
            "spawn_binding": spawn_binding,
            "attempts": [{
                "attempt": 1,
                "stdout": "",
                "stdout_hash": raw_sha256(b""),
                "stderr": "",
                "stderr_hash": raw_sha256(b""),
            }],
            "workspace_guard": {
                "pre_hash": pre.hash,
                "post_hash": post.hash,
                "changed_paths": workspace_fingerprint_changed_paths(&pre, &post),
                "changes": changes,
                "unchanged": false,
            },
            "receipt_hash": "",
        });
        rehash_durable_receipt(&mut violation);
        assert!(command_receipt_integrity_current(&violation));
        atomic_write_yaml(&store.receipts_dir().join("violation-v.yaml"), &violation).unwrap();
        let authority = command_authority_store(&store, project.path()).unwrap();
        let journal_path = authority
            .work_dir()
            .join("command-journals")
            .join("00000000000000000002.yaml");
        let mut journal = json!({
            "schema_version": "1.0",
            "kind": "compiler.read-only-command-attempt",
            "producer": "compiler.read-only-quarantine",
            "run_id": manifest.id,
            "sequence": 2,
            "status": "completed",
            "check_id": "gate-verifier",
            "profile_hash": profile.hash,
            "workspace_root": project.path().canonicalize().unwrap(),
            "state_root": store.root().canonicalize().unwrap(),
            "receipts_root": store.receipts_dir().canonicalize().unwrap(),
            "execution_binding": execution_binding,
            "execution_binding_hash": execution_binding_hash,
            "spawn_binding": spawn_binding,
            "workspace_pre": pre,
            "workspace_post": post,
            "receipt_id": violation["id"],
            "receipt_hash": violation["receipt_hash"],
            "journal_hash": "",
        });
        rehash_command_attempt_journal(&mut journal);
        durable_atomic_write_yaml(&journal_path, &journal).unwrap();
        assert!(command_attempt_journal_matches_receipt(
            &journal, &violation, &profile
        ));

        let blocked = ensure_global_read_only_quarantine_clear(project.path(), &profile, &store)
            .expect_err("the violating postimage must quarantine compiler authority");
        assert!(blocked.to_string().contains("violation-v"));
        let mut direct_engine = Engine {
            root: project.path().canonicalize().unwrap(),
            profile: profile.clone(),
            store: Some(store.clone()),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let direct_error = direct_engine
            .review_ticket("missing-ticket")
            .expect_err("direct review must not bypass quarantine");
        assert!(direct_error.to_string().contains("quarantined"));

        fs::write(project.path().join("product.txt"), "before").unwrap();
        ensure_global_read_only_quarantine_clear(project.path(), &profile, &store)
            .expect("exact restoration writes a strict remediation record");
        let remediation = command_authority_receipt_rows(&profile, &store, project.path())
            .unwrap()
            .into_iter()
            .find(read_only_remediation_receipt_is_valid)
            .expect("strict remediation receipt");
        assert_eq!(remediation["violation_id"], "violation-v");
        assert_eq!(
            remediation["state_root"],
            store
                .root()
                .canonicalize()
                .unwrap()
                .to_string_lossy()
                .as_ref()
        );
        assert_eq!(
            read_only_violation_watermark(&profile, &store, project.path()).unwrap(),
            Some(2),
            "remediation must not erase violation precedence"
        );

        let mut cache = ExecutionResolutionCache::default();
        let next = next_command_attempt_sequence(&store, project.path(), &mut cache).unwrap();
        assert!(next > 2, "N must be newer than P and V");

        fs::write(
            project.path().join("product.txt"),
            "authorized-later-change",
        )
        .unwrap();
        ensure_global_read_only_quarantine_clear(project.path(), &profile, &store)
            .expect("a later authorized edit must not reopen a remediated historical violation");
    }

    #[test]
    fn required_zero_gate_and_optional_policy_share_one_reversible_readiness_overlay() {
        let mut profile = compiled_research_profile();
        let mut optional = profile.gate_policies["research-capability-gates"].clone();
        optional.id = "optional-capability-gates".to_owned();
        optional.applicability.required_subject_node_types.clear();
        optional.auto_evaluate = None;
        profile.gate_policies.insert(optional.id.clone(), optional);

        let project = tempfile::tempdir().unwrap();
        let store = StateStore::new(project.path().join("program"));
        store.ensure_layout().unwrap();
        let engine = Engine {
            root: project.path().canonicalize().unwrap(),
            profile,
            store: Some(store.clone()),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let mut claim = Node::new(
            "claim",
            "Claim",
            json!({"claim": "bounded", "scope": "test"}),
        );
        claim.id = "claim-required".to_owned();
        claim.extensions.insert(
            "readiness".to_owned(),
            json!({"state": "ready", "reason": "domain baseline"}),
        );
        claim.extensions.insert(
            "obligations".to_owned(),
            json!({"unmet": [{"key": "domain.keep", "severity": "blocking"}]}),
        );
        let mut graph = Graph::default();
        graph.insert(claim).unwrap();

        engine
            .materialize_gate_policy_projections(&mut graph, true, &store)
            .unwrap();
        let claim = graph.node("claim-required").unwrap();
        assert_eq!(
            claim.extensions["compiler"]["gates"]["research-capability-gates"]["state"],
            "missing"
        );
        assert_eq!(
            claim.extensions["compiler"]["gates"]["optional-capability-gates"]["state"],
            "not_applicable"
        );
        assert_eq!(claim.extensions["readiness"]["state"], "blocked");
        assert_eq!(
            claim.extensions["readiness"]["policies"],
            json!(["research-capability-gates"])
        );
        assert_eq!(
            claim.extensions["compiler"]["gate_readiness"]["prior_readiness"],
            json!({"state": "ready", "reason": "domain baseline"})
        );
        let obligations = claim.extensions["obligations"]["unmet"].as_array().unwrap();
        assert!(obligations.iter().any(|row| row["key"] == "domain.keep"));
        assert!(obligations.iter().any(|row| {
            row["policy"] == "research-capability-gates" && row["subject_id"] == "claim-required"
        }));

        engine
            .profile
            .gate_policies
            .get("research-capability-gates")
            .expect("required policy exists");
        let mut no_required = engine.profile.clone();
        no_required
            .gate_policies
            .get_mut("research-capability-gates")
            .unwrap()
            .applicability
            .required_subject_node_types
            .clear();
        let restoring_engine = Engine {
            profile: no_required,
            ..engine
        };
        restoring_engine
            .materialize_gate_policy_projections(&mut graph, true, &store)
            .unwrap();
        let claim = graph.node("claim-required").unwrap();
        assert_eq!(
            claim.extensions["readiness"],
            json!({"state": "ready", "reason": "domain baseline"})
        );
        assert!(claim.extensions["compiler"].get("gate_readiness").is_none());
        let obligations = claim.extensions["obligations"]["unmet"].as_array().unwrap();
        assert_eq!(
            obligations,
            &vec![json!({"key": "domain.keep", "severity": "blocking"})]
        );
    }

    #[test]
    fn scoped_gate_impact_uses_exact_current_and_all_prior_binding_footprints() {
        let profile = compiled_research_profile();
        let project = tempfile::tempdir().unwrap();
        fs::create_dir_all(project.path().join("program/assets/current")).unwrap();
        fs::write(
            project.path().join("program/assets/current/check.py"),
            "print('ok')\n",
        )
        .unwrap();
        let store = StateStore::new(project.path().join("program"));
        store.ensure_layout().unwrap();
        let mut graph = Graph::default();
        let mut hypothesis =
            Node::new("hypothesis", "Hypothesis", json!({"hypothesis": "bounded"}));
        hypothesis.id = "hypothesis-current".to_owned();
        hypothesis.status = "active".to_owned();
        let mut gate = policy_gate("gate-current", "^1.0.0");
        gate.edges
            .insert("applies_to".to_owned(), vec![hypothesis.id.clone()]);
        let mut asset = policy_asset("asset-current", "1.0.0");
        let spec = asset.spec.as_object_mut().unwrap();
        spec.insert(
            "implementation_plan".to_owned(),
            json!({"root": "program/assets/current"}),
        );
        spec.insert(
            "implementation".to_owned(),
            json!({"kind": "script", "entrypoints": ["program/assets/current/check.py"]}),
        );
        spec.insert(
            "gate_contracts".to_owned(),
            json!({"gate-current": {"command": ["python3", "program/assets/current/check.py"]}}),
        );
        graph.insert(hypothesis).unwrap();
        graph.insert(gate).unwrap();
        graph.insert(asset).unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, project.path());
        let current = resolver
            .gate_policy_binding("research-capability-gates", "gate-current")
            .unwrap();
        assert!(current.selection.winner_id.as_deref() == Some("asset-current"));

        let mut prior = current.clone();
        prior.context_read_paths = vec!["program/assets/prior".to_owned()];
        assert!(gate_policy_binding_is_impacted(
            &current,
            &[prior.clone()],
            &BTreeSet::from(["asset-current".to_owned()]),
            &BTreeSet::new(),
        ));
        assert!(gate_policy_binding_is_impacted(
            &current,
            &[prior],
            &BTreeSet::new(),
            &BTreeSet::from(["program/assets/prior/file.py".to_owned()]),
        ));
        assert!(!gate_policy_binding_is_impacted(
            &current,
            &[],
            &BTreeSet::from(["asset-unrelated".to_owned()]),
            &BTreeSet::from(["program/assets/unrelated".to_owned()]),
        ));
    }

    #[test]
    fn active_gate_evaluation_target_cardinality_is_graph_validated() {
        let profile = compiled_research_profile();
        let project = tempfile::tempdir().unwrap();
        let store = StateStore::new(project.path().join("program"));
        store.ensure_layout().unwrap();
        let engine = Engine {
            root: project.path().canonicalize().unwrap(),
            profile,
            store: Some(store),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let mut graph = Graph::default();
        graph
            .insert(policy_gate("gate-cardinality", "^1.0.0"))
            .unwrap();
        let zero = engine.validate_graph(&graph).unwrap();
        assert!(zero.iter().any(|error| {
            error.contains("gate-cardinality") && error.contains("rejected 0 targets")
        }));

        for id in ["hypothesis-a", "hypothesis-b"] {
            let mut hypothesis = Node::new("hypothesis", id, json!({"hypothesis": "bounded"}));
            hypothesis.id = id.to_owned();
            hypothesis.status = "active".to_owned();
            graph.insert(hypothesis).unwrap();
        }
        graph.node_mut("gate-cardinality").unwrap().edges.insert(
            "applies_to".to_owned(),
            vec!["hypothesis-a".to_owned(), "hypothesis-b".to_owned()],
        );
        let two = engine.validate_graph(&graph).unwrap();
        assert!(two.iter().any(|error| {
            error.contains("gate-cardinality") && error.contains("rejected 2 targets")
        }));

        graph
            .node_mut("gate-cardinality")
            .unwrap()
            .edges
            .get_mut("applies_to")
            .unwrap()
            .truncate(1);
        let one = engine.validate_graph(&graph).unwrap();
        assert!(!one.iter().any(|error| error.contains("rejected 1 targets")));
    }

    #[test]
    fn dynamic_command_source_is_graph_validated_as_exact_argv() {
        let mut profile = compiled_updog_profile();
        profile.node_types.get_mut("change").unwrap().fields.insert(
            "test_command".to_owned(),
            serde_yaml::from_str(
                r#"
type: list
required: true
items: {type: string, required: true}
"#,
            )
            .unwrap(),
        );
        let check: crate::config::CheckDef = serde_yaml::from_str(
            r#"
id: expected-red
kind: command
applies_to: []
command_source:
  kind: node
  selection: target
  node_types: [change]
  role: implementation
  field: spec.test_command
cwd: .
timeout_seconds: 30
receipt_type: expected_red
effect: read_only
"#,
        )
        .unwrap();
        profile.checks.insert(check.id.clone(), check);

        let project = tempfile::tempdir().unwrap();
        let store = StateStore::new(project.path().join("program"));
        store.ensure_layout().unwrap();
        let engine = Engine {
            root: project.path().canonicalize().unwrap(),
            profile,
            store: Some(store),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let mut change = Node::new(
            "change",
            "Implement a focused change",
            json!({
                "current_state": "old",
                "target_state": "new",
                "owned_paths": ["src"],
                "blast_radius": "bounded",
                "commit_type": "feat",
                "test_command": ["pnpm --filter books exec vitest run focused.test.ts"]
            }),
        );
        change.id = "change-with-command".to_owned();
        let mut graph = Graph::default();
        graph.insert(change).unwrap();

        let invalid = engine.validate_graph(&graph).unwrap();
        assert!(invalid.iter().any(|error| {
            error.contains("field spec.test_command") && error.contains("not an exact argv array")
        }));

        graph.node_mut("change-with-command").unwrap().spec["test_command"] = json!([
            "pnpm",
            "--filter",
            "books",
            "exec",
            "vitest",
            "run",
            "focused.test.ts"
        ]);
        let valid = engine.validate_graph(&graph).unwrap();
        assert!(
            !valid
                .iter()
                .any(|error| error.contains("field spec.test_command"))
        );
    }

    #[cfg(unix)]
    #[test]
    fn scoped_path_manifests_reject_every_intermediate_symlink_component() {
        use std::os::unix::fs::symlink;

        let temp = tempfile::tempdir().unwrap();
        fs::create_dir_all(temp.path().join("authored/sub")).unwrap();
        fs::write(temp.path().join("authored/sub/file.txt"), "evidence\n").unwrap();
        let regular = BTreeSet::from(["authored/sub/file.txt".to_owned()]);
        assert!(project_read_path_manifest(temp.path(), &regular, &BTreeSet::new()).is_ok());

        symlink("authored", temp.path().join("alias")).unwrap();
        for scoped in ["alias/sub/file.txt", "alias/sub"] {
            let error = project_read_path_manifest(
                temp.path(),
                &BTreeSet::from([scoped.to_owned()]),
                &BTreeSet::new(),
            )
            .expect_err("exact read and scoped-write evidence may not traverse aliases");
            assert!(error.to_string().contains("symlink component"), "{error}");
            let error = project_write_path_manifest(
                temp.path(),
                &BTreeSet::from([scoped.to_owned()]),
                &BTreeSet::new(),
            )
            .expect_err("scoped write prestate may not traverse aliases");
            assert!(error.to_string().contains("symlink component"), "{error}");
        }
        let error = dynamic_path_prestate(temp.path(), &["alias/sub".to_owned()])
            .expect_err("produced-output prestate may not traverse aliases");
        assert!(error.to_string().contains("symlink component"), "{error}");
    }

