    fn report_test_tree(root: &Path) -> BTreeMap<PathBuf, Vec<u8>> {
        if !root.exists() {
            return BTreeMap::new();
        }
        WalkDir::new(root)
            .follow_links(false)
            .into_iter()
            .map(|entry| entry.unwrap())
            .filter(|entry| entry.file_type().is_file())
            .map(|entry| {
                (
                    entry.path().strip_prefix(root).unwrap().to_path_buf(),
                    fs::read(entry.path()).unwrap(),
                )
            })
            .collect()
    }

