    #[test]
    fn report_publication_is_deterministic_and_stops_when_current() {
        let _serial = REPORT_PUBLICATION_TEST_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let (_project, engine) = report_test_engine();
        let store = engine.store().unwrap();

        let published = engine.render_reports().unwrap();
        assert_eq!(published["status"], "published");
        assert_eq!(published["action"], "report");
        let manifest_path = store.reports_dir().join("report-manifest.yaml");
        let manifest: Value = serde_yaml::from_slice(&fs::read(&manifest_path).unwrap()).unwrap();
        for key in [
            "source_graph_hash",
            "source_ticket_board_hash",
            "source_program_state_hash",
            "ledger_hashes",
            "ledger_counts",
            "bundle_hash",
        ] {
            assert!(manifest.get(key).is_some(), "manifest omitted {key}");
        }
        let expected_outputs = engine
            .profile
            .reports
            .values()
            .flat_map(|report| {
                report.formats.iter().map(|format| {
                    normalized_project_path(
                        report_output_path(&engine.root.join(&report.output), *format)
                            .strip_prefix(&engine.root)
                            .unwrap(),
                    )
                })
            })
            .collect::<Vec<_>>();
        assert_eq!(
            manifest["outputs"]
                .as_array()
                .unwrap()
                .iter()
                .map(|value| value.as_str().unwrap().to_owned())
                .collect::<Vec<_>>(),
            expected_outputs
        );
        assert!(
            expected_outputs
                .iter()
                .all(|output| !Path::new(output).is_absolute())
        );

        let mut bundle_contract = BTreeMap::new();
        for report in engine.profile.reports.values() {
            let payload: Value = serde_json::from_slice(
                &fs::read(report_output_path(
                    &engine.root.join(&report.output),
                    crate::config::ReportFormat::Json,
                ))
                .unwrap(),
            )
            .unwrap();
            assert_eq!(
                payload
                    .as_object()
                    .unwrap()
                    .keys()
                    .cloned()
                    .collect::<BTreeSet<_>>(),
                [
                    "schema_version",
                    "report_id",
                    "ledger_id",
                    "kind",
                    "row_count",
                    "ledger_hash",
                    "bundle_hash",
                    "rows",
                ]
                .into_iter()
                .map(ToOwned::to_owned)
                .collect()
            );
            assert_eq!(
                payload["ledger_hash"],
                normalized_hash(payload["rows"].as_array().unwrap())
            );
            bundle_contract.insert(
                report.id.clone(),
                json!({
                    "ledger_hash": payload["ledger_hash"],
                    "row_count": payload["row_count"],
                    "formats": report.formats,
                    "output": normalized_project_path(&report.output),
                }),
            );
        }
        assert_eq!(manifest["bundle_hash"], normalized_hash(&bundle_contract));

        let report_tree = report_test_tree(store.reports_dir());
        let receipt_tree = report_test_tree(store.receipts_dir());
        let snapshot_tree = report_test_tree(&store.root().join("snapshots"));
        let events = fs::read(store.root().join("events.jsonl")).unwrap();
        for bytes in report_tree
            .values()
            .chain(receipt_tree.values())
            .chain(snapshot_tree.values())
        {
            let text = String::from_utf8_lossy(bytes);
            for forbidden in ["created_at", "updated_at", "completed_at", "occurred_at"] {
                assert!(
                    !text.contains(forbidden),
                    "artifact contains {forbidden}: {text}"
                );
            }
        }

        let current = engine.render_reports().unwrap();
        assert_eq!(current["status"], "current");
        assert_eq!(current["action"], "stop");
        assert_eq!(current["reason"], "report-current");
        assert_eq!(report_test_tree(store.reports_dir()), report_tree);
        assert_eq!(report_test_tree(store.receipts_dir()), receipt_tree);
        assert_eq!(
            report_test_tree(&store.root().join("snapshots")),
            snapshot_tree
        );
        assert_eq!(fs::read(store.root().join("events.jsonl")).unwrap(), events);
        assert_eq!(
            String::from_utf8(events)
                .unwrap()
                .lines()
                .filter(|line| line.contains("compiler.report.compiled"))
                .count(),
            1
        );
    }

    #[test]
    fn report_publication_failpoints_restore_the_previous_generation() {
        let _serial = REPORT_PUBLICATION_TEST_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let (_project, engine) = report_test_engine();
        let store = engine.store().unwrap();
        engine.render_reports().unwrap();
        let reports_before = report_test_tree(store.reports_dir());
        let receipts_before = report_test_tree(store.receipts_dir());
        let snapshots_before = report_test_tree(&store.root().join("snapshots"));
        let events_before = fs::read(store.root().join("events.jsonl")).unwrap();

        let mut manifest = store.manifest().unwrap();
        manifest.status = "paused-for-new-report-generation".to_owned();
        store.write_manifest(&manifest).unwrap();
        for failpoint in [
            "after_stage_outputs",
            "after_stage_manifest",
            "after_support_publish",
        ] {
            *REPORT_PUBLICATION_FAILPOINT.lock().unwrap() = Some(failpoint.to_owned());
            let error = engine.render_reports().unwrap_err();
            assert!(error.to_string().contains(failpoint), "{error}");
            assert_eq!(report_test_tree(store.reports_dir()), reports_before);
            assert_eq!(report_test_tree(store.receipts_dir()), receipts_before);
            assert_eq!(
                report_test_tree(&store.root().join("snapshots")),
                snapshots_before
            );
            assert_eq!(
                fs::read(store.root().join("events.jsonl")).unwrap(),
                events_before
            );
            assert!(fs::read_dir(store.root()).unwrap().all(|entry| {
                !entry
                    .unwrap()
                    .file_name()
                    .to_string_lossy()
                    .starts_with(".report-publication-")
            }));
        }
    }

    #[cfg(unix)]
    #[test]
    fn report_publication_rejects_hostile_symlink_components_without_touching_targets() {
        use std::os::unix::fs::symlink;

        let _serial = REPORT_PUBLICATION_TEST_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        for hostile in [
            "transaction-root",
            "receipts-parent",
            "snapshots-parent",
            "events-target",
            "reports-target",
        ] {
            let (_project, engine) = report_test_engine();
            let store = engine.store().unwrap();
            let outside = tempfile::tempdir().unwrap();
            fs::write(outside.path().join("sentinel"), b"untouched").unwrap();
            let hostile_path = match hostile {
                "transaction-root" => report_publication_transaction_root(store.root()),
                "receipts-parent" => store.receipts_dir().to_path_buf(),
                "snapshots-parent" => store.root().join("snapshots"),
                "events-target" => store.root().join("events.jsonl"),
                "reports-target" => store.reports_dir().to_path_buf(),
                _ => unreachable!(),
            };
            if hostile_path.is_dir() {
                fs::remove_dir_all(&hostile_path).unwrap();
            } else if hostile_path.exists() {
                fs::remove_file(&hostile_path).unwrap();
            }
            let target = if hostile == "events-target" {
                outside.path().join("sentinel")
            } else {
                outside.path().to_path_buf()
            };
            symlink(&target, &hostile_path).unwrap();
            let outside_before = report_test_tree(outside.path());

            let error = engine.render_reports().unwrap_err();
            assert!(error.to_string().contains("symlink"), "{hostile}: {error}");
            assert!(
                fs::symlink_metadata(&hostile_path)
                    .unwrap()
                    .file_type()
                    .is_symlink(),
                "{hostile} symlink was replaced"
            );
            assert_eq!(
                report_test_tree(outside.path()),
                outside_before,
                "{hostile} modified the symlink target"
            );
        }
    }

