    #[test]
    fn report_publication_recovers_every_hard_crash_boundary_without_losing_events() {
        let _serial = REPORT_PUBLICATION_TEST_LOCK
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let (_project, engine) = report_test_engine();
        let root = engine.root.clone();
        let store = engine.store().unwrap();
        engine.render_reports().unwrap();

        let phases = [
            "after_journal",
            "after_receipt_install",
            "after_snapshot_install",
            "during_event_append",
            "after_event_append",
            "after_report_backup",
            "after_report_install",
            "after_previous_cleanup",
        ];
        for (index, phase) in phases.into_iter().enumerate() {
            let history_event = Event {
                schema_version: "1.0".to_owned(),
                id: format!("unrelated-history-{index}"),
                event_type: "compiler.unrelated.history".to_owned(),
                at: Utc
                    .with_ymd_and_hms(2025, 2, 1, 0, 0, index as u32)
                    .single()
                    .unwrap(),
                run_id: "run-report-fixture".to_owned(),
                ticket_id: None,
                actor: "compiler".to_owned(),
                data: json!({"sequence": index}),
            };
            let events_path = store.root().join("events.jsonl");
            let mut history_line = serde_json::to_vec(&history_event).unwrap();
            if phase != "during_event_append" {
                history_line.push(b'\n');
            }
            let mut events_file = fs::OpenOptions::new()
                .append(true)
                .open(&events_path)
                .unwrap();
            events_file.write_all(&history_line).unwrap();
            events_file.sync_all().unwrap();
            drop(events_file);
            let events_before = fs::read(&events_path).unwrap();
            let reports_before = report_test_tree(store.reports_dir());

            let mut manifest = store.manifest().unwrap();
            manifest.status = format!("hard-crash-generation-{index}");
            store.write_manifest(&manifest).unwrap();
            let expected = engine.prepare_report_publication().unwrap();
            let mut expected_reports = expected.report_files.clone();
            expected_reports.insert(
                PathBuf::from("report-manifest.yaml"),
                expected.manifest_bytes.clone(),
            );

            let status = Command::new(std::env::current_exe().unwrap())
                .args([
                    "--ignored",
                    "--exact",
                    "engine::tests::report_publication_hard_crash_child",
                    "--nocapture",
                ])
                .env("KONI_REPORT_HARD_CRASH_ROOT", &root)
                .env("KONI_REPORT_HARD_CRASH_PHASE", phase)
                .stdin(Stdio::null())
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .status()
                .unwrap();
            #[cfg(unix)]
            {
                use std::os::unix::process::ExitStatusExt;
                assert_eq!(status.signal(), Some(9), "phase {phase}: {status}");
            }
            #[cfg(not(unix))]
            assert!(!status.success(), "phase {phase} unexpectedly survived");

            let crashed_reports = report_test_tree(store.reports_dir());
            assert!(
                crashed_reports.is_empty()
                    || crashed_reports == reports_before
                    || crashed_reports == expected_reports,
                "phase {phase} exposed a mixed trusted report generation"
            );
            assert!(
                fs::read(&events_path).unwrap().starts_with(&events_before),
                "phase {phase} lost historical events before recovery"
            );

            let reopened = report_test_open_engine(&root);
            let recovered = reopened.render_reports().unwrap();
            assert_eq!(recovered["status"], "current", "phase {phase}");
            let reopened_store = reopened.store().unwrap();
            assert_eq!(
                report_test_tree(reopened_store.reports_dir()),
                expected_reports,
                "phase {phase} published a mixed report generation"
            );
            let events_after = fs::read(reopened_store.root().join("events.jsonl")).unwrap();
            assert!(
                events_after.starts_with(&events_before),
                "phase {phase} rewrote unrelated historical events"
            );
            let parsed_events = String::from_utf8(events_after.clone())
                .unwrap()
                .lines()
                .map(|line| serde_json::from_str::<Value>(line).unwrap())
                .collect::<Vec<_>>();
            assert_eq!(
                parsed_events
                    .iter()
                    .filter(|event| {
                        event["data"]["transaction_hash"]
                            == Value::String(expected.transaction_hash.clone())
                    })
                    .count(),
                1,
                "phase {phase} duplicated its transaction event"
            );
            assert_eq!(
                parsed_events
                    .iter()
                    .filter(|event| event["id"] == history_event.id)
                    .count(),
                1,
                "phase {phase} lost or duplicated unrelated history"
            );
            assert_eq!(
                report_test_tree(reopened_store.receipts_dir()).len(),
                index + 2,
                "phase {phase} duplicated or lost report receipts"
            );
            assert_eq!(
                report_test_tree(&reopened_store.root().join("snapshots")).len(),
                index + 2,
                "phase {phase} duplicated or lost report snapshots"
            );
            assert!(
                !report_publication_transaction_root(reopened_store.root()).exists(),
                "phase {phase} left a recovered journal behind"
            );
        }
    }

    fn policy_gate(id: &str, requirement: &str) -> Node {
        let mut gate = Node::new(
            "gate",
            id,
            json!({
                "capability": {
                    "name": "research.sortedness",
                    "protocol_range": requirement
                }
            }),
        );
        gate.id = id.to_owned();
        gate.status = "active".to_owned();
        gate
    }

    fn policy_asset(id: &str, version: &str) -> Node {
        let mut asset = Node::new(
            "asset",
            id,
            json!({
                "capabilities": [{
                    "name": "research.sortedness",
                    "protocol_version": version
                }]
            }),
        );
        asset.id = id.to_owned();
        asset.status = "active".to_owned();
        asset
    }

    #[test]
    fn gate_capability_contract_uses_full_semver_and_ordered_aliases() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let cases = [
            ("1.2.3", "1.2.3", true),
            ("1.2.3", "1.2.4", false),
            ("^1.2.3", "1.9.0", true),
            ("^1.2.3", "2.0.0", false),
            ("^0.2.3", "0.2.9", true),
            ("^0.2.3", "0.3.0", false),
            ("~1.2.3", "1.2.9", true),
            ("~1.2.3", "1.3.0", false),
            ("1.*", "1.9.7", true),
            ("1.*", "2.0.0", false),
            (">=1.0.0 <2.0.0", "1.8.0", true),
            (">=1.0.0 <2.0.0", "2.0.0", false),
            ("=1.2.3", "1.2.3+build.7", true),
            (">=1.0.0 <2.0.0", "1.1.0-alpha.1", false),
            (">=1.1.0-alpha.1 <2.0.0", "1.1.0-alpha.1", true),
        ];
        for (index, (required, provided, expected)) in cases.into_iter().enumerate() {
            let gate = policy_gate(&format!("gate-{index}"), required);
            let asset = policy_asset(&format!("asset-{index}"), provided);
            let mut graph = Graph::default();
            graph.insert(gate.clone()).unwrap();
            graph.insert(asset.clone()).unwrap();
            let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
            assert_eq!(
                resolver
                    .gate_policy_compatible("research-capability-gates", &gate, &asset,)
                    .unwrap(),
                expected,
                "requirement {required:?}, provided {provided:?}"
            );
        }

        let mut malformed_gate = policy_gate("gate-malformed", "not semver");
        malformed_gate.spec["capability"]["protocol"] = json!(">=1.0.0");
        let asset = policy_asset("asset-valid", "1.2.3");
        let mut graph = Graph::default();
        graph.insert(malformed_gate.clone()).unwrap();
        graph.insert(asset.clone()).unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        let error = resolver
            .gate_policy_compatible("research-capability-gates", &malformed_gate, &asset)
            .unwrap_err();
        assert!(error.to_string().contains("malformed SemVer"), "{error}");

        let gate = policy_gate("gate-alias", ">=1.0.0");
        let mut malformed_provider = policy_asset("asset-alias", "broken");
        malformed_provider.spec["capabilities"][0]["version"] = json!("1.2.3");
        let mut graph = Graph::default();
        graph.insert(gate.clone()).unwrap();
        graph.insert(malformed_provider.clone()).unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        assert!(
            !resolver
                .gate_policy_compatible("research-capability-gates", &gate, &malformed_provider,)
                .unwrap()
        );
    }

    #[test]
    fn gate_policy_ranking_binds_every_reason_and_is_insertion_order_independent() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let gate = policy_gate("gate", ">=1.0.0 <2.0.0");
        let mut candidates = Vec::new();
        let mut contract = policy_asset("z-contract", "1.0.0");
        contract.spec["gate_contracts"] = json!({"\"gate\"": {"command": ["true"]}});
        candidates.push(contract);
        let mut passed = policy_asset("a-passed", "1.0.0");
        passed.spec["gate_results"] = json!({"gate": "failed"});
        passed.spec["spec"] = json!({"gate_results": {"gate": "failed"}});
        passed.spec["capabilities"][0]["gate_results"] = json!({" 'gate' ": "passed"});
        candidates.push(passed);
        let mut targeted = policy_asset("targeted", "1.0.0");
        targeted.spec["target_gate_id"] = json!("gate");
        candidates.push(targeted);
        let mut explicit = policy_asset("explicit", "1.0.0");
        explicit
            .edges
            .insert("validates".to_owned(), vec!["gate".to_owned()]);
        candidates.push(explicit);
        let mut any_result = policy_asset("any-result", "1.0.0");
        any_result.spec["gate_results"] = json!({"gate": "failed"});
        candidates.push(any_result);
        candidates.push(policy_asset("fallback", "1.0.0"));

        let resolve = |items: Vec<Node>| {
            let mut graph = Graph::default();
            graph.insert(gate.clone()).unwrap();
            for item in items {
                graph.insert(item).unwrap();
            }
            let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
            resolver
                .gate_policy_selection_binding("research-capability-gates", "gate")
                .unwrap()
        };
        let forward = resolve(candidates.clone());
        let reverse = resolve(candidates.into_iter().rev().collect());
        assert_eq!(forward.binding_hash, reverse.binding_hash);
        assert_eq!(forward.winner_id.as_deref(), Some("z-contract"));
        assert!(gate_policy_selection_binding_integrity_current(&forward));
        let first_ranks = forward
            .compatible_candidates
            .iter()
            .map(|candidate| (candidate.id.as_str(), candidate.first_matching_rank))
            .collect::<BTreeMap<_, _>>();
        assert_eq!(first_ranks["z-contract"], Some(0));
        assert_eq!(first_ranks["a-passed"], Some(1));
        assert_eq!(first_ranks["targeted"], Some(2));
        assert_eq!(first_ranks["explicit"], Some(3));
        assert_eq!(first_ranks["any-result"], Some(4));
        assert_eq!(first_ranks["fallback"], Some(5));
        assert!(forward.compatible_candidates.iter().all(|candidate| {
            candidate.ranks.len() == 6
                && candidate
                    .ranks
                    .iter()
                    .all(|rank| normalized_hash(&rank.observed) == rank.observed_hash)
        }));

        let mut quoted_override = policy_asset("quoted-override", "1.0.0");
        quoted_override.spec["gate_results"] = json!({"gate": "passed"});
        quoted_override.spec["spec"] = json!({"gate_results": {"\"gate\"": "failed"}});
        let binding = resolve(vec![quoted_override]);
        assert_eq!(
            binding.compatible_candidates[0].first_matching_rank,
            Some(4)
        );
    }

    #[test]
    fn exact_one_policy_distinguishes_zero_one_and_ambiguous_candidates() {
        let mut profile = compiled_research_profile();
        let policy = profile
            .gate_policies
            .get_mut("research-capability-gates")
            .unwrap();
        policy.selection.mode = GateSelectionMode::ExactlyOne;
        policy.selection.ranks.clear();
        policy.selection.tie_break = None;
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        for count in 0..=2 {
            let mut graph = Graph::default();
            graph.insert(policy_gate("gate", ">=1.0.0")).unwrap();
            for index in 0..count {
                graph
                    .insert(policy_asset(&format!("asset-{index}"), "1.0.0"))
                    .unwrap();
            }
            let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
            let binding = resolver
                .gate_policy_selection_binding("research-capability-gates", "gate")
                .unwrap();
            assert_eq!(binding.compatible_candidates.len(), count);
            assert_eq!(binding.winner_id.is_some(), count == 1);
            resolver.bind("target", vec!["gate".to_owned()]);
            let predicate: Predicate = serde_yaml::from_str(&format!(
                "op: gate_policy_candidate_count\ngate_policy: research-capability-gates\ngate_subject: $target\nexact: {count}\n"
            ))
            .unwrap();
            assert!(predicate.evaluate(&resolver).unwrap());
        }
    }

    #[test]
    fn gate_policy_candidate_pool_fails_closed_on_missing_nodes() {
        let mut profile = compiled_research_profile();
        profile
            .gate_policies
            .get_mut("research-capability-gates")
            .unwrap()
            .candidate_pool = serde_yaml::from_str("$candidate_pool").unwrap();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let mut graph = Graph::default();
        graph.insert(policy_gate("gate", ">=1.0.0 <2.0.0")).unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("candidate_pool", vec!["missing-asset".to_owned()]);

        let error = resolver
            .gate_policy_selection_binding("research-capability-gates", "gate")
            .expect_err("a missing configured candidate must never be silently dropped");

        assert!(
            error
                .to_string()
                .contains("candidate_pool selected missing node missing-asset"),
            "{error}"
        );
    }

    #[test]
    fn experiment_portfolio_rule_and_named_gap_remain_open_for_uncovered_claims() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let mut graph = Graph::default();
        let mut hypothesis = Node::new("hypothesis", "Hypothesis", json!({}));
        hypothesis.id = "hypothesis".to_owned();
        hypothesis.edges.insert(
            "claims".to_owned(),
            vec!["claim-a".to_owned(), "claim-b".to_owned()],
        );
        hypothesis
            .edges
            .insert("literature".to_owned(), vec!["literature".to_owned()]);
        hypothesis
            .edges
            .insert("experiments".to_owned(), vec!["experiment".to_owned()]);
        let mut claim_a = Node::new("claim", "Claim A", json!({}));
        claim_a.id = "claim-a".to_owned();
        let mut claim_b = Node::new("claim", "Claim B", json!({}));
        claim_b.id = "claim-b".to_owned();
        let mut experiment = Node::new("experiment", "Experiment", json!({}));
        experiment.id = "experiment".to_owned();
        experiment
            .edges
            .insert("target_claims".to_owned(), vec!["claim-a".to_owned()]);
        let mut literature = Node::new("literature", "Source", json!({}));
        literature.id = "literature".to_owned();
        for node in [hypothesis, claim_a, claim_b, experiment, literature] {
            graph.insert(node).unwrap();
        }
        let rule = &profile.rules["ticket.experiment-portfolio"];
        let gap = profile.checks["gap.experiment-portfolio"]
            .predicate
            .as_ref()
            .unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["hypothesis".to_owned()]);
        assert!(rule.when.evaluate(&resolver).unwrap());
        assert!(gap.evaluate(&resolver).unwrap());

        graph
            .node_mut("experiment")
            .unwrap()
            .edges
            .get_mut("target_claims")
            .unwrap()
            .push("claim-b".to_owned());
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["hypothesis".to_owned()]);
        assert!(!rule.when.evaluate(&resolver).unwrap());
        assert!(!gap.evaluate(&resolver).unwrap());
    }

    #[test]
    fn current_receipt_is_exact_between_connected_gate_nodes() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        install_active_test_run_identity(&store, temp.path(), &profile);
        let mut graph = Graph::default();
        let mut gate_a = Node::new("gate", "Gate A", json!({}));
        gate_a.id = "gate-a".to_owned();
        gate_a
            .edges
            .insert("strengthens".to_owned(), vec!["gate-b".to_owned()]);
        let mut gate_b = Node::new("gate", "Gate B", json!({}));
        gate_b.id = "gate-b".to_owned();
        graph.insert(gate_a).unwrap();
        graph.insert(gate_b).unwrap();
        let receipt = json!({
            "id": "gate-b-receipt",
            "receipt_type": "gate.receipt",
            "status": "passed",
            "recorded_at": "2026-01-01T00:00:00Z",
            "target_node_ids": ["gate-b"],
            "target_hashes": {"gate-b": normalized_hash(graph.node("gate-b").unwrap())}
        });
        atomic_write_yaml(&store.receipts_dir().join("gate-b-receipt.yaml"), &receipt).unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        assert!(
            resolver
                .latest_receipt("gate.receipt", graph.node("gate-a"))
                .unwrap()
                .is_none(),
            "a connected gate's receipt must not satisfy this gate"
        );
        assert!(
            resolver
                .latest_receipt("gate.receipt", graph.node("gate-b"))
                .unwrap()
                .is_some()
        );
    }

    #[test]
    fn changed_scientific_input_makes_current_receipt_false_and_reopens_run_work() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        fs::create_dir_all(temp.path().join("inputs")).unwrap();
        fs::write(
            temp.path().join("inputs/runner.py"),
            concat!(
                "import json\n",
                "print(json.dumps({'schema_version':'1.0',",
                "'protocol':'autoresearch.research-result.v1',",
                "'verdict':'supported','measurements':{'rows':1},",
                "'observations':['ok'],'artifacts':[]}))\n"
            ),
        )
        .unwrap();
        fs::write(temp.path().join("inputs/data.txt"), b"initial input").unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        install_active_test_run_identity(&store, temp.path(), &profile);
        let mut graph = Graph::default();
        let runtime_contract = json!({
            "command": ["python3", "inputs/runner.py", "inputs/data.txt"],
            "composed_verification_command": [
                "python3",
                "-c",
                "import pathlib,sys; [pathlib.Path(path).read_bytes() for path in sys.argv[1:]]",
                "inputs/data.txt"
            ],
            "result_protocol": "autoresearch.research-result.v1",
            "required_measurements": ["rows"],
            "asset_entrypoints": [{"asset_id": "asset", "path": "inputs/runner.py"}],
            "scientific_inputs": [{
                "asset_id": "asset",
                "role": "dataset",
                "path": "inputs/data.txt"
            }]
        });
        let mut run = Node::new("run", "Run", json!({"runtime_contract": runtime_contract}));
        run.id = "run".to_owned();
        run.edges
            .insert("uses".to_owned(), vec!["asset".to_owned()]);
        run.extensions
            .insert("readiness".to_owned(), json!({"state": "ready"}));
        let mut asset = Node::new("asset", "Asset", json!({"revision": 1}));
        asset.id = "asset".to_owned();
        graph.insert(run).unwrap();
        graph.insert(asset).unwrap();
        let ticket = Ticket {
            schema_version: "1.0".to_owned(),
            id: "run-ticket".to_owned(),
            operation: "run-experiment".to_owned(),
            status: "closed".to_owned(),
            title: "Run".to_owned(),
            target_nodes: vec!["run".to_owned()],
            scope: Scope {
                read_nodes: BTreeSet::from(["run".to_owned(), "asset".to_owned()]),
                read_paths: BTreeSet::from(["inputs".to_owned()]),
                ..Scope::default()
            },
            source_state_key: "missing".to_owned(),
            target_state_key: "current".to_owned(),
            obligation_keys: Vec::new(),
            profile_hash: profile.hash.clone(),
            rule_id: "ticket.run-experiment".to_owned(),
            workflow: Vec::new(),
            outputs: Vec::new(),
            reviews: Vec::new(),
            blockers: Vec::new(),
            lease: None,
            change_control: TicketChangeControl::default(),
            extensions: BTreeMap::new(),
        };
        store.write_ticket(&ticket).unwrap();
        for id in ["run", "asset"] {
            graph.save_node(&store.graph_dir(), id).unwrap();
        }
        let engine = Engine {
            root: temp.path().to_path_buf(),
            profile: profile.clone(),
            store: Some(store.clone()),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let receipt = engine
            .run_check(&BTreeMap::from([
                ("check".to_owned(), json!("scientific-runtime")),
                ("ticket".to_owned(), json!(ticket.id)),
            ]))
            .unwrap();
        assert_eq!(receipt["status"], "passed");
        let decorated = load_receipt_rows_with_input_currentness(
            &profile,
            &store,
            temp.path(),
            &graph,
            "runtime.receipt",
        )
        .unwrap();
        assert_eq!(
            decorated[0]["_command_current"],
            true,
            "{}",
            serde_json::to_string_pretty(&decorated[0]).unwrap()
        );
        let run_rule = &profile.rules["ticket.run-experiment"];
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["run".to_owned()]);
        assert!(!run_rule.when.evaluate(&resolver).unwrap());

        fs::write(temp.path().join("inputs/data.txt"), b"changed input").unwrap();
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["run".to_owned()]);
        assert!(run_rule.when.evaluate(&resolver).unwrap());
    }

    #[test]
    fn evidence_work_waits_for_every_exact_run_in_each_claim_portfolio() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let mut graph = Graph::default();
        let mut hypothesis = Node::new("hypothesis", "Hypothesis", json!({}));
        hypothesis.id = "hypothesis".to_owned();
        hypothesis.edges.insert(
            "claims".to_owned(),
            vec!["claim-a".to_owned(), "claim-b".to_owned()],
        );
        hypothesis.edges.insert(
            "experiments".to_owned(),
            vec!["experiment-a".to_owned(), "experiment-b".to_owned()],
        );
        graph.insert(hypothesis).unwrap();
        for suffix in ["a", "b"] {
            let claim_id = format!("claim-{suffix}");
            let experiment_id = format!("experiment-{suffix}");
            let run_id = format!("run-{suffix}");
            let ablation_id = format!("ablation-{suffix}");
            let ablation_run_id = format!("ablation-run-{suffix}");
            let mut claim = Node::new("claim", format!("Claim {suffix}"), json!({}));
            claim.id = claim_id.clone();
            let mut experiment = Node::new("experiment", format!("Experiment {suffix}"), json!({}));
            experiment.id = experiment_id;
            experiment.edges.insert("tests".to_owned(), vec![claim_id]);
            experiment
                .edges
                .insert("runs".to_owned(), vec![run_id.clone()]);
            experiment
                .edges
                .insert("ablations".to_owned(), vec![ablation_id.clone()]);
            let mut run = Node::new("run", format!("Run {suffix}"), json!({}));
            run.id = run_id;
            let mut ablation = Node::new("ablation", format!("Ablation {suffix}"), json!({}));
            ablation.id = ablation_id;
            ablation
                .edges
                .insert("runs".to_owned(), vec![ablation_run_id.clone()]);
            let mut ablation_run = Node::new("run", format!("Ablation run {suffix}"), json!({}));
            ablation_run.id = ablation_run_id;
            for node in [claim, experiment, run, ablation, ablation_run] {
                graph.insert(node).unwrap();
            }
        }
        write_bound_runtime_fixture_receipt(
            &profile,
            temp.path(),
            &store,
            &mut graph,
            "run-a",
            "run-a-receipt",
            "2026-01-01T00:00:00Z",
        );
        write_bound_runtime_fixture_receipt(
            &profile,
            temp.path(),
            &store,
            &mut graph,
            "ablation-run-a",
            "ablation-run-a-receipt",
            "2026-01-01T00:00:01Z",
        );
        let rule = &profile.rules["ticket.synthesize-evidence"];
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["claim-a".to_owned()]);
        assert!(
            !rule.when.evaluate(&resolver).unwrap(),
            "hypothesis-wide evidence waits for claim B's experiment and ablation runs"
        );
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["claim-b".to_owned()]);
        assert!(
            !rule.when.evaluate(&resolver).unwrap(),
            "claim A's connected receipt must not emit evidence work for claim B"
        );
        write_bound_runtime_fixture_receipt(
            &profile,
            temp.path(),
            &store,
            &mut graph,
            "run-b",
            "run-b-receipt",
            "2026-01-01T00:00:02Z",
        );
        write_bound_runtime_fixture_receipt(
            &profile,
            temp.path(),
            &store,
            &mut graph,
            "ablation-run-b",
            "ablation-run-b-receipt",
            "2026-01-01T00:00:03Z",
        );
        for claim_id in ["claim-a", "claim-b"] {
            let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
            resolver.bind("target", vec![claim_id.to_owned()]);
            assert!(rule.when.evaluate(&resolver).unwrap());
        }
    }

    #[test]
    fn superseding_source_receipt_reopens_synthesis_for_promoted_evidence() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let mut graph = Graph::default();
        let mut hypothesis = Node::new("hypothesis", "Hypothesis", json!({}));
        hypothesis.id = "hypothesis".to_owned();
        hypothesis
            .edges
            .insert("claims".to_owned(), vec!["claim".to_owned()]);
        hypothesis
            .edges
            .insert("experiments".to_owned(), vec!["experiment".to_owned()]);
        let mut claim = Node::new("claim", "Claim", json!({}));
        claim.id = "claim".to_owned();
        let mut experiment = Node::new("experiment", "Experiment", json!({}));
        experiment.id = "experiment".to_owned();
        experiment
            .edges
            .insert("tests".to_owned(), vec!["claim".to_owned()]);
        experiment
            .edges
            .insert("runs".to_owned(), vec!["run".to_owned()]);
        experiment
            .edges
            .insert("ablations".to_owned(), vec!["ablation".to_owned()]);
        let mut ablation = Node::new("ablation", "Ablation", json!({}));
        ablation.id = "ablation".to_owned();
        ablation
            .edges
            .insert("runs".to_owned(), vec!["run".to_owned()]);
        let mut run = Node::new("run", "Run", json!({}));
        run.id = "run".to_owned();
        let mut evidence = Node::new(
            "evidence",
            "Evidence",
            json!({
                "promotion_state": "lead-promoted",
                "promoted_by": "lead",
                "promotion_review_id": "review",
                "receipt_refs": ["receipt-1"],
                "run_dispositions": {
                    "run": {
                        "disposition": "supports",
                        "receipt_id": "receipt-1",
                        "rationale": "The current observation supports the bounded claim."
                    }
                }
            }),
        );
        evidence
            .edges
            .insert("from_runs".to_owned(), vec!["run".to_owned()]);
        evidence
            .edges
            .insert("supports".to_owned(), vec!["claim".to_owned()]);
        for node in [hypothesis, claim, experiment, ablation, run, evidence] {
            graph.insert(node).unwrap();
        }
        write_bound_runtime_fixture_receipt(
            &profile,
            temp.path(),
            &store,
            &mut graph,
            "run",
            "receipt-1",
            "2026-01-01T00:00:00Z",
        );
        let rule = &profile.rules["ticket.synthesize-evidence"];
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["claim".to_owned()]);
        assert!(
            !rule.when.evaluate(&resolver).unwrap(),
            "current promoted evidence closes synthesis"
        );

        write_bound_runtime_fixture_receipt(
            &profile,
            temp.path(),
            &store,
            &mut graph,
            "run",
            "receipt-2",
            "2026-01-02T00:00:00Z",
        );
        let resolver = GraphResolver::new(&graph, &profile, &store, temp.path());
        resolver.bind("target", vec!["claim".to_owned()]);
        assert!(
            rule.when.evaluate(&resolver).unwrap(),
            "a newer exact source receipt makes the old promoted evidence stale and reopens synthesis"
        );
    }

    fn write_bound_runtime_fixture_receipt(
        profile: &CompiledProfile,
        root: &Path,
        store: &StateStore,
        graph: &mut Graph,
        run_id: &str,
        receipt_id: &str,
        recorded_at: &str,
    ) {
        install_active_test_run_identity(store, root, profile);
        fs::create_dir_all(root.join("inputs")).unwrap();
        fs::write(root.join("inputs/data.txt"), b"deterministic input").unwrap();
        let asset_id = "fixture-runtime-asset";
        if graph.node(asset_id).is_none() {
            let mut asset = Node::new("asset", "Fixture runtime asset", json!({"revision": 1}));
            asset.id = asset_id.to_owned();
            graph.insert(asset).unwrap();
        }
        let run = graph.node_mut(run_id).expect("fixture run exists");
        run.spec["runtime_contract"] = json!({
            "command": [
                "python3",
                "-c",
                "import json; print(json.dumps({'schema_version':'1.0','protocol':'autoresearch.research-result.v1','verdict':'supported','measurements':{'rows':1},'observations':[],'artifacts':[]}))",
                "inputs/data.txt"
            ],
            "result_protocol": "autoresearch.research-result.v1",
            "required_measurements": ["rows"],
            "asset_entrypoints": [{"asset_id": asset_id, "path": "inputs/data.txt"}],
            "scientific_inputs": [{
                "asset_id": asset_id,
                "role": "fixture",
                "path": "inputs/data.txt"
            }]
        });
        let uses = run.edges.entry("uses".to_owned()).or_default();
        if !uses.iter().any(|id| id == asset_id) {
            uses.push(asset_id.to_owned());
        }
        graph.save_node(&store.graph_dir(), asset_id).unwrap();
        graph.save_node(&store.graph_dir(), run_id).unwrap();
        let ticket_id = format!("fixture-{run_id}");
        let ticket = Ticket {
            schema_version: "1.0".to_owned(),
            id: ticket_id.clone(),
            operation: "run-experiment".to_owned(),
            status: "closed".to_owned(),
            title: format!("Fixture runtime for {run_id}"),
            target_nodes: vec![run_id.to_owned()],
            scope: Scope {
                read_nodes: BTreeSet::from([run_id.to_owned(), asset_id.to_owned()]),
                write_nodes: BTreeSet::from([run_id.to_owned()]),
                read_paths: BTreeSet::from(["inputs".to_owned()]),
                write_paths: BTreeSet::new(),
            },
            source_state_key: "missing".to_owned(),
            target_state_key: "current".to_owned(),
            obligation_keys: vec!["run.receipt".to_owned()],
            profile_hash: profile.hash.clone(),
            rule_id: "ticket.run-experiment".to_owned(),
            workflow: Vec::new(),
            outputs: Vec::new(),
            reviews: Vec::new(),
            blockers: Vec::new(),
            lease: None,
            change_control: TicketChangeControl::default(),
            extensions: BTreeMap::from([(
                "operation_registry_id".to_owned(),
                json!("execution.run.run-experiment"),
            )]),
        };
        store.write_ticket(&ticket).unwrap();
        let engine = Engine {
            root: root.to_path_buf(),
            profile: profile.clone(),
            store: Some(store.clone()),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let mut receipt = engine
            .run_check(&BTreeMap::from([
                ("check".to_owned(), json!("scientific-runtime")),
                ("ticket".to_owned(), json!(ticket_id)),
            ]))
            .unwrap();
        let generated_id = receipt["id"].as_str().unwrap().to_owned();
        fs::remove_file(store.receipts_dir().join(format!("{generated_id}.yaml"))).unwrap();
        receipt["id"] = json!(receipt_id);
        receipt["recorded_at"] = json!(recorded_at);
        rehash_command_receipt(&mut receipt);
        atomic_write_yaml(
            &store.receipts_dir().join(format!("{receipt_id}.yaml")),
            &receipt,
        )
        .unwrap();
    }

    #[test]
    fn rendered_worker_prompt_copies_context_eof_and_adaptive_read_discipline() {
        let preserved = "Use only an exact issued file path. Call submit_and_compile at the terminal boundary. Submit graph changes only through the compiler-owned graph_delta.";
        let protocol = worker_protocol_with_context_read_discipline(preserved.to_owned(), true);
        let prompt = render_agent_assignment_prompt(
            "Implementer persona",
            "Implement the assigned step.",
            "",
            "",
            "Ticket read paths: {src/lib.rs}",
            &protocol,
        );
        for required in [
            "Context is complete only when `eof` is true",
            "Observe each successful context result before issuing another call",
            "exact `document_path`",
            "each returned `next_offset`",
            "at least 32768 `max_bytes`",
            "observing every returned page before the next call",
            "search first and read only the required region",
            "do not search it again merely to relocate text",
            "exact issued file path",
            "submit_and_compile",
            "compiler-owned graph_delta",
        ] {
            assert!(prompt.contains(required), "missing `{required}`: {prompt}");
        }
        assert_eq!(
            worker_protocol_with_context_read_discipline(LEAD_BROKER_PROTOCOL.to_owned(), false),
            LEAD_BROKER_PROTOCOL,
            "Lead prompt semantics must not inherit worker product-read policy"
        );
    }

