    #[test]
    fn run_token_usage_aggregates_completed_codex_turns_without_double_counting_breakdowns() {
        let temp = tempfile::tempdir().unwrap();
        let state_root = temp.path().join("state");
        let control_root = temp.path().join("control");
        let worker_log = state_root.join("work/tickets/TK-1/worker.log");
        let planning_log = control_root.join("agents/planner/attempt-1/stdout.jsonl");
        fs::create_dir_all(worker_log.parent().unwrap()).unwrap();
        fs::create_dir_all(planning_log.parent().unwrap()).unwrap();
        fs::write(
            &worker_log,
            concat!(
                "ordinary stderr text\n",
                "{\"type\":\"turn.completed\",\"usage\":{\"input_tokens\":1000,\"cached_input_tokens\":800,\"output_tokens\":100,\"reasoning_output_tokens\":50}}\n",
                "{\"type\":\"planning.agent.event\",\"event\":{\"type\":\"turn.completed\",\"usage\":{\"input_tokens\":999999,\"output_tokens\":999999}}}\n",
                "{unfinished\n"
            ),
        )
        .unwrap();
        fs::write(
            &planning_log,
            concat!(
                "{\"type\":\"turn.started\"}\n",
                "{\"type\":\"turn.completed\",\"usage\":{\"input_tokens\":250,\"cached_input_tokens\":125,\"output_tokens\":25,\"reasoning_output_tokens\":10}}\n"
            ),
        )
        .unwrap();

        let expected = RunTokenUsage {
            input_tokens: 1_250,
            cached_input_tokens: 925,
            output_tokens: 125,
            reasoning_output_tokens: 60,
            total_tokens: 1_375,
            new_tokens: 450,
            completed_turns: 2,
        };
        assert_eq!(
            run_token_usage(&state_root.join("work"), &control_root),
            expected
        );
        assert_eq!(
            run_token_usage(&state_root.join("work"), &control_root),
            expected,
            "an unchanged cockpit refresh must reuse the per-log usage cache"
        );

        writeln!(
            fs::OpenOptions::new()
                .append(true)
                .open(&worker_log)
                .unwrap(),
            "{{\"type\":\"turn.completed\",\"usage\":{{\"input_tokens\":20,\"output_tokens\":5}}}}"
        )
        .unwrap();
        assert_eq!(
            run_token_usage(&state_root.join("work"), &control_root),
            RunTokenUsage {
                input_tokens: 1_270,
                cached_input_tokens: 925,
                output_tokens: 130,
                reasoning_output_tokens: 60,
                total_tokens: 1_400,
                new_tokens: 475,
                completed_turns: 3,
            },
            "an appended model turn must invalidate only its changed log"
        );
    }

