    #[test]
    fn run_token_usage_matches_compact_preserved_run_arithmetic() {
        use std::fmt::Write as _;

        fn partition(total: u64, count: usize, index: usize) -> u64 {
            total / count as u64 + u64::from(index < (total % count as u64) as usize)
        }

        fn pi_checkpoints(
            prefix: &str,
            count: usize,
            total: u64,
            cached: u64,
            output: u64,
            reasoning: u64,
        ) -> String {
            (0..count)
                .map(|index| {
                    let total = partition(total, count, index);
                    let cached = partition(cached, count, index);
                    let output = partition(output, count, index);
                    let reasoning = partition(reasoning, count, index);
                    format!(
                        "{}\n",
                        json!({
                            "type": "pi.turn_usage",
                            "runtime": "pi-sdk",
                            "turn_id": format!("{prefix}-{index}"),
                            "usage": {
                                "input_tokens": total.saturating_sub(cached).saturating_sub(output),
                                "cached_input_tokens": cached,
                                "output_tokens": output,
                                "reasoning_tokens": reasoning,
                                "total_tokens": total,
                            }
                        })
                    )
                })
                .collect()
        }

        fn native_terminals(
            count: usize,
            input: u64,
            cached: u64,
            output: u64,
            reasoning: u64,
        ) -> String {
            (0..count)
                .map(|index| {
                    format!(
                        "{}\n",
                        json!({
                            "type": "turn.completed",
                            "usage": {
                                "input_tokens": partition(input, count, index),
                                "cached_input_tokens": partition(cached, count, index),
                                "output_tokens": partition(output, count, index),
                                "reasoning_output_tokens": partition(reasoning, count, index),
                            }
                        })
                    )
                })
                .collect()
        }

        let temp = tempfile::tempdir().unwrap();
        let work_root = temp.path().join("state/work");
        let control_root = temp.path().join("control");
        let planning = control_root.join("agents/planning-plan/attempt-1/stdout.jsonl");
        let review = control_root.join("agents/reviewer/attempt-1/stdout.jsonl");
        let lead = work_root.join("tickets/TK-1/lead/slices/1/worker.lead-slice.attempt-1.log");
        let worker = work_root.join("tickets/TK-1/worker.worker-main.attempt-1.log");
        for path in [&planning, &review, &lead, &worker] {
            fs::create_dir_all(path.parent().unwrap()).unwrap();
        }
        fs::write(
            planning,
            pi_checkpoints("planning", 2, 434_867, 333_312, 25_425, 20_000),
        )
        .unwrap();
        fs::write(
            review,
            native_terminals(5, 248_128, 120_832, 17_708, 10_000),
        )
        .unwrap();
        fs::write(lead, pi_checkpoints("lead", 1, 69_687, 0, 5_000, 5_000)).unwrap();
        let mut worker_log = pi_checkpoints("worker", 68, 5_736_322, 4_672_000, 69_193, 29_317);
        for index in 0..7 {
            writeln!(
                worker_log,
                "{}",
                json!({
                    "type": "pi.event",
                    "runtime": "pi-sdk",
                    "event": {
                        "event": "usage",
                        "turn_id": format!("partial-{index}"),
                        "usage": {
                            "input_tokens": 1,
                            "cached_input_tokens": 0,
                            "output_tokens": 0,
                            "reasoning_tokens": 0,
                            "total_tokens": 1,
                        }
                    }
                })
            )
            .unwrap();
        }
        fs::write(worker, worker_log).unwrap();

        assert_eq!(
            run_token_usage(&work_root, &control_root),
            RunTokenUsage {
                input_tokens: 6_389_393,
                cached_input_tokens: 5_126_144,
                output_tokens: 117_326,
                reasoning_output_tokens: 64_317,
                total_tokens: 6_506_719,
                new_tokens: 1_380_575,
                completed_turns: 76,
            },
            "the compact fixture preserves the paused acceptance run's category totals, 76 terminal/checkpoint turns, and seven additional partial turns"
        );
    }

