    fn direct_pi_planning_budget_treats_fifteen_as_exhausted_and_sixteen_as_runnable() {
        let policy = RunPlanningPolicy {
            session_scope: PlanningSessionScope::Run,
            graph_seed_stage: None,
            max_repository_tool_calls: 32,
            token_budget: crate::catalog::PlanningTokenBudget {
                metric: PlanningTokenMetric::NewTokens,
                limit: 100,
                synthesis_reserve: 20,
                on_exhausted: PlanningBudgetExhaustion::ForceSynthesis,
            },
        };
        assert!(
            direct_pi_planning_budget(
                &policy,
                RunTokenUsage {
                    new_tokens: 85,
                    ..Default::default()
                }
            )
            .is_err()
        );
        assert_eq!(
            direct_pi_planning_budget(
                &policy,
                RunTokenUsage {
                    new_tokens: 84,
                    ..Default::default()
                }
            )
            .unwrap(),
            (16, true)
        );
    }

