    #[test]
    fn failed_budget_synthesis_can_recover_its_exact_schema_valid_plan() {
        let output = json!({
            "kind": "plan",
            "plan": "Preserve legacy behavior and add the five optional fields.",
            "review": {
                "architecture": [{
                    "heading": "Shared contract",
                    "description": "One contract drives every surface."
                }],
                "risk": null,
                "verification": null
            },
            "graph_seed": null,
            "prompt": null,
            "context": null,
            "impact": null,
            "options": null,
            "questions": null
        })
        .to_string();
        let session: PlanningSessionState = serde_json::from_value(json!({
            "schema_version": "1.0",
            "run_id": "run-1",
            "session_id": "session-1",
            "session_scope": "run",
            "budget_metric": "new_tokens",
            "budget_limit": 250000,
            "synthesis_reserve": 50000,
            "on_exhausted": "force_synthesis",
            "usage": {
                "input_tokens": 400000,
                "cached_input_tokens": 100000,
                "output_tokens": 10000,
                "reasoning_output_tokens": 5000,
                "total_tokens": 410000,
                "new_tokens": 310000
            },
            "synthesis_forced": true,
            "synthesis_only": true,
            "completed_turns": 2,
            "last_stage_id": "focused-plan",
            "updated_at": "2026-07-14T00:00:00Z"
        }))
        .unwrap();
        let record: AgentSessionRecord = serde_json::from_value(json!({
            "schema_version": "1.0",
            "id": "planning-focused-plan",
            "run_id": "run-1",
            "stage_id": "focused-plan",
            "persona": "run-planner",
            "status": "failed",
            "attempt": 2,
            "codex_session_id": "session-1",
            "input_hash": "sha256:revision",
            "exit_code": null,
            "timed_out": false,
            "updated_at": "2026-07-14T00:00:00Z"
        }))
        .unwrap();
        let events = vec![
            json!({
                "type": "item.completed",
                "item": {"type": "agent_message", "text": output}
            }),
            json!({
                "type": "turn.finished",
                "status": "interrupted",
                "usage": {"new_tokens": 310000}
            }),
        ];

        let recovered = recoverable_budget_exhausted_synthesis_plan(
            &session,
            &record,
            "sha256:revision",
            "focused-plan",
            &events,
            events[0]["item"]["text"].as_str().unwrap(),
        )
        .unwrap()
        .expect("the compiler should adopt the exact completed synthesis artifact");

        assert!(recovered.0.contains("five optional fields"));
        assert_eq!(
            recovered.1.unwrap().architecture.unwrap(),
            PlanningReviewSection::Items(vec![PlanningReviewItem {
                heading: "Shared contract".to_owned(),
                description: "One contract drives every surface.".to_owned(),
            }])
        );
        assert!(recovered.2.is_none());
    }

