    #[test]
    fn planning_output_keeps_the_full_plan_separate_from_the_operator_review() {
        let output = json!({
            "kind": "plan",
            "plan": "Complete implementation detail for compiler and execution agents.",
            "review": {
                "architecture": [
                    {"heading": "Shared contract", "description": "Change the shared contract."},
                    {"heading": "Compatibility", "description": "Preserve existing consumers."}
                ],
                "risk": [
                    {"heading": "Legacy data", "description": "Roll back on legacy-data drift."}
                ],
                "verification": [
                    {"heading": "Focused and live proof", "description": "Run focused and end-to-end checks."}
                ]
            },
            "graph_seed": null,
            "prompt": null,
            "context": null,
            "impact": null,
            "options": null,
            "questions": null
        });
        let schema = planning_agent_output_schema();
        let validator = jsonschema::validator_for(&schema).unwrap();
        assert!(validator.is_valid(&output));
        let mut missing_review = output.clone();
        missing_review.as_object_mut().unwrap().remove("review");
        assert!(!validator.is_valid(&missing_review));
        let parsed = parse_planning_agent_output(&output.to_string()).unwrap();
        let PlanningAgentOutputEnvelope::Plan { plan, review, .. } = parsed else {
            panic!("expected a completed plan");
        };
        assert!(plan.contains("Complete implementation detail"));
        let review = review.expect("new planning output should preserve its review");
        assert_eq!(
            review.architecture,
            Some(PlanningReviewSection::Items(vec![
                PlanningReviewItem {
                    heading: "Shared contract".to_owned(),
                    description: "Change the shared contract.".to_owned(),
                },
                PlanningReviewItem {
                    heading: "Compatibility".to_owned(),
                    description: "Preserve existing consumers.".to_owned(),
                },
            ]))
        );
        assert_eq!(
            review.risk,
            Some(PlanningReviewSection::Items(vec![PlanningReviewItem {
                heading: "Legacy data".to_owned(),
                description: "Roll back on legacy-data drift.".to_owned(),
            }]))
        );
        assert_eq!(
            review.verification,
            Some(PlanningReviewSection::Items(vec![PlanningReviewItem {
                heading: "Focused and live proof".to_owned(),
                description: "Run focused and end-to-end checks.".to_owned(),
            }]))
        );

        let mut oversized_plan = output.clone();
        oversized_plan["plan"] = json!("x".repeat(MAX_PLANNING_PLAN_CHARS + 1));
        assert!(!validator.is_valid(&oversized_plan));
        let error = parse_planning_agent_output(&oversized_plan.to_string())
            .expect_err("the execution plan must share its downstream artifact bound")
            .to_string();
        assert!(error.contains("plan exceeds"), "{error}");

        let mut oversized_response = output.clone();
        oversized_response["graph_seed"] = json!({
            "root_spec": {"planning_context": "x".repeat(MAX_PLANNING_RESPONSE_BYTES)},
            "nodes": [],
            "edges": []
        });
        let error = parse_planning_agent_output(&oversized_response.to_string())
            .expect_err("the complete planning response must remain bounded")
            .to_string();
        assert!(error.contains("planning agent response exceeds"), "{error}");

        let oversized = json!({
            "kind": "plan",
            "plan": "Full plan remains valid.",
            "review": {
                "architecture": "x".repeat(MAX_PLANNING_REVIEW_SECTION_CHARS + 1),
                "risk": null,
                "verification": null
            }
        });
        let error = parse_planning_agent_output(&oversized.to_string())
            .expect_err("operator summaries must remain bounded")
            .to_string();
        assert!(error.contains("architecture summary exceeds"), "{error}");

        let legacy =
            parse_planning_agent_output(r#"{"kind":"plan","plan":"Legacy in-flight full plan"}"#)
                .expect("an agent launched before the schema upgrade must remain readable");
        assert!(matches!(
            legacy,
            PlanningAgentOutputEnvelope::Plan { review: None, .. }
        ));
    }

    #[test]
    fn planning_graph_seed_uses_bounded_local_keys_and_strict_references() {
        let seed = PlanningGraphSeed {
            root_spec: Map::from_iter([(
                "success_signals".to_owned(),
                json!(["The focused behavior is covered."]),
            )]),
            nodes: vec![PlanningGraphSeedNode {
                key: "shared-contract".to_owned(),
                node_type: "contract".to_owned(),
                title: "Shared behavior contract".to_owned(),
                spec: json!({
                    "invariant": "Every surface observes one behavior.",
                    "enforcement_point": "The shared package.",
                    "failure_meaning": "Surfaces drift."
                }),
            }],
            edges: vec![PlanningGraphSeedEdge {
                source: "$root".to_owned(),
                relation: "contracts".to_owned(),
                target: "shared-contract".to_owned(),
            }],
        };
        validate_planning_graph_seed_shape(&seed).unwrap();
        assert_eq!(
            planning_seed_node_id("run-one", "shared-contract"),
            planning_seed_node_id("run-one", "shared-contract")
        );
        assert_ne!(
            planning_seed_node_id("run-one", "shared-contract"),
            planning_seed_node_id("run-two", "shared-contract")
        );

        let mut duplicate = seed.clone();
        duplicate.nodes.push(duplicate.nodes[0].clone());
        assert!(
            validate_planning_graph_seed_shape(&duplicate)
                .unwrap_err()
                .to_string()
                .contains("repeats node key")
        );
        let mut dangling = seed;
        dangling.edges[0].target = "missing".to_owned();
        assert!(
            validate_planning_graph_seed_shape(&dangling)
                .unwrap_err()
                .to_string()
                .contains("unknown local key")
        );

        let empty = PlanningGraphSeed {
            root_spec: Map::new(),
            nodes: Vec::new(),
            edges: Vec::new(),
        };
        assert!(
            validate_planning_graph_seed_shape(&empty)
                .unwrap_err()
                .to_string()
                .contains("must enrich the root or add")
        );

        let disconnected = PlanningGraphSeed {
            root_spec: Map::new(),
            nodes: vec![PlanningGraphSeedNode {
                key: "orphan".to_owned(),
                node_type: "contract".to_owned(),
                title: "Orphan contract".to_owned(),
                spec: json!({}),
            }],
            edges: Vec::new(),
        };
        assert!(
            validate_planning_graph_seed_shape(&disconnected)
                .unwrap_err()
                .to_string()
                .contains("disconnected from $root")
        );
    }

    #[test]
    fn approved_planning_seed_materializes_deterministic_profile_valid_nodes() {
        let mut profile = compiled_updog_profile();
        let mut seed_operation = profile.operations["architecture.objective.map"].clone();
        seed_operation.id = "initialization.objective.seed-approved-plan".to_owned();
        seed_operation.operation = "seed-approved-plan".to_owned();
        seed_operation.workflow = None;
        seed_operation.allowed_new_node_types = vec!["contract".to_owned()];
        seed_operation.allowed_existing_node_types = vec!["objective".to_owned()];
        seed_operation.max_new_nodes = Some(64);
        seed_operation.checks.clear();
        seed_operation.review_effects.clear();
        seed_operation.receipt_coverage = None;
        seed_operation.change_control_barrier = false;
        seed_operation.allow_node_deletion = false;
        seed_operation.allow_edge_deletion = false;
        seed_operation.allow_gate_contract_edits = false;
        seed_operation.terminal_resolver = false;
        profile
            .operations
            .insert(seed_operation.id.clone(), seed_operation);
        profile.manifest.initialization.planning_seed_operation =
            Some("initialization.objective.seed-approved-plan".to_owned());
        profile
            .node_types
            .get_mut("contract")
            .unwrap()
            .compiler_owned_fields
            .push("spec.observability".to_owned());
        let temp = tempfile::tempdir().unwrap();
        let store =
            StateStore::with_storage(temp.path().join("run"), &profile.manifest.storage).unwrap();
        store.ensure_layout().unwrap();
        let mut manifest = RunManifest::new(
            &profile.manifest.profile.id,
            &profile.manifest.profile.version,
            &profile.hash,
            "Keep every surface on one shared behavior contract",
            temp.path().to_path_buf(),
        );
        manifest.id = "run-seed-materialization".to_owned();
        store.write_manifest(&manifest).unwrap();
        let mut engine = Engine {
            root: temp.path().to_path_buf(),
            profile,
            store: Some(store.clone()),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let seed = PlanningGraphSeed {
            root_spec: Map::from_iter([(
                "success_signals".to_owned(),
                json!(["Every configured surface remains consistent."]),
            )]),
            nodes: vec![PlanningGraphSeedNode {
                key: "shared-contract".to_owned(),
                node_type: "contract".to_owned(),
                title: "Shared surface behavior".to_owned(),
                spec: json!({
                    "invariant": "All surfaces use the same behavior contract.",
                    "enforcement_point": "The shared package boundary.",
                    "failure_meaning": "Surfaces expose incompatible behavior."
                }),
            }],
            edges: vec![PlanningGraphSeedEdge {
                source: "$root".to_owned(),
                relation: "contracts".to_owned(),
                target: "shared-contract".to_owned(),
            }],
        };
        let context = ApprovedPlanningContext::new(Vec::new(), Vec::new(), 0, Some(seed), None);
        let graph = engine
            .build_initial_graph(&manifest, Some(&context))
            .unwrap();
        assert!(engine.validate_graph(&graph).unwrap().is_empty());
        let root_id = planning_seed_node_id(&manifest.id, "$root");
        let contract_id = planning_seed_node_id(&manifest.id, "shared-contract");
        assert_eq!(
            graph.node(&root_id).unwrap().edges["contracts"],
            vec![contract_id.clone()]
        );
        assert_eq!(graph.node(&contract_id).unwrap().node_type, "contract");
        assert_eq!(graph.node(&contract_id).unwrap().status, "draft");
        assert_eq!(
            graph.node(&root_id).unwrap().spec["success_signals"],
            json!(["Every configured surface remains consistent."])
        );

        let root_only = engine.build_initial_graph(&manifest, None).unwrap();
        persist_graph_atomically(&store.graph_dir(), &root_only).unwrap();
        engine
            .ensure_approved_run_state(&manifest, Some(&context))
            .unwrap();
        let initialized = store.graph().unwrap();
        assert!(initialized.node(&contract_id).is_some());
        assert_eq!(
            store
                .events()
                .unwrap()
                .iter()
                .filter(|event| event.event_type == "compiler.run.initialized")
                .count(),
            1
        );
        engine
            .ensure_approved_run_state(&manifest, Some(&context))
            .unwrap();
        assert_eq!(
            store
                .events()
                .unwrap()
                .iter()
                .filter(|event| event.event_type == "compiler.run.initialized")
                .count(),
            1,
            "approved initialization replay must not duplicate its receipt"
        );
        fs::write(store.root().join("events.jsonl"), "").unwrap();
        engine
            .ensure_approved_run_state(&manifest, Some(&context))
            .unwrap();
        assert_eq!(
            store
                .events()
                .unwrap()
                .iter()
                .filter(|event| event.event_type == "compiler.run.initialized")
                .count(),
            1,
            "a seed persisted before its event must recover the missing receipt"
        );

        let mut protected = context.clone();
        protected
            .graph_seed
            .as_mut()
            .unwrap()
            .root_spec
            .insert("outcome".to_owned(), json!("replace compiler goal"));
        assert!(
            engine
                .build_initial_graph(&manifest, Some(&protected))
                .unwrap_err()
                .to_string()
                .contains("protected root field outcome")
        );

        let mut compiler_owned = context;
        compiler_owned.graph_seed.as_mut().unwrap().nodes[0].spec["observability"] =
            json!("planner-authored compiler state");
        let error = engine
            .build_initial_graph(&manifest, Some(&compiler_owned))
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("compiler-owned field spec.observability"),
            "{error}"
        );
    }

    #[test]
    fn planning_output_parser_accepts_legacy_and_one_to_three_question_batches() {
        let request = |prompt: &str| {
            json!({
                "prompt": prompt,
                "context": "This changes the plan.",
                "impact": "high",
                "options": [
                    {"label": "A", "description": "Choose A.", "recommended": true},
                    {"label": "B", "description": "Choose B.", "recommended": false}
                ]
            })
        };
        let legacy = json!({
            "kind": "question",
            "plan": null,
            "prompt": "Legacy choice?",
            "context": "This changes the plan.",
            "impact": "high",
            "options": [
                {"label": "A", "description": "Choose A.", "recommended": true},
                {"label": "B", "description": "Choose B.", "recommended": false}
            ]
        });
        assert!(matches!(
            parse_planning_agent_output(&legacy.to_string()).unwrap(),
            PlanningAgentOutputEnvelope::Question(_)
        ));

        for size in 1..=3 {
            let questions = (1..=size)
                .map(|index| request(&format!("Choice {index}?")))
                .collect::<Vec<_>>();
            let output = json!({
                "kind": "questions",
                "plan": null,
                "prompt": null,
                "context": null,
                "impact": null,
                "options": null,
                "questions": questions
            });
            let parsed = parse_planning_agent_output(&output.to_string()).unwrap();
            assert!(matches!(
                parsed,
                PlanningAgentOutputEnvelope::Questions { questions } if questions.len() == size
            ));
        }
    }

    #[test]
    fn planning_output_parser_rejects_empty_oversized_duplicate_and_malformed_batches() {
        let request = |prompt: &str| {
            json!({
                "prompt": prompt,
                "context": "This changes the plan.",
                "impact": "high",
                "options": [
                    {"label": "A", "description": "Choose A.", "recommended": true},
                    {"label": "B", "description": "Choose B.", "recommended": false}
                ]
            })
        };
        let output = |questions: Vec<Value>| {
            json!({
                "kind": "questions",
                "plan": null,
                "prompt": null,
                "context": null,
                "impact": null,
                "options": null,
                "questions": questions
            })
        };
        assert!(parse_planning_agent_output(&output(Vec::new()).to_string()).is_err());
        assert!(
            parse_planning_agent_output(
                &output(
                    (1..=4)
                        .map(|index| request(&format!("Q{index}?")))
                        .collect()
                )
                .to_string()
            )
            .is_err()
        );
        assert!(
            parse_planning_agent_output(
                &output(vec![request("  Same   choice? "), request("same choice?")]).to_string()
            )
            .is_err()
        );
        let mut malformed = request("Malformed?");
        malformed.as_object_mut().unwrap().remove("context");
        assert!(parse_planning_agent_output(&output(vec![malformed]).to_string()).is_err());

        let ambiguous = json!({
            "kind": "questions",
            "plan": null,
            "prompt": "Singleton field is forbidden",
            "context": null,
            "impact": null,
            "options": null,
            "questions": [request("Valid child?")]
        });
        assert!(parse_planning_agent_output(&ambiguous.to_string()).is_err());
    }

