    #[cfg(unix)]
    #[test]
    fn official_npm_codex_launcher_resolves_its_native_process_image() {
        use std::os::unix::fs::PermissionsExt;

        let temp = tempfile::TempDir::new().unwrap();
        let package = temp.path().join("node_modules/@openai/codex");
        let launcher = package.join("bin/codex.js");
        fs::create_dir_all(launcher.parent().unwrap()).unwrap();
        fs::write(&launcher, "#!/usr/bin/env node\n").unwrap();
        let platform = match std::env::consts::OS {
            "macos" => "darwin",
            "linux" => "linux",
            other => panic!("unsupported test platform {other}"),
        };
        let architecture = match std::env::consts::ARCH {
            "aarch64" => "arm64",
            "x86_64" => "x64",
            other => panic!("unsupported test architecture {other}"),
        };
        let native = package
            .join("node_modules/@openai")
            .join(format!("codex-{platform}-{architecture}"))
            .join("vendor/test-target/bin/codex");
        fs::create_dir_all(native.parent().unwrap()).unwrap();
        fs::write(&native, "native codex fixture\n").unwrap();
        fs::set_permissions(&native, fs::Permissions::from_mode(0o755)).unwrap();

        assert_eq!(
            official_npm_codex_native_executable(&launcher).unwrap(),
            Some(native.canonicalize().unwrap())
        );
        let unrelated = temp.path().join("bin/codex.js");
        fs::create_dir_all(unrelated.parent().unwrap()).unwrap();
        fs::write(&unrelated, "#!/usr/bin/env node\n").unwrap();
        assert_eq!(
            official_npm_codex_native_executable(&unrelated).unwrap(),
            None,
            "only the official @openai/codex package layout is unwrapped"
        );
    }

    #[test]
    fn worker_runtime_mcp_is_one_highest_layer_identity_bound_table() {
        let temp = tempfile::TempDir::new().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let executable = std::env::current_exe().unwrap();
        let runtime = build_agent_mcp_launch_config(
            executable.clone(),
            "grant-019f",
            "worker-019f",
            2,
            agent_mcp_enabled_tools(None),
        )
        .unwrap();
        let hostile_override = "mcp_servers.koni_runtime.enabled_tools=[\"unbounded\"]".to_owned();
        let native_overrides = vec![hostile_override.clone()];
        let permissions =
            agent_permission_assignments(&StorageConfig::default(), false, false).unwrap();
        let args = ticket_worker_agent_argv(
            &root,
            "never",
            false,
            false,
            &permissions,
            CodexAgentLaunchOptions {
                model: None,
                reasoning_effort: None,
                native_config_overrides: &native_overrides,
            },
            &runtime,
        );
        let reserved = runtime.codex_assignment();
        assert!(
            !args.iter().any(|arg| arg == &hostile_override),
            "native MCP config must never enter a bounded Codex argv"
        );
        let reserved_index = args.iter().position(|arg| arg == &reserved).unwrap();
        assert!(reserved_index > 0);
        assert!(reserved.starts_with("mcp_servers={koni_runtime={"));
        for exact in [
            "enabled=true",
            "required=true",
            "default_tools_approval_mode=\"approve\"",
            "tool_timeout_sec=3660",
            "enabled_tools=[\"context\",\"read_file\",\"list_files\",\"search_files\",\"write_file\",\"edit_file\",\"run_configured_check\",\"graph_context\",\"record_note\",\"submit_and_compile\",\"submit_output\",\"compile\"]",
        ] {
            assert!(reserved.contains(exact), "missing {exact}: {reserved}");
        }
        assert!(!reserved.contains("ask_question"));
        assert!(
            runtime
                .server_args
                .windows(2)
                .any(|pair| pair == ["--grant", "grant-019f"])
        );
        assert!(
            runtime
                .server_args
                .windows(2)
                .any(|pair| pair == ["--agent-id", "worker-019f"])
        );
        for forbidden in [
            "--root",
            "--run",
            "--persona",
            "--ticket",
            "--step",
            "--input-hash",
            "--allow-tool",
        ] {
            assert!(
                !runtime
                    .server_args
                    .iter()
                    .any(|argument| argument == forbidden)
            );
        }
        assert!(runtime.inherited_environment.is_empty());
        assert_eq!(runtime.command, executable.canonicalize().unwrap());
    }

