    fn filesystem_manifest_test_definition() -> FilesystemManifestDef {
        serde_json::from_value(json!({
            "root_field": "spec.plan.root",
            "implementation_contract_field": "spec.implementation",
            "implementation_kind_field": "spec.implementation.kind",
            "implementation_entrypoints_field": "spec.implementation.entrypoints",
            "contract_fields": ["spec.plan"],
            "output_field": "artifact_manifest",
            "allowed_root_prefixes": ["artifacts"],
            "scan": {
                "ignored_path_components": ["__pycache__"],
                "ignored_suffixes": [".pyc"],
                "symlinks": "reject"
            }
        }))
        .unwrap()
    }

    fn filesystem_manifest_test_node(entrypoints: Value) -> Node {
        let mut node = Node::new(
            "component",
            "Filesystem component",
            json!({
                "plan": {"root": "artifacts/component"},
                "implementation": {
                    "kind": "script",
                    "entrypoints": entrypoints
                }
            }),
        );
        node.id = "component".to_owned();
        node
    }

    #[test]
    fn filesystem_manifest_recursively_hashes_and_scoped_acceptance_detects_mutation() {
        let temp = tempfile::TempDir::new().unwrap();
        let root = temp.path().join("artifacts/component");
        fs::create_dir_all(root.join("nested")).unwrap();
        fs::create_dir_all(root.join("__pycache__")).unwrap();
        fs::write(root.join("main.py"), b"print('ready')\n").unwrap();
        fs::write(root.join("nested/data.txt"), b"payload\n").unwrap();
        fs::write(root.join("__pycache__/main.pyc"), b"transient").unwrap();
        let definition = filesystem_manifest_test_definition();
        let mut node = filesystem_manifest_test_node(json!(["artifacts/component/main.py"]));

        let unaccepted = derive_filesystem_manifest(&node, &definition, temp.path(), false);
        assert_eq!(unaccepted["implementation_status"], "incomplete");
        assert!(
            unaccepted["implementation_errors"]
                .as_array()
                .unwrap()
                .iter()
                .any(|error| error
                    .as_str()
                    .unwrap()
                    .contains("scoped compiler acceptance"))
        );

        let accepted = derive_filesystem_manifest(&node, &definition, temp.path(), true);
        assert_eq!(accepted["implementation_status"], "ready");
        assert_eq!(accepted["file_count"], 2);
        assert_eq!(accepted["entrypoint_count"], 1);
        assert_eq!(accepted["files"][0]["path"], "artifacts/component/main.py");
        assert_eq!(
            accepted["files"][1]["path"],
            "artifacts/component/nested/data.txt"
        );
        assert_eq!(
            accepted["files"][0]["sha256"],
            raw_sha256(b"print('ready')\n")
        );
        node.extensions
            .insert("artifact_manifest".to_owned(), accepted.clone());
        assert_eq!(
            derive_filesystem_manifest(&node, &definition, temp.path(), false),
            accepted,
            "an unchanged accepted tree stays current"
        );

        let mut contract_changed = node.clone();
        contract_changed.spec["plan"]["declared_revision"] = Value::from(2);
        let changed_contract =
            derive_filesystem_manifest(&contract_changed, &definition, temp.path(), false);
        assert_eq!(changed_contract["implementation_status"], "incomplete");
        assert_ne!(
            changed_contract["contract_fields_hash"],
            accepted["contract_fields_hash"]
        );

        fs::write(root.join("nested/data.txt"), b"mutated\n").unwrap();
        let mutated = derive_filesystem_manifest(&node, &definition, temp.path(), false);
        assert_eq!(mutated["implementation_status"], "incomplete");
        assert_ne!(mutated["content_hash"], accepted["content_hash"]);
        assert_eq!(
            mutated["accepted_content_hash"],
            accepted["accepted_content_hash"]
        );

        fs::remove_file(root.join("main.py")).unwrap();
        let deleted = derive_filesystem_manifest(&node, &definition, temp.path(), false);
        assert_eq!(deleted["implementation_status"], "incomplete");
        assert!(
            deleted["implementation_errors"]
                .as_array()
                .unwrap()
                .iter()
                .any(|error| error.as_str().unwrap().contains("does not exist"))
        );
    }

    #[test]
    fn filesystem_manifest_rejects_missing_escape_empty_duplicate_and_outside_entrypoints() {
        let temp = tempfile::TempDir::new().unwrap();
        let root = temp.path().join("artifacts/component");
        fs::create_dir_all(&root).unwrap();
        fs::create_dir_all(temp.path().join("artifacts/other")).unwrap();
        fs::write(root.join("empty.py"), b"").unwrap();
        fs::write(root.join("main.py"), b"ok\n").unwrap();
        fs::write(temp.path().join("artifacts/other/outside.py"), b"outside\n").unwrap();
        let definition = filesystem_manifest_test_definition();
        for (entrypoints, expected) in [
            (json!(["artifacts/component/missing.py"]), "does not exist"),
            (json!(["artifacts/component/empty.py"]), "is empty"),
            (
                json!(["artifacts/component/main.py", "artifacts/component/main.py"]),
                "duplicate",
            ),
            (
                json!(["artifacts/other/outside.py"]),
                "escapes configured root",
            ),
            (json!(["../outside.py"]), "escapes the project"),
        ] {
            let node = filesystem_manifest_test_node(entrypoints);
            let manifest = derive_filesystem_manifest(&node, &definition, temp.path(), true);
            assert_eq!(manifest["implementation_status"], "incomplete");
            assert!(
                manifest["implementation_errors"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|error| error.as_str().unwrap().contains(expected)),
                "expected {expected:?}: {}",
                manifest["implementation_errors"]
            );
        }

        let missing_root = Node::new(
            "component",
            "Missing root",
            json!({"implementation": {"kind": "script", "entrypoints": ["artifacts/component/main.py"]}}),
        );
        let manifest = derive_filesystem_manifest(&missing_root, &definition, temp.path(), true);
        assert_eq!(manifest["implementation_status"], "incomplete");
        assert!(
            manifest["implementation_errors"]
                .as_array()
                .unwrap()
                .iter()
                .any(|error| error
                    .as_str()
                    .unwrap()
                    .contains("nonempty project-relative path"))
        );
    }

