        ticket.workflow[0].required_receipts = vec!["scoped-compile".to_owned()];

        let without_receipt = ticket_workflow_progress(&ticket, &[], None);
        assert!(without_receipt.completed_steps.is_empty());
        assert_eq!(without_receipt.ready_steps, vec!["produce"]);
