    #[test]
    fn generated_scoped_receipt_binding_is_current_and_ignores_compiler_owned_effects() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let mut ticket = worker_projection_ticket(false);
        ticket.profile_hash = profile.hash.clone();
        ticket.target_nodes = vec!["asset".to_owned()];
        ticket.scope.read_nodes.insert("asset".to_owned());
        ticket.scope.write_nodes.insert("asset".to_owned());
        let mut node = Node::new("asset", "Asset", json!({"revision": 1}));
        node.id = "asset".to_owned();
        node.extensions
            .insert("readiness".to_owned(), json!({"state": "blocked"}));
        let mut unrelated = Node::new("claim", "Unrelated", json!({"revision": 1}));
        unrelated.id = "unrelated".to_owned();
        let mut graph = Graph::default();
        graph.insert(node).unwrap();
        graph.insert(unrelated).unwrap();
        let bindings = scoped_compile_bindings(&profile, &ticket, &graph).unwrap();
        let ticket_binding = scoped_compile_ticket_binding(&ticket);
        let path_exclusions =
            command_read_path_exclusions(&profile, std::iter::empty::<&str>()).unwrap();
        let mut receipt = json!({
            "schema_version": "1.0",
            "id": "receipt",
            "receipt_type": "scoped-compile",
            "ticket_id": ticket.id,
            "context_hash": null,
            "context_hashes": scoped_compile_context_hashes(&ticket),
            "output_hash": normalized_hash(&ticket.outputs),
            "graph_hash": scoped_compile_graph_hash(&ticket_binding, &bindings),
            "ticket_binding": ticket_binding,
            "status": "passed",
            "profile_hash": ticket.profile_hash,
            "target_hashes": bindings.target_hashes,
            "scope_hashes": bindings.scope_hashes,
            "scope_bindings": bindings.scope_bindings,
            "path_exclusions": path_exclusions,
            "read_path_manifest": [],
            "write_path_manifest": [],
            "filesystem_manifests": {},
            "recorded_at": "2026-01-01T00:00:00Z",
            "receipt_hash": "",
        });
        rehash_durable_receipt(&mut receipt);

        assert!(scoped_compile_receipt_is_current(
            &profile,
            &ticket,
            &receipt,
            &graph,
            temp.path(),
        ));

        let forged = [
            ("schema", "schema_version", json!("9.9")),
            ("kind", "receipt_type", json!("generic.receipt")),
            ("identity", "id", json!("")),
            ("ticket", "ticket_id", json!("TK-forged")),
            ("status", "status", json!("failed")),
            ("profile", "profile_hash", json!("sha256:forged")),
            ("output", "output_hash", json!("sha256:forged")),
            ("graph", "graph_hash", json!("sha256:forged")),
            ("timestamp", "recorded_at", json!("not-a-timestamp")),
            ("contexts", "context_hashes", json!({"forged": "ctx"})),
            ("legacy context", "context_hash", json!("ctx-forged")),
            ("ticket binding", "ticket_binding", json!({})),
            ("targets", "target_hashes", json!({})),
            ("scope", "scope_hashes", json!({})),
            ("definitions", "scope_bindings", json!({})),
            ("exclusions", "path_exclusions", json!([])),
            (
                "read paths",
                "read_path_manifest",
                json!([{"forged": true}]),
            ),
            (
                "write paths",
                "write_path_manifest",
                json!([{"forged": true}]),
            ),
            ("filesystem", "filesystem_manifests", json!({"forged": {}})),
        ];
        for (label, field, value) in forged {
            let mut candidate = receipt.clone();
            candidate[field] = value;
            rehash_durable_receipt(&mut candidate);
            assert!(
                !scoped_compile_receipt_is_current(
                    &profile,
                    &ticket,
                    &candidate,
                    &graph,
                    temp.path(),
                ),
                "self-consistently rehashed forged {label} must fail"
            );
        }
        let mut unhashed_mutation = receipt.clone();
        unhashed_mutation["status"] = json!("failed");
        assert!(
            !scoped_compile_receipt_is_current(
                &profile,
                &ticket,
                &unhashed_mutation,
                &graph,
                temp.path(),
            ),
            "durable receipt mutation must fail its integrity hash"
        );

        graph.node_mut("unrelated").unwrap().spec["revision"] = json!(2);
        assert!(scoped_compile_receipt_is_current(
            &profile,
            &ticket,
            &receipt,
            &graph,
            temp.path(),
        ));
        graph
            .node_mut("asset")
            .unwrap()
            .extensions
            .insert("readiness".to_owned(), json!({"state": "ready"}));
        assert!(
            scoped_compile_receipt_is_current(&profile, &ticket, &receipt, &graph, temp.path(),),
            "compiler-owned review/rule effects must not stale a scoped receipt"
        );
        graph.node_mut("asset").unwrap().spec["revision"] = Value::from(2);
        assert!(
            !scoped_compile_receipt_is_current(&profile, &ticket, &receipt, &graph, temp.path(),),
            "worker-authored semantic mutations must stale a scoped receipt"
        );
    }

    #[test]
    fn scoped_replay_rejects_missing_and_duplicate_receipt_identities() {
        assert!(durable_receipt_ids_are_unique(&[
            json!({"id": "first"}),
            json!({"id": "second"}),
        ]));
        assert!(!durable_receipt_ids_are_unique(&[
            json!({"id": "same"}),
            json!({"id": "same"}),
        ]));
        assert!(!durable_receipt_ids_are_unique(&[
            json!({"id": "present"}),
            json!({}),
        ]));
        assert!(!durable_receipt_ids_are_unique(&[json!({"id": ""})]));
    }

    #[test]
    fn generic_receipt_writer_cannot_fabricate_or_overwrite_authority_receipts() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        store
            .write_manifest(&RunManifest::new(
                profile.manifest.profile.id.clone(),
                profile.manifest.profile.version.clone(),
                profile.hash.clone(),
                "receipt authority test",
                temp.path().to_path_buf(),
            ))
            .unwrap();
        let mut engine = Engine {
            root: temp.path().to_path_buf(),
            profile: profile.clone(),
            store: Some(store.clone()),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let step: ActionStepDef = serde_json::from_value(json!({
            "primitive": "receipt.write"
        }))
        .unwrap();
        let write = |id: &str, receipt_type: &str| {
            BTreeMap::from([(
                "receipt".to_owned(),
                json!({
                    "id": id,
                    "receipt_type": receipt_type,
                    "recorded_at": "1900-01-01T00:00:00Z",
                    "profile_hash": "sha256:forged",
                    "status": "passed"
                }),
            )])
        };

        for reserved in ["scoped-compile", "runtime.receipt"] {
            let error = engine
                .execute_primitive(&step, &write("forged", reserved))
                .expect_err("compiler-owned receipt identities are reserved");
            assert!(error.to_string().contains("compiler-owned"));
        }
        let error = engine
            .execute_primitive(&step, &write("../escape", "domain.receipt"))
            .expect_err("receipt ids may not traverse directories");
        assert!(error.to_string().contains("safe filename"));

        engine
            .execute_primitive(&step, &write("domain-proof", "domain.receipt"))
            .unwrap();
        let receipt: Value = serde_yaml::from_str(
            &fs::read_to_string(store.receipts_dir().join("domain-proof.yaml")).unwrap(),
        )
        .unwrap();
        assert_eq!(receipt["profile_hash"], profile.hash);
        assert_eq!(receipt["producer"], "compiler.recipe");
        assert_ne!(receipt["recorded_at"], "1900-01-01T00:00:00Z");
        assert!(durable_receipt_integrity_current(&receipt));
        let error = engine
            .execute_primitive(&step, &write("domain-proof", "domain.receipt"))
            .expect_err("durable receipt identities are immutable");
        assert!(error.to_string().contains("overwrite"));

        let mut tampered = receipt;
        tampered["status"] = json!("failed");
        assert!(!receipt_is_current_for_ticket(
            &worker_projection_ticket(false),
            &tampered,
            None,
        ));
    }

    #[test]
    fn new_nodes_reject_every_configured_compiler_owned_field_before_deserialization() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let engine = Engine {
            root: temp.path().to_path_buf(),
            profile: profile.clone(),
            store: Some(store),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let mut ticket = worker_projection_ticket(false);
        ticket.operation = "plan-build-asset".to_owned();
        ticket.extensions.insert(
            "operation_registry_id".to_owned(),
            Value::String("asset-resolution.prerequisite.plan-build-asset".to_owned()),
        );
        let base = json!({
            "schema_version": "1.0",
            "id": "asset-new",
            "type": "asset",
            "title": "Agent-authored asset",
            "spec": {"capabilities": [{"name": "fixture", "version": "1.0.0"}]},
            "edges": {}
        });
        for field in &profile.node_types["asset"].compiler_owned_fields {
            let mut forged = base.clone();
            set_value_path(&mut forged, field, json!({"forged": true})).unwrap();
            let error = engine
                .apply_graph_delta_to_graph(
                    &ticket,
                    &json!({"add_nodes": [forged]}),
                    &mut Graph::default(),
                    false,
                )
                .expect_err("new nodes must not author configured compiler state")
                .to_string();
            assert!(
                error.contains(&format!("compiler-owned field {field}")),
                "forged field {field} produced {error}"
            );
        }

        let mut graph = Graph::default();
        engine
            .apply_graph_delta_to_graph(&ticket, &json!({"add_nodes": [base]}), &mut graph, false)
            .unwrap();
        assert_eq!(graph.node("asset-new").unwrap().status, "draft");
    }

    #[test]
    fn existing_node_upsert_carries_omitted_compiler_state_but_rejects_an_explicit_change() {
        let profile = compiled_research_profile();
        let temp = tempfile::tempdir().unwrap();
        let store = StateStore::new(temp.path().join("program"));
        store.ensure_layout().unwrap();
        let engine = Engine {
            root: temp.path().to_path_buf(),
            profile: profile.clone(),
            store: Some(store),
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        let mut ticket = worker_projection_ticket(false);
        ticket.operation = "design-experiment".to_owned();
        ticket.extensions.insert(
            "operation_registry_id".to_owned(),
            Value::String("preparation.experiment.design-experiment".to_owned()),
        );
        ticket
            .scope
            .write_nodes
            .insert("metric-existing".to_owned());

        let mut existing = Node::new(
            "metric",
            "Existing metric",
            json!({
                "name": "bounded-observation",
                "definition": "initial definition",
                "measurement_keys": ["mismatch_count"]
            }),
        );
        existing.id = "metric-existing".to_owned();
        existing.status = "blocked".to_owned();
        existing
            .extensions
            .insert("compiler".to_owned(), json!({"projection": "current"}));
        existing
            .extensions
            .insert("readiness".to_owned(), json!({"state": "blocked"}));
        let mut graph = Graph::default();
        graph.insert(existing.clone()).unwrap();

        let semantic_upsert = json!({
            "id": "metric-existing",
            "type": "metric",
            "title": "Existing metric",
            "spec": {
                "name": "bounded-observation",
                "definition": "tightened definition",
                "measurement_keys": ["mismatch_count"]
            },
            "edges": {}
        });
        engine
            .apply_graph_delta_to_graph(
                &ticket,
                &json!({"upsert": [semantic_upsert.clone()]}),
                &mut graph,
                false,
            )
            .unwrap();
        let updated = graph.node("metric-existing").unwrap();
        assert_eq!(updated.status, "blocked");
        assert_eq!(updated.spec["definition"], "tightened definition");
        assert_eq!(
            updated.extensions["compiler"],
            json!({"projection": "current"})
        );
        assert_eq!(updated.extensions["readiness"], json!({"state": "blocked"}));

        let narrow_step = serde_json::from_value::<Step>(json!({
            "id": "narrow-write",
            "persona": "worker",
            "read_nodes": ["metric-existing"],
            "write_nodes": [],
            "context_hash": "sha256:narrow-write"
        }))
        .unwrap();
        let scoped_ticket = ticket_with_step_scope(&ticket, &narrow_step);
        let mut out_of_step_update = semantic_upsert.clone();
        out_of_step_update["spec"]["definition"] = json!("unauthorized second update");
        let error = engine
            .apply_graph_delta_to_graph(
                &scoped_ticket,
                &json!({"upsert": [out_of_step_update]}),
                &mut graph,
                false,
            )
            .expect_err("step-local write authority must narrow the ticket scope")
            .to_string();
        assert!(error.contains("cannot update out-of-scope node metric-existing"));

        let mut forged = semantic_upsert;
        forged["compiler"] = json!({"projection": "forged"});
        let error = engine
            .apply_graph_delta_to_graph(&ticket, &json!({"upsert": [forged]}), &mut graph, false)
            .expect_err("explicit compiler projection changes remain forbidden")
            .to_string();
        assert!(error.contains("cannot modify compiler-owned field compiler"));
    }

