    fn terminal_recovery_failure(
        fixture: &ChangeControlEngineFixture,
        ticket_id: &str,
        journal_id: &str,
        failure: &str,
    ) -> BTreeMap<String, Value> {
        fixture
            .store
            .write_journal(&Journal {
                id: journal_id.to_owned(),
                action: "finish".to_owned(),
                input_hash: Some(normalized_hash(&(ticket_id, "finish"))),
                status: JournalStatus::Compensating,
                started_at: Utc.with_ymd_and_hms(2026, 7, 14, 12, 0, 0).unwrap(),
                profile_hash: fixture.engine.profile.hash.clone(),
                completed_steps: vec![0, 1],
                outputs: BTreeMap::new(),
                error: Some(failure.to_owned()),
            })
            .unwrap();
        let diagnostic = agent_mcp_safe_error(&KoniError::Action(failure.to_owned()));
        BTreeMap::from([
            ("ticket".to_owned(), Value::String(ticket_id.to_owned())),
            ("_action".to_owned(), Value::String("finish".to_owned())),
            ("_actor".to_owned(), Value::String("compiler".to_owned())),
            ("_journal".to_owned(), Value::String(journal_id.to_owned())),
            (
                "_failure_hash".to_owned(),
                Value::String(normalized_hash(&failure)),
            ),
            (
                "_failure_diagnostic".to_owned(),
                serde_json::to_value(diagnostic).unwrap(),
            ),
            (
                "mode".to_owned(),
                Value::String("block_and_emit_single_resolver".to_owned()),
            ),
        ])
    }

    #[test]
    fn terminal_recovery_dispatch_blocks_emits_and_replays_idempotently() {
        let mut fixture = change_control_engine_fixture();
        let retained_worktree = tempfile::tempdir().unwrap();
        fs::write(retained_worktree.path().join("candidate.txt"), "retain me").unwrap();
        let mut source = fixture.store.ticket(&fixture.source.id).unwrap();
        source.lease = Some(Lease {
            id: "lease-terminal-source".to_owned(),
            branch: "koni/test/terminal-source".to_owned(),
            worktree: retained_worktree.path().to_path_buf(),
            base_commit: "0123456789abcdef".to_owned(),
            started_at: Utc.with_ymd_and_hms(2026, 7, 14, 11, 0, 0).unwrap(),
            heartbeat_at: Utc.with_ymd_and_hms(2026, 7, 14, 11, 30, 0).unwrap(),
            worker_pid: None,
        });
        fixture.store.write_ticket(&source).unwrap();

        let git = GitBackend::discover(&fixture.engine.root).unwrap();
        let head_before = git.head_oid().unwrap();
        let state_prefix = fixture
            .engine
            .profile
            .manifest
            .storage
            .state_path
            .parent()
            .unwrap()
            .to_path_buf();
        let product_changes = |changes: Vec<WorktreeChange>| {
            changes
                .into_iter()
                .filter(|change| !change.path.starts_with(&state_prefix))
                .collect::<Vec<_>>()
        };
        let product_status_before = product_changes(git.status(&[]).unwrap());
        let graph_before = fixture
            .engine
            .semantic_graph_hash(&fixture.store.graph().unwrap());
        let failure =
            "ticket integration conflicts: /secret/SENTINEL; compensation remains bounded";
        let args =
            terminal_recovery_failure(&fixture, &source.id, "journal-terminal-source", failure);
        let first = fixture
            .engine
            .execute_primitive(&terminal_recovery_step(), &args)
            .unwrap();
        assert_eq!(first["emitted"], true);
        assert_eq!(first["reused"], false);
        assert_eq!(first["chain_suppressed"], false);
        let resolver_id = first["resolver_ticket"].as_str().unwrap().to_owned();

        let blocked = fixture.store.ticket(&source.id).unwrap();
        assert_eq!(blocked.status, "blocked");
        assert_eq!(blocked.lease.as_ref().unwrap().id, "lease-terminal-source");
        assert_eq!(
            fs::read_to_string(retained_worktree.path().join("candidate.txt")).unwrap(),
            "retain me"
        );
        assert!(blocked.blockers.iter().any(|blocker| {
            blocker.kind == TERMINAL_RECOVERY_BLOCKER_KIND
                && blocker.related_ticket.as_deref() == Some(resolver_id.as_str())
        }));
        let resolver = fixture.store.ticket(&resolver_id).unwrap();
        let operation = ticket_operation(&fixture.engine.profile, &resolver).unwrap();
        assert!(operation.terminal_resolver);
        assert_eq!(
            resolver
                .extensions
                .get("workflow_id")
                .and_then(Value::as_str),
            operation.workflow.as_deref()
        );
        assert_eq!(
            resolver
                .extensions
                .get(TERMINAL_RESOLVER_BINDING_EXTENSION)
                .and_then(|binding| binding.get("source_ticket_id"))
                .and_then(Value::as_str),
            Some(source.id.as_str())
        );
        let model_facing_recovery = serde_json::to_string(&json!({
            "source_dispatch": blocked.extensions.get(TERMINAL_RECOVERY_DISPATCH_EXTENSION),
            "source_blockers": blocked.blockers,
            "resolver_binding": resolver.extensions.get(TERMINAL_RESOLVER_BINDING_EXTENSION),
            "events": fixture.store.events().unwrap(),
        }))
        .unwrap();
        assert!(!model_facing_recovery.contains("SENTINEL"));
        assert!(!model_facing_recovery.contains("/secret"));
        assert!(
            fixture
                .store
                .journals()
                .unwrap()
                .iter()
                .any(|journal| journal.error.as_deref() == Some(failure)),
            "the raw failure remains only in the compiler-owned journal"
        );
        assert_eq!(git.head_oid().unwrap(), head_before);
        assert_eq!(
            product_changes(git.status(&[]).unwrap()),
            product_status_before
        );
        assert_eq!(
            fixture
                .engine
                .semantic_graph_hash(&fixture.store.graph().unwrap()),
            graph_before
        );
        assert_eq!(fixture.store.tickets().unwrap().len(), 2);

        let blocked_hash = normalized_hash(&blocked);
        let resolver_hash = normalized_hash(&resolver);
        let event_count = fixture.store.events().unwrap().len();
        let mut completed_failure = fixture
            .store
            .journals()
            .unwrap()
            .into_iter()
            .find(|journal| journal.id == "journal-terminal-source")
            .unwrap();
        completed_failure.status = JournalStatus::Failed;
        fixture.store.write_journal(&completed_failure).unwrap();
        let compiler_status = git.status(&[]).unwrap();
        let replay = fixture
            .engine
            .execute_primitive(&terminal_recovery_step(), &args)
            .unwrap();
        assert_eq!(replay["resolver_ticket"], resolver_id);
        assert_eq!(replay["emitted"], false);
        assert_eq!(replay["reused"], true);
        assert_eq!(fixture.store.tickets().unwrap().len(), 2);
        assert_eq!(
            normalized_hash(&fixture.store.ticket(&source.id).unwrap()),
            blocked_hash
        );
        assert_eq!(
            normalized_hash(&fixture.store.ticket(&resolver_id).unwrap()),
            resolver_hash
        );
        assert_eq!(fixture.store.events().unwrap().len(), event_count);
        assert_eq!(git.head_oid().unwrap(), head_before);
        assert_eq!(git.status(&[]).unwrap(), compiler_status);
        assert_eq!(
            product_changes(git.status(&[]).unwrap()),
            product_status_before
        );
    }

    #[test]
    fn terminal_recovery_dispatch_suppresses_resolver_chains() {
        let mut fixture = change_control_engine_fixture();
        let first_args = terminal_recovery_failure(
            &fixture,
            &fixture.source.id,
            "journal-source-before-resolver-chain",
            "integration conflict requires terminal recovery",
        );
        let first = fixture
            .engine
            .execute_primitive(&terminal_recovery_step(), &first_args)
            .unwrap();
        let resolver_id = first["resolver_ticket"].as_str().unwrap().to_owned();
        let mut resolver = fixture.store.ticket(&resolver_id).unwrap();
        resolver.status = "in_progress".to_owned();
        fixture.store.write_ticket(&resolver).unwrap();

        let chain_args = terminal_recovery_failure(
            &fixture,
            &resolver_id,
            "journal-terminal-resolver",
            "integration conflict at /secret/RESOLVER_SENTINEL",
        );
        let ticket_count = fixture.store.tickets().unwrap().len();
        let result = fixture
            .engine
            .execute_primitive(&terminal_recovery_step(), &chain_args)
            .unwrap();
        assert_eq!(result["chain_suppressed"], true);
        assert_eq!(result["emitted"], false);
        assert!(result["resolver_ticket"].is_null());
        assert_eq!(fixture.store.tickets().unwrap().len(), ticket_count);
        let failed_resolver = fixture.store.ticket(&resolver_id).unwrap();
        assert_eq!(failed_resolver.status, "blocked");
        assert!(failed_resolver.blockers.iter().any(|blocker| {
            blocker.kind == TERMINAL_RESOLVER_FAILURE_BLOCKER_KIND
                && blocker.related_ticket.is_none()
        }));
        assert_eq!(
            failed_resolver
                .extensions
                .get(TERMINAL_RECOVERY_DISPATCH_EXTENSION)
                .and_then(|dispatch| dispatch.get("chain_suppressed"))
                .and_then(Value::as_bool),
            Some(true)
        );
        let safe_state = serde_json::to_string(&json!({
            "ticket": failed_resolver,
            "events": fixture.store.events().unwrap(),
        }))
        .unwrap();
        assert!(!safe_state.contains("RESOLVER_SENTINEL"));
        assert!(!safe_state.contains("/secret"));
    }

    fn reviewed_change_control_proposal(
        fixture: &ChangeControlEngineFixture,
        proposal_id: &str,
        operation: &str,
    ) -> Ticket {
        let manifest = fixture.store.manifest().unwrap();
        let mut approval = Event::new(
            &manifest.id,
            "compiler.steering.recorded",
            Some(proposal_id.to_owned()),
            json!({"kind": "approval", "message": "Approve bounded change-control review."}),
        );
        approval.id = format!("EV-approve-{operation}");
        approval.actor = "lead".to_owned();
        fixture.store.append_event(&approval).unwrap();
        fixture
            .engine
            .reconcile_change_control(&fixture.store, &Graph::default(), &manifest)
            .unwrap();
        let mut proposal = fixture.store.ticket(proposal_id).unwrap();
        assert_eq!(
            proposal.status,
            initial_ticket_state(&fixture.engine.profile)
        );
        assert!(proposal.change_control.proposal_approval.is_some());
        let disposition = operation == "no-op";
        let mut contract = ChangeApplicationContract {
            schema_version: "1.0".to_owned(),
            operation: operation.to_owned(),
            summary: format!("Reviewed {operation} contract"),
            target_nodes: vec!["hypothesis-a".to_owned()],
            scope: Scope {
                read_nodes: BTreeSet::from(["hypothesis-a".to_owned()]),
                write_nodes: if disposition {
                    BTreeSet::new()
                } else {
                    BTreeSet::from(["hypothesis-a".to_owned()])
                },
                ..Scope::default()
            },
            source_change_request_id: proposal.id.clone(),
            contract_hash: String::new(),
        };
        contract.contract_hash = change_application_contract_hash(&contract);
        let output = crate::state::StepOutput {
            id: format!("OUT-{operation}"),
            step_id: "propose-graph-delta".to_owned(),
            persona: "integrator".to_owned(),
            context_hash: proposal
                .workflow
                .iter()
                .find(|step| step.id == "propose-graph-delta")
                .unwrap()
                .context_hash
                .clone(),
            recorded_at: Utc.with_ymd_and_hms(2026, 7, 12, 12, 5, 0).unwrap(),
            files_read: Vec::new(),
            files_written: Vec::new(),
            files_deleted: Vec::new(),
            findings: Vec::new(),
            risks: Vec::new(),
            receipts: Vec::new(),
            patch_proposal: String::new(),
            recommended_next_step: String::new(),
            upstream_change: None,
            change_application: Some(contract),
            typed: BTreeMap::new(),
        };
        proposal.outputs = vec![output];
        let approved_at = proposal
            .change_control
            .proposal_approval
            .as_ref()
            .unwrap()
            .approved_at;
        proposal.reviews = vec![Review {
            id: format!("REV-{operation}"),
            status: "passed".to_owned(),
            notes: "Exact proposal reviewed".to_owned(),
            reviewed_at: approved_at + Duration::seconds(1),
            ticket_hash: "sha256:ticket-before-review".to_owned(),
            output_hash: normalized_hash(&proposal.outputs),
            agent_binding: None,
        }];
        fixture.store.write_ticket(&proposal).unwrap();
        proposal
    }

    fn finalize_reviewed_change_control_proposal(
        fixture: &ChangeControlEngineFixture,
        proposal: Ticket,
    ) -> Value {
        let OperationChangeControlDef::Proposal {
            proposal_step,
            application_operations,
        } = fixture.engine.profile.operations["lifecycle.change-request"]
            .change_control
            .clone()
        else {
            panic!("research change-request operation must be proposal typed");
        };
        fixture
            .engine
            .finalize_change_control_proposal(
                &fixture.store,
                proposal,
                &proposal_step,
                &application_operations,
            )
            .unwrap()
    }

    #[test]
    fn upstream_change_publication_is_deterministic_audited_and_holds_the_source() {
        let fixture = change_control_engine_fixture();
        let first = fixture
            .engine
            .publish_upstream_change_request(&fixture.source, &fixture.output)
            .unwrap();
        let second = fixture
            .engine
            .publish_upstream_change_request(&fixture.source, &fixture.output)
            .unwrap();
        assert_eq!(first, second);

        let source = fixture.store.ticket(&fixture.source.id).unwrap();
        assert_eq!(source.status, "blocked");
        assert!(source.change_control.is_held_source());
        let request = source.change_control.pending_request.unwrap();
        assert_eq!(request.source_output_id, fixture.output.id);
        assert_eq!(request.source_output_hash, normalized_hash(&fixture.output));
        assert_eq!(request.target_nodes, vec!["hypothesis-a"]);
        let audit_path = fixture.store.root().join(&request.source_output_audit_path);
        let archived: crate::state::StepOutput =
            serde_yaml::from_str(&fs::read_to_string(audit_path).unwrap()).unwrap();
        assert_eq!(normalized_hash(&archived), normalized_hash(&fixture.output));
        let proposals = fixture
            .store
            .tickets()
            .unwrap()
            .into_iter()
            .filter(|ticket| ticket.operation == "change-request")
            .collect::<Vec<_>>();
        assert_eq!(proposals.len(), 1);
        assert_eq!(proposals[0].id, first);
        assert_eq!(proposals[0].change_control.request, Some(request));
    }

    #[test]
    fn proposal_first_reconciliation_repairs_the_missing_source_hold() {
        let fixture = change_control_engine_fixture();
        let proposal_id = fixture
            .engine
            .publish_upstream_change_request(&fixture.source, &fixture.output)
            .unwrap();
        let mut source = fixture.store.ticket(&fixture.source.id).unwrap();
        source.status = "in_progress".to_owned();
        source.change_control.pending_request = None;
        source.change_control.blocker = None;
        source.blockers.clear();
        fixture.store.write_ticket(&source).unwrap();

        let manifest = fixture.store.manifest().unwrap();
        fixture
            .engine
            .reconcile_change_control(&fixture.store, &Graph::default(), &manifest)
            .unwrap();

        let repaired = fixture.store.ticket(&fixture.source.id).unwrap();
        assert_eq!(repaired.status, "blocked");
        assert!(repaired.change_control.is_held_source());
        assert_eq!(
            repaired
                .change_control
                .blocker
                .as_ref()
                .map(|blocker| blocker.change_request_ticket_id.as_str()),
            Some(proposal_id.as_str())
        );
        assert!(repaired.blockers.iter().any(|blocker| {
            blocker.kind == "upstream-change-request"
                && blocker.related_ticket.as_deref() == Some(proposal_id.as_str())
        }));
        let expected_output_hash = normalized_hash(&fixture.output);
        assert_eq!(
            repaired
                .change_control
                .pending_request
                .as_ref()
                .map(|request| request.source_output_hash.as_str()),
            Some(expected_output_hash.as_str())
        );
        assert_eq!(
            fixture
                .store
                .tickets()
                .unwrap()
                .iter()
                .filter(|ticket| ticket.operation == "change-request")
                .count(),
            1
        );
    }

    #[test]
    fn active_proposal_barriers_stop_only_overlapping_downstream_work() {
        let fixture = change_control_engine_fixture();
        let proposal_id = fixture
            .engine
            .publish_upstream_change_request(&fixture.source, &fixture.output)
            .unwrap();
        let downstream_operation =
            &fixture.engine.profile.operations["evidence-reports.node.synthesize-evidence"];
        assert!(downstream_operation.change_control_barrier);
        let downstream = |id: &str, node: &str| {
            fixture
                .engine
                .change_control_ticket(
                    id,
                    downstream_operation,
                    initial_ticket_state(&fixture.engine.profile),
                    "Downstream evidence synthesis",
                    vec![node.to_owned()],
                    Scope {
                        read_nodes: BTreeSet::from([node.to_owned()]),
                        write_nodes: BTreeSet::from([node.to_owned()]),
                        ..Scope::default()
                    },
                    TicketChangeControl::default(),
                )
                .unwrap()
        };
        fixture
            .store
            .write_ticket(&downstream("TK-overlap", "hypothesis-a"))
            .unwrap();
        fixture
            .store
            .write_ticket(&downstream("TK-unrelated", "hypothesis-b"))
            .unwrap();
        fixture
            .engine
            .derive_change_control_barriers(&fixture.store)
            .unwrap();

        let overlap = fixture.store.ticket("TK-overlap").unwrap();
        let unrelated = fixture.store.ticket("TK-unrelated").unwrap();
        assert_eq!(overlap.change_control.barriers.len(), 1);
        assert_eq!(overlap.change_control.barriers[0].ticket_id, proposal_id);
        assert_eq!(
            overlap.change_control.barriers[0].overlap_node_ids,
            vec!["hypothesis-a"]
        );
        assert!(unrelated.change_control.barriers.is_empty());
        assert!(
            fixture
                .engine
                .ensure_change_control_admission(&overlap, "start")
                .unwrap_err()
                .to_string()
                .contains("change-control barrier")
        );
        fixture
            .engine
            .ensure_change_control_admission(&unrelated, "start")
            .unwrap();
        assert_eq!(
            maximal_disjoint_eligible_tickets(
                fixture.engine.root.as_path(),
                &[overlap, unrelated],
                initial_ticket_state(&fixture.engine.profile),
                &BTreeSet::new(),
            )
            .unwrap(),
            vec!["TK-unrelated"]
        );
    }

    #[test]
    fn configured_change_control_states_drive_publication_barriers_and_release() {
        let profile_copy = tempfile::tempdir().unwrap();
        let source = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../profiles/research");
        install_profile(&source, profile_copy.path()).unwrap();
        let manifest_path = profile_copy.path().join("profile.yaml");
        let manifest = fs::read_to_string(&manifest_path)
            .unwrap()
            .replace(
                "awaiting_approval_state: proposed",
                "awaiting_approval_state: awaiting_decision",
            )
            .replace(
                "held_source_state: blocked",
                "held_source_state: waiting_upstream",
            );
        fs::write(&manifest_path, manifest).unwrap();
        let lifecycle_path = profile_copy.path().join("rules/lifecycle.yaml");
        let lifecycle = fs::read_to_string(&lifecycle_path)
            .unwrap()
            .replace("proposed", "awaiting_decision")
            .replace("blocked", "waiting_upstream");
        fs::write(&lifecycle_path, lifecycle).unwrap();
        let profile = ProfileCompiler::compile(profile_copy.path()).unwrap();
        assert_eq!(
            profile.manifest.change_control.awaiting_approval_state,
            "awaiting_decision"
        );
        assert_eq!(
            profile.manifest.change_control.held_source_state,
            "waiting_upstream"
        );

        let fixture = change_control_engine_fixture_with_profile(profile);
        let proposal_id = fixture
            .engine
            .publish_upstream_change_request(&fixture.source, &fixture.output)
            .unwrap();
        assert_eq!(
            fixture.store.ticket(&proposal_id).unwrap().status,
            "awaiting_decision"
        );
        assert_eq!(
            fixture.store.ticket(&fixture.source.id).unwrap().status,
            "waiting_upstream"
        );
        let downstream_operation =
            &fixture.engine.profile.operations["evidence-reports.node.synthesize-evidence"];
        let downstream = fixture
            .engine
            .change_control_ticket(
                "TK-custom-state-overlap",
                downstream_operation,
                initial_ticket_state(&fixture.engine.profile),
                "Downstream overlap under custom states",
                vec!["hypothesis-a".to_owned()],
                Scope {
                    read_nodes: BTreeSet::from(["hypothesis-a".to_owned()]),
                    write_nodes: BTreeSet::from(["hypothesis-a".to_owned()]),
                    ..Scope::default()
                },
                TicketChangeControl::default(),
            )
            .unwrap();
        fixture.store.write_ticket(&downstream).unwrap();
        fixture
            .engine
            .derive_change_control_barriers(&fixture.store)
            .unwrap();
        assert_eq!(
            fixture
                .store
                .ticket("TK-custom-state-overlap")
                .unwrap()
                .change_control
                .barriers[0]
                .ticket_id,
            proposal_id
        );

        let manifest = fixture.store.manifest().unwrap();
        fixture
            .store
            .append_event(&Event::new(
                &manifest.id,
                "compiler.steering.recorded",
                Some(proposal_id.clone()),
                json!({"kind": "rejection", "message": "Reject custom-state proposal."}),
            ))
            .unwrap();
        fixture
            .engine
            .reconcile_change_control(&fixture.store, &Graph::default(), &manifest)
            .unwrap();
        assert_eq!(
            fixture.store.ticket(&proposal_id).unwrap().status,
            terminal_ticket_state(&fixture.engine.profile)
        );
        assert_eq!(
            fixture.store.ticket(&fixture.source.id).unwrap().status,
            initial_ticket_state(&fixture.engine.profile)
        );
    }

    #[test]
    fn change_control_rejects_missing_runtime_hold_and_profile_rejection_transitions() {
        let mut runtime_profile = compiled_research_profile();
        runtime_profile
            .state_machines
            .get_mut("ticket")
            .unwrap()
            .transitions
            .retain(|transition| transition.id != "block-active");
        let runtime_fixture = change_control_engine_fixture_with_profile(runtime_profile);
        let error = runtime_fixture
            .engine
            .publish_upstream_change_request(&runtime_fixture.source, &runtime_fixture.output)
            .unwrap_err()
            .to_string();
        assert!(error.contains("in_progress -> blocked"), "{error}");
        assert_eq!(
            runtime_fixture
                .store
                .ticket(&runtime_fixture.source.id)
                .unwrap()
                .status,
            "in_progress"
        );
        assert!(
            runtime_fixture
                .store
                .tickets()
                .unwrap()
                .iter()
                .all(|ticket| ticket.operation != "change-request")
        );

        let profile_copy = tempfile::tempdir().unwrap();
        let source = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../profiles/research");
        install_profile(&source, profile_copy.path()).unwrap();
        let lifecycle_path = profile_copy.path().join("rules/lifecycle.yaml");
        let lifecycle = fs::read_to_string(&lifecycle_path)
            .unwrap()
            .replace(
                "      - {id: reject-change-request, from: [proposed], to: closed, actors: [compiler]}\n",
                "",
            );
        fs::write(&lifecycle_path, lifecycle).unwrap();
        let error = ProfileCompiler::compile(profile_copy.path())
            .unwrap_err()
            .to_string();
        assert!(
            error.contains("awaiting-approval -> initial/terminal"),
            "{error}"
        );
    }

    #[test]
    fn active_proposal_keeps_original_approval_and_rejects_stale_worktree_authority() {
        let mut fixture = change_control_engine_fixture();
        let proposal_id = fixture
            .engine
            .publish_upstream_change_request(&fixture.source, &fixture.output)
            .unwrap();
        let manifest = fixture.store.manifest().unwrap();
        let mut first = Event::new(
            &manifest.id,
            "compiler.steering.recorded",
            Some(proposal_id.clone()),
            json!({"kind": "approval", "message": "Approve this proposal attempt."}),
        );
        first.id = "EV-active-approval-first".to_owned();
        first.actor = "lead".to_owned();
        fixture.store.append_event(&first).unwrap();
        fixture
            .engine
            .reconcile_change_control(&fixture.store, &Graph::default(), &manifest)
            .unwrap();
        fixture
            .engine
            .acquire_lease(&BTreeMap::from([("ticket".to_owned(), json!(proposal_id))]))
            .unwrap();
        let mut active = fixture.store.ticket(&proposal_id).unwrap();
        let original_approval = active.change_control.proposal_approval.clone().unwrap();
        active.status = "in_progress".to_owned();
        fixture.store.write_ticket(&active).unwrap();

        let mut stale_runtime = active.clone();
        stale_runtime.change_control.proposal_approval = None;
        let error = fixture
            .engine
            .ensure_change_control_admission(&stale_runtime, "output")
            .unwrap_err()
            .to_string();
        assert!(error.contains("stale approval authority"), "{error}");

        let mut second = Event::new(
            &manifest.id,
            "compiler.steering.recorded",
            Some(proposal_id.clone()),
            json!({"kind": "approval", "message": "A later approval is audit-only while active."}),
        );
        second.id = "EV-active-approval-second".to_owned();
        second.actor = "lead-second".to_owned();
        fixture.store.append_event(&second).unwrap();
        fixture
            .engine
            .reconcile_change_control(&fixture.store, &Graph::default(), &manifest)
            .unwrap();
        let canonical = fixture.store.ticket(&proposal_id).unwrap();
        assert_eq!(
            canonical.change_control.proposal_approval,
            Some(original_approval)
        );
        assert!(
            fixture
                .store
                .events()
                .unwrap()
                .iter()
                .any(|event| event.id == "EV-active-approval-second")
        );
    }

