    #[test]
    fn direct_pi_lead_activation_unblocks_claim_and_preserves_early_progress() {
        let root = tempfile::tempdir().unwrap();
        let control = RunControlStore::new(root.path().to_path_buf());
        let boundary = LeadSliceBoundary::DispatchBatch {
            tickets: vec!["TK-first".to_owned()],
        };
        let mut spawning = bounded_test_lead_slice(boundary.clone());
        spawning.status = LeadSliceStatus::Spawning;
        spawning.process_identity = None;
        spawning.raw_agent_id = None;
        control.write_lead_slice(&spawning).unwrap();
        let identity = AgentProcessIdentity {
            pid: 4242,
            process_group_id: 4242,
            birth_marker: "direct-pi-born".to_owned(),
        };
        let role = AgentBrokerRole::Lead {
            generation: spawning.generation,
            boundary,
        };

        activate_direct_pi_lead_slice(&control, &role, "worker-direct", &identity).unwrap();
        let mut progressed = control.lead_slice().unwrap().unwrap();
        assert_eq!(progressed.status, LeadSliceStatus::Active);
        assert_eq!(progressed.raw_agent_id.as_deref(), Some("worker-direct"));
        assert_eq!(progressed.process_identity.as_ref(), Some(&identity));

        progressed.status = LeadSliceStatus::Yielded;
        progressed.boundaries_completed = 1;
        progressed.actions.push("dispatch:TK-first".to_owned());
        progressed.yield_reason = Some("boundary-complete".to_owned());
        progressed.updated_at = Utc::now();
        control.write_lead_slice(&progressed).unwrap();

        let mut stale_supervisor_view = spawning;
        reconcile_supervised_lead_activation(
            &control,
            &mut stale_supervisor_view,
            "worker-direct",
            &identity,
        )
        .unwrap();
        assert_eq!(stale_supervisor_view, progressed);
        assert_eq!(control.lead_slice().unwrap().unwrap(), progressed);
    }

    struct ComposedBrokerInvocation {
        _project: tempfile::TempDir,
        root: PathBuf,
        common_dir: PathBuf,
        grant_id: String,
        control: RunControlStore,
        shell: ComposedBrokerChild,
        claimed: PathBuf,
        pre_execute_resume: PathBuf,
        phase_ready: PathBuf,
        phase_resume: PathBuf,
        effect: PathBuf,
        result: PathBuf,
        log: PathBuf,
    }

    struct ComposedBrokerChild(Child);

    impl Drop for ComposedBrokerChild {
        fn drop(&mut self) {
            if self.0.try_wait().ok().flatten().is_none() {
                let _ = self.0.kill();
                let _ = self.0.wait();
            }
        }
    }

    impl ComposedBrokerInvocation {
        fn wait_for(path: &Path) {
            let deadline = Instant::now() + std::time::Duration::from_secs(10);
            while !path.exists() {
                assert!(
                    Instant::now() < deadline,
                    "timed out waiting for composed broker fixture {}",
                    path.display()
                );
                thread::sleep(std::time::Duration::from_millis(10));
            }
        }

        fn finish(&mut self) -> Value {
            let deadline = Instant::now() + std::time::Duration::from_secs(15);
            let status = loop {
                if let Some(status) = self.shell.0.try_wait().unwrap() {
                    break status;
                }
                if Instant::now() >= deadline {
                    let _ = self.shell.0.kill();
                    let _ = self.shell.0.wait();
                    panic!(
                        "composed broker child timed out:\n{}",
                        fs::read_to_string(&self.log).unwrap_or_default()
                    );
                }
                thread::sleep(std::time::Duration::from_millis(10));
            };
            assert!(
                status.success(),
                "composed broker child failed with {status}:\n{}",
                fs::read_to_string(&self.log).unwrap_or_default()
            );
            let result = fs::read_to_string(&self.result).unwrap_or_else(|error| {
                panic!(
                    "composed broker child produced no result ({error}):\n{}",
                    fs::read_to_string(&self.log).unwrap_or_default()
                )
            });
            serde_json::from_str(&result).unwrap()
        }

        fn effect_count(&self) -> u64 {
            fs::read_to_string(&self.effect)
                .ok()
                .and_then(|value| value.trim().parse().ok())
                .unwrap_or(0)
        }

        fn grant(&self) -> AgentBrokerGrant {
            read_agent_broker_grant(&self.common_dir, &self.grant_id).unwrap()
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn start_composed_broker_invocation(
        boundary: LeadSliceBoundary,
        tool: &str,
        arguments: Value,
        initial_actions: Vec<String>,
        boundaries_completed: usize,
        inject_effect: bool,
        failpoint: Option<&str>,
        block_phase: Option<&str>,
        wait_before_execute: bool,
        retry: bool,
    ) -> ComposedBrokerInvocation {
        start_composed_broker_invocation_with_second(
            boundary,
            tool,
            arguments,
            initial_actions,
            boundaries_completed,
            inject_effect,
            failpoint,
            block_phase,
            wait_before_execute,
            retry,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn start_composed_broker_invocation_with_second(
        boundary: LeadSliceBoundary,
        tool: &str,
        arguments: Value,
        initial_actions: Vec<String>,
        boundaries_completed: usize,
        inject_effect: bool,
        failpoint: Option<&str>,
        block_phase: Option<&str>,
        wait_before_execute: bool,
        retry: bool,
        second: Option<(&str, Value)>,
    ) -> ComposedBrokerInvocation {
        let project = tempfile::tempdir().unwrap();
        let root = project.path().canonicalize().unwrap();
        let profile_source =
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../profiles/research");
        Engine::open_with_profile(&root, Some(&profile_source)).unwrap();
        ensure_repository_with_head(&root).unwrap();
        let planned = Engine::plan_run(
            &root,
            Some("small"),
            "composed runtime broker security fixture",
            "HEAD",
            None,
        )
        .unwrap();
        let profile = compiled_research_profile();
        assert_eq!(planned.profile_hash, profile.hash);
        let git = GitBackend::discover(&root).unwrap();
        let common_dir = git.common_dir().canonicalize().unwrap();
        let registry = ProjectRegistryStore::new(git.sidecar_root(), root.clone()).unwrap();
        let run_root = registry.run_root(&planned.run_id).unwrap();
        let operational_store = StateStore::new(run_root.clone());
        let mut manifest = operational_store.manifest().unwrap();
        manifest.status = "active".to_owned();
        manifest.integration_branch = Some(git.branch_ref().unwrap());
        manifest.integration_worktree = Some(root.clone());
        manifest.planning_worktree = None;
        manifest.planning_read_only = false;
        manifest.updated_at = Utc::now();
        let store = StateStore::with_storage(
            tracked_state_root(&root, &profile),
            &profile.manifest.storage,
        )
        .unwrap();
        store.ensure_layout().unwrap();
        store.write_manifest(&manifest).unwrap();
        if let LeadSliceBoundary::WaitWorkers { tickets } = &boundary {
            for ticket_id in tickets {
                let mut ticket = worker_projection_ticket(false);
                ticket.id = ticket_id.clone();
                ticket.profile_hash = profile.hash.clone();
                ticket.lease = None;
                ticket.extensions.remove("active_worker");
                store.write_ticket(&ticket).unwrap();
            }
        }
        let mut registration = registry.run(&planned.run_id).unwrap();
        registration.status = RunRegistrationStatus::Active;
        registration.planning_worktree = None;
        registration.planning_read_only = false;
        registration.integration_branch = Some(git.branch_ref().unwrap());
        registration.integration_worktree = Some(root.clone());
        registration.updated_at = Utc::now();
        registry.update_run(registration).unwrap();

        let control = RunControlStore::new(run_root);
        let config = root.join("broker-child.json");
        let go = root.join("broker-child.go");
        let claimed = root.join("broker-child.claimed");
        let pre_execute_resume = root.join("broker-child.execute");
        let phase_ready = root.join("broker-child.phase-ready");
        let phase_resume = root.join("broker-child.phase-resume");
        let effect = root.join("broker-child.effect");
        let result = root.join("broker-child.result.json");
        let log = root.join("broker-child.log");
        let test_binary = std::env::current_exe().unwrap().canonicalize().unwrap();
        let script = concat!(
            "set -eu\n",
            "while [ ! -f \"$BROKER_COMPOSED_TEST_GO_FILE\" ]; do sleep 0.01; done\n",
            "set +e\n",
            "\"$BROKER_COMPOSED_TEST_BINARY\" --ignored --exact ",
            "engine::tests::composed_broker_subprocess --nocapture\n",
            "status=$?\n",
            "set -e\n",
            "exit \"$status\"\n",
        );
        let stdout = fs::File::create(&log).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let mut command = Command::new("/bin/sh");
        command
            .args(["-c", script])
            .current_dir(&root)
            .env("BROKER_COMPOSED_TEST_BINARY", &test_binary)
            .env("BROKER_COMPOSED_TEST_CONFIG", &config)
            .env("BROKER_COMPOSED_TEST_GO_FILE", &go)
            .env("BROKER_COMPOSED_TEST_CLAIMED_FILE", &claimed)
            .env(
                "BROKER_COMPOSED_TEST_PRE_EXECUTE_RESUME_FILE",
                &pre_execute_resume,
            )
            .env("BROKER_COMPOSED_TEST_READY_FILE", &phase_ready)
            .env("BROKER_COMPOSED_TEST_RESUME_FILE", &phase_resume)
            .env("BROKER_COMPOSED_TEST_RESULT_FILE", &result)
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        if inject_effect {
            command.env("BROKER_COMPOSED_TEST_EFFECT_FILE", &effect);
            if second.is_some() {
                command.env("BROKER_COMPOSED_TEST_EFFECT_TOOL", tool);
            }
        }
        if let Some(failpoint) = failpoint {
            command.env("BROKER_COMPOSED_TEST_FAILPOINT", failpoint);
        }
        if let Some(block_phase) = block_phase {
            command.env("BROKER_COMPOSED_TEST_BLOCK_PHASE", block_phase);
        }
        isolate_agent_process_group(&mut command);
        let shell = ComposedBrokerChild(command.spawn().unwrap());
        #[cfg(target_os = "macos")]
        let expected_shell = Path::new("/bin/bash").canonicalize().unwrap();
        #[cfg(not(target_os = "macos"))]
        let expected_shell = Path::new("/bin/sh").canonicalize().unwrap();
        let parent_identity = {
            let deadline = Instant::now() + std::time::Duration::from_secs(5);
            loop {
                let observed =
                    process_executable_path(shell.0.id()).and_then(|path| path.canonicalize().ok());
                if observed.as_deref() == Some(expected_shell.as_path())
                    && let Some(identity) = capture_owned_agent_process_identity(shell.0.id())
                    && process_executable_path(identity.pid)
                        .and_then(|path| path.canonicalize().ok())
                        .as_deref()
                        == Some(expected_shell.as_path())
                {
                    break identity;
                }
                assert!(
                    Instant::now() < deadline,
                    "shell parent never completed exec: expected {}, observed {}",
                    expected_shell.display(),
                    observed
                        .as_deref()
                        .map(|path| path.display().to_string())
                        .unwrap_or_else(|| "<unavailable>".to_owned())
                );
                thread::sleep(std::time::Duration::from_millis(10));
            }
        };
        let parent_executable = process_executable_path(parent_identity.pid).unwrap();
        let codex_binding = bind_external_executable(&parent_executable, "test-parent").unwrap();
        let broker_binding = bind_external_executable(&test_binary, "test-broker").unwrap();
        let agent_id = format!("worker-{}", Uuid::now_v7());
        let input_hash = normalized_hash(&json!({"tool": tool, "arguments": arguments}));
        let generation = 1;
        let grant = issue_agent_broker_grant(
            &root,
            &root,
            &planned.run_id,
            &profile.hash,
            &agent_id,
            1,
            &input_hash,
            AgentBrokerRole::Lead {
                generation,
                boundary: boundary.clone(),
            },
            codex_binding,
            broker_binding,
        )
        .unwrap();
        let now = Utc::now();
        let mut record = bounded_test_raw_agent("running", None);
        record.id = agent_id.clone();
        record.run_id = planned.run_id.clone();
        record.stage_id = Some("orchestrate".to_owned());
        record.attempt = 1;
        record.pid = Some(parent_identity.pid);
        record.process_identity = Some(parent_identity.clone());
        record.working_directory = Some(root.clone());
        record.input_hash = Some(input_hash);
        record.started_at = Some(now);
        record.finished_at = None;
        record.updated_at = now;
        control.write_agent(&record).unwrap();
        let mut slice = bounded_test_lead_slice(boundary);
        slice.run_id = planned.run_id.clone();
        slice.generation = generation;
        slice.raw_agent_id = Some(agent_id.clone());
        slice.process_identity = Some(parent_identity.clone());
        slice.actions = initial_actions;
        slice.boundaries_completed = boundaries_completed;
        slice.updated_at = Utc::now();
        control.write_lead_slice(&slice).unwrap();
        bind_agent_broker_grant_parent(&root, &grant.id, &parent_identity).unwrap();
        let (second_tool, second_arguments) = second
            .map(|(tool, arguments)| (Some(tool.to_owned()), Some(arguments)))
            .unwrap_or((None, None));
        fs::write(
            &config,
            serde_json::to_vec(&json!({
                "grant_id": grant.id,
                "agent_id": agent_id,
                "attempt": 1,
                "tool": tool,
                "arguments": arguments,
                "retry": retry,
                "wait_before_execute": wait_before_execute,
                "second_tool": second_tool,
                "second_arguments": second_arguments,
            }))
            .unwrap(),
        )
        .unwrap();
        fs::write(&go, b"go").unwrap();

        ComposedBrokerInvocation {
            _project: project,
            root,
            common_dir,
            grant_id: grant.id,
            control,
            shell,
            claimed,
            pre_execute_resume,
            phase_ready,
            phase_resume,
            effect,
            result,
            log,
        }
    }

    #[test]
    #[ignore = "subprocess entry point for composed runtime broker tests"]
    fn composed_broker_subprocess() {
        let config_path = PathBuf::from(std::env::var_os("BROKER_COMPOSED_TEST_CONFIG").unwrap());
        let config: Value = serde_json::from_slice(&fs::read(config_path).unwrap()).unwrap();
        let cwd = std::env::current_dir().unwrap();
        let mut ingress = claim_agent_mcp_grant(
            &cwd,
            config["grant_id"].as_str().unwrap(),
            config["agent_id"].as_str().unwrap(),
            config["attempt"].as_u64().unwrap() as u32,
        )
        .unwrap();
        let claimed = PathBuf::from(std::env::var_os("BROKER_COMPOSED_TEST_CLAIMED_FILE").unwrap());
        fs::write(&claimed, b"claimed").unwrap();
        if config["wait_before_execute"].as_bool() == Some(true) {
            let resume = PathBuf::from(
                std::env::var_os("BROKER_COMPOSED_TEST_PRE_EXECUTE_RESUME_FILE").unwrap(),
            );
            ComposedBrokerInvocation::wait_for(&resume);
        }
        let tool = config["tool"].as_str().unwrap();
        let arguments = config["arguments"].clone();
        let first = execute_agent_mcp_tool(&mut ingress, tool, arguments.clone());
        let second = if let Some(second_tool) = config["second_tool"].as_str() {
            Some(execute_agent_mcp_tool(
                &mut ingress,
                second_tool,
                config["second_arguments"].clone(),
            ))
        } else {
            config["retry"]
                .as_bool()
                .unwrap_or(false)
                .then(|| execute_agent_mcp_tool(&mut ingress, tool, arguments))
        };
        let result = json!({
            "first": first.as_ref().ok(),
            "first_error": first.as_ref().err().map(ToString::to_string),
            "second": second.as_ref().and_then(|result| result.as_ref().ok()),
            "second_error": second
                .as_ref()
                .and_then(|result| result.as_ref().err())
                .map(ToString::to_string),
        });
        let result_path =
            PathBuf::from(std::env::var_os("BROKER_COMPOSED_TEST_RESULT_FILE").unwrap());
        fs::write(result_path, serde_json::to_vec(&result).unwrap()).unwrap();
    }

    #[test]
    fn composed_broker_failure_boundaries_reconcile_without_duplicate_effects() {
        for (phase, expected_effects, reconciles) in [
            ("reserve_to_effect", 0, false),
            ("effect_to_response", 1, false),
            ("response_to_receipt", 1, true),
        ] {
            let mut invocation = start_composed_broker_invocation(
                LeadSliceBoundary::Recover,
                "recover",
                json!({}),
                Vec::new(),
                0,
                true,
                Some(phase),
                None,
                false,
                true,
            );
            let result = invocation.finish();
            assert!(
                result["first_error"]
                    .as_str()
                    .is_some_and(|error| error.contains("injected broker interruption")),
                "{phase}: {result}"
            );
            assert_eq!(invocation.effect_count(), expected_effects, "{phase}");
            let grant = invocation.grant();
            if reconciles {
                assert_eq!(result["second"]["effect"], "recorded", "{phase}");
                assert!(result["second_error"].is_null(), "{phase}: {result}");
                assert!(grant.in_flight.is_none(), "{phase}");
                assert_eq!(grant.tool_receipts.len(), 1, "{phase}");
                assert_eq!(grant.sequence, 1, "{phase}");
            } else {
                assert!(result["second"].is_null(), "{phase}: {result}");
                assert!(
                    result["second_error"]
                        .as_str()
                        .is_some_and(|error| error.contains("durably in flight")),
                    "{phase}: {result}"
                );
                assert!(grant.in_flight.is_some(), "{phase}");
                assert!(grant.tool_receipts.is_empty(), "{phase}");
            }
        }
    }

    #[test]
    fn composed_execute_and_revoke_are_safe_in_both_lock_orderings() {
        let mut revoke_first = start_composed_broker_invocation(
            LeadSliceBoundary::Recover,
            "recover",
            json!({}),
            Vec::new(),
            0,
            true,
            None,
            None,
            true,
            false,
        );
        ComposedBrokerInvocation::wait_for(&revoke_first.claimed);
        revoke_agent_broker_grant(&revoke_first.root, &revoke_first.grant_id).unwrap();
        fs::write(&revoke_first.pre_execute_resume, b"execute").unwrap();
        let result = revoke_first.finish();
        assert!(result["first"].is_null(), "{result}");
        assert!(result["first_error"].is_string(), "{result}");
        assert_eq!(revoke_first.effect_count(), 0);
        assert_eq!(revoke_first.grant().state, AgentBrokerGrantState::Revoked);

        let mut execute_first = start_composed_broker_invocation(
            LeadSliceBoundary::Recover,
            "recover",
            json!({}),
            Vec::new(),
            0,
            true,
            None,
            Some("reserve_to_effect"),
            false,
            false,
        );
        ComposedBrokerInvocation::wait_for(&execute_first.phase_ready);
        revoke_agent_broker_grant(&execute_first.root, &execute_first.grant_id).unwrap();
        let pending = execute_first.grant();
        assert_eq!(pending.state, AgentBrokerGrantState::Claimed);
        assert!(pending.revoke_pending);
        assert!(pending.in_flight.is_some());
        fs::write(&execute_first.phase_resume, b"resume").unwrap();
        let result = execute_first.finish();
        assert_eq!(result["first"]["effect"], "recorded", "{result}");
        assert_eq!(execute_first.effect_count(), 1);
        let grant = execute_first.grant();
        assert_eq!(grant.state, AgentBrokerGrantState::Revoked);
        assert!(!grant.revoke_pending);
        assert!(grant.in_flight.is_none());
        assert_eq!(grant.tool_receipts.len(), 1);
    }

    #[test]
    fn composed_lead_execution_commits_every_enabled_action_path() {
        let cases = [
            (
                LeadSliceBoundary::DispatchBatch {
                    tickets: vec!["TK-a".to_owned()],
                },
                "start",
                json!({"ticket": "TK-a"}),
                Vec::new(),
                0,
                "start:TK-a",
                0,
            ),
            (
                LeadSliceBoundary::DispatchBatch {
                    tickets: vec!["TK-a".to_owned()],
                },
                "spawn_worker",
                json!({"ticket": "TK-a"}),
                vec!["start:TK-a".to_owned()],
                0,
                "spawn-worker:TK-a",
                1,
            ),
            (
                LeadSliceBoundary::Recover,
                "recover",
                json!({}),
                Vec::new(),
                0,
                "recover",
                1,
            ),
            (
                LeadSliceBoundary::SpawnWorker {
                    ticket: "TK-a".to_owned(),
                },
                "spawn_worker",
                json!({}),
                Vec::new(),
                0,
                "spawn-worker:TK-a",
                1,
            ),
            (
                LeadSliceBoundary::Review {
                    ticket: "TK-a".to_owned(),
                },
                "review",
                json!({}),
                Vec::new(),
                0,
                "review:TK-a",
                1,
            ),
            (
                LeadSliceBoundary::Finish {
                    ticket: "TK-a".to_owned(),
                },
                "finish",
                json!({}),
                Vec::new(),
                0,
                "finish:TK-a",
                1,
            ),
        ];
        for (boundary, tool, arguments, actions, completed, expected_action, expected_completed) in
            cases
        {
            let mut invocation = start_composed_broker_invocation(
                boundary, tool, arguments, actions, completed, true, None, None, false, false,
            );
            let result = invocation.finish();
            assert!(result["first_error"].is_null(), "{tool}: {result}");
            assert_eq!(invocation.effect_count(), 1, "{tool}");
            let slice = invocation.control.lead_slice().unwrap().unwrap();
            assert!(
                slice.actions.iter().any(|action| action == expected_action),
                "{tool}: {:?}",
                slice.actions
            );
            assert_eq!(slice.boundaries_completed, expected_completed, "{tool}");
            assert_eq!(invocation.grant().tool_receipts.len(), 1, "{tool}");
        }

        let mut wait = start_composed_broker_invocation(
            LeadSliceBoundary::WaitWorkers {
                tickets: vec!["TK-wait".to_owned()],
            },
            "wait_worker",
            json!({}),
            Vec::new(),
            0,
            false,
            None,
            None,
            false,
            false,
        );
        let result = wait.finish();
        assert!(result["first_error"].is_null(), "wait_worker: {result}");
        let slice = wait.control.lead_slice().unwrap().unwrap();
        assert_eq!(slice.boundaries_completed, 1);
        assert!(
            slice
                .actions
                .iter()
                .any(|action| action.starts_with("wait-worker:"))
        );
        assert_eq!(wait.grant().tool_receipts.len(), 1);

        let mut yield_lead = start_composed_broker_invocation(
            LeadSliceBoundary::Recover,
            "yield_lead",
            json!({"reason": "boundary-complete"}),
            vec!["recover".to_owned()],
            1,
            false,
            None,
            None,
            false,
            false,
        );
        let result = yield_lead.finish();
        assert!(result["first_error"].is_null(), "yield_lead: {result}");
        let slice = yield_lead.control.lead_slice().unwrap().unwrap();
        assert_eq!(slice.status, LeadSliceStatus::Yielded);
        assert_eq!(slice.yield_reason.as_deref(), Some("boundary-complete"));
        let grant = yield_lead.grant();
        assert_eq!(grant.state, AgentBrokerGrantState::Consumed);
        assert_eq!(grant.tool_receipts.len(), 1);
    }

    #[test]
    fn composed_lead_spawn_then_yield_keeps_the_same_grant_current() {
        let mut invocation = start_composed_broker_invocation_with_second(
            LeadSliceBoundary::SpawnWorker {
                ticket: "TK-a".to_owned(),
            },
            "spawn_worker",
            json!({}),
            Vec::new(),
            0,
            true,
            None,
            None,
            false,
            false,
            Some(("yield_lead", json!({"reason": "boundary-complete"}))),
        );
        let result = invocation.finish();
        assert!(result["first_error"].is_null(), "spawn: {result}");
        assert!(result["second_error"].is_null(), "yield: {result}");
        assert_eq!(invocation.effect_count(), 1);
        let slice = invocation.control.lead_slice().unwrap().unwrap();
        assert_eq!(slice.status, LeadSliceStatus::Yielded);
        assert_eq!(slice.boundaries_completed, 1);
        assert_eq!(slice.yield_reason.as_deref(), Some("boundary-complete"));
        let grant = invocation.grant();
        assert_eq!(grant.state, AgentBrokerGrantState::Consumed);
        assert_eq!(grant.tool_receipts.len(), 2);
    }

