    #[test]
    fn pre_edit_full_worker_grant_remains_valid_without_gaining_edit_authority() {
        let mut grant = synthetic_agent_broker_grant();
        grant.context_policy = None;
        grant.enabled_tools = PRE_EDIT_FULL_WORKER_TOOL_CATALOG
            .into_iter()
            .map(str::to_owned)
            .collect();
        grant.enabled_tools_hash = normalized_hash(&grant.enabled_tools);
        rehash_agent_broker_grant(&mut grant);

        validate_agent_broker_grant(&grant).unwrap();
        let encoded = serde_yaml::to_string(&grant).unwrap();
        assert!(
            !encoded.contains("context_policy"),
            "an absent policy must preserve historical grant serialization and its hash"
        );
        let decoded: AgentBrokerGrant = serde_yaml::from_str(&encoded).unwrap();
        validate_agent_broker_grant(&decoded).unwrap();
        assert_eq!(decoded.context_policy, None);
        assert!(!grant.enabled_tools.iter().any(|tool| tool == "edit_file"));

        let mut impossible_edit_intent = grant.clone();
        impossible_edit_intent.in_flight = Some(AgentBrokerInFlight {
            sequence: 1,
            tool: "edit_file".to_owned(),
            operation_key: "edit_file".to_owned(),
            request_hash: "sha256:request".to_owned(),
            write_intent: Some(AgentBrokerWriteIntent {
                path: "src/lib.rs".to_owned(),
                expected_sha256: format!("sha256:{}", "a".repeat(64)),
                post_sha256: format!("sha256:{}", "b".repeat(64)),
                content_bytes: 10,
            }),
            started_at: Utc::now(),
        });
        rehash_agent_broker_grant(&mut impossible_edit_intent);
        assert!(validate_agent_broker_grant(&impossible_edit_intent).is_err());

        let mut missing_preimage = synthetic_agent_broker_grant();
        missing_preimage.in_flight = Some(AgentBrokerInFlight {
            sequence: 1,
            tool: "edit_file".to_owned(),
            operation_key: "edit_file".to_owned(),
            request_hash: "sha256:request".to_owned(),
            write_intent: Some(AgentBrokerWriteIntent {
                path: "src/lib.rs".to_owned(),
                expected_sha256: "missing".to_owned(),
                post_sha256: format!("sha256:{}", "b".repeat(64)),
                content_bytes: 10,
            }),
            started_at: Utc::now(),
        });
        rehash_agent_broker_grant(&mut missing_preimage);
        assert!(validate_agent_broker_grant(&missing_preimage).is_err());
    }

    #[test]
    fn worker_mutation_response_is_exactly_bound_to_its_durable_intent() {
        let edit = AgentBrokerInFlight {
            sequence: 1,
            tool: "edit_file".to_owned(),
            operation_key: "edit_file".to_owned(),
            request_hash: "sha256:request".to_owned(),
            write_intent: Some(AgentBrokerWriteIntent {
                path: "src/lib.rs".to_owned(),
                expected_sha256: format!("sha256:{}", "a".repeat(64)),
                post_sha256: format!("sha256:{}", "b".repeat(64)),
                content_bytes: 17,
            }),
            started_at: Utc::now(),
        };
        let response = json!({
            "path": "src/lib.rs",
            "sha256": format!("sha256:{}", "b".repeat(64)),
            "bytes": 17,
            "created": false,
            "replacements": 1,
        });
        validate_worker_write_response_against_intent(&edit, &response).unwrap();

        for (field, wrong) in [
            ("path", json!("src/other.rs")),
            ("sha256", json!(format!("sha256:{}", "c".repeat(64)))),
            ("bytes", json!(18)),
            ("created", json!(true)),
            ("replacements", json!(2)),
        ] {
            let mut changed = response.clone();
            changed[field] = wrong;
            assert!(
                validate_worker_write_response_against_intent(&edit, &changed).is_err(),
                "changed {field} must not reconcile against the durable edit intent"
            );
        }

        let mut write = edit.clone();
        write.tool = "write_file".to_owned();
        write.write_intent.as_mut().unwrap().expected_sha256 = "missing".to_owned();
        let mut write_response = response;
        write_response["created"] = json!(true);
        write_response
            .as_object_mut()
            .unwrap()
            .remove("replacements");
        validate_worker_write_response_against_intent(&write, &write_response).unwrap();
        write_response["replacements"] = json!(1);
        assert!(validate_worker_write_response_against_intent(&write, &write_response).is_err());
    }

