    #[test]
    fn broker_binds_ordered_graph_supplement_receipts_to_worker_output() {
        let mut grant = synthetic_agent_broker_grant();
        for (sequence, tool) in [
            (3, "record_note"),
            (1, "context"),
            (2, "graph_context"),
            (4, "submit_output"),
        ] {
            let request_hash = format!("sha256:request-{sequence}");
            let receipt = synthetic_agent_broker_receipt(sequence, tool, &request_hash);
            grant
                .tool_receipts
                .insert(agent_broker_receipt_key(tool, &request_hash), receipt);
        }
        let mut failed =
            synthetic_agent_broker_receipt(5, "graph_context", "sha256:request-failed");
        failed.status = "failed".to_owned();
        failed.receipt_hash = normalized_hash(&failed);
        grant.tool_receipts.insert(
            agent_broker_receipt_key("graph_context", "sha256:request-failed"),
            failed,
        );

        let supplements = agent_broker_context_supplement_receipts(&grant);
        assert_eq!(supplements.len(), 2);
        assert!(supplements[0].starts_with("broker-tool:graph_context:sha256:"));
        assert!(supplements[1].starts_with("broker-tool:record_note:sha256:"));
    }

