    #[test]
    fn broker_revocation_marks_in_flight_pending_and_never_waits_on_operation_lock() {
        let mut grant = synthetic_agent_broker_grant();
        grant.state = AgentBrokerGrantState::Claimed;
        grant.in_flight = Some(AgentBrokerInFlight {
            sequence: 1,
            tool: "submit_output".to_owned(),
            operation_key: "submit_output".to_owned(),
            request_hash: "sha256:request".to_owned(),
            write_intent: None,
            started_at: Utc::now(),
        });
        assert!(request_agent_broker_revocation(&mut grant));
        assert_eq!(grant.state, AgentBrokerGrantState::Claimed);
        assert!(grant.revoke_pending);
        assert!(grant.in_flight.is_some());

        let common = tempfile::TempDir::new().unwrap();
        let common = common.path().canonicalize().unwrap();
        let operation = acquire_agent_broker_operation_lock(&common, "grant-test").unwrap();
        let (sender, receiver) = std::sync::mpsc::channel();
        let thread_common = common.clone();
        let waiter = thread::spawn(move || {
            let lock = acquire_agent_broker_grant_lock(&thread_common, "grant-test").unwrap();
            sender.send(()).unwrap();
            drop(lock);
        });
        receiver
            .recv_timeout(std::time::Duration::from_secs(1))
            .expect("revocation grant phase must not wait for a long operation lock");
        drop(operation);
        waiter.join().unwrap();

        assert!(
            !clear_agent_broker_tool_reservation_state(
                &mut grant,
                "submit_output",
                "sha256:different-request",
            ),
            "a different failed action cannot clear the reserved operation"
        );
        assert!(clear_agent_broker_tool_reservation_state(
            &mut grant,
            "submit_output",
            "sha256:request",
        ));
        assert_eq!(grant.state, AgentBrokerGrantState::Revoked);
        assert!(!grant.revoke_pending);
        assert!(grant.in_flight.is_none());

        let mut revoked_before_reserve = synthetic_agent_broker_grant();
        revoked_before_reserve.state = AgentBrokerGrantState::Claimed;
        assert!(request_agent_broker_revocation(&mut revoked_before_reserve));
        assert_eq!(revoked_before_reserve.state, AgentBrokerGrantState::Revoked);
        assert!(
            claim_agent_broker_state(
                &mut revoked_before_reserve,
                &ProcessBirthIdentity {
                    pid: 43,
                    birth_marker: "late-claim".to_owned(),
                },
            )
            .is_err(),
            "pause/delete that wins first closes later claims"
        );

        let mut completed_before_delete = synthetic_agent_broker_grant();
        completed_before_delete.state = AgentBrokerGrantState::Consumed;
        assert!(!request_agent_broker_revocation(
            &mut completed_before_delete
        ));
        assert_eq!(
            completed_before_delete.state,
            AgentBrokerGrantState::Consumed
        );
    }

    #[test]
    fn superseded_terminal_lead_wait_recovery_requires_absent_response_and_dead_exact_owners() {
        let repository = tempfile::tempdir().unwrap();
        git2::Repository::init(repository.path()).unwrap();
        let root = repository.path().canonicalize().unwrap();
        let git = GitBackend::discover(&root).unwrap();
        let control = RunControlStore::new(root.join("control"));

        let boundary = LeadSliceBoundary::WaitWorkers {
            tickets: vec!["TK-wait".to_owned()],
        };
        let mut historical = bounded_test_lead_slice(boundary.clone());
        let runtime_identity = AgentProcessIdentity {
            pid: 900_001,
            process_group_id: 900_001,
            birth_marker: "dead-runtime-host".to_owned(),
        };
        historical.process_identity = Some(runtime_identity.clone());
        control.write_lead_slice(&historical).unwrap();

        let mut current = historical.clone();
        current.generation = 2;
        current.token_hash = normalized_hash(&"later-secret");
        current.status = LeadSliceStatus::Yielded;
        current.boundary = LeadSliceBoundary::Finish {
            ticket: "TK-wait".to_owned(),
        };
        current.boundaries_completed = 1;
        current.actions = vec!["finish:TK-wait".to_owned()];
        current.raw_agent_id = Some("worker-later".to_owned());
        current.process_identity = Some(AgentProcessIdentity {
            pid: 900_003,
            process_group_id: 900_003,
            birth_marker: "dead-later-host".to_owned(),
        });
        current.yield_reason = Some("boundary-complete".to_owned());
        control.write_lead_slice(&current).unwrap();

        let mut grant = synthetic_agent_broker_grant();
        grant.id = "grant-terminal-wait".to_owned();
        grant.repository_root = root.clone();
        grant.working_directory = root.clone();
        grant.agent_id = "worker-first".to_owned();
        grant.role = AgentBrokerRole::Lead {
            generation: historical.generation,
            boundary: boundary.clone(),
        };
        grant.context_policy = None;
        grant.enabled_tools = agent_mcp_enabled_tools(Some(&boundary));
        grant.enabled_tools_hash = normalized_hash(&grant.enabled_tools);
        grant.state = AgentBrokerGrantState::Claimed;
        grant.revoke_pending = true;
        grant.expected_codex_parent = Some(runtime_identity.clone());
        grant.claimed_broker = Some(ProcessBirthIdentity {
            pid: 900_002,
            birth_marker: "dead-broker".to_owned(),
        });
        grant.in_flight = Some(AgentBrokerInFlight {
            sequence: 1,
            tool: "wait_worker".to_owned(),
            operation_key: "wait-worker".to_owned(),
            request_hash: "sha256:terminal-wait".to_owned(),
            write_intent: None,
            started_at: Utc::now(),
        });

        let mut agent = bounded_test_raw_agent("failed", Some(1));
        agent.pid = Some(runtime_identity.pid);
        agent.process_identity = Some(runtime_identity);
        agent.working_directory = Some(root.clone());
        agent.result = Some(json!({
            "broker_grant_id": grant.id,
            "broker_tool_failure": {
                "code": "tool_effect_or_ingress_failed",
                "phase": "execute",
                "safe_code": "authority_busy_stop",
                "tool": "wait_worker"
            }
        }));
        control.write_agent(&agent).unwrap();
        write_agent_broker_grant(git.common_dir(), &mut grant).unwrap();

        let response_relative = agent_broker_response_relative_path(&grant.id, 1).unwrap();
        write_agent_broker_response(
            git.common_dir(),
            &grant.id,
            1,
            &serde_json::to_value(WorkerWaitOutcome {
                state: WorkerWaitState::Paused,
                ticket: None,
                next: WorkerNextBoundary::Stop,
                message: "paused".to_owned(),
            })
            .unwrap(),
        )
        .unwrap();
        assert!(
            reconcile_superseded_terminal_lead_wait_grants(&root, "run-test", &control)
                .unwrap()
                .is_empty(),
            "an uncommitted response is ambiguous and must remain quarantined"
        );
        let still_pending = read_agent_broker_grant(git.common_dir(), &grant.id).unwrap();
        assert_eq!(still_pending.state, AgentBrokerGrantState::Claimed);
        assert!(still_pending.revoke_pending);
        assert!(still_pending.in_flight.is_some());

        fs::remove_file(git.common_dir().join(response_relative)).unwrap();
        assert_eq!(
            reconcile_superseded_terminal_lead_wait_grants(&root, "run-test", &control).unwrap(),
            vec![grant.id.clone()]
        );
        let recovered = read_agent_broker_grant(git.common_dir(), &grant.id).unwrap();
        assert_eq!(recovered.state, AgentBrokerGrantState::Revoked);
        assert!(!recovered.revoke_pending);
        assert!(recovered.in_flight.is_none());
        assert!(recovered.tool_receipts.is_empty());
    }

    #[test]
    fn lead_slice_bearer_rejects_stale_forged_and_unowned_ingress() {
        let state = bounded_test_lead_slice(LeadSliceBoundary::Recover);
        let exact = LeadIngressCapability::LegacyToken {
            token: "secret".to_owned(),
            generation: 1,
        };
        let forged = LeadIngressCapability::LegacyToken {
            token: "forged".to_owned(),
            generation: 1,
        };
        let stale = LeadIngressCapability::LegacyToken {
            token: "secret".to_owned(),
            generation: 2,
        };
        assert!(validate_lead_slice_ingress(&state, &exact, true).is_ok());
        assert!(validate_lead_slice_ingress(&state, &forged, true).is_err());
        assert!(validate_lead_slice_ingress(&state, &stale, true).is_err());
        assert!(validate_lead_slice_ingress(&state, &exact, false).is_err());

        let broker = LeadIngressCapability::BrokerGrant {
            grant_id: "grant-test".to_owned(),
            agent_id: "worker-first".to_owned(),
            generation: 1,
        };
        assert!(validate_lead_slice_ingress(&state, &broker, true).is_ok());
        assert!(
            validate_lead_slice_ingress(&state, &broker, false).is_ok(),
            "the validated direct Pi broker is the model host's parent"
        );

        let mut yielded = state;
        yielded.status = LeadSliceStatus::Yielded;
        assert!(validate_lead_slice_ingress(&yielded, &exact, true).is_err());
    }

    #[test]
    fn dispatch_slice_enforces_one_complete_capacity_sized_boundary() {
        let mut state = bounded_test_lead_slice(LeadSliceBoundary::DispatchBatch {
            tickets: vec!["TK-a".to_owned(), "TK-b".to_owned()],
        });
        assert!(authorize_lead_slice_operation(&mut state, "start", Some("TK-b")).is_err());
        assert!(authorize_lead_slice_operation(&mut state, "spawn-worker", Some("TK-a")).is_err());
        authorize_lead_slice_operation(&mut state, "start", Some("TK-a")).unwrap();
        assert!(authorize_lead_slice_operation(&mut state, "start", Some("TK-b")).is_err());
        authorize_lead_slice_operation(&mut state, "spawn-worker", Some("TK-a")).unwrap();
        assert_eq!(state.boundaries_completed, 0);
        authorize_lead_slice_operation(&mut state, "start", Some("TK-b")).unwrap();
        authorize_lead_slice_operation(&mut state, "spawn-worker", Some("TK-b")).unwrap();
        assert_eq!(state.boundaries_completed, 1);
        assert!(authorize_lead_slice_operation(&mut state, "recover", None).is_err());
        assert!(authorize_lead_slice_operation(&mut state, "spawn-worker", Some("TK-c")).is_err());
    }

    #[test]
    fn dispatch_slice_can_yield_only_when_live_capacity_invalidates_its_remainder() {
        let mut state = bounded_test_lead_slice(LeadSliceBoundary::DispatchBatch {
            tickets: vec!["TK-a".to_owned(), "TK-b".to_owned()],
        });
        let mut orchestration = OrchestrationState::new(true, 1).unwrap();

        assert!(!lead_dispatch_capacity_reached(&state, &orchestration, 0));
        assert!(lead_dispatch_capacity_reached(&state, &orchestration, 1));
        assert!(validate_lead_yield_reason(&state, "capacity-reached", true, false, true).is_ok());
        assert!(
            validate_lead_yield_reason(&state, "capacity-reached", true, false, false).is_err()
        );

        authorize_lead_slice_operation(&mut state, "start", Some("TK-a")).unwrap();
        authorize_lead_slice_operation(&mut state, "spawn-worker", Some("TK-a")).unwrap();
        assert!(lead_dispatch_capacity_reached(&state, &orchestration, 1));

        authorize_lead_slice_operation(&mut state, "start", Some("TK-b")).unwrap();
        authorize_lead_slice_operation(&mut state, "spawn-worker", Some("TK-b")).unwrap();
        assert!(!lead_dispatch_capacity_reached(&state, &orchestration, 2));

        let pending = bounded_test_lead_slice(LeadSliceBoundary::DispatchBatch {
            tickets: vec!["TK-a".to_owned()],
        });
        orchestration.unchained = true;
        assert!(!lead_dispatch_capacity_reached(&pending, &orchestration, 1));
        orchestration.unchained = false;
        orchestration.running = false;
        assert!(!lead_dispatch_capacity_reached(&pending, &orchestration, 1));
    }

