    fn worker_projection_ticket(with_output: bool) -> Ticket {
        let outputs = if with_output {
            json!([{
                "id": "output-1",
                "step_id": "produce",
                "persona": "worker",
                "context_hash": "ctx-produce",
                "recorded_at": "2026-07-10T12:01:00Z"
            }])
        } else {
            json!([])
        };
        serde_json::from_value(json!({
            "schema_version": "1.0",
            "id": "TK-test",
            "operation": "test",
            "status": "in_progress",
            "title": "test ticket",
            "source_state_key": "before",
            "target_state_key": "after",
            "profile_hash": "sha256:test",
            "rule_id": "test.rule",
            "workflow": [
                {
                    "id": "produce",
                    "persona": "worker",
                    "context_hash": "ctx-produce"
                },
                {
                    "id": "integrate",
                    "persona": "integrator",
                    "depends_on": ["produce"],
                    "kind": "integration",
                    "context_hash": "ctx-integrate"
                }
            ],
            "outputs": outputs,
            "lease": {
                "id": "lease-1",
                "branch": "koni/ticket/TK-test",
                "worktree": "/tmp/nonexistent-ticket-worktree",
                "base_commit": "0000000000000000000000000000000000000000",
                "started_at": "2026-07-10T12:00:00Z",
                "heartbeat_at": "2026-07-10T12:00:00Z",
                "worker_pid": 999999
            },
            "extensions": {
                "active_worker": {
                    "persona": "worker",
                    "pid": 999999,
                    "step": "produce"
                }
            }
        }))
        .expect("test ticket deserializes")
    }

    #[test]
    fn replacement_context_observes_only_pre_output_in_scope_sidecar_edits() {
        let mut engine = Engine {
            root: PathBuf::from("/tmp/koni-context-recovery-test"),
            profile: compiled_software_profile(),
            store: None,
            run_git_templates: None,
            run_slug: None,
            resolved_run_type: None,
            compiler_action_context: BTreeMap::new(),
            ticket_review_authorization: None,
        };
        assert_eq!(
            engine.profile.manifest.storage.backend,
            StorageBackend::GitCommonDir
        );
        let context = engine.profile.actions["context"].clone();
        let params = BTreeMap::from([
            ("ticket".to_owned(), Value::String("TK-test".to_owned())),
            ("step".to_owned(), Value::String("produce".to_owned())),
        ]);
        let mut ticket = worker_projection_ticket(false);
        ticket.workflow[0].write_paths = Some(BTreeSet::from(["src".to_owned()]));
        let in_scope = vec![WorktreeChange {
            path: PathBuf::from("src/preserved.rs"),
            status_bits: 0,
        }];

        assert!(engine.context_reissuance_observes_recoverable_step_changes(
            &context, &params, &ticket, &in_scope,
        ));

        let out_of_scope = vec![WorktreeChange {
            path: PathBuf::from("tests/outside.rs"),
            status_bits: 0,
        }];
        assert!(
            !engine.context_reissuance_observes_recoverable_step_changes(
                &context,
                &params,
                &ticket,
                &out_of_scope,
            )
        );

        ticket.outputs = worker_projection_ticket(true).outputs;
        assert!(
            !engine.context_reissuance_observes_recoverable_step_changes(
                &context, &params, &ticket, &in_scope,
            )
        );

        ticket.outputs.clear();
        engine.profile.manifest.storage.backend = StorageBackend::Tracked;
        assert!(
            !engine.context_reissuance_observes_recoverable_step_changes(
                &context, &params, &ticket, &in_scope,
            )
        );
    }

    fn dead_worker_agent(id: &str) -> AgentSessionRecord {
        serde_json::from_value(json!({
            "schema_version": "1.0",
            "id": id,
            "run_id": "run-test",
            "ticket_id": "TK-test",
            "stage_id": "produce",
            "persona": "worker",
            "status": "running",
            "attempt": 1,
            "pid": 999999,
            "process_identity": {
                "pid": 999999,
                "process_group_id": 999999,
                "birth_marker": "Thu Jul 10 12:00:00 2026"
            },
            "started_at": "2026-07-10T12:00:30Z",
            "updated_at": "2026-07-10T12:00:30Z"
        }))
        .expect("worker agent deserializes")
    }

    fn circuit_worker_session(
        id: &str,
        ticket_id: &str,
        step_id: &str,
        started_at: &str,
        finished_at: &str,
    ) -> AgentSessionRecord {
        let pid = 800_000
            + id.bytes()
                .fold(0_u32, |sum, byte| sum.saturating_add(u32::from(byte)));
        serde_json::from_value(json!({
            "schema_version": "1.0",
            "id": id,
            "run_id": "run-test",
            "ticket_id": ticket_id,
            "stage_id": step_id,
            "persona": "worker",
            "status": "completed",
            "attempt": 1,
            "pid": pid,
            "process_identity": {
                "pid": pid,
                "process_group_id": pid,
                "birth_marker": format!("birth-{id}")
            },
            "exit_code": 0,
            "started_at": started_at,
            "finished_at": finished_at,
            "updated_at": finished_at
        }))
        .expect("circuit worker session deserializes")
    }

    #[test]
    fn prior_attempt_feedback_is_compiler_owned_sanitized_and_output_reset() {
        let mut ticket = worker_projection_ticket(false);
        let step = ticket.workflow[0].clone();
        let mut first = circuit_worker_session(
            "private-agent-one",
            &ticket.id,
            &step.id,
            "2026-07-10T12:00:00Z",
            "2026-07-10T12:01:00Z",
        );
        first.status = "failed".to_owned();
        first.result = Some(json!({
            "supervision_error": "provider failure at /secret/PRIVATE_SENTINEL"
        }));
        let mut second = circuit_worker_session(
            "private-agent-two",
            &ticket.id,
            &step.id,
            "2026-07-10T12:02:00Z",
            "2026-07-10T12:03:00Z",
        );
        second.status = "failed".to_owned();
        second.result = Some(json!({
            "supervision_error": "direct Pi agent stopped without one compiler-committed terminal tool boundary at /secret/PRIVATE_SENTINEL"
        }));

        let feedback = prior_worker_attempt_feedback(
            "run-test",
            &ticket,
            &step,
            &[first.clone(), second.clone()],
        )
        .expect("finished attempts without output should produce bounded recovery guidance");
        assert_eq!(feedback["authority"], "compiler_owned_recovery_context");
        assert_eq!(feedback["code"], "terminal_boundary_missing");
        assert_eq!(feedback["consecutive_attempts_without_output"], 2);
        let rendered = serde_json::to_string(&feedback).unwrap();
        assert!(!rendered.contains("private-agent"));
        assert!(!rendered.contains("PRIVATE_SENTINEL"));
        assert!(!rendered.contains("/secret"));

        let mut timeout = second.clone();
        timeout.id = "private-timeout".to_owned();
        timeout.timed_out = true;
        assert_eq!(
            prior_worker_attempt_feedback("run-test", &ticket, &step, &[timeout]).unwrap()["code"],
            "timeout"
        );

        ticket.extensions.insert(
            "superseded_outputs".to_owned(),
            json!([{
                "id": "successful-output",
                "step_id": step.id,
                "persona": step.persona,
                "context_hash": "ctx-produce",
                "recorded_at": "2026-07-10T12:04:00Z"
            }]),
        );
        assert!(
            prior_worker_attempt_feedback("run-test", &ticket, &step, &[first, second]).is_none(),
            "a newer compiler-owned output resets the recovery window"
        );
    }

    #[test]
    fn worker_no_output_circuit_blocks_after_two_identity_bound_failures() {
        let profile = compiled_updog_profile();
        let mut ticket = worker_projection_ticket(false);
        ticket.lease.as_mut().unwrap().worker_pid = None;
        ticket.extensions.remove("active_worker");
        let agents = vec![
            circuit_worker_session(
                "worker-failure-1",
                &ticket.id,
                "produce",
                "2026-07-10T12:00:00Z",
                "2026-07-10T12:01:00Z",
            ),
            circuit_worker_session(
                "worker-failure-2",
                &ticket.id,
                "produce",
                "2026-07-10T12:02:00Z",
                "2026-07-10T12:03:00Z",
            ),
        ];

        let evidence = worker_no_output_circuit_evidence("run-test", &ticket, "produce", &agents)
            .expect("the third dispatch must be stopped");
        assert_eq!(
            evidence.session_ids,
            vec!["worker-failure-1", "worker-failure-2"]
        );
        assert!(
            apply_worker_no_output_circuit_breaker(&profile, &mut ticket, "produce", &evidence,)
                .unwrap()
        );
        assert_eq!(ticket.status, "blocked");
        assert!(
            ticket
                .blockers
                .iter()
                .any(|blocker| blocker.kind == WORKER_NO_OUTPUT_BLOCKER_KIND)
        );
        assert_eq!(
            ticket.extensions[WORKER_NO_OUTPUT_EXTENSION]["consecutive_no_output_sessions"],
            2
        );
    }

    #[test]
    fn explicit_recovery_reopens_worker_circuit_from_a_fresh_failure_window() {
        let profile = compiled_software_profile();
        let mut ticket = worker_projection_ticket(false);
        ticket.lease.as_mut().unwrap().worker_pid = None;
        ticket.extensions.remove("active_worker");
        let prior_sessions = vec![
            circuit_worker_session(
                "worker-prior-1",
                &ticket.id,
                "produce",
                "2026-07-10T12:00:00Z",
                "2026-07-10T12:01:00Z",
            ),
            circuit_worker_session(
                "worker-prior-2",
                &ticket.id,
                "produce",
                "2026-07-10T12:02:00Z",
                "2026-07-10T12:03:00Z",
            ),
        ];
        let evidence =
            worker_no_output_circuit_evidence("run-test", &ticket, "produce", &prior_sessions)
                .expect("the prior pair opens the circuit");
        apply_worker_no_output_circuit_breaker(&profile, &mut ticket, "produce", &evidence)
            .unwrap();

        let temp = tempfile::tempdir().unwrap();
        ensure_repository_with_head(temp.path()).unwrap();
        let repository = git2::Repository::open(temp.path()).unwrap();
        let index = repository.index().unwrap();
        assert!(reconcile_recoverable_ticket_blockers(
            &profile,
            &mut ticket,
            None,
            &index,
            &[],
        ));
        assert_eq!(ticket.status, "in_progress");
        assert!(ticket.blockers.is_empty());
        assert_eq!(
            ticket.extensions[WORKER_NO_OUTPUT_EXTENSION]["status"],
            "explicitly_recovered"
        );
        assert!(ticket.extensions[WORKER_NO_OUTPUT_EXTENSION]["dispositioned_at"].is_string());
        assert!(
            worker_no_output_circuit_evidence("run-test", &ticket, "produce", &prior_sessions)
                .is_none(),
            "pre-recovery sessions must not immediately reopen the circuit"
        );
    }

