    #[cfg(unix)]
    #[test]
    fn ticket_worker_liveness_requires_the_persisted_process_birth_identity() {
        let mut command = Command::new("sh");
        command.args(["-c", "sleep 30"]);
        isolate_agent_process_group(&mut command);
        let mut process = SpawnedAgentProcess::new(command.spawn().unwrap()).unwrap();
        let identity = process.identity.clone();
        let mut ticket = worker_projection_ticket(false);
        ticket.lease.as_mut().unwrap().worker_pid = Some(identity.pid);
        ticket.extensions.insert(
            "active_worker".to_owned(),
            json!({"pid": identity.pid, "persona": "worker", "step": "produce"}),
        );
        assert!(
            !ticket_worker_is_alive(&ticket),
            "a bare live PID is not durable ownership"
        );

        ticket.extensions.get_mut("active_worker").unwrap()["process_identity"] =
            serde_json::to_value(&identity).unwrap();
        assert!(ticket_worker_is_alive(&ticket));

        ticket.extensions.get_mut("active_worker").unwrap()["process_identity"]["birth_marker"] =
            Value::String("kernel-start-v2:macos:1:1".to_owned());
        assert!(
            !ticket_worker_is_alive(&ticket),
            "a recycled PID must not be reported as the owned worker"
        );
        let recycled: AgentProcessIdentity =
            serde_json::from_value(ticket.extensions["active_worker"]["process_identity"].clone())
                .unwrap();
        assert!(
            terminate_owned_agent_process(
                &recycled,
                std::time::Duration::from_millis(10),
                std::time::Duration::from_millis(10),
            )
            .is_err(),
            "stop must refuse to signal a PID with a mismatched birth marker"
        );
        assert!(process_group_is_alive(identity.process_group_id));

        let mut legacy = identity.clone();
        legacy.birth_marker = "ps-lstart-utc-v1:Thu Jul 16 12:30:00 2026".to_owned();
        let error = terminate_owned_agent_process(
            &legacy,
            std::time::Duration::from_millis(10),
            std::time::Duration::from_millis(10),
        )
        .expect_err("legacy identity must never authorize group signaling");
        assert!(error.to_string().contains("legacy or weak birth marker"));
        assert!(process_group_is_alive(identity.process_group_id));
        process.terminate_and_wait().unwrap();
    }

    #[test]
    fn successful_reaper_cleanup_clears_only_the_identity_bound_worker() {
        let identity = AgentProcessIdentity {
            pid: 4242,
            process_group_id: 4242,
            birth_marker: "Mon Jul 13 03:00:00 2026".to_owned(),
        };
        let mut ticket = worker_projection_ticket(false);
        ticket.lease.as_mut().unwrap().worker_pid = Some(identity.pid);
        ticket.extensions.insert(
            "active_worker".to_owned(),
            json!({
                "pid": identity.pid,
                "persona": "worker",
                "step": "produce",
                "process_identity": identity,
            }),
        );

        assert!(clear_reaped_ticket_worker(&mut ticket, &identity).unwrap());
        assert_eq!(ticket.lease.as_ref().unwrap().worker_pid, None);
        assert!(!ticket.extensions.contains_key("active_worker"));

        let mut mismatched = worker_projection_ticket(false);
        mismatched.lease.as_mut().unwrap().worker_pid = Some(identity.pid);
        mismatched.extensions.insert(
            "active_worker".to_owned(),
            json!({
                "pid": identity.pid,
                "persona": "worker",
                "step": "produce",
                "process_identity": {
                    "pid": identity.pid,
                    "process_group_id": identity.process_group_id,
                    "birth_marker": "recycled process",
                },
            }),
        );
        assert!(clear_reaped_ticket_worker(&mut mismatched, &identity).is_err());
        assert_eq!(
            mismatched.lease.as_ref().unwrap().worker_pid,
            Some(identity.pid)
        );
        assert!(mismatched.extensions.contains_key("active_worker"));
    }

