    #[test]
    fn direct_pi_exit_waits_for_action_authority_then_corrects_provisional_recovery() {
        let fixture = direct_pi_exit_fixture(RunRegistrationStatus::Active);
        let authority = acquire_run_authority_barrier_at_with_timeout(
            &fixture.spec.sidecar_root,
            &fixture.spec.run_id,
            RUN_AUTHORITY_CONTROL_TIMEOUT,
        )
        .unwrap();
        let spec = fixture.spec.clone();
        let identity = fixture.identity.clone();
        let pid_path = fixture.pid_path.clone();
        let (started_tx, started_rx) = std::sync::mpsc::channel();
        let (published_tx, published_rx) = std::sync::mpsc::channel();
        let waiter = thread::spawn(move || {
            started_tx
                .send(())
                .expect("announce direct Pi waiter before authority acquisition");
            published_tx
                .send(reconcile_direct_pi_agent_exit(
                    &spec,
                    &identity,
                    &pid_path,
                    Ok(successful_direct_pi_turn()),
                ))
                .unwrap();
        });

        started_rx
            .recv_timeout(std::time::Duration::from_secs(2))
            .expect("direct Pi waiter starts while compiler authority is held");
        thread::sleep(std::time::Duration::from_millis(75));
        assert!(matches!(
            published_rx.try_recv(),
            Err(std::sync::mpsc::TryRecvError::Empty)
        ));
        assert_eq!(
            fixture
                .spec
                .control
                .agent(&fixture.spec.agent_id)
                .unwrap()
                .unwrap()
                .status,
            "exited_without_receipt",
            "the waiter cannot publish while compiler authority is held"
        );

        drop(authority);
        assert!(
            published_rx
                .recv_timeout(std::time::Duration::from_secs(2))
                .expect("direct Pi exit waiter finishes after authority releases")
        );
        waiter.join().unwrap();
        let corrected = fixture
            .spec
            .control
            .agent(&fixture.spec.agent_id)
            .unwrap()
            .unwrap();
        assert_eq!(corrected.status, "completed");
        assert_eq!(corrected.exit_code, Some(0));
        assert_eq!(
            corrected.result.as_ref().unwrap()["preserved"],
            "unrelated-result"
        );
        assert_eq!(
            corrected.result.as_ref().unwrap()["compiler_owned_recovery"]["status"],
            "exited_without_receipt"
        );
        assert_eq!(
            corrected.result.as_ref().unwrap()["turn"]["turn_id"],
            "turn-direct-pi-exit"
        );
        assert!(!fixture.pid_path.exists());
    }

    #[test]
    fn direct_pi_exit_refuses_deleted_unregistered_concluded_or_missing_control_state() {
        for disposition in ["tombstoned", "unregistered", "concluded"] {
            let fixture = direct_pi_exit_fixture(RunRegistrationStatus::Active);
            match disposition {
                "tombstoned" => {
                    let tombstone = fixture
                        .spec
                        .sidecar_root
                        .join("deletions")
                        .join(format!("{}.yaml", fixture.spec.run_id));
                    fs::create_dir_all(tombstone.parent().unwrap()).unwrap();
                    fs::write(tombstone, "schema_version: '1.0'\n").unwrap();
                }
                "unregistered" => {
                    fixture
                        .registry
                        .unregister_run(&fixture.spec.run_id)
                        .unwrap();
                }
                "concluded" => {
                    let mut registration = fixture.registry.run(&fixture.spec.run_id).unwrap();
                    registration.status = RunRegistrationStatus::Concluded;
                    registration.updated_at = Utc::now();
                    fixture.registry.update_run(registration).unwrap();
                }
                _ => unreachable!(),
            }
            let before = serde_json::to_value(
                fixture
                    .spec
                    .control
                    .agent(&fixture.spec.agent_id)
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            assert!(
                !reconcile_direct_pi_agent_exit(
                    &fixture.spec,
                    &fixture.identity,
                    &fixture.pid_path,
                    Ok(successful_direct_pi_turn()),
                ),
                "{disposition} state must refuse process-exit publication"
            );
            let after = serde_json::to_value(
                fixture
                    .spec
                    .control
                    .agent(&fixture.spec.agent_id)
                    .unwrap()
                    .unwrap(),
            )
            .unwrap();
            assert_eq!(after, before, "{disposition} state changed the raw agent");
            assert_eq!(
                read_worker_pid(&fixture.pid_path).unwrap(),
                Some(fixture.identity.pid),
                "{disposition} state must not perform post-publication cleanup"
            );
        }

        let fixture = direct_pi_exit_fixture(RunRegistrationStatus::Active);
        let control_root = fixture.spec.control.root().to_path_buf();
        fs::remove_dir_all(&control_root).unwrap();
        assert!(!reconcile_direct_pi_agent_exit(
            &fixture.spec,
            &fixture.identity,
            &fixture.pid_path,
            Ok(successful_direct_pi_turn()),
        ));
        assert!(
            !control_root.exists(),
            "an exit waiter must never recreate a missing control namespace"
        );
    }

    #[test]
    fn direct_pi_exit_receipts_remain_valid_during_pause_and_open_question() {
        let paused = direct_pi_exit_fixture(RunRegistrationStatus::Paused);
        paused
            .spec
            .control
            .write_orchestration(&OrchestrationState::new(false, 1).unwrap())
            .unwrap();
        assert!(reconcile_direct_pi_agent_exit(
            &paused.spec,
            &paused.identity,
            &paused.pid_path,
            Err(KoniError::Process(
                "exact paused runtime failure".to_owned()
            )),
        ));
        let paused_record = paused
            .spec
            .control
            .agent(&paused.spec.agent_id)
            .unwrap()
            .unwrap();
        assert_eq!(paused_record.status, "failed");
        assert_eq!(
            paused_record.result.as_ref().unwrap()["preserved"],
            "unrelated-result"
        );
        assert_eq!(
            paused_record.result.as_ref().unwrap()["compiler_owned_recovery"]["status"],
            "exited_without_receipt"
        );
        assert!(
            paused_record.result.as_ref().unwrap()["supervision_error"]
                .as_str()
                .unwrap()
                .contains("exact paused runtime failure")
        );

        let questioned = direct_pi_exit_fixture(RunRegistrationStatus::Active);
        let question = QuestionRecord::new(
            "direct-pi-exit-question",
            "Keep waiting?",
            "An open question pauses new work without revoking the existing process receipt.",
            vec![
                QuestionOption {
                    id: "yes".to_owned(),
                    label: "Yes".to_owned(),
                    description: "Keep the run paused.".to_owned(),
                    recommended: true,
                },
                QuestionOption {
                    id: "no".to_owned(),
                    label: "No".to_owned(),
                    description: "Resume after answering.".to_owned(),
                    recommended: false,
                },
            ],
            true,
            QuestionPauseScope::Run {
                run_id: questioned.spec.run_id.clone(),
            },
            CatalogQuestionPolicy::Interactive,
            QuestionImpact::Routine,
            None,
            QuestionSessionResume {
                session_id: "direct-pi-exit-session".to_owned(),
                agent_id: Some(questioned.spec.agent_id.clone()),
                turn_id: Some("direct-pi-exit-turn".to_owned()),
                working_directory: Some(questioned.spec.worktree.clone()),
                context_hash: normalized_hash(&"direct-pi-exit-question-context"),
                captured_at: Utc::now(),
            },
            Utc::now(),
        )
        .unwrap();
        questioned.spec.control.write_question(&question).unwrap();
        assert_eq!(questioned.spec.control.open_questions().unwrap().len(), 1);
        assert!(reconcile_direct_pi_agent_exit(
            &questioned.spec,
            &questioned.identity,
            &questioned.pid_path,
            Err(KoniError::Process(
                "exact questioned runtime failure".to_owned()
            )),
        ));
        let questioned_record = questioned
            .spec
            .control
            .agent(&questioned.spec.agent_id)
            .unwrap()
            .unwrap();
        assert_eq!(questioned_record.status, "failed");
        assert_eq!(
            questioned_record.result.as_ref().unwrap()["compiler_owned_recovery"]["status"],
            "exited_without_receipt"
        );
        assert_eq!(
            questioned_record.result.as_ref().unwrap()["preserved"],
            "unrelated-result"
        );
    }

    #[test]
    fn exact_live_history_classifier_rejects_every_known_transition() {
        for status in [
            "starting",
            "reaping",
            "active",
            "waiting",
            "boundary_committed",
            "compiling",
            "compiled",
            "between_slices",
            "output_recorded",
            "review_ready",
            "recovery_required",
        ] {
            let record = bounded_test_raw_agent(status, None);
            assert!(
                !exact_live_terminal_agent_history(&record),
                "{status} is unfinished compiler state, not history"
            );
        }
        for status in [
            "completed",
            "failed",
            "supervision_failed",
            "exited_without_receipt",
            "succeeded",
            "changes_requested",
        ] {
            let record = bounded_test_raw_agent(status, Some(1));
            assert!(
                exact_live_terminal_agent_history(&record),
                "{status} should remain readable terminal history"
            );
        }
    }

